-- UPDATE preguntas.explicacion (generadas via Groq)
-- Fuente: ingesta/explicaciones_generadas.json (1025 registros)

BEGIN;

DO $$
DECLARE
  total_antes int;
  sin_explicacion_antes int;
BEGIN
  SELECT COUNT(*) INTO total_antes FROM public.preguntas;
  SELECT COUNT(*) INTO sin_explicacion_antes
    FROM public.preguntas WHERE explicacion IS NULL OR explicacion = '';
  IF total_antes != 1025 THEN
    RAISE EXCEPTION 'Se esperaban 1025 preguntas en total, hay % -- abortando.', total_antes;
  END IF;
  IF sin_explicacion_antes != 1025 THEN
    RAISE EXCEPTION 'Se esperaban 1025 preguntas sin explicacion (segun el JSON), hay % -- abortando para no pisar filas con otro motivo.', sin_explicacion_antes;
  END IF;
END $$;

UPDATE public.preguntas AS p
SET explicacion = v.explicacion
FROM (VALUES
  (1, 'Ewald Hering propuso que la percepción cromática se basa en tres pares de procesos oponentes que operan sobre la información visual: blanco‑negro, rojo‑verde y amarillo‑azul; cada par representa la oposición entre dos colores que no pueden coexistir en la misma percepción, reflejando la actividad de fotoreceptores y vías neuronales que codifican la información de contraste cromático, lo que explica fenómenos como la persistencia de la visión y la ilusión de colores complementarios. Las demás opciones son incorrectas: la alternativa A menciona mecanismos de brillo, contraste e intensidad, que corresponden a la teoría de la luminancia y no a la teoría de los procesos oponentes; la alternativa B se refiere a parámetros físicos de la luz (longitud y amplitud de onda), que describen la espectroscopía pero no la organización neuronal de la percepción cromática; y la alternativa C habla de sinapsis excitatorias, inhibitorias y oponentes, un concepto que mezcla procesos neurofisiológicos con la teoría de Hering, pero no refleja la clasificación específica de los pares de colores que él propuso.'),
  (2, 'El problema de la Torre de Hanoi se plantea con tres pivotes y una serie de discos de distintos tamaños, todos colocados en el pivote inicial en orden descendente; la tarea es trasladar la pila completa al pivote final respetando la regla de que nunca puede colocarse un disco mayor sobre uno menor, lo que obliga a la planificación secuencial y la memoria de trabajo para prever los movimientos intermedios; la opción C resume precisamente esta configuración y restricción, mientras que las demás alternativas confunden la naturaleza de los discos (mismo tamaño en A y D, o requerimiento de torres con discos idénticos en B) o alteran la condición de apilamiento (torres de igual altura en A, torres de distinta altura en D), por lo que no describen el problema original.'),
  (3, 'El modelo triangular de Sternberg (1988) conceptualiza el amor como la interacción de tres componentes interdependientes: intimidad, pasión y compromiso; por lo tanto la opción D reúne los tres elementos que constituyen la estructura teórica del amor según este modelo, diferenciándose de las demás alternativas que sustituyen o añaden conceptos que no forman parte de la teoría original (sexualidad, apego, fidelidad, etc.). Las opciones A y C introducen “sexualidad” y “apego”, conceptos que no aparecen en la propuesta de Sternberg y que confunden la distinción entre componentes cognitivos y afectivos; la opción B sustituye “intimidad” por “apego”, alterando la dimensión emocional del modelo, y por tanto no corresponde a la formulación establecida.'),
  (4, 'En un esquema de reforzamiento positivo de intervalo fijo de cuatro minutos, el reforzador se dispensa únicamente cuando la respuesta operante se produce después de que haya transcurrido el intervalo de cuatro minutos desde la última entrega; es decir, la respuesta debe ocurrir dentro del periodo de disponibilidad que comienza justo al finalizar los cuatro minutos, y el reforzador se entrega inmediatamente en ese momento, independientemente de cuántas veces el sujeto haya emitido la respuesta antes de que expire el intervalo. La opción A describe precisamente este procedimiento: la respuesta operante se emite después de cuatro minutos y el reforzador se entrega en ese instante. La opción B es incorrecta porque en un intervalo fijo el reforzador no se entrega a intervalos fijos independientemente de la respuesta; el reforzador solo se entrega cuando la respuesta ocurre después del intervalo. La opción C confunde la disponibilidad del reforzador con la entrega; en un intervalo fijo el reforzador no se entrega cuatro minutos después de que esté disponible, sino cuando la respuesta ocurre tras el intervalo. La opción D es errónea porque el estímulo discriminativo no determina la entrega en un intervalo fijo; la entrega depende únicamente del tiempo transcurrido y de la respuesta operante, no de la presentación del estímulo discriminativo.'),
  (5, 'El fenómeno del olvido inducido por la recuperación se refiere a la pérdida de información que ocurre cuando la recuperación de un recuerdo facilita la exclusión o la interferencia de otros recuerdos vinculados a la misma clave, de modo que la evocación de un episodio concreto provoca la supresión de datos relacionados que comparten la misma asociación semántica o contextual, lo que explica la opción A; las demás alternativas son erróneas porque la opción B describe un proceso de “desintegración” que no está respaldado por la teoría de la memoria, la opción C confunde el efecto de la dificultad de recuperación con la interferencia retroactiva, y la opción D invierte la dirección temporal del olvido, lo que no corresponde al mecanismo de olvido inducido por la recuperación.'),
  (6, 'La devaluación del reforzador consiste en asociar el estímulo reforzador con un evento o estímulo de naturaleza contraria, de modo que la respuesta operante deja de producir la satisfacción esperada y su frecuencia disminuye; este procedimiento se basa en la teoría de la contingencia de la expectativa, donde la expectativa de un resultado positivo se altera mediante la introducción de un estímulo aversivo o neutral que cambia la valoración del reforzador, reduciendo así la motivación para la conducta. Las opciones A y B describen manipulaciones de la magnitud o la exigencia de la respuesta, que corresponden a procedimientos de magnitud de reforzador o de ratio, no a la devaluación propiamente dicha. La opción C se refiere a la manipulación de la demora temporal, un factor que afecta la eficacia del reforzador pero que no implica la asociación con un estímulo contrario, por lo que no constituye un proceso de devaluación.'),
  (7, 'La falacia del jugador se origina en la aplicación indebida del heurístico de representatividad, que lleva al jugador a inferir que una secuencia de resultados “representa” la tendencia global del azar y, por tanto, que los eventos futuros deben corregir la desviación percibida, como si el sistema tuviera una tendencia a equilibrarse; este razonamiento ignora la independencia de los eventos y la verdadera interpretación de la ley de los grandes números, que solo se aplica a largo plazo y no a la sucesión inmediata de resultados. Las alternativas A y D se refieren a heurísticos que operan sobre la disponibilidad de información y la categorización por prototipos, respectivamente, y no explican la tendencia a suponer una corrección automática del azar; la opción B, el heurístico de anclaje y ajuste, implicaría un ajuste sistemático a partir de un punto de referencia inicial, lo cual tampoco describe la creencia de que el azar se autoajusta tras una serie de pérdidas o ganancias.'),
  (8, 'El diencéfalo se compone de las estructuras tálamo, hipotálamo, epitálamo y subtálamo, que forman el núcleo central de la corteza cerebral y regulan funciones autonómicas, endocrinas y sensoriales; esta descripción coincide con la opción C, pues identifica correctamente los componentes anatómicos y su organización funcional, mientras que la opción A confunde el diencéfalo con el núcleo periacueductal, que es parte del tronco encefálico; la B describe los colículos, que pertenecen al mesencéfalo, no al diencéfalo; y la D atribuye al diencéfalo una función exclusiva de control respiratorio y cardiovascular, función que corresponde principalmente al bulbo raquídeo y la médula oblongata, dejando al diencéfalo como modulador de procesos más amplios.'),
  (9, 'La resonancia magnética funcional (RMf) presenta la peor resolución temporal entre las técnicas citadas porque la señal BOLD que detecta depende de la respuesta hemodinámica al flujo sanguíneo cerebral, la cual se desarrolla con un retraso de varios segundos (alrededor de 4–6 s) y se mantiene durante 10–12 s, limitando la capacidad de distinguir eventos de corta duración; en contraste, la electroencefalografía (EEG) y la magnetoencefalografía (MEG) registran directamente la actividad eléctrica y magnética neuronal con una resolución en el orden de milisegundos, mientras que los registros intracraneales (iEEG) también capturan señales eléctricas con una temporalidad comparable a la EEG, aunque con mayor localización espacial. Por tanto, la opción D es la que presenta la menor resolución temporal. Las demás alternativas (A, B y C) comparten la característica de registrar la actividad neuronal de forma directa y con una latencia en milisegundos, razón por la cual no cumplen el criterio de peor resolución temporal.'),
  (10, 'El cromosoma 21 contiene el gen APP, cuya sobreexpresión se ha relacionado con la acumulación de placas amiloides en el cerebro, mecanismo central en la patología de la enfermedad de Alzheimer; por ello, la presencia de una copia extra de este cromosoma en el síndrome de Down aumenta el riesgo de desarrollar Alzheimer en edad temprana, lo que explica la asociación citada. Las demás opciones son incorrectas: el Parkinson no está vinculado a genes localizados en el cromosoma 21, sino a mutaciones en genes como SNCA o LRRK2; la enfermedad de Huntington se origina por una expansión de CAG en el gen HTT del cromosoma 4; y el síndrome de Tourette se asocia a alteraciones en el circuito cortico‑basal ganglionar, sin implicación directa de genes del cromosoma 21.'),
  (11, 'El núcleo geniculado lateral del tálamo es el relé principal de la vía visual, recibiendo información de la retina a través del tracto óptico y proyectando al córtex visual primario; por tanto la modalidad sensorial que procesa es la visual, lo que explica la opción B. Las demás alternativas son incorrectas porque el núcleo geniculado medial (A) se ocupa de la información auditiva, el núcleo geniculado posterior (C) procesa la información táctil y la nociceptiva, y la gustación se transmite al núcleo geniculado medial del tálamo, no al lateral.'),
  (12, 'En la unión neuromuscular, la acetilcolina es el neurotransmisor que se libera desde la terminal motora del nervio somático y actúa sobre los receptores nicotínicos de la membrana postsináptica del músculo esquelético, generando la despolarización necesaria para la contracción; su papel es esencial y exclusivo en esta sinapsis, ya que los demás neurotransmisores citados no participan en la transmisión motora a nivel de la fibra muscular. Las opciones A y D, dopamina y noradrenalina, están implicadas en la regulación de la motivación, el estado de ánimo y la respuesta autonómica, pero no en la transmisión motora esquelética; la opción B, serotonina, modula funciones sensoriales y emocionales, pero tampoco actúa como mensajero en la unión neuromuscular.'),
  (13, 'La inhibición de la conducta motora se regula principalmente a través del circuito cortico‑basal‑ganglionar que incluye la área premotora suplementaria, el núcleo subtalámico y el globo pálido interno, los cuales participan en la vía indirecta que disminuye la actividad de la corteza motora; el núcleo subtalámico, al excitarlas, aumenta la actividad del globo pálido interno, el cual inhibe la zona reticular intralaminar y, por tanto, reduce la excitación motora, mientras que la área premotora suplementaria integra la planificación motora y modula la inhibición mediante conexiones cortico‑basales. En contraste, el núcleo arqueado es parte del sistema límbico y se asocia principalmente con la regulación de la motivación, el apetito y la respuesta emocional, sin participar directamente en los circuitos de inhibición motora; por ello no interviene en la inhibición de la conducta. Las opciones A, B y C son las que sí participan en la vía indirecta de los ganglios basales y, por tanto, sí intervienen en la inhibición motora.'),
  (14, 'La técnica que permite reconstruir las rutas de las fibras nerviosas en el cerebro es la resonancia magnética con tensor de difusión (DTI), ya que la difusión de agua a lo largo de las fibras permite estimar su dirección y generar tractografía; la tomografía computarizada, aunque útil para estructuras anatómicas, no mide la anisotropía de la difusión y por tanto no puede generar imágenes virtuales de los haces; la espectroscopia por resonancia magnética se centra en la composición química de los tejidos y no en la arquitectura de las fibras; la estimulación magnética transcraneal es una modalidad terapéutica que modula la actividad cerebral pero no produce imágenes de las vías nerviosas.'),
  (15, 'La afirmación falsa es la D, pues la memoria semántica se sustenta principalmente en el sistema de memoria declarativa que integra el hipocampo y la corteza temporal medial (amígdala, parahippocampo) con la corteza prefrontal ventrolateral y dorsolateral, pero no requiere la participación directa del lóbulo prefrontal ventral; la evidencia de pacientes con daño en el lóbulo prefrontal ventral muestra preservación de la memoria semántica mientras que la memoria episódica se ve afectada, lo que indica que la función semántica no depende de esa región. En cambio, la opción A es verdadera porque la corteza prefrontal izquierda, especialmente la región dorsolateral, está implicada en la codificación de la información semántica mediante la organización y el acceso a categorías conceptuales, mientras que su papel en la recuperación es relativamente menor. La opción B es correcta porque la corteza prefrontal izquierda, en la parte ventrolateral, facilita la codificación de eventos episódicos al integrar la información contextual y la atención, y su participación en la recuperación es menos pronunciada que en la codificación. La opción C es cierta porque la corteza prefrontal derecha, particularmente la región ventromedial, se ha asociado con la recuperación de la memoria episódica, contrastando con la izquierda que se centra más en la codificación y el control ejecutivo; por tanto, la derecha supera a la izquierda en la recuperación episódica. Las opciones A, B y C comparten la característica de describir funciones de la corteza prefrontal en la memoria que están respaldadas por estudios de neuroimagen y de lesiones, mientras que la opción D falla al atribuir una dependencia directa del lóbulo prefrontal ventral para la memoria semántica.'),
  (16, 'La demencia por cuerpos de Lewy se caracteriza por la acumulación de alfa‑sinucleína en forma de cuerpos de Lewy, mientras que la parálisis supranuclear progresiva, la enfermedad de Alzheimer y el trastorno frontotemporal presentan depósitos patológicos de tau (en forma de filamentos de neurofibrillas, inclusiones neurofibrilares y cuerpos de Pick, respectivamente), por lo que son tauopatías; la demencia por cuerpos de Lewy, al no implicar tau, no se clasifica como tal. Las opciones A, B y C son tauopatías porque la patología de tau es el hallazgo neuropatológico principal, mientras que la opción D se excluye por la ausencia de tau y la presencia de alfa‑sinucleína.'),
  (17, 'La reactancia, según la teoría de la reactancia de Brehm, se refiere a la motivación que surge cuando una persona percibe una amenaza a su libertad de elección, y se manifiesta como una tendencia a afirmar o reforzar el comportamiento prohibido; esta propuesta no contempla la influencia de la presencia de otros en la mejora del rendimiento, por lo que no se vincula con la facilitación social. En contraste, la teoría de la aprehensión por la evaluación sostiene que la presencia de observadores aumenta la presión social y la ansiedad, lo que explica la mejora en tareas simples; la teoría de la distracción‑conflicto postula que la presencia de otros genera distracciones que reducen la carga cognitiva, favoreciendo el desempeño; y la teoría del impulso o de la motivación (activación) plantea que la presencia de una audiencia eleva el nivel de activación fisiológica, lo que potencia la ejecución de tareas bien aprendidas, todas ellas constituyen marcos explicativos de la facilitación social.'),
  (18, 'La teoría de los estados de expectativas de Berger y colaboradores se centra en cómo la percepción de la legitimidad y el estatus de los individuos dentro de un grupo influye en su comportamiento y en la dinámica grupal; por ello la opción B es la que describe adecuadamente el proceso de emergencia del estatus en las personas que integran los grupos, ya que la teoría explica que la expectativa de ser visto como un miembro valioso y competente determina la posición social y la influencia dentro del grupo. Las demás alternativas son inadecuadas: la A se refiere a emociones interpersonales, un tema distinto; la C habla de conformidad, que es un proceso diferente al de la formación de estatus; y la D trata conductas altruistas, que no es el foco principal de la teoría de expectativas.'),
  (19, 'La teoría de la conducta planificada extiende la teoría de la acción razonada al incluir el constructo de “control conductual percibido”, que representa la percepción de la facilidad o dificultad de ejecutar la conducta y su influencia en la intención, lo que permite explicar variaciones en la intención que la teoría de la acción razonada no contempla; las demás opciones son incorrectas porque la supresión de “creencias conductuales” no ocurre (el componente persiste), la introducción de relaciones no lineales no es una característica distintiva de la teoría de la conducta planificada, y la incorporación de relaciones directas entre actitud y conducta no es nueva, ya que la teoría de la acción razonada ya establece esa relación.'),
  (20, 'En el modelo de contenido de estereotipos de Fiske, la combinación de baja calidez y alta competencia se denomina “competencia sin afecto” y suele generar en la persona que percibe el estereotipo una sensación de superioridad y resentimiento, es decir, envidia; el individuo se siente desventajado frente a un grupo que percibe como más competente pero poco afable, lo que provoca una reacción de desdén y celos. Las otras opciones son incorrectas: la compasión (A) se asocia con baja calidez y baja competencia, la admiración (B) con alta calidez y alta competencia, y el desprecio (D) con baja calidez y baja competencia, por lo que solo la envidia encaja con la combinación de baja calidez y alta competencia.'),
  (21, 'El modelo de disociación de Devine sostiene que las personas que no presentan prejuicios automáticos experimentan un conflicto entre la respuesta automática de prejuicio y sus creencias personales, pues la última actúa como filtro que regula la expresión del sesgo cuando se percibe inconsistencia con la propia identidad y valores internos; por tanto la opción D refleja la tensión entre la respuesta automática y la internalización de normas personales que el modelo describe. Las demás opciones son inexactas porque el modelo no contempla la conducta real (A) como fuente de conflicto, pues la conducta se ajusta a la regulación interna, ni las emociones (B) ni los valores del entorno social (C) como factores directos de disociación; estos elementos pueden influir indirectamente pero no constituyen el núcleo del conflicto propuesto por Devine.'),
  (22, 'El paradigma del grupo mínimo, que consiste en asignar a los participantes a grupos arbitrarios y con recursos idénticos, se diseñó para estudiar la dinámica de la identidad social cuando la competencia entre grupos es mínima; los resultados mostraron que los individuos tienden a favorecer a su propio grupo aun cuando no haya una ventaja real, lo que evidencia la internalización de la pertenencia grupal como un componente esencial de la autoimagen, fundamento de la teoría de la identidad social, que explica cómo la pertenencia a un grupo constituye un aspecto central de la identidad individual y guía la conducta intergrupal. Las demás opciones son inadecuadas: la teoría de la autoafirmación se centra en la preservación de la autoestima frente a amenazas, no en la dinámica grupal; la teoría del pensamiento grupal se ocupa de la conformidad y la cohesión en la toma de decisiones, no del efecto de la pertenencia grupal en la autoimagen; y la teoría de la dominancia social se enfoca en la jerarquía y el poder entre grupos, no en la identidad mínima.'),
  (23, 'El fenómeno descrito corresponde al reflejo de Moro, también llamado reflejo de sobresalto, que se manifiesta en neonatos y lactantes menores de tres meses cuando se les produce una sensación de caída o se les expone a estímulos auditivos bruscos; el mecanismo involucra la extensión de los miembros, la apertura de las manos y la posterior flexión, reflejo que se asocia a la protección de la cabeza y a la respuesta de búsqueda de apoyo, y que desaparece con el desarrollo del sistema nervioso central. El reflejo de Babinski (A) se caracteriza por la extensión del dedo gordo del pie al estimular la planta del pie, no por la reacción a ruidos o caídas. El reflejo del primate (B) se refiere a la extensión de la mano ante la estimulación de la palma, y no implica la extensión de piernas ni la respuesta a ruidos. El reflejo de Babkin (C) es un reflejo de la mano que se observa en el recién nacido al tocar la palma, y tampoco corresponde a la reacción descrita.'),
  (24, 'El fenómeno descrito corresponde a la referenciación social, pues los infantes utilizan la mirada y las expresiones emocionales de los cuidadores como señales de referencia para interpretar la validez y el significado de estímulos novedosos, lo que constituye un mecanismo de aprendizaje social temprano; la audiencia imaginaria implica la presencia de una figura imaginaria que escucha al niño, lo que no se menciona en la pregunta; el andamiaje se refiere al apoyo estructurado que el adulto brinda al niño para avanzar en tareas cognitivas, no a la observación de señales emocionales; la teoría de la mente se refiere a la capacidad de atribuir estados mentales a otros, una competencia que se desarrolla más tarde en la infancia y no explica la conducta observada en los primeros meses.'),
  (25, 'La respuesta “Porque te pueden pillar y te castigarían” refleja la lógica de la moralidad preconvencional de Kohlberg, donde la conducta se regula principalmente por la evitación de castigos y la búsqueda de recompensas externas; el individuo actúa según la consecuencia inmediata y no por principios internos o normas sociales aceptadas, por lo que la opción B es la que corresponde. Las demás alternativas son incorrectas: la moralidad conformista (A) implicaría obedecer normas sociales sin cuestionarlas, pero no se centra en el miedo al castigo; la moralidad instrumental (C) se refiere a la utilización de la moral como medio para alcanzar fines, lo cual no se evidencia en la respuesta; y la moralidad heteronormativa (D) no es un término reconocido en la teoría de Kohlberg, por lo que no puede ser la respuesta adecuada.'),
  (26, 'El dominio de los principios cognitivos de reversibilidad, descentración e identidad, según la teoría de Piaget, constituye la etapa de operaciones concretas; en esta fase los niños ya pueden aplicar la conservación, es decir, comprender que la cantidad de una sustancia permanece constante a pesar de cambios en su forma o disposición, lo que les permite resolver problemas de conservación de masa, volumen y número; las otras opciones son incorrectas porque la resolución de problemas de adición y sustracción (A) se logra en la etapa de operaciones preoperacionales, la coordinación cognitiva y emocional (B) corresponde a la etapa de operaciones formales y la zona de desarrollo próximo (C) es un concepto de Vygotsky que no se relaciona directamente con la conservación.'),
  (27, 'El pensamiento posformal, según la teoría del desarrollo cognitivo de Piaget y sus posteriores ampliaciones, se define como la capacidad de integrar y reconciliar elementos aparentemente contradictorios, permitiendo la reflexión sobre la complejidad y la ambigüedad de las situaciones; este enfoque flexible y dialéctico distingue al adulto de las etapas preformal y formal, pues permite la valoración simultánea de múltiples perspectivas y la generación de soluciones que combinan diferentes aspectos de la realidad, algo que el pensamiento divergente (A) se limita a la generación de ideas sin necesariamente integrarlas, el pensamiento pragmático (B) se centra en la utilidad práctica sin la integración dialéctica, y el pensamiento integrativo (C) describe una síntesis de información pero no enfatiza la flexibilidad dialéctica que caracteriza al posformal; por lo tanto, la opción D es la que mejor corresponde a la descripción dada.'),
  (28, 'La respuesta es la opción A porque la teoría del ciclo vital de Baltes y Baltes identifica la selección, la optimización y la compensación como los tres procesos fundamentales que permiten a los individuos adaptarse a los cambios y demandas del entorno a lo largo de la vida; la selección implica la priorización de objetivos y recursos, la optimización se refiere al mejoramiento y la maximización de los recursos disponibles, y la compensación consiste en la sustitución de funciones perdidas o reducidas por otras estrategias o recursos. Las demás opciones son incorrectas: la B describe los procesos de adaptación de Piaget, no los de Baltes y Baltes; la C incluye conceptos que no aparecen en la teoría del ciclo vital; y la D presenta categorías temáticas (emociones, cognición, acción) que no corresponden a los procesos de adaptación propuestos por Baltes y Baltes.'),
  (29, 'En una regresión lineal simple la ecuación de la recta es Y = β0 + β1X + ε; el parámetro β1 es el coeficiente de regresión no estandarizado que representa la pendiente de la relación entre la variable predictora X y la variable de respuesta Y, es decir, el incremento esperado en Y cuando X aumenta en una unidad, manteniendo constantes los demás factores; por tanto, β1 es el valor que cuantifica el efecto marginal de la variable predictora. Los demás enunciados no cumplen esta función: el coeficiente β0 (opción B) es el intercepto, que indica el valor esperado de Y cuando X es cero y no describe el cambio por unidad; el coeficiente tipificado B1 (opción C) es la pendiente estandarizada, que expresa el cambio en unidades estándar y no en unidades originales de la variable; y el coeficiente de determinación corregido (opción D) mide la proporción de varianza explicada por el modelo, no el cambio unitario en la respuesta.'),
  (30, 'El estadístico que se emplea para detectar multicolinealidad en modelos de regresión lineal múltiple es la tolerancia, ya que mide la proporción de varianza de una variable predictora que no se explica por las demás variables del modelo; valores bajos indican alta colinealidad. El Durbin‑Watson (A) evalúa autocorrelación de residuos, la distancia de Cook (C) identifica observaciones influyentes y la correlación de Pearson (D) mide asociación bivariada, por lo que no sirven como indicadores de multicolinealidad.'),
  (31, 'En una regresión logística binaria, un predictor categórico con k niveles se codifica mediante k‑1 variables dummy para evitar la trampa de la colinealidad perfecta; la categoría de referencia queda implícita en el intercepto. Por lo tanto, con cuatro niveles se requieren tres variables dicotómicas, lo que corresponde a la opción B. La alternativa A sugiere una codificación insuficiente que no cubriría todas las comparaciones entre niveles; la opción C implica una sobrecodificación que introduciría una columna de colinealidad y haría imposible estimar el modelo; y la D añade una variable extra sin justificación, generando redundancia y complicando la interpretación.'),
  (32, 'La prueba recomendada cuando el supuesto de homocedasticidad se viola en un análisis de varianza unifactorial es la prueba de Brown‑Forsythe, ya que sustituye a la estadística F ordinaria mediante la comparación de la mediana de las desviaciones absolutas de cada grupo, lo que la hace robusta frente a heterogeneidad de varianzas; la opción B, Shapiro‑Wilk, evalúa la normalidad de los residuos y no la igualdad de varianzas; la C, Levene, también prueba la homogeneidad de varianzas, pero su versión original es menos robusta que Brown‑Forsythe cuando las distribuciones son asimétricas, y la D, Mauchly, se aplica a la suposición de esfericidad en ANOVA de medidas repetidas, no a la homocedasticidad.'),
  (33, 'La violación que se describe corresponde al supuesto de independencia local, que establece que la respuesta a cada ítem debe depender únicamente del nivel de la variable latente y no de las respuestas a otros ítems; cuando la respuesta a un ítem se ve condicionada por la respuesta a otro, se produce una correlación residual entre ítems que indica falta de independencia local. Las demás opciones son inexactas: la invarianza respecto a los ítems se refiere a la equivalencia de los ítems entre grupos, no a la dependencia entre respuestas; la linealidad exige que la relación entre la variable latente y la probabilidad de respuesta sea una función logística o similar, pero no impide la dependencia entre ítems; y la igualdad de errores típicos se refiere a la homogeneidad de la variabilidad de los ítems, no a la independencia de las respuestas entre sí.'),
  (34, 'El diseño jerárquico, también llamado “diseño de grupos anidados”, se caracteriza por la ausencia de un esquema de asignación aleatoria a los niveles superiores y por la falta de un plan de control de variables externas, lo que lo convierte en un diseño estructuralmente incompleto: no se puede garantizar la equivalencia interna ni la validez interna de los efectos observados, ya que los grupos internos dependen de la estructura externa sin un mecanismo de randomización que los iguale. En contraste, el diseño de bloques aleatorios (B) incorpora una randomización dentro de bloques homogéneos, asegurando comparabilidad; el diseño de covarianza (C) controla estadísticamente las variables de confusión mediante análisis de covariables; y el diseño con grupo de control no equivalente (D) aunque presenta limitaciones de equivalencia, sigue siendo estructuralmente completo porque mantiene un grupo de control, aunque no sea equivalente por randomización. Por tanto, solo la opción A presenta la falta de estructura necesaria para una investigación rigurosa.'),
  (35, 'El modelo de Cattell se fundamenta en la premisa de que la personalidad puede descomponerse en factores primarios que se manifiestan a través de la expresión lingüística; por ello, su punto de partida es el análisis del lenguaje, ya que a partir de la descripción de los rasgos en el discurso se extraen los factores de personalidad. Las demás opciones son inadecuadas: el enfoque biológico (A) y genético (D) no son la base metodológica de Cattell, pues él no parte de la herencia o de los procesos fisiológicos; el análisis del ambiente (C) tampoco es su punto de partida, pues la teoría de Cattell se centra en la estructura interna de la personalidad y no en la influencia externa.'),
  (36, 'El rasgo de búsqueda de emociones, que se asocia con la alta puntuación en la dimensión de apertura a la experiencia y la activación emocional, se manifiesta clínicamente en una persona que busca estímulos novedosos, asume riesgos y muestra energía y entusiasmo en sus actividades; estos comportamientos se correlacionan con la dimensión de extraversión, donde la sociabilidad, la actividad y la asertividad son los indicadores más fuertes, por lo que la opción A describe la combinación más coherente con el modelo de los cinco grandes. Las demás alternativas fallan porque mezclan rasgos que no están vinculados directamente a la búsqueda de emociones: la opción B introduce la desconfiada, típica del rasgo de neuroticismo; la C enfatiza la autodisciplina, característica del rasgo de responsabilidad; y la D combina calidez y impulsividad, pero la calidez pertenece a la amabilidad, no a la búsqueda de emociones, dejando a la opción A como la única que integra los componentes teóricos correctos.'),
  (37, 'La teoría de la reactancia de Brehm sostiene que cuando una persona percibe una amenaza a su libertad, experimenta una motivación interna para restaurar esa libertad, lo que se manifiesta en tres formas: (A) la restauración directa, donde la conducta prohibida se lleva a cabo; (B) la restauración indirecta, donde la persona busca alternativas que le permitan obtener la misma satisfacción sin infringir la restricción; y (D) la negación de la amenaza, donde la persona minimiza o niega la validez de la restricción. La opción (C) – la pérdida o disminución del atractivo de la conducta amenazada – no corresponde a la teoría, pues la reactancia no implica una desvaloración de la conducta prohibida sino un impulso para recuperarla o justificarla; por lo tanto, las demás alternativas reflejan los mecanismos propuestos por Brehm, mientras que la (C) describe un fenómeno contrario al de la reactancia.'),
  (38, 'La necesidad de logro, según la teoría de McClelland, se manifiesta en la búsqueda de metas desafiantes pero alcanzables; por ello las personas con un nivel alto de esta necesidad tienden a escoger tareas de dificultad media, pues les permiten experimentar éxito y aprendizaje sin caer en la frustración de objetivos demasiado exigentes, lo que favorece la motivación intrínseca y la autoeficacia; en contraste, la opción A es errónea porque un bajo nivel de necesidad de logro conduce a la evitación de retos, prefiriendo tareas fáciles o de baja exigencia, no moderadas; la alternativa B es falsa porque la alta necesidad de logro no impulsa a elegir tareas extremadamente difíciles, ya que el riesgo de fracaso disminuye la satisfacción y la motivación; la respuesta D también es incorrecta, pues la elección de carreras universitarias de extrema dificultad no es una característica típica de los individuos con alta necesidad de logro; suelen optar por programas que ofrezcan un equilibrio entre desafío y posibilidad de éxito, evitando la sobrecarga académica que puede generar ansiedad y desmotivación.'),
  (39, 'El modelo atribucional de Weiner distingue tres dimensiones que estructuran la interpretación de causas de eventos: el locus de causalidad (interno o externo), la estabilidad (si la causa es permanente o transitoria) y la controlabilidad (si la causa puede ser modificada por el individuo). Estas tres variables permiten diferenciar entre atribuciones que generan una sensación de poder y control frente a aquellas que generan impotencia, lo cual es fundamental para la motivación y la regulación emocional. Las otras opciones son incorrectas porque mezclan conceptos que no pertenecen al marco teórico de Weiner: la distinción entre distintividad, consistencia y consenso no corresponde a su esquema; la combinación de estabilidad, globalidad e internalidad no refleja las tres dimensiones propuestas; y la propuesta de intencionalidad, estabilidad y especificidad incluye una variable (intencionalidad) que no forma parte del modelo atribucional de Weiner.'),
  (40, 'El fenómeno descrito, el incremento sostenido de las puntuaciones de cociente intelectual a lo largo de las generaciones, se conoce como el Efecto Flynn, nombrado por James R. Flynn, quien documentó en la década de 1980 que las puntuaciones promedio de CI en distintas poblaciones habían aumentado de forma sistemática; este hallazgo se ha replicado en múltiples países y se atribuye a factores ambientales como la mejora en la nutrición, la educación, la complejidad cognitiva de la vida cotidiana y la reducción de la exposición a enfermedades infantiles, lo que favorece el desarrollo neurológico y la capacidad de resolución de problemas. Las demás opciones son incorrectas: el Efecto Catell se refiere a la estructura de la inteligencia con factores generales y específicos, el Efecto Horn se relaciona con la teoría de la inteligencia de Horn sobre la evolución de los factores de inteligencia, y el Efecto Stern no corresponde a ningún fenómeno reconocido en la literatura de psicología de la inteligencia.'),
  (41, 'El test de vocabulario del WISC‑IV o WAIS‑IV mide la capacidad de acceder y usar el conocimiento adquirido a lo largo de la vida, es decir, la inteligencia cristalizada, ya que exige la recuperación de definiciones y significados consolidados en la memoria semántica; la respuesta B refleja precisamente esta dimensión. Las opciones A y D se refieren a procesos fluidos y de memoria de trabajo que no se evalúan con un solo ítem de vocabulario, mientras que la C, aunque implica almacenamiento y recuperación, no distingue la distinción entre conocimiento semántico consolidado y la mera capacidad de retener información a largo plazo, por lo que no corresponde al objetivo principal del test.'),
  (42, 'La propuesta de Guilford distingue entre tipos de procesos cognitivos (operaciones, contenidos y productos) y no los organiza en una jerarquía de niveles de inteligencia; su modelo de la matriz de la inteligencia enfatiza la multidimensionalidad y la interrelación de las capacidades sin establecer una estructura de dominio superior, lo que responde a la pregunta. Las demás opciones presentan modelos jerárquicos: Cattell desarrolló la teoría de la inteligencia fluidal y cristalizada con una jerarquía de factores primarios y secundarios; Vernon propuso una jerarquía de niveles de inteligencia con factores generales y específicos; y Carroll integró las teorías de Cattell y Horn en un modelo de tres niveles (g, fluidez, cristalización), también jerárquico.'),
  (43, 'El enunciado falso es la opción A; el programa Triple P Universal, diseñado para la prevención primaria, suele ser implementado por profesionales de la salud pública o de la educación, pero no se limita a la atención primaria y su aplicación se realiza mayoritariamente por psicólogos, trabajadores sociales o educadores, no exclusivamente por médicos de atención primaria. La opción B es verdadera porque el nivel estándar de Triple P se ofrece en sesiones grupales o individuales y es llevado a cabo por psicólogos, psiquiatras u otros profesionales de la salud mental, con un enfoque de intervención temprana y prevención secundaria. La opción C también es correcta: el nivel selectivo de Triple P contempla de una a dos sesiones orientadas a problemas leves de conducta, con intervención breve y dirigida a familias que presentan dificultades moderadas. La opción D es verdadera; el nivel aumentado de Triple P se dirige a conductas disruptivas severas que se ven agravadas por factores estresores familiares, y se aplica con estrategias intensivas y de mayor duración. Por tanto, la única afirmación que no concuerda con la estructura y la práctica del programa es la A.'),
  (44, 'El programa No Worries! de Holmes (2014) es un tratamiento grupal diseñado para niños con trastorno de ansiedad generalizada y sus padres, que integra técnicas de relajación, respiración y entrenamiento en manejo de la ansiedad; su enfoque es predominantemente cognitivo‑conductual, abordando la intolerancia a la incertidumbre, las creencias negativas sobre la preocupación y la evitación cognitiva, lo que coincide con las opciones A, B y C, por lo que son consistentes con la descripción del programa; la opción D, en cambio, es falsa porque No Worries! no es una adaptación del tratamiento metacognitivo de Wells, sino un protocolo propio que se basa en la terapia cognitivo‑conductual adaptada a la población infanto‑juvenil, por lo que la afirmación de que es una adaptación del tratamiento metacognitivo es incorrecta.'),
  (45, 'El modelo de personalidad de Gray se fundamenta en la teoría de la motivación que distingue dos sistemas neurobiológicos: el Sistema de Respuesta a la Recompensa (BAS) y el Sistema de Respuesta a la Castigo (BIS); la primera regula la impulsividad y la búsqueda de recompensas, mientras que la segunda controla la ansiedad y la evitación de estímulos aversivos, de modo que las dimensiones de impulsividad y ansiedad se explican mediante la interacción de estos mecanismos biológicos y las consecuencias conductuales que siguen a la conducta, lo cual coincide con la opción A; las demás alternativas son inexactas porque la opción B mezcla conceptos cognitivos con biológicos pero no aborda la relación específica entre impulsividad, ansiedad y los sistemas de recompensa y castigo; la C se refiere a la activación cerebral y a superfactores psicoticismo, extraversión y neuroticismo, que pertenecen a la teoría de Eysenck y no a la de Gray; y la D limita la explicación a la extraversión sin considerar el componente de ansiedad ni la estructura de los sistemas de motivación, por lo que se excluye.'),
  (46, 'La opción D es falsa porque la técnica del diferencial semántico de Osgood no exige que el encuestado evite responder de forma rápida; al contrario, la rapidez de respuesta no se considera un criterio de validez, ya que la escala mide la percepción de atributos mediante juicios de valor que pueden expresarse en segundos sin comprometer la calidad de la información. En cambio, la opción A es verdadera pues el diferencial semántico se basa en una teoría mediacional neoconductista que relaciona estímulos, respuestas y consecuencias; la opción B es correcta porque el significado denotativo se refiere al contenido objetivo o factual de un concepto; y la opción C también es cierta, pues el formato de respuesta más habitual emplea escalas de siete intervalos que permiten una mayor variabilidad y sensibilidad en la medición de los atributos evaluados.'),
  (47, 'En la evaluación psicológica, el nivel de inferencia que se fundamenta en la hipótesis de que la respuesta evaluada puede estar relacionada o correlacionada con otras conductas se denomina Nivel II; este nivel implica la identificación de patrones o relaciones entre la variable medida y otras variables o comportamientos, sin llegar a establecer causalidad, lo cual es característico de la inferencia de correlación o asociación. Las opciones A y D se refieren a niveles de inferencia más básicos (Nivel I) o más complejos (Nivel IV), respectivamente, que implican la interpretación de la respuesta en términos de un único constructo o la inferencia causal directa, lo cual no corresponde a la descripción dada; la opción C, Nivel III, se centra en la inferencia de un constructo latente a partir de múltiples indicadores, por lo que tampoco se ajusta al supuesto de relación o correlato entre conductas.'),
  (48, 'El factor primario del modelo de la personalidad de Guilford es la **objetividad**, pues Guilford distingue entre factores primarios (dimensiones básicas de la personalidad) y secundarios (subdimensiones derivadas), y la objetividad se refiere a la tendencia a valorar la información de manera racional y basada en evidencia, una característica fundamental en su teoría; las demás opciones corresponden a rasgos secundarios o a constructos que no aparecen en el esquema de Guilford: la disposición paranoide y la independencia son rasgos de personalidad que se clasifican en categorías distintas (por ejemplo, en el modelo de los cinco grandes, la paranoia se relaciona con la neuroticismo y la independencia con la apertura a la experiencia), mientras que la extraversión, aunque es un rasgo ampliamente estudiado, se ubica en la dimensión de la extraversión/introversión, que Guilford no la designa como factor primario dentro de su estructura.'),
  (49, 'El aparato “Omega” se emplea para medir la velocidad de procesamiento y la coordinación motora fina, por lo que se clasifica dentro de las técnicas motoras, ya que evalúa la ejecución de tareas que implican movimientos precisos y la respuesta a estímulos físicos; las opciones A y B son incorrectas porque el instrumento no se centra en la percepción sensorial ni en procesos cognitivos como la memoria o el razonamiento, sino en la capacidad motora; la alternativa D es errónea porque las técnicas estructurales se refieren a la organización de la información y no a la medición de la función motora.'),
  (50, 'La batería que contempla las subescalas de procesamiento simultáneo, procesamiento sucesivo y conocimientos es la Batería de Evaluación para Niños de Kaufman y Kaufman (K‑ABC); su modelo de procesamiento de información distingue explícitamente entre procesamiento simultáneo (capacidad de integrar información de forma holística) y procesamiento sucesivo (capacidad de procesar secuencialmente), mientras que la subescala de conocimientos evalúa el dominio de contenidos académicos y culturales, lo que coincide con la descripción de la pregunta; las demás opciones no se ajustan: el CAS de Naglieri y Das se basa en la teoría de la inteligencia de la teoría de la inteligencia de procesamiento de la información, pero sus subescalas se denominan “procesamiento de la información” y “conocimientos” sin diferenciar simultáneo y sucesivo; la WPPSI‑IV utiliza índices de rendimiento verbal y de rendimiento no verbal, sin subescalas de procesamiento simultáneo/sucesivo; y la MSCA es una prueba de aptitudes y psicomotricidad, no una batería de inteligencia con esas subescalas.'),
  (51, 'La opción B es la que se ajusta a la “Regla de las tres D” de la observación directa: las unidades de comportamiento deben ser **delimitables** para que el observador pueda marcar claramente sus límites temporales y espaciales; **denominables** para que se les pueda asignar un nombre o etiqueta que permita su registro y comunicación; y **definibles** para que se describan con criterios precisos y observables, evitando ambigüedades. En contraste, la alternativa A incluye “directas”, término que no se emplea en la regla y que sugiere una relación causal que no corresponde a la definición de unidad observacional; la opción C utiliza “divisibles”, “distinguibles” y “diferenciables”, que aunque parecen coherentes, no reflejan la terminología establecida y carecen de la especificidad de “delimitables” y “definibles”; la alternativa D sustituye “definibles” por “determinat­es”, que implica una causalidad o determinismo que la regla no exige, por lo que no cumple con los criterios de observación directa.'),
  (52, 'La entrevista motivacional se concibe como una técnica de intervención que integra simultáneamente la evaluación y la acción terapéutica, pues el proceso de indagar las motivaciones y ambivalencias del paciente sirve para identificar objetivos de cambio y, al mismo tiempo, para diseñar estrategias de intervención; por eso la opción A refleja fielmente su naturaleza dual, mientras que la B es errónea porque la técnica no se desarrolló para la depresión sino para el cambio de conductas de riesgo; la C es incorrecta porque, aunque los cuatro principios (reflexión, empatía, autonomía y colaboración) son centrales, no incluye la discusión directa de la resistencia, que se evita; y la D se equivoca al afirmar que la entrevista es directa y utiliza preguntas cerradas, cuando en realidad se caracteriza por la ausencia de directividad y el uso de preguntas abiertas para fomentar la autorreflexión.'),
  (53, 'Las pruebas de aprovechamiento de orientación amplia, como las pruebas de rendimiento académico de tipo “broad” o “wide‑band”, están diseñadas para medir el nivel general de aprendizaje y dominio de contenidos escolares en distintas áreas, sin centrarse en habilidades específicas o subcomponentes particulares; por ello presentan el mayor grado de especificidad en el sentido de que evalúan el rendimiento global y no una faceta puntual de la cognición o la aptitud, lo que las distingue de las demás opciones. En cambio, los test de aptitud e inteligencia de tipo verbal (A) miden habilidades lingüísticas y de razonamiento verbal, por lo que son más específicos en ese dominio particular; los test transculturales de inteligencia (B) buscan la equivalencia cultural y, al hacerlo, reducen la especificidad al intentar medir la inteligencia de forma universal; y las pruebas de desempeño sin lenguaje (C) se centran en la ejecución de tareas no verbales, lo que las hace menos específicas respecto al aprovechamiento escolar en general.'),
  (54, 'La tendencia de la persona a la fantasía y a la imaginación se refleja principalmente en la ubicación del dibujo dentro del papel, es decir, en su emplazamiento; cuando el dibujo se sitúa en los márgenes o en la esquina, indica una preferencia por el espacio “libre” y la distancia de la realidad, lo que sugiere una mayor orientación hacia el mundo de las ideas y la búsqueda de satisfacciones en la fantasía; el tamaño del dibujo (opción A) se relaciona más con la autoestima y la necesidad de control, la proyección (opción B) se interpreta como la transferencia de contenido interno al objeto externo y la presión del trazo (opción D) se vincula con la intensidad emocional y la impulsividad, por lo que no son indicadores directos de la inclinación a la fantasía.'),
  (55, 'La opción d) es la única que corresponde a la clasificación de evidencias de validez según la normativa de la psicometría; la validez de criterio o de relación con otras variables se evalúa mediante correlaciones o modelos estructurales que relacionan el puntaje del test con variables externas, y esta evidencia se puede obtener tanto con la teoría clásica de los test (TCT) como con la teoría de respuesta al ítem (TRI), aunque la respuesta menciona únicamente la TCT, lo cual es suficiente para la respuesta; las demás alternativas fallan porque la evidencia de estructura interna (opción A) se recoge con análisis factoriales y la TRI se utiliza para estimar parámetros de ítems, no para la validez interna; la evidencia basada en el contenido (opción B) se evalúa por revisión de expertos y no por análisis de temas o palabras; y la evidencia de generalidad (opción C) se refiere a la consistencia interna, no a la generalidad, y su evaluación no se limita a la TRI, TCT ni teoría conductual.'),
  (56, 'La escala acumulativa es la que se emplea cuando al evaluado se presenta una lista de adjetivos y se le solicita marcar aquellos que considera aplicables a la característica evaluada; cada ítem se suma para obtener un puntaje total que refleja la presencia o ausencia de la característica, lo que permite cuantificar la intensidad de la misma sin requerir comparaciones entre ítems. Las demás alternativas son inadecuadas: la escala de intensidad (A) exige grados de intensidad para cada ítem, no una simple selección de aplicabilidad; la escala de orden (B) requiere que el evaluado clasifique los ítems en una jerarquía, lo cual no corresponde a la tarea de marcar los que le parecen pertinentes; y la escala de elección no forzada (C) implica que el evaluado elija entre opciones mutuamente excluyentes, mientras que en la escala acumulativa puede marcar varios ítems simultáneamente.'),
  (57, 'El prototipo descrito corresponde a un registro semisistematizado, pues la estructura tabular con columnas que codifican niveles de respuesta y filas que identifican unidades de conducta o textos refleja la codificación sistemática de observaciones, pero con cierta flexibilidad que permite la inclusión de categorías predefinidas y la posibilidad de añadir observaciones libres cuando sea necesario; este formato facilita la cuantificación de conductas específicas sin perder la riqueza cualitativa de la observación. Las demás opciones son inadecuadas: el registro narrativo (B) se basa en descripciones continuas y sin codificación tabular; el registro de interacción (C) se centra en la dinámica entre sujetos y no en la codificación de unidades de conducta; y el registro de apreciación (D) implica juicios subjetivos del observador, lo que no se ajusta a la descripción de una tabla con niveles de respuesta.'),
  (58, 'En la evaluación narrativa el análisis textual se centra en la estructura y el contenido del relato, examinando la coherencia, la cohesión, las redundancias, los recursos retóricos y la organización de las unidades discursivas; la detección de macroestructuras, que implica identificar grandes bloques temáticos o arquetipos narrativos, pertenece a la fase de interpretación o síntesis de la narración, no al análisis textual propiamente dicho, por lo que no forma parte de esta etapa; las demás opciones sí corresponden a actividades de análisis textual: la generación de síntesis discursiva resume el contenido y la organización del texto, el análisis de coherencias evalúa la lógica interna y la consistencia de la narrativa, y el análisis de las redundancias identifica repeticiones que pueden indicar énfasis o falta de claridad.'),
  (59, 'El subtest “matrices” del WAIS‑IV mide el razonamiento abstracto no verbal, ya que exige que el examinando identifique patrones lógicos y relaciones entre figuras geométricas sin recurrir al lenguaje, evaluando la capacidad de inferir reglas y completar secuencias basadas en relaciones espaciales y de similitud; esta habilidad se asocia con la inteligencia fluida. Las opciones B y C se refieren a procesos que implican análisis de información visual y categorización lógica, respectivamente, pero el subtest no requiere discriminación de elementos arbitrarios ni clasificación de categorías, sino la identificación de relaciones abstractas; la opción D describe la percepción visual y la praxis constructiva, competencias que se evalúan en subtests como “bloques” o “puzzle”, no en “matrices”.'),
  (60, 'El punto de fusión “Flicker” se emplea para medir la percepción visual objetiva porque evalúa la capacidad de la visión binocular de fusionar dos estímulos alternados, lo que permite determinar la sensibilidad a la disparidad y la integridad de la función visual binocular; su aplicación clínica se centra en la detección de ambliopía, estrabismo y otras alteraciones de la fusión, ofreciendo datos cuantitativos sobre la tolerancia a la disparidad. El estesiómetro, aunque también mide la percepción visual, se utiliza para valorar la percepción de profundidad y la percepción de la posición de los objetos en el espacio, no la fusión binocular. El test de precisión de Purdue es un instrumento de medición de la precisión motora fina y no se relaciona con la percepción visual. El test de discriminación de dos puntos evalúa la sensibilidad táctil cutánea y no la percepción visual.'),
  (61, 'La respuesta indica que el sujeto debe estimar el porcentaje de tiempo que le acontecen experiencias disociativas, pues la escala de Likert de 0 a 100 % en la DES se emplea para cuantificar la duración relativa de dichos episodios dentro de un periodo determinado, reflejando la frecuencia en términos de tiempo transcurrido; las demás opciones son incorrectas porque la opción A mezcla frecuencia e intensidad en un producto, la opción C confunde el período de referencia con un mes anterior y la opción D se centra únicamente en la intensidad, omitiendo la dimensión temporal que la escala pretende medir.'),
  (62, 'El EGEP‑5 de Crespo y colaboradores se distingue por incorporar una escala de síntomas postraumáticos que va más allá de los criterios estrictamente definidos por el DSM‑5, integrando manifestaciones como la disociación, la irritabilidad crónica y la alteración del sueño que, aunque no forman parte de la clasificación oficial, son frecuentes en la clínica y se han validado en estudios de población española; por ello la opción C se justifica clínicamente y metodológicamente. La alternativa A es falsa porque el instrumento presenta escalas de respuesta distintas (0‑3, 0‑4 y 0‑5) según la dimensión evaluada, lo que permite una mayor sensibilidad a la variabilidad de los síntomas. La opción B es incorrecta ya que el EGEP‑5 se administra preferentemente de forma auto‑aplicada, facilitando su uso en grandes muestras y en entornos clínicos con recursos limitados, aunque puede emplearse en entrevistas heteroaplicadas cuando se requiere mayor precisión. Finalmente, la alternativa D resulta errónea porque el test no se organiza en dos secciones separadas; la parte de acontecimientos traumáticos y la de sintomatología están integradas en una única escala compuesta por ítems que evalúan ambos aspectos simultáneamente, evitando la doble carga de respuesta y mejorando la coherencia interna.'),
  (63, 'El modelo de coherencia narrativa de Adler y colaboradores (2007) identifica cuatro índices que permiten evaluar la consistencia y la integridad de la historia de vida de un individuo: orientación (la capacidad de situarse en el tiempo y el espacio), estructura (la organización lógica de los episodios), afecto (la regulación emocional y la expresión de sentimientos coherentes) e integración (la síntesis de experiencias en una narrativa unificada); estos cuatro elementos constituyen la base para determinar la coherencia narrativa, por lo que la opción A los recoge correctamente. Las demás alternativas presentan conceptos que, aunque relevantes en otros modelos de psicología clínica, no corresponden a los índices de coherencia narrativa: la opción B incluye “unidad” y “diálogo”, que son componentes de la coherencia discursiva pero no de la narrativa; la opción C menciona “autodominio” y “estatus”, que se relacionan con la autoestima y la regulación del comportamiento, no con la coherencia narrativa; y la opción D enumera “valores”, “tema vital” y “logro”, que son constructos de la identidad y la motivación, pero no los indicadores de coherencia de la historia de vida.'),
  (64, 'El Inventario de adjetivos para la evaluación de los trastornos de personalidad (IA‑TP) de Tous y colaboradores (2009) dispone de escalas específicas que capturan los rasgos más característicos de cada trastorno de personalidad; la escala “Personalidad respetuosa” se diseñó para medir la preocupación excesiva por la conformidad, la adhesión a normas y la necesidad de ser aceptado, rasgos que definen el trastorno obsesivo‑compulsivo de la personalidad (TOCP), donde la rigidez, el perfeccionismo y la preocupación por el orden son predominantes; por tanto, la escala que se asocia con el TOCP es la de “Personalidad respetuosa”. Las opciones A, B y C corresponden a escalas que miden rasgos de otros trastornos: “Personalidad inhibida” se relaciona con el trastorno evitativo, “Personalidad perfeccionista” con el trastorno narcisista y “Personalidad sensible” con el trastorno de la personalidad dependiente; por ello no se ajustan al perfil del TOCP.'),
  (65, 'El Inventario de Evaluación de la Personalidad (PAI) se fundamenta en la teoría de la personalidad de la psicopatología y su estructura se compone de 22 escalas: 4 de validez (para detectar respuestas inadecuadas o inconsistentes), 14 clínicas (que miden síntomas y rasgos de trastornos de personalidad y otras patologías), 3 de consideraciones para el tratamiento (que ayudan a orientar la intervención) y 1 de conflictos interpersonales; por lo tanto la opción A es falsa. La normativa del PAI establece que la validez del protocolo se ve comprometida cuando el número de omisiones o respuestas dobles supera los 18, ya que esto indica una falta de esfuerzo o una respuesta incoherente que invalida la interpretación de las escalas clínicas, lo que hace que la opción B sea la única que coincide con la información oficial. La finalidad del PAI no se limita exclusivamente a la evaluación de trastornos de personalidad, pues también incluye escalas clínicas que abordan síntomas de ansiedad, depresión, trastornos somatomorfos, entre otros, por lo que la opción C es incorrecta. Finalmente, la versión abreviada del PAI no se compone de los primeros 100 ítems, sino de 50 ítems seleccionados de todas las escalas, lo que invalida la opción D.'),
  (66, 'El Cuestionario breve de calidad de vida (CUBRECAVI) de Fernández‑Ballesteros y colaboradores (1996) se diseñó como una herramienta de auto‑evaluación que puede aplicarse tanto en formato escrito como mediante entrevista, lo que permite su uso en poblaciones con dificultades de lectura o en contextos clínicos donde el entrevistador puede aclarar dudas; por ello la alternativa que indica que “se puede administrar mediante entrevista o cuestionario autoaplicado” es la única que describe correctamente su modalidad de aplicación. Las demás opciones resultan inexactas: la primera es falsa porque el CUBRECAVI está pensado para adultos mayores a partir de los 50 años, no exclusivamente a partir de los 55; la segunda es incorrecta ya que el instrumento contempla seis dimensiones (salud física, salud mental, relaciones sociales, actividades de ocio, autonomía y entorno), no cinco; y la tercera es errónea porque la escala de salud percibida incluye los ítems de energía, dolor, reacciones emocionales, sueño, aislamiento social y movilidad, pero no se describe como “evaluación de la salud percibida” sino como parte de las dimensiones de calidad de vida.'),
  (67, 'El índice de Lawton y Brody se emplea específicamente para evaluar las actividades instrumentales de la vida diaria (AIVD), es decir, las tareas que requieren un nivel de autonomía mayor, como la gestión del dinero, la preparación de comidas, el uso del transporte y la administración de medicamentos, y que son indicativas de la capacidad funcional en la vida cotidiana de personas con dependencia; por tanto, es el instrumento indicado en la pregunta. El índice de Katz y el de Barthel miden las actividades básicas de la vida diaria (ABVD), como el baño, el vestido, la movilidad y la alimentación, y no abordan la complejidad de las AIVD. El índice de Morton, por otro lado, se utiliza para valorar la movilidad y la marcha, no la autonomía funcional en actividades diarias.'),
  (68, 'La opción C es la que corresponde a la descripción de la PANSS: la escala está diseñada para cuantificar la gravedad de los síntomas positivos, negativos y generalizados de la esquizofrenia, y su uso permite diferenciar clínicamente entre un cuadro predominantemente positivo, negativo o mixto, lo que facilita la planificación terapéutica y el seguimiento de la respuesta al tratamiento; la escala no se limita a una clasificación categórica rígida, sino que proporciona puntuaciones continuas que se interpretan en función de los rangos clínicos, pero la distinción entre tipos de presentación es una de sus utilidades principales. La alternativa A es incorrecta porque la escala compuesta (PANSS-C) se calcula sumando la puntuación de la escala positiva y la negativa (PANSS-C = PANSS-P + PANSS-N), no restándolas. La opción B es falsa porque cada ítem se evalúa con una escala tipo Likert de 7 puntos, no de 5. Finalmente, la alternativa D es errónea porque la PANSS se aplica con referencia a la sintomatología presente en el momento de la evaluación, no específicamente al último mes, aunque la escala puede usarse para evaluar la evolución a lo largo del tiempo.'),
  (69, 'La subteoría experiencial de la teoría triárquica de Sternberg se refiere a la capacidad de aprender de la experiencia y de aplicar ese aprendizaje de forma flexible y novedosa, lo cual constituye la base de la creatividad; la creatividad exige la generación de ideas originales y la adaptación de conocimientos previos a contextos nuevos, funciones que se desarrollan precisamente a través de la experiencia acumulada y la capacidad de transferirla a situaciones inéditas. Las otras opciones son incorrectas porque la subteoría componencial (A) se centra en el procesamiento de información y la resolución de problemas, más vinculada a la inteligencia analítica que a la creativa; la subteoría contextual (C) aborda la adaptación al entorno y la aplicación de la inteligencia en contextos específicos, pero no explica la generación de ideas originales; y la subteoría de ejecución (D) se relaciona con la ejecución de tareas y la aplicación de la inteligencia práctica, sin abordar la dimensión creativa.'),
  (70, 'La decisión que no pertenece al nivel de muestreo intersesional es la opción D, ya que los intervalos en que se divide la sesión de observación corresponden al nivel de muestreo intra‑sesional, donde se determina la granularidad temporal dentro de cada sesión; en cambio, las opciones A, B y C se refieren a parámetros que regulan la relación entre sesiones: el periodo de observación (intervalo entre el inicio y el fin del seguimiento), el número mínimo de sesiones (cuántas sesiones se deben registrar para garantizar la representatividad) y el criterio de inicio de sesión (condiciones que deben cumplirse para considerar que una sesión ha comenzado), todos son decisiones que se toman a nivel intersesional.'),
  (71, 'La NEPSY‑II es una batería diseñada para evaluar el desarrollo cognitivo en la infancia y la adolescencia temprana; su estructura incluye módulos específicos que miden el reconocimiento de emociones faciales y la teoría de la mente, aspectos fundamentales de la función socioemocional y la comprensión de estados mentales ajenos, por lo que la opción A describe una característica esencial de la batería. Las demás alternativas son incorrectas: la opción B es errónea porque el tiempo de aplicación típico de NEPSY‑II es de 45 a 60 min, no 30‑45 min; la opción C es falsa ya que la batería no dispone de una forma dirigida a padres, sino que se centra en la evaluación directa del niño; y la opción D es inexacta porque NEPSY‑II sí cubre la evaluación de adolescentes hasta los 16 años, por lo que no se limita solo a niños.'),
  (72, 'La prueba que no forma parte de las estructuras rítmicas de Stambak es la reproducción de estructuras espaciales dictadas (opción C), porque el modelo de Stambak se centra en la evaluación de la percepción y la memoria de estructuras rítmicas, es decir, en la reproducción de patrones temporales y espacio‑temporales que se perciben o se escuchan; la reproducción de estructuras espaciales dictadas no implica un componente rítmico ni auditivo y, por tanto, no se ajusta a la lógica de la prueba. En cambio, la reproducción gráfica de estructuras espaciales observadas (A) y la reproducción de estructuras temporales escuchadas (B) son actividades que evalúan la percepción visual y auditiva de patrones rítmicos, respectivamente, y la simbolización de estructuras espacio‑temporales (D) permite la integración de ambos dominios, todas alineadas con la teoría de Stambak. Las opciones A, B y D comparten la característica de involucrar la percepción y reproducción de patrones rítmicos, mientras que la opción C se desvía al requerir únicamente la reproducción espacial sin componente rítmico.'),
  (73, 'La prueba de Columbia (CMMS) es una batería de evaluación de la conducta y el desarrollo que se aplica a niños de 5 a 12 años; su contenido y escalas de puntuación no están diseñadas para la edad temprana de 3 años, por lo que no se emplea en esa población. En contraste, la Escala McCarthy de aptitudes y psicomotricidad (MSCA) se orienta a niños de 3 a 7 años y evalúa habilidades cognitivas y motoras; la Batería Kaufman y Kaufman (K‑ABC) cubre desde la infancia temprana hasta la adolescencia, con versiones específicas para niños de 3 años; y el Inventario de Desarrollo Battelle incluye módulos para bebés y niños pequeños, incluyendo la edad de 3 años. Las otras opciones, por tanto, sí se utilizan en niños de esa edad, mientras que la CMMS no lo hace.'),
  (74, 'El WPPSI‑IV, en la franja de 2 años 6 meses a 3 años 11 meses, emplea la batería de subpruebas que permite calcular los índices de Comprensión Verbal, Visuoespacial y Memoria de Trabajo; estos tres índices constituyen la base de la interpretación del coeficiente intelectual en este rango etario, por lo que la opción B es la única que refleja la estructura de índices que el manual prescribe para la edad mencionada. La opción A es incorrecta porque las subpruebas citadas (matrices, búsqueda de animales, semejanzas, conceptos, cancelación y vocabulario) corresponden al nivel superior de aplicación (4 años 0 meses a 6 años 11 meses), no al inferior; la opción C es errónea porque el índice de Competencia Cognitiva es propio del WPPSI‑III y no se incluye en la versión IV, donde la interpretación se basa en los índices de Comprensión Verbal, Visuoespacial y Memoria de Trabajo; y la opción D es inexacta porque los índices de Razonamiento Fluido y de Velocidad de Procesamiento aparecen en la versión IV solo en la franja de 4 años 0 meses a 6 años 11 meses, no en la franja inferior.'),
  (75, 'El índice de razonamiento perceptivo de segundo orden del BAS‑II se obtiene a partir de la combinación de la prueba de conceptos numéricos, que evalúa la capacidad de abstraer y organizar información numérica a partir de patrones visuales, y la prueba de semejanzas gráficas, que mide la habilidad de identificar relaciones entre objetos visuales y establecer categorías conceptuales; ambas tareas requieren la integración de la percepción visual con el razonamiento abstracto, característica esencial del razonamiento perceptivo de segundo orden. Las demás opciones son incorrectas porque el test de copia y el test de cubos (A y D) se utilizan para valorar la percepción visual y la organización espacial, pero no incorporan la dimensión de abstracción numérica necesaria; el test de semejanzas gráficas y el test de cubos (B) combinan una prueba de semejanzas con una prueba de organización espacial, sin incluir la evaluación numérica que es indispensable para el razonamiento perceptivo de segundo orden.'),
  (76, 'La Escala de tolerancia materna de Morgan y Young evalúa la capacidad de la madre para aceptar y manejar la enuresis funcional del niño, y estudios longitudinales han demostrado que valores bajos en esta escala se asocian con una mayor probabilidad de abandono prematuro de la intervención, ya que la falta de tolerancia conduce a una menor motivación para continuar el tratamiento; en cambio, las opciones B y C se refieren a la implicación directa de la madre y la adherencia del niño, respectivamente, aspectos que no se correlacionan de manera significativa con la escala, mientras que la opción D, que sugiere una relación con la eficacia en casos resistentes, no ha sido respaldada por la literatura, pues la escala mide la tolerancia más que la respuesta al tratamiento.'),
  (77, 'La opción A es la única que refleja la evidencia epidemiológica de que, según Haro y colaboradores (2015), más de la mitad de los adultos con esquizofrenia experimentan síntomas psicóticos persistentes durante un periodo que ronda los diez años, lo que concuerda con la descripción de la duración típica de la enfermedad en el DSM‑5; la cifra de casi diez años es coherente con la media de 8‑12 años de curso de la esquizofrenia reportada en estudios longitudinales. Las demás alternativas se basan en datos que no están respaldados por los estudios citados: la opción B describe un patrón de respuesta negativa que no corresponde a la trayectoria clínica típica de la esquizofrenia, donde la mayoría de los pacientes presentan una fase de empeoramiento seguida de estabilización, pero no con la proporción ni la secuencia exacta propuesta; la opción C presenta un porcentaje y una evolución de síntomas que no se encuentran en la literatura de Austin y colaboradores (2015), pues ese estudio no reporta un 15 % con ese patrón; y la opción D confunde los criterios de trastorno psicótico breve con los de trastorno esquizofrénico, pues el DSM‑5 no exige remisión completa ni un retorno parcial al nivel premórbido en un mes para ese diagnóstico.'),
  (78, 'El límite de 400 mg de cafeína diaria se establece como la dosis máxima tolerable en adultos sanos porque estudios epidemiológicos y de toxicología han demostrado que, por encima de esta cantidad, la probabilidad de efectos adversos—tales como insomnio, taquicardia, ansiedad y alteraciones gastrointestinales—se incrementa de forma significativa, sin que se observe un beneficio clínico adicional; además, la farmacocinética de la cafeína indica que su eliminación (t½ ≈ 5 h) permite que, con una ingesta de 400 mg, los niveles plasmáticos se mantengan dentro de rangos seguros durante la mayor parte del día, mientras que dosis mayores pueden acumularse y provocar toxicidad. Las opciones A y B subestiman la tolerancia individual y la evidencia clínica, pues 100 mg y 300 mg se consideran seguros y a menudo se emplean como dosis de referencia en estudios de rendimiento cognitivo; la opción D sobrepasa ampliamente el rango de tolerancia, pues 1 000 mg excede el límite de seguridad establecido por organismos como la FDA y la EFSA, y se asocia con síntomas de sobredosis.'),
  (79, 'El DSM‑5 especifica que el trastorno disfórico premenstrual debe estar respaldado por evaluaciones diarias prospectivas durante al menos dos ciclos sintomáticos, pues solo la recogida prospectiva permite diferenciar los síntomas del síndrome premenstrual de los de otras afecciones y garantiza la temporalidad y la intensidad de los mismos; la opción A refleja exactamente ese requisito, mientras que la B excede el número mínimo exigido, la C emplea una metodología retrospectiva que no cumple con el estándar de evidencia prospectiva, y la D combina una metodología inapropiada con un número de ciclos superfluo.'),
  (80, 'El cuadro clínico descrito—sensación de dilatación temporal, anestesia, episodios de parálisis y amnesia que desaparecen en menos de un mes tras un suceso estresante—es característico de una reacción disociativa aguda, ya que la disociación se manifiesta como alteraciones de la percepción del tiempo, de la conciencia corporal y de la memoria, y su duración típica es inferior a 48 h, aunque puede prolongarse hasta un mes; la presencia de parálisis y amnesia apunta a una disociación más profunda que la simple despersonalización, y la rapidez de resolución excluye trastornos crónicos. Las otras opciones son incorrectas: el trastorno de síntomas somáticos (A) se centra en síntomas físicos sin una causa fisiológica clara y suele persistir más allá de un mes; el trastorno adaptativo con síntomas mixtos (B) implica síntomas de ansiedad o depresión sin disociación y su curso es más prolongado; el trastorno de estrés agudo (D) comparte la exposición a un evento traumático pero se caracteriza por síntomas de ansiedad, reexperimentación y evitación, sin la predominancia de disociación que se observa aquí.'),
  (81, 'En el DSM‑5 el trastorno depresivo mayor con características melancólicas se define por la presencia de anhedonia, es decir, la incapacidad de experimentar placer ante estímulos que normalmente serían gratificantes, y por la falta de reactividad a eventos positivos; estos criterios son los que distinguen la forma melancólica del trastorno depresivo mayor y se reflejan en la opción A, por lo que la respuesta indicada es la que señala la anhedonia. Las demás opciones son incorrectas: la opción B describe una variación estacional típica del trastorno depresivo estacional, no del sub‑tipo melancólico; la opción C se refiere a la circadianidad del estado de ánimo, un patrón que puede observarse en varios tipos de depresión pero no es un criterio distintivo de la melancolía; y la opción D alude a un patrón interpersonal de sensibilidad o rechazo, que no forma parte de los criterios diagnósticos del DSM‑5 para el trastorno depresivo mayor con características melancólicas.'),
  (82, 'Las sincinesias se definen como movimientos involuntarios que aparecen como acompañantes de un movimiento voluntario, típicamente en trastornos del movimiento como la enfermedad de Parkinson o en el uso de ciertos fármacos; por tanto la opción A describe fielmente su manifestación clínica, pues el término deriva de la combinación de “sin” (sin) y “cinesia” (movimiento) y se refiere a la aparición de movimientos parásitos o accesorios que se generan en respuesta a un movimiento voluntario, lo que explica su etiología neurofisiológica relacionada con la disfunción de los circuitos basal ganglia y la alteración de la transmisión dopaminérgica. Las demás alternativas son erróneas: la B describe efectos iatrogénicos generales sin especificar la característica de ser movimientos parásitos; la C se refiere a movimientos espasmódicos breves, que corresponden a tics o mioclonías, no a sincinesias; y la D alude a contracciones sostenidas, típica de espasmos musculares o distonías, pero no a la relación parásita con un movimiento voluntario.'),
  (83, 'Las alucinaciones olfativas se asocian con la activación de la corteza olfativa y estructuras límbicas, y su aparición más frecuente se observa en la epilepsia, especialmente en las crisis de tipo temporal mesial, donde la disfunción de la amígdala y el hipocampo produce experiencias sensoriales vívidas y a menudo desagradables; en contraste, el delirium suele caracterizarse por alucinaciones visuales y auditivas, la manía por alucinaciones auditivas o visuales en casos de psicosis, y la alucinosis alcohólica por alucinaciones auditivas o visuales, sin un predominio olfativo. Por lo tanto, la opción C es la que mejor describe la frecuencia clínica de las alucinaciones olfativas.'),
  (84, 'El enunciado que afirma que en el trastorno neurocognitivo frontotemporal mayor o leve la supervivencia es mayor y el declive más lento que en la enfermedad de Alzheimer típica es falso porque, aunque la progresión clínica puede variar, la literatura indica que la supervivencia media en el frontotemporal suele ser comparable o incluso inferior a la de la Alzheimer, especialmente en los subtipos de PPA y FTD de comportamiento, donde la pérdida funcional y la mortalidad pueden ocurrir con mayor rapidez; por tanto, la opción C no refleja la realidad epidemiológica. La alternativa A es verdadera pues los déficits subcorticales vasculares pueden presentarse con un curso lentamente progresivo que imita la Alzheimer; la B es correcta al señalar que los déficits de función ejecutiva y lenguaje con inicio insidioso y progresión gradual son típicos del frontotemporal y no de la vascular; la D es correcta al describir la distinción entre delirium por abstinencia y síndrome de abstinencia cuando predominan alteraciones de atención y cognición.'),
  (85, 'La opción C es falsa porque la incapacidad para enfocar y mover los ojos correctamente no constituye una señal típica de la enfermedad de Parkinson; los síntomas oculares característicos de esta patología son la miosis, la dificultad para iniciar el movimiento ocular (saccades) y la reducción de la velocidad de los movimientos oculares, pero no una pérdida de la capacidad de enfocar o de mover los ojos de forma generalizada, que se observa más en trastornos neurológicos como la esclerosis múltiple o la enfermedad de Huntington. En cambio, la opción A describe correctamente el perfil clínico del trastorno neurocognitivo frontotemporal, donde los cambios conductuales y los déficits del lenguaje son predominantes; la opción B es coherente con el trastorno neurocognitivo con cuerpos de Lewy, que se caracteriza por alucinaciones visuales recurrentes y parkinsonismo espontáneo; y la opción D refleja la realidad clínica del delirium, donde la mayoría de los casos se resuelven con o sin tratamiento, y la intervención temprana suele acortar su duración.'),
  (86, 'En el manejo de los trastornos neurocognitivos, la evidencia clínica y las guías de práctica indican que el empleo de antipsicóticos en pacientes con demencia conlleva un riesgo elevado de efectos adversos, especialmente de sedación, hipotensión, síndrome neuroleptico maligno y muerte súbita, por lo que su uso debe limitarse a situaciones de riesgo inmediato y bajo estrecha monitorización; la opción A recoge este riesgo de forma precisa, mientras que la opción B es incorrecta porque los inhibidores de la acetilcolinesterasa se reservan para la fase leve a moderada, no avanzada, donde la memantina (opción C) es la terapia de elección; la opción C es errónea al invertir las indicaciones de los fármacos, pues la memantina se emplea en la etapa moderada a avanzada, no en la leve; y la opción D es falsa porque los antipsicóticos no están especialmente indicados en la demencia por cuerpos de Lewy, donde se prefieren tratamientos no farmacológicos y se debe evitar su uso por el riesgo de empeorar la agitación y la agitación.'),
  (87, 'La demencia vascular se caracteriza por un deterioro cognitivo que se manifiesta de forma fluctuante, con episodios de empeoramiento agudo (brotes) que luego progresan a un declive más estable; este patrón se explica por la naturaleza de los accidentes cerebrovasculares que afectan regiones cerebrales de manera intermitente y acumulativa, lo que produce deterioro progresivo a medida que se acumulan lesiones. En contraste, la demencia cortical típica (por ejemplo, Alzheimer) presenta un curso más lineal y gradual sin brotes, y el déficit más marcado en la demencia vascular suele ser el ejecutivo y la atención, no la memoria episódica, que se conserva relativamente mejor en etapas tempranas; por ello la opción C es errónea. La afirmación de que la demencia vascular es el prototipo de demencia cortical (opción B) es incorrecta porque se trata de una demencia subcortical, con lesiones en la sustancia blanca y los vasos cerebrales, no de una lesión cortical primaria. Finalmente, los criterios de VASCOG y NINDS-AIREN difieren en la necesidad de dos o más dominios cognitivos afectados, pero ninguno exige que la memoria sea uno de ellos; por lo tanto, la opción D también es falsa.'),
  (88, 'La ecognición se define como la distorsión de la percepción del propio pasado, de modo que los recuerdos se experimentan como si fueran vivencias actuales; por eso la opción A describe fielmente el fenómeno, pues implica una reexperiencia temporal del recuerdo con la intensidad y la sensación de presente, característica de la ecognición. Las demás alternativas no concuerdan con la definición: la B describe un falso reconocimiento de identidad (confusión de familiar con desconocido), la C corresponde a un falso reconocimiento de novedad (creer que una situación es nueva cuando no lo es), y la D se refiere a la creación de recuerdos imaginarios o ideas originales, no a la reexperiencia de recuerdos pasados; todas comparten el error de confundir el tipo de distorsión (falso reconocimiento o creación de recuerdos) con la ecognición.'),
  (89, 'La opción A corresponde a la pseudoalucinación, que se caracteriza por la presencia de una imagen perceptiva que el individuo reconoce como falsa o imaginaria, pero que carece de la convicción de que exista en el mundo exterior; el paciente percibe la imagen como propia, sin atribuirla a un estímulo externo real, lo que explica la escasa o nula sensación de realidad “exterior”. En contraste, la alucinación funcional (B) implica una percepción que el paciente interpreta como real y que parece provenir de una fuente externa, aunque sea falsa, por lo que sí mantiene una convicción de realidad; la imagen alucinante (C) es una manifestación de la alucinación en la que la imagen se percibe como real y con contenido significativo, y la imagen refleja (D) se refiere a la percepción de una imagen que el sujeto reconoce como una proyección o reflejo de su propio entorno, manteniendo la sensación de realidad. Por tanto, las alternativas B, C y D describen modalidades en las que la convicción de realidad no es nula, a diferencia de la pseudoalucinación.'),
  (90, 'La afirmación falsa es la d) porque la literatura clínica y epidemiológica muestra que la prematuridad, especialmente la prematuridad muy temprana (menos de 32 semanas de gestación), se asocia con un mayor riesgo de trastornos de la conducta alimentaria, incluida la bulimia nerviosa, posiblemente por la alteración temprana de los sistemas neurobiológicos de regulación del apetito y la impulsividad; por tanto, no se puede afirmar que no exista riesgo alguno. En contraste, la opción a) es coherente con estudios que identifican desviaciones tempranas de peso, ya sea sobrepeso o bajo peso, como indicadores de riesgo de BN, pues reflejan alteraciones metabólicas y de la percepción corporal que predisponen al desarrollo del trastorno. La opción b) es válida porque el rasgo de evitación del daño, caracterizado por la tendencia a evitar experiencias potencialmente negativas, se ha asociado con la BN, pues la conducta compensatoria (vomito, uso de laxantes) puede interpretarse como una estrategia para evitar el daño percibido de la ingesta excesiva. Finalmente, la opción c) es correcta, pues la BN se caracteriza por una marcada dificultad para tolerar y regular emociones intensas, incluidas las positivas, lo que contribuye a la recurrencia de episodios de ingesta descontrolada y de conductas compensatorias.'),
  (91, 'La laguna temporal se refiere a la pérdida transitoria de la capacidad de prestar atención a la información que se está procesando en el momento, fenómeno que suele aparecer durante la ejecución de tareas que demandan un alto nivel de automatismo o que se realizan en un contexto de alta carga cognitiva; por ello la opción C describe con precisión la naturaleza de la alteración, ya que la laguna se manifiesta como una interrupción momentánea de la atención que no implica pérdida de memoria ni de orientación, sino una desconexión temporal del flujo de información. Las demás alternativas son inexactas: la A confunde la laguna con la amnesia selectiva, que implica pérdida de recuerdos específicos; la B describe una alteración de la orientación temporal, pero la laguna no afecta la orientación espacial ni personal; y la D se refiere a una alteración de la conciencia con descenso del estado de alerta, lo cual corresponde a la somnolencia o al sueño, no a la laguna temporal.'),
  (92, 'La atmósfera delirante se refiere a la experiencia subjetiva de que el entorno ha cambiado de manera fundamental, lo que constituye una idea delirante primaria; la persona percibe que el mundo entero se ha transformado, no solo interpreta una situación específica, por lo que la opción B describe correctamente este fenómeno, pues la atmósfera delirante implica una alteración global del significado del mundo que no depende de una idea secundaria. Las demás alternativas son inexactas: la A describe una idea delirante secundaria, que depende de una idea primaria y no implica un cambio global del entorno; la C también se refiere a una idea secundaria, pues la persona varía interpretaciones de percepciones ya existentes, y la D se refiere a una idea primaria, pero asociada a la reconstrucción de recuerdos, no a la percepción de un cambio ambiental.'),
  (93, 'Las contracciones incontrolables, violentas y difusas de la musculatura voluntaria se denominan convulsiones, ya que reflejan una actividad eléctrica anómala del sistema nervioso central que produce movimientos musculares bruscos y descoordinados; los tics, por otro lado, son movimientos breves, repetitivos y de corta duración que suelen ser conscientes y pueden ser parcialmente suprimidos, los automatismos implican conductas sin conciencia que se ejecutan de manera automática, y la acatisia se caracteriza por una sensación de inquietud interna que provoca movimientos repetitivos y de desplazamiento, pero sin la intensidad y la falta de control que se observa en las convulsiones.'),
  (94, 'El DSM‑5 establece que el trastorno de ansiedad por separación requiere que los síntomas persistan durante al menos seis meses en adultos, mientras que en niños la duración mínima es de cuatro meses; por lo tanto la opción que indica que los síntomas deben estar presentes al menos seis meses en adultos es la única que se ajusta a los criterios diagnósticos, pues respeta la diferencia de duración entre poblaciones; las demás alternativas son erróneas porque confunden los periodos de tiempo requeridos: la A propone cuatro meses para ambos grupos, lo que omite la mayor exigencia de duración en adultos; la B fija seis meses para niños, excediendo el mínimo estipulado; y la C reduce la duración a cuatro semanas, lo cual es insuficiente para cualquier grupo según el manual.'),
  (95, 'El modelo integrador cognitivo de Casey, Oei y Newcombe (2004) destaca la autoeficacia como factor central porque sostiene que la percepción de control propio sobre los síntomas de pánico y la confianza en la capacidad de manejar el episodio determinan la intensidad y la frecuencia de los ataques; la autoeficacia se modela a partir de la experiencia de éxito o fracaso en la gestión de las sensaciones físicas, lo que explica la variabilidad individual en la gravedad del trastorno. En contraste, el modelo cognitivo de Clark (1986) se centra en la interpretación de las sensaciones interoceptivas y la atención dirigida a ellas, sin enfatizar la autoeficacia; el modelo integrador de Barlow (Barlow y Durand, 2003) incorpora factores de aprendizaje y cognición, pero la autoeficacia no es su eje principal; y el modelo de aprendizaje interoceptivo de Wolpe y Rowan (1988) se basa en la habituación a estímulos interoceptivos, sin considerar la percepción de control personal.'),
  (96, 'En el modelo de Borkovec y colaboradores la preocupación se conceptualiza como un proceso de pensamiento repetitivo que, paradójicamente, se mantiene porque la persona percibe que la anticipación de eventos negativos reduce la ansiedad y la activación fisiológica asociada a las imágenes mentales negativas; la preocupación actúa como una estrategia de control que, aunque no elimina la ansiedad, la mitiga al ofrecer una sensación de preparación y dominio sobre la amenaza, lo que explica por qué el individuo continúa preocupándose. Las demás opciones son incorrectas: la opción B confunde los tipos de creencias, pues las creencias negativas sobre la preocupación no son las que activan las preocupaciones tipo 2, sino que la preocupación en sí misma se basa en la creencia de que la anticipación es útil; la opción C atribuye la aprensión ansiosa como origen de la preocupación, cuando en realidad la preocupación es el mecanismo de respuesta a la aprensión, no su causa; y la opción D mezcla la intolerancia a la incertidumbre con la evitación cognitiva, aunque la intolerancia a la incertidumbre sí activa la cadena de preocupación, la evitación cognitiva no es parte directa del modelo de Borkovec.'),
  (97, 'El trastorno bipolar I se caracteriza por la presencia de al menos un episodio maníaco, y la edad de inicio puede variar ampliamente, desde la adolescencia hasta la tercera edad, por lo que la afirmación que indica que el comienzo se limita a los primeros años de la edad adulta es incorrecta; la literatura clínica muestra que el inicio puede ocurrir en cualquier etapa del ciclo vital, lo que sustenta la opción B como la única afirmación que refleja la realidad epidemiológica y clínica del trastorno. La opción A es errónea porque restringe el inicio a la adultez temprana, ignorando casos de inicio en la adolescencia o en la adultez tardía. La opción C es falsa porque la proporción de episodios maníacos que preceden inmediatamente a un episodio depresivo mayor es mucho mayor que el 30 %, y la opción D es incorrecta porque el especificador de ciclos rápidos se aplica cuando se presentan cuatro o más episodios en un año, no tres.'),
  (98, 'El DSM‑5 clasifica la presencia de síntomas somáticos acompañados de pensamientos desproporcionados y persistentes sobre la gravedad de dichos síntomas, junto con una ansiedad elevada y persistente sobre la salud, como Trastorno de síntomas somáticos; la característica definitoria es la preocupación excesiva que no se explica por una enfermedad médica conocida y que provoca alteraciones significativas en la vida diaria, lo que coincide con la descripción de la opción A. La alternativa B, el Trastorno de ansiedad por la enfermedad, se reserva para casos en los que la preocupación se centra en la posibilidad de padecer una enfermedad grave, pero el diagnóstico requiere que la ansiedad sea la causa principal, no simplemente la presencia de síntomas somáticos; en la pregunta la ansiedad es secundaria a los síntomas, por lo que no se ajusta. La opción C, Hipocondría, corresponde a una preocupación crónica y persistente por la idea de estar enfermo, sin la presencia de síntomas somáticos reales, lo cual difiere de la situación planteada. Finalmente, la opción D, Trastorno de pánico, se caracteriza por ataques de pánico recurrentes y miedo anticipatorio, sin relación directa con la interpretación de síntomas somáticos, por lo que tampoco es pertinente.'),
  (99, 'La CIE‑11 define la disforia por integridad corporal como un trastorno en el que el individuo experimenta un deseo intenso y persistente de perder una parte del cuerpo, generalmente una extremidad, con la convicción de que su identidad se ajustaría mejor a esa discapacidad; por ello la opción B resume la característica principal al referirse al deseo de una discapacidad física importante, que constituye el núcleo diagnóstico de este trastorno. Las demás alternativas son incorrectas: la A describe un malestar corporal sin la especificación de la pérdida deseada, lo que corresponde más a un trastorno de somatización; la C se refiere a despersonalización, típica de trastornos disociativos, y la D al miedo de disgregación, que se asocia con trastornos de ansiedad o somatomorfos, pero no con la disforia por integridad corporal.'),
  (100, 'El trastorno facticio aplicado a otros, según el DSM‑5, se clasifica dentro de los trastornos de síntomas somáticos y se caracteriza por la falsificación de signos o síntomas físicos o psicológicos en otra persona con la intención de engañar, sin que exista una recompensa externa evidente; por ello la opción A es coherente con la clasificación, la B describe adecuadamente el proceso de engaño y la D señala la ausencia de incentivos externos, lo cual es una característica definitoria del trastorno, mientras que la C es errónea porque el diagnóstico se asigna únicamente al autor del engaño, no a la víctima, pues la víctima no presenta intención de falsificar su propio estado, sino que es objeto del engaño.'),
  (101, 'La afirmación falsa es la d) porque las alucinaciones negativas se caracterizan por la ausencia de una experiencia perceptiva, no por la percepción de un objeto inexistente; el sujeto no “percibe” nada y, por tanto, no puede comportarse como si un objeto estuviera presente cuando no lo está. En contraste, la opción a) es verdadera: las pseudoalucinaciones son experiencias subjetivas que el paciente reconoce como internas y no externas, situándose dentro del propio mundo interno. La opción b) también es correcta: en las alucinaciones funcionales la percepción se produce como respuesta a un estímulo externo real y la alucinación cesa cuando dicho estímulo desaparece, evidenciando una relación causal directa. Finalmente, la opción c) es cierta, pues las alucinaciones funcionales, como las auditivas o visuales que responden a estímulos externos, se observan con frecuencia en la esquizofrenia, donde la integración sensorial está alterada. Así, solo la d) presenta un error conceptual al atribuir a las alucinaciones negativas la percepción de un objeto inexistente.'),
  (102, 'El DSM‑5 indica que la evaluación de la deficiencia en el trastorno de deseo sexual hipoactivo en el varón debe ser realizada por el clínico, pues la falta de deseo se debe a factores fisiológicos o psicológicos que no se pueden determinar con un cuestionario estándar; por tanto, el profesional debe valorar la historia clínica, los antecedentes médicos y los aspectos psicológicos para confirmar la presencia de una deficiencia real y no una variación normal del deseo; las otras opciones no incluyen esa especificación: el trastorno del interés/excitación sexual femenino y la eyaculación prematura se evalúan mediante criterios clínicos y pruebas específicas, pero el DSM no señala que la evaluación la haga exclusivamente el clínico; la eyaculación retardada se diagnostica con criterios de duración y disfunción, sin requerir una valoración exclusiva del profesional.'),
  (103, 'El trastorno del lenguaje no fluente con buena repetición es típico de la afasia transcortical motora, donde la lesión afecta el área frontal de Broca y sus conexiones, pero la vía de repetición (cortico‑cortical) permanece intacta, permitiendo la repetición de palabras y frases; la producción espontánea se ve severamente comprometida por la disfunción del circuito frontal‑subcortical. En contraste, la afasia de Broca presenta tanto disfluencia como pobre repetición, la afasia de conducción se caracteriza por errores de sustitución y buena repetición pero con disfluencia leve, y la afasia de Wernicke muestra fluidez y repetición preservada pero con pérdida de comprensión, por lo que las opciones A, B y D no describen la combinación específica de disfluencia con buena repetición que distingue a la afasia transcortical motora.'),
  (104, 'El factor mantenedor de los trastornos de la conducta alimentaria según Fairburn y colaboradores (2003) es el aislamiento social (opción C), pues la retirada de la interacción interpersonal refuerza la percepción de control que la persona intenta mantener a través de la restricción alimentaria y la preocupación por el peso, perpetuando el ciclo de disfunción; la pérdida o separación (A) y las críticas sobre el cuerpo (B) son desencadenantes o precipitantes, no factores que sostienen el trastorno a largo plazo, mientras que la enfermedad adelgazante (D) se refiere a una condición física que puede coexistir con el trastorno pero no constituye un factor mantenedor según la teoría de Fairburn.'),
  (105, 'La teoría de los estilos de respuesta de Nolen‑Hoeksema sostiene que la rumiación, entendida como la repetición persistente de pensamientos negativos sobre el origen, la gravedad y las consecuencias de los síntomas, prolonga y intensifica la depresión; por ello la opción B describe el mecanismo que explica el agravamiento de la sintomatología, mientras que las demás alternativas no se ajustan a la hipótesis de la teoría: la evasión (A) y la distracción (C) son estrategias de afrontamiento que, aunque pueden reducir la intensidad momentánea, no generan un prolongado empeoramiento de la depresión; la atribución fatalista (D) se relaciona con la percepción de falta de control, pero no constituye el estilo de respuesta rumiativo que la teoría identifica como el factor de riesgo principal.'),
  (106, 'El modelo de Barlow (1986) postula que la disfunción eréctil se debe a una tendencia a distraerse de las claves eróticas cuando se presentan estímulos que implican una demanda de rendimiento sexual; por ello, la opción B es la única que no corresponde a sus ideas principales, ya que B afirma que personas funcionales y disfuncionales reaccionan de igual manera a los distractores cuando son estímulos sexuales, lo cual contradice la premisa de que los disfuncionales son más susceptibles a la distracción bajo presión. Las demás alternativas se alinean con el modelo: la A describe cómo los distractores neutros reducen la activación en disfuncionales; la C explica la distracción de las claves eróticas por demandas de rendimiento; y la D señala que en personas sin disfunción la activación sexual se facilita con estímulos sexuales que implican demanda de rendimiento.'),
  (107, 'La opción D es la que se ajusta a la clasificación del DSM‑5 porque la disforia de género se define por el malestar persistente y la incongruencia entre la identidad de género y el sexo asignado, no por la mera presencia de conductas sexuales atípicas; dichas conductas pueden estar asociadas a otros trastornos, como trastornos de la conducta sexual o trastornos de la identidad, pero no constituyen automáticamente indicios de disforia de género, por lo que su interpretación aislada sería errónea. Las alternativas A y B se basan en conceptos desactualizados: el DSM‑5 ya no utiliza el término “trastorno somático del desarrollo sexual” ni considera la disforia de género como una forma de intersexualidad del sistema nervioso central, y la afirmación de que la correlación con la producción prenatal de andrógenos es alta carece de respaldo empírico. La opción C es incorrecta porque la evidencia indica que la preocupación por el cambio de sexo suele manifestarse a partir de los 12‑13 años, no a los 6 años, y la edad temprana no es un criterio diagnóstico.'),
  (108, 'La afirmación falsa es la D; la edad de aparición de los ataques de pánico sí resulta útil para diferenciar las hipótesis etiológicas, pues la aparición temprana (pre‑adolescencia) se asocia con mayor probabilidad de comorbilidad con trastornos de ansiedad y trastornos del espectro autista, mientras que la aparición tardía suele indicar mayor riesgo de trastornos somatomorfos o de ansiedad social, lo que permite orientar la evaluación y el tratamiento; las opciones A y B son verdaderas porque el hiperparatiroidismo puede provocar hipercalcemia y síntomas de ansiedad, y los niveles de calcio se emplean clínicamente para descartar causas médicas; la opción C es cierta ya que la presencia de ataques de pánico aumenta la probabilidad de desarrollar trastorno bipolar, especialmente en la fase de síntomas mixtos o de ansiedad comórbida.'),
  (109, 'El DSM‑5 clasifica al trastorno del sadismo sexual como un trastorno algolágnico porque implica la obtención de placer sexual a partir de la inflictión de dolor o sufrimiento a otra persona, lo que constituye una forma de excitación que depende del dolor; la característica definitoria de la algolágnia es la búsqueda de placer a través del dolor, y el sadismo sexual encaja exactamente en esta categoría al requerir la presencia de dolor o humillación para la estimulación sexual. En contraste, el trastorno de síntomas somáticos con predominio de dolor se centra en la percepción de dolor físico sin relación con la excitación sexual, el trastorno de dolor génito‑pélvico se refiere a dolor físico en la zona genital sin componente de placer sexual, y el trastorno facticio implica la fabricación de síntomas sin motivación sexual, por lo que ninguno de estos comparte la característica de búsqueda de placer mediante el dolor.'),
  (110, 'La opción d) es la única que concuerda con la clasificación DSM‑5 y la literatura clínica: en la fobia específica los ataques de pánico son, cuando aparecen, menos frecuentes y de menor intensidad que en el trastorno de pánico, aunque comparten los mismos síntomas fisiológicos y cognitivos; la diferencia radica en la frecuencia y gravedad, no en la cualidad de los episodios. La alternativa a) es incorrecta porque los ataques de pánico en fobia específica no son cualitativamente distintos, sino que simplemente son menos recurrentes y menos severos; la b) es errónea porque la fobia específica se caracteriza por temor a un solo objeto o situación, pero los ataques de pánico no son “inesperados” ni frecuentes, y la c) es falsa porque no todas las fobias específicas generan el mismo patrón cardiovascular; la respuesta fisiológica varía según el estímulo y la respuesta individual.'),
  (111, 'El DSM‑5 describe al trastorno dismórfico corporal (TDC) como una condición en la que la preocupación por defectos percibidos en la apariencia física es excesiva, produce angustia severa y afecta el funcionamiento social, laboral y académico; esta presentación se observa con igual frecuencia en ambos sexos, por lo que la opción D refleja la realidad clínica y la literatura que indica que las manifestaciones, la gravedad y la comorbilidad con trastornos de ansiedad, depresión y trastornos obsesivo‑compulsivos son prácticamente indistinguibles entre hombres y mujeres, aunque la expresión de la dismorfia puede variar en cuanto a los objetos de preocupación (por ejemplo, la musculatura en hombres y la figura corporal en mujeres). Las demás alternativas se desvían de la evidencia: la opción A es incorrecta porque la comorbilidad más frecuente del TDC se registra con trastornos de ansiedad y depresión, no con trastornos alimentarios; la opción B es errónea al negar la evidencia de factores biológicos (genéticos, neuroquímicos) que contribuyen al TDC; y la opción C es inexacta porque la dismorfia muscular es más típica en hombres, mientras que en mujeres predominan preocupaciones por la figura corporal o la piel.'),
  (112, 'La cleptomanía, clasificada como trastorno de control de impulsos, se presenta con mayor frecuencia en el contexto de trastornos afectivos, especialmente el trastorno depresivo mayor y el trastorno bipolar, donde la alteración del estado de ánimo y la impulsividad son componentes centrales; además, la comorbilidad con trastornos de la conducta alimentaria es frecuente debido a la presencia de impulsividad y la búsqueda de control sobre el comportamiento, lo que facilita la aparición de patrones de alimentación disfuncionales. En contraste, el trastorno esquizofrénico se caracteriza por síntomas psicóticos (delirios, alucinaciones) y deterioro cognitivo que no favorecen la manifestación de conductas impulsivas específicas como la robos compulsivos; la evidencia clínica y epidemiológica muestra una relación mucho más débil entre la esquizofrenia y la cleptomanía, lo que explica por qué es el trastorno menos comórbido. Las demás opciones comparten la misma razón de error: todas están asociadas a una mayor comorbilidad con la cleptomanía, ya sea por la presencia de impulsividad o por la afectación de los sistemas de control del impulso.'),
  (113, 'La distorsión descrita corresponde a la “Juego de culpa”, en la que el individuo atribuye a su propio aspecto físico la responsabilidad de eventos negativos que no controlaba, generando un sentimiento de culpa y auto‑castigo; esta es la única opción que refleja la lógica de causalidad interna y auto‑culpabilización típica de la “docena sucia”. Las demás alternativas, aunque evocan conceptos relacionados con la imagen corporal, no describen la inferencia de causalidad interna: “El espejo malhumorado” se refiere a la percepción distorsionada del propio cuerpo, “Expansión de la fealdad” al magnificar la percepción de imperfección y “La atadura de la belleza” al idealizar la perfección estética; todas comparten la falta de la atribución de culpa por el aspecto físico.'),
  (114, 'La especificación “en remisión total” en el DSM‑5 para un trastorno depresivo se define como la ausencia de signos o síntomas significativos del trastorno durante al menos dos meses, lo que permite diferenciarla de la remisión parcial o de la fase de recuperación en la que pueden persistir síntomas leves; esta duración se estableció para asegurar que la mejora sea sostenida y no refleje simplemente la fluctuación típica de la depresión, y se corresponde con el criterio de remisión de otros trastornos del estado de ánimo. Las demás opciones son incorrectas: la alternativa A (un año) excede la duración mínima exigida y se asemeja más a la definición de remisión prolongada de ciertos trastornos, mientras que las alternativas B (cuatro meses) y D (seis meses) tampoco cumplen con el periodo mínimo de dos meses establecido por el DSM‑5 y podrían confundir la evaluación clínica con criterios de remisión parcial o de recuperación tardía.'),
  (115, 'La opción B es la única que se ajusta a la fisiopatología de los terrores nocturnos: el episodio se inicia de forma súbita, con un aumento abrupto de la actividad autonómica (frecuencia cardíaca, respiración, sudoración) sin fase de transición ni signos de anticipación, reflejo de un despertar parcial del sueño NO‑REM que se produce de manera abrupta y con una respuesta fisiológica intensa; en contraste, la inestabilidad del sueño profundo NO‑REM (A) no es específica ni suficientemente fiable para diferenciar el sonambulismo, ya que la polisomnografía muestra variabilidad en la fase N3 en muchos trastornos del sueño; la afirmación de que los trastornos del despertar NO‑REM se presentan con mayor frecuencia durante el sueño de ondas rápidas (C) es incorrecta, pues los terrores y el sonambulismo ocurren predominantemente en la fase N3, no en REM; y la idea de que existen indicadores polisomnográficos fiables para predecir terrores nocturnos en registros fuera del episodio (D) carece de evidencia, pues la polisomnografía sin episodio no muestra patrones predictivos concluyentes.'),
  (116, 'El enunciado D es el que se ajusta a la evidencia clínica: los terrores nocturnos son más frecuentes en varones durante la infancia, pero la diferencia de género se nivela en la adultez, reflejando la disminución de la incidencia con la madurez. La opción A describe un patrón de despertares con ansiedad que se observa más en pesadillas que en terrores nocturnos, donde el paciente suele permanecer inconsciente y no recuerda el episodio. La alternativa B confunde la prevalencia de episodios aislados con la prevalencia del trastorno; la cifra de 0,5 % corresponde a la prevalencia de trastorno de terrores nocturnos, no a episodios aislados. Finalmente, la opción C es errónea porque los estudios de gemelos sí han identificado un componente genético moderado en la etiología de los terrores nocturnos, lo que contradice la afirmación de ausencia de herencia.'),
  (117, 'El inicio de la hipersomnia se observa con mayor frecuencia en la adolescencia y en los primeros años de la vida adulta porque en esta etapa el cerebro atraviesa procesos de maduración y consolidación de los ritmos circadianos, y la exposición a factores psicosociales como la presión académica, el uso de dispositivos electrónicos y la alteración de los patrones de sueño favorece la aparición de somnolencia excesiva; además, la literatura clínica indica que la prevalencia de trastornos de sueño con síntomas hipersomníficos aumenta en este rango etario, lo que sustenta la opción A, mientras que la opción B se refiere a la edad avanzada, donde la hipersomnia suele asociarse a enfermedades neurodegenerativas o trastornos del sueño específicos, no a su inicio; la opción C es demasiado amplia y no refleja la distribución epidemiológica real; y la opción D, que señala la primera infancia, corresponde a trastornos como la narcolepsia infantil o el trastorno del sueño en la infancia, pero no es la etapa típica de aparición de la hipersomnia en la población general.'),
  (118, 'La Escala de Epworth (ESS) es una medida de la somnolencia diurna subjetiva, evaluando la probabilidad de quedarse dormido en ocho situaciones cotidianas; por ello la opción B describe con precisión su función clínica, ya que la ESS cuantifica la tendencia a la somnolencia durante el día, lo que es esencial para diagnosticar trastornos como la apnea obstructiva del sueño o la narcolepsia. Las demás alternativas son incorrectas: la opción A confunde la ESS con instrumentos de insomnio (por ejemplo, la escala de insomnio de Pittsburgh), la opción C se refiere a la intensidad del ronquido, que no se mide con la ESS, y la opción D implica la detección de trastornos del sueño REM, lo cual requiere estudios de polisomnografía, no la escala de somnolencia.'),
  (119, 'El trastorno de voyeurismo se clasifica como una parafilia que implica la observación de personas desnudas, parcialmente desnudas o en actos de actividad sexual, con la finalidad de obtener excitación sexual; la normativa diagnóstica del DSM‑5 y la ICD‑11 establecen que la conducta debe ser realizada por un individuo mayor de edad, pues la ley considera que la capacidad de consentimiento y la responsabilidad legal están vinculadas a la mayoría; en contraste, el trastorno de pedofilia se refiere a la atracción sexual hacia niños prepubescentes y, por su naturaleza, no requiere que el sujeto sea mayor de edad; el trastorno de exhibicionismo y el de fetichismo pueden presentarse en adolescentes y, aunque la edad influye en la gravedad y la intervención, la normativa no los condiciona a la mayoría; por tanto, solo el voyeurismo exige la mayoría, mientras que las demás opciones no lo hacen.'),
  (120, 'El trastorno psicótico breve o agudo y transitorio, según el DSM‑5, constituye aproximadamente el 9 % de los primeros episodios de psicosis, y su incidencia es mayor en mujeres, lo que explica la opción C; la prevalencia vital se sitúa entre el 0,5 % y el 1,5 %, y la mayor frecuencia se observa en mujeres, no en hombres. Las alternativas A y B son incorrectas porque presentan cifras de prevalencia vital (4,6 % y 0,3 %) que no corresponden a la literatura del DSM‑5 y asignan la mayor incidencia a los hombres en la A, a las mujeres en la B, pero con valores numéricos erróneos. La opción D, aunque menciona la prevalencia correcta (0,5‑1,5 %), falla al indicar la mayor incidencia en hombres, cuando en realidad es mayor en mujeres.'),
  (121, 'El DSM‑5 define la disforia de género en niños como una “insistencia persistente en que el individuo es del género opuesto o de un género alternativo distinto del que se le asignó al nacer, acompañada de un deseo profundo de ser tratado como tal y de una incongruencia marcada con los caracteres sexuales primarios y secundarios”; por ello la opción D resume los criterios esenciales, pues combina la insistencia de identidad, el deseo de ser tratado como el otro género y la discrepancia con los caracteres sexuales, elementos que el manual considera indispensables para el diagnóstico; las demás alternativas se limitan a aspectos parciales (A solo menciona el deseo de poseer caracteres sexuales, B habla de incongruencia sin insistencia en la identidad, C se centra en preferencias y fantasías sin requerir la insistencia diagnóstica), por lo que no cumplen la totalidad de los requisitos del DSM‑5.'),
  (122, 'La opción A es la única que se ajusta a los criterios del DSM‑5 porque la fobia específica tipo situacional se diagnostica cuando la ansiedad se limita a una sola situación o objeto concreto, y la agorafobia requiere que la ansiedad se produzca en dos o más situaciones distintas o en una sola situación que implique dificultad para escapar, y que la persona evite o tolere la situación con gran ansiedad; por lo tanto, si la persona teme únicamente a una situación típicamente agorafóbica, la clasificación debe ser fobia específica situacional y no agorafobia. Las demás alternativas son incorrectas: la B confunde la preocupación por el daño con la agorafobia, que se centra en la dificultad de escapar y la evitación, no en la valoración de riesgo; la C presupone que la presencia de una situación agorafóbica concreta basta para diagnosticar agorafobia, pero el DSM exige múltiples situaciones o una sola con gran dificultad de escape; y la D equivale a la A al afirmar que un estímulo situacional único justifica la agorafobia, cuando en realidad indica fobia específica situacional.'),
  (123, 'La anorexia nerviosa se caracteriza por un peso corporal significativamente bajo, definido clínicamente por un índice de masa corporal (IMC) inferior a 18,5 en adultos; en niños y adolescentes se emplea el percentil del IMC para la edad, y el criterio de diagnóstico exige un percentil inferior al 5 %, pues refleja la gravedad del déficit de peso en relación con la población de referencia, diferenciándose de los percentiles 8 % o 10 % que se utilizan en otras condiciones de bajo peso o en criterios de bajo peso no clínicamente relevantes; las opciones A y C establecen el umbral de IMC en adultos a 18 y 18,5 respectivamente, pero subestiman el nivel de gravedad requerido, mientras que la opción B reduce el umbral en adultos a 17, lo cual es insuficiente para la definición diagnóstica; por tanto, la alternativa D es la única que cumple con los criterios establecidos por la clasificación internacional de trastornos de la conducta alimentaria.'),
  (124, 'En la depresión bipolar, el patrón de episodios alterna entre estados depresivos y maníacos o hipomaníacos, y la presencia de síntomas atípicos (como aumento del apetito, sueño prolongado, sensibilidad al rechazo) es más frecuente que en la depresión unipolar, donde los síntomas atípicos son menos comunes; por tanto la opción D refleja la diferencia clínica más relevante. Las demás alternativas son erróneas: la edad de inicio de la depresión bipolar suele ser similar o incluso menor que la de la unipolar, por lo que la opción A es falsa; el número de episodios en la depresión bipolar tiende a ser mayor, no menor, invalidando la B; y la duración de los episodios depresivos en la depresión bipolar no es sistemáticamente mayor que en la unipolar, lo que descarta la C.'),
  (125, 'El objetivo propio de la terapia dialéctico-conductual (TDC) de Linehan para el trastorno límite de la personalidad es mejorar la eficacia interpersonal, ya que la TDC se centra en la regulación emocional, la tolerancia a la angustia y la mejora de las habilidades interpersonales para reducir la impulsividad y los comportamientos autolesivos; la eficacia interpersonal constituye la base para la integración de las demás competencias de la TDC y se considera un objetivo central del tratamiento. Las demás opciones son incorrectas: la opción B, que menciona cuestionar patrones de pensamiento disfuncional, corresponde más a la terapia cognitivo-conductual; la C, que habla de modificar esquemas tempranos desadaptativos, se relaciona con la terapia basada en esquemas; y la D, buscar la causa del malestar, es un enfoque más exploratorio y no un objetivo específico de la TDC.'),
  (126, 'El tratamiento cognitivo-conductual (TCC) para el trastorno de atracones se ha documentado como eficaz para disminuir la frecuencia de los episodios y mejorar la calidad de vida, pero la evidencia indica que no logra mantener a largo plazo la reducción del peso corporal; los estudios de seguimiento muestran que, a pesar de la mejoría en la conducta alimentaria, la mayoría de los pacientes recupera el peso perdido una vez finalizada la intervención, lo que explica la limitación señalada en la opción A. Las demás alternativas son incorrectas porque la TCC sí logra reducir la frecuencia de los atracones (opción D) y mejora la calidad de vida (opción B), y aunque los síntomas psicopatológicos pueden persistir en algunos casos, la literatura no sostiene que el tratamiento no reduzca estos síntomas (opción C).'),
  (127, 'La técnica que se emplea preferente y específicamente en el tratamiento de la tricotilomanía y la excoriación es la inversión de hábito, pues consiste en identificar los desencadenantes de la conducta compulsiva y sustituirla por una acción incompatible, de modo que el paciente aprende a detener la extracción de piel o cabello y a reemplazarla por una conducta alternativa, lo que reduce la frecuencia y la intensidad del comportamiento. Las otras opciones no se aplican de forma tan directa: la reestructuración cognitiva (A) se centra en modificar pensamientos disfuncionales y suele complementarse con la inversión de hábito, pero no es la estrategia principal; las estrategias para incrementar la motivación (C) son útiles en la fase de compromiso y mantenimiento, pero no abordan la conducta específica; los experimentos conductuales (D) se utilizan para probar hipótesis sobre la relación estímulo‑respuesta, pero no sustituyen la intervención de sustitución de hábito que es la más eficaz en estos trastornos.'),
  (128, 'El objetivo central de la terapia cognitiva en el trastorno obsesivo‑compulsivo es cambiar la forma en que la persona evalúa e interpreta sus pensamientos intrusivos y obsesivos, pues la distorsión cognitiva—la tendencia a sobreestimar la amenaza y a atribuirles un valor excesivamente negativo—es la que mantiene la ansiedad y la compulsión; al reestructurar esas interpretaciones se reduce la necesidad de rituales de alivio, lo que explica por qué la opción B es la que se corresponde con el objetivo terapéutico; la opción A se refiere a una visión general del trastorno, no al proceso de revaluación de los pensamientos; la C, que habla de aceptación, corresponde más a la terapia de aceptación y compromiso, no a la terapia cognitiva clásica; y la D describe la habituación, un proceso que se logra a través de la exposición, no mediante la modificación cognitiva directa.'),
  (129, 'El experimento descrito se centra en la frecuencia de un pensamiento intrusivo (el gato blanco) y en la comparación de su aparición durante un periodo de exposición controlada con su aparición habitual, lo que apunta a la sobrestimación de la importancia que el paciente asigna a ese pensamiento; al registrar y contrastar la frecuencia, se busca evidenciar que el pensamiento no tiene consecuencias reales y que su presencia no implica una amenaza real, lo que reduce la ansiedad asociada. Las opciones A y B se refieren a la fusión cognitivo‑conductual, es decir, la tendencia a tratar los pensamientos como hechos o a actuar en función de ellos, lo cual no se aborda directamente en el experimento; la opción C, la responsabilidad excesiva, implica la creencia de que el individuo debe controlar los pensamientos para evitar consecuencias, algo distinto del objetivo de medir la frecuencia y su impacto percibido.'),
  (130, 'La terapia de aceptación y compromiso (ACT) se centra en la aceptación de experiencias internas y la clarificación de valores, lo que permite al paciente generar un sentido de propósito y trascendencia más allá de los síntomas psicóticos; el proceso de identificación y compromiso con valores personales constituye precisamente el elemento de “sentido trascendental del yo” que se menciona, pues ACT promueve la construcción de una identidad basada en valores y metas que trascienden el trastorno. En contraste, la terapia metacognitiva para la psicosis (A) se orienta a la regulación de procesos cognitivos y metacognitivos sin enfatizar la trascendencia personal; la terapia centrada en la compasión (C) y la terapia cognitiva basada en mindfulness (D) se enfocan en la regulación emocional y la atención plena, respectivamente, pero no incluyen explícitamente la creación de un sentido trascendental del yo como objetivo terapéutico.'),
  (131, 'La intervención que se diseñó específicamente para la prevención de recaídas en la depresión es la terapia cognitiva basada en mindfulness (TCBM), pues incorpora la práctica de la atención plena y la aceptación de los pensamientos y emociones sin juicio, lo que favorece la regulación emocional y la flexibilidad cognitiva, factores clave para evitar la reaparición de síntomas depresivos; además, la TCBM se centra en la consolidación de habilidades de autocuidado y en la prevención de patrones de pensamiento negativos que suelen desencadenar recaídas, algo que no se aborda de manera tan explícita en la activación conductual, la terapia interpersonal ni la terapia cognitiva de Beck, las cuales se orientan principalmente a la reducción de síntomas actuales y a la modificación de patrones cognitivos disfuncionales sin un enfoque sistemático en la prevención a largo plazo.'),
  (132, 'La terapia familiar de Maudsley se basa en la premisa de que el control parental debe ser ejercido de forma total durante la fase inicial para asegurar la ingesta adecuada del adolescente, luego se procede a un distanciamiento gradual del control mientras se refuerza la autonomía del joven, y finalmente se reintroduce el control parental de manera progresiva para consolidar una independencia funcional; por lo tanto, la afirmación que indica “distanciamiento respecto de los padres” como fase de la terapia es falsa, ya que el distanciamiento se aplica a la autonomía del paciente y no a la relación con los padres, que mantienen el control. Las opciones A, C y D describen adecuadamente las etapas de control, retorno gradual y establecimiento de independencia, respectivamente, y por ello no contienen errores.'),
  (133, 'En la Terapia cognitiva basada en la persona, la intervención con esquemas personales negativos en pacientes psicóticos se centra en la aceptación y la no confrontación directa de las experiencias, pues la confrontación puede intensificar la ansiedad y la disociación; por ello la opción que propone no cuestionar las experiencias esquemáticas negativas, sino facilitar la conciencia de las mismas, permite que el paciente observe sus creencias sin juzgarlas, lo que favorece la integración gradual y la reducción de la rigidez del esquema sin provocar un aumento de la paranoia o el miedo; las demás alternativas son erróneas porque la opción A sugiere una integración de las experiencias en la identidad, lo que puede reforzar la autoimagen distorsionada; la B propone confrontar la evitación experiencial, lo que en el contexto psicótico suele exacerbar la ansiedad y la desorganización; la C trata las experiencias como distorsiones cognitivas, lo que implica una reestructuración cognitiva directa que no es la estrategia principal de la terapia basada en la persona, que prioriza la aceptación y la empatía.'),
  (134, 'La opción d es la que contiene la afirmación falsa porque la CIDI 3.0, aunque es una entrevista semiestructurada de ayuda diagnóstica para las principales categorías incluidas en la CIE-10, no se compone de 41 secciones; su estructura se basa en módulos más cortos y su número de secciones es considerablemente menor, por lo que la cifra indicada es incorrecta. En cambio, la afirmación a es verdadera: el SCID‑5 dispone de cinco versiones, tres módulos para diagnósticos generales agrupados en diez módulos y dos módulos específicos para trastornos de personalidad. La afirmación b también es correcta, pues la SADS (Schedule for Affective Disorders and Schizophrenia) permite tanto el diagnóstico como la obtención del historial médico. Finalmente, la opción c es válida, ya que la KSADS‑5 (Kiddie Schedule for Affective Disorders and Schizophrenia, DSM‑5) está diseñada para la evaluación de niños y adolescentes de 6 a 18 años siguiendo los criterios del DSM‑5.'),
  (135, 'La recomendación de una recuperación de peso entre 0,5 y 1 kg por semana en pacientes hospitalizados con anorexia nerviosa se fundamenta en la evidencia clínica que muestra que este rango permite una rehidratación y restauración de masa muscular progresiva sin provocar sobrecarga cardiovascular ni complicaciones metabólicas, manteniendo la estabilidad hemodinámica y evitando la reconstitución de peso demasiado rápida que puede desencadenar síndrome de rehidratación o reequilibrio electrolítico; además, estudios de seguimiento indican que este ritmo favorece la mejora de la función cognitiva y la motivación terapéutica al evitar la frustración asociada a una pérdida de peso más lenta. Las opciones A y C son incorrectas porque proponen incrementos de peso que son demasiado bajos o demasiado altos, respectivamente, lo que puede conllevar a una recuperación insuficiente o a riesgos de sobrecarga fisiológica. La alternativa D es errónea pues existen directrices clínicas establecidas que orientan la velocidad de recuperación en este contexto.'),
  (136, 'La terapia de procesamiento cognitivo (TPC) se considera la más indicada para el trastorno de estrés postraumático con sentimientos de culpa porque se centra en la reestructuración de las distorsiones cognitivas que mantienen la culpa y la disociación, y en la exposición gradual a los recuerdos traumáticos, lo que facilita la integración de la experiencia y la reducción de la evitación; además, la TPC incorpora técnicas de revaluación de la responsabilidad y la auto‑compasión que abordan directamente la culpa interna. La EMDR (opción A) es eficaz para el TEPT, pero su enfoque no se dirige específicamente a la culpa cognitiva, centrándose más en la desensibilización del recuerdo; la terapia dialéctica conductual (B) es útil para la regulación emocional y la tolerancia al dolor, pero no se orienta a la reestructuración cognitiva de la culpa; y la terapia centrada en el presente (D) enfatiza la atención plena y la aceptación, sin abordar de manera específica las distorsiones de culpa que caracterizan al TEPT con este síntoma.'),
  (137, 'La terapia de exposición prolongada (TEP) es la modalidad con mayor respaldo empírico para el trastorno de estrés postraumático, ya que los ensayos controlados aleatorios y meta‑análisis han demostrado su eficacia superior a otras intervenciones psicológicas, reduciendo significativamente los síntomas de intrusión, evitación y alteraciones de estado de ánimo, y manteniendo los efectos a largo plazo; la TEP opera mediante la exposición sistemática y repetida a recuerdos traumáticos y estímulos asociados, facilitando la desensibilización y la reestructuración cognitiva, lo que explica su eficacia clínica. En contraste, la terapia dialéctica conductual, aunque útil en trastornos de regulación emocional, no cuenta con evidencia específica para TEPT; el entrenamiento en relajación muscular progresiva, aunque reduce la ansiedad, no aborda los componentes cognitivos y de exposición del TEPT; y la terapia centrada en el presente, orientada a la atención plena, muestra resultados mixtos y menor evidencia de eficacia en este trastorno.'),
  (138, 'El trastorno “Factores psicológicos que influyen en otras afecciones médicas” se clasifica en grados de gravedad según el impacto clínico; cuando los factores psicológicos provocan un empeoramiento que obliga al paciente a acudir a urgencias, la especificación es “grave”, pues la intervención requiere atención inmediata y la alteración es significativa, pero no alcanza la magnitud de una crisis potencialmente letal que caracterizaría la categoría extrema; las opciones A y B describen niveles de gravedad insuficientes para justificar la urgencia, mientras que la D sobrepasa la severidad típica de la presentación clínica descrita, por lo que no corresponde.'),
  (139, 'En la terapia de procesamiento cognitivo (TPC) de Resick y colaboradores, el reto o desafío de los significados del trauma se centra en las áreas que más comprometen la integración del evento traumático y la reconstrucción de la identidad del paciente; dichas áreas son la seguridad, la confianza, el poder/control, la autoestima y la intimidad, pues son los dominios cognitivos que suelen alterarse de forma profunda tras el trauma y que, al ser cuestionados, permiten reestructurar las creencias disfuncionales que mantienen el trastorno de estrés postraumático. Las opciones A y C son incorrectas porque, aunque la autoestima y la seguridad pueden verse afectadas, la TPC no se focaliza específicamente en sentimientos de vacío, embotamiento afectivo o culpa como áreas centrales de desafío; la opción B es errónea porque la amnesia psicógena no es un objetivo de la TPC y la confianza no se aborda de forma aislada.'),
  (140, 'La técnica RGINA se basa en la reducción gradual de la ingesta de nicotina y alquitrán mediante dos estrategias clave: la disminución progresiva del número de cigarrillos consumidos y la sustitución semanal de la marca por otra con menor contenido de nicotina, lo que facilita la adaptación fisiológica y psicológica al menor nivel de dependencia; por tanto la opción B recoge ambos elementos esenciales de la intervención, mientras que las demás combinan componentes que no pertenecen a RGINA (relajación, habilidades de afrontamiento) o que omiten la reducción progresiva del consumo, por lo que resultan incorrectas.'),
  (141, 'El manejo de contingencias mediante incentivos se ha demostrado eficaz cuando se combina con el Programa de Reforzamiento Comunitario (CRA), pues este protocolo integra la entrega de recompensas tangibles y la supervisión de la abstinencia en un entorno social estructurado, maximizando la motivación operante y reduciendo la probabilidad de recaídas; la evidencia clínica muestra que la CRA permite la aplicación práctica de reforzadores positivos en la comunidad, lo que potencia la adherencia y la consolidación de conductas saludables. En contraste, la entrevista motivacional (A) se centra en la exploración de la ambivalencia y no ofrece el esquema de reforzamiento sistemático que necesita la contingencia; la terapia familiar conductual (B) enfatiza la dinámica familiar y el aprendizaje social, pero no incorpora la entrega de incentivos de forma estructurada; y la terapia de exposición a señales (D) se orienta a la desensibilización frente a estímulos de la droga, sin abordar la motivación conductual que el protocolo de contingencia requiere.'),
  (142, 'La evidencia empírica sobre la bulimia nerviosa indica que la terapia interpersonal (TIP) es la única alternativa a la terapia cognitivo-conductual (TCC) que ha demostrado eficacia comparable; los estudios de ensayo controlado aleatorizado muestran mejoras sustanciales en la frecuencia de episodios de ingesta y en la autoestima, con efectos sostenidos al seguimiento, lo que la coloca como opción válida en la práctica clínica. Las demás opciones son incorrectas porque la psicoterapia focal (A) se centra en la resolución de conflictos específicos y no aborda los patrones de pensamiento disfuncional ni los comportamientos de alimentación; la psicoterapia cognitivo-analítica (B) combina elementos cognitivos y analíticos pero carece de la estructura de TCC y no cuenta con datos robustos de eficacia en bulimia; y la terapia familiar sistémica (D) se orienta a la dinámica familiar, pero los ensayos no han demostrado una superioridad o equivalencia frente a la TCC en este trastorno.'),
  (143, 'El modelo de tratamiento cognitivo‑conductual grupal para el trastorno por hipersexualidad de Hallberg et al. (2019) se fundamenta en la integración de psicoeducación básica, técnicas de gestión de impulsos y activación conductual interpersonal, elementos que permiten al paciente comprender la naturaleza del trastorno, regular los impulsos sexuales y mejorar las relaciones interpersonales, respectivamente; la exposición y prevención de respuesta (EPR), aunque útil en otros trastornos obsesivo‑compulsivos, no se incluye en este protocolo porque la hipersexualidad no se caracteriza por compulsiones rituales que se puedan exponer de forma segura, sino por impulsos y conductas de búsqueda de gratificación sexual, por lo que la EPR no se adapta a la dinámica del trastorno. Las opciones A, B y D son componentes esenciales del modelo, mientras que la opción C se excluye por no ser pertinente al enfoque cognitivo‑conductual aplicado a la hipersexualidad.'),
  (144, 'El “thinking aloud” consiste en que el paciente verbalice sus procesos mentales mientras se enfrenta a la situación de juego, lo que permite al terapeuta captar en tiempo real los pensamientos automáticos, creencias disfuncionales y justificaciones que mantienen la conducta de juego; por tanto, la opción A es la que describe su uso principal, ya que el objetivo es identificar los pensamientos irracionales que acompañan a la conducta de jugar, facilitando su posterior reestructuración cognitiva. Las demás alternativas son incorrectas: la B se refiere a la exposición o control de estímulos condicionados, que se aborda con técnicas de terapia de exposición o manejo de estímulos, no con “thinking aloud”; la C implica la modificación de patrones de juego compulsivos, lo cual es el objetivo de la terapia cognitivo-conductual en su conjunto, pero el procedimiento en cuestión no modifica directamente los patrones, sino que permite su identificación; la D habla de identificar determinantes de recaídas, función que corresponde a la elaboración de planes de prevención de recaídas, no al proceso de verbalización de pensamientos durante el juego.'),
  (145, 'El uso de estrógenos o antiandrógenos en el tratamiento de la disforia de género actúa sobre los sistemas hormonales que regulan la libido, reduciendo la producción de testosterona y, en consecuencia, la excitación sexual y el deseo; sin embargo, la literatura clínica indica que en algunos pacientes se observa un aumento de la curiosidad y el interés por la sexualidad, posiblemente debido a la reorganización de los receptores hormonales y la percepción de una identidad sexual más coherente con su género deseado, lo que explica la opción D. Las demás alternativas son incorrectas: la opción A asume un efecto ansiolítico que no se ha documentado; la B describe un deterioro del estado de ánimo que suele contradecir los resultados de mejora en la calidad de vida reportados en estudios longitudinales; y la C sugiere una mayor aversión genital, cuando en realidad el tratamiento tiende a disminuir la disforia genital y mejorar la aceptación del cuerpo.'),
  (146, 'El objetivo primordial del tratamiento psicológico de los trastornos parafílicos es evitar o disminuir la probabilidad de que se realice el comportamiento parafílico, ya que este puede culminar en actos delictivos o en la reincidencia, por lo que la opción B se ajusta a la práctica clínica que prioriza la prevención del daño tanto al individuo como a terceros; la opción A es errónea porque la eliminación total del interés sexual no es factible ni necesaria, y la terapia suele orientarse a la gestión del comportamiento más que a la supresión del impulso; la opción C confunde la reducción del deseo sexual general con la reducción del comportamiento parafílico, pues la intervención se focaliza en el acto específico, no en la libido en general; la opción D, aunque valiosa en la comprensión empática, no constituye el objetivo terapéutico principal y se limita a una dimensión secundaria de la intervención.'),
  (147, 'La mejora de la comunicación y el autocuidado con pacientes que presentan alta fragmentación se aborda desde la primera fase de tratamiento, la de estabilización, porque el objetivo inicial es lograr la seguridad interna y la regulación emocional, lo que permite que el paciente establezca una base de confianza y un sentido de continuidad entre sus partes disociativas; sin este nivel de estabilidad, las intervenciones posteriores de integración pueden resultar contraproducentes o incluso desencadenar crisis. Las opciones B, C y D son incorrectas porque, respectivamente, niegan la posibilidad de iniciar el trabajo en la fase de estabilización, lo cual contradice la práctica clínica basada en la teoría de la disociación que exige una base de seguridad antes de la integración; la opción C postula que la integración de la personalidad es la única etapa adecuada, ignorando la necesidad de estabilizar la relación terapéutica y la autorregulación; y la opción D limita el inicio del trabajo a la fase de integración de recuerdos, omitiendo la importancia de la estabilización previa para que el paciente pueda manejar la fragmentación de manera segura.'),
  (148, 'El protocolo de Woolfolk y Allen (2006) se distingue por incorporar la terapia centrada en las emociones (TCE) de Greenberg dentro de una estructura cognitivo‑conductual, con el objetivo de abordar la disfunción emocional que subyace en la somatización; la TCE facilita la identificación, aceptación y regulación de emociones intensas que suelen manifestarse como síntomas físicos, complementando así los componentes cognitivos y conductuales que reducen la atención y la interpretación catastrofista de los síntomas. Las demás opciones son incorrectas: la terapia de esquemas de Young (A) y la terapia de mentalización (B) se centran en procesos de esquema y teoría de la mente, respectivamente, y no se integran en el protocolo de Woolfolk y Allen; la entrevista motivacional (D) se orienta a la ambivalencia conductual y la preparación para el cambio, pero no aborda la regulación emocional que caracteriza la somatización.'),
  (149, 'La terapia interpersonal (TIP) se fundamenta en la teoría de que los síntomas depresivos y de otros trastornos se originan o mantienen por disfunciones en las relaciones interpersonales y los roles sociales; por ello, su objetivo es mejorar la calidad de las interacciones y la satisfacción de las necesidades sociales, lo que explica por qué la evidencia clínica respalda su eficacia en la depresión y, con menor grado, en la bulimia nerviosa, como indica la literatura de meta‑análisis; en contraste, la fobia social se trata con mayor eficacia mediante intervenciones cognitivas conductuales que abordan la evitación y la distorsión cognitiva, y la TIP no incorpora técnicas cognitivas, psicodinámicas ni gestálticas, por lo que las opciones A y B son incorrectas, mientras que la opción C es errónea porque la TIP no tiene evidencia sólida para los trastornos de la conducta alimentaria en general.'),
  (150, 'La terapia interpersonal y del ritmo social (TIRS) se fundamenta en la teoría de que los trastornos del estado de ánimo están vinculados a la desregulación de los ritmos circadianos y a la calidad de las relaciones interpersonales; en el trastorno bipolar, la alteración de los ciclos de sueño‑despertar y la dificultad para mantener vínculos sociales coherentes son componentes centrales, por lo que la TIRS ha demostrado eficacia al estabilizar ambos aspectos y reducir la frecuencia y gravedad de los episodios maníacos y depresivos. Las demás opciones son inadecuadas: la opción A se refiere a trastornos del sueño en general, pero la TIRS no se dirige específicamente a los trastornos de sueño aislados; la opción C, la fobia social, se trata mejor con terapia cognitivo‑conductual o exposición, sin la necesidad de intervenir en ritmos circadianos; la opción D, problemas de pareja, aunque la TIRS puede mejorar la comunicación, no constituye su objetivo principal ni ha mostrado eficacia específica en ese ámbito.'),
  (151, 'La terapia centrada en las emociones (TCE) de Greenberg es un enfoque humanista experiencial que pone al paciente en el centro de la experiencia emocional, integrando técnicas de atención plena, de expresión emocional y de reestructuración experiencial propias de la terapia centrada en el cliente y de la Gestalt, con el objetivo de que el individuo reconozca, experimente y modifique sus emociones de forma consciente y adaptativa; por ello la opción D describe con precisión su carácter humanista y experiencial y su fusión de prácticas centradas en el cliente y Gestalt. Las demás alternativas son erróneas porque la opción A confunde la TCE con un modelo psicoanalítico y menciona técnicas conductuales y cognitivas que no son su núcleo; la B lo presenta como un modelo cognitivo y se centra en la motivación-emoción, distorsionando su enfoque experiencial; y la C atribuye a la TCE el biofeedback como técnica principal, lo cual no corresponde a la práctica de Greenberg.'),
  (152, 'La psicoterapia centrada en la transferencia es una modalidad psicodinámica que se fundamenta en el análisis de las relaciones transaccionales entre paciente y terapeuta, y se ha documentado con evidencia empírica sólida en el tratamiento del trastorno de personalidad límite, donde la dinámica de la transferencia facilita la reestructuración de patrones relacionales disfuncionales; por tanto la opción B se ajusta a la descripción clínica y a los resultados de estudios controlados. La alternativa A es incorrecta porque la psicoterapia centrada en la transferencia no es un enfoque humanista y su eficacia no está respaldada específicamente para el trastorno de estrés postraumático; la opción C es falsa pues sí cuenta con evidencia empírica, y la opción D es errónea porque no pertenece al modelo cognitivo y su eficacia no se ha demostrado de manera concluyente para la depresión.'),
  (153, 'Según la propuesta de Winter (1992), la terapia extraspectiva se dirige a clientes cuyo sistema de constructos es rígido, es decir, que presentan una estructura cognitiva inflexible y poco abierta a la integración de nuevas experiencias; esta característica facilita la intervención que busca ampliar la flexibilidad constructiva y la apertura a nuevas perspectivas. Por ello la opción C es la que describe el criterio de selección. Las demás alternativas son incorrectas porque la propuesta no contempla la centralidad de los síntomas (A), la consistencia lógica (B) ni la construcción de problemas en términos psicológicos (D) como requisitos para la terapia extraspectiva.'),
  (154, 'En las terapias breves, estratégicas y centradas en soluciones el objetivo primordial es que el paciente logre modificar la situación presente mediante intervenciones concretas y orientadas a resultados; la eficacia de la intervención se mide en la capacidad de generar cambios funcionales inmediatos, por lo que la opción A refleja la esencia de estos enfoques, que privilegian la acción y la solución sobre la exploración del origen del problema. Las demás alternativas, aunque contienen elementos valiosos de la práctica clínica, no capturan el núcleo de la metodología: la opción B enfatiza la reconstrucción del relato del problema, una técnica más típica de la terapia narrativa o psicodinámica; la C, centrada en la validación empática, es un componente transversales pero no la característica distintiva de las terapias breves; y la D, que habla de un diagnóstico consensuado y libre de estigmas, corresponde más a la práctica clínica general que a la orientación estratégica y de soluciones.'),
  (155, 'La terapia familiar estructural concibe la familia como un sistema de relaciones dinámicas, donde la estructura se manifiesta en las demandas y expectativas que cada miembro proyecta y responde, creando patrones de interacción que pueden ser funcionales o disfuncionales; por ello la opción C es la que refleja la visión de que la familia se organiza a través de un conjunto invisible de demandas y expectativas funcionales que guían la interacción entre sus miembros, tal como lo plantea la teoría de Minuchin, que enfatiza la importancia de los límites y la jerarquía interna para mantener la cohesión y la diferenciación. Las demás alternativas son incorrectas porque la A se limita a criterios sociales y legales, sin abordar la dinámica interna; la B reduce la estructura a la información del genograma, que es una herramienta de registro más que una concepción de la estructura; y la D, aunque menciona pautas de comunicación y roles, se enfoca en la comunicación funcional y disfuncional sin referirse al concepto de demandas y expectativas que estructuran la interacción familiar.'),
  (156, 'La integración metateórica busca sintetizar los distintos enfoques terapéuticos restringiendo la síntesis a aquellos que comparten una base epistemológica coherente, de modo que la práctica resultante sea conceptualmente sólida y no simplemente un catálogo de técnicas; por ello la opción C es la que refleja fielmente ese objetivo, pues reconoce la necesidad de limitar la síntesis a enfoques compatibles epistemológicamente. Las opciones A y D se equivocan al proponer una unificación total o la supresión de teorías, lo cual contradice el carácter selectivo y crítico de la integración metateórica; la opción B, por su parte, promueve la expansión de teorías sin considerar su coherencia, lo que tampoco corresponde al propósito de esta metodología.'),
  (157, 'El tacto, según la teoría de Skinner, es un operante verbal que se controla por un estímulo discriminativo no verbal (por ejemplo, la presencia de un objeto) y se mantiene mediante reforzamiento social generalizado, es decir, la aprobación o el reconocimiento de otros cuando el hablante etiqueta correctamente el estímulo; por eso la opción A es la que describe fielmente la definición clásica del tacto. Las demás alternativas son incorrectas porque la B describe una respuesta que se asemeja morfológicamente al estímulo, característica del eco, no del tacto; la C atribuye al tacto el control de estímulos discriminativos verbales y reforzadores negativos, lo cual corresponde más bien a la función de la mandada, que se basa en la necesidad y en reforzadores positivos; y la D confunde la naturaleza del estímulo discriminativo, pues el tacto se regula por estímulos no verbales y no por otros verbales que no sean similares morfológicamente.'),
  (158, 'Los estudios de análisis de la conducta han demostrado que la conducta gobernada por reglas, es decir, aquella que se mantiene por la expectativa de que “si hago X, entonces Y”, se vuelve menos dependiente de las contingencias ambientales inmediatas porque la regla actúa como una guía interna que sustituye la retroalimentación directa; por tanto, la opción B refleja correctamente que la conducta adquirida mediante instrucciones directas tiende a ser menos sensible a las contingencias ambientales. Las demás alternativas fallan: la A presupone una capacidad innata de insensibilidad a contingencias, lo cual no se ha evidenciado; la C sugiere una limitación de las fuentes de reforzamiento que no se sostiene, pues las reglas pueden ser reforzadas por cualquier fuente que valide la regla; y la D afirma que el seguimiento de reglas es totalmente ajeno a las contingencias, lo cual contradice la evidencia de que las reglas siguen siendo operadas por el contexto y los reforzadores disponibles.'),
  (159, 'En el análisis funcional, el estímulo condicionado (EC) es aquel que, tras haber sido asociado repetidamente con un estímulo incondicionado (EI), adquiere la capacidad de provocar la respuesta condicionada (RC) por sí mismo; es decir, el EC precede y provoca la RC, estableciendo una relación de contingencia directa entre el estímulo y la respuesta. Por el contrario, el estímulo discriminativo (Ed) no provoca la RC por sí mismo, sino que indica la disponibilidad de una contingencia de refuerzo: cuando el Ed está presente, la respuesta tiene mayor probabilidad de ser reforzada, pero el Ed no genera la RC de forma automática. Por tanto, la opción A es la única que describe correctamente que el EC elicitó la respuesta y que el Ed señala la relación de contingencia entre la respuesta y el reforzador. Las demás alternativas son incorrectas porque confunden la naturaleza de las respuestas (emocionales vs. motoras, automáticas vs. voluntarias) o la relación de contingencia (el Ed no establece una relación con el estímulo consecuente, sino con la disponibilidad del reforzador).'),
  (160, 'La tercera fase de integración y rehabilitación en el tratamiento de trastornos disociativos se orienta a la reintegración de la personalidad, es decir, a la consolidación de una identidad coherente y la reconstrucción de la continuidad autobiográfica, lo que permite al paciente recuperar la capacidad de autorregulación y la cohesión interna; esta etapa sigue a la estabilización emocional y a la desensibilización de los recuerdos traumáticos, por lo que no se centra en la confrontación directa de memorias (opción A) ni en la regulación emocional (opción D), que son tareas propias de fases anteriores, y tampoco se limita a la funcionalidad interpersonal y social (opción C), que se aborda de manera complementaria pero no constituye el eje central de esta fase.'),
  (161, 'La metacomunicación adecuada en el tratamiento de la psicosis se refiere a la capacidad del paciente para verbalizar y reflexionar sobre sus propias experiencias internas y sobre la relación terapéutica, lo que permite al terapeuta ajustar la intervención y fortalecer la alianza; por eso la opción B es la que describe correctamente la situación en la que se logra esa metacomunicación, pues implica la referencia a las dificultades que el paciente percibe en la relación con el profesional, un elemento clave para la construcción de una alianza terapéutica sólida y la monitorización de la respuesta al tratamiento. Las demás alternativas son incorrectas porque la opción A se centra en procesos cognitivos internos sin vincularlos a la relación terapéutica, la opción C se refiere a la teoría de la mente en personas conocidas, lo cual no es el objetivo de la metacomunicación en psicosis, y la opción D, aunque menciona la teoría de la mente, se enfoca en personas desconocidas, lo que tampoco corresponde a la definición de metacomunicación en este contexto.'),
  (162, 'La venlafaxina, inhibidor de la recaptación de serotonina y norepinefrina, se utiliza principalmente en depresión mayor y trastornos de ansiedad, pero su perfil farmacológico puede precipitar episodios maníacos o hipomaníacos en pacientes con trastorno bipolar, por lo que su empleo está contraindicado; en contraste, los estabilizadores del humor (litio, valproato, carbamazepina) son la base terapéutica para controlar tanto fases maníacas como depresivas, los antipsicóticos atípicos (quetiapina, olanzapina, risperidona) se emplean como estabilizadores secundarios o en combinación con estabilizadores del humor, y los antiepilépticos (valproato, carbamazepina, lamotrigina) funcionan como moduladores de la excitabilidad neuronal y se usan con frecuencia en el manejo de la bipolaridad; por tanto, la opción D es la única que no corresponde a un tratamiento indicado.'),
  (163, 'La terapia cognitiva de Beck para la depresión grave se caracteriza por su duración breve y focalizada, normalmente comprendida entre 15 y 25 sesiones, lo que permite un abordaje estructurado y eficiente de los pensamientos disfuncionales y conductas asociadas; esta cifra se basa en estudios de eficacia que demuestran que la mayoría de los pacientes alcanzan mejoría clínica sustancial dentro de ese rango, sin necesidad de prolongar el tratamiento más allá de la fase de consolidación. Las demás opciones son erróneas: el rango de edad no se limita a 15‑65 años, pues la terapia cognitiva se ha aplicado con éxito en poblaciones más jóvenes y mayores; iniciar el tratamiento después del periodo agudo no es una recomendación específica de Beck, ya que la intervención puede y debe iniciarse durante la fase aguda para prevenir recaídas; y el estilo de la terapia no es no directivo ni de aceptación incondicional, sino que se basa en la guía activa del terapeuta para identificar y reestructurar cogniciones disfuncionales.'),
  (164, 'La terapia de activación conductual se centra en identificar y modificar patrones de comportamiento que perpetúan la depresión, mediante la reintroducción de actividades gratificantes, la reducción de evitaciones y la práctica de habilidades que aumenten la probabilidad de refuerzos positivos; por ello la opción C, que habla de “mejora de rutinas y ritmos sociales”, no corresponde a una técnica específica de activación conductual, sino a un objetivo más amplio de la intervención. Las demás alternativas sí se ajustan a los componentes de la activación: la atención a la experiencia (A) permite que el paciente observe sus emociones y sensaciones para identificar conductas que las refuerzan; la extinción de evitaciones (B) consiste en enfrentar gradualmente situaciones que el individuo evita, reduciendo su función de escape; y el entrenamiento en habilidades específicas para obtener refuerzos (D) implica enseñar estrategias concretas (por ejemplo, solicitar ayuda o buscar recompensas) que faciliten la obtención de reforzadores positivos. Así, solo la opción C se desvía de la práctica clínica de la activación conductual.'),
  (165, 'La opción A es la más adecuada porque el tratamiento asertivo comunitario (TAC) se ha demostrado eficaz en pacientes con esquizofrenia que presentan un patrón de desorganización social, alta frecuencia de recaídas y hospitalizaciones, y una baja adherencia a la atención tradicional; el TAC combina la intervención clínica con la coordinación de recursos sociales, la supervisión continua y la motivación de la adherencia, lo que reduce las visitas a urgencias y mejora la estabilidad funcional. Las alternativas B y C, aunque incluyen componentes integrados y de habilidades sociales, no abordan de forma tan específica la alta rotación hospitalaria y la falta de asistencia a los servicios, ya que se centran más en la intervención individualizada que en la continuidad comunitaria. La opción D, el tratamiento cognitivo-conductual para recaídas, se orienta principalmente a la prevención de síntomas agudos y no contempla suficientemente la desorganización social y la falta de apoyo estructurado que caracterizan a este perfil de paciente.'),
  (166, 'El objetivo de trabajar con el sistema de regulación emocional denominado “amenaza y autoprotección” se centra en la modificación de la respuesta emocional que subyace a los síntomas psicóticos, particularmente en la reducción de la ansiedad y la percepción de amenaza que alimentan la paranoia y la agitación; la terapia centrada en la compasión para la psicosis (TCCP) incorpora técnicas de atención plena y auto‑compasión que permiten a los pacientes observar sus pensamientos y emociones sin juicio, disminuyendo la reactividad defensiva y promoviendo la regulación emocional, lo que la convierte en la opción que aborda explícitamente ese sistema. Las demás alternativas, aunque orientadas a la psicosis, se enfocan principalmente en la reestructuración cognitiva (A y D) o en la aceptación de la experiencia sin un componente específico de regulación emocional centrado en la amenaza y la autoprotección (B), por lo que no cumplen con el objetivo señalado.'),
  (167, 'La mentalización se refiere a la capacidad de comprender y reflexionar sobre los estados mentales propios y ajenos, y en la terapia basada en la mentalización (MBT) de Bateman y Fonagy (2004) la activación de los esquemas de apego constituye el proceso central que permite a los pacientes explorar y regular sus experiencias internas, pues los esquemas de apego proporcionan el marco conceptual que facilita la interpretación de las emociones y las relaciones interpersonales; al trabajar con estos esquemas, el terapeuta ayuda al paciente a identificar patrones de pensamiento y comportamiento que se originan en experiencias tempranas, lo que favorece la integración de la experiencia emocional y la mejora de la regulación afectiva. Las demás opciones son incorrectas: la reactivación de las relaciones de objeto (A) se refiere a la dinámica de las relaciones internas pero no es el mecanismo principal de la mentalización; el análisis de los sentimientos de vacío (C) es una técnica asociada a la psicoterapia psicodinámica, no a la MBT; y el aumento de la aceptación y tolerancia al malestar (D) describe un objetivo terapéutico, pero no el proceso específico que impulsa la mentalización.'),
  (168, 'La terapia dialéctica conductual (TDC) de Linehan (1993) se centra en cuatro módulos de entrenamiento: atención plena, regulación emocional, tolerancia al malestar y eficacia interpersonal; cada uno busca mejorar la capacidad del paciente para manejar la intensidad emocional, aceptar la realidad, y mantener relaciones funcionales, por lo que la opción C, “resistencia al cambio”, no forma parte de los objetivos fundamentales de la TDC, ya que la propia metodología promueve activamente el cambio conductual y cognitivo; las demás opciones sí son pilares de la TDC: la eficacia interpersonal (A) permite al paciente establecer y mantener relaciones saludables, la regulación emocional (B) facilita la identificación y modulación de estados afectivos extremos, y la tolerancia al malestar (D) enseña estrategias de afrontamiento para situaciones de crisis sin recurrir a conductas autolesivas.'),
  (169, 'La opción B corresponde a la terapia cognitivo‑educativa de Barsky, la cual se centra en la enseñanza del paciente sobre la naturaleza de los síntomas físicos, su percepción y la forma en que los factores psicológicos, como la atención, la interpretación y la ansiedad, amplifican el malestar somático; este enfoque educativo permite que el individuo reconozca la relación entre sus pensamientos, emociones y síntomas, reduciendo la preocupación y la búsqueda de atención médica innecesaria. Las demás alternativas son incorrectas porque la terapia de Starcevic (A) se enfoca en la reestructuración cognitiva y la exposición a estímulos físicos, sin un componente educativo explícito; el tratamiento de Kellner (C) combina terapia cognitivo‑conductual con educación, pero su objetivo principal es la modificación de conductas de búsqueda de atención, no la enseñanza de la naturaleza de los síntomas; y la terapia de Warwick y Salkovskis (D) se centra en la reestructuración cognitiva y la exposición, sin el énfasis educativo que caracteriza a la propuesta de Barsky.'),
  (170, 'La terapia cognitivo‑conductual que emplea la modificación del pensamiento dicotómico, el manejo del tiempo y la solución de problemas se dirige a la personalidad obsesivo‑compulsiva, ya que los pacientes con esta patología presentan una rigidez cognitiva y una necesidad de control que se abordan eficazmente mediante la reestructuración de pensamientos disfuncionales y la planificación de actividades; la intervención se centra en reducir la ansiedad asociada a la perfección y la necesidad de orden, lo que se logra precisamente con esas técnicas. Las opciones A y D se refieren a trastornos con características más psicófilas o desapego social, donde la intervención se orienta a la empatía y la regulación emocional, no a la reestructuración cognitiva; la opción B, la dependencia, se trata con intervenciones centradas en la autonomía y la autoestima, por lo que la técnica descrita no es la principal en su abordaje.'),
  (171, 'La afirmación falsa es la C, pues la terapia interpersonal (TIP) no organiza su intervención en “eventos vitales, síntomas, evitación y problemas interpersonales”; en su esquema clásico se distinguen cuatro áreas interpersonales: duelo, transiciones de rol, déficits interpersonales y disputas de rol, tal y como indica la opción A, y la intervención se centra en mejorar la calidad de las relaciones y la adaptación a los cambios, no en tratar síntomas aislados o la evitación conductual. La opción B es verdadera porque la TIP posee un nivel de evidencia comparable al de la terapia cognitivo‑conductual, con múltiples estudios aleatorizados que demuestran su eficacia en la depresión mayor. La opción D también es correcta, pues la TIP incorpora técnicas de solución de problemas para abordar los conflictos interpersonales y mejorar la funcionalidad social. Por tanto, la única declaración que se desvía de la estructura teórica y práctica de la TIP es la C.'),
  (172, 'La opción B es la que corresponde a la evidencia actual sobre la intervención digital en psicosis, pues la literatura describe la utilización de plataformas en línea para la psicoeducación familiar y la creación de foros de apoyo entre cuidadores, con resultados que indican tanto viabilidad como utilidad clínica; estos estudios se sitúan dentro de la categoría de intervención psicosocial de bajo riesgo y son recomendados en guías internacionales. La alternativa A es incorrecta porque la terapia cognitiva basada en la persona para la psicosis perturbadora (PBCT) no se basa en tecnologías de la información y comunicación; se trata de una adaptación de la terapia centrada en la persona que se aplica en sesiones presenciales. La respuesta C es errónea porque la guía NICE no asigna un grado de recomendación C a la intervención digital en psicosis; en realidad, la recomendación es más baja o inexistente en la guía actual. Finalmente, la opción D describe una práctica de monitorización digital, pero no es la definición de la intervención digital en psicosis; la monitorización se considera una herramienta complementaria y no constituye la intervención en sí, por lo que también resulta incorrecta.'),
  (173, 'La afirmación falsa es la opción C, pues las guías internacionales de práctica clínica, como las de la APA y la NICE, incluyen explícitamente intervenciones psicológicas preventivas—principalmente la terapia cognitivo-conductual y la intervención psicológica integrada—para individuos con estado de alto riesgo de psicosis, reconociendo su eficacia en la reducción de la transición a episodio psicótico; en contraste, la opción A se alinea con la evidencia que muestra la superioridad de estas terapias frente a otras modalidades, la opción B refleja la incertidumbre clínica sobre la elección de la intervención más adecuada dado el heterogéneo perfil de riesgo, y la opción D es coherente con la literatura que indica que los modelos de prevención se aplican tanto a la fase de alto riesgo como a los primeros episodios, donde la intervención temprana mejora el pronóstico.'),
  (174, 'La afirmación que no es cierta es la A: la intervención familiar no se limita a familias de sujetos con esquizofrenia de larga evolución y con alta emoción expresada; la evidencia muestra que es eficaz en etapas tempranas y en casos con síntomas menos intensos, y su aplicación se basa en la dinámica familiar y la comunicación, no en la duración del trastorno ni en la intensidad emocional. La opción B es válida porque la intervención familiar constituye una de las intervenciones psicosociales más robustamente respaldadas en trastornos psicóticos, con numerosos ensayos controlados que demuestran su efecto en la reducción de recaídas y mejora de la adherencia. La C también es correcta, pues la guía NICE incluye la intervención familiar como un indicador de calidad asistencial, reconociendo su valor en la práctica clínica. La D es cierta, ya que las intervenciones pueden organizarse en formato individual, grupal o mixto, adaptándose a las necesidades de la familia y del paciente. Por tanto, solo la A presenta un error conceptual.'),
  (175, 'La ausencia de protodeclarativos a los 18 meses indica una alteración de la comunicación social y, por tanto, es un marcador temprano de trastorno del espectro autista; la falta de gestos que buscan compartir una experiencia con el interlocutor es un síntoma característico de la deficiencia de interacción social que define el TEA y suele presentarse antes de los dos años, cuando el desarrollo de la comunicación simbólica está en pleno auge. Las demás opciones son erróneas porque el trastorno del lenguaje (A) se manifiesta con retrasos en la producción y comprensión de palabras, pero no necesariamente con la ausencia de protodeclarativos; la opción B es incorrecta pues la ausencia de estos gestos sí constituye un indicador de patología antes de los dos años; y la discapacidad intelectual (D) se caracteriza por déficits cognitivos y adaptativos, no por la falta específica de gestos de compartir intereses.'),
  (176, 'La opción C, The Incredible Years (IY), se centra en la prevención y tratamiento de conductas problemáticas específicas mediante la modificación del entorno familiar y la enseñanza de habilidades sociales, sin adoptar la estructura de un modelo transdiagnóstico que integre procesos comunes a múltiples trastornos; en cambio, SSL, UPA y MST están diseñados como protocolos unificados que abordan factores transdiagnósticos como la regulación emocional, la cognición y la interacción familiar, aplicables a diversas patologías infantiles, por lo que las demás alternativas sí siguen un enfoque transdiagnóstico.'),
  (177, 'El programa multicomponente de escenificaciones emotivas se emplea en el tratamiento de fobias específicas porque combina la exposición gradual a estímulos temidos con la reestructuración cognitiva y la regulación emocional, permitiendo al paciente confrontar y revaluar las sensaciones de miedo en un entorno controlado; la evidencia clínica muestra que la integración de la exposición con la práctica de habilidades de afrontamiento mejora la habituación y la reducción de la evitación, algo que no se logra con la misma intensidad cuando se trata trastornos como el de pánico, la ansiedad social o el trastorno obsesivo‑compulsivo, donde la intervención se centra más en la reducción de la ansiedad anticipatoria, la modificación de la interacción social o la eliminación de compulsiones, respectivamente. Por tanto, las opciones A, B y C son inadecuadas porque el enfoque terapéutico de las fobias específicas requiere la exposición emocional específica que el programa ofrece, mientras que los otros trastornos demandan estrategias distintas.'),
  (178, 'El protocolo unificado (PU) de Barlow y colaboradores se diseñó como una intervención transdiagnóstica que busca reducir la evitación emocional y promover la exposición a experiencias emocionales, por lo que la afirmación de que uno de sus objetivos es prevenir la evitación emocional (opción A) es coherente con la literatura que describe su enfoque en la regulación emocional y la exposición gradual; la opción C también es congruente, pues el PU enfatiza la conciencia emocional como base para la regulación y la reducción de la evitación, y la opción D es válida porque el protocolo se emplea tanto en tratamientos clínicos como en programas de prevención, tal como se indica en los estudios de Barlow et al. (2018). En contraste, la afirmación de que el PU no ha sido adaptado a población infantil pero sí a adolescentes (opción B) es falsa, ya que la misma publicación y posteriores trabajos han reportado adaptaciones específicas del PU para niños y adolescentes, demostrando su aplicabilidad en rangos de edad más jóvenes; por lo tanto, la única alternativa que no corresponde a la descripción oficial del protocolo es la B.'),
  (179, 'La PCIT es una intervención de terapia conductual que se fundamenta en la evidencia empírica y se dirige a niños menores de edad que presentan problemas de conducta disruptiva, por lo que la opción A describe adecuadamente su población objetivo y su base de evidencia; la opción B es coherente porque la PCIT se estructura en principios de aprendizaje operante, con reforzamiento positivo y disciplina consistente, lo que la clasifica como terapia conductual; la opción C se ajusta a la práctica clínica de la PCIT, que incorpora técnicas de reforzamiento positivo (por ejemplo, elogios y recompensas) y estrategias disciplinarias efectivas (como el tiempo fuera y la instrucción clara) para mejorar la relación y el comportamiento. En contraste, la opción D es falsa porque la PCIT no está diseñada ni ha demostrado eficacia en el tratamiento de trastornos de la conducta alimentaria; dicha población requiere intervenciones específicas de alimentación y trastornos de la imagen corporal, no la dinámica de interacción familiar centrada en la conducta disruptiva. Las demás opciones comparten la misma razón de error, ya que todas describen correctamente los fundamentos y la población de la PCIT, mientras que la opción D lo hace incorrectamente al asociar la terapia con un trastorno para el cual no está indicada.'),
  (180, 'La terapia cognitivo-conductual individual (A) constituye la intervención de primera línea para la bulimia nerviosa y la anorexia nerviosa, con evidencia robusta de eficacia; la terapia familiar-conductual (C) es la modalidad preferida en adolescentes con trastornos de la conducta alimentaria, mientras que la terapia familiar sistémica (D) se emplea en casos de bulimia y trastornos de la conducta alimentaria en adolescentes, con resultados clínicamente significativos; en contraste, la terapia de aceptación y compromiso (B) no se considera bien establecida ni probablemente eficaz para estos trastornos, pues su eficacia clínica no ha sido demostrada en estudios de alta calidad y su aplicación se limita a otras condiciones psicológicas; las demás opciones son erróneas porque cada una corresponde a una modalidad con respaldo empírico sólido, mientras que la opción B carece de tal respaldo.'),
  (181, 'El método de alarma se reconoce como la intervención psicológica más eficaz y bien establecida para la enuresis nocturna, pues combina condicionamiento clásico y operante al asociar la detección de humedad con una señal sonora que despierta al niño, reforzando la respuesta de vaciado voluntario y promoviendo la consolidación de la memoria de la respuesta de orina; además, la evidencia de estudios controlados muestra tasas de éxito superiores a las de otras técnicas y su aplicación no requiere medicación ni intervenciones invasivas, lo que lo convierte en la opción de primera línea. El entrenamiento en retención, aunque útil para la enuresis diurna, no aborda la respuesta nocturna y su eficacia es limitada; el entrenamiento en cama seca es una estrategia de manejo conductual que se emplea en conjunto con la alarma pero no constituye un tratamiento independiente; la imipramina, a pesar de su uso en algunos protocolos, es un fármaco antidepresivo cuya eficacia en la enuresis nocturna es menor y conlleva efectos secundarios que lo relegan a un segundo plano.'),
  (182, 'La evidencia empírica muestra que, tras un evento traumático, tanto niños como niñas pueden desarrollar dificultades escolares y de socialización, y que, a diferencia de los adultos, tienden a internalizar el evento culpándolos a sí mismos directa o indirectamente; esta tendencia se explica por la falta de mecanismos de defensa más desarrollados y la mayor tendencia a la auto‑culpa en la infancia, lo que favorece la aparición de síntomas de adaptación escolar y de socialización. Las demás opciones son incorrectas porque la primera presupone una diferencia de expresión emocional entre sexos que no se sostiene en la literatura (ni la mayor facilidad de los niños ni la predominancia de síntomas ansiosos frente a depresivos), la tercera invierte la asociación típica de trastornos de conducta y depresivos entre sexos, y la cuarta describe un patrón de reexperimentación que se observa más en niños menores y preadolescentes, no en los mayores y prepúberes, por lo que las afirmaciones A, C y D carecen de respaldo empírico.'),
  (183, 'El motivo que explica la dificultad diagnóstica del TAG infantil es que la manifestación típica de la ansiedad en niños se presenta frecuentemente como un temperamento ansioso o un perfil de madurez precoz, con rasgos de escrupulosidad, responsabilidad y perfeccionismo que los adultos suelen valorar positivamente; esta valoración social favorece la interpretación de la ansiedad como una virtud más que como un trastorno, lo que dificulta su identificación clínica. Las demás opciones son erróneas: la alternativa B confunde los criterios de diagnóstico, pues el DSM‑5 exige al menos cuatro de los seis síntomas, no solo dos, y no conduce a un sobrediagnóstico; la C asume incorrectamente que la preocupación ansiosa se desarrolla antes de los ocho años y que el niño no puede expresarla, cuando en realidad la expresión puede variar pero no es imposible; y la D describe preocupaciones típicas de la ansiedad, pero no explica por qué se dificulta la identificación, pues las inquietudes sobre el pasado y la familia son comunes en varios trastornos ansiosos infantiles.'),
  (184, 'La opción B es la que se ajusta a la evidencia clínica sobre el diagnóstico diferencial entre TEA y TDAH: las rabietas en TEA suelen desencadenarse por cambios inesperados en la rutina o el entorno, reflejando la alta sensibilidad a la predictibilidad y la necesidad de control, mientras que en TDAH las explosiones emocionales se asocian a impulsividad y falta de regulación, sin requerir necesariamente un cambio ambiental. En contraste, la opción A es incorrecta porque los patrones conductuales restrictivos y repetitivos son característicos del TEA y no se observan con la misma frecuencia ni intensidad en el trastorno de la comunicación social, que se centra en la pragmática del lenguaje. La opción C falla al afirmar que el mutismo en TEA se debe a la evitación de situaciones de ansiedad, pues el mutismo en TEA suele estar vinculado a déficits comunicativos y no a una ansiedad social específica, mientras que el mutismo selectivo se caracteriza por la evitación social. Finalmente, la opción D es errónea porque los rituales en TEA no suelen generar una sensación de agrado; al contrario, suelen ser conductas compulsivas que alivian la ansiedad, a diferencia de los rituales en TOC que sí pueden producir una sensación de alivio o agrado tras su realización.'),
  (185, 'La fase que no corresponde a la terapia cognitivo‑conductual focalizada en el trauma es el de debriefing (A); esta intervención, orientada a la desensibilización inmediata tras un suceso traumático, se emplea en contextos de crisis agudas y no forma parte del protocolo de tratamiento de secuelas a largo plazo que incluye estabilización y desarrollo de habilidades (B), reelaboración del trauma (C) y consolidación y cierre (D), los cuales siguen una progresión lógica de seguridad, procesamiento y cierre del episodio traumático; las demás opciones son etapas habituales del modelo, mientras que el debriefing se reserva para la fase inicial de intervención en la que la víctima aún no ha establecido una base de seguridad ni ha desarrollado las habilidades de afrontamiento necesarias.'),
  (186, 'La afirmación D es falsa porque la terapia dialéctico-conductual (TDC) para adolescentes con conductas autolíticas y ideación suicida se centra principalmente en la adquisición de habilidades de regulación emocional, tolerancia a la frustración y la construcción de una vida que merezca la pena ser vivida (A), incluye apoyo telefónico para crisis (B) y se organiza en sesiones semanales que combinan trabajo individual con el adolescente, participación familiar y sesiones grupales (C); la TDC no se basa en la reestructuración cognitiva de pensamientos negativos como la principal estrategia de intervención, ya que su enfoque es la aceptación y la validación de las emociones, no la modificación cognitiva directa. Las opciones A, B y C son coherentes con la práctica clínica de la TDC, mientras que la opción D se desvía del modelo dialéctico-conductual, que no emplea la reestructuración cognitiva como componente central.'),
  (187, 'La fase que no pertenece a la Imagery Rehearsal Therapy (IRT) es la opción D, porque la IRT se centra en la reestructuración de la propia imagen del sueño mediante la práctica guiada de una versión modificada del mismo, no en el análisis de sesgos cognitivos o significados biográficos; esas intervenciones se encuentran en terapias cognitivas o psicoanalíticas, no en la IRT. Por otro lado, las opciones A, B y C describen pasos esenciales de la IRT: el registro del sueño (diario de intervención), la evocación y modificación de la pesadilla en estado de relajación, y la revisión y reescritura del contenido del sueño, respectivamente, que son componentes reconocidos del protocolo de IRT.'),
  (188, 'El trastorno de estrés postraumático sí puede diagnosticarse en niños menores de seis años; la manifestación de recuerdos intrusivos en esta edad suele adoptar la forma de juegos repetitivos o fantasías que recrean la experiencia traumática, y estos recuerdos pueden no provocar angustia inmediata, por lo que la opción B es la que describe correctamente la presentación clínica típica, donde el juego sirve como medio de procesamiento simbólico del trauma. Las demás alternativas son erróneas: la A niega la posibilidad de diagnóstico, lo cual está en contradicción con los criterios diagnósticos que reconocen la edad temprana; la C sobreestima la gravedad de la exposición a medios indirectos, pues la exposición pasiva a imágenes violentas no se considera un evento traumático por sí solo; y la D confunde la irritabilidad con el trastorno negativista desafiante, pues la irritabilidad puede ser un síntoma del TEP pero no constituye un diagnóstico exclusivo.'),
  (189, 'El programa Coping Cat es un tratamiento altamente estructurado para la ansiedad infantil, pues se basa en la terapia cognitivo‑conductual y se organiza en módulos que combinan exposición gradual, reestructuración cognitiva y entrenamiento de habilidades de afrontamiento, todo ello adaptado a la edad y nivel de desarrollo de los niños; su eficacia se ha demostrado en ensayos controlados para trastornos de ansiedad generalizada, fobia social y trastorno de ansiedad por separación en población pediátrica. Las demás opciones resultan erróneas: la opción B confunde la edad objetivo, pues Coping Cat se aplica a niños de 7 a 12 años, no a preescolares; la opción C es inexacta porque el programa no está diseñado para la depresión, aunque puede mejorar síntomas ansiosos asociados; y la opción D es incorrecta al afirmar que es multicomponente para la ansiedad social, cuando su enfoque principal es la ansiedad generalizada y fobias específicas, no exclusivamente la social.'),
  (190, 'El setpoint de Keesey (1980) describe un mecanismo homeostático que mantiene el peso corporal dentro de un rango relativamente estable; por ello la afirmación de que “el cuerpo tiende a regularse para dificultar una bajada excesiva de peso” (opción A) y la que indica que “obstaculiza un aumento rápido y extremo de peso” (opción B) reflejan adecuadamente la respuesta fisiológica de resistencia a cambios bruscos, y la referencia al “efecto suelo y efecto techo” (opción C) explica cómo la ingesta y la energía se ajustan para evitar desviaciones extremas, lo que concuerda con la teoría del setpoint. En contraste, la afirmación de que “el setpoint es inamovible” (opción D) es falsa, pues la literatura indica que el punto de referencia puede desplazarse con cambios crónicos en la dieta, la actividad física o factores hormonales, por lo que la opción D es la única incorrecta.'),
  (191, 'La opción D es falsa porque la teoría de la puerta de Melzack y Wall sostiene explícitamente que factores psicológicos como las creencias, las experiencias previas y el estado emocional modulan la percepción del dolor; estos elementos influyen en la apertura o cierre de la “puerta” en el asta dorsal, alterando la transmisión de la señal nociceptiva. En cambio, la alternativa A describe correctamente la visión multidimensional del dolor, integrando daño tisular, estado emocional, motivación y atención. La alternativa B resume adecuadamente el mecanismo de la puerta, señalando que la actividad neuronal aferente se modula en el asta dorsal y que la puerta controla el paso de los impulsos nociceptivos. La alternativa C también es coherente con la teoría, pues indica que la puerta puede ser influenciada por mensajes descendentes del cerebro, y que emociones como la ansiedad, el miedo o el estrés pueden intensificar la sensación de dolor.'),
  (192, 'La hiperuricemia, aunque puede presentarse en personas con sobrepeso, no se considera un factor de riesgo directo ni tan frecuente como la diabetes tipo 2, los problemas respiratorios y cardiovasculares o la hipertensión, los cuales están bien documentados como consecuencias fisiológicas del exceso de masa corporal; por ello la opción A no se ajusta a la afirmación de que el sobrepeso y la obesidad son factores de riesgo importantes para dichas enfermedades. Las alternativas B, C y D describen condiciones que sí se ven aumentadas de forma consistente con el sobrepeso y la obesidad, por lo que no cumplen el criterio de “no lo está o lo está en menor medida”.'),
  (193, 'La opción A es la única que refleja la recomendación de la guía NICE (2018), la cual establece que el metilfenidato constituye el tratamiento farmacológico de primera línea para niños mayores de cinco años y para adolescentes con TDAH, basándose en la evidencia de eficacia y perfil de seguridad; las demás alternativas se desvían de la evidencia actual: la opción B menciona una recomendación de la OMS que no existe y confunde la edad de derivación con la edad de inicio del tratamiento; la opción C, aunque reconoce la eficacia de los programas de entrenamiento parental y escolares, presenta una afirmación incorrecta al afirmar que el tratamiento psicosocial mejora más los síntomas externalizantes que los internalizantes, pues la literatura indica que los efectos son equivalentes o incluso más fuertes en internalizantes; la opción D es errónea al afirmar que la lisdexanfetamina es “claramente más ineficaz”, cuando la evidencia muestra que es tan eficaz como el metilfenidato y a veces superior en ciertos subgrupos.'),
  (194, 'La opción C es la única que refleja la evidencia clínica sobre la función cognitiva en el trastorno bipolar II: los pacientes presentan un rendimiento deteriorado en la mayoría de los dominios cognitivos (atención, memoria de trabajo, velocidad de procesamiento, funciones ejecutivas) comparado con la población general, salvo en tareas de memoria episódica y fluidez semántica, donde los déficits suelen ser menores o inexistentes, lo que sugiere una preservación parcial de la capacidad de recuperación de la información semántica y la generación de palabras; en contraste, la recuperación funcional global suele tardar más que la remisión de los síntomas (opción A es incorrecta porque la recuperación funcional se ve afectada por episodios recurrentes y deterioro cognitivo); el deterioro cognitivo no es necesariamente más leve en el trastorno bipolar II que en el I (opción B es errónea, pues estudios comparativos muestran déficits similares o incluso mayores en el I, especialmente en episodios maníacos); y la frecuencia de transición directa entre episodios sin recuperación interepisódica no alcanza el 50 % (opción D es falsa, la literatura indica tasas más bajas, alrededor del 20‑30 %).'),
  (195, 'El modelo cúbico de estructura del intelecto de Guilford postula que la inteligencia se construye a partir de la interacción de contenidos (conocimientos), operaciones (procesos mentales) y productos (resultados de la actividad cognitiva), por lo que la opción A es la que corresponde a esta concepción; el modelo de la teoría triárquica de Sternberg, aunque también contempla tres componentes, los denomina análisis, síntesis y aplicación, y no se centra en la combinación de contenidos, operaciones y productos; el modelo jerárquico de Vernon organiza la inteligencia en niveles de complejidad, pero no enfatiza la interacción de esos tres elementos; y el modelo de los tres estratos de Carroll combina la teoría de la inteligencia general con la específica, pero no se basa en la tríada de contenidos‑operaciones‑productos.'),
  (196, 'En el modelo analítico funcional de Stephen Haynes, el símbolo del rombo designa la causa original o fundamental que no puede modificarse directamente; representa la raíz estructural del problema que condiciona la aparición de los síntomas, por lo que se interpreta como la “causa original no modificable”. La opción A (variable causa o moderador) corresponde a los círculos que indican variables que influyen en la relación entre causa y efecto, pero no a un rombo; la opción B (problema efecto de otro problema) se refiere a la relación de dependencia entre dos problemas y se representa con flechas, no con un rombo; y la opción D (variable causal hipotética) se emplea para variables que aún no se han comprobado, también representadas por círculos, no por el rombo.'),
  (197, 'La condición indispensable para la aplicación de un programa de manejo de contingencias con incentivos en el tratamiento de la adicción a drogas es la monitorización frecuente de la conducta objetivo, es decir, la abstinencia o el uso de la droga principal, porque la efectividad del esquema depende de la retroalimentación inmediata y precisa que permite ajustar la magnitud y la frecuencia de los refuerzos; sin datos concretos sobre la conducta que se pretende modificar, el programa pierde su base operante y la contingencia no puede establecerse de manera fiable. Las demás opciones son incorrectas: la evaluación de patrones de consumo de todas las drogas (B) y la exclusión de trastornos asociados (C) pueden ser útiles para un abordaje integral, pero no constituyen requisitos esenciales para la implementación del esquema de incentivos; la implicación de terceros (D) puede facilitar la supervisión, pero no es un requisito imprescindible, ya que la monitorización puede realizarse mediante pruebas de laboratorio u otros métodos de registro directo.'),
  (198, 'En la observación conductual, los “no reactivos” se refieren a la ausencia de respuesta ante estímulos, y la medida de erosión (c) es la herramienta que cuantifica la pérdida de la respuesta habitual, identificando la intensidad de la falta de reacción; por tanto, constituye el único elemento de la lista que se considera un producto de conducta, pues refleja directamente la variación funcional de la conducta observada. Los atributos (a) describen cualidades de la conducta pero no miden su ausencia; las interacciones (b) implican la relación entre estímulo y respuesta, por lo que no se clasifican como no reactivos; y las conductas (d) son los fenómenos observados en sí mismos, no la medida de su falta.'),
  (199, 'El tratamiento con mayor respaldo empírico para el trastorno de estrés postraumático en niños y adolescentes es la terapia cognitivo-conductual centrada en el trauma, ya que combina la exposición gradual al recuerdo traumático con la reestructuración cognitiva y la enseñanza de habilidades de afrontamiento, lo que ha demostrado reducir significativamente los síntomas de intrusión, evitación y alteraciones emocionales en estudios controlados; la relajación, el EMDR y las técnicas de autocontrol, aunque pueden aportar beneficios complementarios, carecen de la evidencia robusta y específica que respalde su uso como intervención primaria en esta población, y en el caso del EMDR su eficacia sigue siendo objeto de debate en la literatura infantojuvenil.'),
  (200, 'El diseño de bloques aleatorios se basa en la idea de agrupar las unidades experimentales en bloques homogéneos según una variable de bloqueo que se considera una fuente de variabilidad no deseada; al asignar aleatoriamente los tratamientos dentro de cada bloque se controla esa fuente de variación, lo que reduce la heterogeneidad residual y, en consecuencia, aumenta la potencia estadística de la prueba F que evalúa el efecto del tratamiento, pues el error experimental se vuelve más pequeño; las demás opciones son incorrectas porque la interacción entre la variable manipulada y la de bloqueo no se asume (el objetivo es evitarla), la variable de bloqueo sí debe estar correlacionada con la variable dependiente para que su efecto sea relevante y se pueda controlar, y aunque el bloqueo es una técnica de control estadístico, la afirmación no describe una característica específica del diseño de bloques aleatorios.'),
  (201, 'La teoría de la auto‑discrepancia de Higgins sostiene que la discrepancia entre el autoconcepto real y el autoconcepto de deber (o responsable) genera una tensión motivacional que se manifiesta principalmente en estados de ansiedad, pues el individuo percibe una brecha entre lo que es y lo que debe ser, lo que activa el sistema de alerta y la preocupación por el cumplimiento de normas internas; la depresión (A) se asocia más con la discrepancia entre el autoconcepto real y el ideal, el abatimiento (B) se vincula a la percepción de falta de control o a la pérdida de motivación, y la decepción (D) corresponde a la discrepancia entre expectativas y resultados, por lo que las opciones A, B y D no corresponden al fenómeno descrito por la teoría de la auto‑discrepancia.'),
  (202, 'El área de fusión de Panum, que determina el rango de disparidad aceptable para la percepción de la profundidad, es mayor en la periferia y disminuye progresivamente hacia el centro de la visión, alcanzando su mínima extensión en la zona del punto de fijación, donde la densidad de fotoreceptores y la resolución visual son máximas y la disparidad tolerada es mínima; en la periferia visual (opción A) la zona de fusión es más amplia, pues la resolución es menor y la disparidad tolerada mayor; las hemirretinas nasal (C) y temporal (D) no presentan diferencias relevantes en el tamaño del área de fusión, por lo que sus opciones son incorrectas.'),
  (203, 'Para que el estadístico Chi‑cuadrado de independencia sea válido en una tabla de contingencia, se requiere que la distribución de frecuencias esperadas bajo la hipótesis nula no presente valores demasiado pequeños, ya que el chi‑cuadrado se aproxima a la distribución asintótica solo cuando cada celda tiene una expectativa razonablemente grande; la regla práctica es que no más del 20 % de las frecuencias esperadas sean menores a 5, lo que garantiza la aproximación adecuada y evita la inflación de la estadística. Las demás alternativas son inadecuadas: la igualdad de número de filas y columnas (A) no afecta la validez del chi‑cuadrado, la igualdad de márgenes (B) no es una condición necesaria y, de hecho, la hipótesis de independencia presupone márgenes independientes, y la nulidad de todos los residuales (C) implicaría que los datos coinciden exactamente con las expectativas, lo que haría que el chi‑cuadrado fuera cero y no evaluaría la independencia.'),
  (204, 'El tamaño de la caja central de un diagrama de caja representa la amplitud intercuartílica, es decir, la distancia entre el primer cuartil (Q1) y el tercer cuartil (Q3), porque la caja está diseñada para ilustrar la dispersión del 50 % central de los datos, excluyendo los valores atípicos que se muestran en los bigotes; el rango, la desviación típica o la diferencia entre media y mediana no describen esa dispersión central, pues el rango abarca todo el espectro de valores, la desviación típica pondera la dispersión en torno a la media y la diferencia entre media y mediana mide la asimetría, por lo que las opciones B, C y D son incorrectas.'),
  (205, 'El estadístico que permite conocer la relación lineal entre X e Y después de quitar el efecto de una tercera variable Z sobre Y es la correlación semiparcial (también llamada parcial de X sobre Y), porque se calcula el coeficiente de correlación entre la parte residual de X (después de remover la variación explicada por Z) y la parte residual de Y (después de remover la variación explicada por Z), manteniendo intacta la influencia de Z sobre X; la correlación parcial, en cambio, elimina el efecto de Z sobre ambas variables y no responde a la pregunta planteada, mientras que la covarianza y la regresión no controlan por una variable adicional y, por tanto, no permiten aislar la relación específica entre X e Y.'),
  (206, 'El test de anclaje, o ítems de anclaje, se emplea en la equiparación porque permite establecer equivalencias entre distintas formas de un mismo instrumento mediante la comparación de puntuaciones de referencia; los ítems de anclaje sirven como puntos de referencia que facilitan la calibración de escalas y la conversión de puntuaciones entre versiones, garantizando la comparabilidad de resultados. Las demás opciones son inadecuadas: la baremación (B) se refiere a la aplicación de normas para interpretar puntuaciones, no a la equivalencia entre formas; la validez de contenido (C) evalúa la representatividad de los ítems respecto al constructo, sin implicar anclaje; y la fiabilidad interjueces (D) se centra en la consistencia entre evaluadores, no en la comparación de instrumentos.'),
  (207, 'La prueba de Welch (opción C) es la adecuada porque permite comparar medias entre dos grupos cuando el diseño es no equilibrado y la varianza de los grupos difiere, es decir, cuando se viola la homocedasticidad; la estadística de Welch ajusta los grados de libertad según la varianza y el tamaño muestral de cada grupo, ofreciendo una inferencia robusta sin requerir igualdad de varianzas. La prueba de Levene (opción A) solo verifica la igualdad de varianzas, no compara medias; el estadístico Durbin‑Watson (opción B) evalúa autocorrelación en residuos de regresión, no varianzas; y la prueba de Hartley (opción D) también prueba homocedasticidad, pero no es la herramienta de comparación de medias bajo heterocedasticidad.'),
  (208, 'La prueba más adecuada en un diseño multigrupos al azar cuando se desean comparaciones a posteriori entre todos los pares de medias, bajo supuestos de normalidad y homogeneidad de varianzas, es el método HSD (Honestly Significant Difference) de Tukey, pues controla el error de tipo I a nivel global y mantiene la potencia al comparar todas las combinaciones posibles, algo que el ajuste de Bonferroni, aunque conservador, reduce de forma excesiva; la prueba de Dunnett, por otro lado, está diseñada para comparaciones con un grupo de control y no cubre todas las parejas; y la prueba de Fisher (Fisher''s LSD) no controla adecuadamente el error de tipo I cuando se realizan múltiples comparaciones, lo que la hace menos fiable en este contexto.'),
  (209, 'La afirmación A es la única que describe correctamente la relación entre eta cuadrado y el coeficiente de determinación (R²) de un modelo de regresión; ambos cuantifican la proporción de varianza explicada por las variables independientes, por lo que son equivalentes en su interpretación estadística, aunque eta cuadrado se suele usar en análisis de varianza y R² en regresión. La opción B es errónea porque omega cuadrado es, al contrario, un estimador menos sesgado que eta cuadrado y se prefiere cuando se desea una estimación más precisa del efecto poblacional, especialmente en muestras de tamaño moderado; no se recomienda sustituirlo por eta cuadrado. La alternativa C es incorrecta porque el delta de Cliff es un estadístico no paramétrico que mide la diferencia de medianas entre dos grupos, no un estimador paramétrico del tamaño del efecto. Finalmente, la opción D es falsa porque la “d” de Cohen no es la única medida que puede informar sobre el tamaño del efecto de un tratamiento; existen otras métricas como eta cuadrado, omega cuadrado, y delta de Cliff, entre otras, que también son válidas según el contexto analítico.'),
  (210, 'Según la teoría de los lemmas de Levelt (1989), el lemma constituye la representación semántica y fonológica de una palabra, sin incluir la morfología ni la ortografía; la morfología se añade en la fase de derivación, la fonología se codifica en la fase de articulación y la ortografía se gestiona en la fase de escritura, mientras que la sintaxis se integra en la estructura de la oración, por lo que la opción D es la única que se alinea con la función del lemma. Las demás opciones son incorrectas porque la morfología (A) se procesa después del lemma, la fonología (B) se gestiona en la etapa de articulación y la ortografía (C) se relaciona con la representación escrita, no con la unidad léxica interna.'),
  (211, 'El modelo jerárquico de Collins y Quillian (1969) postula que los conceptos se organizan en una red con nodos semánticos y que la velocidad de acceso depende de la distancia entre nodo raíz y nodo objetivo; para comprobarlo emplearon la tarea de verificación de frases, en la que los participantes debían decidir rápidamente si una frase era semánticamente coherente o no, lo que permite medir la latencia de respuesta como reflejo de la distancia en la red; las demás opciones no se ajustan al diseño original: la asociación de palabras (A) se utiliza para estudiar asociaciones libres, la denominación (C) evalúa acceso fonológico y la categorización semántica (D) mide la clasificación de conceptos sin involucrar la distancia jerárquica; por tanto, solo la verificación de frases (B) corresponde al experimento que validó empíricamente el modelo de red jerárquica.'),
  (212, 'La hipótesis propuesta por Woodworth y Sells (1935) se denomina efecto atmósfera, pues sostiene que la conclusión de un silogismo se forma a partir de la impresión global que generan las premisas, sin analizar los componentes lógicos individualmente; la atmósfera conceptual creada por el conjunto de premisas guía la inferencia, lo que explica la tendencia a aceptar conclusiones que se ajustan al “sentido” general del argumento. El efecto de la figura (A) se refiere a la influencia de la disposición de los términos en la respuesta, no a la impresión global; el efecto de anclaje (C) implica la influencia de una cifra inicial en juicios posteriores, y el efecto de la conjunción (D) describe la preferencia por opciones combinadas, ambos conceptos distintos del fenómeno de la atmósfera.'),
  (213, 'La ley psicofísica de Stevens (1957) se expresa mediante la función de potencia, que relaciona la magnitud física de un estímulo con la magnitud perceptual en una escala de razón, de modo que la percepción es proporcional a una potencia de la intensidad del estímulo; esta formulación surge de los datos obtenidos con métodos directos como la estimación y la comparación simultánea, y permite describir la relación entre estímulo y sensación en términos de exponentes que varían según la modalidad sensorial. Las demás alternativas son incorrectas: el logaritmo (B) corresponde a la ley de Weber‑Fechner, la integral (C) no aparece en la formulación de Stevens y la raíz cuadrada (D) no describe la relación general entre estímulo y percepción establecida por la teoría de la potencia.'),
  (214, 'La hipótesis de los niveles de procesamiento de Craik y Lockhart sostiene que la profundidad con la que se procesa la información determina su retención a largo plazo, de modo que el procesamiento semántico o elaborativo, que implica la integración de la nueva información con conocimientos previos y la generación de significados, produce el recuerdo más duradero; por ello el repaso elaborativo (opción C) es el que favorece la consolidación en la memoria de largo plazo. El repaso de mantenimiento (A) se limita a la repetición mecánica sin añadir significado, lo que solo refuerza la memoria de corto plazo. El repaso significativo (B) se refiere a la comprensión de la información en sí, pero no necesariamente implica la elaboración de conexiones adicionales, por lo que su efecto es menor que el de la elaboración. El repaso declarativo (D) se centra en la memorización de hechos explícitos sin profundizar en su relación con otros contenidos, resultando en una retención inferior al proceso elaborativo.'),
  (215, 'McAdams (1980) desarrolló el concepto de “motivo de afiliación” como una dimensión motivacional que impulsa a los individuos a buscar y mantener relaciones interpersonales profundas y satisfactorias; dentro de este marco, el “motivo de intimidad” se define específicamente como la búsqueda de conexiones emocionales genuinas y de confianza que favorecen la calidad y armonía de las relaciones, lo que coincide con la descripción de la pregunta de que se centró en experiencias positivas que aumentan la calidad y armonía interpersonales. Las otras opciones son incorrectas: el “motivo de apego” se refiere a la necesidad de seguridad y protección, el “motivo de vinculación emocional” no es un término utilizado por McAdams y el “motivo de empatía” se relaciona con la capacidad de comprender y compartir emociones, pero no constituye la dimensión central de la afiliación que McAdams identificó.'),
  (216, 'La tarea de selección de Wason se compone de cuatro tarjetas, una de las cuales contiene la regla a comprobar y las otras tres presentan combinaciones de símbolos que deben ser evaluadas; esta configuración permite observar la tendencia de los participantes a responder de forma confirmatoria, lo que constituye la base de los estudios sobre razonamiento condicional y sesgos cognitivos. Las opciones A y B son incorrectas porque el número de tarjetas es mayor que dos o tres, lo que alteraría la estructura experimental; la opción D es errónea porque incluiría una tarjeta adicional que no forma parte del diseño original y cambiaría la dinámica de la prueba.'),
  (217, 'El fenómeno descrito corresponde a la extensión o sobreextensión léxica, en la cual el niño aplica una palabra a todos los miembros de una categoría semántica aun cuando no son idénticos, reflejando la etapa de adquisición del vocabulario en la que la categoría conceptual aún no está delimitada; la opción A describe precisamente este proceso. La opción B, la generalización sintáctica, se refiere a la aplicación de una estructura gramatical a contextos no habituales y no al uso de un léxico de manera indiscriminada. La C, el habla telegráfica, implica la omisión de palabras funcionales y no la ampliación de una categoría léxica. La D, palabras pivote, designa términos que actúan como anclajes en la comunicación de un grupo, pero no explican la tendencia a usar una palabra para todo un conjunto de objetos.'),
  (218, 'El fenómeno descrito corresponde a las reacciones circulares terciarias, que según la teoría de Piaget se manifiestan en la etapa de operaciones concretas tempranas (12‑18 meses) cuando el niño comienza a experimentar con nuevas conductas para observar sus efectos, tras haber consolidado las reacciones circulares secundarias (repetición de acciones que generan consecuencias agradables) y las adaptaciones; la adaptación implica la modificación de la conducta para lograr un objetivo, mientras que la asimilación se refiere a la incorporación de nueva información en esquemas existentes, y las reacciones circulares secundarias son las primeras respuestas automáticas a estímulos. Por tanto, la opción D describe el proceso de experimentación activa que caracteriza esta etapa, mientras que las demás opciones se refieren a conceptos distintos o a etapas anteriores del desarrollo.'),
  (219, 'La capacidad descrita corresponde a la metacognición, pues implica la autorregulación del propio proceso cognitivo: la persona evalúa la tarea, selecciona estrategias adecuadas y supervisa su ejecución, una función que se consolida a partir de la edad escolar y que se distingue de la mera adaptación (acomodación) o de la ayuda estructural (andamiaje) que se brinda a otro; el periodo operacional concreto se refiere a la etapa de Piaget, no a una función metacognitiva específica.'),
  (220, 'El patrón descrito —ausencia de llanto al separarse y falta de búsqueda de contacto al reencuentro— corresponde a un apego evasivo, caracterizado por la minimización de la expresión de angustia y la evitación de la proximidad con el cuidador, reflejo de una estrategia de defensa que busca protegerse de la frustración de la separación; en contraste, un apego seguro implicaría llanto y búsqueda activa, el ambivalente se manifestaría con llanto intenso y resistencia al contacto, y el desorganizado se asociaría con conductas contradictorias y confusas, por lo que las demás opciones no se ajustan al perfil observado.'),
  (221, 'La respuesta se fundamenta en la teoría del convoy social, que describe la red de apoyo social como una serie de círculos concéntricos que se estrechan o se amplían a lo largo de la vida, especialmente durante transiciones y crisis; el convoy se compone de relaciones de mayor o menor cercanía que proporcionan recursos emocionales y prácticos, y su dinámica explica cómo la calidad y la cantidad de apoyo cambian con el tiempo y con los eventos de la vida. Las otras opciones son incorrectas: la constancia socioemocional (A) se refiere a la estabilidad de las emociones y no a la estructura de apoyo; el amortiguador social (B) es un concepto de resiliencia que describe la capacidad de la red para mitigar el estrés, pero no la organización en círculos; y la teoría del ciclo vital (D) aborda el desarrollo a lo largo de la vida sin enfatizar la configuración de redes de apoyo en forma de convoy.'),
  (222, 'El reto evolutivo que Erikson asigna a la adultez emergente (aproximadamente 18‑30 años) es la etapa de “identidad vs confusión de roles”, donde el individuo debe consolidar una identidad coherente y, a partir de ella, desarrollar la capacidad de establecer relaciones íntimas; por eso la oposición que plantea es “intimidad frente a aislamiento”, pues la falta de una identidad estable conduce al aislamiento social y emocional. Las demás opciones corresponden a etapas posteriores: la generatividad frente al estancamiento es característica de la adultez media, la productividad frente a la desesperanza se refiere a la misma fase media, y la orientación al presente frente a la orientación al futuro no corresponde a ninguna de las etapas de Erikson, por lo que son incorrectas.'),
  (223, 'El razonamiento moral posconvencional, según la teoría de Kohlberg, se caracteriza por la valoración de principios éticos universales y la disposición a aceptar sacrificios personales por la justicia y la equidad; la persona actúa guiada por normas abstractas que trascienden las expectativas sociales y las reglas del grupo, lo que explica por qué en el dilema moral se priorizan los valores éticos sobre los costos personales. Las demás opciones son incorrectas: la heterocéntrica se refiere a la orientación hacia el propio interés, no a la universalidad de principios; la convencional implica la adhesión a normas sociales y la conformidad con las expectativas del grupo, lo cual contrasta con la independencia de las reglas externas que caracteriza al posconvencional; y la posformal, término no reconocido en la teoría de Kohlberg, no corresponde a ninguna etapa del desarrollo moral.'),
  (224, 'El modelo de afrontamiento adaptativo de las emociones de Berking y Whitley (2014) distingue tres componentes esenciales para el autoapoyo: autocompasión, autoestímulo y autoinstrucción activa, los cuales se integran para facilitar la regulación emocional autónoma; en cambio, el modelo de Gross se centra en la revaluación y la supresión de la respuesta emocional sin subdividirla en esos tres elementos, el modelo de Hervás enfatiza el procesamiento de la emoción a través de la atención y la reestructuración cognitiva sin incluir la autoinstrucción activa, y el modelo dialéctico‑conductual de Linehan propone la validación, la tolerancia al dolor y la regulación de la emoción, pero no los tres componentes mencionados.'),
  (225, 'El modelo ampliado de regulación emocional de Gross (2015) distingue cuatro fases secuenciales: identificación de la emoción, selección de una estrategia adecuada, implementación de dicha estrategia y monitorización del proceso; por tanto la opción A es la única que refleja fielmente esta estructura teórica, ya que cada etapa corresponde a los componentes cognitivos y conductuales que el autor asigna a la regulación emocional. Las demás alternativas presentan conceptos que no se corresponden con la taxonomía propuesta por Gross: la opción B mezcla procesos de conciencia y etiquetado con la identificación de factores causales, que no son parte del modelo; la C introduce nociones de aceptación y afrontamiento que pertenecen a enfoques de aceptación y compromiso, no a la regulación según Gross; y la D emplea términos como apertura emocional y modulación que, aunque relacionados con la emoción, no describen las etapas específicas del modelo. Todas comparten el error de confundir la terminología de otros modelos de regulación emocional con la taxonomía de Gross.'),
  (226, 'El enunciado falso es la opción D; el trastorno facticio suele aparecer en la adultez temprana, con una edad media de inicio entre los 20 y 30 años, y no se caracteriza por un inicio típico en la adolescencia, por lo que esa afirmación no se ajusta a los datos epidemiológicos del DSM‑5. En cambio, la opción A es verdadera porque el trastorno facticio, tanto cuando se presenta como auto‑impuesto como cuando se simula en otra persona, puede provocar un sufrimiento psicológico intenso y un deterioro funcional significativo, especialmente cuando el paciente busca atención médica y los recursos se destinan a un proceso de diagnóstico y tratamiento innecesarios. La opción B es correcta pues las estimaciones de prevalencia en población hospitalaria sitúan al trastorno facticio en torno al 1 %, lo que refleja su frecuencia moderada en entornos clínicos. Finalmente, la opción C también es válida porque la literatura indica que la mayoría de los casos se manifiestan en episodios intermitentes, con períodos de síntomas activos intercalados con fases de aparente normalidad, lo que dificulta su detección y contribuye a la complejidad del manejo clínico.'),
  (227, 'La opción C es falsa porque en la anorexia nerviosa los niveles de tiroxina (T4) suelen estar reducidos o dentro del rango bajo, reflejando el estado de hipometabolismo inducido por la restricción calórica y la pérdida de masa muscular, mientras que la opción A es verdadera ya que la prevalencia a los 12 meses en mujeres jóvenes se sitúa alrededor del 0,4 %; la opción B es correcta porque la mayoría de los pacientes alcanzan una remisión parcial o total a los cinco años tras el inicio del trastorno, según los estudios de seguimiento longitudinal; y la opción D es válida pues la emaciación extrema es el hallazgo físico más característico y distintivo de la AN, superando cualquier otro signo clínico.'),
  (228, 'El trastorno del apego reactivo se caracteriza por la incapacidad de establecer vínculos afectivos seguros con los cuidadores, lo que se traduce en una tendencia a evitar la cercanía emocional y a mostrar una respuesta de desapego que puede confundirse con indiferencia; por ello, los niños presentan una marcada dificultad para formar apegos selectivos, ya que su respuesta emocional se orienta hacia la auto‑protección y la independencia temprana, lo que explica la opción C. Las demás alternativas fallan porque la opción A describe una búsqueda de consuelo, lo cual es contrario a la evitación típica del trastorno; la opción B sugiere que los episodios de irritabilidad, tristeza o miedo no son evidentes, cuando en realidad son manifestaciones centrales del trastorno; y la opción D indica que expresan emociones positivas de manera adecuada a sus figuras de apego, lo cual no corresponde al patrón de desapego y falta de respuesta emocional apropiada que caracteriza a este diagnóstico.'),
  (229, 'El DSM‑5 establece que el trastorno de estrés postraumático en niños mayores de seis años requiere la presencia de al menos un síntoma de intrusión, un síntoma de evitación, dos síntomas de alteraciones cognitivas y del estado de ánimo, y dos síntomas de reactividad o alerta; la opción B refleja exactamente esta configuración, pues incluye la cantidad mínima exigida en cada dominio, garantizando la gravedad y la persistencia del trastorno. La alternativa A es insuficiente porque solo contempla un síntoma de reactividad o alerta, mientras que la opción C, aunque incluye un síntoma en cada dominio, falla en el requisito de dos síntomas en los dominios cognitivo‑emocional y de reactividad, y la opción D, al requerir solo un síntoma en el dominio de reactividad, también no cumple con el criterio de dos síntomas en ese dominio.'),
  (230, 'La opción C es la que no corresponde a una similitud entre la CIE‑11 y el DSM‑5 en el caso del autismo, porque en la CIE‑11 el autismo se clasifica con un único nivel de gravedad (leve, moderado, grave) sin subdividirlo en tres niveles, mientras que el DSM‑5 sí emplea tres niveles de apoyo (leve, moderado y severo) para describir la gravedad del trastorno; las demás opciones sí reflejan concordancias: ambos manuales utilizan el término “espectro autista”, los incluyen dentro de los trastornos del neurodesarrollo y comparten criterios nucleares de dificultades en la comunicación e interacción social recíproca y patrones restrictivos, repetitivos e inflexibles de comportamiento, intereses o actividades.'),
  (231, 'El trastorno de conducta disruptiva no se clasifica dentro de los trastornos del neurodesarrollo en la CIE‑11 porque se considera un trastorno de la conducta y de los controles de impulsividad, cuya etiología se atribuye principalmente a factores ambientales, familiares y sociales, y no a alteraciones neurobiológicas tempranas que afectan el desarrollo cognitivo, motor o del lenguaje; en cambio, el trastorno por déficit de atención/hiperactividad, el trastorno por movimientos estereotipados y el trastorno del desarrollo de la coordinación motora se incluyen en la categoría de neurodesarrollo porque implican alteraciones neurobiológicas que se manifiestan en la infancia y afectan funciones motoras, cognitivas o de atención. Las opciones A, C y D, por tanto, pertenecen a la categoría de neurodesarrollo, mientras que la opción B no.'),
  (232, 'La alteración formal del pensamiento descrita corresponde a la circunstancialidad, pues el paciente se desvía de la línea principal del discurso incorporando detalles irrelevantes y comentarios entre paréntesis que, aunque relacionados, distraen y prolongan la respuesta; esta característica se distingue de la pérdida de meta, que implicaría una incapacidad para iniciar o mantener la dirección del pensamiento, y de la habla distraída, que se refiere a interrupciones frecuentes y a la falta de coherencia entre ideas sin la presencia de un discurso excesivamente detallado; el descarrilamiento, por su parte, implica saltos abruptos entre temas sin relación, lo cual no se observa en el caso presentado.'),
  (233, 'El conjunto de experiencias de lectura del pensamiento, transmisión del pensamiento, robo del pensamiento y alienación del pensamiento constituye el delirio de control o pasividad, pues implica la creencia de que los procesos mentales están sujetos a una fuerza externa que los dirige, altera o los sustrae, característica central de este tipo de delirio; las otras opciones corresponden a categorías distintas: el delirio de suplantación se relaciona con la sensación de ser sustituido o reemplazado por otra persona, el delirio de referencia o alusión se centra en la interpretación de eventos externos como dirigidos a uno mismo, y el delirio de persecución se refiere a la creencia de ser objeto de hostilidad o vigilancia. Todas las alternativas se apartan de la noción de control interno de los procesos mentales, que es el eje definitorio del delirio de control.'),
  (234, 'El fenómeno de kindling en la depresión describe la progresiva disminución de la cantidad de estímulo externo necesario para desencadenar un episodio depresivo, de modo que, con cada episodio, la vulnerabilidad neurobiológica se incrementa y la respuesta a los factores estresantes se vuelve más automática y menos dependiente de la intensidad del evento desencadenante; por ello la opción que indica que “cantidades cada vez más pequeñas de estresores pueden disparar reacciones de una intensidad comparable a los anteriores episodios” es la que mejor refleja este mecanismo de sensibilización. Las demás alternativas son incorrectas porque la opción A sugiere una mayor dependencia del episodio previo y una menor relación con factores estresantes, lo cual contrasta con el principio de kindling; la B, al afirmar que los episodios siguen siendo más ligados a factores estresantes, también contradice la idea de que la necesidad de estímulo externo disminuye; la C, al indicar que se requieren más estresores para reapariciones, describe exactamente el fenómeno contrario al kindling.'),
  (235, 'La preocupación patológica se manifiesta como una cadena de pensamientos e imágenes cargadas de afecto negativo y relativamente incontrolable, que constituye un intento improductivo de resolución mental de problemas futuros; tal descripción coincide con la opción B, pues refleja la naturaleza obsesiva, repetitiva y sin solución de la “worry” típica del trastorno de ansiedad generalizada, donde el individuo se queda atrapado en escenarios hipotéticos sin avanzar hacia la acción. En contraste, la opción A describe una autoafirmación negativa breve y no vinculada a la búsqueda de soluciones, lo cual corresponde más a un pensamiento autocrítico transitorio que a la preocupación crónica. La opción C se refiere a una cadena de pensamientos centrada en síntomas y causas pasivas, lo que se asemeja más a la rumia depresiva que a la preocupación ansiosa, que se orienta a futuros. Finalmente, la opción D habla de creencias anómalas y extrañas con convicción elevada, característica de los trastornos delirantes, no de la preocupación patológica.'),
  (236, 'La opción B es la que describe una característica diferenciadora entre los trastornos depresivos y los bipolares: la presencia de antecedentes familiares multigeneracionales con trastornos anímicos es más frecuente en la bipolaridad, lo que sugiere un componente genético más marcado y una herencia más fuerte en este trastorno, mientras que en la depresión mayor la historia familiar suele ser menos consistente y no tan específica. La alternativa A es incorrecta porque los antidepresivos tricíclicos son más efectivos en la depresión mayor que en la bipolaridad, donde su uso puede precipitar episodios maníacos; la opción C es errónea pues las quejas somáticas tienden a ser más frecuentes en la depresión mayor, no en la bipolaridad; y la D es falsa porque los episodios depresivos periparto son más típicos de la depresión posparto, un subtipo de depresión mayor, y no de la bipolaridad.'),
  (237, 'El especificador “grave” del trastorno de depresión mayor en el DSM‑5 se emplea cuando la sintomatología produce una interferencia notable en el funcionamiento social, ocupacional o en otras áreas importantes, y se acompaña de al menos tres de los criterios de gravedad (pérdida de peso >5 %, insomnio o hipersomnia, fatiga, sentimientos de inutilidad, disminución de la concentración, pensamientos recurrentes de muerte o suicidio); por ello la opción C describe correctamente el uso clínico de este especificador. La alternativa A es errónea porque la remisión total se define por la ausencia de síntomas significativos durante al menos dos semanas, no tres meses, y no constituye un especificador diagnóstico. La opción B confunde el especificador “con características psicóticas” con la presencia de alucinaciones y delirios congruentes con el estado de ánimo; en realidad, la psicopatía puede ser congruente o incongruente y no se limita a la congruencia. La respuesta D es incorrecta porque el especificador “con características mixtas” se refiere a la coexistencia de síntomas de depresión y de manía o hipomanía, no simplemente a la presencia de síntomas de ansiedad la mayoría de los días.'),
  (238, 'La Teoría de Redes (TR) sostiene que la depresión se constituye por la interacción dinámica entre síntomas, por lo que el propio entramado de síntomas y sus retroalimentaciones constituye el problema clínico, sin recurrir a una entidad latente subyacente; por tanto, la opción B refleja fielmente este enfoque, pues enfatiza que los síntomas y sus interacciones son el núcleo del trastorno, en contraste con la visión clásica de un “trastorno” o “enfermedad” que los produce. Las alternativas A y C se basan en la concepción tradicional de un trastorno latente y en la utilización de sistemas politéticos de clasificación como el DSM o la CIE, conceptos que la TR rechaza al no considerar una entidad subyacente. La opción D, aunque menciona comorbilidad, la interpreta como la presencia de entidades esenciales que enlazan redes de síntomas, lo cual contrasta con la visión de la TR que ve la comorbilidad como la superposición de redes interactivas sin entidades esenciales.'),
  (239, 'En el DSM‑5 la categoría “Otro trastorno bipolar y trastorno relacionado especificado” abarca presentaciones que no cumplen los criterios completos de trastorno bipolar I, II, ciclotimia ni de trastorno depresivo mayor, pero que presentan episodios mixtos o de hipomanía con características atípicas; por ello la opción A, “Depresión con hipomanía mixta”, describe una sintomatología que sí se contempla dentro de esta categoría, ya que se trata de un episodio mixto con predominio depresivo y presencia de hipomanía, que se clasifica como trastorno bipolar y trastorno relacionado especificado. En cambio, la opción B describe un episodio hipomaníaco aislado sin antecedente depresivo, que corresponde a un trastorno bipolar I o II según la duración y la presencia de episodios mayores; la opción C, “Ciclotimia de corta duración”, se refiere a un trastorno ciclotímico que, aunque breve, sigue los criterios de ciclotimia y no se incluye en la categoría especificada; y la opción D, “Episodios hipomaníacos de corta duración (23 días) y episodios de depresión”, corresponde a un trastorno bipolar I o II con episodios cortos de hipomanía y episodios depresivos, por lo que tampoco pertenece a la categoría de trastorno bipolar y trastorno relacionado especificado.'),
  (240, 'La opción B es la que distingue clínicamente a los trastornos bipolares de las depresiones unipolares, pues los síntomas atípicos (alteración del apetito y sueño, sensibilidad al rechazo, fatiga y sensación de pesadez) aparecen con mayor frecuencia en el espectro bipolar, especialmente en la fase depresiva, y su presencia suele asociarse a una mayor probabilidad de episodios maníacos; en contraste, la duración de los episodios depresivos (A) no es un criterio diferenciador, ya que ambos trastornos pueden presentar episodios prolongados; la edad de inicio (C) es variable y no se limita al trastorno bipolar, pues las depresiones unipolares pueden comenzar en la adolescencia o adultez temprana; el retraso psicomotor (D) es más típico de la depresión unipolar, pero su ausencia no excluye el trastorno bipolar, por lo que no constituye una característica diferencial definitiva.'),
  (241, 'El trastorno ciclotímico se caracteriza por fluctuaciones crónicas de humor que alternan episodios hipomaníacos leves y episodios depresivos leves durante al menos dos años (en niños, un año), pero ninguno de los episodios alcanza la intensidad de un episodio maníaco o depresivo completo; por ello la edad típica de aparición es temprana, con un promedio de 6 años y medio, cuando el desarrollo neurobiológico y la maduración emocional favorecen la expresión de estos cambios de humor; las otras opciones son erróneas porque la opción A describe la duración de los síntomas en el trastorno depresivo mayor, no en el ciclotímico; la opción B confunde los criterios de episodios maníacos o depresivos con los de ciclotimia, que solo requiere episodios hipomaníacos y depresivos leves, no completos; y la opción C sobre la prevalencia por sexo carece de respaldo epidemiológico, ya que la frecuencia no muestra una diferencia significativa entre hombres y mujeres.'),
  (242, 'La opción A es la que corresponde a la teoría de Öst sobre la adquisición de los trastornos fóbicos, pues sostiene que la mayoría de las fobias se originan a partir de experiencias directas de miedo intenso, donde el condicionamiento clásico (exposición a un estímulo temido seguido de una respuesta de ansiedad) es el mecanismo predominante; este proceso explica la asociación entre el estímulo y la respuesta de evitación que caracteriza a la fobia. Las demás alternativas son erróneas porque la opción B confunde el aprendizaje vicario, que es más relevante en la formación de fobias sociales y no en la mayoría de los casos fóbicos; la opción C atribuye la adquisición a la transmisión de información negativa, un proceso que, aunque puede influir, no es el principal mecanismo propuesto por Öst; y la opción D asume una falta de memoria del origen, lo cual no se sostiene en la teoría de Öst, que enfatiza la importancia de la experiencia directa como fuente de la fobia.'),
  (243, 'La opción D, pensamiento dicotómico, no se considera una creencia disfuncional característica del trastorno obsesivo‑compulsivo según el grupo de trabajo sobre cogniciones obsesivas compulsivas (OCCWG, 1997, 2005); el pensamiento dicotómico se relaciona más con trastornos de la personalidad y de la ansiedad generalizada, pero no constituye un esquema cognitivo central del TOC, que se basa en la sobrevaloración de la importancia del pensamiento (A), la responsabilidad exagerada (B) y la intolerancia a la incertidumbre (C), todos los cuales son reconocidos por el OCCWG como pilares de la interpretación cognitiva del TOC. Las opciones A, B y C son correctas porque reflejan las tres categorías de creencias disfuncionales identificadas por el grupo de trabajo, mientras que la opción D se excluye por no pertenecer a esa clasificación específica.'),
  (244, 'El DSM‑5 clasifica el trastorno de acumulación como un trastorno de la personalidad, no como un especificador del trastorno obsesivo‑compulsivo de la personalidad; por ello la opción A es errónea. La definición de la categoría exige que el individuo experimente una dificultad persistente y significativa para deshacerse o renunciar a sus posesiones, independientemente de la cantidad de objetos que posea, lo que corresponde a la opción D. La opción B confunde el trastorno con la adquisición compulsiva de objetos, cuando la acumulación puede ocurrir sin una adquisición excesiva o sin que las posesiones excedan el espacio disponible. La opción C sugiere que la motivación sea el deterioro cognitivo, pero el DSM‑5 indica que la motivación puede ser multifactorial (miedo a perder información, necesidad de control, etc.) y no se limita al deterioro cognitivo.'),
  (245, 'El DSM‑5 enumera como síntomas de un ataque de pánico la presencia de al menos cuatro de los siguientes ocho: sensación de muerte inminente o pérdida de control, taquicardia, sudoración, temblor, sensación de falta de aire, dolor torácico, náuseas, mareo, sensación de irrealidad o despersonalización, miedo a volverse loco o a morir, y sensación de que algo terrible ocurrirá. La opción C reúne simultáneamente “escalofríos o sensación de calor” (síntoma fisiológico) y “miedo a perder el control o a volverse loco” (síntoma cognitivo), ambos elementos que figuran en la lista diagnóstica, por lo que constituye un conjunto válido de manifestaciones de un ataque de pánico. En cambio, la A incluye “gritos o llanto incontrolables”, que no son síntomas típicos del ataque de pánico según el DSM‑5; la B menciona “parestesias y dolor de cabeza”, donde la parestesia puede aparecer en ataques, pero el dolor de cabeza no es un criterio esencial y la combinación no cumple con la lista; la D menciona “tensión muscular”, que sí puede presentarse, pero la “sensación de dificultad para respirar o asfixia” es un síntoma, sin embargo la opción D no incluye el miedo a perder el control o a volverse loco, que es un componente clave, por lo que no constituye la respuesta más completa.'),
  (246, 'El DSM‑5 establece que el trastorno de ansiedad social se caracteriza por un miedo intenso a ser evaluado negativamente en situaciones sociales, que provoca evitación o malestar severo; el criterio A exige que el miedo sea desproporcionado a la amenaza real, el criterio B exige que la ansiedad sea persistente durante al menos seis meses, y el criterio C contempla la preocupación por la propia actuación o por mostrar síntomas de ansiedad que serán valorados negativamente; en cambio, el reconocimiento de que el miedo es excesivo o irracional no forma parte de los criterios diagnósticos, sino que es una posible percepción del paciente y no un requisito clínico. Por tanto, la opción A no corresponde a un criterio del DSM‑5, mientras que las demás opciones sí lo cumplen; las opciones B, C y D son correctas porque describen la desproporcionalidad, la duración y la preocupación por la evaluación negativa, respectivamente.'),
  (247, 'En los modelos cognitivos de Reiss la fobia se explica principalmente como un proceso de aprendizaje y mantenimiento en el que el individuo mantiene expectativas de peligro y de ansiedad ante la presencia de un estímulo o situación específica; dichas expectativas actúan como un filtro cognitivo que anticipa la amenaza y genera la respuesta de evitación, lo que refuerza la conducta fóbica y la mantiene a lo largo del tiempo. Las demás opciones son incorrectas porque la autofocalización de la atención (A) se asocia más con la ansiedad generalizada y la atención selectiva, no con la especificidad de la fobia; la intolerancia a la incertidumbre y a la activación fisiológica (B) es un factor de riesgo general para la ansiedad pero no constituye el núcleo explicativo de la fobia según Reiss; y las metacogniciones (D) se relacionan con la regulación del pensamiento y la percepción de control, pero no son el elemento central que sustenta la adquisición y el mantenimiento de la fobia en estos modelos.'),
  (248, 'El trastorno de ansiedad generalizada (TAG) según el DSM‑5 se caracteriza por preocupación excesiva y persistente que se manifiesta en al menos tres de los síntomas físicos o cognitivos listados; la irritabilidad se incluye explícitamente como uno de esos síntomas, reflejando la tensión y la dificultad para controlar la respuesta emocional ante la ansiedad crónica, mientras que la sensación de pérdida de control, las palpitaciones y el dolor torácico, aunque pueden aparecer en la comorbilidad o en otros trastornos de ansiedad, no están enumerados como criterios específicos del TAG y, por tanto, no cumplen la condición de diagnóstico.'),
  (249, 'La afirmación falsa es la A: el DSM‑5 ha eliminado la categoría diagnóstica de “fetichismo travestista” y la ha reemplazado por “trastorno de travestismo sexual”, que se caracteriza por la necesidad de vestirse con ropa del sexo opuesto para obtener excitación sexual, sin que la presencia de objetos o prendas específicas sea un requisito; por ello la categoría original de fetichismo travestista ya no existe. En cambio, la opción B es verdadera porque el trastorno de fetichismo incluye el parcialismo, que se refiere a la excitación sexual derivada de partes específicas del cuerpo, y ambos se agrupan bajo el mismo diagnóstico. La C también es correcta, pues el trastorno masoquista sexual puede especificarse con asfixiofilia (la excitación sexual derivada de la restricción de la respiración). Finalmente, la D es cierta: el trastorno de travestismo sexual puede especificarse con fetichismo cuando la excitación se centra en objetos o prendas específicas. Las opciones B, C y D comparten la veracidad porque describen correctamente las especificaciones y subtipos reconocidos en el DSM‑5, mientras que la A es errónea por referirse a una categoría que el manual ya no contempla.'),
  (250, 'La opción d es falsa porque, en el DSM‑5, la disfunción sexual inducida por sustancias/medicamentos sigue existiendo como categoría específica, con criterios que distinguen la causa farmacológica de la disfunción; la propuesta de eliminarla no se realizó. En cambio, la opción a es verdadera: el trastorno por aversión al sexo dejó de ser una categoría independiente y se integró dentro de la disfunción sexual, reflejando la tendencia a consolidar los trastornos de respuesta sexual. La opción b también es correcta, pues el DSM‑5 agrupa los trastornos de respuesta sexual y los trastornos de dolor sexual bajo la categoría de disfunciones sexuales, simplificando la clasificación. La opción c es cierta, ya que el DSM‑5 mantiene dos categorías distintas para la reducción o ausencia del deseo sexual, una para mujeres (trastorno de deseo sexual hipoactivo) y otra para hombres (trastorno de deseo sexual hipoactivo masculino), reconociendo diferencias biológicas y psicológicas entre géneros.'),
  (251, 'La CIE‑11 organiza las condiciones sexuales en el capítulo 17 “Condiciones relacionadas con la salud sexual”, donde se incluyen los trastornos de la función sexual, los trastornos de la respuesta sexual, los trastornos de la identidad de género y los trastornos de la orientación sexual, así como los trastornos de la conducta sexual. El término “trastornos parafílicos” se refiere a patrones de comportamiento sexual que involucran fantasías, impulsos o actos que causan angustia o daño a la persona o a terceros y que, en la CIE‑11, se clasifican dentro del capítulo 18 “Trastornos de la conducta sexual” y no bajo la denominación de “Condiciones relacionadas con la salud sexual”. Por tanto, la opción B es la que no se incluye en el capítulo 17. Las demás alternativas sí pertenecen a ese capítulo: la discordancia de género (identidad de género) se clasifica en la sección de trastornos de la identidad de género; las disfunciones sexuales y los trastornos sexuales por dolor se encuentran dentro de los trastornos de la función sexual y de la respuesta sexual, respectivamente.'),
  (252, 'El trastorno esquizofreniforme comparte con la esquizofrenia los mismos criterios diagnósticos, pero se diferencia en la duración y en la intensidad de ciertos síntomas; por ello la convicción, extensión y presión de las ideas (es decir, la intensidad de la delirio) no son mayores en el trastorno esquizofreniforme, sino que suelen ser comparables o incluso menores, lo que hace que la opción C sea la que no se ajusta a la realidad clínica. Las demás opciones describen aspectos que sí distinguen al trastorno esquizofreniforme: el inicio suele ser más rápido (A), la fase prodrómica es muy breve (B) y los síntomas negativos tienden a ser menos pronunciados (D), por lo que se corresponden con la descripción oficial.'),
  (253, 'En la fase residual de la esquizofrenia la sintomatología se caracteriza por la desaparición o reducción de los síntomas positivos, mientras que los síntomas negativos y la alteración afectiva suelen mantenerse; por ello la afirmación de que predomina la presencia de síntomas positivos es la única que no concuerda con el perfil clínico de esta etapa, ya que en la fase residual los positivos son escasos o ausentes y la afectividad puede manifestarse con apatía o anhedonia. Las demás opciones describen aspectos típicos de la fase residual: la persistencia de síntomas positivos leves acompañados de crítica (opción B), la presencia significativa de alteraciones afectivas (opción C) y la alta probabilidad de recaída (hasta un 80 % en los primeros cinco años) (opción D).'),
  (254, 'El modelo de Zubin y la relación biopsicosocial sostiene que la esquizofrenia es un trastorno multifactorial, donde la interacción entre predisposición genética, factores ambientales y procesos psicológicos explica la aparición y evolución del cuadro; por ello la opción C, que afirma que el trastorno tiene un curso crónico, no corresponde a una de sus aseveraciones principales, ya que Zubin enfatiza la variabilidad y la posibilidad de episodios agudos y remisiones, no un curso estrictamente crónico; las demás opciones, aunque no son las más destacadas, sí reflejan aspectos del modelo: la A subraya la insuficiencia de los modelos parciales y la necesidad de una visión integral; la B reconoce que la esquizofrenia no es siempre tan devastadora como se pensaba, y la D indica la utilidad de identificar marcadores de vulnerabilidad para prevenir episodios, todo ello alineado con la perspectiva biopsicosocial de Zubin.'),
  (255, 'La variante logopénica de la afasia primaria progresiva se caracteriza por un deterioro progresivo de la repetición, tanto de palabras como de frases, mientras que la producción espontánea y la comprensión permanecen relativamente preservadas en las primeras etapas; por ello la opción D es la que refleja la característica principal, ya que la repetición es el dominio más afectado y el hallazgo clínico más distintivo de esta variante. Las demás alternativas se refieren a síntomas más típicos de otras formas de afasia: la opción A describe errores fonológicos que suelen aparecer en la afasia anómica o la variante logopénica tardía, pero no son el rasgo definitorio inicial; la B señala la anomia, característica de la variante anómica, no de la logopénica; y la C menciona la ausencia de agramatismo puro, lo cual es cierto, pero no constituye una característica principal, pues la presencia o ausencia de agramatismo no distingue la variante logopénica de otras.'),
  (256, 'La demencia por cuerpos de Lewy se caracteriza por la pérdida progresiva de neuronas dopaminérgicas en el área tegmental y de neuronas colinérgicas en el prosencéfalo basal, lo que explica los síntomas motores, cognitivos y de fluctuación de la atención típicos de esta entidad; la enfermedad de Parkinson comparte exactamente el mismo patrón de degeneración neuronal, por lo que la opción C recoge ambas patologías que presentan dichas alteraciones. La opción A es incorrecta porque la enfermedad de Huntington presenta pérdida de neuronas en el núcleo caudado y putamen, con afectación colinérgica menor y sin pérdida significativa de neuronas dopaminérgicas en el área tegmental; la opción B es errónea porque la demencia vascular no implica una pérdida específica de neuronas dopaminérgicas o colinérgicas, sino lesiones isquémicas focales; la opción D es también incorrecta porque, aunque la demencia por cuerpos de Lewy incluye la pérdida dopaminérgica y colinérgica, la demencia vascular no comparte ese patrón neurobiológico.'),
  (257, 'El deterioro marcado de las funciones ejecutivas, la lentitud del procesamiento y los déficits atencionales son la firma clínica de la demencia asociada a la enfermedad de Huntington, donde la lesión de los ganglios basales y la corteza prefrontal provoca una pérdida de la inhibición, la perseverancia y la toma de decisiones; además, la progresiva pérdida de neuronas en el núcleo caudado y el putamen explica el enlentecimiento cognitivo y la dificultad atencional. En contraste, la parálisis supranuclear progresiva se caracteriza principalmente por alteraciones del control ocular y la marcha, con menos énfasis en la disfunción ejecutiva; la demencia frontotemporal y la enfermedad de Pick, aunque presentan alteraciones de la personalidad y la conducta, suelen mostrar un deterioro más pronunciado en la conducta social y la impulsividad que en la atención y el procesamiento enlentecido, por lo que las opciones B, C y D no describen el cuadro clínico más definitorio.'),
  (258, 'La causa adquirida potencialmente reversible en las demencias es la enfermedad tiroidea, ya que alteraciones de la función tiroidea, especialmente el hipotiroidismo, pueden provocar deterioro cognitivo que mejora con el tratamiento hormonal; en contraste, la atrofia olivo‑ponto‑cerebelosa (A) es una degeneración neurodegenerativa progresiva, la enfermedad de Binswanger (C) corresponde a demencia vascular con cambios de la médula blanca que no se revierten con intervención, y la enfermedad priónica familiar (D) es una patología priónica fatal e irreversible; por tanto, solo la opción B presenta reversibilidad clínica.'),
  (259, 'La propuesta alternativa de la sección III del DSM‑5 para los trastornos de la personalidad contempla, como criterio A, la valoración de la capacidad de establecer y mantener relaciones interpersonales satisfactorias, lo que incluye la empatía y la intimidad; estos elementos son esenciales para la integración social y la regulación emocional, y su alteración constituye un componente central de la patología de la personalidad. Las demás opciones son incorrectas porque el autoconcepto y la autodirección (opción B) se ubican en el criterio B (identidad y autocontrol), no en el funcionamiento interpersonal; las relaciones interpersonales y la desregulación emocional (opción C) combinan un criterio correcto con uno que pertenece al criterio C (regulación emocional), por lo que no se ajustan al criterio A; y la identidad y la autodirección (opción D) corresponden al criterio B, no al de funcionamiento interpersonal.'),
  (260, 'El cannabis, cuando su consumo inicia antes de los 16 años, ha sido asociado en estudios epidemiológicos con un mayor riesgo de tumores de testículo en varones, probablemente por la alteración de la función endocrina y la estimulación de receptores cannabinoides que influyen en la proliferación celular testicular; en contraste, la cocaína, el LSD y el alcohol no presentan evidencia robusta de relación con este tipo de neoplasia, y su consumo precoz se vincula principalmente con alteraciones neuropsiquiátricas y cardiovasculares, no con tumores germinales testiculares, por lo que las opciones A, B y C son erróneas.'),
  (261, 'El trastorno de pica se caracteriza por la ingesta persistente de sustancias no nutritivas, cuya naturaleza suele cambiar con la edad y la disponibilidad, lo que explica la opción C; la definición del DSM‑5 subraya que las sustancias ingeridas pueden variar según la etapa de desarrollo y el entorno, reflejando la flexibilidad del patrón de consumo. Las demás alternativas son erróneas: la A confunde pica con el consumo de alimentos no nutritivos, cuando en realidad se trata de sustancias no alimentarias; la B es incorrecta porque el DSM‑5 no establece una edad mínima de 1 año, sino que el diagnóstico puede aplicarse a cualquier edad siempre que se cumplan los criterios; y la D es falsa, pues la epidemiología muestra mayor prevalencia en mujeres, no en varones.'),
  (262, 'El DSM‑5 especifica que el trastorno específico del aprendizaje se manifiesta en dificultades en la lectura (dislexia), la escritura (disgrafía) o las matemáticas (discalculia); por tanto, la opción que no corresponde a una de esas áreas académicas es la que menciona la expresión oral, ya que la disfluencia o el trastorno del habla no forman parte de la clasificación de aprendizaje. Las demás opciones (lectura, expresión escrita y matemática) sí están contempladas como subaptitudes académicas afectadas en el diagnóstico del trastorno específico del aprendizaje.'),
  (263, 'La CIE‑11 establece que el criterio de peso corporal significativamente bajo en la anorexia nerviosa se fija en un IMC inferior a 18,5 kg/m² en adultos y en un IMC por debajo del percentil 5 para la edad en niños; este umbral refleja la gravedad clínica y la necesidad de intervención, diferenciándose de los percentiles 7 y 8 que se emplean en otras clasificaciones y que no cumplen con la especificación de la CIE‑11, y de los valores de 18 y 17,5 que tampoco corresponden a la normativa actual, por lo que las opciones A, B y D son incorrectas.'),
  (264, 'La disociación primaria, tal y como la describe el modelo jerárquico de van der Hart, van der Kolk y Boon, corresponde al nivel más bajo de disociación y se caracteriza por la fragmentación del procesamiento de la información del evento traumático; el individuo percibe el acontecimiento, pero la información se almacena de forma discontinua y no se integra en la narrativa coherente, lo que impide la consolidación de la memoria y la experiencia emocional asociada. Por tanto, la opción A refleja fielmente esta definición, mientras que la B y la D describen una experiencia de percibir el evento con o sin impacto emocional completo, lo cual se relaciona con la disociación secundaria o terciaria, no primaria; la C, que habla de identidades separadas, corresponde a la disociación de la identidad, un nivel superior del modelo.'),
  (265, 'Según la teoría de Kihlstrom, los trastornos disociativos se conceptualizan principalmente como alteraciones en la memoria, ya que la disociación implica la ruptura de la continuidad de la experiencia y la fragmentación de la información autobiográfica, lo que se traduce en amnesia específica, pérdida de recuerdos y dificultades para integrar episodios pasados en una narrativa coherente; por ello la opción B se ajusta a la descripción teórica de Kihlstrom. Las demás alternativas son erróneas: la identidad (A) se relaciona con trastornos disociativos de identidad, pero la teoría de Kihlstrom no la ubica como eje central; la integración (C) y la representación (D) son conceptos más generales que pueden aplicarse a distintos trastornos, pero no reflejan la especificidad de la memoria que caracteriza la visión de Kihlstrom.'),
  (266, 'El enunciado se refiere al modelo de condicionamiento clásico aplicado a la PTSD, donde la agresión sexual constituye un estímulo incondicionado que provoca una respuesta de miedo y ansiedad; los estímulos asociados (cuerpos, lugares, sonidos) se convierten en condicionados que activan la respuesta de miedo, por lo que las víctimas presentan mayor temor y ansiedad que quienes no han sufrido la agresión, lo que hace que la opción A sea la única que refleja la relación entre el condicionamiento y la respuesta emocional; las demás alternativas son incorrectas porque la exposición repetida a la agresión (B) no reduce la magnitud del miedo sino que puede reforzar la respuesta de miedo; la ansiedad anticipatoria (C) sí propicia la evitación de situaciones lúdicas, pues la anticipación de la amenaza lleva a la evitación, y la opción D confunde la naturaleza de los estímulos, pues las situaciones ansiógenas se relacionan con estímulos condicionados, no con estímulos incondicionados a la violación.'),
  (267, 'El síndrome de las piernas inquietas se caracteriza por una sensación de malestar que suele localizarse en las extremidades inferiores y, en ocasiones, se extiende a los brazos o tronco; esta sensación provoca una necesidad irresistible de mover las piernas y suele empeorar en reposo, especialmente por la tarde y la noche, lo que interfiere de manera significativa en la iniciación y mantenimiento del sueño, por lo que la opción A describe fielmente la presentación clínica y el impacto en la calidad del sueño; las demás opciones son incorrectas: la opción B confunde la relación con la fatiga diurna, pues el empeoramiento nocturno no depende de la fatiga sino de la circadianidad y el reposo; la opción C es errónea porque los síntomas se alivian con el movimiento, no se agravan; y la opción D presenta la conducta opuesta a la real, ya que los pacientes buscan el movimiento para aliviar los síntomas, no lo evitan.'),
  (268, 'La Oficina sobre Drogas y Crimen de Naciones Unidas (2016) indica que aproximadamente el 5 % de la población mundial de 16 a 64 años ha consumido alguna droga ilegal en el último año, lo que equivale a una de cada veinte personas en ese rango etario; esta cifra se deriva de la estimación global de 1 000 millones de usuarios frente a una población de 20 000 millones, y refleja la prevalencia de consumo de sustancias ilícitas en la población adulta. Las demás opciones son incorrectas porque subestiman la prevalencia real: la opción B (una de cada 50) corresponde a un 2 % y no coincide con los datos de la ONU, la opción C (una de cada 100) sugiere un 1 % y la opción D (una de cada 200) un 0,5 %, ambos valores demasiado bajos para la población global de usuarios de drogas ilegales.'),
  (269, 'La desrealización se caracteriza por una percepción subjetiva de que el entorno es extraño, irreal o distorsionado; la persona experimenta una pérdida de la vividez y coherencia del mundo que la rodea, pero no posee una convicción delirante ni una interpretación personal de cambios en el entorno, por lo que la opción B es falsa; las demás alternativas describen fielmente la naturaleza de la desrealización: la A señala el cambio subjetivo de la realidad, la C indica que puede coexistir con la despersonalización y aparecer en la población general, y la D la clasifica como una reacción disociativa que implica una pérdida subjetiva de la realidad.'),
  (270, 'El descriptor que el DSM‑5 emplea para los síntomas negativos de la esquizofrenia que implican una reducción tanto en la cantidad como en la calidad del discurso es la alogia; se trata de una pobreza del habla y del contenido del habla que refleja la disminución de la producción verbal y la falta de fluidez y coherencia en la expresión, característica de la fase negativa de la esquizofrenia. La opción A, “Pararrespuesta”, no corresponde a ningún término clínico reconocido en el DSM‑5 y parece una confusión con “parálisis de la respuesta” que no describe la pobreza del habla. La alternativa C, “Ilogicidad”, se refiere a la incoherencia del pensamiento, no a la reducción del habla. Por último, la D, “Mutismo selectivo”, es un trastorno de ansiedad infantil que implica la falta de habla en situaciones específicas, no la pobreza del discurso asociada a la esquizofrenia.'),
  (271, 'La respuesta es la opción B, ya que la elación se define clínicamente como un estado de ánimo anormalmente elevado, con exaltación de la autoestima, energía y optimismo, típicamente asociado a episodios maníacos o hipomaníacos; su descripción coincide con la de un sentimiento exagerado y desproporcionado de bienestar que el enunciado describe. Las demás opciones son incorrectas: la A, paratimia, se refiere a la alteración de la percepción del valor o la importancia de los objetos, no al estado de ánimo; la C, labilidad, implica fluctuaciones rápidas y descontroladas entre estados de ánimo, pero no necesariamente un sentimiento de bienestar elevado; y la D, hiperarousal, es un término más general que describe una activación fisiológica y psicológica aumentada, sin especificar la cualidad de bienestar o el contexto de trastornos del estado de ánimo.'),
  (272, 'El modelo etiológico multifactorial de Vanderlinden y Vandereycken sostiene que la disociación surge cuando la experiencia traumática supera la capacidad de procesamiento del individuo, y que la autoimagen negativa constituye un factor de riesgo esencial porque reduce la cohesión del yo y facilita la fragmentación de la identidad; por tanto, la opción C es la que mejor explica la predisposición a síntomas disociativos. La edad mayor (A) no se relaciona directamente con la vulnerabilidad disociativa, pues la disociación puede presentarse en cualquier edad y la literatura no la vincula con un mayor riesgo. La relación estrecha entre atacante y víctima (B) puede aumentar el impacto emocional, pero el modelo enfatiza la percepción interna del yo más que la proximidad del agresor. Un nivel intelectual bajo (D) tampoco se considera un factor determinante en la teoría de Vanderlinden y Vandereycken, ya que la disociación no depende de la capacidad cognitiva general.'),
  (273, 'La afirmación falsa es la A: los somatizadores e hipocondríacos no presentan una mayor probabilidad de atribuir psicológicamente sus síntomas que personas con otros trastornos psicológicos; al contrario, la literatura transdiagnóstica indica que tienden a interpretar sus síntomas como indicativos de una enfermedad física y a minimizar la influencia de factores psicológicos, lo que se refleja en una menor tendencia a la atribución psicológica. En contraste, la opción B es coherente con la evidencia que muestra que la sobrevaloración de los pensamientos relacionados con la salud y la enfermedad constituye un factor cognitivo central en la generación y mantenimiento de la somatización y la hipocondría. La opción C describe correctamente la fusión cognitivo‑conductual, donde el pensamiento y la acción se entrelazan de manera probabilística, fenómeno frecuente en estos trastornos. Finalmente, la opción D se alinea con la propuesta de la amplificación somatosensorial, una dimensión que se ha identificado como común en la somatización y la hipocondría, pues implica una mayor sensibilidad y atención a las sensaciones corporales.'),
  (274, 'La propuesta de Salkovskis y Warwick sobre la hipocondría se centra en la interpretación cognitiva de los síntomas físicos y la percepción de la amenaza que estos representan; los factores que identifican son la valoración de la gravedad de las consecuencias de una enfermedad, la percepción de la propia capacidad de controlar o interferir en la enfermedad y la evaluación de la disponibilidad de recursos externos (como el acceso a servicios de salud) para gestionar la situación, pues estos elementos influyen directamente en la ansiedad somática y la búsqueda de atención médica. En cambio, la opción A se refiere a creencias disfuncionales sobre el pensamiento repetitivo de enfermedad, un concepto que pertenece al modelo de la ansiedad generalizada o a la teoría de la rumia, pero no es uno de los constructos cognitivos que Salkovskis y Warwick incluyen en su modelo de hipocondría; por lo tanto, no corresponde a los factores cognitivos propuestos por estos autores.'),
  (275, 'La opción C es la que no pertenece al esquema de la terapia cognitivo‑conductual afectiva de Woolfolk y Allen (2006), pues su enfoque se centra en la exposición a situaciones temidas y a pensamientos e imágenes sobre la enfermedad, una técnica típica de la terapia de exposición para trastornos de ansiedad, no en la intervención somatizante que la propuesta de Woolfolk y Allen describe; allí se privilegian la reestructuración cognitiva, la regulación emocional, el entrenamiento de habilidades interpersonales y conductuales, y la reducción del rol de enfermo, sin recurrir a la exposición directa a temores. Las demás alternativas sí coinciden con los módulos de la terapia: la A contempla la regulación cognitivo‑emocional, la B aborda la interacción social y la disminución del rol de enfermo, y la D se refiere al entrenamiento en habilidades conductuales, todos componentes esenciales del modelo de tratamiento somatizante de Woolfolk y Allen.'),
  (276, 'El diagnóstico de trastorno de síntomas neurológicos funcionales (TSNF) en el DSM‑5 permite la coexistencia de una enfermedad neurológica; por tanto la opción A es falsa. Cuando los criterios se cumplen simultáneamente para el TSNF y para el trastorno de síntomas somáticos, el DSM‑5 exige que se realicen ambos diagnósticos, ya que cada uno describe un patrón distinto de presentación y de respuesta al tratamiento, lo que justifica la respuesta B. En cuanto al trastorno facticio y la simulación, el DSM‑5 establece que el TSNF se diagnostica cuando los síntomas no son fingidos, pero no exige la demostración de que no se fingen; simplemente se excluye la intención de engaño, por lo que la opción C es incorrecta. Finalmente, la presencia de síntomas depresivos primarios como tristeza y anhedonia, acompañados de quejas de pesadez general de los miembros, no constituye por sí sola un TSNF; se requiere evidencia de incongruencia funcional y de la presencia de síntomas neurológicos que no se explican por una enfermedad médica, por lo que la opción D también es errónea.'),
  (277, 'El cuadro descrito corresponde a un trastorno delirante de tipo somático, ya que la persona mantiene una convicción fija e inamovible de padecer una enfermedad grave, pese a evidencia objetiva en su contra, y la creencia se presenta como un delirio (pensamiento de falsa naturaleza, no basado en la realidad) que no se reconoce como producto de un trastorno mental; la presencia de síntomas somáticos leves y ansiedad elevada es secundaria al delirio, pero no constituye la base diagnóstica. El trastorno por síntomas somáticos (B) implicaría una preocupación excesiva por los síntomas y su significado, pero la creencia no sería delirante y la persona sí reconocería la posibilidad de un origen psicológico; el trastorno de conversión (A) se caracteriza por síntomas neurológicos inexplicables sin intención de engaño, sin la fijación delirante de enfermedad; el trastorno de ansiedad por la enfermedad (D) se basa en una preocupación excesiva y temor real de enfermarse, pero la persona mantiene la conciencia de que la ansiedad es irracional y no presenta una convicción delirante absoluta.'),
  (278, 'El DSM‑5 clasifica la discapacidad intelectual según el nivel de funcionamiento adaptativo; la descripción de un niño con comprensión muy limitada de la comunicación simbólica y dependencia total para el cuidado físico, la salud y la seguridad corresponde a un nivel de discapacidad intelectual profunda, ya que implica una severa incapacidad para la autonomía diaria y la comunicación, características que exceden el umbral de gravedad de la categoría grave y que se alinean con el criterio de “dependencia total” y “comprensión simbólica muy limitada”. Las opciones A y B se refieren a grados de funcionamiento adaptativo mucho más altos (leve y moderado) y no incluyen la dependencia total descrita; la opción C, grave, implica una autonomía reducida pero no tan total como la profunda, por lo que no coincide con la descripción clínica dada.'),
  (279, 'El sistema dopaminérgico que emana del área tegmental ventral constituye el principal eje de modulación difusa del tronco encefálico y su función central es la regulación del sistema de recompensa, la motivación y la ejecución de conductas adaptativas, lo que explica la asociación indicada; la dopamina liberada en la corteza y el estriado facilita la plasticidad y la toma de decisiones orientadas a la consecución de objetivos, características propias de la conducta adaptativa. Las demás opciones presentan errores conceptuales: la opción A confunde el locus coeruleus, que es noradrenérgico y regula la vigilia y la atención, no la conducta emocional; la B asigna al complejo pontomesencéfalo la serotonina, cuando la serotonina se origina en los núcleos del rafe y su función principal es la regulación del estado de ánimo, no la del complejo pontomesencéfalo; la D atribuye la colina a los núcleos del rafe, mientras que la colinergia se origina en el núcleo basal del tallo y su participación se relaciona más con la atención y la memoria de trabajo que con el aprendizaje y la formación de recuerdos.'),
  (280, 'La prosopagnosia se origina por daño en el giro fusiforme, zona del lóbulo temporal inferior que integra la información visual de rostros y constituye la “zona de fusión” donde se codifican las características faciales de manera holística; la lesión de esta área impide la identificación de rostros aunque la visión y la memoria sean intactas. El giro lingual (A) se asocia principalmente con procesamiento de letras y palabras, el giro frontal inferior (B) participa en funciones ejecutivas y de control de impulsos, y el giro postcentral (D) corresponde al área somatosensorial primaria; ninguno de estos sitios está implicado en la representación visual de rostros, por lo que sus lesiones no generan prosopagnosia.'),
  (281, 'El circuito dopaminérgico mesolímbico se origina en el área tegmental ventral (ATV), donde se encuentran los cuerpos celulares de las neuronas dopaminérgicas que proyectan hacia el núcleo accumbens y otras estructuras limbicas; esta vía es la que subyace a la motivación y el placer, y su disfunción se asocia con la adicción y la esquizofrenia, por lo que la opción C describe la localización anatómica correcta. Las demás alternativas son incorrectas porque el núcleo arqueado (A) y el núcleo paraventricular (B) son núcleos hipotalámicos que participan en la regulación endocrina y no en la transmisión dopaminérgica; el rafe (D) alberga neuronas serotonérgicas, no dopaminérgicas, por lo que no puede ser la fuente de este circuito.'),
  (282, 'La frecuencia dominante de 30 Hz corresponde a la banda gamma, que se observa principalmente durante la actividad cognitiva activa, la atención sostenida y el procesamiento de información sensorial; por tanto, el registro de 30 Hz es más probable cuando la persona está realizando el examen, en la que su cerebro procesa estímulos y tareas cognitivas, generando actividad gamma. Las demás opciones describen estados de reposo o sueño en los que la actividad cerebral se desplaza hacia bandas de menor frecuencia: la relajación con ojos cerrados y vigilia produce mayor actividad alfa (8‑12 Hz), la fase 2 del sueño se caracteriza por ondas theta y la fase 4 por ondas delta, por lo que la presencia de 30 Hz sería atípica en esos contextos.'),
  (283, 'La corteza perirrinal se ha vinculado de manera más consistente con la familiaridad mnésica, ya que su actividad se incrementa cuando se reconoce un estímulo sin necesidad de recuperar detalles específicos, y su lesión produce déficits en la discriminación de familiaridad sin afectar la memoria de contexto; en contraste, los cuerpos mamilares están implicados en la consolidación de la memoria episódica y su daño produce amnesia anterógrada, el núcleo anterior del tálamo participa en la integración sensorial y la memoria de trabajo, y el cuerno de Amón (CA1-CA3) es esencial para la formación de recuerdos episódicos y la recuperación de información detallada, no para la sensación de familiaridad.'),
  (284, 'El componente N400, una deflexión negativa que aparece aproximadamente 400 ms después de la presentación de un estímulo lingüístico, está estrechamente vinculado al procesamiento semántico porque su amplitud aumenta cuando el significado de una palabra no encaja con el contexto semántico previo, reflejando la integración y la actualización de la representación conceptual; la evidencia neurofisiológica muestra que la activación de áreas temporales y frontales asociadas al lenguaje se modula según la congruencia semántica, lo que explica la mayor sensibilidad del N400 a la información semántica que a la sintaxis, la prosodia o la mera detección de símbolos lingüísticos, los cuales están más relacionados con componentes como el P600, el P300 o las respuestas de atención temprana, respectivamente.'),
  (285, 'La opción A es la única que describe adecuadamente el papel de las neuronas noradrenérgicas y serotoninérgicas del tronco encefálico en la regulación del sueño REM: el sistema de retículo pontino, compuesto por neuronas de la sustancia negra y la zona raphe, produce un tono de inhibición que suprime la actividad de las neuronas del núcleo reticular pontino que generan la fase REM, y su inactivación durante el sueño permite la aparición de la actividad característica de esta fase; en cambio, la opción B confunde la melatonina con la fase de inicio del sueño, pues su principal función es regular el ritmo circadiano y no actúa directamente sobre los sistemas de sueño‑despertar; la opción C atribuye erróneamente a la adenosina un efecto excitador sobre los sistemas moduladores, cuando su acción es inhibidora y favorece la consolidación del sueño; y la opción D presenta una relación causal incorrecta, pues la expresión de genes inmediatos y mitocondriales aumenta principalmente en la fase de vigilia, no en el sueño, donde el metabolismo cerebral se reduce.'),
  (286, 'La respuesta que describe correctamente la función del fascículo tectoespinal es la opción D, ya que este tracto, que se origina en el tecto del tronco encefálico y decusa en la médula espinal, integra la información visual y vestibular para generar la respuesta orientada que dirige la cabeza y los ojos hacia un estímulo, un mecanismo esencial para la coordinación visuo‑motor; las demás alternativas son erróneas: la hipercinesia del balismo no se relaciona con la disfunción del área motora suplementaria (A), los fascículos vestibuloespinales no “potencian” los reflejos antigravitatorios sino que transmiten la información vestibular a la médula (B), y una lesión en la parte superior del sistema motor no produce simultáneamente hipertonía, arreflexia y espasticidad, pues la hipotonía y la arreflexia se asocian con lesiones inferiores, mientras que la hipertonía y la espasticidad son características de lesiones superiores (C).'),
  (287, 'La afirmación correcta es la A, pues la teoría de la teoría de la mente indica que la interpretación de estados mentales ajenos depende de la interacción entre la corteza prefrontal medial, que integra la información social y la toma de decisiones, y la unión temporoparietal, que procesa la perspectiva y la diferenciación entre el yo y el otro; estudios de lesiones y neuroimagen corroboran que daño en estas áreas deteriora la capacidad de “leer” la mente. La opción B es incorrecta porque la empatía involucra, además de la corteza cingulada anterior, la corteza insular y la amígdala, y la prefrontal no es la única región; la opción C es errónea pues la primera impresión se asocia principalmente con la amígdala y la corteza prefrontal ventromedial, no con el área de Broca; y la D falla al ubicar las neuronas espejo en la corteza premotora y parietal, no en la temporal superior, y su actividad sí muestra potencial de aprendizaje.'),
  (288, 'La teoría del sexismo ambivalente distingue dos formas de sesgo de género: la hostil, que se manifiesta en actitudes y comportamientos explícitamente negativos y discriminatorios contra las mujeres, y la benevolente, que se expresa mediante juicios paternalistas o condescendientes que, aunque no son abiertamente hostiles, refuerzan la subordinación de las mujeres al justificar su inferioridad o la necesidad de protección; esta distinción permite explicar la coexistencia de prejuicios explícitos e implícitos dentro de la misma actitud. Las demás opciones son incorrectas: la alternativa A confunde el sexismo con la homofobia, mientras que la C y la D se refieren a categorías de discriminación que no corresponden a la clasificación de la teoría del sexismo ambivalente.'),
  (289, 'El modelo de racismo simbólico, tal y como se describe en la literatura de psicología social, se fundamenta en dos dimensiones interrelacionadas: una componente afectiva que se manifiesta como hostilidad o aversión negativa hacia los grupos minoritarios, y una componente cognitiva que se expresa en la defensa de la ética protestante del trabajo, es decir, la creencia en la responsabilidad individual y la meritocracia como justificación de la desigualdad social; por ello la opción A recoge precisamente estos dos elementos. Las demás alternativas se apartan de la definición teórica: la B confunde la discriminación pasiva con la hostilidad afectiva, la C mezcla prejuicio implícito con una socialización positiva que no forma parte del modelo, y la D introduce procesos de activación automática y procesamiento consciente, que corresponden a mecanismos de prejuicio inconsciente, pero no a los pilares del racismo simbólico.'),
  (290, 'Según el modelo de covariación de Kelley, la interpretación de una conducta se basa en la interacción de tres criterios: consenso, distintividad y consistencia. Cuando los tres criterios se presentan en valores altos, la explicación que se deriva es la de una causa situacional, es decir, que la conducta se debe al estímulo o a la situación que la provoca; por tanto, la respuesta que se corresponde con la lógica del modelo es la opción A, que identifica al estímulo como la causa atribuida. Las demás alternativas resultan incorrectas porque la personalidad del sujeto (B) se asocia a la interpretación cuando el consenso es bajo, la distintividad alta y la consistencia alta, lo que indica una causa interna; la opción C, que habla de la situación/circunstancia, es redundante con la opción A y no aporta una distinción conceptual; y la opción D, el estado emocional, se relaciona con la interpretación cuando la distintividad es baja y el consenso alto, lo que no se cumple en el caso planteado.'),
  (291, 'El modelo MODE de Fazio (1990) sostiene que la conducta se produce cuando la motivación y la oportunidad se combinan; la motivación se activa cuando la actitud es fuerte y la oportunidad está presente, y la conducta se produce cuando la motivación supera la oportunidad o viceversa, según la ruta de procesamiento (espontáneo o elaborado). Por tanto, la opción que refleja la esencia del modelo es la D, pues el MODE distingue explícitamente entre procesamiento espontáneo (rápido, automático) y procesamiento elaborado (más reflexivo y deliberado), integrándolos como dos vías que dependen de la motivación y la oportunidad. Las demás alternativas son erróneas: la A confunde el modelo con la teoría de la acción razonada, que sí incorpora normas subjetivas y objetivas, pero el MODE no las contempla; la B lo sitúa dentro de la teoría expectativa‑valor, lo cual no corresponde, ya que el MODE se basa en la interacción entre motivación y oportunidad, no en expectativas y valores; y la C lo describe como trifactorial, cuando en realidad es un modelo bidimensional que combina dos factores (motivación y oportunidad) y dos rutas de procesamiento, no tres factores independientes.'),
  (292, 'En la fase de investigación del modelo de socialización grupal de Levine y Moreland, el proceso consiste en que los individuos recluten información sobre el grupo y luego la reconocen como relevante para su identidad y comportamiento; por ello la opción B, “Reclutamiento y reconocimiento”, es la que refleja fielmente los dos pasos esenciales de esta etapa, pues el reclutamiento implica la búsqueda activa de datos sobre el grupo y el reconocimiento implica la valoración y aceptación de esos datos como parte de la propia identidad grupal. Las demás alternativas son incorrectas: la A se refiere a procesos cognitivos de adaptación de la información (asimilación y acomodación) que no describen la dinámica de la investigación grupal; la C menciona “tradición y remembranza”, conceptos que pertenecen a la fase de internalización y no a la investigación; y la D, “Exploración y verificación”, aunque suena similar, emplea términos que se aplican más a la fase de evaluación crítica del grupo y no a la recopilación y reconocimiento inicial de información.'),
  (293, 'La dimensión que recoge la atracción individual hacia la tarea del grupo corresponde a la “Atracción hacia la tarea”, una de las cuatro dimensiones del Cuestionario de Ambiente Grupal de Carron y colaboradores, que evalúa el grado de compromiso y motivación que cada miembro siente por la actividad grupal; las otras opciones se refieren a conceptos distintos: la similitud percibida intragrupal (A) se relaciona con la cohesión interna, la categorización grupal compartida (B) con la identidad grupal y la percepción de pertenencia, y las relaciones comunes en el grupo (C) al aspecto de la cohesión interpersonal, por lo que no corresponden a la dimensión solicitada.'),
  (294, 'El experimento “azul‑verde” de Moscovici y colaboradores mostró que la exposición a un estímulo visual (el color azul) puede inducir una respuesta fisiológica o conductual que no corresponde al estímulo real, fenómeno conocido como conversión; en el estudio los participantes mostraron una respuesta de “color verde” cuando se les presentaba el azul, evidenciando la transformación de la percepción sensorial en una respuesta distinta, lo que confirma la hipótesis de conversión. Las demás opciones son inadecuadas: la metacontraste se refiere a la percepción de contraste entre estímulos consecutivos, no a la sustitución de un color por otro; la reactancia describe la resistencia a la persuasión, no la alteración sensorial; y la inferencia correspondiente implica la interpretación de estímulos en función de su relación causal, lo cual no explica la sustitución perceptual observada en el experimento.'),
  (295, 'En la clasificación de Matarazzo (1984) los “inmunógenos conductuales” son aquellas conductas y hábitos de vida que actúan como factores protectores, reduciendo la morbilidad y la mortalidad prematura; por ello la opción A se ajusta a la definición de factores de riesgo inverso que favorecen la salud. Las demás alternativas son incorrectas: la B, “patógenos conductuales”, se refiere a conductas que aumentan el riesgo de enfermedad, lo que contrasta con la función protectora de los inmunógenos; la C, “condiciones de vida”, es un término más amplio que incluye factores socioeconómicos y ambientales, pero no especifica la función inmunológica; y la D, “prevención terciaria”, implica intervenciones tras la aparición de la enfermedad, no la prevención de la morbilidad prematura.'),
  (296, 'La teoría de la acción planeada de Ajzen (1988) sostiene que la intención de realizar una conducta se determina por tres constructos: la actitud hacia la conducta, la norma subjetiva y el control conductual percibido; la actitud refleja la valoración positiva o negativa que el individuo tiene respecto a la conducta específica, la norma subjetiva incorpora la presión social percibida y el control conductual percibido indica la percepción de facilidad o dificultad para ejecutar la acción, factores que interactúan para predecir la intención y, por ende, la conducta; las demás opciones son incorrectas porque el apoyo social (B) se relaciona más con la influencia de la red de relaciones, el sentido de coherencia (C) es un concepto de la teoría de la autodeterminación que no forma parte de la teoría de la acción planeada, y la discriminación del riesgo (D) corresponde a la evaluación de riesgos en la teoría de la protección, no a la teoría de la acción planeada.'),
  (297, 'El modelo de cinco factores de personalidad, también conocido como el Big Five, fue desarrollado por McCrae y Costa a partir de la investigación de la taxonomía de la personalidad de John Tukey y la clasificación de los rasgos de Raymond Cattell; sin embargo, la propuesta de que la personalidad se puede describir con cinco dimensiones básicas se consolidó en la década de 1990 cuando el psicólogo estadounidense Robert R. McCrae y el psicólogo canadiense Paul T. Costa, Jr. formalizaron el modelo, inspirándose en los trabajos de Cattell y de otros autores que habían identificado estructuras de rasgos de longitud similar. En la pregunta, la opción A menciona a Tupes y Christal, quienes también propusieron un modelo de cinco factores (el modelo de cinco factores de la personalidad de la Universidad de Chicago), por lo que es la respuesta que coincide con la descripción de la pregunta. La opción B, Cattell, desarrolló un modelo de 16 factores, no de cinco; la opción C, Eysenck, propuso un modelo de tres factores (psicopatía, neuroticismo y extraversión), y la opción D, Ashton, es conocido por su trabajo en la escala NEO-PI-R, pero no por proponer un modelo de cinco factores por sí mismo. Por lo tanto, las opciones B, C y D son incorrectas porque cada uno propone un número distinto de factores o no es el autor principal del modelo de cinco factores.'),
  (298, 'El modelo de estructura del intelecto de Guilford se basa en la idea de que la inteligencia se compone de 15 factores básicos que se combinan en un sistema de 5 factores de contenido, 4 de proceso y 6 de producto, dando lugar a 120 aptitudes distintas (5×4×6); por tanto la opción B refleja fielmente la propuesta original de Guilford, que distingue entre dimensiones de contenido, proceso y producto, y no solo entre tipos generales o específicos de inteligencia. Las alternativas A, C y D son incorrectas porque A confunde el número de factores con el número de aptitudes, C reduce la complejidad del modelo a una clasificación demasiado simplista y D atribuye categorías que pertenecen a la teoría de la inteligencia creativa de Torrance, no al modelo de Guilford.'),
  (299, 'El modelo atribucional de Weiner distingue tres dimensiones esenciales para la interpretación de causas: el locus de causalidad (interno o externo), la estabilidad (si la causa es permanente o transitoria) y la controlabilidad (si la causa está bajo el control del individuo), pues estas tres variables interactúan para determinar la respuesta emocional y la motivación de la persona ante un evento; las demás opciones presentan conceptos que no corresponden al marco teórico de Weiner, ya que la distinción de “distintividad, consistencia y consenso” se refiere a la teoría de la consistencia de Heider, “estabilidad, globalidad e internalidad” no son categorías del modelo atribucional, y “intencionalidad, estabilidad y especificidad” mezclan la dimensión de intencionalidad (no parte de Weiner) con la especificidad, que no forma parte de su triada; por tanto, solo la alternativa d reúne las tres dimensiones propuestas por Weiner.'),
  (300, 'Según la teoría componencial de Sternberg, la adquisición del conocimiento se estructura en tres procesos selectivos que permiten organizar la información de manera coherente y útil: la codificación selectiva, que implica la identificación y registro de los datos relevantes; la combinación selectiva, que consiste en la integración de estos datos en esquemas mentales; y la comparación selectiva, que permite contrastar la nueva información con los conocimientos previos para evaluar su validez y utilidad; por lo tanto, la opción C describe adecuadamente estos componentes. Las demás alternativas no corresponden a la teoría de Sternberg: la opción A menciona reconocimiento, monitorización y comprensión, que son procesos de procesamiento cognitivo pero no se presentan como componentes de la adquisición del conocimiento en su modelo; la opción B incluye codificación, inferencia y aplicación, términos que pertenecen a la teoría de la inteligencia de Guilford y no a la componencial de Sternberg; y la opción D combina inferencia, selección y decisión selectiva, que se relacionan más con la toma de decisiones y la resolución de problemas que con la adquisición del conocimiento.'),
  (301, 'La opción d) es la única que describe correctamente la distinción entre las teorías de entidad y las de incrementalidad; la teoría de entidad sostiene que los rasgos de personalidad son fijos y no pueden modificarse, mientras que la incremental (o de desarrollo) postula que los rasgos pueden crecer o cambiar con el tiempo y la experiencia, por lo que la afirmación de que “los atributos personales se poseen en una cantidad fija y no pueden cambiarse” corresponde a la teoría de entidad, no a la incremental. Las demás alternativas son incorrectas porque la a) invierte la relación entre la teoría de entidad y la incremental, atribuyendo la posibilidad de cambio a la entidad; la b) presenta una idea contradictoria, pues las teorías implícitas son creencias que sí pueden ser influenciadas y modificadas por la información y la experiencia; y la c) confunde los términos, pues la incrementalidad no implica una cantidad fija ni la imposibilidad de cambio, sino la percepción de que los rasgos pueden incrementarse.'),
  (302, 'El modelo propuesto por Mischel y Shoda sostiene que la conducta se explica mejor cuando se integran tanto los procesos cognitivo‑afectivos internos (expectativas, metas, autoeficacia) como las características específicas de la situación (estímulos, normas sociales, contingencias), lo que permite comprender la variabilidad situacional de la personalidad; Bandura enfatiza la autoeficacia pero no la interacción situación‑personalidad, Eysenck y los Eysenck se centran en rasgos biológicos y no en la dinámica cognitivo‑afectiva, y Gray describe un modelo de sistemas de motivación (depleción y búsqueda) sin incorporar explícitamente las características situacionales, por lo que solo la opción B refleja la integración de ambos componentes.'),
  (303, 'El modelo de la integración frontal‑parietal de la inteligencia se fundamenta en la hipótesis de que las funciones ejecutivas y la planificación, controladas por la corteza prefrontal, se coordinan con la capacidad de procesamiento de información y la memoria de trabajo, que se localiza mayormente en la corteza parietal; esta interacción explica la variabilidad individual en tareas de razonamiento y resolución de problemas, y se ha corroborado mediante estudios de neuroimagen y de lesión cerebral, lo que lo convierte en la propuesta que busca explicar las bases biológicas de la inteligencia; las demás opciones se basan en combinaciones de regiones que, aunque participan en procesos cognitivos, no han sido identificadas como el eje principal de la integración funcional que explica la inteligencia, por lo que se consideran incorrectas.'),
  (304, 'La creatividad se mide con mayor precisión en los tests de pensamiento divergente, donde se solicita al participante generar la mayor cantidad posible de respuestas distintas a una misma provocación; la puntuación se desglosa en fluidez (número de ideas), flexibilidad (categorización de ideas en dominios distintos) y originalidad (raridad de las respuestas), lo que permite cuantificar la capacidad generativa y la variedad de la producción creativa; en contraste, los tests de pensamiento convergente evalúan la capacidad de converger a una única solución correcta, sin valorar la diversidad de respuestas, por lo que no se obtienen índices de fluidez, flexibilidad u originalidad; los inventarios de juicios de productos miden la valoración de la creatividad de obras ya existentes, no la producción creativa del evaluado; y los inventarios de actitudes e intereses se centran en disposiciones y preferencias, sin incluir medidas de generación de ideas.'),
  (305, 'La asociación entre el factor p y las dimensiones del modelo de cinco factores se fundamenta en la evidencia empírica que muestra que la dimensión de Neuroticismo, que refleja la tendencia a experimentar emociones negativas y vulnerabilidad al estrés, es la que más fuertemente predice la gravedad y la frecuencia de los trastornos psicológicos; la dimensión de Responsabilidad (conocida también como Conciencia o Conscienciosidad) se relaciona con la regulación del comportamiento y la resistencia a la disfunción, mientras que la dimensión de Amabilidad/cordialidad, que captura la tendencia a la cooperación y la empatía, también se ha vinculado a menores niveles de psicopatología, especialmente en la prevención de conductas antisociales y trastornos de la personalidad. Por tanto, la combinación de Neuroticismo, Responsabilidad y Amabilidad constituye la única que abarca tanto la vulnerabilidad como la resiliencia, explicando la correlación con el factor p. Las demás opciones fallan porque omiten la dimensión de Responsabilidad (A y D) o la de Amabilidad (C), y al incluir dimensiones como la apertura a la experiencia o la extraversión, que tienen correlaciones más débiles o incluso negativas con la psicopatología, se pierde la precisión del modelo predictivo del factor p.'),
  (306, 'El concepto de cociente intelectual fue introducido por William Stern, quien en 1912 propuso la fórmula QI = (edad mental / edad cronológica) × 100 para cuantificar la inteligencia relativa de un individuo; esta propuesta permitió la comparación estandarizada de resultados de pruebas de inteligencia y sentó las bases de la psicología de la inteligencia moderna. James McKeen Cattell, aunque pionero en la psicología experimental y en la medición de la inteligencia, desarrolló la escala de Cattell y la prueba de inteligencia de Cattell-Binet, pero no introdujo el cociente; Alfred Binet, junto con Théodore Simon, elaboró la primera prueba de inteligencia práctica, pero su enfoque se centró en la identificación de necesidades educativas, no en el cálculo de un cociente; Louis Terman adaptó la prueba de Binet a la población estadounidense y la estandarizó, pero también no fue el originador del concepto de cociente.'),
  (307, 'En la comparación entre el modelo PEN (psicótico, egocéntrico, neurótico) y el modelo de los cinco grandes, el eje de psicoticismo de PEN se alinea con la dimensión de apertura a la experiencia y la impulsividad, y su nivel elevado se asocia con menor grado de cordialidad (afinidad) y responsabilidad (conformidad) en el modelo de los cinco grandes; por tanto, la opción que indica que un mayor psicoticismo se corresponde con una menor cordialidad y responsabilidad es la que refleja la correlación empírica y teórica entre ambos modelos. Las demás opciones son incorrectas porque presentan relaciones inversas o inconsistentes con la literatura comparativa: la opción B sugiere una mayor cordialidad y responsabilidad con alto psicoticismo, lo cual contradice la evidencia de que el psicoticismo implica impulsividad y falta de conformidad; la opción C relaciona un menor psicoticismo con menor cordialidad y responsabilidad, lo que no corresponde a la tendencia de que la baja impulsividad se asocie con mayor conformidad y sociabilidad; y la opción D mezcla una mayor cordialidad con menor responsabilidad, lo cual no refleja la correlación establecida entre psicoticismo y las dimensiones de apertura y responsabilidad.'),
  (308, 'La dimensión del modelo de los cinco grandes que recoge mejor la calidad de la interacción social es la cordialidad, ya que esta se refiere a la tendencia a mostrar amabilidad, cortesía y afecto en las relaciones interpersonales, lo que se traduce en una interacción social positiva y cooperativa; la cordialidad se asocia con la habilidad de establecer vínculos afectivos y de confianza, aspectos esenciales para la calidad de la interacción. Por el contrario, la extraversión (B) se centra en la energía, la sociabilidad y la búsqueda de estimulación, pero no necesariamente implica una interacción social de calidad; la estabilidad emocional (C) se relaciona con la regulación de las emociones y la resiliencia, sin abordar directamente la calidad de las relaciones; y la responsabilidad (D) se refiere a la organización, el cumplimiento de obligaciones y la autodisciplina, tampoco vinculada con la calidad de la interacción social.'),
  (309, 'El BAVQ‑R (Beliefs About Voice Questionnaire – Revised) es el único instrumento que incorpora explícitamente la evaluación de los patrones de afrontamiento frente a las alucinaciones auditivas, diferenciando entre resistencia (estrategias de evasión o negación) y compromiso (aceptación y adaptación), lo que permite valorar la relación subjetiva del paciente con las voces y su impacto funcional; en contraste, la LHSH‑R se centra en la frecuencia y contenido de las alucinaciones sin explorar la respuesta conductual, la PSY‑RATS mide la gravedad y la intensidad de los síntomas psicóticos sin incluir dimensiones de afrontamiento, y la VPDS evalúa la percepción de poder de la voz sobre el individuo, pero no aborda las estrategias de resistencia o compromiso.'),
  (310, 'El muestreo intersesional se refiere a la selección de momentos entre sesiones para la observación de la conducta o el proceso terapéutico; por lo tanto, implica decidir cuántas sesiones se observarán (B), el período durante el cual se llevará a cabo la observación (A) y los criterios que determinan cuándo se inicia la observación (C), ya que estos elementos definen el marco temporal y la frecuencia de la recolección de datos entre encuentros. La opción D, que indica “intervalos en que se divide la sesión de observación”, corresponde a la división interna de una sesión única (muestreo intra­sesional) y no a la planificación entre sesiones, por lo que no pertenece a este tipo de muestreo. Las demás alternativas son pertinentes al muestreo intersesional y, por tanto, no cumplen con la condición de exclusión.'),
  (311, 'La fuente de error que proviene del propio sistema de observación es el tipo de registro elegido (opción C), ya que el método de registro (por ejemplo, registro continuo, intervalos, eventos, etc.) determina la sensibilidad y la especificidad de la medición, la posibilidad de omitir comportamientos breves o de sobrecargar al observador con datos irrelevantes, y afecta directamente la validez interna del procedimiento; en cambio, el grado de entrenamiento (A) y la participación (B) son factores de error del observador, no del sistema, mientras que las expectativas creadas (D) corresponden a sesgos cognitivos del observador que influyen en la interpretación de los datos, no en la estructura del sistema de observación.'),
  (312, 'El índice que se obtiene en todas las escalas de inteligencia de Wechsler (WPSSI‑IV, WISC‑V y WAIS‑IV) es el Índice de Memoria de Trabajo, pues cada versión incluye la subprueba de Memoria de Trabajo (por ejemplo, “Digit Span” y “Letter‑Number Sequencing” en el WAIS‑IV; “Digit Span” y “Letter‑Number Sequencing” en el WISC‑V; y “Digit Span” y “Letter‑Number Sequencing” en el WPSSI‑IV), y el puntaje combinado de estas subpruebas constituye el índice de Memoria de Trabajo que se reporta en los informes. Los demás índices no aparecen en todas las versiones: el Índice Visoespacial (A) solo se incluye en la WISC‑V y WAIS‑IV, pero no en el WPSSI‑IV; el Índice de Razonamiento Perceptivo (B) se presenta en la WISC‑V y WAIS‑IV, pero el WPSSI‑IV utiliza el Índice de Razonamiento Perceptivo y el de Razonamiento Fluido, no el de Memoria de Trabajo; y el Índice de Razonamiento Fluido (D) es propio de la WISC‑V y WAIS‑IV, pero el WPSSI‑IV no lo incluye, por lo que las opciones A, B y D son incorrectas.'),
  (313, 'La entrevista semiestructurada diseñada específicamente para la evaluación del trastorno obsesivo‑compulsivo en la infancia y adolescencia es la Escala Yale–Brown de Obsesiones y Compulsiones para niños (CY‑BOCS) de Scahill y colaboradores; su formato permite al clínico explorar la frecuencia, intensidad y el impacto funcional de los síntomas, además de incluir una sección de observación directa, lo que la convierte en la herramienta de referencia para la población pediátrica. El Inventario de Obsesiones de Leyton, versión para niños (LOI‑CV), el Inventario Obsesivo‑Compulsivo de Maudsley (MOCI) y el Inventario Obsesivo‑Compulsivo para niños (CHOCI) son cuestionarios autoadministrados, no entrevistas semiestructuradas, y por tanto carecen de la interacción clínica y la valoración directa que caracteriza a la CY‑BOCS.'),
  (314, 'La opción B es la adecuada porque, en la evaluación de escolares de 9 años, las preguntas que comienzan con “¿por qué?” suelen generar respuestas que reflejan la interpretación del niño más que su experiencia real; la estructura de la pregunta invita a la elaboración de explicaciones que pueden no corresponder a la realidad del niño y favorece la sugestión, lo que compromete la validez de la información obtenida. En cambio, la opción A, que propone usar preferentemente preguntas cerradas, limita la expresión del niño y reduce la oportunidad de explorar sus procesos internos, mientras que la opción C, aunque valiosa en otras edades, no es la indicación principal para ajustar la entrevista en este caso, pues el uso de juegos no verbales puede resultar más útil en niños más pequeños o con dificultades de lenguaje. La opción D, que sugiere emplear alternativas de respuesta para reducir la sugestión, se aplica a entrevistas con adultos o en contextos donde se busca evitar la influencia de la respuesta; en niños de 9 años, la técnica de preguntas abiertas y el uso de lenguaje sencillo son más pertinentes para obtener información fiable.'),
  (315, 'En el análisis de las historias proyectadas del CAT se valora la forma en que el niño interpreta y organiza los estímulos visuales, centrándose en la identificación de figuras, la presencia de conflictos internos y la manifestación de ansiedad, pues estos elementos revelan la estructura del mundo interno y los mecanismos de defensa; la opción A, “preferencias e identificaciones”, no forma parte de la codificación estándar del CAT, ya que el protocolo se centra en la interpretación de la trama y la expresión de conflictos, no en la valoración de gustos personales, por lo que las demás opciones (B, C y D) sí se incluyen en la evaluación de contenido, cada una aportando datos sobre la dinámica emocional y cognitiva del niño.'),
  (316, 'La opción C es la que corresponde al MMPI‑A, la versión adaptada para adolescentes, porque incluye escalas suplementarias específicas para la evaluación de consumo de sustancias (alcohol y drogas) y de inmadurez, aspectos que son más prevalentes y clínicamente relevantes en la población juvenil que en la adulta; además, el MMPI‑A mantiene las 10 escalas clínicas básicas del MMPI‑R, pero añade estas dos escalas suplementarias para cubrir dimensiones de riesgo y desarrollo típicas de la adolescencia. La alternativa A es incorrecta porque el potencial agresivo no se añade como escala nueva en la versión adolescente, sino que se mantiene la escala de agresión presente en el MMPI‑R; la B es errónea porque el MMPI‑A no dispone de 11 escalas clínicas ni de 5 escalas para relaciones personales y 5 para tratamiento, sino que conserva las 10 escalas clínicas y añade las dos suplementarias; la D resulta falsa porque el número de ítems del MMPI‑A no se reduce a 300, sino que se mantiene en 567, con la inclusión de las escalas suplementarias.'),
  (317, 'El Inventario de Depresión Infantil (CDI) de Kovác es el único de los cuestionarios citados que dispone de una versión abreviada, el CDI‑R, que mantiene la validez y la sensibilidad diagnóstica con un número reducido de ítems, lo que facilita su aplicación en entornos clínicos y escolares sin perder la capacidad de detectar síntomas depresivos en niños; la Escala de Depresión para Niños (CDS) de Lang y Tisher, aunque es una herramienta válida, no ofrece una forma reducida; el Cuestionario Educativo Clínico: Ansiedad y Depresión (CECAD) de Lozano y colaboradores se centra en la ansiedad y la depresión en contextos educativos pero no cuenta con una versión abreviada; y la Escala de Sintomatología Depresiva para Maestros de Educación Primaria (ESDM 612) de Domènech y Polaino está diseñada específicamente para la observación docente y tampoco dispone de una forma abreviada.'),
  (318, 'El proyecto vital según Mahoney se concibe como una evaluación narrativa que se centra en la reconstrucción de la vida del individuo a través de la elaboración de un relato estructurado en tres etapas: la “recomposición de la vida”, el “viaje por la vida” y la “revisión de la vida”, donde se revisan los significados y las metas; la propuesta enfatiza la interpretación hermenéutica del texto, pues el psicólogo debe analizar los símbolos, las metáforas y los patrones de significado que el paciente emplea para dar sentido a su historia, sin limitarse a la mera descripción de hechos. Por ello la opción C, que indica que la evaluación no impone restricciones al texto pero sí sí cuenta con criterios hermenéuticos, describe fielmente el método. Las demás alternativas son erróneas: la A confunde el proyecto vital con la elaboración de un relato de identidad personal, cuando la identidad se deriva del análisis de la narrativa, no es el objetivo principal; la B presenta una estructura incorrecta y una terminología inexacta (“revisar la revisión vital” no corresponde al esquema de Mahoney); la D introduce categorías de afectos transitivas e intransitivas que no forman parte de la metodología de Mahoney, la cual se basa en la interpretación del relato y no en la clasificación de afectos.'),
  (319, 'En la observación psicológica, los productos de conducta que se obtienen a partir de ejecuciones que el sujeto ya realizó en el pasado se denominan “medidas no reactivas”, pues no implican la reactivación de la conducta en el momento de la evaluación y se basan en la memoria o en registros anteriores; la distinción con las medidas retrospectivas y retroactivas radica en que estas últimas se refieren a la valoración de la conducta a través de la propia memoria del individuo o de terceros, mientras que las no reactivas se obtienen de datos ya registrados o de registros de la conducta sin requerir la participación activa del sujeto en el momento de la medición. Las opciones A y C se confunden con la idea de “retroceso” o “memoria” y, aunque pueden parecer similares, no describen la característica de no requerir la reactivación de la conducta; la opción B, “medidas prospectivas”, se refiere a la valoración de conductas futuras, lo cual es incompatible con la descripción de productos de conducta pasados.'),
  (320, 'El pensamiento‑en‑voz‑alta se define como la verbalización continua de los propios pensamientos durante la realización de una tarea; por ello el método de recogida más habitual es el monólogo continuo, en el que el participante habla todo lo que le ocurre en la mente mientras se registra la conducta, lo que permite correlacionar contenido verbal con acción en tiempo real; las demás opciones son erróneas porque la técnica no es una forma estructurada de autoinforme (A), pues no se basa en un cuestionario predefinido; la categorización de contenido verbal no constituye el procedimiento más complejo del registro de eventos (B), ya que la complejidad reside en la sincronía entre pensamiento y acción, no en la clasificación posterior; y la verbalización no ocurre independientemente de la conducta informada (C), pues su propósito es precisamente describir los procesos cognitivos que acompañan la acción observada.'),
  (321, 'La descripción que el entrevistador hace sobre lo que está ocurriendo en un momento concreto en relación con el entrevistado se denomina inmediatez, pues se refiere a la observación y registro de la dinámica presente, sin intermediar por interpretaciones o juicios posteriores; la inmediatez permite captar la experiencia actual del proceso de entrevista y sirve como base para la valoración clínica. La interpretación implica una valoración subjetiva de los contenidos, la confrontación consiste en desafiar al entrevistado y el encuadre se refiere al marco estructural de la sesión, por lo que las opciones B, C y D no corresponden a la definición solicitada.'),
  (322, 'La subfase en la que el evaluador prepara la situación de evaluación y da instrucciones al sujeto corresponde a la **Recogida de información: recopilación de información pertinente (c)**, pues en la Guía de Proceso de Evaluación (GAP) se define que esta etapa implica la organización de los instrumentos, la configuración del entorno y la explicación de los procedimientos al evaluado, asegurando la validez y la fiabilidad de los datos que se obtendrán; las opciones A y B describen fases posteriores (operativización de hipótesis y análisis de demandas, respectivamente), donde ya se dispone de la información y se procede a su interpretación, mientras que la opción D corresponde a la fase de discusión y toma de decisiones, que se sitúa al final del proceso.'),
  (323, 'El instrumento diseñado para evaluar la disociación motora entre ambas manos es el Omega, pues consiste en una serie de tareas en las que el sujeto debe realizar movimientos simultáneos y asimétricos con cada mano, permitiendo observar la coordinación y la independencia de los movimientos, algo esencial en la valoración de la función motora y la integración sensoriomotriz; el Rotor de persecución mide la capacidad de seguimiento visual y la coordinación ojo-mano, el Test de punteado evalúa la percepción visual y la atención, y el Tromómetro de barra se utiliza para medir la fuerza y la resistencia muscular, por lo que las demás opciones no se centran en la disociación de movimientos bilaterales.'),
  (324, 'El índice de velocidad de procesamiento del WAIS‑IV se evalúa mediante la subprueba Búsqueda de símbolos, que mide la rapidez con la que el individuo puede codificar, procesar y responder a estímulos visuales bajo presión de tiempo; la puntuación se obtiene contando los símbolos correctamente identificados en un tiempo limitado, lo que refleja la velocidad de procesamiento cognitivo. La opción A, Dígitos, pertenece al índice de memoria de trabajo, pues evalúa la capacidad de retener y manipular información auditiva. La opción C, Figuras incompletas, corresponde al índice de razonamiento perceptivo, ya que exige la identificación de patrones visuales. La opción D, Matrices, forma parte del índice de razonamiento verbal, pues se centra en la resolución de problemas abstractos mediante la selección de la figura que completa una serie.'),
  (325, 'Las escalas de apreciación son instrumentos estructurados que permiten al observador cuantificar, calificar o clasificar las conductas o rasgos de un sujeto mediante criterios definidos previamente; se basan en descripciones operacionales de conductas específicas y asignan puntuaciones numéricas o categóricas que reflejan la intensidad o frecuencia de los atributos evaluados, lo que facilita la comparación entre sujetos y la interpretación estadística de los datos. Por ello la opción B es la que describe fielmente su función. La alternativa A describe una observación cualitativa narrativa, no una escala cuantitativa; la C se refiere a la observación no estructurada o de flujo continuo, que no emplea criterios preestablecidos; y la D indica una observación breve, pero sin especificar la estructura de valoración que caracteriza a las escalas de apreciación.'),
  (326, 'La subteoría experiencial de la teoría triárquica de Sternberg se refiere a la capacidad de la inteligencia para generar y aplicar soluciones novedosas a problemas, es decir, la habilidad de enfrentar situaciones que no se han vivido previamente y de improvisar estrategias efectivas; esta dimensión se centra en la creatividad y la flexibilidad cognitiva que permiten la resolución de problemas de forma original. Por tanto, la opción B es la que describe adecuadamente esta función. Las demás alternativas son incorrectas porque la opción A corresponde a la subteoría contextual, que se ocupa de la adaptación al entorno; la opción C describe la subteoría componencial, que se enfoca en los procesos y estructuras mentales subyacentes; y la opción D mezcla aspectos de la subteoría contextual con la sociocultural, pero no refleja la orientación experiencial de la teoría.'),
  (327, 'En la clasificación de Cronbach (1992) los tests de rendimiento típico se distinguen de los de rendimiento máximo por su objetivo de medir la tendencia habitual de una persona a responder a un estímulo, no el potencial máximo que podría alcanzar en condiciones ideales; por ello se emplean para evaluar constructos de personalidad, actitudes o rasgos que se manifiestan de forma regular en la vida cotidiana, lo cual corresponde a la opción C. Las demás alternativas son inadecuadas: la A describe precisamente la característica de los tests de rendimiento máximo, que capturan los niveles más altos de capacidad; la B se refiere a las pruebas de respuesta automática o de reacción involuntaria, no a la diferencia entre rendimiento típico y máximo; y la D describe la medición de la velocidad o precisión en tareas de respuesta, típica de los tests de rendimiento máximo, no de los de rendimiento típico.'),
  (328, 'El Test de Aptitudes Mentales Primarias (PMA) está diseñado para niños a partir de los 10 años y evalúa, de manera integral, las aptitudes verbales, espaciales, de razonamiento, numéricas y de fluidez verbal, lo que permite detectar fortalezas y debilidades en el procesamiento cognitivo de los escolares; la opción A describe fielmente la edad mínima de aplicación y la gama de dominios evaluados, mientras que las demás alternativas presentan errores: la B indica una edad de inicio demasiado temprana y omite la dimensión de fluidez verbal; la C reduce la evaluación a tres dominios, excluyendo la espacialidad y la fluidez; y la D confunde “actitud verbal” con “aptitud verbal” y presenta una edad de aplicación incorrecta.'),
  (329, 'La opción C es la que contiene la afirmación incorrecta: cuanto más ambiguas sean las propiedades de los estímulos, menos reflejarán la personalidad las respuestas de los sujetos. En la teoría de las pruebas proyectivas, la ambigüedad del estímulo es precisamente la condición que favorece la proyección del contenido inconsciente del evaluado; por lo tanto, la mayor ambigüedad aumenta la capacidad del test para revelar aspectos de la personalidad. Las demás opciones, por su parte, son consistentes con los principios de las técnicas proyectivas: la A sostiene que el sujeto posee una estructura básica y estable de la personalidad, lo cual es la base para interpretar las proyecciones; la B reconoce que las respuestas no son casuales sino significativas, interpretándose como signos de la personalidad; y la D indica que el análisis debe ser cualitativo y global, enfocándose en la interpretación de los patrones y significados más que en la cuantificación. Todas estas afirmaciones reflejan los fundamentos teóricos y clínicos de las pruebas proyectivas.'),
  (330, 'El modelo de atributo se centra en la descripción de rasgos y estados psicológicos sin buscar causas ni relaciones funcionales; por ello la evaluación debe emplear técnicas correlacionales que permitan cuantificar la presencia y la intensidad de dichos rasgos, y los objetivos se orientan a la pseudoexplicación, es decir, a describir patrones sin afirmar causalidad, lo que concuerda con la opción C; las demás alternativas se desvían porque la A propone observación clínica y clasificación, que pertenece al modelo de clasificación; la B alude a estrategias experimentales y explicación funcional, propio del modelo causal; y la D menciona observaciones y descripción, pero sin la especificidad de correlación y pseudoexplicación que caracteriza al modelo de atributo.'),
  (331, 'La opción a) es la única que recoge los supuestos que Fernández Ballesteros identifica como esenciales para la formulación de hipótesis en la evaluación psicológica: el supuesto de cuantificación, que permite medir y comparar variables; el supuesto de semejanza, que presupone que la población de referencia comparte características relevantes con el caso; el supuesto de asociación predictiva, que postula que la relación entre variables se mantiene a lo largo del tiempo; y el supuesto de asociación funcional, que exige que la relación entre variables sea coherente con la función psicológica del individuo; estos cuatro supuestos garantizan la validez interna y externa de las hipótesis. Las demás alternativas fallan porque mezclan conceptos que no pertenecen a la teoría de Fernández Ballesteros (por ejemplo, supuestos epistemológicos, axioma, aleatorios, idiográficos) o incluyen supuestos que no son parte de su marco teórico (cualitativos, supuestos de semejanza sin cuantificación, etc.), por lo que no cumplen con la especificación de los supuestos necesarios para la hipótesis evaluativa.'),
  (332, 'En la interpretación del psicograma de Rorschach, la categoría de respuestas de color constituye la única que se emplea sistemáticamente para evaluar la dimensión afectiva, pues el uso de colores (tanto en la selección de tonos como en la intensidad y la distribución) refleja la regulación emocional, la intensidad de la experiencia afectiva y la tendencia a la expresividad o a la inhibición emocional; estos datos se codifican en escalas específicas (por ejemplo, la escala de color de la afectividad) y permiten diferenciar patrones de afectividad disfuncional de los adaptativos. Las respuestas de sombreado, claroscuro y figuras humanas, aunque aportan información sobre la percepción visual, la integración perceptiva y la proyección de contenido, no se utilizan como indicadores directos de la afectividad; el sombreado y el claroscuro se centran más en la organización perceptiva y la profundidad, mientras que las figuras humanas se relacionan con la proyección y la identificación, pero no con la intensidad emocional en sí.'),
  (333, 'La técnica que profundiza en los significados más profundos del evaluado y en las emociones asociadas es la flecha descendente, pues consiste en descomponer los constructos personales en sus componentes más básicos, permitiendo al paciente identificar las emociones subyacentes y los valores que sustentan cada constructo, lo que facilita la comprensión de la estructura cognitiva y la motivación emocional; la escalación, por su parte, se limita a medir la intensidad de una respuesta, el flujo de conciencia recorre la narrativa sin profundizar en la estructura constructiva y la autocaracterización se centra en la autoimagen superficial, sin desglosar los constructos ni explorar las emociones que los acompañan.'),
  (334, 'En la técnica de rejilla interpersonal, los elementos que se colocan en la rejilla corresponden a las personas significativas en la vida del evaluado, ya que la herramienta está diseñada para mapear las relaciones interpersonales y la influencia que ejercen estas figuras sobre el individuo; la posición de cada elemento en la rejilla refleja la valoración subjetiva del evaluado respecto a la importancia, cercanía y calidad de la relación con cada persona, lo que permite identificar patrones de interacción y posibles fuentes de conflicto o apoyo. Las demás opciones son incorrectas: la opción A confunde la rejilla con el protocolo de la técnica, que se refiere a los pasos de aplicación y no a los elementos de la rejilla; la opción C se refiere a la comparación de constructos, concepto propio de la técnica de repertorio de constructos, no de la rejilla interpersonal; y la opción D menciona el punto de saturación, un concepto de la técnica de repertorio de constructos, que no aplica en este contexto.'),
  (335, 'La respuesta es la opción D porque los marcadores episódicos, que reflejan cambios fisiológicos transitorios vinculados a un episodio clínico concreto, no tienen la capacidad de predecir la aparición futura de un trastorno; son más bien indicadores de la fase actual del cuadro. En contraste, los marcadores de vulnerabilidad (A) capturan predisposiciones biológicas que aumentan la susceptibilidad a la enfermedad, los marcadores genéticos (B) identifican variantes hereditarias asociadas con riesgo, y los marcadores endofenotípicos (C) son rasgos biológicos hereditables y específicos que sirven como puentes entre la genética y la manifestación clínica, por lo que todos ellos sí contribuyen a la identificación de personas con mayor probabilidad de desarrollar un trastorno.'),
  (336, 'La baja autoeficacia percibida se relaciona con la conducta antisocial en niños y adolescentes porque la percepción de incapacidad para influir en los resultados de sus acciones genera frustración y una tendencia a externalizar la culpa, lo que favorece la adopción de conductas agresivas o desviadas como mecanismo de escape frente a la falta de control interno; además, la literatura sobre psicopatología infantojuvenil indica que la autoeficacia es un predictor de regulación emocional y de la capacidad para seguir normas sociales, por lo que su déficit facilita la aparición de conductas antisociales. El centro de control interno (A) se asocia más con la regulación de impulsos y la toma de decisiones, pero no se ha demostrado que su alteración sea un factor cognitivo específico de la conducta antisocial; la desesperanza (C) se vincula principalmente con trastornos depresivos y suicidismo, no con la agresión antisocial; el autoconcepto positivo (D) suele proteger contra la conducta antisocial, por lo que su presencia es un factor de riesgo opuesto.'),
  (337, 'El DSM‑5 define el trastorno negativista‑desafiante como un patrón persistente de conducta de enfado y irritabilidad, discusiones y actitud desafiante o vengativa, que se manifiesta en al menos tres de los ítems de la escala de diagnóstico y que causa deterioro significativo en el funcionamiento social, académico o laboral; por tanto la opción A resume fielmente esta descripción, pues recoge los tres componentes esenciales (enfado/irritabilidad, discusiones/actitud desafiante y vengativa) sin añadir criterios adicionales. Las demás alternativas son incorrectas: la B confunde la clasificación con una descripción de situaciones emocionales, lo cual no corresponde a la estructura diagnóstica; la C introduce la idea de violación de normas y reglas, que es típica del trastorno de conducta, no del negativista‑desafiante; y la D se centra en arrebatos de agresividad impulsiva, criterio propio del trastorno de oposición, no del negativista‑desafiante.'),
  (338, 'El tratamiento más indicado para el trastorno de la personalidad límite es el Programa STEPPS (Systematic Treatment for Personality Pathology – Emotionally Sensitive Patients), pues combina terapia cognitivo-conductual, entrenamiento en habilidades sociales, regulación emocional y prevención de recaídas, y ha demostrado eficacia en la reducción de la impulsividad y la autoagresión característica de este trastorno; las otras opciones no se centran en la estructura multidimensional de STEPPS: el Diálogo Abierto es una técnica de comunicación interpersonal sin un marco terapéutico específico para la personalidad límite, la Terapia Interpersonal y del Ritmo Social se orienta a la depresión y trastornos del estado de ánimo, y la Terapia Familiar Funcional se enfoca en dinámicas familiares en trastornos de la conducta, sin abordar los síntomas centrales de la personalidad límite.'),
  (339, 'La opción D es la única que se sustenta en la evidencia de la intervención conductual en la infancia, pues la reducción de la estimulación aversiva (por ejemplo, el control de estímulos que provocan la agresión, la eliminación de provocaciones y la modificación del entorno inmediato) disminuye la probabilidad de que se produzca el comportamiento agresivo, tal como lo demuestran los estudios de modificación de conducta aplicada; en cambio, la opción A es incorrecta porque el tiempo fuera sí se emplea con niños menores de diez años cuando se aplica de forma funcional y supervisada; la opción B es errónea porque la eficacia de los tratamientos conductuales no depende del rango etario, sino de la adecuación de la intervención al nivel de desarrollo y la consistencia de la aplicación; y la opción C es falsa porque la búsqueda de indicios por parte de niños agresivos no se ha demostrado como un proceso diferencial frente a niños no agresivos, sino que la agresión suele estar más vinculada a déficits de regulación emocional y a la falta de habilidades sociales.'),
  (340, 'La opción C es la única que corresponde a la realidad de la clasificación del DSM‑5: en la Sección III se presenta un modelo alternativo de diagnóstico que combina criterios categóricos y dimensional, con la intención de superar las limitaciones de la clasificación multiaxial del DSM‑IV y de la CIE‑11; este modelo híbrido permite evaluar la gravedad y la presencia de rasgos transversales, lo que no ocurre en las otras opciones. La alternativa A es errónea porque la CIE‑11 mantiene una clasificación categórica, no una propuesta de diagnóstico híbrido. La alternativa B es falsa porque el DSM‑5 abandonó el sistema multiaxial, por lo que los trastornos de personalidad ya no se ubican en el eje II. La alternativa D también es incorrecta, pues el DSM‑5 no aumenta el número de trastornos a 12 ni los organiza en tres grupos; la cantidad y la organización de los trastornos permanecen iguales a la del DSM‑IV.'),
  (341, 'El ADOS‑2 (Autism Diagnostic Observation Schedule, segunda edición) es una escala de observación estandarizada y semiestructurada que se emplea para el diagnóstico de trastornos del espectro autista; cuenta con módulos específicos que se adaptan al nivel de lenguaje y la edad del individuo, permitiendo la evaluación de la comunicación, la interacción social y los comportamientos repetitivos y restringidos, lo que lo convierte en la herramienta de referencia para la valoración clínica y la investigación; las opciones A y B describen instrumentos de cribado o cuestionarios de padres que no poseen la estructura observacional y la validez diagnóstica del ADOS‑2, mientras que la opción C se refiere a una entrevista estructurada, no a la escala de observación que caracteriza al ADOS‑2.'),
  (342, 'La terapia dialéctico-conductual en formato grupal (opción C) es la modalidad indicada para el trastorno límite de la personalidad en adolescentes porque combina la estructura de la TDC, con sus módulos de regulación emocional, tolerancia al malestar y habilidades interpersonales, con la dinámica grupal que facilita la validación y la práctica de las habilidades en un contexto de apoyo entre pares, algo esencial en la etapa de desarrollo donde la identidad y las relaciones sociales están en construcción; además, la TDC ha demostrado eficacia en estudios con adolescentes y su aplicación grupal permite optimizar recursos y aumentar la adherencia al tratamiento. Las demás opciones son inadecuadas: la terapia interpersonal adaptada (A) se centra en la resolución de conflictos interpersonales y no aborda la regulación emocional ni la impulsividad propia del trastorno límite; la terapia familiar orientada al apego (B) se enfoca en la relación madre‑hijo y no en los procesos cognitivo‑conductuales que caracterizan la patología; la terapia de desarrollo de habilidades familiares y psicoeducación (D) ofrece apoyo educativo pero carece de la intervención específica en la regulación emocional y la tolerancia al malestar que requiere el trastorno límite.'),
  (343, 'La afirmación D resulta falsa porque la literatura sobre la eficacia de los modelos de terapia de tercera generación (como la terapia de aceptación y compromiso o la terapia cognitiva conductual basada en la atención plena) en personas con discapacidad intelectual no ha alcanzado un nivel de evidencia de calidad alta; los estudios disponibles son mayormente de diseño observacional o de muestras pequeñas, con riesgo de sesgo y falta de replicación en ensayos aleatorios controlados rigurosos, por lo que no se puede afirmar con certeza la efectividad de estos enfoques en este grupo. En contraste, la opción A es verdadera ya que las terapias basadas en atención plena se han adaptado y aplicado con éxito a individuos con discapacidad intelectual, mostrando mejoras en la regulación emocional y la reducción de la ansiedad; la opción B también es correcta porque la terapia centrada en la compasión, un enfoque contextualista, ha sido utilizada para abordar la autocrítica y la comparación social negativa en esta población, con resultados prometedores; y la opción C es válida pues la depresión, al igual que en la población general, constituye el problema más investigado en relación con la activación conductual aplicada a personas con discapacidad intelectual, con evidencia que respalda su eficacia en la reducción de síntomas depresivos.'),
  (344, 'La afirmación falsa es la A, porque los enfoques centrados en el niño, también denominados naturales o de interacción, no se basan principalmente en el modelado, moldeamiento y reforzamiento; estos métodos son típicos de los tratamientos centrados en el terapeuta, donde el profesional controla la exposición al lenguaje y utiliza técnicas de enseñanza estructuradas para guiar la producción del niño. En los modelos centrados en el niño, el terapeuta facilita la comunicación a través de la interacción espontánea, el juego y la conversación diaria, permitiendo que el niño internalice el lenguaje de forma más orgánica y contextualizada, sin imponer un esquema rígido de modelado. Las opciones B y C describen correctamente la estructura de los tratamientos centrados en el terapeuta y la relación entre formalidad y enfoque del profesional, mientras que la D refleja adecuadamente la naturaleza intencional de los recursos comunicativos en los enfoques naturales.'),
  (345, 'El programa “Los años increíbles” es un tratamiento estructurado de intervención familiar y escolar que combina estrategias de reforzamiento positivo, entrenamiento en habilidades sociales y manejo de conductas desafiantes, y se ha validado específicamente para niños y adolescentes con trastornos de conducta, por lo que se alinea con la evidencia de eficacia en la población infantojuvenil; en contraste, la terapia basada en el modelo de Worden se centra en la resolución de pérdidas y el duelo, no en la conducta disruptiva; la intervención compresiva conductual (probablemente un error tipográfico de “intervención conductual compuesta”) no es un programa estandarizado reconocido para trastornos de conducta, y el programa Coping Cat se orienta a la ansiedad y el trastorno de ansiedad social, no a la conducta disfuncional, por lo que las opciones A, C y D no cumplen con el objetivo de tratamiento de trastornos de conducta en esta población.'),
  (346, 'El mutismo selectivo se define precisamente como la incapacidad persistente de hablar en contextos sociales específicos donde se espera la comunicación, a pesar de la habilidad lingüística normal y la ausencia de retardo del lenguaje; el caso descrito coincide con esta descripción clínica, pues el menor presenta fracaso constante para hablar solo en situaciones sociales con expectativa de hablar, sin indicios de déficit fonológico ni de trastorno del lenguaje general. El trastorno del lenguaje implica dificultades en la producción o comprensión del lenguaje en todos los contextos, no restringido a situaciones sociales; el trastorno fonológico se centra en la producción de sonidos y no en la ausencia de habla por ansiedad; el trastorno de la comunicación social (trastorno del espectro autista) se caracteriza por déficits en la comunicación no verbal y la reciprocidad social, pero no por la evitación específica de hablar en contextos donde se espera hacerlo.'),
  (347, 'La terapia conductual para la esquizofrenia, tal y como la describen Kingdom y Turkington (2005), se centra en la modificación de conductas disfuncionales y la reducción de síntomas psicóticos mediante técnicas de aprendizaje y manejo de la ansiedad; por ello incluye la explicación normalizadora de la psicosis (A), el examen de los antecedentes de la crisis psicótica (B) y el tratamiento de la ansiedad y depresión coexistentes (C), pues todos estos elementos contribuyen a la reestructuración cognitiva y al alivio de la angustia que acompaña a la enfermedad. La opción D, que propone una formulación de las conexiones entre A, B y C con el desarrollo psicológico evolutivo, no forma parte de la intervención conductual descrita por Kingdom y Turkington, ya que su enfoque se limita a la intervención inmediata y a la gestión de síntomas, sin incorporar un análisis evolutivo profundo; las demás opciones son componentes esenciales de la terapia conductual y, por tanto, no son la respuesta buscada.'),
  (348, 'El entrenamiento en escenificaciones emotivas, también llamado exposición guiada o terapia de exposición en vivo, se emplea principalmente en niños y adolescentes, con mayor frecuencia en menores de 9 años, pues su desarrollo cognitivo permite comprender y procesar la situación de miedo mediante la imaginación guiada; además, la técnica se basa en provocar una respuesta emocional intensa y realista, por lo que se busca generar emociones negativas (pánico, ansiedad) y no positivas, y se apoya en la retroalimentación social y el refuerzo de la conducta adaptativa, por ejemplo, el elogio o la aprobación de los padres o terapeutas, lo que constituye un sistema de refuerzo social; la relajación muscular progresiva, aunque es una estrategia de manejo de la ansiedad, no forma parte intrínseca de la escenificación emotiva, que se centra en la exposición y la habituación, por lo que la opción D es la que no corresponde. Las opciones A, B y C son características habituales de este tipo de intervención.'),
  (349, 'La clordiazepóxido, benzodiacepina de acción corta, no se emplea como tratamiento estabilizador del ánimo en el trastorno bipolar; su uso se limita a la ansiedad o a la inducción de sueño y puede precipitar episodios maníacos o depresivos, por lo que no está indicado en esta patología. En contraste, la lamotrigina es un estabilizador del ánimo eficaz en la fase depresiva y la prevención de recaídas; la flufenazina, aunque antipsicótica, se utiliza en el manejo de la fase aguda de la manía cuando se necesita control de síntomas psicóticos; y la oxcarbazepina, anticonvulsor con propiedades estabilizadoras, se emplea en el tratamiento de la fase maníaca y en la prevención de episodios. Por tanto, las opciones A, B y C son fármacos con indicaciones en el trastorno bipolar, mientras que la opción D carece de dicha indicación.'),
  (350, 'El aripiprazol, al ser un antipsicótico atípico con agonista parcial de D2 y antagonista de 5‑HT2A, presenta un perfil de efectos adversos que favorece la aparición de alteraciones metabólicas, entre ellas la hipercolesterolemia, la cual es la que se documenta con mayor frecuencia en estudios de farmacovigilancia y ensayos clínicos de esquizofrenia; esto se debe a su acción moduladora sobre los receptores de serotonina y dopamina que influyen en la regulación lipídica central y periférica, generando incrementos en el colesterol total y LDL. En contraste, la galactorrea es poco frecuente con aripiprazol porque su menor afinidad por D2 en el hipotálamo reduce la inhibición de la prolactina; el parkinsonismo, aunque posible, aparece con menor incidencia que en antipsicóticos típicos, y la discinesia tardía es la de menor frecuencia entre los efectos extrapiramidales, dada su acción parcial agonista que limita la desregulación dopaminérgica crónica.'),
  (351, 'El modelo de autorregulación de Kanfer, que fundamenta la terapia de autocontrol de Rhem para la depresión, identifica tres déficits estructurales que impiden la regulación emocional: la autoobservación, la autoevaluación y el autorreforzamiento; la primera fase implica la incapacidad de monitorear de manera continua y precisa las propias emociones y conductas, la segunda se refiere a la falta de juicio crítico sobre la validez y la utilidad de las respuestas emocionales, y la tercera corresponde a la ausencia de mecanismos internos de recompensa que consoliden los cambios conductuales y cognitivos; las demás opciones son incorrectas porque la opción A mezcla procesos de tratamiento con fases de intervención, la B describe dominios funcionales de la terapia pero no los déficits de autorregulación, y la D incluye conceptos que no aparecen en el marco teórico de Kanfer.'),
  (352, 'La terapia interpersonal se centra en la relación entre la persona y su entorno social, identificando patrones de interacción que contribuyen a la sintomatología depresiva y trabajando en la resolución de problemas concretos como duelo, transición o conflicto de roles; por ello, es la única que especifica un foco de interés en la depresión y la resolución de problemas de vida relacionados con las relaciones interpersonales. Las demás opciones se enfocan en la reestructuración cognitiva (C), la aceptación y el compromiso con valores (B) o la modificación de creencias irracionales (A), sin dirigirse de manera específica a la depresión ni a la resolución de problemas de vida relacionados con el duelo o las relaciones interpersonales.'),
  (353, 'El CAD, desarrollado por Lewinsohn y colaboradores, se diseñó inicialmente para adultos con depresión mayor y se ha aplicado con éxito a adolescentes, personas con trastorno bipolar y pacientes con trastornos de ansiedad, demostrando eficacia en la reducción de la sintomatología depresiva y en la prevención de recaídas; por tanto la opción C es la que se ajusta a la realidad clínica y empírica del tratamiento. Las demás alternativas son inexactas: la afirmación A es errónea porque el CAD no excluye la terapia cognitiva; de hecho, la combinación con técnicas cognitivas suele potenciar los resultados, y la idea de que la cognición sea contraproducente carece de fundamento. La opción B es incorrecta porque el CAD es una intervención estructurada y directiva, con el terapeuta guiando la identificación de conductas, la planificación de actividades agradables y la resolución de problemas, no dejando que el grupo sea completamente autónomo. Finalmente, la opción D es falsa, pues existen numerosos estudios controlados que respaldan la eficacia del CAD, tanto en entornos clínicos como comunitarios.'),
  (354, 'La terapia interpersonal (TIP) se fundamenta en la hipótesis que la depresión se origina y se mantiene por alteraciones en las relaciones interpersonales y los roles sociales; por ello, el modelo considera la depresión como una enfermedad que se manifiesta cuando los cambios en el entorno interpersonal provocan crisis de adaptación, pérdida de apoyo o conflictos, y la intervención se centra en identificar y modificar estos patrones para restaurar la funcionalidad social, lo que explica por qué la opción C es la que corresponde; las demás alternativas son erróneas porque la TIP sí tiene una duración limitada y estructurada (opción A), no ofrece un marco comprensivo tan amplio como la activación conductual o la terapia cognitiva (opción B), y sí presta especial atención al análisis de afectos y emociones generados por las circunstancias (opción D).'),
  (355, 'La técnica TRAP‑TRAC (técnica de “tareas de activación y registro de progresos”) es un componente esencial de la activación conductual, donde se planifican actividades concretas, se registran los resultados y se refuerza la motivación mediante la autoobservación y el feedback positivo; esta estrategia se basa en la teoría de la motivación y la autoeficacia de Bandura y se ha demostrado eficaz en la reducción de la anhedonia y la evitación conductual típica de la depresión. En contraste, la terapia dialéctico‑conductual se centra en la regulación emocional y la tolerancia a la angustia, sin emplear un esquema estructurado de tareas de activación; la terapia racional‑emocional se orienta a la reestructuración cognitiva de creencias irracionales, sin un componente de registro de progresos; y la terapia interpersonal se enfoca en las relaciones interpersonales y la resolución de conflictos, sin la metodología de tareas y seguimiento que caracteriza a la activación conductual.'),
  (356, 'El programa de entrenamiento en reconocimiento emocional de Wölwer y colaboradores se estructura en tres bloques progresivos: el primero se centra en la identificación de emociones básicas (felicidad, tristeza, ira, miedo, sorpresa y asco), que constituye la base de la lectura facial; el segundo bloque profundiza en el procesamiento emocional, es decir, la interpretación y contextualización de las emociones identificadas, integrando la información contextual y la regulación emocional; y el tercero se dedica a la identificación de expresiones más ambiguas o complejas del afecto, que requieren una mayor discriminación y sensibilidad a matices. Las demás opciones son incorrectas porque la alternativa B confunde la secuencia al colocar la diferenciación de estímulos no sociales antes de la identificación de emociones básicas; la C introduce componentes de la teoría de la mente que no forman parte de este programa; y la D describe habilidades sociales en lugar de reconocimiento emocional, desviándose del enfoque de Wölwer.'),
  (357, 'El programa de entrenamiento en cognición social e interacción descrito por Penn y colaboradores (2005) se estructura en tres fases progresivas: la primera se centra en la comprensión de emociones, entrenando la identificación y discriminación de expresiones faciales y señales emocionales, lo que constituye la base para cualquier interacción social; la segunda fase aborda el estilo de cognición social, es decir, la forma en que se procesa la información social, incluyendo la percepción de intenciones y la interpretación de contextos sociales, lo que permite una interpretación más precisa de las interacciones; y la tercera fase se dedica a la consolidación de las habilidades aprendidas y a su extrapolación a la vida cotidiana, garantizando que los pacientes puedan aplicar las estrategias cognitivas en situaciones reales y mejorar su funcionamiento social. Las otras opciones son incorrectas porque la A y la B describen déficits y entrenamientos que no corresponden a la estructura original del programa (enfocándose en psicosis y funciones neurocognitivas básicas, respectivamente), mientras que la C se limita a habilidades sociales básicas y complejas sin mencionar la comprensión emocional ni la consolidación práctica, aspectos esenciales del modelo de Penn.'),
  (358, 'La opción D es la que refleja la distinción esencial entre la terapia para la mejora cognitiva (CET) y el programa de terapia psicológica integrada (IPT) para la esquizofrenia: ambos intervienen en déficits de neurocognición y cognición social, pero la CET se estructura de forma lineal y escalonada, progresando de tareas cognitivas básicas a más complejas, mientras que el IPT adopta un enfoque más flexible y menos lineal, integrando módulos de cognición social, psicoeducación y habilidades funcionales en un programa adaptativo. Las demás alternativas son incorrectas porque la A y B confunden la orientación de cada programa, atribuyendo a la CET la intervención en cognición social cuando en realidad es la IPT la que la incorpora; la C presenta la relación de linealidad al revés, pues la IPT no es menos lineal que la CET, sino que su estructura es más flexible y no estrictamente escalonada.'),
  (359, 'La respuesta se fundamenta en la propuesta de Lysaker y Dimaggio (2014) sobre la metacognición en psicosis, que identifica cuatro competencias esenciales: la autorreflexividad (capacidad de observar y evaluar los propios procesos mentales), la comprensión de la mente del otro (habilidad para inferir estados mentales ajenos), el descentramiento (capacidad de situarse fuera de la propia experiencia inmediata) y la integración intersubjetiva (fusión de la información social y propia para resolver problemas adaptativamente); por tanto, la opción C recoge exactamente estos cuatro constructos. Las demás alternativas presentan conceptos que, aunque relevantes en la psicología social, no corresponden a la taxonomía de Lysaker y Dimaggio: la opción A incluye la teoría de la mente y el estilo atribucional, que no son parte de su modelo; la B sustituye la autorreflexividad por procesamiento emocional y la percepción social, desviándose del enfoque metacognitivo; y la D combina percepción emocional y descentramiento con percepción social y estilo atribucional, omitiendo la autorreflexividad y la integración intersubjetiva, por lo que no cumplen con la propuesta original.'),
  (360, 'La terapia para la mejora cognitiva (CET) según Hogarty y Flesher (1999) se centra en la rehabilitación de las funciones cognitivas que suelen estar comprometidas en trastornos psicóticos, especialmente la atención, la memoria y la resolución de problemas, pues estas tres áreas son esenciales para el funcionamiento diario y la recuperación funcional; la atención permite la selección y mantenimiento de información relevante, la memoria facilita la consolidación y recuperación de datos, y la resolución de problemas integra ambas capacidades para la toma de decisiones y la adaptación; las demás opciones son erróneas porque la opción A incluye velocidad de procesamiento, que no es uno de los pilares centrales de la CET; la opción C menciona fluidez verbal y aprendizaje verbal, que son subcomponentes de la memoria y no se consideran funciones básicas en el modelo de Hogarty y Flesher; la opción D combina memoria con velocidad de procesamiento y praxias, donde la velocidad de procesamiento y las praxias no se destacan como funciones cognitivas básicas en la CET propuesta.'),
  (361, 'La disomnia se define como un trastorno del sueño que altera la calidad, cantidad o patrón del sueño sin implicar un episodio de sueño activo; por tanto, la alteración circadiana, que implica un desajuste del reloj biológico y produce insomnio o somnolencia diurna, encaja en la categoría de disomnias, mientras que el bruxismo, el somniloquio y los terrores nocturnos son parasomnias, ya que se manifiestan como comportamientos o episodios activos durante el sueño.'),
  (362, 'El modelo de intervención familiar de Miklowitz se fundamenta en la hipótesis de que el entorno familiar constituye un factor de estrés que influye en la aparición y el curso de la esquizofrenia, por lo que el tratamiento se orienta a identificar y modificar las interacciones familiares que contribuyen a la exacerbación de los síntomas; por tanto la opción B es la que refleja correctamente la premisa teórica de la intervención, mientras que la opción A invierte la relación causal, la C sugiere una reducción indiscriminada de la interacción familiar sin considerar la calidad de la misma, y la D describe erróneamente la estructura del modelo, el cual es sistemático y basado en principios específicos.'),
  (363, 'La técnica que se emplea para evitar el rol de espectador y eliminar la ansiedad de rendimiento en los problemas de erección es la utilización de fantasías sexuales; al imaginar situaciones eróticas que estimulan la excitación, el paciente puede concentrarse en la respuesta fisiológica en lugar de en la presión de “desempeño”, reduciendo la ansiedad y facilitando la erección. La autoestimulación (A) no elimina la ansiedad de rendimiento porque el estímulo sigue siendo externo y puede generar una expectativa de “auto‑rendimiento”. La alineación coital (C) se refiere a la posición física durante el coito y no aborda la dimensión psicológica de la ansiedad. La técnica del puente (D) es una estrategia de relajación muscular que, aunque útil para la tensión corporal, no se centra en la reducción de la ansiedad de rendimiento asociada a la función eréctil.'),
  (364, 'El inicio del tratamiento de un trastorno orgásmico femenino generalizado se orienta a la práctica de la masturbación a solas, ya que permite al paciente explorar su propio cuerpo, identificar zonas erógenas y aprender a generar placer sin la presión de la interacción con un compañero, lo que facilita la reeducación sensorial y la reconstrucción de la respuesta sexual de manera autónoma; la masturbación individual favorece la reducción de la ansiedad de desempeño y la internalización de la respuesta orgásmica, aspectos críticos en la etiología de este trastorno. Por su parte, la masturbación delante del compañero sexual (A) no elimina la necesidad de autoexploración y puede reforzar la dependencia del estímulo externo, mientras que la focalización sensorial (B) es una técnica complementaria que se emplea después de haber establecido la autoestimulación, y las relaciones coitales (C) suelen requerir la superación previa de la disfunción orgásmica, por lo que no constituyen el punto de partida adecuado.'),
  (365, 'La maniobra del puente es una técnica de terapia sexual que consiste en simultanear la estimulación manual de los genitales con movimientos coitales hasta que se produzca la eyaculación intravaginal, de modo que el paciente aprenda a controlar el punto de excitación y a prolongar la respuesta sexual, reduciendo la disfunción eréctil y la eyaculación precoz; la combinación de estímulo manual y coito permite la reeducación de la respuesta fisiológica y la consolidación de la experiencia de placer en un contexto de pareja. Las demás opciones son incorrectas: la opción B describe simplemente la eyaculación extravaginal, que no es la maniobra del puente; la opción C se refiere a la práctica de orgasmos simultáneos, una estrategia de intimidad, pero no implica la técnica de puente; y la opción D habla de la masturbación frente a la pareja, que tampoco corresponde a la maniobra de puente.'),
  (366, 'La intervención que se caracteriza por establecer medidas que permitan que el consumo de sustancias se realice en condiciones de seguridad para la salud del usuario es la de reducción de daños, pues su objetivo es minimizar los efectos adversos de la adicción sin exigir la abstinencia total, mediante la provisión de entornos controlados, la administración de dosis más seguras y la educación sobre prácticas menos riesgosas; las comunidades terapéuticas (A) se centran en la reinserción social y el apoyo grupal, los centros de día (B) ofrecen tratamiento ambulatorio con seguimiento clínico, y los programas con antagonistas opiáceos (C) buscan la sustitución farmacológica para reducir la dependencia, pero ninguno de ellos se enfoca primordialmente en la seguridad del consumo como su eje central.'),
  (367, 'En el modelo de Marlatt y Gordon (1985) las conductas, racionalizaciones y minimizaciones del riesgo que llevan a las personas a situaciones de alta probabilidad de consumo se denomina “decisiones aparentemente irrelevantes”; estas son elecciones cotidianas que, aunque en apariencia sin importancia, incrementan la exposición al estímulo de consumo y, por tanto, la probabilidad de recaída, y se distinguen de las “creencias justificativas” que son justificaciones explícitas de la conducta, de la “matriz adictiva de valoración” que no aparece en el modelo, y del “craving”, que se refiere al deseo intenso y no a la toma de decisiones.'),
  (368, 'En los programas de reducción gradual de nicotina, la reducción inicial se emplea para disminuir la probabilidad de síntomas de abstinencia, ya que al disminuir la ingesta de nicotina de forma progresiva se evita la abrupta retirada que desencadena la disforia, irritabilidad y somnolencia, facilitando la adaptación fisiológica y psicológica del paciente; este enfoque se basa en la evidencia de que la reducción gradual reduce la intensidad de la abstinencia y mejora la adherencia al tratamiento. Las demás opciones son incorrectas: la opción B sugiere controlar estímulos, pero la reducción de nicotina no se dirige a la gestión de estímulos externos; la C habla de obtener feedback fisiológico, lo cual es un subproducto, no el objetivo principal; y la D menciona autorregistro, que es una técnica complementaria pero no el fin de la reducción inicial.'),
  (369, 'La reestructuración cognitiva se introduce en la fase segunda del protocolo de Fairburn, Marcus y Wilson (1993) porque, tras haber estabilizado la conducta alimentaria y haber trabajado la relación con la comida y el peso en la fase inicial, el paciente ya dispone de una base de seguridad y de una mayor capacidad para afrontar los pensamientos disfuncionales que perpetúan la bulimia; en esta etapa se aborda la distorsión cognitiva central (el miedo al aumento de peso y la valoración excesiva del control corporal) con técnicas de identificación y revaluación de creencias, lo que permite consolidar los cambios conductuales. En la fase primera se centra en la estabilización de la conducta y la motivación, mientras que en la fase tercera se refuerza la prevención de recaídas mediante la consolidación de la autoconciencia y la autonomía; por ello la reestructuración cognitiva no se aplica en esos momentos. La opción D es incorrecta porque la presencia de infrapeso severo no justifica la introducción de la reestructuración en la fase inicial, ya que la prioridad es la estabilización de la conducta y la seguridad física.'),
  (370, 'La guía NICE recomienda que, como tratamiento de elección de primera línea para la anorexia nerviosa en adultos, se utilice un programa de tratamiento cognitivo-conductual individual que comience explicando los riesgos de la desnutrición y el bajo peso, pues la fase inicial de la intervención debe centrarse en la motivación y la conciencia de la gravedad de la condición, elementos esenciales para la adherencia al tratamiento y la prevención de recaídas; en contraste, la opción B es incorrecta porque la guía no limita el número de sesiones a 20, sino que sugiere una duración flexible según la respuesta clínica; la alternativa C es errónea porque la intervención psicoterapéutica no debe posponerse tras la terapia farmacológica, sino que puede iniciarse simultáneamente o antes, ya que la farmacoterapia no es el tratamiento de primera línea; y la alternativa D es falsa porque el programa cognitivo-conductual no se aplica como paso previo a la rehabilitación nutricional, sino que se integra con la misma desde el inicio para abordar tanto los patrones de pensamiento como los comportamientos alimentarios.'),
  (371, 'La terapia metacognitiva de Wells (2009) se focaliza en las creencias metacognitivas que el paciente mantiene acerca de sus propios pensamientos y de la manera en que estos influyen en su conducta, especialmente la fusión entre pensamiento, evento y acción; por ello la opción B es la que describe adecuadamente el eje teórico de la intervención, pues la terapia busca modificar la percepción de los pensamientos intrusivos como amenazas reales y la necesidad de responder a ellos con rituales compulsivos. Las demás alternativas son erróneas: la A se refiere al contenido de las obsesiones y su relación con la historia personal, un enfoque más propio de la terapia cognitiva clásica; la C menciona la rumiación, que es un proceso distinto y no el foco central de la terapia metacognitiva; y la D habla de creencias positivas sobre la preocupación, que no son el objetivo de la intervención, pues la terapia pretende reducir la ansiedad asociada a las obsesiones, no reforzarla.'),
  (372, 'La opción C es la que se corresponde con la evidencia disponible: los metaanálisis que comparan la exposición con prevención de respuesta (EPR) aplicada de forma individual y en grupo han encontrado que la eficacia clínica, medida en reducción de síntomas obsesivo‑compulsivos y en la mejora funcional, no difiere de manera significativa entre ambos formatos, lo que indica que el formato grupal puede ser tan efectivo como el individual cuando se sigue un protocolo estandarizado y se cuenta con la supervisión adecuada; además, la evidencia sugiere que el grupo puede aportar beneficios adicionales como la normalización social y el apoyo entre pares. En contraste, la alternativa A es incorrecta porque la heterogeneidad del TOC no impide la aplicación grupal; la alternativa B es falsa pues existen estudios que evalúan la eficacia y la rentabilidad de la EPR grupal; y la alternativa D se basa en una suposición errónea: los datos no muestran una menor eficacia ni un mayor abandono en el formato grupal, por lo que esa afirmación no está respaldada por la literatura.'),
  (373, 'La opción d) es la más adecuada porque la estrategia descrita por el paciente constituye una forma de neutralización: al decir “¡basta!” y cambiar inmediatamente a un pensamiento agradable, está intentando reducir la ansiedad que provoca la obsesión sin confrontar directamente el contenido intrusivo, lo que perpetúa el ciclo obsesivo‑compulsivo; por lo tanto, la intervención debe centrarse en identificar y desmantelar esa neutralización, enseñándole técnicas de exposición y prevención de respuesta que le permitan enfrentar la idea sin sustituirla por otro pensamiento. Las alternativas a) y b) fallan porque reforzar o generalizar la estrategia solo consolidaría la neutralización, mientras que la opción c) es inapropiada pues dirigir el pensamiento a actividades sexuales “apropiadas” no aborda la raíz del TOC y puede reforzar la ansiedad; todas comparten el error de no atacar la neutralización que mantiene el trastorno.'),
  (374, 'La evidencia de nivel 1, que corresponde a estudios de alta calidad con resultados consistentes, se asigna a la exposición prolongada, la terapia de procesamiento cognitivo (TPC) y la terapia de desensibilización y reprocesamiento por movimientos oculares (EMDR); estos tres enfoques han sido confirmados en múltiples ensayos controlados aleatorios y meta‑análisis como intervenciones efectivas para el TEPT, con mejoras sostenidas en síntomas y funcionamiento funcional. En cambio, la búsqueda de seguridad y el entrenamiento en inoculación del estrés son técnicas de prevención y no se han evaluado con la rigurosidad necesaria para alcanzar el nivel 1, mientras que el debriefing postraumático, aunque popular, ha demostrado resultados mixtos y, en algunos estudios, incluso potenciales efectos adversos, por lo que no alcanza dicho nivel de evidencia; por tanto, las opciones A, B y C incluyen intervenciones que no cumplen con los criterios de nivel 1 y, por consiguiente, son incorrectas.'),
  (375, 'En la fase de desensibilización del EMDR, el objetivo es procesar la memoria traumática mediante la estimulación bilateral; por ello se emplean movimientos oculares, audios binaurales o toques táctiles (tapping) en manos, hombros y piernas, lo que facilita la reestructuración de la experiencia y la reducción de la carga emocional asociada; las demás opciones son incorrectas porque la opción A describe una verificación de sensaciones somáticas que se realiza en la fase de estabilización, la opción B corresponde a la fase de estabilización y acceso a recursos positivos, y la opción C se refiere a la fase de identificación del recuerdo objetivo, no a la desensibilización.'),
  (376, 'En el tratamiento del TEPT, las técnicas de exposición se fundamentan en la teoría del procesamiento emocional y la habituación; al enfrentar repetidamente los recuerdos traumáticos o las situaciones temidas, se facilita la integración de la información afectiva (opción A) y la reducción progresiva de la respuesta ansiosa (opción B), mientras que la experiencia de dominio sobre la ansiedad refuerza la percepción de control (opción D). La eliminación de información correctora (opción C) no es un objetivo ni un resultado esperado de la exposición; al contrario, la exposición busca actualizar y corregir la interpretación disfuncional del trauma, no eliminarla. Por tanto, la opción C es la única que no corresponde a los efectos clínicos de la exposición, mientras que las demás describen adecuadamente los procesos terapéuticos implicados.'),
  (377, 'La terapia del procesamiento cognitivo (TPC) se distingue por su componente de escritura de una narrativa detallada del evento traumático, que permite a la paciente desglosar y reestructurar las creencias disfuncionales asociadas al trauma y a la culpa; esta técnica se basa en la teoría de la memoria episódica y la integración de la información emocional, facilitando la desensibilización y la revaluación cognitiva. Las demás opciones no incluyen este requisito: la terapia centrada en el presente se orienta a la regulación emocional y la atención plena sin requerir una narrativa escrita; el entrenamiento en inoculación del estrés se centra en la preparación de afrontamiento ante situaciones futuras, sin abordar la reexpresión escrita del trauma; la terapia EMDR emplea la estimulación bilateral y la reestructuración cognitiva, pero no contempla la escritura narrativa como parte de su protocolo.'),
  (378, 'La técnica implosiva de Stampfl y Levis (1967) se basa en la exposición a estímulos aversivos que provocan una respuesta de escape, con el objetivo de impedir que el paciente realice dicha conducta de evasión; por ello la opción C es la única que refleja el propósito terapéutico de la intervención, que consiste en eliminar la función de escape que mantiene la ansiedad, sin eliminar la contingencia entre estímulo y respuesta, pues la exposición se mantiene para generar un aprendizaje de tolerancia. Las demás alternativas son erróneas: la A confunde la eliminación de la contingencia con la eliminación de la respuesta de escape, lo cual no es el objetivo de la técnica implosiva; la B es incorrecta porque los estímulos aversivos sí están vinculados a contenidos dinámicos, ya que se utilizan para generar una respuesta emocional que permita el aprendizaje de la tolerancia; la D equivale a una generalización indebida, pues la técnica se aplica principalmente en vivo, aunque puede emplearse en imaginación, pero no se considera “suele aplicar tanto en imaginación como en vivo” como una característica distintiva.'),
  (379, 'El enunciado correcto es la opción B, porque el modelo de habituación dual de Watts (1979) postula que la disminución de las respuestas de ansiedad se produce mediante la interacción simultánea de dos procesos: un proceso de sensibilización que aumenta la respuesta ante la amenaza y un proceso de habituación que la reduce; ambos actúan en paralelo y se equilibran para explicar el mantenimiento y la eventual extinción de la ansiedad. La opción A confunde la ausencia de escape con la competencia de otra respuesta, cuando la teoría señala que la ausencia de escape se debe a la falta de un estímulo que la provoque, no a una respuesta competidora. La opción C es incorrecta porque el modelo no propone una alternancia secuencial entre sensibilización y habituación, sino su coexistencia simultánea. La opción D equivale a una interpretación errónea de la frecuencia de la respuesta de evitación, pues la teoría indica que la ausencia de escape no impide la extinción de otras respuestas de ansiedad, siempre que el proceso de habituación actúe.'),
  (380, 'La opción B resulta la más eficaz porque la autoexposición en vivo permite al paciente confrontar directamente el estímulo temido en un entorno real, lo que favorece la habituación y la desensibilización, procesos centrales en la terapia cognitivo-conductual para trastornos de ansiedad; además, la ausencia de un terapeuta presente reduce la transferencia de ansiedad y aumenta la autonomía del paciente, factores que la literatura clínica ha demostrado potenciar la eficacia de la exposición. Las demás alternativas son inadecuadas: la exposición con presencia del terapeuta en imaginación (A) limita la intensidad del estímulo y la experiencia emocional, reduciendo la habituación; el uso de psicofármacos antidepresivos o ansiolíticos (C y D) no interviene directamente en el proceso de desensibilización y, en el caso de los ansiolíticos, puede disminuir la motivación para enfrentar el miedo, por lo que no se considera una modalidad de mayor eficacia.'),
  (381, 'El primer procedimiento clínico que incorporó el mindfulness como componente de un tratamiento multicomponente fue la Terapia de Conducta Dialéctica (TCD) de Marsha Linehan; la TCD fue diseñada para tratar a pacientes con trastorno límite de la personalidad y combina técnicas de regulación emocional, tolerancia al malestar y aceptación con prácticas de atención plena, integrándolas dentro de un marco de intervención estructurado y validado por investigación; las demás opciones son incorrectas porque la terapia cognitiva basada en mindfulness de la depresión se desarrolló posteriormente como una adaptación de la TCD, la terapia de aceptación y compromiso (ACT) surgió a partir de la terapia de aceptación y compromiso de la conducta y la desensibilización sistemática es una técnica de exposición clásica que no incluye mindfulness.'),
  (382, 'La opción A describe la creencia disfuncional característica del TOC de sobrestimar la importancia del pensamiento: al atribuir un significado personal, relevante y negativo a la mera ocurrencia de una obsesión, el individuo interpreta el pensamiento como una amenaza real y exigente, lo que genera ansiedad y la necesidad de actuar; esta distorsión se diferencia de la simple valoración de la fuerza de la obsesión (B) o de la creencia en la posibilidad de control (C), que corresponden a la sobrevaloración de la necesidad de controlar el pensamiento, y de la idea de poder provocar o prevenir eventos (D), que se relaciona con la sensación de poder personal y no con la importancia del pensamiento en sí.'),
  (383, 'La opción B es la única que concuerda con la evidencia sobre la influencia de la reactancia en la respuesta terapéutica: las personas con alta reactancia tienden a resistirse a la autoridad y a las directrices explícitas, por lo que se benefician de un estilo terapéutico menos directivo y más colaborativo, que les permite sentir mayor autonomía y control sobre el proceso, reduciendo la resistencia y facilitando la internalización de los cambios; las demás alternativas se basan en supuestos erróneos: la A presupone que el afrontamiento internalizante responde únicamente a la reducción de síntomas, ignorando la necesidad de procesamiento cognitivo y emocional; la C confunde el estilo externalizante con la necesidad de insight, cuando en realidad estos pacientes suelen responder mejor a intervenciones estructuradas y orientadas a la acción; y la D asume que la baja reactancia se beneficia de intervenciones paradójicas, lo cual no está respaldado por la literatura, pues la reactancia baja no requiere de estrategias de resistencia.'),
  (384, 'El trazado de límites y la intervención en la jerarquía familiar son técnicas centrales de la escuela estructural de Minuchin, donde el terapeuta reorganiza la estructura familiar para reforzar límites claros y una jerarquía funcional, facilitando la comunicación y la resolución de conflictos; las demás opciones corresponden a enfoques distintos: la escuela estratégica de Haley se centra en la generación de tareas y la alteración de patrones de interacción, la teoría intergeneracional de Bowen enfatiza la separación del yo y el análisis de ciclos familiares a lo largo de generaciones, y la terapia experiencial de Satir pone énfasis en la expresión emocional y la autoafirmación, por lo que no abordan directamente la delimitación estructural ni la jerarquía familiar.'),
  (385, 'En la terapia psicoanalítica las técnicas de cambio se centran en la interpretación de los procesos inconscientes que se manifiestan en la relación terapéutica, y en la confrontación de las resistencias que impiden la integración de esos contenidos; la clarificación, por su parte, permite al paciente articular y comprender las interpretaciones, facilitando la internalización de los cambios. Por ello la opción B reúne los elementos esenciales: la interpretación, la confrontación de resistencias y la clarificación, que son las herramientas primarias para generar el cambio clínico en el marco psicoanalítico. Las demás alternativas son incorrectas porque la A incluye la transferencia y contratransferencia como técnicas de cambio, cuando son fenómenos que deben ser analizados y no se utilizan directamente como herramientas de intervención; la C menciona la clarificación pero omite la confrontación, y el análisis de resistencias por sí solo no constituye una técnica de cambio; la D incluye la asociación libre y la atención flotante, que son técnicas de exploración, y la confrontación, pero la combinación no refleja el conjunto de técnicas de cambio reconocidas en el psicoanálisis.'),
  (386, 'El programa de tratamiento de Clare Philips (1987/1991) se diseñó específicamente para pacientes con dolor crónico, integrando intervenciones cognitivas y conductuales orientadas a la reestructuración de creencias disfuncionales sobre el dolor, la reducción de la evitación y el aumento de la actividad funcional; la evidencia clínica de la época demuestra su eficacia en la disminución de la intensidad percibida y la mejora de la calidad de vida en esta población, lo que justifica su aplicación en ese contexto. Las demás opciones son inexactas: la opción B se refiere a trastorno bipolar, un grupo que no fue objeto de estudio de este programa; la opción C menciona ansiedad social, que no corresponde al objetivo original del tratamiento; y la opción D indica un régimen ambulatorio para esquizofrenia, lo cual no coincide con la naturaleza de la intervención de Philips, la cual se centraba en el dolor crónico y no en la psicoterapia ambulatoria para esquizofrenia.'),
  (387, 'La obtención y uso de feedback constituye el factor de mayor nivel de eficacia en la relación terapéutica porque permite al terapeuta ajustar continuamente la intervención a las necesidades del paciente, basándose en datos objetivos sobre el progreso y la percepción del tratamiento; la evidencia empírica muestra que la retroalimentación sistemática mejora los resultados clínicos al promover la autoobservación del paciente y la colaboración activa, lo que fortalece la alianza y la motivación. El uso de autorrevelaciones (A) puede reforzar la alianza pero su impacto es variable y depende de la adecuación contextual, por lo que no alcanza el mismo nivel de eficacia demostrada; la promoción de la credibilidad del tratamiento (B) es importante para la adherencia, pero su efecto es indirecto y no tan robusto como el feedback directo; el manejo de la contratransferencia (C) es esencial para la integridad del proceso, pero constituye una estrategia de gestión interna del terapeuta y no un factor de eficacia directa sobre el resultado del paciente.'),
  (388, 'La investigación de Norcross y Lambert (2019) demuestra que los factores que mejor predicen el resultado de la terapia son las características del paciente, pues la evidencia muestra que la motivación, la gravedad de los síntomas, la historia clínica y la disposición a colaborar determinan en gran medida la respuesta al tratamiento; estos rasgos interactúan con la relación terapéutica y con la intervención específica, pero son los que más influyen en el curso y la eficacia de la terapia. Por el contrario, las técnicas específicas empleadas (opción B) y el modelo teórico del psicólogo (opción C) tienen un efecto modesto y a menudo no superan la variabilidad explicada por las características del paciente, mientras que los factores comunes (opción D) son importantes pero no alcanzan la misma fuerza predictiva que la información individual del paciente.'),
  (389, 'La afirmación falsa es la C; la evidencia empírica indica que la percepción del paciente sobre la calidad de la alianza es la que mejor predice los resultados terapéuticos, mientras que la percepción del terapeuta suele sobreestimar la alianza y no añade valor predictivo adicional, por lo que su capacidad predictiva es inferior o equivalente a la del paciente; en contraste, la opción A se sustenta en numerosos estudios longitudinales que muestran que una alianza sólida anticipa mejor la mejoría clínica, la opción B se confirma en meta‑análisis que abarcan diversas modalidades terapéuticas (psicodinámica, cognitivo‑conductual, humanista, etc.), y la opción D está respaldada por investigaciones que demuestran que la reparación de rupturas fortalece la confianza y la colaboración, mejorando la relación terapéutica y los resultados clínicos.'),
  (390, 'La técnica de búsqueda de excepciones es el elemento distintivo de la terapia centrada en soluciones, pues consiste en identificar momentos en los que el problema no se presenta, lo que permite al paciente reconocer recursos y estrategias que ya funcionan, reforzando la percepción de control y la construcción de una visión orientada a resultados; las otras opciones corresponden a conceptos de enfoques distintos: la desesperanza creativa es una intervención de la terapia cognitivo‑conductual, la tarea del tigre se relaciona con la terapia de aceptación y compromiso, y la técnica de la rejilla pertenece a la terapia de esquemas.'),
  (391, 'En el protocolo unificado de Barlow y colaboradores, la exposición a sensaciones físicas se centra en la valoración de la intensidad subjetiva del malestar que la sensación provoca (grado de malestar) y en la percepción de similitud entre la sensación actual y las experiencias previas que han generado ansiedad (similitud), pues estas dos variables permiten medir la respuesta emocional y la discriminación sensorial que guían la progresión de la exposición; las otras opciones fallan porque el nivel de ansiedad y evitación (A) se emplea para evaluar la respuesta general a estímulos externos, el grado de dificultad y aversión (B) se reserva para tareas conductuales, y el nivel de dominio y agrado (D) corresponde a la valoración de habilidades de afrontamiento, no a la exposición sensorial.'),
  (392, 'En la terapia dialéctica-conductual (TDC) las habilidades de tolerancia al malestar se organizan en dos bloques: las de “supervivencia a la crisis” y las de “aceptación de la realidad”; la segunda se refiere a la capacidad de tolerar el sufrimiento sin intentar cambiarlo, aceptando la situación tal como es, lo cual es esencial para reducir la impulsividad y la autolesión en el trastorno límite de la personalidad. Las demás opciones no corresponden a este bloque: la atención plena (A) se ubica dentro de la regulación emocional, la regulación emocional (B) y la eficacia interpersonal (C) pertenecen a los módulos de “regulación emocional” y “eficacia interpersonal” respectivamente, y no a la tolerancia al malestar.'),
  (393, 'El concepto de difusión de identidad, que describe la falta de una estructura coherente y estable de la propia identidad, se desarrolló de manera sistemática en la teoría de la personalidad de Otto Kernberg, quien integró esta noción dentro de su modelo de trastornos de la personalidad narcisista y borderline, enfatizando la fragilidad del yo y la tendencia a la idealización y devaluación de los demás como mecanismos compensatorios; las demás opciones son incorrectas porque Linehan se centra en la terapia dialéctico‑conductual para el trastorno límite, Fonagy en la teoría del apego y la teoría de la mente, y Kohut en la psicología del self y la psicoterapia del self, sin abordar la difusión de identidad como tal.'),
  (394, 'La terapia dialéctica-conductual (TDC) propuesta por Linehan (1993) se fundamenta en la teoría biosocial, que explica el TLP como resultado de la interacción entre una predisposición biológica a la impulsividad y la invalidación ambiental, y en la teoría dialéctica, que enfatiza la necesidad de equilibrar la aceptación y el cambio mediante estrategias de regulación emocional y habilidades de tolerancia al estrés; por tanto la opción d) es la que recoge ambas bases teóricas. Las demás alternativas son incorrectas porque la teoría del marco relacional (A) y la teoría del apego (B) no son centrales en la TDC, la teoría de la mente (C) tampoco forma parte de la conceptualización original, y la combinación de la teoría del apego con la modificación de conducta (B) corresponde más a enfoques integrados de terapia cognitivo-conductual que a la TDC; en conjunto, las opciones A, B y C comparten el error de incluir teorías que no sustentan la estructura conceptual de la TDC.'),
  (395, 'El modelo que emplea la terapia cognitivo‑analítica (TCA) para abordar los trastornos de la personalidad se denomina “modelo de estados múltiples del self”; la TCA sostiene que la personalidad se compone de distintos estados del self, cada uno con sus propias representaciones, emociones y conductas, y que la disociación entre estos estados produce los síntomas patológicos; la intervención se centra en integrar estos estados, modificando las creencias disfuncionales y promoviendo la coherencia interna, lo que explica por qué la opción B es la que corresponde. Las demás alternativas son incorrectas porque el “modelo dialógico del self” pertenece a la terapia dialógica, el “modelo cognitivo del self” es una formulación general de la teoría del self que no especifica la integración de estados, y el “modelo del procedimiento secuenciado” no corresponde a ninguna propuesta reconocida dentro de la TCA.'),
  (396, 'El perfil mentalizador evalúa la capacidad de interpretar estados mentales en tres dimensiones esenciales: la automatización del proceso (automática versus controlada), la referencia al objeto (otro versus uno mismo) y la orientación del contenido (interno versus externo), además de la distinción entre procesos cognitivos y afectivos (cognitiva versus afectiva); por tanto la opción que recoge todas estas dimensiones es la C. Las alternativas A y B omiten la dimensión interna‑externa, esencial para diferenciar la interpretación de estados mentales propios frente a los de los demás, mientras que la D añade una dimensión “social versus individual” que no forma parte del marco teórico de la mentalización según Fonagy y Bateman.'),
  (397, 'La opción d) es la que describe adecuadamente la organización borderline según la teoría de la transferencia: los pacientes presentan defensas primitivas (por ejemplo, idealización y desvalorización), una prueba de realidad que suele estar comprometida (no se mantiene de forma coherente) y una identidad difusa, sin una estructura sólida y estable, lo que facilita la fluctuación de la transferencia en la relación terapéutica; la presencia de defensas primitivas explica la tendencia a proyectar emociones intensas y la falta de una identidad estable explica la inestabilidad de la transferencia. Las demás alternativas fallan porque la opción a) combina defensas primitivas con una prueba de realidad y una identidad sólidas, lo cual no corresponde a la organización borderline; la opción b) menciona un fallo en la prueba de realidad pero sugiere una identidad difusa, pero incluye defensas primitivas, lo cual es correcto, sin embargo la combinación de “fallo en la prueba de realidad” con “difusión de identidad” no se presenta en la respuesta d) y se considera menos precisa; la opción c) introduce defensas evolucionadas y una identidad sólida, lo que contrasta con la naturaleza primitiva y difusa de la identidad en el trastorno límite.'),
  (398, 'El constructo “Autoritarismo de derechas” de Altemeyer se compone de tres dimensiones: convencionalismo, agresión autoritaria y sumisión autoritaria, las cuales describen la adhesión a normas tradicionales, la hostilidad hacia grupos “otros” y la obediencia a la autoridad, respectivamente; la opción D, liderazgo autoritario, no forma parte de este modelo, pues Altemeyer no lo incluye como dimensión del autoritarismo, sino que lo considera una característica de la personalidad autoritaria en general, no específica del constructo de derechas. Las opciones A, B y C sí están definidas explícitamente en la teoría, por lo que no pueden descartarse.'),
  (399, 'La afirmación A es la única incorrecta porque la terapia metacognitiva de Wells no se centra en el contenido específico de los pensamientos, sino en la forma en que los individuos procesan, evalúan y responden a esos pensamientos; el modelo postula que la metacognición (creencias sobre el propio pensamiento, estrategias de control cognitivo y preocupación por el contenido) es la variable que mantiene el trastorno, no el contenido en sí. En cambio, la opción B es coherente con la teoría, ya que el distanciamiento (dejar que el pensamiento exista sin involucrarse) no implica necesariamente su aceptación ni su eliminación, sino que se busca cambiar la relación con el pensamiento. La opción C resume correctamente la ampliación del foco de las terapias cognitivo-conductuales tradicionales al incluir la metacognición como eje central. Finalmente, la opción D describe con precisión la combinación de técnicas de reestructuración cognitiva, experimentos conductuales y entrenamiento atencional que caracterizan la intervención metacognitiva. Las demás opciones comparten la misma razón de error: todas describen correctamente los principios y componentes de la terapia metacognitiva, mientras que la opción A presenta una concepción errónea del modelo.'),
  (400, 'En la programación de actividades de la terapia cognitiva de Beck, el objetivo es evaluar la percepción subjetiva del paciente sobre la utilidad y el disfrute de las actividades, ya que la falta de gratificación y el bajo dominio cognitivo son factores que perpetúan la depresión; por ello se registra el grado de dominio y agrado (opción B), lo que permite identificar patrones de evitación y reforzar la motivación intrínseca. La frecuencia de episodios de tristeza (A) y su duración (C) son más relevantes para el diagnóstico y la monitorización de la gravedad, pero no se utilizan en la programación de actividades, que se centra en la experiencia de la actividad en sí. La valoración del grado de creencia en los esquemas depresógenos (D) corresponde a la fase de reestructuración cognitiva, no a la fase de registro de actividades, por lo que las opciones A, C y D no cumplen con el propósito específico de la técnica.'),
  (401, 'La opción B es la que se ajusta a la evidencia neuropsicológica sobre el autismo; estudios de neuroimagen han mostrado que el volumen aumentado de la corteza dorsolateral frontal se asocia con déficits en la atención ejecutiva, ya que esta área participa en la planificación, el control inhibitorio y la flexibilidad cognitiva, funciones que suelen estar alteradas en el trastorno del espectro autista. En contraste, la opción A es incorrecta porque la heminegligencia por desconexión parietofrontal implica una pérdida de la atención sostenida, pues la corteza parietal y frontal son esenciales para mantener la alerta tónica. La opción C falla porque el trastorno de hiperactividad con déficit de atención sí presenta alteraciones en la corteza cingulada anterior, la cual regula la vigilancia y la respuesta a estímulos distractores. Finalmente, la opción D es errónea: el síndrome de Balint, causado por lesiones bilaterales en los lóbulos parietales, produce ataxia visual y óptica, pero también afecta la orientación atencional, ya que la corteza parietal es clave para la integración espacial y la atención dirigida.'),
  (402, 'La opción D es la que corresponde a la práctica clínica establecida para la fobia a la sangre, inyecciones o daño, ya que la técnica de tensión aplicada de Öst y Sterner se emplea específicamente para prevenir el desmayo mediante la contracción voluntaria de los músculos de la cara, cuello y tronco, lo que aumenta la presión arterial y evita la vasodilatación que conduce a la síncope; esta intervención se basa en la evidencia de que la tensión muscular activa mecanismos fisiológicos que contrarrestan la respuesta de hipotensión postural típica de la fobia vasovagal. Las demás alternativas son incorrectas: la A se refiere a la relajación, que en realidad puede favorecer la caída de la presión arterial y empeorar el riesgo de desmayo; la B menciona la exposición con prevención de respuesta, una técnica útil pero no la más adecuada para controlar el desmayo, ya que no aborda directamente la respuesta fisiológica; la C confunde la tensión aplicada con la relajación de grandes grupos musculares, lo cual es contrario a la técnica de Öst y Sterner, que exige contracción activa para elevar la presión arterial.'),
  (403, 'La terapia interpersonal y del ritmo social (TIPR) es la modalidad psicológica que se orienta específicamente a la regulación de las rutinas diarias en el trastorno bipolar, pues se basa en la premisa de que la estabilidad de los ritmos circadianos y sociales (horarios de sueño, alimentación, actividad y relaciones interpersonales) constituye un factor protector contra los episodios maníacos y depresivos; por ello, el tratamiento incluye la identificación y modificación de patrones de comportamiento que alteran estos ritmos, el establecimiento de horarios regulares y la mejora de la comunicación interpersonal para reforzar la adherencia a la rutina. Las otras opciones no comparten este enfoque: la terapia de aceptación y compromiso (TAC) y la terapia centrada en la compasión se centran en la aceptación de experiencias internas y la auto‑compasión, sin un objetivo explícito de regular la vida cotidiana; la terapia sistémica aborda la dinámica familiar o de grupo, pero no se dirige de manera específica a los ritmos diarios del individuo.'),
  (404, 'La opción C es la única que refleja la epidemiología establecida de las fobias específicas: su inicio más frecuente se observa en la infancia, típicamente entre los 7 y 11 años, cuando la cognición simbólica y la capacidad de asimilar experiencias de riesgo están en pleno desarrollo, favoreciendo la aparición de temores concretos y rígidos; en contraste, la opción A es errónea porque las fobias específicas suelen ser crónicas y persistentes, no transitorias; la B es incorrecta pues la adolescencia representa un período de consolidación de la identidad y de mayor exposición a situaciones sociales, pero no es la etapa de inicio más frecuente; y la D se descarta porque la primera edad adulta no es la fase de aparición habitual, sino más bien un momento de posible exacerbación o reconocimiento clínico, no de inicio.'),
  (405, 'La opción C es la que se ajusta a la evidencia neurobiológica del proceso de reconsolidación, pues la disminución de la fosforilación de los receptores de glutamato GluR1 se ha identificado como un marcador molecular que indica la reactivación y posterior modificación de la memoria, diferenciándose de la fosforilación que se asocia con la consolidación inicial; la opción A es errónea porque el lóbulo temporal medial y el hipocampo participan principalmente en la consolidación de la memoria a largo plazo, no en el mantenimiento de la memoria a corto plazo, que depende de la corteza prefrontal y otras estructuras corticales; la B se basa en un concepto incorrecto, ya que las regiones visuales primarias y la corteza parietal inferior están implicadas en la percepción visual y la atención, no en la generación de falsos recuerdos, que se relacionan más con la memoria episódica y la integración de la información; y la D es falsa porque la conversión de memoria a corto a largo plazo implica tanto síntesis proteica como cambios morfológicos, como la formación de nuevas sinapsis y la plasticidad sináptica.'),
  (406, 'La reducción del miedo observada durante la exposición se explica por la habituación, proceso en el cual la respuesta fisiológica y conductual al estímulo aversivo disminuye con la repetición sin que se produzca un cambio en la asociación estímulo‑respuesta; en la exposición sistemática el organismo aprende que el estímulo no implica peligro real, lo que lleva a una disminución progresiva de la activación del sistema límbico y de la respuesta de alarma, fenómeno que se documenta con la disminución de la frecuencia cardíaca, la tensión arterial y la actividad de la corteza prefrontal. La extinción (opción B) se refiere a la desaparición de una respuesta condicionada cuando el estímulo condicionado se presenta sin el estímulo incondicionado, pero no implica la reducción gradual de la respuesta en cada presentación, sino la pérdida de la asociación; la sensibilización (C) describe el aumento de la respuesta a estímulos repetidos, lo que es opuesto al fenómeno de exposición. La respuesta de orientación (D) se relaciona con la dirección de la atención hacia estímulos relevantes y no con la disminución de la respuesta de miedo; por tanto, solo la habituación describe correctamente el proceso psicofisiológico subyacente a la reducción del miedo en la exposición.'),
  (407, 'La opción C es la que se ajusta a la teoría del aprendizaje operante y la discriminación funcional: la utilidad de generalizar o discriminar depende de las demandas ambientales, pues la discriminación es ventajosa cuando las respuestas deben diferenciarse para maximizar el refuerzo, mientras que la generalización facilita la respuesta cuando las condiciones son similares y el refuerzo es más amplio; por tanto, la adaptabilidad se determina por el contexto. La alternativa A es falsa porque los estímulos discriminativos sí pueden generalizarse, aunque con menor intensidad, y la generalización es un fenómeno inherente a cualquier estímulo. La B es incorrecta porque la generalización no aumenta con reforzamiento diferencial; de hecho, el reforzamiento diferencial tiende a reducir la generalización al fortalecer la respuesta solo al estímulo discriminativo. La D es errónea porque una mayor generalización suele conllevar una menor precisión y ajuste fino al medio, pues la respuesta se aplica a estímulos más heterogéneos, reduciendo la discriminación necesaria para la adaptación específica.'),
  (408, 'El fenómeno descrito corresponde al **ensombrecimiento**: cuando el estímulo dominante (los dibujos) suprime o eclipsa la respuesta al estímulo más sutil (las palabras), de modo que el niño asocia la información principalmente con el elemento visual más llamativo, relegando el aprendizaje de la lectura a un segundo plano; este proceso se explica por la mayor saliencia y el mayor número de señales asociadas a los dibujos, que capturan la atención y facilitan la codificación semántica, mientras que las palabras, con menor intensidad perceptiva y menor número de pistas, quedan relegadas. Las demás opciones son incorrectas: el condicionamiento visual implicaría una asociación entre estímulos visuales y respuestas condicionadas, pero no explica la supresión del aprendizaje de las palabras; la generalización se refiere a la transferencia de una respuesta aprendida a estímulos similares, no a la preferencia por un tipo de estímulo; y la equivalencia del estímulo se relaciona con la sustitución de un estímulo por otro con la misma función, lo cual no se observa en este caso.'),
  (409, 'El concepto de reactancia psicológica de Brehm describe el fenómeno por el cual una persona, al percibir una amenaza a su libertad o autonomía, adopta una actitud contraria a la que se le exige, buscando afirmar su independencia; esta explicación se fundamenta en la teoría de la motivación de la libertad, donde la reacción de oposición se interpreta como un esfuerzo por restaurar el control percibido sobre la propia conducta, lo que explica la conducta de hacer lo opuesto a lo que se le pide. Las opciones A y D son incorrectas porque la reactancia no se relaciona con el cumplimiento de normas ni con miedos motivacionales, sino con la defensa de la autonomía; la opción B, aunque menciona la sensación de falta de control, no captura el aspecto de la conducta contraria que caracteriza la reactancia.'),
  (410, 'La teoría del marcador somático de Damasio sostiene que las decisiones racionales se fundamentan en la integración de la información emocional que se origina en la actividad somática; por ello la respuesta que refleja esta concepción es la opción B, ya que indica que el procesamiento de la emoción depende del procesamiento que se haga de la información somática, lo que concuerda con la idea de que los marcadores somáticos guían el razonamiento. Las demás alternativas son erróneas: la A niega la influencia emocional en el razonamiento, contradiciendo el núcleo de la teoría; la C atribuye la emoción al hemisferio izquierdo, aunque la evidencia sugiere una participación bilateral y no específica de un hemisferio; y la D menciona la glándula pineal, que no tiene relación con el proceso de marcadores somáticos propuesto por Damasio.'),
  (411, 'El fenómeno descrito corresponde a la expansión de la respuesta, según la Ley de Stevens, la cual establece que la intensidad percibida de un estímulo no aumenta linealmente con la magnitud física, sino que sigue una función potencia; al duplicar la corriente eléctrica, la sensación desagradable crece de manera mayor que el doble, reflejando la expansión de la respuesta. Las demás opciones son incorrectas: la opción A, “fenómeno de líneas rectas”, no corresponde a ninguna teoría de la percepción; la C, “comprensión de la respuesta”, no es un término reconocido en la psicología de la percepción; y la D, que sugiere que la teoría no explica el fenómeno, es falsa porque la Ley de Stevens sí lo contempla mediante la expansión.'),
  (412, 'La hipótesis de Sapir‑Whorf sostiene que la lengua que hablamos condiciona la forma en que percibimos y conceptualizamos la realidad; por ello la opción A es la única que contradice la premisa fundamental de la teoría, pues afirma que el lenguaje no influye en los procesos cognitivos, lo cual es incompatible con la idea de que la estructura lingüística moldea la cognición. Las demás alternativas son consistentes con la hipótesis: la B señala la relación entre pensamiento y lenguaje, la C reconoce la posibilidad de que el lenguaje afecte la cognición y la D describe la idea de que la estructura de una lengua determina la visión del mundo de su hablante nativo; todas reflejan los postulados de la teoría, por lo que no son incorrectas.'),
  (413, 'La conducta de María se explica por la interferencia proactiva, fenómeno en el que la información previamente aprendida (el número de piso anterior) dificulta la adquisición o el recuerdo de nueva información (el número de piso actual), de modo que la respuesta habitual se mantiene aun cuando ya no es pertinente; este mecanismo se basa en la persistencia de la memoria semántica y la automatización de la respuesta asociada al número 3. Las demás opciones son incorrectas: el “número mágico” se refiere a la capacidad de retener una lista de números en la memoria de trabajo, no a la persistencia de una respuesta automatizada; la interferencia constructiva implica la combinación de estímulos que facilitan la recuperación, lo cual no ocurre en este caso; la interferencia retroactiva describe la interferencia de nueva información sobre la anterior, pero aquí la interferencia es de la información vieja sobre la nueva.'),
  (414, 'Los heurísticos son atajos cognitivos que empleamos para simplificar la toma de decisiones, basados en reglas de pulgar que reducen la carga de procesamiento y se aplican de forma automática; por ello se describen como estrategias generales de predicción (opción A) y pueden derivarse tanto de cálculos de similitud con prototipos como de la recuperación de casos previos (opción C), y su uso frecuente genera sesgos sistemáticos como el de disponibilidad o el de anclaje (opción D). En cambio, la opción B es errónea porque los modelos normativos pretenden describir cómo *debería* tomarse una decisión bajo criterios de racionalidad y optimización, mientras que los heurísticos pertenecen a los modelos descriptivos, que explican cómo la gente realmente actúa, con sus limitaciones y desviaciones de la racionalidad. Las demás alternativas, por tanto, son consistentes con la teoría de los heurísticos.'),
  (415, 'La opción B es la que resulta incorrecta porque los procesos automáticos, a diferencia de los procesos controlados, no se activan de manera espontánea sin entrenamiento; de hecho, su automatización depende de la práctica y la repetición que consolidan la respuesta en la memoria procedimental, por lo que requieren un aprendizaje previo para que se vuelvan automáticos. En cambio, la opción A es coherente con la definición de procesos automáticos, pues su ejecución demanda un bajo consumo de recursos atencionales, lo que permite que la persona pueda realizar otras tareas simultáneamente. La alternativa C también es válida, pues los procesos automáticos no generan nuevos aprendizajes por sí mismos; simplemente ejecutan patrones ya consolidados. Finalmente, la opción D es correcta, ya que la automatización reduce la interferencia con procesos concurrentes, facilitando la ejecución simultánea de varias tareas.'),
  (416, 'El coeficiente de correlación biserial es el que se emplea cuando una de las variables es continua (la velocidad de procesamiento medida por el número de respuestas correctas) y la otra es dicotómica derivada de una variable continua (la inteligencia, que se ha dividido en alta y baja a partir de la media de 107); la correlación biserial estima la relación que existiría entre las dos variables originales continuas, ajustando la dicotomía mediante la densidad de la distribución normal de la variable continua. Las demás alternativas son inadecuadas: el coeficiente parcial (A) se utiliza para controlar el efecto de una tercera variable, lo que no se plantea aquí; el coeficiente Phi (C) corresponde a tablas de contingencia 2×2 con ambas variables dicotómicas, y la correlación tetracórica (D) se aplica cuando ambas variables son ordinales con cuatro categorías, lo que no corresponde al diseño descrito.'),
  (417, 'La potencia estadística se incrementa cuando el tamaño del efecto es mayor y la variabilidad poblacional es menor, porque la relación señal‑ruido mejora y el contraste entre grupos se vuelve más evidente; por ello la opción A describe correctamente la situación en la que la potencia aumenta. En contraste, la opción B describe una situación de baja potencia, ya que una muestra reducida y alta dispersión dificultan la detección del efecto. La opción C es incorrecta porque un nivel de significación alto (α elevado) aumenta la probabilidad de error tipo I y, al mismo tiempo, la potencia, no la disminuye; además, un tamaño de muestra grande favorece la potencia, no la reduce. La opción D es errónea porque, aunque el tamaño del efecto sea grande, un desvío estándar poblacional elevado reduce la relación señal‑ruido, lo que atenúa la potencia; por lo tanto, las respuestas B, C y D comparten el error de confundir los efectos de la variabilidad y el nivel de significación sobre la potencia.'),
  (418, 'La corrección de Bonferroni y los procedimientos post hoc como HSD de Tukey reducen la probabilidad de cometer un error Tipo I al ajustar el nivel de significación para cada comparación múltiple, evitando la inflación del error de primera especie que se produce cuando se realizan varias pruebas simultáneamente; por tanto la opción D es la que describe la ventaja de estos métodos. Las demás alternativas son incorrectas: la opción A es falsa porque el ajuste de Bonferroni y Tukey tienden a disminuir la potencia estadística, no aumentarla; la B es correcta en cuanto a su efecto, pero no corresponde a la ventaja planteada; la C es errónea porque la reducción del error Tipo I suele ir acompañada de un aumento del error Tipo II, no de su disminución.'),
  (419, 'El índice de Fisher (skewness de Fisher‑Pearson) es el más adecuado para medir la asimetría porque calcula la media de los cubos de las desviaciones estándar de cada puntuación, normalizando por la desviación típica al cubo; de esta forma incorpora la información de todas las observaciones y produce una estimación no sesgada de la asimetría poblacional, lo que lo hace robusto frente a la presencia de valores atípicos y a la distribución de la muestra. El intercuartílico, aunque basado en índices de posición, no refleja la forma completa de la distribución y se limita a la dispersión entre cuartiles, por lo que no captura la asimetría de manera precisa. El de Pearson, que se basa únicamente en la diferencia entre la media y la mediana, es sensible a la presencia de valores extremos y no utiliza toda la información de la muestra, lo que lo hace menos fiable. El coeficiente de variación, por su parte, mide la relación entre la desviación típica y la media para evaluar la variabilidad relativa, pero no está diseñado para describir la asimetría de la distribución.'),
  (420, 'La opción A es la más adecuada porque la hipótesis H1 compara las distribuciones de los CI entre dos grupos independientes (varones y mujeres); el test t de muestras independientes (o su equivalente no paramétrico, Mann‑Whitney) es el procedimiento estándar para evaluar diferencias en medias o medianas cuando los datos son comparables entre grupos, mientras que la hipótesis H2 plantea una comparación directa de las medias de CI entre los mismos grupos, por lo que un t‑test para muestras independientes también es apropiado; las demás alternativas son inadecuadas: la B emplea correlaciones (Spearman y Pearson) que miden asociación entre variables continuas, no diferencias entre grupos; la C propone un t‑test para muestras relacionadas, que solo aplica cuando las observaciones están emparejadas, lo cual no es el caso, y un chi‑cuadrado que evalúa frecuencias, no medias; la D usa el test de Wilcoxon (para muestras relacionadas) y la prueba binomial de signos, ambos diseñados para datos pareados o de orden, y tampoco se ajustan a la comparación de medias entre dos poblaciones distintas.'),
  (421, 'La opción B es la que refleja la ventaja de los diseños experimentales con medidas repetidas frente a los de muestras independientes: al emplear el mismo grupo de participantes en todas las condiciones, se reduce la variabilidad interindividual, lo que permite detectar efectos con menos sujetos y, por tanto, resulta más económico en cuanto al número de participantes necesarios; además, la potencia estadística aumenta porque la variabilidad entre sujetos se controla. Las demás alternativas son incorrectas: la opción A describe una desventaja, ya que la pérdida de participantes entre condiciones suele ser mayor en diseños de medidas repetidas; la opción C menciona el efecto de orden, que es un riesgo potencial que debe controlarse, no una ventaja; y la opción D señala la necesidad de listas diferentes, lo cual es una característica de los diseños de muestras independientes, no de los de medidas repetidas.'),
  (422, 'La afirmación correcta es la B porque el nivel de significación α=0,005 define la probabilidad de cometer un error tipo I, es decir, rechazar la hipótesis nula cuando en realidad es verdadera; por tanto, la probabilidad de que ocurra ese error es exactamente 0,005. La opción A confunde el error tipo II (falso negativo) con el error tipo I, pues la probabilidad de mantener H0 cuando es falsa corresponde a 1‑β, no a α. La opción C presenta un valor que sería la probabilidad de no cometer un error tipo I (1‑α), pero se refiere a mantener H0 siendo falsa, lo cual es incorrecto. La opción D mezcla el error tipo I con la probabilidad de no cometerlo, dando 0,995, pero esa cifra corresponde a 1‑α y no a la probabilidad de rechazar H0 cuando es verdadera.'),
  (423, 'El principio que predomina en caso de conflicto entre dos o más de los principios de Beauchamp y Childress es el de la evaluación contextual, pues la ética clínica exige que el profesional analice la situación concreta para determinar cuál principio debe ser prioritario; esta postura se fundamenta en la idea de que la aplicación de los principios no es automática ni jerárquica, sino que depende de la complejidad del caso y de los valores en juego, lo que permite un juicio ético más flexible y realista. Las opciones A, B y C son incorrectas porque cada una presenta un principio de manera aislada y sin reconocer la necesidad de ponderar los demás principios en situaciones de conflicto, lo que contradice la posición de Beauchamp y Childress de que la ética clínica debe ser contextualizada y no rígidamente jerarquizada.'),
  (424, 'La relación dual se define como aquella en la que el profesional mantiene simultáneamente una relación terapéutica y otra relación distinta (por ejemplo, laboral, académica, familiar o de amistad) con el mismo paciente, lo que genera un conflicto de intereses y una potencial pérdida de objetividad clínica; por ello, la normativa ética de la psicología prohíbe expresamente este tipo de vínculos para salvaguardar la integridad del proceso terapéutico. La opción A, “adicional abusiva”, no corresponde a un término reconocido en la literatura ética y parece una confusión con la noción de abuso de poder; la C, “sumativa”, no es un concepto de relación profesional y la D, “de poder”, sugiere una relación de dominio pero no describe la coexistencia de dos vínculos distintos, por lo que ambas alternativas resultan incorrectas.'),
  (425, 'El término que describe el conjunto de características idiosincrásicas que cada psicólogo aplica a la práctica clínica, influyendo en su modo de actuar durante la sesión, es el “Estilo Personal del Terapeuta”; este concepto abarca la combinación de disposiciones, valores, experiencias y preferencias que guían la interacción terapéutica y se manifiesta en la forma de establecer la relación, seleccionar técnicas y responder a las dinámicas del paciente, constituyendo así un patrón de conducta profesional distintivo. Las otras opciones son inadecuadas: el “Estilo Cognitivo” se refiere a la manera de procesar información y no a la conducta clínica general; los “Rasgos de Personalidad” son características estáticas del individuo, no un conjunto de conductas aplicadas al contexto terapéutico; y la “Función Involucración” no corresponde a un término reconocido en la literatura psicoterapéutica para describir la conducta del terapeuta.'),
  (426, 'En la evaluación psicológica, las matrices de interacción y los mapas de conducta se emplean como protocolos observacionales de conducta porque permiten registrar sistemáticamente las interacciones entre el individuo y su entorno, describiendo patrones de comportamiento en contextos específicos y facilitando la cuantificación de la frecuencia y la intensidad de las conductas observadas; esto difiere de las escalas de apreciación, que se centran en la valoración subjetiva de rasgos o síntomas, y de los procedimientos automáticos de muestreo, que se basan en la captura de datos sin intervención directa del evaluador, mientras que los registros narrativos describen de forma cualitativa y no estructurada las conductas observadas, sin la rigurosidad de un protocolo estandarizado.'),
  (427, 'El instrumento que corresponde a un test de 10 ítems elaborado por la OMS es el AUDIT (Alcohol Use Disorders Identification Test) de Babor y colaboradores; la OMS lo publicó en 1992 como una herramienta breve, de fácil aplicación y validada en múltiples contextos culturales, diseñada específicamente para la detección rápida de consumo problemático y trastornos por alcohol, con puntuaciones que permiten comparaciones internacionales. Las demás opciones son incorrectas: el ACQ mide la antojo de alcohol, no es de 10 ítems ni de la OMS; el MALT es un test de Munich de 1977, con más de 10 ítems y no tiene respaldo de la OMS; el CAGE es un cuestionario de 4 ítems, breve pero no desarrollado por la OMS y orientado a la identificación de dependencia, no a la detección rápida y comparativa internacional.'),
  (428, 'La opción A es la que recoge los tres criterios fundamentales que Fernández‑Ballesteros et al. (2013) establecen para que una medida pueda fundamentar la valoración de un tratamiento psicológico: la fiabilidad, que garantiza la consistencia y estabilidad de los resultados; la validez, que asegura que la prueba mide lo que pretende medir y que sus resultados son interpretables en el contexto clínico; y la utilidad, que implica que la herramienta sea práctica, relevante y aporte información útil para la toma de decisiones terapéuticas. Las demás alternativas son incorrectas porque la B confunde exactitud con precisión estadística sin referirse a la validez; la C menciona validez de constructo, pero sustituye la utilidad por eficacia y efectividad, conceptos que pertenecen a la evaluación de la intervención y no a la propia medida; y la D incluye consistencia interna y objetividad, que son subcomponentes de la fiabilidad, pero omite la validez y la utilidad, elementos esenciales para la valoración clínica.'),
  (429, 'La dimensión que no forma parte de las tres del carácter en el TCI‑R es la Persistencia, pues el modelo de Cloninger distingue las dimensiones de carácter como Autodirección, Cooperación y Autotrascendencia, cada una reflejando la internalización de valores y la regulación de la conducta; la Persistencia, por el contrario, se ubica dentro de las dimensiones de temperamento (como la Persistencia de la actividad), no del carácter, y por tanto no corresponde a la clasificación de carácter; las otras opciones sí corresponden a las tres dimensiones del carácter, por lo que no pueden considerarse incorrectas.'),
  (430, 'En la evaluación de la esquizofrenia se ha recurrido con frecuencia a la actividad electrodérmica, los potenciales evocados y los movimientos oculares como marcadores psicofisiológicos, pues cada uno refleja alteraciones en la respuesta autonómica, la función cortical y la coordinación motora, respectivamente, aspectos que se sabe que se ven afectados en la enfermedad; en cambio, la actividad respiratoria no se ha empleado de forma preferente, ya que su medición no aporta información específica sobre los déficits neuropsicológicos característicos de la esquizofrenia y su variabilidad fisiológica se ve influida por factores externos no relacionados con la patología. Las opciones A, B y D son marcadores con evidencia clínica y experimental de utilidad, mientras que la opción C carece de respaldo metodológico y clínico en la práctica habitual.'),
  (431, 'El PAI‑A, el Inventario de Evaluación de la Personalidad para Adolescentes de Morey, está diseñado específicamente para medir tanto rasgos de personalidad normal como disfuncionales, integrando escalas de psicopatología (por ejemplo, ansiedad, depresión, trastornos de la personalidad) y escalas de adaptación normal, lo que permite una evaluación integral de la personalidad en adolescentes; las otras opciones se centran exclusivamente en la personalidad normal (16PF‑APQ y 16PF‑5) o en la personalidad normal y la psicopatología de adultos (NEO PI‑R), pero no están adaptadas ni validadas para la población adolescente ni incluyen escalas de psicopatología tan amplias como el PAI‑A.'),
  (432, 'La prueba más adecuada es la Escala de Inteligencia de Reynolds (RIAS) porque está diseñada específicamente para niños de 6 a 16 años, ofrece una administración breve (alrededor de 20–30 min) y evalúa simultáneamente los dominios verbales y no verbales mediante tareas de comprensión verbal, razonamiento verbal, razonamiento no verbal y velocidad de procesamiento, lo que la hace idónea para un niño de 7 años cuando se requiere una valoración rápida y completa; la TONI‑4, aunque mide la inteligencia no verbal, no incluye una dimensión verbal y su aplicación suele ser más extensa; las Matrices Progresivas de Raven miden únicamente el razonamiento no verbal y no proporcionan una estimación de la inteligencia verbal, por lo que no cubre ambos aspectos; el WISC‑V, aunque es la prueba de inteligencia infantil más completa y actualizada, requiere una administración más larga (aproximadamente 60–90 min) y no es la opción más breve para una valoración rápida, por lo que las tres alternativas restantes son menos adecuadas por falta de brevedad o de cobertura completa de los dominios verbales y no verbales.'),
  (433, 'El diagnóstico del TDAH se basa en la evaluación clínica integral, que incluye la entrevista con el paciente y sus familiares, la observación directa, y la recopilación de información de múltiples contextos, especialmente la escuela, pero no se limita a ella; la guía diagnóstica (DSM‑5, ICD‑11) exige criterios clínicos y la presencia de síntomas en al menos dos entornos, por lo que la afirmación de que el diagnóstico es exclusivamente clínico es la que se alinea con la práctica estándar, pues la evidencia clínica es el pilar central y las pruebas neuropsicológicas, aunque útiles, son complementarias y no obligatorias. Las demás opciones son erróneas: la opción A sugiere un conjunto de pruebas específicas que no son indispensables ni obligatorias para el diagnóstico; la opción B minimiza la fiabilidad de la información parental, que suele ser valiosa y esencial; y la opción C reduce la recogida de datos a la escuela en casos dudosos, ignorando la importancia de la historia familiar y la evaluación clínica completa.'),
  (434, 'El Peabody Picture Vocabulary Test (PPVT‑III) es la única prueba de la lista que se emplea para medir la comprensión del lenguaje y que incluye una escala de cociente intelectual verbal (CI‑V) para niños a partir de los dos años y seis meses; su diseño consiste en la presentación de imágenes que el niño debe seleccionar en función de la palabra auditiva, lo que permite evaluar el vocabulario receptivo y, por extensión, la capacidad verbal. Las demás opciones presentan instrumentos que, aunque relacionados con el lenguaje, no cumplen con los criterios de edad ni de medición del CI verbal: la BLOC‑S‑R se centra en la producción y la estructura del lenguaje, no en la comprensión; el CEG evalúa la comprensión de estructuras gramaticales, pero no ofrece una escala de CI verbal; y el Test Boehm de Conceptos Básicos mide la comprensión conceptual y no la comprensión del lenguaje ni el CI verbal.'),
  (435, 'El Bedside de lenguaje (Sabe et al., 2008) constituye un test de cribado diseñado para detectar rápidamente alteraciones en la producción y comprensión del lenguaje, permitiendo identificar funciones que requieran una valoración más profunda; su estructura breve y su enfoque en tareas de denominación, comprensión y repetición lo convierten en una herramienta de screening eficaz, mientras que el Test-Barcelona 2, la Batería de afasias Western y el Test de Denominación de Boston son instrumentos de evaluación más extensos y detallados, orientados a la valoración exhaustiva de la afasia y no a la detección preliminar.'),
  (436, 'El nivel de gravedad 1 del DSM‑5 se define por la presencia de deficiencias en la comunicación social que, sin apoyo externo, generan dificultades significativas, pero que no impiden de manera sustancial el funcionamiento cotidiano; la persona puede iniciar interacciones sociales con esfuerzo y responder de forma atípica o insuficiente a la apertura de otros, y la inflexibilidad conductual produce interferencias moderadas en uno o más contextos, tal como se describe en la pregunta; los grados superiores (2 y 3) implican mayor severidad, con necesidad de apoyo intensivo y con interferencias más graves en la vida diaria, mientras que el grado 4, que no existe en la clasificación, sería una interpretación errónea de la escala.'),
  (437, 'El DSM‑5 establece que el diagnóstico de discapacidad intelectual y trastorno del espectro autista (TEA) se puede realizar de forma comórbida cuando el individuo presenta déficits significativos en el funcionamiento intelectual y adaptativo, y además manifiesta patrones persistentes de déficits en la comunicación social y en el comportamiento, intereses o actividades restringidos y repetitivos; el criterio A del TEA exige que dichos déficits en la comunicación social sean evidentes en la interacción interpersonal, lo que se refleja en un desempeño inferior al esperado para el nivel de desarrollo general, por lo que la opción A describe precisamente ese requisito; las demás alternativas se refieren a manifestaciones que pueden observarse en el TEA (B y C) pero no constituyen requisitos diagnósticos específicos, y la opción D, aunque la evaluación psicométrica es útil, no es un requisito indispensable para la confirmación diagnóstica según el DSM‑5.'),
  (438, 'El Inventario de Desarrollo Battelle (BDI) es una prueba estandarizada que evalúa el desarrollo infantil en las áreas de Motora, Adaptativa, Comunicación y Cognitiva, por lo que la afirmación de que no incluye la área cognitiva (opción A) es falsa; la prueba sí la contempla. La escala se administra a niños desde el nacimiento hasta los 8 años, con versiones específicas para cada rango de edad, lo que hace que la opción D sea la que corresponde, mientras que la alternativa B, que limita el rango a 6 años, es incorrecta. Además, el BDI no es una escala auto‑informada (opción C), ya que el evaluador observa y registra el desempeño del niño, por lo que esta opción también se descarta.'),
  (439, 'El acto de presionar un juguete para reproducir un sonido llamativo corresponde a la etapa 3 de la inteligencia sensorio‑motriz de Piaget, en la que el bebé consolida las reacciones circulares secundarias: la acción se repite de forma intencional y dirigida a un objetivo concreto, demostrando que ya ha superado la mera exploración sensorial y ha empezado a usar la acción para obtener una respuesta deseada; en la etapa 2 las reacciones son principalmente circulares primarias y no están dirigidas a un objetivo externo, mientras que en la etapa 4 la coordinación de esquemas secundarios permite la aplicación de patrones aprendidos a nuevas situaciones, lo que excede el simple acto de presionar el juguete, y en la etapa 5 las reacciones circulares terciarias implican la exploración de nuevas posibilidades y la manipulación de la causa‑efecto, algo que el bebé aún no ha alcanzado.'),
  (440, 'El egocentrismo intelectual en el periodo preoperatorio se caracteriza por la incapacidad de los niños para comprender que otras personas pueden tener perspectivas distintas a la propia; en este contexto el finalismo (A) se manifiesta cuando el niño interpreta los acontecimientos como una cadena de causas y efectos que culminan en un fin, una tendencia típica de la etapa preoperatoria; el animismo (B) se refiere a la atribución de cualidades animadas a objetos inanimados, una forma de pensamiento simbólico que también es frecuente en esta edad; el realismo (C) indica que el niño percibe los objetos y eventos tal como los presenta la realidad, sin distorsiones de la percepción, y es una característica de la etapa preoperatoria. En contraste, la reversibilidad (D) es una operación mental que permite al niño comprender que las transformaciones pueden revertirse, una capacidad que se desarrolla en la etapa de operaciones concretas (a partir de los 7 años), por lo que su inclusión en la lista de manifestaciones del egocentrismo intelectual preoperatorio es incorrecta. Las opciones A, B y C son correctas porque describen fenómenos típicos de la etapa preoperatoria, mientras que la opción D es incorrecta porque corresponde a una habilidad que aparece en una etapa posterior.'),
  (441, 'El reflejo descrito, en el cual la extensión de los dedos del pie en abanico se produce al estimular la planta del pie y se sigue de una flexión de los dedos, corresponde al reflejo de Babinski, característico de la respuesta anormal en adultos y de la respuesta normal en neonatos; su presencia indica una lesión del tracto corticoespinal o una inmadurez neurológica, por lo que la opción A es la única que describe ese patrón. La opción B, el reflejo Moro, implica una respuesta de retirada y extensión de brazos y piernas ante un estímulo súbito, no la extensión de los dedos del pie; la opción C, el reflejo patelar, se manifiesta con la contracción del músculo cuádriceps tras el golpe sobre el tendón patelar; y la opción D, la prensión plantar, se refiere a la flexión de los dedos del pie al tocar la planta, lo cual es contrario al patrón descrito.'),
  (442, 'Según Vygotsky el lenguaje interno, o pensamiento verbal, surge como una internalización de la interacción social y adquiere una función de regulación y planificación de la conducta, pues el niño utiliza la palabra interna para dirigir sus acciones y resolver problemas; por ello la opción C es la que refleja la teoría de la internalización del lenguaje como herramienta de control conductual. La alternativa A es incorrecta porque el lenguaje social precede al interno, ya que el primero se desarrolla a través de la interacción con el entorno y luego se internaliza; la opción B es errónea porque el lenguaje interno aparece mucho antes, alrededor de los 3 a 4 años, cuando el niño ya habla; la opción D es inexacta porque, aunque la estructura gramatical del lenguaje interno se basa en la del lenguaje social, la función principal no es la ordenación gramatical sino la autorregulación, por lo que las opciones A, B y D comparten el error de confundir la función con la forma o el momento de aparición.'),
  (443, 'La clasificación de Mary Ainsworth en la “Situación Extraña” distingue cuatro patrones de apego; el patrón que se observa cuando el niño muestra mayor interés en los juguetes que en el cuidador al reencuentro es el apego evitativo (Tipo A), pues el niño evita el contacto con la figura de apego, mostrando una actitud de desapego y distracción, lo que indica una estrategia de defensa frente a la ansiedad que produce la separación; el apego ambivalente (Tipo C) se caracteriza por la búsqueda intensa y la dificultad para calmarse, el apego desorganizado (Tipo D) por comportamientos contradictorios y el apego seguro (Tipo B) por la búsqueda equilibrada y la confianza en la disponibilidad del cuidador, por lo que las opciones B, C y D describen patrones que no se ajustan a la conducta de distracción y evitación observada.'),
  (444, 'El paradigma de la “cara inmóvil” de Tronick describe una situación experimental en la que el cuidador mantiene una expresión facial neutral durante el contacto visual con el lactante, con el fin de observar la regulación emocional y la reciprocidad afectiva que se produce; por ello la opción A es la única que corresponde a la descripción funcional del método, pues la técnica se emplea para medir la regulación mutua en lactantes. Las demás alternativas son incorrectas: la B confunde el paradigma con una teoría del autismo, cuando en realidad Tronick lo utiliza para estudiar la regulación emocional temprana y no la teoría de la mente; la C introduce una limitación inexistente, ya que el método no se centra en la transmisión intergeneracional del trauma; y la D presupone una validez cultural limitada, aunque el procedimiento ha sido aplicado en diversos contextos culturales, no exclusivamente occidentales.'),
  (445, 'El juego funcional se refiere a la etapa de desarrollo donde el niño practica movimientos corporales y coordinación motora mediante la repetición de actividades físicas, como rodar una pelota, lanzar o atrapar objetos, lo que favorece la integración sensoriomotora y la adquisición de habilidades motoras básicas; por tanto la opción D es la que describe adecuadamente esta fase. Las alternativas A y C describen el juego simbólico y el juego constructivo, respectivamente, que implican el uso de la función simbólica y la manipulación de objetos para crear estructuras imaginativas, mientras que la opción B se refiere a la prevalencia del juego simbólico en la edad escolar, no al juego funcional.'),
  (446, 'El análisis factorial se emplea principalmente en estudios correlacionales porque permite identificar patrones de asociación entre variables observables (por ejemplo, ítems de un cuestionario de personalidad) y extraer factores latentes que explican la covarianza entre ellas; la técnica requiere datos cuantitativos y la estimación de matrices de correlación o covarianza, lo que la hace idónea para la investigación correlacional, donde se examinan relaciones entre variables sin manipulación experimental. El método clínico (A) se centra en la observación y valoración subjetiva de casos individuales, no en la identificación de estructuras latentes a partir de datos estadísticos; la metodología cualitativa (B) se basa en la interpretación de datos no numéricos y no utiliza análisis factorial; el método experimental (D) implica la manipulación de variables independientes y el control de condiciones, lo que no corresponde a la finalidad del análisis factorial, que se limita a la exploración de relaciones entre variables medidas.'),
  (447, 'La Teoría de los Constructos Personales de Kelly sostiene que cada individuo construye su realidad a través de un repertorio de constructos binarios que interpreta la información que recibe; estos constructos son activos, idiosincráticos y se actualizan continuamente, lo que implica que el conocimiento se organiza e integra de manera individual y dinámica, no mediante reglas formales ni modelos estandarizados, sino mediante la adaptación de estos constructos a la experiencia presente, lo que explica la variabilidad y la singularidad de la percepción de cada persona. Las opciones A y C se centran en atributos de depresión o rasgos cuantitativos, lo cual pertenece a teorías de la personalidad o trastornos, no a la teoría de Kelly; la opción B describe un enfoque de resolución de problemas más pragmático, pero no refleja la idea de constructos binarios y la interpretación activa de la información que caracteriza a Kelly.'),
  (448, 'La discrepancia entre el Yo Real y el Yo Ideal constituye la forma de auto‑discrepancia que Higgins (1987) asocia con la depresión, porque la brecha entre lo que uno es y lo que aspira a ser genera una sensación de insuficiencia y pérdida de valor propio, desencadenando síntomas depresivos; la discrepancia real‑ideal se interpreta como una amenaza a la autoestima y al sentido de propósito, lo que explica la relación empíricamente documentada con la depresión. Las demás opciones son incorrectas: la discrepancia real‑debería (Yo Real vs Yo que Debería) se vincula con la vergüenza, no con la depresión, por lo que la alternativa B está mal; la discrepancia entre el Yo que Debería y el Yo que me Asigno (Yo que me Asigno) no se relaciona con la motivación de logro, sino con la motivación de cumplimiento, por lo que la opción C es errónea; y la discrepancia real‑potencial (Yo Real vs Yo Potencial) se asocia con la frustración, no con la depresión, lo que invalida la alternativa D.'),
  (449, 'Fredrickson y Losada (2005) desarrollaron la teoría del “curva de oro” de la positividad, en la que la relación entre emociones positivas y negativas (EP/EN) debe situarse en torno a 3:1 para maximizar el bienestar y la resiliencia; esta proporción se deriva de la evidencia empírica que muestra que cuando las emociones positivas superan a las negativas en ese margen, se favorecen la creatividad, la salud física y la adaptación social, mientras que valores inferiores a 3:1 se asocian con mayor riesgo de depresión y deterioro funcional. La opción C recoge precisamente esta relación óptima de 3:1, contrastando con la idea de un equilibrio 1:1 (A) que no refleja la evidencia de la curva de oro, con la hipótesis de un sesgo de positividad que llevaría a 2:1 (B), que sobreestima la prevalencia de emociones positivas, y con la propuesta de que las emociones negativas deberían superar a las positivas (D), que contradice la literatura sobre la importancia de la positividad para la salud psicológica.'),
  (450, 'La opción A es la única que refleja la evidencia empírica de los estudios de gemelos: las correlaciones de los Cinco Grandes entre gemelos monocigóticos son consistentemente más altas que entre gemelos dicigóticos, lo que indica que la herencia genética contribuye de forma sustancial a la variabilidad de cada dimensión de personalidad, aunque el entorno también juega un papel; la diferencia entre los dos tipos de gemelos permite estimar la proporción de variación atribuible a factores genéticos. La alternativa B es incorrecta porque atribuye las similitudes en los gemelos MC a factores ambientales no compartidos, cuando en realidad la mayor similitud se debe a la coincidencia de su genoma completo. La opción C es errónea al afirmar que no existen influencias genéticas, contradiciendo la diferencia observada entre MC y DC y la literatura que muestra un efecto genético significativo. Finalmente, la respuesta D sobre el neuroticismo es demasiado específica y exagerada: aunque el neuroticismo muestra una alta herencia, no se puede afirmar que esté “exclusivamente” influenciado por factores genéticos, ya que también existen componentes ambientales que modulan su expresión.'),
  (451, 'Los estudios longitudinales que han seguido a cohortes a lo largo de décadas han mostrado que la correlación intrapersonal de los rasgos de las cinco grandes dimensiones (neuroticismo, extraversión, apertura, amabilidad y responsabilidad) permanece alta, con coeficientes típicamente entre .60 y .80, indicando una estabilidad considerable a lo largo de la vida; esto se interpreta como evidencia de que la estructura de la personalidad es relativamente estable y que los rasgos son más predictivos de los mismos individuos que de la población en general. En contraste, la opción A presenta cifras que no corresponden a la literatura empírica y sugiere una división arbitraria de la población que no se sustenta en datos longitudinales. La opción C confunde la relación entre extraversión y neuroticismo, pues los estudios no hallan una asociación directa de esa naturaleza ni un patrón de cambio tan marcado. La opción D se refiere a la percepción subjetiva del cambio, un fenómeno distinto que no refleja la estabilidad objetiva de los rasgos; además, la alta correlación entre percepción y cambio objetivo no es un hallazgo consistente en la literatura longitudinal.'),
  (452, 'Los planteamientos socio‑cognitivos de la personalidad se centran en la manera en que la persona procesa la información y regula su conducta en situaciones concretas, enfatizando la interacción entre cogniciones, motivaciones y contexto; por ello la opción B es la que mejor refleja este enfoque, ya que describe la atención al modo de elaboración y manejo de cada situación en vez de inferir rasgos globales. La alternativa A es incorrecta porque los modelos socio‑cognitivos sí incorporan valores, intereses y metas como componentes de la motivación y la autoeficacia, aunque no los traten como rasgos fijos. La opción C corresponde a la visión de los rasgos, no a la socio‑cognitiva, que no sostiene que los rasgos predecan comportamiento en circunstancias específicas. La alternativa D describe la teoría de los rasgos de extraversión, no el enfoque socio‑cognitivo, que no asume que la extraversión se manifieste de forma uniforme en todas las situaciones.'),
  (453, 'El modelo de capacidades mentales primarias de Thurstone se fundamenta en un análisis factorial exploratorio que identifica una serie de factores independientes que explican la variabilidad de las pruebas de inteligencia; por ello la afirmación de que “se basa, del mismo modo que el modelo de Spearman, en el análisis factorial” es la que describe fielmente su metodología, aunque difiere en la interpretación de la estructura subyacente, pues Thurstone no postula un factor general G sino varios factores primarios. Las demás opciones son erróneas: la primera presupone la existencia de un factor G, algo propio de Spearman y no de Thurstone; la segunda confunde la rapidez perceptiva con la capacidad de razonamiento general, atribuyéndole una función que no corresponde a su definición; y la tercera sobreestima el número de factores, pues Thurstone identificó siete factores primarios, no once.'),
  (454, 'El modelo Cattell‑Horn distingue entre inteligencia fluida (Gf) y cristalizada (Gc) como factores de primer orden, y los agrupa bajo un factor de tercer orden denominado “inteligencia general” (G), sin separar una “inteligencia fluida histórica” ni un “factor de aprendizaje común”; por lo tanto la opción D, que propone dos factores de tercer orden distintos, es la única que coincide con la estructura jerárquica propuesta por Cattell‑Horn, donde Gf y Gc se combinan en un único G. Las demás alternativas son incorrectas: la A describe una estructura de 120 aptitudes independientes que no corresponde al modelo jerárquico de Cattell‑Horn; la B confunde el modelo con la teoría bifactorial de Spearman, que no es la base de Cattell‑Horn; y la C enumera factores de primer orden que no se reconocen en la jerarquía de Cattell‑Horn, pues Gf y Gc son los únicos factores de primer orden que se combinan en el G.'),
  (455, 'La opción D es la única que describe de forma precisa una dimensión del modelo de los Cinco Grandes: la responsabilidad (conocida también como consciencia o minuciosidad) se caracteriza por la organización, el cumplimiento de obligaciones y la seriedad, en contraste con la informalidad y la falta de cuidado; esta definición coincide con la descripción académica de la dimensión de responsabilidad. Las demás alternativas son incorrectas: la A confunde neuroticismo con autoestima, pues el neuroticismo se asocia con la vulnerabilidad emocional y la inseguridad, no con la seguridad; la B mezcla la extraversión con la apertura, pues la extraversión se centra en la sociabilidad y la energía, mientras que la apertura evalúa la curiosidad y la imaginación; la C presenta una contradicción interna, pues una baja puntuación en apertura implica falta de curiosidad e imaginación, no la presencia de estas cualidades.'),
  (456, 'Francis Galton es reconocido por haber introducido la idea de que las diferencias individuales en la inteligencia podían cuantificarse mediante pruebas estandarizadas, lo que sentó las bases de la psicología diferencial; su trabajo consistió en diseñar instrumentos y procedimientos de medición que permitieran obtener puntuaciones comparables entre individuos, lo que constituye la aportación que el enunciado designa como “la creación de pruebas y estrategias de evaluación para obtener medidas directas de las funciones mentales”. Las demás opciones son inadecuadas: la opción A se refiere a la sistematización conceptual, una labor posterior a la de Galton; la B describe la utilización del tiempo de reacción, técnica desarrollada por otros psicólogos como William James y más tarde por los psicólogos de la velocidad de reacción; la C menciona el método sustractivo y la cronometría mental, que son conceptos asociados a la psicología experimental y no a la contribución de Galton.'),
  (457, 'El término que describe el conjunto de costumbres, sentimientos e ideales que confieren estabilidad y predictibilidad a las reacciones de un individuo es el carácter, pues constituye la organización coherente de disposiciones afectivas, cognitivas y conductuales que se manifiestan de forma consistente en distintas situaciones, diferenciándose del temperamento que se refiere a la predisposición biológica y de la constitución a la estructura fisiológica, y del estilo cognitivo que se limita a la forma de procesar información. Las otras opciones son incorrectas porque el temperamento se refiere a rasgos innatos y de respuesta emocional, la constitución a la predisposición física y la fisiología, y el estilo cognitivo a patrones de pensamiento sin abarcar la totalidad de la personalidad estable.'),
  (458, 'El tiempo mínimo necesario para reconocer correctamente un estímulo presentado durante un período muy breve se denomina tiempo de inspección; este concepto se emplea en la medición de la velocidad de procesamiento perceptivo en estudios de inteligencia, pues refleja la rapidez con la que el cerebro puede extraer información de un estímulo antes de que se produzca una respuesta, diferenciándose de los tiempos de reacción simples o de elección que implican una respuesta motor o una selección entre opciones, y del tiempo de decisión que se refiere a la deliberación entre alternativas más complejas; las opciones A y B describen procesos que incluyen una respuesta motor o una elección entre varias respuestas, mientras que la D se refiere a la fase de deliberación, por lo que no corresponden al concepto de inspección.'),
  (459, 'El ítem “Maquiavelismo” no se incluye en ninguno de los dos factores identificados por la PCL‑R; el factor I (interpersonal/affective) agrupa rasgos como encanto superficial, grandiosidad, falta de remordimiento, y el factor II (social deviance) comprende estilo de vida parasitario, impulsividad, problemas de conducta tempranos y conducta antisocial, entre otros, pero no contempla el maquiavelismo, que se considera más un rasgo de manipulación estratégica que no se correlaciona con las dimensiones de la escala; en cambio, el estilo de vida parasitario, la impulsividad y los problemas de conducta tempranos sí aparecen en el factor II, mientras que el maquiavelismo, al no estar asociado a las dos dimensiones, queda excluido.'),
  (460, 'El criterio que no pertenece al trastorno de la personalidad esquizotípica es la opción C, ya que la falta de deseo o disfrute de las relaciones íntimas y la ausencia de interés en formar parte de una familia son características propias del trastorno de la personalidad antisocial y no del esquizotípico, que se centra en la presencia de ideas delirantes, creencias paranóicas, comportamiento excéntrico y dificultades en la interacción social, pero no en la ausencia de afecto o deseo de intimidad; la opción A describe la falta de amistades cercanas, típica de la esquizotípica; la opción B recoge el comportamiento y aspecto extraño o excéntrico, también característico; la opción D señala la ansiedad social persistente y la asociación con miedos paranoides, que son criterios diagnósticos del trastorno esquizotípico.'),
  (461, 'El síndrome CADASIL es una vasculopatía hereditaria que causa accidentes cerebrovasculares y demencia subcortical, pero no se clasifica dentro de la demencia frontotemporal, la cual comprende la variante conductual y las dos formas de afasia progresiva primaria (no fluente y semántica); por tanto la opción d) es la que no corresponde a un tipo de demencia frontotemporal. Las demás alternativas sí describen entidades reconocidas dentro de la demencia frontotemporal: la variante conductual se caracteriza por alteraciones en la conducta y la personalidad; la afasia progresiva primaria no fluente presenta dificultades en la producción del lenguaje con preservación de la comprensión; y la variante semántica se manifiesta con pérdida de significado léxico y preservación inicial de la fluidez. Todas estas cumplen criterios clínicos y neuropsicológicos que las sitúan dentro del espectro frontotemporal.'),
  (462, 'El síndrome disejecutivo que se caracteriza por irritabilidad, desinhibición sexual y grave impulsividad se asocia con daño en la corteza orbitofrontal, ya que esta zona regula la inhibición de respuestas sociales, la valoración de la recompensa y la regulación de la conducta impulsiva; la lesión de la corteza orbitofrontal produce una desinhibición de la conducta y alteraciones en la toma de decisiones, lo que explica los síntomas descritos; las demás opciones corresponden a regiones con funciones distintas: la corteza dorsolateral frontal se vincula principalmente con la planificación, el razonamiento y la memoria de trabajo, por lo que su lesión no produce desinhibición sexual; la corteza cingulada está implicada en la regulación emocional y la atención, pero no es la principal responsable de la impulsividad; la corteza motora suplementaria controla la planificación motora y la ejecución de movimientos, sin relación directa con la desinhibición.'),
  (463, 'En la demencia con cuerpos de Lewy la disfunción cognitiva se caracteriza por una marcada alteración de la atención y de las funciones ejecutivas, con un deterioro particular en el cambio atencional (shifting), y también por dificultades visoespaciales que se manifiestan en la incapacidad para orientarse en el espacio y en la percepción de objetos; estos déficits se deben a la afectación de los circuitos fronto-parietales y temporales afectados por la presencia de cuerpos de Lewy, lo que explica la predominancia de los síntomas atencionales y visoespaciales en el perfil neuropsicológico. Las opciones B y C son erróneas porque, aunque la memoria episódica y semántica pueden verse afectadas, el deterioro no es exclusivamente grave ni se presenta desde el inicio; la memoria se deteriora de manera más gradual y con un patrón más amplio que el de la demencia alzheimerica. La opción D describe síntomas motores y conductuales que, aunque pueden coexistir en la enfermedad, no constituyen el núcleo del perfil neuropsicológico típico, por lo que se descarta.'),
  (464, 'La mielina en el SNC es sintetizada por los oligodendrocitos, que envuelven múltiples axones y forman varias vaina de mielina, mientras que en el SNP la mielina la generan las células de Schwann, que envuelven un solo axón y producen una sola vaina, lo que explica la diferencia en la organización y el número de vaina entre ambos sistemas; las demás alternativas fallan porque la mielina no es producida por neurotransmisores ni hormonas (A), no es generada directamente por los axones (C), y los nódulos de Ranvier no son sitios de síntesis de mielina (D).'),
  (465, 'La arteria basilar, que se forma a partir de la unión de las arterias vertebrales, da origen a varias ramas que suministran sangre al tronco encefálico; por tanto, el tallo cerebral (mesencéfalo, puente y bulbo) es irrigado en su mayor parte por esta arteria, lo que explica la opción C. La rodilla del cuerpo calloso (A) recibe su vascularización principalmente de las arterias carótidas internas y sus ramas, no de la basilar. Los lóbulos frontales (B) y parietales (D) están abastecidos por las arterias cerebrales anteriores y posteriores, derivadas de la carótida interna, y no por la basilar, por lo que las opciones A, B y D son erróneas.'),
  (466, 'La vía que integra el procesamiento del movimiento y la percepción espacial es la vía magnocelular (vía M), que se origina en la retina y proyecta a través del núcleo geniculado lateral de la médula espinal hasta la corteza visual primaria (V1) y, desde allí, a la corteza parietal posterior, donde se integran la información motora y espacial; por tanto la alternativa que indica la proyección desde el lóbulo occipital hasta el lóbulo parietal (D) describe correctamente la trayectoria de esta vía, mientras que la opción A confunde la vía magnocelular con la parvocelular, la B describe una ruta temporal que no participa en la percepción espacial, y la C limita erróneamente la vía al estriado occipital, omitiendo su proyección parietal.'),
  (467, 'El metilfenidato ejerce su efecto farmacológico al inhibir el transportador de dopamina (DAT) en la membrana presináptica, lo que impide la recaptación de la catecolamina y aumenta su concentración en la hendidura sináptica; este aumento de dopamina disponible en la sinapsis potencia la señalización dopaminérgica, especialmente en los circuitos prefrontal y de recompensa, lo que explica su eficacia en el TDAH. Las demás alternativas son incorrectas: la opción A niega la acción dopaminérgica, contradiciendo la evidencia de que el fármaco actúa sobre el DAT; la B describe una supresión de la liberación, lo cual es el efecto de inhibidores de la recaptación, no su mecanismo; y la D afirma un aumento de la recaptación, lo cual sería opuesto al efecto real del metilfenidato.'),
  (468, 'La APA (2006) define la Práctica Basada en la Evidencia (PBE) como la combinación de la mejor evidencia científica disponible, la experiencia clínica del profesional y las características, cultura y preferencias del paciente; esta definición subraya la necesidad de integrar datos empíricos rigurosos con el juicio clínico individualizado y el contexto del paciente para optimizar los resultados terapéuticos, lo que coincide con la opción A. Las demás alternativas son incorrectas: la opción B invierte la relación entre evidencia y práctica, lo cual no refleja el modelo de la APA; la C se refiere a la Práctica Deliberada, un concepto de aprendizaje y mejora de habilidades que no implica la integración de evidencia científica; y la D describe la Práctica Reflexiva, centrada en la autoevaluación del profesional, sin enfatizar la evidencia empírica como elemento central.'),
  (469, 'La afirmación de Anderson et al. (2009) identifica a la fluidez verbal, la calidez, la empatía, la expresión emocional, la capacidad persuasiva, la capacidad para instilar esperanza, la capacidad de vinculación y la comprensión del problema del paciente como un conjunto de habilidades de facilitación interpersonal, pues son competencias que permiten al terapeuta establecer una relación terapéutica eficaz, facilitar la expresión del paciente y guiar el proceso de cambio; la literatura de psicoterapia sostiene que estos rasgos constituyen la base de la alianza terapéutica y la efectividad clínica, por lo que la opción B es la que refleja adecuadamente la clasificación de Anderson et al. Las demás opciones son incorrectas: la opción A niega la relación entre estas competencias y la eficacia clínica, contradiciendo la evidencia empírica; la opción C introduce una variable demográfica (edad) que no se relaciona directamente con la presencia de dichas habilidades según el estudio citado; y la opción D atribuye erróneamente estas competencias al concepto de Práctica Reflexiva de Bennett-Levy, que se centra en la reflexión profesional y no en las habilidades interpersonales específicas señaladas.'),
  (470, 'La disartria se define como un trastorno de la articulación o del control muscular del habla, originado por un déficit neurológico que afecta la coordinación de los músculos implicados en la producción del sonido; por tanto la opción B describe adecuadamente este fenómeno, pues la disartria implica alteraciones en la fuerza, velocidad, tono y coordinación de los músculos del habla, sin que exista un daño estructural del aparato bucofonatorio. Las demás alternativas son inexactas: la A describe un trastorno fonológico, que implica dificultades en la selección y organización de fonemas, no en el control muscular; la C se refiere a un trastorno estructural, típico de la apraxia o de la disfonía, donde la causa es anatómica y no neurológica; y la D corresponde a la apraxia del habla, caracterizada por tropiezos, espasmos y repeticiones debido a una coordinación imperfecta de las funciones ideomotrices, no a un déficit neurológico que altere la fuerza o tono muscular.'),
  (471, 'La opción B es la única que concuerda con la descripción oficial de la Escala de gravedad de los síntomas de las dimensiones de psicosis del DSM‑5, la cual se emplea en la Sección III para valorar la severidad de los síntomas durante los siete días previos a la evaluación, con el fin de guiar la monitorización y la intervención clínica; las demás alternativas presentan fallos: la A es incorrecta porque la escala es administrada por el profesional clínico, no es auto‑aplicada; la C es errónea porque la escala contempla cinco dominios (Alucinaciones, Delirios, Discurso desorganizado, Comportamiento psicomotor anormal y Deterioro cognitivo), excluyendo el dominio de Comportamiento adaptativo; y la D es falsa pues la escala sí contempla la gravedad del deterioro cognitivo como uno de sus cinco dominios.'),
  (472, 'El “descuento por demora” se refiere a la tendencia de los individuos adictos a valorar de manera desproporcionadamente más los refuerzos inmediatos que los que se presentan con un retraso temporal, lo que explica la preferencia por la gratificación instantánea a costa de beneficios mayores a largo plazo; por tanto, la opción B describe adecuadamente este fenómeno. Las demás alternativas se equivocan al asociar el descuento por demora con la intensidad (A), la saliencia (C) o la cantidad (D) de reforzadores, conceptos que pertenecen a otras dimensiones de la valoración de refuerzos y no al proceso de devaluación temporal que caracteriza la patología del refuerzo en la adicción.'),
  (473, 'El refuerzo de la abstinencia es el objetivo más directamente vinculado a la reducción del consumo de cannabis, y los ensayos aleatorizados de contingencia que aplican recompensas por muestras de orina negativas muestran la mayor eficacia, pues la contingencia se alinea con la conducta deseada y produce un efecto de aprendizaje operante robusto; en contraste, reforzar conductas indirectas como la asistencia a sesiones o la realización de tareas para casa (opciones B y C) puede mejorar la participación en el tratamiento pero no garantiza la reducción del consumo, y reforzar la comunicación familiar (opción D) se centra en variables interpersonales que, aunque relevantes, no han demostrado un impacto clínicamente significativo en la abstinencia en los estudios disponibles.'),
  (474, 'La terapia de exposición a señales (Cue Exposure Therapy–CET) no alcanza el grado de recomendación A de eficacia probada para la adicción al alcohol, ya que la evidencia clínica muestra resultados mixtos y una eficacia limitada cuando se compara con intervenciones más establecidas; en contraste, las intervenciones motivacionales breves (A) están respaldadas por numerosos estudios que demuestran su capacidad para aumentar la motivación y reducir el consumo; la terapia conductual familiar y de pareja (B) cuenta con evidencia robusta que indica mejoras significativas en la abstinencia y la calidad de vida familiar; y el Community Reinforcement Approach (CRA) (C) se ha validado en múltiples ensayos controlados como una intervención integral que combina refuerzo positivo, apoyo social y estrategias de manejo de la recaída, obteniendo resultados consistentes con el nivel A. Las opciones A, B y C comparten la característica de estar respaldadas por evidencia clínica sólida y consenso de guías de práctica, mientras que la opción D carece de ese respaldo uniforme y se considera de grado de recomendación inferior.'),
  (475, 'La respuesta es la opción C porque, tanto en las adicciones a sustancias como en las conductuales, la neurobiología subyacente comparte mecanismos de recompensa y aprendizaje asociativo que se modifican mediante intervenciones que alteran la motivación y la conducta, como la terapia cognitivo-conductual, la terapia de motivación y la farmacoterapia (en el caso de las sustancias), lo que explica la eficacia de tratamientos comunes como la terapia de reforzamiento positivo, la prevención de la recaída y la intervención en la conducta de riesgo; en cambio, la opción A es errónea porque la abstinencia completa no es el objetivo de las adicciones conductuales, donde se busca la reducción o control de la conducta; la opción B es falsa ya que la terapia cognitivo-conductual sí ha demostrado eficacia en ambos tipos de adicción; y la opción D es incorrecta porque la investigación en adicciones a sustancias sí aporta información valiosa sobre la neurociencia y los procesos psicológicos que también se aplican a las conductas adictivas.'),
  (476, 'El trastorno que pasó de la categoría de “Trastornos del control de los impulsos” a la de “Trastorno obsesivo‑compulsivo y trastornos relacionados” es la tricotilomanía, pues su sintomatología se centra en la compulsión de arrancar el pelo, un comportamiento repetitivo y difícil de controlar que, en la clasificación original, se consideraba un control de impulso; la revisión del DSM‑5 y el CIE‑11 lo ubican junto a los trastornos obsesivo‑compulsivos por la presencia de rumiaciones y la necesidad de realizar actos repetitivos para aliviar la ansiedad. Las demás opciones, aunque presentan conductas repetitivas, no fueron reclasificadas de esa forma: el trastorno de acumulación, la excoriación y el trastorno dismórfico corporal permanecen en la categoría de trastornos obsesivo‑compulsivos o en la propia sección de trastornos del control de los impulsos, pues su núcleo sintomático no se ajusta al patrón de compulsión de arrancar pelo que caracteriza la tricotilomanía.'),
  (477, 'La opción D resulta la única que concuerda con la conceptualización contemporánea del trastorno obsesivo‑compulsivo, pues la expresión “obsesiones puras” se ha abandonado por considerarse imprecisa y potencialmente confusa, pues implica una distinción artificial entre obsesiones y compulsiones que no refleja la naturaleza continua del espectro TOC y puede llevar a diagnósticos erróneos y a tratamientos inadecuados; las demás alternativas son incorrectas porque la A presupone una fase cronológica específica que no se sostiene en la literatura, la B sugiere una secuencia temporal que no es característica de la mayoría de los casos, y la C, aunque menciona un insight precario, se basa en una noción de “obsesiones puras” que ya no se emplea en la práctica clínica actual.'),
  (478, 'La supresión de obsesiones en el TOC se manifiesta principalmente mediante la autocastigación, pues la paciente intenta neutralizar la intrusión obsesiva aplicando una respuesta moral o de culpa que le resulte “aceptable”, lo que refuerza la ansiedad y la necesidad de rituales; este mecanismo se explica por la teoría de la “autocontrol moral” donde el individuo intenta compensar la disonancia interna a través de la autocrítica, un proceso que se observa de forma frecuente en la literatura clínica. En cambio, la distracción (A) es una estrategia de evitación que no se asocia con la característica compulsión interna del TOC, el control social (B) implica la búsqueda de aprobación externa y no es una táctica de supresión interna, y la preocupación (D) describe una respuesta cognitiva de ansiedad que, aunque presente, no constituye la técnica de supresión propia del trastorno.'),
  (479, 'El insight en el trastorno obsesivo‑compulsivo (TOC) se refiere a la percepción de la persona sobre la naturaleza patológica de sus obsesiones y compulsiones; un nivel bajo implica que el individuo no reconoce la irracionalidad de sus síntomas y los interpreta como realidades justificadas, lo que favorece la persistencia y la resistencia al tratamiento, y se ha documentado que tal falta de insight se correlaciona con una mayor comorbilidad, especialmente con trastornos de ansiedad y depresión, pues la falta de reconocimiento de la enfermedad dificulta la búsqueda de ayuda y la adherencia terapéutica. Por tanto, la alternativa A es la que refleja la relación clínica establecida entre bajo insight y mayor comorbilidad. Las demás opciones son incorrectas: la B presupone una relación causal entre el contenido obsesivo y el nivel de insight, cuando el insight no varía sistemáticamente con los temáticas obsesivas; la C afirma estabilidad del insight, aunque la evidencia muestra que el insight puede fluctuar con la gravedad del trastorno y con la respuesta al tratamiento; y la D vincula el inicio tardío con bajo insight, sin respaldo empírico, ya que el momento de aparición no determina la percepción de la patología.'),
  (480, 'La sensación de conocer, también denominada “déjà vu”, se interpreta en la teoría de la memoria como una anomalía del recuerdo, ya que implica la recuperación de una experiencia que se percibe como familiar sin que exista una memoria consciente previa de la misma; la distorsión ocurre en la fase de recuerdo, no en la de reconocimiento, y no se trata de una confusión de palabras o de una producción involuntaria de errores lingüísticos, por lo que no corresponde a una parapraxia, sino a una pará‑memoria del recuerdo. Las opciones A y B se refieren a paramnesias del recuerdo y del reconocimiento respectivamente, pero la sensación de conocer se asocia con la fase de recuerdo, no con el reconocimiento de estímulos. La opción D describe una parapraxia del reconocimiento, que implica errores en la identificación de estímulos, lo cual no corresponde al fenómeno del déjà vu.'),
  (481, 'La explicación de Radomsky et al. (2006) sobre la verificación compulsiva en el TOC se basa en la hipótesis de una baja confianza en la propia memoria, lo que lleva al individuo a repetir el acto de comprobar para reforzar la certeza de que la acción se ha completado adecuadamente; esta falta de confianza se manifiesta en la necesidad de confirmar repetidamente la información, ya que el verificador percibe su propia memoria como insuficiente y requiere evidencia externa para reducir la ansiedad. Las demás opciones son incorrectas porque la opción B presupone un efecto de recencia reducido por la repetición, un concepto no respaldado por la literatura de Radomsky; la opción C atribuye la verificación a una tendencia visual de la memoria, lo cual no corresponde a la teoría de la baja confianza; y la opción D sugiere un error en la ordenación temporal durante la codificación, una idea que no se relaciona con la hipótesis de la confianza memorizacional propuesta por Radomsky.'),
  (482, 'La dificultad para identificar sensaciones corporales internas, como la temperatura, corresponde a la somatoagnosia, que es la agnosia de las sensaciones somáticas; implica un déficit en la percepción y reconocimiento de la información interoceptiva, sin afectar la conciencia de la propia enfermedad (anosognosia) ni la percepción de objetos (agnosia para objetos) ni la localización de partes del cuerpo (autotopagnosia), por lo que las opciones A, B y D son incorrectas.'),
  (483, 'La amnesia global transitoria (AGT) se manifiesta como una pérdida súbita e intensa de la memoria episódica que suele durar entre 24 y 72 horas, con recuperación completa y sin deterioro cognitivo residual, y su etiología se asocia principalmente a alteraciones vasculares o metabólicas que afectan la corteza temporal medial; por ello la opción D es la que describe correctamente la característica epidemiológica y fisiopatológica de la AGT, pues la presencia de enfermedades sistémicas o cardiovasculares constituye el factor de riesgo más relevante y explica la mayor incidencia en personas mayores. Las demás alternativas son erróneas: la A es falsa porque la AGT afecta mayoritariamente a adultos mayores, no a jóvenes, y la recuperación es rápida y completa, no gradual; la B es incorrecta porque la tasa de recurrencia se sitúa por debajo del 5 %, no entre 25‑30 %; y la C es inexacta porque la duración típica no alcanza una o dos semanas, sino solo unos pocos días.'),
  (484, 'La depresión doble se refiere a la coexistencia de dos episodios depresivos mayores simultáneos, una situación que se contempla en la literatura clínica como un fenómeno de mayor gravedad y complejidad, pero que no está codificado como diagnóstico independiente en el DSM‑5 ni en la CIE‑11; por ello la opción B es la que se ajusta a la definición oficial, ya que el término se emplea principalmente en estudios de investigación para describir esta presentación clínica sin que exista una categoría diagnóstica específica. Las opciones A y D son incorrectas porque el DSM‑5 y la CIE‑11 no incluyen la depresión doble como un trastorno distinto; en ambos manuales la co‑ocurrencia de depresión mayor con trastorno depresivo persistente (distimia) o con trastorno distímico no constituye un diagnóstico propio. La opción C es errónea porque la depresión doble no implica un trastorno por uso de sustancias, sino simplemente la presencia simultánea de dos episodios depresivos mayores.'),
  (485, 'La opción d) es la que refleja la realidad epidemiológica descrita por el DSM‑5: la prevalencia anual de la depresión mayor se sitúa en torno al 7 % de la población, mientras que la prevalencia anual del trastorno bipolar ronda el 0,6 %, lo que indica una diferencia marcada en la frecuencia de aparición de cada trastorno; esta cifra se basa en estudios epidemiológicos de gran escala que han sido incorporados al manual. Las demás alternativas presentan fallos conceptuales: la A) confunde la respuesta al tratamiento y la carga genética, pues la depresión mayor suele responder mejor a los antidepresivos y su herencia es más fuerte que la del trastorno bipolar; la B) invierte la relación de riesgo suicida, ya que el trastorno bipolar con mayor frecuencia presenta riesgo de suicidio que la depresión mayor; y la C) suposición de que los trastornos depresivos generan más episodios que los bipolares es incorrecta, pues el trastorno bipolar se caracteriza por episodios recurrentes de manía y depresión, resultando en un mayor número de episodios a lo largo de la vida.'),
  (486, 'El mutismo selectivo se clasifica en el DSM‑5 como trastorno de ansiedad, ya que la conducta se explica por la presencia de miedo intenso a hablar en situaciones sociales específicas, y su diagnóstico se basa en la ansiedad que provoca la incapacidad de hablar, no en déficits cognitivos o de desarrollo; por ello la opción A es coherente. En la CIE‑10 el término “mutismo electivo” se emplea para describir la misma condición, por lo que la opción B coincide con la nomenclatura oficial. La duración mínima requerida para el diagnóstico es de al menos un mes, sin limitarse al primer mes de escolaridad, lo que confirma la opción D. La opción C es errónea porque el DSM‑5 no ubica el mutismo selectivo dentro de los trastornos del neurodesarrollo; esa categoría incluye trastornos como el autismo o la discapacidad intelectual, donde la causa subyacente es un déficit neurológico, no la ansiedad social que caracteriza al mutismo selectivo.'),
  (487, 'El modelo de aprensión ansiosa fue propuesto por Barlow, quien lo describe como una respuesta de evitación de estímulos que se perciben como amenazantes, con la finalidad de reducir la ansiedad; la aprensión se mantiene mediante la evitación y la interpretación catastrofista de los síntomas, lo que refuerza la percepción de amenaza y la ansiedad anticipatoria, y se explica dentro de la teoría cognitivo‑conductual de la ansiedad. Borkovec, aunque desarrolló el modelo de preocupación excesiva, se centra en la rumia y la preocupación en lugar de la aprensión específica; Semerari es conocido por su trabajo sobre la ansiedad social y la teoría de la evitación social, no sobre la aprensión ansiosa; Wells, por su modelo de atención selectiva y la interpretación de la información, se enfoca en la ansiedad de la salud y la preocupación, pero no en la aprensión ansiosa.'),
  (488, 'La Teoría de la Indefensión Aprendida de Seligman sostiene que la depresión se origina cuando un individuo, tras experimentar repetidas situaciones de fracaso o control externo, desarrolla un patrón de atribuciones internas, estables y globales que explican los eventos negativos; esta visión atribucional explica la sensación de impotencia y la falta de motivación para cambiar la situación, pues el individuo percibe que sus esfuerzos son inútiles, lo que conduce a la depresión; las demás opciones son incorrectas porque la opción B describe un modelo de refuerzo social y habilidades sociales que no es central en la teoría de la indefensión, la opción C confunde la autoestima con el eje causal de la depresión cuando la teoría se centra en la percepción de control, y la opción D menciona el autorrefuerzo, un concepto que no forma parte de la propuesta original de Seligman.'),
  (489, 'El trastorno de pánico se caracteriza por ataques de ansiedad súbita y recurrente acompañados de síntomas fisiológicos intensos; la elevada comorbilidad con enfermedades físicas y médicas se explica por la interacción entre la activación del sistema nervioso autónomo y la percepción somática, lo que favorece la aparición de síntomas como disnea, palpitaciones y dolor torácico que pueden ser malinterpretados como patología cardiaca o pulmonar, generando consultas médicas frecuentes y diagnósticos de origen físico; por ello la opción C es la que refleja la realidad epidemiológica y clínica del trastorno. La opción A es incorrecta porque la prevalencia anual del trastorno de pánico se sitúa en torno al 2-3 % de la población general, no el 5‑7 %; la opción B es errónea ya que, aunque la incidencia es mayor en mujeres, la diferencia no alcanza el triple respecto a los hombres; y la opción D se equivoca al afirmar una baja comorbilidad con el trastorno bipolar, pues la comorbilidad entre ambos trastornos es relativamente frecuente, especialmente en la presencia de síntomas mixtos o de episodios depresivos.'),
  (490, 'El riesgo de conducta suicida es mayor en los primeros años tras el inicio del trastorno psicótico porque durante ese periodo la paciente o el paciente experimenta una crisis de adaptación a la enfermedad, con síntomas agudos, deterioro funcional y alta incomodidad emocional que favorecen la desesperanza y la ideación suicida; además, la falta de tratamiento estabilizador y la posible presencia de delirios persecutorios o de referencia aumentan la vulnerabilidad. La fase prodrómica (opción A) suele caracterizarse por síntomas menos intensos y una menor percepción de amenaza, reduciendo la probabilidad de suicidio; los trastornos psicóticos de larga evolución (opción C) a menudo presentan un grado de adaptación y una mayor estabilidad funcional, lo que disminuye el riesgo; y el inicio tardío (opción D) se asocia con menor riesgo porque la edad avanzada y la mayor madurez social suelen proteger contra la conducta suicida.'),
  (491, 'El “salto a las conclusiones” es un sesgo de inferencia que implica pasar de una premisa poco o bien no sustentada a una conclusión definitiva, sin considerar la evidencia suficiente ni las alternativas plausibles; este patrón de pensamiento se observa con frecuencia en la elaboración de ideas delirantes, donde la persona atribuye significados extraños y fijos a eventos o estímulos, y la falta de evidencia objetiva no impide la consolidación de la creencia, de modo que la opción C es la que refleja la relación clínica establecida entre el sesgo y las ideas delirantes. La opción A es errónea porque el salto a las conclusiones no se limita a la presencia de alucinaciones, que son experiencias sensoriales sin estímulo externo; la opción B es incorrecta pues la frecuencia del sesgo no se mide en relación con la proporción de individuos con ideas delirantes, y la opción D es falsa porque el sesgo puede presentarse tanto en la población general como en la clínica, aunque su intensidad y la forma de manifestarse varían.'),
  (492, 'El tratamiento multimodal integrado para la psicosis que se describe en la literatura clínica es la terapia psicológica integrada de Roder, Müller, Brenner y Spaulding, la cual combina intervenciones cognitivas, conductuales, familiares y psicoeducativas dentro de un marco estructurado y de duración limitada, con el objetivo de mejorar la adherencia al tratamiento farmacológico, reducir la sintomatología psicótica y favorecer la recuperación funcional; la evidencia empírica respalda su eficacia en la reducción de recaídas y la mejora de la calidad de vida de los pacientes con esquizofrenia. En cambio, la terapia interpersonal de Fairburn se centra en la bulimia y la anorexia, por lo que no se aplica a la psicosis; la terapia interpersonal y de ritmos sociales de Frank se orienta a trastornos de la personalidad y trastornos del ritmo circadiano, no a la psicosis; y la terapia interpersonal metacognitiva de Cheli, Lysaker y Dimaggio se emplea en trastornos del espectro autista y trastornos de la personalidad, sin evidencia específica para la psicosis.'),
  (493, 'El entrenamiento en habilidades sociales se orienta a mejorar la interacción interpersonal y la regulación emocional del paciente, y por ello incluye la percepción emocional como componente esencial para que el individuo reconozca y responda adecuadamente a las señales afectivas de los demás; la opción D refleja esta integración de la percepción emocional dentro de la intervención, lo que la hace la alternativa que corresponde a la práctica clínica establecida. Las demás opciones son erróneas: la A presupone que el manejo de sustancias es un requisito indispensable de todas las intervenciones sociales, cuando en realidad el entrenamiento en habilidades sociales no necesariamente abarca el abuso de sustancias, que se trata con programas específicos; la B sugiere que las intervenciones familiares se diseñan según las necesidades de los familiares, cuando el enfoque familiar se centra en el paciente y en la dinámica familiar que afecta su evolución; y la C indica que los familiares deben controlar el tratamiento farmacológico, lo cual es incorrecto ya que la medicación debe ser gestionada por el profesional de salud mental, no por los familiares.'),
  (494, 'El modelo fenomenológico de la psicosis se fundamenta en la descripción y comprensión de la experiencia vivida por el paciente, poniendo énfasis en la manera en que la persona percibe, interpreta y se relaciona consigo misma, con los demás y con el entorno, considerando la alteración de la conciencia y la percepción como centrales para la sintomatología psicótica; por tanto la opción A recoge esa orientación centrada en la experiencia subjetiva y la construcción de significado propio, lo que la hace la respuesta adecuada. Las alternativas B y C describen enfoques biológicos y biopsicosociales, respectivamente, que se enfocan en procesos neurobiológicos y factores de vulnerabilidad y estrés, pero no en la dimensión fenomenológica; la D, por su parte, se refiere a un modelo de continuidad de la gravedad de los síntomas, una perspectiva dimensional que no es la esencia del modelo fenomenológico.'),
  (495, 'La afirmación incorrecta es la C; el entrenamiento en inoculación de estrés (EIS) no se considera un tratamiento centrado en el trauma, sino una intervención preventiva que busca fortalecer la resistencia al estrés mediante la exposición controlada a situaciones estresantes y la enseñanza de estrategias de afrontamiento, sin abordar directamente los recuerdos traumáticos ni los síntomas del TEPT; en cambio, las opciones A, B y D describen correctamente la eficacia de la exposición prolongada y la reestructuración cognitiva, la distinción entre tratamientos centrados y no centrados en el trauma, y la clasificación de la terapia de procesamiento cognitivo como una modalidad centrada en el trauma, respectivamente.'),
  (496, 'La descripción corresponde a una alucinación refleja, ya que el estímulo externo (la fotografía del padre) desencadena la percepción de voces, fenómeno típico de la alucinación refleja en la que un estímulo sensorial provoca una experiencia perceptiva que no está presente en el entorno; la alucinación negativa se refiere a la ausencia de estímulos esperados, la extracampina implica que la alucinación ocurre fuera del campo visual habitual y la funcional se relaciona con la producción de alucinaciones por procesos neurocognitivos sin alteración de la percepción, por lo que las demás opciones no se ajustan al caso.'),
  (497, 'La rumiación se define como la tendencia a mantener un pensamiento persistente y repetitivo sobre las emociones negativas, los síntomas de malestar y los problemas, así como sobre sus posibles causas y consecuencias; este proceso se caracteriza por la falta de resolución y la dificultad para cambiar la perspectiva, lo que favorece la intensificación de la angustia y la interferencia con la adaptación funcional, por lo que la opción B es la que describe adecuadamente el fenómeno. Los pensamientos automáticos negativos (A) se refieren a juicios instantáneos y evaluaciones negativas que surgen en respuesta a situaciones específicas, pero no implican la misma repetición y fijación prolongada que la rumiación; las preocupaciones (C) son anticipaciones de posibles eventos adversos y suelen centrarse en el futuro, mientras que la rumiación se orienta al pasado y a la interpretación de experiencias ya vividas; las obsesiones (D) son pensamientos intrusivos, no deseados y de carácter catastrofista que generan ansiedad y suelen estar asociados a trastornos obsesivo-compulsivos, por lo que no coinciden con la descripción dada.'),
  (498, 'En la psicopatología, las alucinaciones auditivas se clasifican según la complejidad del contenido; las que consisten en sonidos sin significado lingüístico, como ruidos, pitidos, cuchicheos o pasos, se denominan acoasmas, pues se perciben como “sonidos” sin asociación con palabras o frases, lo que coincide con la descripción de la pregunta. Las demás opciones son incorrectas: la opción B, fonemas, se refiere a unidades de sonido con significado fonético dentro de una lengua, no a simples ruidos; la C, fotomas, es un término inexistente en la clasificación de alucinaciones auditivas; y la D, fantasmias, hace referencia a alucinaciones visuales de tipo fantasma, no a la auditiva.'),
  (499, 'El síndrome de Cotard, caracterizado por delirios de negación de la propia existencia, de los órganos y de la vida, se asocia con trastornos depresivos graves y con la presencia de psicosis depresiva; la literatura clínica indica que la mayor prevalencia se observa en episodios depresivos mayores con componentes psicóticos, donde la pérdida de sentido de la realidad y la desesperanza se intensifican, favoreciendo la aparición de delirios nihilistas. En contraste, la demencia frontotemporal (A) se manifiesta principalmente con alteraciones conductuales y de personalidad, sin la predominancia de delirios de negación; la epilepsia del lóbulo temporal (C) puede producir alteraciones perceptivas y de identidad, pero los delirios de Cotard son raros y no forman parte del espectro típico; y el episodio maníaco (B) se caracteriza por euforia, grandiosidad y energía aumentada, lo cual es antitético al nihilismo y la negación de la existencia que define al síndrome de Cotard.'),
  (500, 'La Psicoterapia Analítico Funcional (FAP) se fundamenta en la aplicación de principios de análisis conductual para potenciar la interacción terapéutica; las cinco reglas que guían la conducta del terapeuta son: observar las conductas del paciente, evocar esas conductas en el momento presente, reforzar de manera inmediata y contingente, observar el efecto del refuerzo y, finalmente, interpretar la relación entre la conducta y el contexto interno del paciente; esta secuencia permite que el terapeuta intervenga de forma concreta y basada en evidencia, favoreciendo la consolidación de conductas adaptativas y la desinhibición de conductas disfuncionales. Las demás opciones fallan porque incluyen elementos que no forman parte del marco teórico de FAP (por ejemplo, “reformular las conductas clínicas”, “generar hipótesis alternativas” o “disminuir conductas tipo 2”); además, la opción A sustituye la etapa de evocar por observar, lo cual reduce la especificidad de la intervención; la opción C añade “interpretar” pero omite el reforzamiento, y la opción D altera la secuencia y añade categorías de conductas que no son parte de la metodología FAP.'),
  (501, 'La estrategia que constituye parte del proceso terapéutico en la Terapia de Aceptación y Compromiso (ACT) es la opción B, pues ACT se centra en la clarificación de los valores personales y en la identificación de los procesos internos que guían el comportamiento, sin intentar fusionarse con ellos (opción A) ni controlar los eventos privados (opción D); además, ACT no promueve la reestructuración cognitiva tradicional ni la generación de explicaciones alternativas para los pensamientos aversivos (opción C), sino que fomenta la aceptación y la defusión. Las demás opciones son incorrectas porque la opción A describe un proceso de fusión con los valores, contrario al objetivo de ACT de mantener una relación flexible con los valores; la opción C se asemeja a la terapia cognitiva racional, no a la aceptación; y la opción D implica un control directo de los eventos privados, lo cual va en contra de la aceptación de los mismos que es central en ACT.'),
  (502, 'La afirmación A es la que resulta incorrecta porque la jerarquía de metas de la Terapia Dialéctico Conductual establece, en primer lugar, la reducción de la conducta suicida y la prevención de la muerte, antes de abordar las conductas que interfieren con la terapia; dichas conductas se tratan en un nivel posterior, una vez que la seguridad del paciente está garantizada, de modo que el objetivo inicial no es la conducta que interfiere con la terapia. Por el contrario, la opción B refleja la regla de la “línea de crisis” que permite al paciente contactar al terapeuta en cualquier momento, sin restricciones de 24 horas, lo que es coherente con la práctica clínica de la DBT. La opción C es válida pues la DBT‑A se ha consolidado como el tratamiento psicológico más robusto para la conducta suicida en adolescentes, con evidencia empírica que la respalda. Finalmente, la opción D es correcta porque el análisis en cadena y el análisis de solución son herramientas centrales dentro de las estrategias de cambio de la DBT para descomponer la conducta suicida y generar alternativas de afrontamiento.'),
  (503, 'En la Psicoterapia Analítico‑Funcional (FAP) las conductas clínicamente relevantes tipo 3 (CCR3) se definen como aquellas que el paciente articula en forma de reglas o declaraciones que discriminan su propia conducta y los elementos de control que la mantienen; es decir, son expresiones conscientes de la relación entre estímulos, respuestas y consecuencias que el individuo reconoce y que pueden ser modificadas dentro de la sesión para promover la funcionalidad, lo que coincide con la opción C. Las demás alternativas son erróneas: la A describe conductas que aparecen fuera de la sesión y que se consideran equivalentes funcionales, pero no se refiere a las CCR3, que se centran en la auto‑regulación dentro de la sesión; la B habla de una nueva clase funcional de mejoría, lo cual no corresponde al concepto de CCR3, que se basa en la identificación de conductas problemáticas, no en la generación de nuevas; y la D menciona conductas de evitación dentro de la clase problemática, lo cual se relaciona más con la clasificación tipo 1 o tipo 2, no con la definición específica de CCR3.'),
  (504, 'El DSM‑5 define la autolesión no suicida (ALNS) como una conducta en la que el individuo inflige daño físico a sí mismo sin intención de morir, con el fin de obtener alivio emocional o una respuesta específica; por ello la opción C es la que describe correctamente el fenómeno, pues el alivio o la respuesta deseada se experimenta durante o poco después de la autolesión, característica central del trastorno. La alternativa A es incorrecta porque la ALNS puede incluir lesiones dolorosas y no se limita a lesiones superficiales; la opción B es errónea al afirmar que la mayoría de los casos comienzan en la primera edad adulta, cuando en realidad suele iniciar en la adolescencia o al inicio de la adultez temprana; y la alternativa D es falsa porque la práctica de autolesiones puede aumentar el riesgo de transmisión de enfermedades de transmisión sanguínea, especialmente cuando se utilizan objetos no estériles.'),
  (505, 'El término “conducta suicida” según O’Connor y Nock (2014) abarca el espectro completo de pensamientos y comportamientos que se relacionan con la intención de quitarse la vida, pues la definición explícita incluye tanto la ideación suicida como los actos concretos, sin limitarse a la mera intención o a la planificación; por tanto la opción C es la que describe adecuadamente esa amplitud conceptual, integrando la ideación, la planificación y la ejecución. Las demás alternativas son incorrectas porque la A restringe la definición a los pensamientos, omitiendo los comportamientos; la B se centra únicamente en la formulación del modo, excluyendo la ideación previa; y la D, aunque menciona la intención de morir, se limita a la participación en un comportamiento potencialmente autodestructivo, sin abarcar el conjunto de pensamientos que pueden preceder o acompañar dicha conducta.'),
  (506, 'El TERIA, según la CIE‑11, se caracteriza por una ingesta insuficiente de alimentos que no satisface los requerimientos energéticos o nutricionales, lo que constituye la esencia de la restricción alimentaria; por ello la opción B describe fielmente el criterio diagnóstico, mientras que las demás alternativas se apartan de la definición: la opción A se refiere al pica, un trastorno distinto que implica la ingestión de objetos no alimentarios; la opción C describe la preocupación por el peso o la forma corporal, característica del trastorno de la alimentación con preocupación corporal, no del TERIA; y la opción D menciona la exclusión de suplementos nutricionales o alimentación por sonda, lo cual no es un criterio de diagnóstico del TERIA, sino una característica de otros trastornos alimentarios.'),
  (507, 'El “Optimismo Irreal” corresponde a la percepción de que el propio riesgo de enfermarse es inferior al de la población general, un sesgo de percepción de riesgo que se manifiesta como una falsa sensación de invulnerabilidad; este fenómeno se explica por la tendencia a la autoexclusión de eventos negativos y a la sobrevaloración de la propia resiliencia, lo que conduce a una subestimación de la probabilidad de desarrollar una enfermedad y a una menor adherencia a medidas preventivas. Las demás opciones son incorrectas: la opción A describe una creencia general sobre la curabilidad de las enfermedades, no un sesgo de riesgo propio; la opción C se refiere a la asociación entre optimismo y pronóstico, pero no implica la falsa percepción de menor riesgo; y la opción D aborda la comunicación minimizadora a terceros, que no es la definición de optimismo irreal.'),
  (508, 'La Teoría de la Motivación para la Protección de Rogers (1985) expande el Modelo de Creencias sobre la Salud (MCS) de Becker y Maiman al introducir el “miedo a padecer la enfermedad” como factor clave que moviliza la conducta preventiva; este miedo, junto con la percepción de la gravedad y la susceptibilidad, actúa como motivador emocional que potencia la intención de adoptar medidas de protección. El miedo a padecer la enfermedad no se contempla en el MCS original, que se centra en la percepción de riesgo y en los beneficios percibidos, por lo que la opción A es la única que refleja la contribución específica de Rogers. Las opciones B y C se refieren a componentes ya presentes en el MCS (susceptibilidad y severidad), mientras que la opción D corresponde a los beneficios percibidos, otro elemento original del modelo, no a la adición de Rogers.'),
  (509, 'Según Miller y Rollnick (2015), los “Procesos” de la Entrevista Motivacional se estructuran en cuatro etapas: Vincular, focalizar, evocar y planificar; estas fases describen la secuencia clínica que permite establecer una relación terapéutica, centrar la conversación en el cambio, explorar la ambivalencia del paciente y formular un plan de acción concreto, lo cual constituye la base metodológica de la técnica; las demás opciones corresponden a conceptos distintos: la opción B describe las etapas del modelo de cambio de Prochaska y DiClemente, la C hace referencia a componentes de la terapia cognitivo-conductual y la D resume de forma genérica los objetivos de la entrevista sin detallar los procesos operativos; por tanto, solo la alternativa A recoge la estructura específica de los procesos de la Entrevista Motivacional.'),
  (510, 'Worden describe las “Tareas de Duelo” como procesos dinámicos que el individuo debe atravesar para integrar la pérdida; la opción d resume adecuadamente esta conceptualización al incluir la aceptación de la realidad de la pérdida, la elaboración del dolor, la adaptación a un mundo sin el fallecido y la búsqueda de una manera de recordar al fallecido mientras se inicia una nueva vida, reflejando la progresión de la adaptación y la reconstrucción de la identidad; las demás alternativas presentan errores conceptuales: la A incluye la recolocación emocional del fallecido, una idea que no aparece en la teoría de Worden; la B reduce el duelo a la aceptación y la expresión de la tristeza, omitiendo la adaptación y la reconstrucción de la vida; la C describe fases de la respuesta al shock, pero no corresponde a las tareas específicas propuestas por Worden.'),
  (511, 'La fase de “Desesperanza creativa” en la Terapia de Aceptación y Compromiso (ACT) se centra en que el paciente reconozca y experimente la insuficiencia de las estrategias habituales para controlar el dolor, lo que permite abrir la puerta a la aceptación y la flexibilidad psicológica; por ello la opción A es la que describe el objetivo clínico de esta etapa, pues la conciencia de la falta de eficacia es el punto de partida para la exploración de valores y la acción comprometida. Las demás opciones son inadecuadas: la B confunde la fase con la de “desconstrucción del contexto verbal/social”, que ocurre en etapas posteriores; la C se refiere a la fase de “acción comprometida”, donde se diseñan y ejecutan planes de conducta, y la D describe la fase de “establecimiento de un lugar seguro” (o “espacio de aceptación”), que también pertenece a etapas posteriores del proceso terapéutico.'),
  (512, 'La opción que presenta la combinación de estrategias con evidencia de menor malestar emocional y mejor regulación del dolor es la d: búsqueda de apoyo social, centrarse en lo positivo y distanciamiento; estos tres patrones constituyen una respuesta adaptativa porque el apoyo social reduce la sensación de aislamiento y la ansiedad, el enfoque positivo favorece la revaluación cognitiva y la resiliencia, y el distanciamiento permite la regulación emocional sin caer en la evitación total, manteniendo la capacidad de afrontar la enfermedad; en contraste, las alternativas a y c incluyen escape/evitación cognitiva o conductual, que se asocian con mayor depresión y peor manejo del dolor, y la opción b combina centrarse en lo positivo con escape/evitación conductual, donde la evitación conductual contrarresta los beneficios del optimismo; por tanto, las respuestas a, b y c comparten el error de incorporar estrategias evitativas que deterioran la adaptación psicológica.'),
  (513, 'La hipótesis de la amortiguación sostiene que el apoyo social actúa como un factor protector que reduce la intensidad de los efectos fisiológicos y psicológicos del estrés, de modo que las personas que cuentan con redes de apoyo presentan menor riesgo de desarrollar enfermedades crónicas y mayor resiliencia frente a situaciones adversas; por ello la opción B resume adecuadamente este mecanismo de mitigación de daños, mientras que la opción A confunde el apoyo con la internalización de la responsabilidad, la opción C se centra en conductas de riesgo sin referirse al proceso de amortiguación, y la opción D describe un efecto de promoción de conductas saludables que corresponde más a la hipótesis de la facilitación que a la de amortiguación.'),
  (514, 'La clasificación de Mrazek y Haggerty (1994) distingue las estrategias de prevención universal, selectiva e indicada en función del tipo de población a la que se dirige la actividad preventiva: la prevención universal se aplica a toda la población, la selectiva a grupos de riesgo y la indicada a individuos con síntomas o diagnóstico. Este criterio se basa en la idea de que la intensidad y el enfoque de la intervención deben ajustarse al nivel de riesgo y necesidad de cada segmento poblacional, optimizando recursos y maximizando la eficacia. Las demás opciones son incorrectas porque el momento de evolución del problema (A) no determina la categoría de prevención; el tipo de enfermedad (C) no es el factor diferenciador en la propuesta de Mrazek y Haggerty, ya que la clasificación se aplica a cualquier enfermedad; y el ámbito de desarrollo del programa (D) tampoco es el criterio central, pues la distinción se centra en la población objetivo, no en el contexto operativo.'),
  (515, 'La definición de adherencia terapéutica que corresponde a la OMS (2003) es la opción B, pues la OMS la describe como el grado en que el comportamiento del paciente (tomar medicación, seguir una dieta y/o cambios en el estilo de vida) se corresponde con lo acordado con el profesional de la salud, enfatizando la relación entre la decisión clínica y la conducta real del paciente; la opción A, aunque similar, se centra en la coincidencia con las instrucciones sin referirse explícitamente al acuerdo entre paciente y profesional, lo que reduce la precisión de la definición; las opciones C y D son incorrectas porque la OMS no considera la adherencia como un concepto exclusivo de investigación ni como desuso, sino como una dimensión clínica esencial para la eficacia del tratamiento.'),
  (516, 'La opción B es la única que corresponde a un emparejamiento teórico correcto: el concepto de “holding” (sostenimiento emocional) es una aportación central de Donald W. Winnicott, quien desarrolló la idea de que el entorno materno debe proporcionar una “caja de seguridad” que permita al niño experimentar la confianza y la regulación emocional; este concepto se distingue de la teoría de las relaciones objetales de Freud, que se centra en la dinámica de los objetos internos y la transferencia, y de la teoría del real, imaginario y simbólico de Klein, que se refiere a la división de la experiencia interna en tres registros. La alternativa A asocia incorrectamente la teoría de las relaciones objetales a Freud, cuando esta fue desarrollada por Melanie Klein y otros teóricos posteriores. La alternativa C confunde el marco de Klein con el de Freud, pues el real, imaginario y simbólico es la tríada de Lacan, no la de Klein. La alternativa D atribuye la noción de separación-individuación a Karen Horney, cuando esa idea proviene de la teoría del desarrollo psicosocial de Erik Erikson; Horney se centró en la ansiedad de separación y la búsqueda de la autoestima, pero no en la etapa de separación-individuación.'),
  (517, 'Según la investigación de Lambert, el factor que explica la mayor proporción de la variación en los resultados terapéuticos es el cambio extra‑terapéutico, es decir, los procesos que ocurren fuera de la sesión clínica directa y que influyen en la evolución del paciente; estos incluyen la motivación personal, el apoyo social y los cambios en la vida cotidiana, los cuales constituyen la mayor fuente de variabilidad en la respuesta al tratamiento. Los factores comunes (A) y las expectativas de placebo (D) son componentes del proceso terapéutico, pero su contribución a la varianza total es menor y se consideran subcomponentes de los procesos extra‑terapéuticos. El factor técnico (B), aunque relevante para la calidad del tratamiento, representa una fracción aún más reducida de la variabilidad, ya que la mayoría de los efectos se originan en la interacción entre el paciente y su entorno más que en la técnica específica empleada.'),
  (518, 'La terapia basada en la mentalización (MBT) se centra en la hipótesis de que el trastorno límite de la personalidad se caracteriza por una deficiencia en la capacidad de mentalizar, es decir, de atribuir estados mentales internos a uno mismo y a los demás, lo que dificulta la interpretación coherente de los comportamientos y las emociones; por ello, MBT trabaja explícitamente en mejorar la comprensión de estos procesos mentales, favoreciendo la regulación emocional y la relación interpersonal. Las demás opciones no abordan este déficit cognitivo de la misma manera: la terapia dialéctico conductual (TDC) se orienta a la regulación emocional y la tolerancia a la angustia, sin centrarse en la mentalización; la terapia de conducta se limita a la modificación de conductas observables y no a la interpretación de estados mentales; y la terapia Morita enfatiza la aceptación de la ansiedad y la acción orientada a valores, sin tratar la alteración de la comprensión mental.'),
  (519, 'La hipocondriasis, según la CIE‑11, se clasifica dentro de los trastornos obsesivo‑compulsivos y otros trastornos relacionados con el miedo, porque la preocupación excesiva y persistente por la presencia de una enfermedad grave se manifiesta como una obsesión que genera ansiedad y se acompaña de conductas compulsivas (revisión constante de síntomas, búsqueda de información médica, visitas repetidas al médico) que buscan reducir la angustia; esta estructura clínica se alinea con la definición de trastornos obsesivo‑compulsivos, donde la ansiedad se produce por pensamientos intrusivos y se alivia mediante rituales o conductas repetitivas. Las opciones A y B son incorrectas porque la hipocondriasis no se caracteriza por una experiencia corporal distorsionada ni por disociación, sino por una interpretación errónea de sensaciones corporales; la opción C, aunque la ansiedad es evidente, la hipocondriasis no se considera un trastorno de ansiedad tradicional, sino que se ubica dentro de la categoría obsesivo‑compulsiva por su naturaleza obsesivo‑compulsiva.'),
  (520, 'El tratamiento ambulatorio se considera la primera opción para la anorexia nerviosa porque permite la continuidad de la vida cotidiana y la integración social del paciente, favoreciendo la motivación intrínseca y la adherencia al plan terapéutico; además, la evidencia clínica muestra que la intervención temprana en el entorno familiar y comunitario, combinada con terapia cognitivo-conductual y supervisión nutricional, suele ser suficiente cuando el riesgo de desnutrición grave o de complicaciones médicas es bajo, evitando la estigmatización y la pérdida de autonomía que conlleva la hospitalización. Por el contrario, el ingreso hospitalario con separación familiar (A) suele reservarse para casos con riesgo de muerte por desnutrición severa o comorbilidades médicas; el ingreso domiciliario con supervisión familiar (B) no es la primera línea porque implica una carga logística y emocional elevada para la familia sin garantizar la estructura clínica necesaria; y los recursos de hospitalización parcial (D) se utilizan cuando se necesita una supervisión más intensiva que la ambulatoria pero sin requerir la estancia completa, por lo que no constituyen la opción inicial.'),
  (521, 'La intervención de primera línea en la anorexia nerviosa adulta es la gestión clínica especializada (SSCM) porque combina un enfoque estructurado de seguimiento, apoyo psicoeducativo y tratamiento de las comorbilidades, con una evidencia robusta de eficacia en estudios de ensayo controlados que muestran mejoría sustancial en la ingesta calórica y la recuperación de peso cuando se aplica en entornos hospitalarios o ambulatorios especializados; además, la SSCM permite la integración de la familia y el equipo multidisciplinario, lo que es esencial para abordar la naturaleza compleja y crónica de la enfermedad. En contraste, la terapia cognitiva basada en mindfulness (MBCT) se ha estudiado principalmente en trastornos de ansiedad y depresión, y su aplicación en la anorexia se limita a la reducción de la rumia cognitiva sin demostrar mejoras significativas en el peso corporal. La terapia basada en la mentalización (MBT) se centra en la comprensión de estados mentales y se ha aplicado con éxito en trastornos de la personalidad, pero carece de evidencia específica para la anorexia. La terapia de motivación (MET) es útil para aumentar la disposición al cambio en la abstinencia de sustancias, pero su eficacia en la anorexia es limitada y no se considera una intervención de primera línea.'),
  (522, 'La opción d) se sustenta en la evidencia clínica de que la anorexia nerviosa se caracteriza por una marcada falta de insight; el paciente suele minimizar o negar la gravedad de su alteración alimentaria, lo que dificulta la adherencia al tratamiento y la disposición al cambio, por lo que las intervenciones motivacionales (por ejemplo, la terapia motivacional o la fase de ambivalencia de la terapia cognitivo-conductual) se incorporan de forma rutinaria para aumentar la conciencia y la voluntad de modificar el comportamiento; en contraste, la opción a) es incorrecta porque la información sobre regulación del peso y la nutrición es esencial para la reeducación alimentaria y la prevención de la obesidad post‑tratamiento, y su omisión solo perpetúa la disfunción; la opción b) resulta errónea porque, aunque la combinación de fármacos y psicoterapia puede ser útil, la evidencia muestra que la terapia cognitivo-conductual (para bulimia) y la terapia familiar sistémica (para anorexia) son las más eficaces, y el uso de fármacos no se considera la intervención dominante; la opción c) también es falsa, ya que la modificación de la dieta y la reeducación nutricional son objetivos centrales en el tratamiento de la bulimia, pues los atracones están vinculados a patrones de restricción y a la percepción distorsionada de la comida, no solo a factores emocionales.'),
  (523, 'En el DSM‑5 la gravedad de la bulimia nerviosa se clasifica según la frecuencia de los comportamientos compensatorios inapropiados: leve (1‑3 episodios semanales), moderado (4‑7), severo (8‑13) y extremo (≥14). Un promedio de 10 episodios por semana cae dentro del rango de 8‑13, por lo que la especificación de gravedad correspondiente es “grave”, equivalente a “severo”. Las demás opciones son incorrectas porque la opción A (extremo) exige al menos 14 episodios, la opción C (moderado) corresponde a 4‑7 episodios y la opción D (leve) a 1‑3 episodios; ninguna de ellas coincide con la frecuencia reportada.'),
  (524, 'La anorexia nerviosa suele manifestarse en la adolescencia tardía o al inicio de la adultez temprana, con un patrón de mortalidad que se explica mayoritariamente por las complicaciones médicas derivadas del estado de desnutrición severa (cardiopatía, insuficiencia renal, desequilibrios electrolíticos) y por el riesgo elevado de suicidio, de modo que la opción C refleja la realidad epidemiológica y clínica del trastorno; las demás alternativas son erróneas porque la anorexia no tiene su inicio más frecuente en la primera infancia (opción A), la bulimia nerviosa no suele preceder a la anorexia en más de la mitad de los casos (opción B), y no existe evidencia de un segundo pico de incidencia a los 40 años vinculado a la perimenopausia (opción D).'),
  (525, 'La anorexia nerviosa atípica se define en el DSM‑5 como la presencia de todos los criterios de la anorexia nerviosa, salvo que el peso actual del individuo se encuentre dentro o por encima del rango normal; por tanto, la opción A describe correctamente el fenómeno, ya que el diagnóstico se mantiene a pesar de la ausencia de bajo peso, diferenciándolo de la anorexia clásica. La opción B corresponde a la bulimia nerviosa, donde la regurgitación es un síntoma central, y no a la anorexia atípica. La opción C describe purgas en ausencia de atracones, característica de la bulimia nerviosa, no de la anorexia. La opción D se refiere a la evitación por razones organolépticas, típica de la anorexia nerviosa clásica, pero no constituye la especificación atípica del DSM‑5; por tanto, las alternativas B, C y D son incorrectas porque describen criterios de otros trastornos alimentarios o de la forma clásica de anorexia.'),
  (526, 'La opción D es la que se corresponde con la evidencia clínica y epidemiológica de las fobias específicas: las fobias situacionales (por ejemplo, miedo a volar, a los espacios abiertos) suelen manifestarse en la adolescencia tardía o adultez temprana, mientras que las fobias de objetos (como los insectos o los perros) aparecen con mayor frecuencia en la infancia temprana, lo que explica la edad de inicio más tardía de las situacionales; la opción A es incorrecta porque el aprendizaje vicario es relevante solo para ciertas fobias, no la vía predominante; la opción B es falsa, ya que la mayoría de los pacientes con fobia específica presentan una sola fobia, y la prevalencia de múltiples fobias es menor al 20 %; la opción C, aunque describe un aspecto de la fobia, no distingue la característica que diferencia a las fobias situacionales de las demás, por lo que no responde a la pregunta planteada.'),
  (527, 'El modelo metacognitivo de Wells distingue entre creencias metacognitivas negativas (por ejemplo, “no puedo controlar mis pensamientos”) y positivas (por ejemplo, “es útil preocuparme”), y entre dos tipos de preocupación: la preocupación de tipo 1, que se centra en la evaluación de la amenaza y la búsqueda de soluciones, y la preocupación de tipo 2, que es persistente, repetitiva y difícil de controlar, típica de la ansiedad generalizada; por tanto, la opción que combina creencias negativas con preocupación tipo 2 es la que describe adecuadamente a los pacientes con TAG. Las demás alternativas son incorrectas porque mezclan elementos que no coexisten en el modelo: la presencia de creencias positivas no se asocia con TAG, y la preocupación tipo 1 se relaciona más con trastornos de ansiedad específicos o con la búsqueda de control, no con la ansiedad generalizada.'),
  (528, 'El trastorno de ansiedad social se caracteriza por una regulación emocional disfuncional que se manifiesta, entre otras estrategias, en la supresión expresiva; los sujetos tienden a reprimir la expresión de sus emociones para evitar la evaluación negativa, lo que incrementa la carga fisiológica y la sensación de incomodidad social, por lo que la opción A describe una característica clínica documentada de este trastorno; las demás alternativas son incorrectas porque la opción B presupone una disminución natural de la ansiedad con la exposición continua, lo cual no ocurre en el TAS donde la ansiedad suele mantenerse o incluso intensificarse sin intervención; la opción C sugiere una tendencia a subestimar las consecuencias negativas, cuando en realidad los individuos con TAS suelen sobreestimar los riesgos y las consecuencias negativas de las situaciones sociales; y la opción D indica que suelen iniciar tratamiento en fases iniciales, mientras que la realidad clínica muestra que la mayoría de los pacientes presentan retraso en la búsqueda de ayuda debido al miedo a la evaluación y a la falta de reconocimiento de la gravedad del trastorno.'),
  (529, 'El capítulo que no pertenece a la fase “Habilidades de afrontamiento” es el de “Afrontando los síntomas físicos”; en el programa de Barlow, esa sección se ubica dentro de la fase de “Preparación para la exposición”, donde se describen las técnicas de relajación y la identificación de síntomas, mientras que la fase de habilidades de afrontamiento se centra en la adquisición de estrategias de regulación emocional y cognitiva, por lo que los capítulos de entrenamiento en respiración, estableciendo la jerarquía de situaciones agorafóbicas y estrategias cognitivas se incluyen allí. Las demás opciones son incorrectas porque, aunque el capítulo de “Afrontando los síntomas físicos” sí forma parte del tratamiento, se encuentra en una fase distinta; las opciones A, C y D sí se encuentran dentro de la fase de habilidades de afrontamiento, ya que cada una aborda una técnica específica que el paciente debe aprender y practicar para manejar la ansiedad y los síntomas asociados.'),
  (530, 'La terapia intensiva focalizada en las sensaciones de Baker‑Morissette et al. (2005) se caracteriza por la exposición gradual a las sensaciones internas de ansiedad, empezando por aquellas que son menos amenazantes y avanzando progresivamente a las más intensas; por ello la opción C es la que describe adecuadamente el procedimiento, pues el paciente no se enfrenta de inmediato a las situaciones más temidas sino que se expone primero a sensaciones menos alarmantes para construir tolerancia. La alternativa A es incorrecta porque la fase de preparación se centra en la identificación de sensaciones y la elaboración de un plan de exposición, no en la reducción de la activación. La opción B es errónea porque la terapia está dirigida a pacientes con trastorno de pánico leve a moderado, sin requerir necesariamente la presencia de agorafobia. Finalmente, la alternativa D es falsa; la crítica más frecuente sobre esta intervención se relaciona con la falta de un componente de prevención de recaídas, pero no es una ausencia de módulo, sino la ausencia de énfasis en la consolidación a largo plazo.'),
  (531, 'La exposición a la incertidumbre es el componente central de la terapia cognitivo-conductual propuesta por Dugas y Robichaud para el trastorno de ansiedad generalizada, pues su modelo enfatiza la evitación de la incertidumbre como factor mantenedor de la ansiedad, y la exposición sistemática a situaciones inciertas permite reestructurar la interpretación de la incertidumbre y reducir la respuesta de alarma; el entrenamiento en relajación, aunque útil en otros trastornos de ansiedad, no forma parte de su protocolo específico, la organización del tiempo se dirige a la gestión de la procrastinación y la prevención de conductas de seguridad se refiere a la reducción de estrategias de evitación, pero no es el componente clave que Dugas y Robichaud destacan para el TAG.'),
  (532, 'La respuesta se fundamenta en la concepción de Newman sobre la ansiedad como una respuesta adaptativa que, en el TAG, se vuelve desproporcionada y desorganizada, generando un patrón de pensamiento que distorsiona la percepción de la realidad y produce consecuencias interpersonales negativas; por ello, el foco terapéutico se dirige a la reestructuración de las expectativas y la reducción de la evitación, pues la ansiedad generalizada se manifiesta principalmente en la preocupación constante por el futuro y la interpretación negativa de los propios procesos cognitivos, lo que afecta las relaciones sociales y la calidad de vida. Las opciones A y B describen procesos cognitivos y emocionales que pueden estar presentes en la ansiedad, pero no son el rasgo distintivo que Newman identifica como foco de tratamiento; la opción D, aunque relevante, se refiere a una preocupación intrapsíquica que no constituye el elemento central de la terapia integradora de Newman, que se centra en las consecuencias interpersonales.'),
  (533, 'El módulo “Comprendiendo tus emociones” del Protocolo Unificado de Barlow et al. (2019) está específicamente diseñado para descomponer las emociones en componentes más manejables, enseñando a los pacientes a identificar, etiquetar y analizar las sensaciones corporales, pensamientos y conductas asociadas a cada emoción, lo que facilita la regulación emocional y la reducción de la intensidad experiencial; en contraste, el módulo de “Conciencia emocional plena” se centra en la aceptación y observación no evaluativa de la experiencia emocional, sin desglosarla; “Exposiciones emocionales” se orienta a la exposición gradual a estímulos emocionales, pero no a la descomposición interna de la emoción; y “Flexibilidad cognitiva” aborda la modificación de patrones de pensamiento disfuncionales, sin enfocarse en la estructuración de la emoción en sí.'),
  (534, 'La interacción descrita corresponde a la **relación real** (opción C), pues en psicoterapia la relación real se define como la relación directa y auténtica entre el profesional y el paciente, libre de proyecciones y distorsiones que caracterizan a la transferencia; ambos se reconocen y aceptan tal cual son, lo que favorece la alianza terapéutica y la autenticidad emocional. La opción A, transferencia, implica la proyección de sentimientos y expectativas del paciente sobre el terapeuta, no la expresión genuina mutua; la opción B, relación mutua, es un término genérico que no especifica la ausencia de distorsión; y la opción D, relación dual, no corresponde a la terminología clínica habitual y sugiere una relación de doble naturaleza que no se ajusta al concepto de autenticidad plena.'),
  (535, 'El “efecto del terapeuta” se refiere a la influencia que la propia percepción del profesional sobre su desempeño ejerce sobre los resultados terapéuticos; estudios de procesos de terapia han mostrado que la duda sobre la propia competencia, aun cuando el terapeuta mantiene una autoimagen positiva, se asocia con menor eficacia clínica, ya que la inseguridad reduce la confianza en la aplicación de intervenciones y la capacidad de responder a las necesidades del paciente; por tanto la opción D describe correctamente la combinación de duda en el desempeño con un self positivo. Las demás opciones son erróneas porque la confianza en el propio desempeño (A y C) se relaciona con mejores resultados, mientras que la combinación de duda con un self negativo (B) no refleja la evidencia empírica sobre el efecto del terapeuta, que destaca la importancia de la autoeficacia más que la autoimagen negativa.'),
  (536, 'La preferencia que manifiesta el paciente por recibir tareas entre sesiones corresponde a la preferencia sobre las actividades, ya que la asignación de ejercicios prácticos constituye un componente de la intervención que el paciente desea controlar; en la psicoterapia, la autonomía del paciente sobre las actividades se considera un factor común que facilita la motivación y la transferencia de aprendizaje al contexto cotidiano, lo que se refleja en la opción A. Las demás alternativas son incorrectas: la opción B se refiere a la relación con el terapeuta, que no es el objeto de la petición; la C al tratamiento en su totalidad, abarcando aspectos más amplios que la simple asignación de tareas; y la D al formato de la sesión, que no implica la elección de ejercicios entre encuentros.'),
  (537, 'La recomendación basada en la evidencia para pacientes con alto nivel de reactancia es la utilización de intervenciones paradójicas (opción B), pues la reactancia se manifiesta como una resistencia a la imposición de límites y a la autoridad, y las intervenciones paradójicas, al ofrecer una forma de “permitir” la conducta deseada dentro de un marco controlado, reducen la resistencia y aumentan la colaboración; además, se ha demostrado que este enfoque disminuye la sensación de amenaza a la autonomía y facilita la internalización de los cambios. En cambio, los enfoques más directivos y estructurados (A) suelen intensificar la percepción de coerción y, por tanto, la reactancia; provocar rupturas en la alianza (C) es contraproducente y puede escalar la resistencia, mientras que derivar a terapia grupal (D) no aborda directamente la necesidad de disminuir la reactancia individual y puede aumentar la sensación de control externo.'),
  (538, 'El factor común que Frank (1961) identificó como esencial para la eficacia de cualquier psicoterapia es la activación de emociones intensas, pues sostiene que la experiencia emocional profunda permite la reestructuración cognitiva y la integración de experiencias conflictivas, procesos que se observan en todas las modalidades terapéuticas; en cambio, el manejo de la transferencia y la contratransferencia (A) es relevante en la psicodinámica pero no universal, la monitorización sistemática de resultados (B) constituye una técnica de evaluación más que un factor terapéutico intrínseco, y la psicoeducación (C) es una intervención específica que no se aplica en todas las escuelas de terapia.'),
  (539, 'El síndrome confusional agudo se caracteriza por la presencia de desorientación temporal y espacial, alteraciones del ciclo sueño‑vigilia y fluctuaciones de la atención, así como síntomas afectivos que incluyen agitación, agresividad, depresión y ansiedad; estos hallazgos reflejan la disfunción global de la corteza prefrontal y de los sistemas de regulación circadiana. En contraste, las alucinaciones hápticas no suelen aparecer en este trastorno, ya que la percepción táctil se mantiene intacta y las alteraciones sensoriales se limitan a la visión, audición o olfato cuando están presentes. Por tanto, la opción B es la que no corresponde al cuadro típico, mientras que las demás opciones describen manifestaciones clínicas habituales del síndrome confusional agudo.'),
  (540, 'La obnubilación se caracteriza por una alteración leve de la conciencia en la que el paciente mantiene la capacidad de comprender y seguir indicaciones, pero presenta una disminución del estado de alerta, irritabilidad y una conciencia limitada del entorno, tal como se describe en la pregunta; en contraste, el sopor implica una somnolencia profunda con dificultad para despertar, el estupor denota una respuesta mínima a estímulos con falta de iniciativa y el coma representa una pérdida total de la conciencia con imposibilidad de responder a estímulos externos, por lo que las opciones A, B y D no se ajustan a la presentación clínica descrita.'),
  (541, 'El estado descrito, con reducción de la atención al entorno, desorientación, confusión en el curso del pensamiento y presencia de automatismos involuntarios, corresponde a los estados crepusculares, que en la clasificación de la neuropsicología se definen precisamente como alteraciones transitorias de la conciencia y la cognición que incluyen déficit atencional, desorientación temporal y espacial, y la aparición de conductas automáticas sin control voluntario; estos síntomas reflejan una disfunción de la red de atención y la memoria de trabajo, típica de la fase crepuscular de la alteración neuropsicológica. Las demás opciones son inadecuadas: el término “oniroides” no se emplea en la literatura clínica para describir este patrón, por lo que la opción B carece de fundamento; el delirium (C) se caracteriza por fluctuación de la conciencia y alteraciones perceptivas, pero no necesariamente incluye automatismos involuntarios en la misma medida que los estados crepusculares; el estupor (D) implica una inmovilidad y falta de respuesta, sin la confusión y los automatismos que se describen en la pregunta.'),
  (542, 'El paciente describe una sensación de que su entorno se ha alterado, una percepción de que el mundo es extraño y no corresponde a la realidad, lo que caracteriza a la desrealización, un fenómeno disociativo en el que la realidad objetiva parece inverosímil o despojada de significado; la despersonalización, por otro lado, implicaría una sensación de desconexión con el propio cuerpo o yo, no con el entorno, y el estupor se manifiesta como una pérdida de conciencia o de respuesta motora, mientras que el delirio nihilista implica una creencia de inexistencia o de que todo es vacío. Por tanto, la opción B describe el fenómeno clínico observado, mientras que las demás se refieren a alteraciones distintas.'),
  (543, 'El concepto de perplejidad atencional se refiere a la incapacidad para lograr la síntesis del contenido de la atención, es decir, la dificultad de integrar y organizar la información que se percibe en un esquema coherente, lo que provoca que el individuo se quede “atrapado” en fragmentos sin poder avanzar hacia una comprensión global; esta definición se alinea con la descripción de la opción D, que señala la imposibilidad de sintetizar el contenido atencional. Las demás opciones son inexactas: la A describe una inestabilidad atencional general, pero no la falta de síntesis; la B se refiere a la ausencia de atención a estímulos externos debido a una concentración excesiva, lo cual corresponde más a la “atención focalizada” que a la perplejidad; la C habla de una ausencia completa de disposición atencional, lo cual implicaría un déficit de atención más amplio que la perplejidad, que se centra en la síntesis.'),
  (544, 'El modo prementalizador simulado, según la teoría de la mentalización, se caracteriza por un discurso que parece vacío, carente de significado, inconsecuente y circular, pues el individuo intenta atribuir estados mentales a sí mismo y a los demás sin haber desarrollado la capacidad de integrar coherentemente la información interna y externa; esta falta de coherencia refleja la ausencia de una estructura mentalizada que permita la interpretación de las intenciones y emociones, resultando en un discurso que se queda en la superficie sin profundizar en la dimensión interna. Las demás opciones son incorrectas: la B describe una visión estrictamente física de la conducta, lo cual corresponde a un enfoque más conductista que a la mentalización; la C se refiere a una dimensión interna que tiene el mismo poder que la externa, lo cual es característico del modo mentalizador real, no del prementalizador simulado; y la D indica una focalización extrema en lo externo, típica del modo prementalizador real, no del simulado.'),
  (545, 'El paciente se encuentra en la etapa de precontemplación, ya que reconoce la existencia de un problema (daño hepático) pero no está dispuesto a considerar la posibilidad de cambiar su conducta, pues minimiza su responsabilidad al señalar que su círculo social comparte el mismo patrón de consumo; este argumento refleja una negación de la necesidad de intervención y una falta de conciencia de la gravedad de su situación, lo que caracteriza la precontemplación. Las demás opciones son incorrectas: la contemplación implicaría un reconocimiento más profundo de la necesidad de cambio y una evaluación de pros y contras, lo cual no se observa; la acción requeriría la adopción de estrategias concretas para modificar el comportamiento, y la recaída implicaría una regresión a patrones anteriores después de haber intentado cambiar, ninguno de los cuales corresponde al estado actual del paciente.'),
  (546, 'Según el DSM‑5, el trastorno de insomnio se clasifica en tres tipos según la frecuencia y duración de los episodios: agudo (menos de 1 mes), intermitente (entre 1 y 6 meses) y persistente (más de 6 meses). Cuando se registran dos o más episodios de insomnio con una duración igual o superior a los tres meses dentro de un período de un año, la clasificación corresponde a “insomnio recurrente”, ya que la característica definitoria es la recurrencia de episodios con una duración mínima de tres meses, pero sin que la condición persista de forma continua durante más de seis meses. Las demás opciones son incorrectas porque “insomnio persistente” implicaría una duración continua superior a seis meses, “insomnio agudo” se refiere a episodios de menos de un mes, y “insomnio intermedio” no es una categoría reconocida en el DSM‑5.'),
  (547, 'El trastorno de conducta asociado al sueño REM (TCSREM) se caracteriza precisamente por la aparición de movimientos vigorosos, a veces violentos, durante la fase de sueño REM, cuando la atonía muscular normal se pierde y el individuo puede “escenificar” los ensueños que experimenta; estos episodios suelen incluir gritos, golpes o movimientos bruscos que reflejan la actividad cognitiva del sueño. En contraste, las pesadillas REM implican contenido emocional negativo y recuerdo del sueño, pero no generan movimientos físicos; los terrores nocturnos se originan en la fase de sueño no-REM y se manifiestan con arrebatos de miedo intenso, respiración acelerada y gritos sin movimientos corporales significativos; el sonambulismo también ocurre en el sueño no-REM y se caracteriza por caminar o realizar actividades sin conciencia, pero sin la naturaleza violenta y escenificadora típica del TCSREM.'),
  (548, 'El patrón de conducta descrito—agresión física a pares, destrucción de propiedad, expulsiones escolares, mentiras, y robo a los padres—cumple con los criterios del trastorno de conducta según el DSM‑5, que requiere al menos tres de los ocho criterios de conducta antisocial (agresión a personas o animales, destrucción de propiedad, robo, y falsedad) y la edad de aparición antes de los 18 años, sin que la conducta se explique por otro trastorno mental; la ausencia de tristeza o irritación típica del trastorno negativista desafiante y la presencia de episodios de ira desproporcionada no basta para un diagnóstico de trastorno explosivo intermitente, que exige episodios de ira breve y desproporcionada con daño a objetos o personas, y la psicopatía es un constructo de personalidad que no se diagnostica en la infancia. Por tanto, la opción C es la que mejor se ajusta; las demás opciones son incorrectas porque la psicopatía no se aplica a adolescentes, el trastorno explosivo intermitente requiere episodios de ira más breves y desproporcionados, y el trastorno negativista desafiante se caracteriza por oposición y desafío verbal sin la agresión física y el robo descritos.'),
  (549, 'Los terrores nocturnos se manifiestan durante la fase de sueño de ondas lentas (SWS), la cual ocurre principalmente en la primera mitad de la noche; por ello la opción D es la única que coincide con la fisiopatología clínica, ya que durante el episodio se observa activación autonómica (taquipnea, sudoración, midriasis) y un estado de alerta parcial que no permite la recuperación espontánea, característica distintiva de este trastorno; las demás alternativas son erróneas porque A confunde la fase de sueño (es SWS, no sueño REM), B indica una localización temporal incorrecta (los terrores suelen ocurrir en la primera mitad, no en la segunda), y C asocia erróneamente los terrores con estados crepusculares, que se refieren a la transición entre vigilia y sueño, no a los episodios de terror.'),
  (550, 'El entrenamiento del músculo pubocoxígeo mediante técnicas de autoestimulación se emplea principalmente en el trastorno orgásmico femenino, pues la contracción coordinada de este músculo facilita la estimulación del clítoris y la penetración de la vagina, incrementando la probabilidad de alcanzar el orgasmo; la fisioterapia del suelo pélvico mejora la circulación y la sensibilidad, y la autoestimulación permite la práctica segura y autónoma, reduciendo la ansiedad y la disfunción asociada. Las otras opciones son incorrectas: la eyaculación retardada (A) se trata con terapia de excitación y técnicas de respiración, no con entrenamiento del pubocoxígeo; el trastorno eréctil (B) requiere intervenciones farmacológicas y psicológicas de la función eréctil, sin enfoque en el músculo pubocoxígeo; y el trastorno por dolor genitopélvico/penetración (D) se aborda con terapia de dolor y técnicas de relajación, no con autoestimulación del músculo pubocoxígeo.'),
  (551, 'La expresión de Clara Hill (2017) “la manifestación de los niveles más altos de habilidad, destreza, competencia profesional y efectividad” describe la **pericia clínica**, pues se refiere a la excelencia en la aplicación de técnicas terapéuticas y al dominio de la práctica clínica que permite al profesional alcanzar resultados óptimos; este concepto implica un nivel de desempeño que trasciende la mera aplicación de procedimientos y se basa en la integración de conocimientos, habilidades y juicio clínico. La opción A, la práctica deliberada, se centra en la repetición dirigida y el feedback para mejorar habilidades, pero no necesariamente implica la manifestación de la máxima competencia; la opción B, la práctica reflexiva, se orienta a la reflexión sobre la experiencia clínica para el aprendizaje, sin garantizar la excelencia en la ejecución; mientras que la opción D, el rendimiento terapéutico, se refiere al resultado observable del proceso terapéutico, pero no al nivel de habilidad profesional subyacente que caracteriza la pericia clínica.'),
  (552, 'La respuesta A es la única que se corresponde con una de las cinco dimensiones de esquemas que J. Young identifica en su modelo de Terapia de Esquemas; la dimensión de “desconexión y rechazo” agrupa los esquemas que derivan de experiencias tempranas de abandono, negligencia o rechazo, y se manifiesta en patrones de aislamiento, desconfianza y auto‑desprecio. Las demás opciones no aparecen en la clasificación de Young: la “necesidad del sí mismo” no constituye una dimensión, sino un concepto más amplio de auto‑afirmación; la “necesidad del proceso elaborativo interrumpido” no es un término utilizado en el modelo y parece una mezcla de conceptos de psicología cognitiva; y la “alienación y apatía” tampoco figura entre las cinco dimensiones, aunque puede describir síntomas asociados a ciertos esquemas, pero no es una categoría propia del marco teórico. Por tanto, solo la opción A se alinea con la terminología y la estructura de las dimensiones de esquemas de Young.'),
  (553, 'El DSM‑5 describe el trastorno de juego por internet como un patrón de uso persistente y recurrente de internet para participar en juegos, que provoca malestar clínicamente significativo o deterioro funcional; por tanto la opción B coincide con la definición oficial, ya que enfatiza tanto la modalidad de juego en línea como el impacto clínico, mientras que la opción A confunde el trastorno con la adicción a los juegos de azar, que se clasifica por separado; la opción C es incorrecta porque el DSM‑5 no dispone de evidencia concluyente suficiente para incluirlo como diagnóstico oficial, sino que lo presenta como condición de investigación; y la opción D es errónea porque el trastorno de juego por internet no se encuentra dentro de la categoría “Adicciones conductuales” en el DSM‑5, que incluye solo el trastorno por juego y el trastorno por uso de internet, sin agruparlo con otras adicciones conductuales.'),
  (554, 'La opción B es la única que refleja la evidencia clínica sobre la comorbilidad entre el juego patológico y los trastornos afectivos en mujeres; estudios longitudinales y de cohorte han documentado que las mujeres con juego patológico presentan mayor prevalencia de depresión y trastornos de ansiedad que los varones, probablemente debido a la mayor tendencia a internalizar el estrés y a la menor utilización de estrategias de afrontamiento activas, lo que favorece la aparición de síntomas afectivos. La alternativa A es incorrecta porque los datos epidemiológicos indican que los varones suelen iniciar el juego en edades más tempranas que las mujeres, mientras que la opción C se basa en una asociación más frecuente con el abuso de alcohol y otras sustancias en hombres, no específicamente con benzodiacepinas, y la alternativa D es falsa pues sí existen diferencias en la modalidad de juego, con las mujeres mostrando mayor preferencia por juegos de azar con recompensas inmediatas y menores tasas de juego en línea comparado con los varones.'),
  (555, 'El Síndrome de Fregoli se caracteriza por la ilusión de que distintas personas son en realidad la misma figura que cambia de apariencia, lo que constituye un falso reconocimiento positivo: el paciente identifica correctamente la presencia de una figura, pero la atribuye erróneamente a otra persona; por ello la opción C es la única que concuerda con la definición clínica del trastorno. La opción A se refiere al Síndrome de Capgras, no al de Fregoli, y la variante opuesta de este último es el Síndrome de Capgras, no el de Clérambault, que describe la delirio de la relación romántica. La opción B describe el Síndrome de Capgras, donde el paciente cree que una persona importante está siendo usurpada por un impostor idéntico, no el de Fregoli. La opción D confunde el fenómeno con una paramnesia del recuerdo, cuando en realidad el trastorno implica un reconocimiento falso y no una distorsión de la memoria.'),
  (556, 'La definición de remisión total en el DSM‑5 para un trastorno depresivo mayor exige que el paciente experimente un cese significativo de todos los signos y síntomas durante al menos dos meses, sin que aparezcan síntomas que permitan cumplir los criterios diagnósticos completos; esto corresponde a la opción C, pues refleja la duración mínima establecida por el manual para considerar que el episodio ha concluido y que la persona ha recuperado su estado funcional previo. La opción A es incorrecta porque la reducción porcentual de la gravedad no es un criterio diagnóstico de remisión, sino una medida de respuesta que puede variar entre estudios; el DSM no la utiliza como umbral clínico. La opción B combina la duración con la restauración funcional, pero la remisión total no requiere necesariamente el retorno al “funcionamiento normal” completo, solo la ausencia de síntomas diagnósticos; además, la duración mínima es de dos meses, no seis. La opción D describe un episodio residual o de síntomas menores, que no constituye remisión total, ya que todavía se cumplen algunos criterios parciales y la duración es inferior a la exigida.'),
  (557, 'La opción D se corresponde con la teoría de los estilos de respuesta de Nolen‑Hoeksema, la cual sostiene que la rumiación—la repetición de pensamientos negativos sobre el propio estado y las causas de la depresión—es el factor más determinante para la persistencia y la intensidad de los síntomas depresivos, ya que mantiene la atención en la experiencia negativa y dificulta la activación de estrategias de afrontamiento más adaptativas; en contraste, la teoría cognitiva de Beck (A) enfatiza la distorsión de la información interna, la teoría de la desesperanza de Abramson (B) se centra en la expectativa de fracaso y la teoría conductual de Ferster (C) se enfoca en la función de refuerzo de los comportamientos, sin destacar la rumiación como mecanismo central.'),
  (558, 'El diagnóstico diferencial entre trastornos bipolares y depresivos se centra en la presencia de episodios maníacos o hipomaníacos; en el trastorno bipolar, los episodios de ánimo elevado o irritable suelen coexistir con episodios depresivos, y la presencia de síntomas atípicos como enlentecimiento motor, agitación y hipersomnia es más frecuente durante los episodios depresivos bipolares que en los unipolares, ya que la alteración del estado de ánimo en el bipolar tiende a ser más compleja y a presentar una mayor variabilidad de síntomas, mientras que la depresión unipolar suele manifestarse con síntomas más clásicos de tristeza, pérdida de interés y anhedonia. Las demás opciones son erróneas: la edad de aparición no distingue de forma fiable los trastornos bipolares de los depresivos (ambos pueden presentarse en la adolescencia o adultez temprana), el riesgo de suicidio es mayor en el trastorno bipolar, especialmente en la fase depresiva, y el abuso de sustancias psicoactivas es más frecuente en el trastorno bipolar que en la depresión unipolar.'),
  (559, 'La descripción corresponde a la práctica deliberada, pues implica un esfuerzo sistemático y estructurado dirigido a mejorar el rendimiento propio, con períodos prolongados de trabajo, supervisión constante y retroalimentación inmediata de un mentor, y se basa en la repetición y el refinamiento progresivo de las habilidades terapéuticas; la práctica reflexiva (opción A) se centra más en la reflexión sobre la experiencia sin la misma estructura de retroalimentación inmediata, la práctica continuada (opción C) no especifica la orientación deliberada ni la supervisión guiada, y las habilidades de facilitación interpersonal (opción D) se refieren a competencias de interacción social más que a un proceso de mejora sistemática de la práctica clínica.'),
  (560, 'La técnica de reatribución (opción D) es la que, dentro de la terapia cognitiva de Beck, se clasifica como de tipo cognitivo porque consiste en modificar la interpretación que el paciente hace de los eventos, sustituyendo la explicación disfuncional por una más realista y adaptativa; se centra en la reestructuración de los pensamientos automáticos y en la identificación de distorsiones cognitivas, lo que es el núcleo de la intervención cognitiva. En cambio, el análisis de responsabilidad (A) se orienta a la evaluación de la culpabilidad y la atribución de causas, pero no implica la modificación directa de los pensamientos automáticos; el role‑playing (B) es una técnica conductual que simula situaciones para practicar respuestas nuevas, y la distracción externa (C) es una estrategia de manejo de síntomas que desvía la atención sin abordar la estructura cognitiva subyacente. Todas las demás opciones, por lo tanto, pertenecen a categorías distintas (conductual o de gestión de síntomas) y no cumplen con el criterio de reestructuración cognitiva.'),
  (561, 'La afirmación que resulta incorrecta es la B, pues la concordancia genética entre gemelos idénticos con trastorno bipolar no alcanza el 50 %; estudios de gemelos indican una concordancia de aproximadamente 70 % en gemelos mono‑idénticos y mucho menor en gemelos fraternos, lo que refleja la influencia de factores genéticos fuertes pero no determinantes, y la presencia de factores ambientales y epigenéticos que modulan la expresión del trastorno. La opción A es coherente con la evidencia de que los factores constitucionales (biológicos, neuroquímicos y genéticos) constituyen la base del trastorno bipolar. La C es válida, pues el estrés situacional es un desencadenante bien documentado de episodios maníacos. La D también es correcta, ya que alteraciones mínimas en el patrón de sueño pueden precipitar o agravar episodios en individuos con predisposición bipolar, evidenciando la estrecha relación entre el ritmo circadiano y la estabilidad del estado de ánimo.'),
  (562, 'El delirio descrito corresponde al síndrome de Ekbom, también conocido como delirio de infestación o delirio de parasitosis, en el cual el paciente percibe la presencia de insectos o parásitos sobre o dentro de su piel, acompañada de alucinaciones táctiles y somáticas; este fenómeno se explica por la alteración de la percepción sensorial y la integración somatosensorial típica de las psicosis, donde la información sensorial se interpreta erróneamente como una amenaza externa. El síndrome de Cotard (A) se caracteriza por delirios de negación de la propia existencia o de los órganos, no por infestación cutánea; el síndrome de Otelo (B) es un trastorno del pensamiento con ideas de referencia y de control, sin componente somático de infestación; el síndrome de Fregoli (D) implica la creencia de que personas distintas son una misma identidad que cambia de forma, tampoco involucra la sensación de parásitos en la piel.'),
  (563, 'El trastorno formal del pensamiento se caracteriza por alteraciones en la lógica, la coherencia y la organización de los contenidos mentales, manifestándose en síntomas como alucinaciones, delirios, pensamiento desorganizado y discurso incoherente; la esquizofasia, que se define precisamente como una alteración de la forma del pensamiento con pérdida de la coherencia y la lógica, encaja en esta categoría, pues constituye un trastorno formal del pensamiento. Las demás opciones corresponden a procesos cognitivos o emocionales que no implican alteraciones en la estructura formal del pensamiento: los pensamientos automáticos negativos son respuestas automáticas y evaluaciones negativas que aparecen en la depresión; la obsesión es una idea recurrente y persistente que se presenta en el trastorno obsesivo‑compulsivo; y las preocupaciones son pensamientos evaluativos sobre posibles amenazas, típicos de la ansiedad; por lo tanto, solo la esquizofasia satisface la definición de trastorno formal del pensamiento.'),
  (564, 'El trastorno formal del pensamiento de tipo negativo se caracteriza por la reducción de la producción y la calidad del discurso, manifestándose como una disminución de la cantidad de contenido y la falta de fluidez verbal; la alogia, que implica una restricción marcada del habla con respuestas breves y poco elaboradas, es el ítem que mejor encaja en esta definición clínica, pues refleja la pérdida de contenido expresivo y la incapacidad de generar ideas complejas. Las demás opciones son inadecuadas: la incoherencia (A) corresponde a un trastorno formal de tipo positivo, donde el discurso se vuelve ilógico y desorganizado; la pérdida de meta (B) es un síntoma de la desorganización del pensamiento, no de la reducción del mismo; y la resonancia (D) se refiere a la repetición de ideas o palabras, un fenómeno que no implica la reducción del contenido discursivo.'),
  (565, 'La afirmación B resulta errónea porque la terapia cognitivo‑conductual para la psicosis no emplea la desdramatización ni el análisis de ventajas e inconvenientes de mantener la creencia delirante como estrategias centrales; dichas técnicas pertenecen a la terapia de aceptación y compromiso o a intervenciones de reestructuración cognitiva más general, pero en el contexto psicótico se prioriza la identificación de pensamientos disfuncionales, la prueba de realidad y la reestructuración de la interpretación de los síntomas, evitando la confrontación directa con la creencia delirante que puede provocar crisis. En contraste, la opción A describe correctamente la normalización del delirio como intento de dar sentido a experiencias extrañas, la opción C señala la importancia de probar la alternativa no delirante mediante pruebas de realidad, y la opción D refleja la inclusión de la TCC en la mayoría de las guías de práctica clínica como tratamiento psicológico de elección para la psicosis.'),
  (566, 'La terapia contextual, que incluye enfoques como la terapia de aceptación y compromiso (ACT) y la terapia dialéctico-conductual (DBT) adaptada a la psicosis, dispone de evidencia clínica limitada y de estudios de calidad moderada, por lo que la guías de práctica clínica la sitúan con un nivel de evidencia bajo y un grado de recomendación menor; en contraste, la terapia cognitivo-conductual para la psicosis cuenta con numerosos ensayos controlados que demuestran eficacia en la reducción de síntomas y la mejora funcional, lo que le otorga un nivel de evidencia alto y una recomendación fuerte; la intervención familiar, respaldada por estudios longitudinales que evidencian la reducción de recaídas y la mejora de la adherencia al tratamiento, también se clasifica con un nivel de evidencia sólido y una recomendación alta; el tratamiento asertivo comunitario, que combina la atención farmacológica con apoyo psicosocial intensivo, posee evidencia robusta en estudios multicéntricos y se recomienda de forma consistente, situándolo en un nivel de evidencia y recomendación superior al de la terapia contextual.'),
  (567, 'La opción A es la única que refleja el procedimiento clínicamente validado de la terapia cognitivo‑conductual (TCC) frente a los delirios: la comprobación empírica, o “challenge” de la evidencia, debe situarse después de la fase de análisis verbal, donde se desglosa la creencia, se identifican los esquemas subyacentes y se evalúa la lógica interna; esta secuencia permite al paciente comprender la estructura de su pensamiento antes de confrontar la evidencia, reduciendo la resistencia y favoreciendo la aceptación del cambio. La alternativa B es errónea porque el trabajo con el significado de los esquemas cognitivos depende intrínsecamente del insight del paciente; sin una base de reconocimiento de la propia distorsión, el reestructuramiento cognitivo pierde eficacia. La C es falsa porque el análisis verbal de una creencia delirante comprende tres fases: identificación de la creencia, análisis de la evidencia y evaluación de la lógica interna, no solo dos. Finalmente, la D se basa en una práctica contraproducente: cuestionar directamente la idea delirante suele aumentar la defensa y la resistencia, pues el paciente percibe una amenaza a su identidad y a su realidad, lo que dificulta la apertura al cambio.'),
  (568, 'El objetivo del trabajo con esquemas cognitivos básicos en pacientes con voces persistentes es trabajar los factores de vulnerabilidad previos al inicio del trastorno, pues la teoría de los esquemas sostiene que patrones de pensamiento disfuncionales arraigados en la infancia predisponen a la aparición de síntomas psicóticos y que su modificación temprana reduce la probabilidad de que se consoliden como alucinaciones; al intervenir en estos esquemas se alteran las interpretaciones automáticas que generan la experiencia de voces, evitando que se conviertan en un fenómeno crónico. Las demás opciones son incorrectas: la opción B se refiere a estrategias de afrontamiento de las alucinaciones, que son una fase de manejo de síntomas y no el objetivo primario de la intervención esquemática; la opción C habla de prevenir interpretaciones delirantes, que corresponde a un enfoque más centrado en la psicopatología delirante que en la modificación de esquemas básicos; y la opción D, aunque el funcionamiento social puede mejorar como efecto secundario, no constituye el objetivo central del trabajo con esquemas cognitivos básicos.'),
  (569, 'El psicólogo clínico debe ser capaz de representar de manera veraz el carácter y el papel de la voz en relación con la persona que presenta las voces, ya que la terapia AVATAR requiere que el terapeuta comprenda y modelice la voz como una entidad con su propia identidad, motivaciones y dinámicas interpersonales, facilitando así la reestructuración cognitiva y la desensibilización emocional; las demás opciones son erróneas porque la intervención no es completamente autoadministrada (la opción A y B subestiman la necesidad de supervisión y ajuste clínico) y la opción D confunde la confrontación directa con la necesidad de una representación precisa y empática de la voz, lo que no es el objetivo principal de la terapia AVATAR.'),
  (570, 'La terapia basada en la mentalización para niños (MBT‑C) se fundamenta en la teoría del apego porque su objetivo principal es fortalecer la capacidad de los infantes para interpretar y regular sus estados internos y los de los demás a partir de las experiencias de relación temprana, lo que mejora la coherencia interna y la regulación emocional; la intervención se centra en el reconocimiento de las intenciones y emociones subyacentes en las interacciones con figuras de apego, facilitando la internalización de esquemas de seguridad. La resolución de problemas (A) es una técnica que se emplea en otras modalidades terapéuticas, pero no constituye el eje central de la MBT‑C; las defensas del yo (B) son mecanismos de protección que la MBT‑C busca observar y modificar, pero no son su fundamento teórico; el desarrollo del insight (D) es un resultado potencial de la mejora en la mentalización, pero no es el aspecto fundamental sobre el que se construye la intervención.'),
  (571, 'La externalización consiste en separar el problema de la persona, de modo que el niño o adolescente pueda verlo como una entidad distinta y, por tanto, más manejable; en la práctica clínica se suele describir el trastorno como una “sombra malvada” que se proyecta sobre el individuo, lo que permite al paciente identificar y confrontar el síntoma sin internalizarlo como parte de su identidad, facilitando la intervención terapéutica y la motivación para cambiar; las demás opciones son incorrectas porque la opción B describe una evaluación de recursos, no una técnica de externalización; la opción C, aunque positiva, se refiere a la visualización de un futuro sin problema, no a la separación del problema como entidad externa; y la opción D implica una intervención familiar limitada, sin abordar la distinción entre el problema y el paciente.'),
  (572, 'El trastorno de la comunicación social (pragmático) se caracteriza por una dificultad persistente en el uso social de la comunicación verbal y no verbal, es decir, la incapacidad de adaptar el lenguaje al contexto, a la audiencia o a las normas sociales, lo que impide la interacción adecuada; por ello la opción B describe precisamente los criterios diagnósticos del DSM‑5, que incluyen la alteración de la conversación y la interpretación de la comunicación no literal. La alternativa A se refiere a la disfonía fonológica, típica de trastornos del habla como la disfonía o la dislalia, y no implica dificultades pragmáticas. La opción C describe la repetición de sonidos y sílabas, característica de los trastornos del lenguaje expresivo o de la repetición, pero no aborda la dimensión social del uso del lenguaje. Finalmente, la respuesta D confunde la edad de aparición con la complejidad de las interacciones sociales; el trastorno puede manifestarse ya en la primera infancia y no se limita a la adolescencia tardía.'),
  (573, 'La opción D es la que se aparta de la definición del DSM‑5; el criterio de discapacidad intelectual no exige que el CI total sea de 70 o inferior, sino que se requiera un rendimiento intelectual significativamente por debajo del promedio (generalmente un CI de 70‑75) y una deficiencia en el funcionamiento adaptativo, pero la medida puede ser cualquier prueba estandarizada que evalúe el CI y el comportamiento adaptativo; además, el DSM‑5 permite la utilización de pruebas no necesariamente individualizadas, siempre que sean válidas y confiables para la población evaluada. En cambio, la alternativa A describe correctamente la inclusión de limitaciones tanto en el funcionamiento intelectual como en el adaptativo, la B señala que las deficiencias aparecen durante el desarrollo, y la C recoge adecuadamente los dominios cognitivos afectados (razonamiento, resolución de problemas, planificación y pensamiento abstracto), todos en concordancia con los criterios diagnósticos del manual.'),
  (574, 'El trastorno de apego reactivo (TR) y el trastorno de relación social desinhibida (TRSD) comparten la característica de que ambos se originan en experiencias tempranas de negligencia o carencia social, donde las necesidades emocionales básicas del niño no se satisfacen de manera consistente por los cuidadores; esta falta de respuesta afectiva conduce a la incapacidad de establecer vínculos selectivos y seguros, lo que se refleja en la ausencia de relaciones afectivas estables y en la dificultad para regular las emociones. Las demás opciones son incorrectas porque la opción A describe un comportamiento excesivamente familiar y la incapacidad de establecer vínculos selectivos, lo cual es más propio del trastorno de apego evitativo, no de TR o TRSD; la opción B se refiere a relaciones sociales alteradas e inadecuadas, característica del trastorno de relación social desinhibida, pero no es un rasgo común a ambos trastornos; y la opción D menciona episodios de irritabilidad, tristeza o miedo inexplicado, que son síntomas de trastornos de ansiedad o depresión, no de los trastornos de apego o relación social.'),
  (575, 'La opción C es la que se ajusta a la práctica clínica de EMDR en población infantojuvenil, pues el protocolo adaptado para menores permite integrar recursos lúdicos y expresivos, como el dibujo, para facilitar la codificación y el procesamiento de las memorias traumáticas en un lenguaje que el niño pueda comprender y expresar; además, la evidencia indica que la utilización de medios visuales y artísticos mejora la participación y la retención de la información durante la fase de procesamiento bilateral. En contraste, la alternativa A es incorrecta porque sí existe un protocolo estandarizado para menores, que contempla fases específicas de preparación, identificación de recursos y de procesamiento; la opción B es errónea porque la estimulación bilateral en EMDR no se limita al tapping, pudiendo emplearse movimientos oculares, sonidos o tacto; y la alternativa D es falsa, ya que la participación del entorno familiar es esencial para la consolidación de los recursos internos y la contextualización de la experiencia traumática, favoreciendo la transferencia de seguridad y la continuidad del tratamiento.'),
  (576, 'El trastorno negativista desafiante se caracteriza por un patrón persistente de conducta desobediente, hostil y desafiante que suele originarse en la infancia y se mantiene en la adolescencia; la literatura clínica indica que las familias con mayor presencia de estrategias disciplinarias coercitivas y de control rígido favorecen la aparición y la persistencia de estos rasgos, pues el uso frecuente de castigos y la falta de límites consistentes aumentan la frustración y la resistencia del niño, generando un círculo vicioso de confrontación; por ello la opción A refleja el patrón de riesgo familiar más robustamente respaldado por estudios de investigación. En contraste, la opción B sobre hallazgos biológicos no explica la variabilidad individual, ya que los estudios genéticos y neurobiológicos del TND son aún preliminares y no determinan la expresión clínica; la opción C presenta una cifra errónea, pues la comorbilidad entre TDAH y TND es mucho mayor que el 10 %; y la opción D es incorrecta porque la intervención “The Incredible Years” cuenta con una sólida evidencia empírica que demuestra su eficacia en la reducción de la conducta negativista y la mejora de la relación familiar.'),
  (577, 'La FBT se fundamenta en la premisa de que el trastorno alimentario es un fenómeno que se mantiene y se expresa dentro de la dinámica familiar, por lo que la intervención se dirige a la familia como unidad de cambio; los estudios controlados aleatorios y meta‑análisis muestran que, sobre todo en la anorexia nerviosa infantil y adolescente, la FBT produce tasas de recuperación superiores a las de tratamientos individuales o de otras terapias familiares, con efectos sostenidos a mediano plazo, lo que respalda la afirmación de que cuenta con evidencia empírica suficiente; en contraste, la opción B es errónea porque la gravedad inicial no se asocia de forma consistente con una menor mejoría en FBT, la opción C es incorrecta pues la FBT no busca integrar el trastorno en la identidad del paciente sino externalizarlo y reducir su influencia sobre la familia, y la opción D es falsa porque la FBT se implementa típicamente con un equipo multidisciplinar que incluye psicólogo, psiquiatra, nutricionista y, en algunos protocolos, pediatra, garantizando una atención integral.'),
  (578, 'El entrenamiento conductual para padres en preescolares es el único procedimiento que la Society for Clinical Child and Adolescent Psychology (Division 53) clasifica como nivel 1, es decir, con evidencia robusta y consistente de eficacia en estudios controlados aleatorios que demuestran mejoras significativas en la atención, hiperactividad e impulsividad de niños con TDAH; la intervención se basa en la modificación de las contingencias parentales, el refuerzo positivo y la estructuración del entorno, lo que produce cambios duraderos en el comportamiento del niño y en la dinámica familiar. Las demás opciones carecen de ese nivel de evidencia: el neurofeedback (A) y el entrenamiento cognitivo (B) presentan resultados mixtos y falta de replicabilidad en estudios de alta calidad, mientras que la terapia basada en el control de las emociones (D) se ha evaluado principalmente en muestras de adolescentes con trastornos comórbidos y no se ha demostrado su eficacia exclusiva para el TDAH, por lo que no alcanzan la clasificación de nivel 1.'),
  (579, 'La intervención naturalista conductual en desarrollo (ICD) es la que ostenta grado de recomendación A en las Guías de Práctica Clínica del Sistema Nacional de Salud Español porque, según la evidencia acumulada, combina principios de análisis conductual con la estructura natural del entorno familiar y escolar, demostrando eficacia en la mejora de la comunicación, la interacción social y la reducción de conductas problemáticas en niños con trastorno del espectro autista; además, su aplicación temprana y su enfoque contextual facilitan la generalización de habilidades y la participación activa de los cuidadores, lo que se refleja en los protocolos de recomendación de mayor nivel. Por el contrario, la intervención conductual intensiva temprana, aunque eficaz, se clasifica con grado B debido a la menor cantidad de estudios de alta calidad que avalen su aplicación generalizada; el entrenamiento en habilidades sociales, aunque útil, se sitúa en grado C por su menor impacto en la autonomía funcional y la falta de evidencia robusta en poblaciones heterogéneas; y la intervención temprana basada en familias, aunque valiosa, recibe grado B porque su eficacia depende en gran medida de la formación específica de los profesionales y de la disponibilidad de recursos familiares, factores que limitan su universalidad dentro del marco de las guías.'),
  (580, 'La intervención descrita corresponde al entrenamiento en conductas pivotales de aprendizaje, pues las conductas pivotales son aquellas que, al modificarse, generan mejoras generalizadas en la motivación, la iniciativa, la autodirección y la interacción social, aspectos esenciales en el trastorno del espectro autista; el objetivo de esta técnica es potenciar la iniciativa hacia el aprendizaje y la diversificación de intereses, lo que no se logra con el entrenamiento en conductas generales, concretas, básicas lectoras o cualquier otra modalidad que no aborde la dimensión de la motivación y la iniciación social.'),
  (581, 'El CBIT (Comprehensive Behavioral Intervention for Tics) se basa en la terapia de aceptación y compromiso y en la modificación conductual; incluye la identificación de los estímulos antecedentes y las consecuencias de los tics (opción C), el entrenamiento en la inversión del hábito (opción A) y la incorporación de técnicas de relajación para reducir la tensión que puede precipitar los tics (opción B), por lo que esas tres son componentes esenciales; la práctica negativa masiva, que consiste en la repetición continua de la conducta sin la presencia de estímulos desencadenantes, no forma parte del protocolo CBIT y se utiliza en otras intervenciones de modificación de hábitos, por lo que la opción D es la que no se incluye.'),
  (582, 'La evidencia de la literatura sistemática y los guías de práctica clínica indican que la terapia dialéctico‑conductual adaptada a adolescentes (DBT‑A) posee el mayor nivel de evidencia y grado de recomendación para el tratamiento de las autolesiones en esta población; los ensayos controlados randomizados han demostrado una reducción significativa de la frecuencia y gravedad de las conductas autolesivas, así como mejoras en la regulación emocional y la reducción de la ideación suicida, lo que justifica su posición como la intervención de referencia. Por el contrario, la psicoterapia individual para adolescentes (IPT‑A) y la terapia cognitivo‑conductual integrada (I‑CBT) presentan evidencia moderada y se han estudiado con menos rigurosidad en muestras específicas de autolesiones, mientras que la terapia basada en la mentalización para adolescentes (MBT‑A) carece de estudios controlados que demuestren eficacia superior, por lo que se sitúan en un nivel de recomendación inferior.'),
  (583, 'El modelo transdiagnóstico Group Behavioral Activation Therapy (GBAT) se centra en la activación conductual y la reducción de la evitación, por lo que incluye la psicoeducación sobre la ansiedad y la depresión (A) para contextualizar los síntomas y motivar el cambio, la evaluación funcional e identificación del papel de la evitación (B) como base para la intervención, y la solución de problemas y toma de decisiones (C) para mejorar la funcionalidad diaria; en cambio, la opción D se refiere a psicoeducación conductual sobre trastornos del comportamiento, una dimensión que no forma parte de la estructura de GBAT, ya que el modelo se orienta a la activación y la reducción de la evitación más que a la enseñanza específica de conductas problemáticas. Las opciones A, B y C son coherentes con los componentes teóricos y prácticos de GBAT, mientras que la D es incorrecta porque no corresponde al alcance de la intervención.'),
  (584, 'El duelo complicado en la infancia y adolescencia se caracteriza por la persistencia de síntomas disfuncionales que interfieren con el desarrollo normal; la literatura indica que la presencia de un cuidador que haya afrontado su propio proceso de duelo de manera adecuada constituye un factor protector porque el niño aprende estrategias de regulación emocional y modela una adaptación saludable, lo que reduce la probabilidad de que el duelo se vuelva patológico, mientras que la ausencia de este apoyo puede perpetuar la angustia; las demás opciones fallan porque la edad de diagnóstico no está limitada a los 5 años, ya que los niños a partir de los 3 años ya comprenden la muerte y pueden presentar síntomas de duelo complicado; la exposición en vivo, típica de los trastornos de estrés postraumático, no es el componente principal del tratamiento de duelos traumáticos, que suele centrarse en la reestructuración cognitiva y la integración del recuerdo; y aunque las conductas regresivas pueden aparecer en el proceso de duelo, no son el síntoma principal en la adolescencia, donde predominan la angustia, el aislamiento y la disociación.'),
  (585, 'El enunciado señala que la evidencia más robusta sobre el tratamiento del mutismo selectivo proviene de estudios de caso único, ya que la literatura clínica se compone mayoritariamente de reportes individuales que describen intervenciones específicas y sus resultados, lo que permite una comprensión detallada de los procesos de cambio en contextos reales; por ello la opción C es la que se ajusta a la realidad de la investigación en este campo. Las demás alternativas son erróneas porque A presupone la existencia de protocolos estandarizados y ampliamente validados, lo cual no se ha logrado aún; B indica que la terapia sistémica es la primera elección, cuando en realidad la intervención más recomendada es la terapia cognitivo‑conductual adaptada al mutismo selectivo; y D confunde la orientación de la IBTSM, la cual se fundamenta en principios conductuales y de exposición, no en una perspectiva psicodinámica.'),
  (586, 'El trastorno de estrés postraumático (TEPT) en la infancia y adolescencia se caracteriza por la presencia de síntomas de reexperimentación, evitación, alteraciones cognitivas y afectivas y alteraciones de arousal, pero la manifestación de las pesadillas puede diferir de la adulta: en los menores las pesadillas suelen ser de contenido inespecífico y no necesariamente referidas al evento traumático, lo que facilita la identificación clínica y la diferenciación de otras alteraciones del sueño; por tanto, la opción B es la que refleja la característica clínica específica del TEPT en esta población. La alternativa A es incorrecta porque la prevalencia del TEPT en menores es comparable o incluso mayor que en adultos, especialmente en contextos de violencia doméstica o escolar; la opción C es errónea ya que existen diferencias de género en la expresión del TEPT, con mayor frecuencia de síntomas de ansiedad y depresión en niñas y mayor probabilidad de conductas agresivas en niños; y la opción D es falsa porque el DSM‑5 no establece criterios diferenciados por edad menor de 10 años, sino que permite la aplicación de los criterios generales con ajustes de edad en la descripción de síntomas.'),
  (587, 'La opción D es la que se ajusta a la guía de tratamiento de trastorno de estrés postraumático en la infancia, pues la fase inicial consiste en psicoeducar al niño y a sus cuidadores sobre la naturaleza de los síntomas, la respuesta fisiológica al trauma y la importancia de la seguridad, lo que facilita la posterior participación en intervenciones más activas; la exposición en imaginación (opción B) pertenece a la fase de procesamiento de la memoria traumática, no a la primera, y la relajación (opción C) se emplea en fases de manejo de la activación fisiológica, no al final; la afirmación A es errónea porque existen intervenciones con grado de recomendación, como la terapia cognitivo-conductual adaptada, que han demostrado eficacia en esta población.'),
  (588, 'La opción D es la única que refleja la obligación legal y ética de los profesionales de la salud mental de notificar a las autoridades competentes cualquier revelación de violencia sexual infantil, independientemente de la presencia de síntomas clínicos o del consentimiento de los progenitores, ya que la ley de protección de menores establece la notificación obligatoria como medida de prevención y protección; la opción A presenta una cifra que excede los datos epidemiológicos aceptados, donde los estudios indican que la prevalencia oscila entre el 10 y el 20 % de los menores; la opción B es incorrecta porque el consentimiento de los padres no es requisito para la notificación cuando se trata de un menor en riesgo, pues la protección del niño prevalece sobre la autonomía familiar; la opción C es errónea porque la violencia sexual infantil no garantiza la aparición de psicopatología en la edad adulta, aunque sí aumenta el riesgo de trastornos, pero no es una relación causal universal.'),
  (589, 'La técnica descrita corresponde a la recast o reformulación conversacional, pues consiste en repetir la expresión del niño, ampliándola o modificándola ligeramente para ofrecer un modelo más complejo y estructurado que el niño pueda internalizar y usar en su propio discurso; esta estrategia se emplea en la terapia del lenguaje infantil para mejorar la producción lingüística y la comprensión semántica, y se basa en principios de aprendizaje por imitación y modelado. El pensamiento en voz alta (A) se refiere a la externalización de procesos internos del adulto, no a la ampliación de las verbalizaciones infantiles. La habla paralela (C) implica repetir simultáneamente el discurso del interlocutor sin alteración, y la estimulación focalizada (D) se centra en reforzar habilidades específicas mediante ejercicios estructurados, sin la característica de reformulación del enunciado.'),
  (590, 'La falta de atención conjunta, es decir, la incapacidad de compartir el foco de atención con otra persona hacia un objeto o evento, constituye la primera señal clínica de alerta para el diagnóstico del trastorno del espectro autista en el rango de 12 a 18 meses, pues refleja una alteración temprana de la interacción social y la comunicación no verbal, elementos esenciales en el desarrollo típico; las demás opciones describen dificultades que aparecen más adelante o que no son específicas del espectro, como la interpretación de normas sociales (A), la inversión pronominal (B) o la comprensión de dobles sentidos (D), por lo que no cumplen el criterio de manifestación precoz.'),
  (591, 'El modelo Early Start Denver (ESDM) se considera eficaz para el autismo porque combina intervención temprana intensiva con principios de aprendizaje social y cognitivo‑conductual, demostrando en estudios de nivel de evidencia 1+ mejoras significativas en habilidades cognitivas, lenguaje y conducta adaptativa en niños de 12 a 48 meses; la intervención se entrega en un entorno natural, con sesiones diarias de 2–3 h, lo que permite la generalización de habilidades y la participación activa de la familia, factores críticos que han sido reproducidos en ensayos controlados aleatorios y revisiones sistemáticas. El Programa TEACCH, aunque útil para estructurar el entorno y mejorar la comunicación, carece de evidencia de nivel 1+ en cuanto a cambios globales en el funcionamiento adaptativo. El PECS, aunque mejora la comunicación simbólica, se ha evaluado principalmente en estudios de nivel 2 o 3 y no alcanza la robustez de los ensayos de nivel 1+. El modelo DIR, centrado en la relación y la motivación, se basa mayormente en estudios de caso y diseños no controlados, por lo que tampoco cuenta con evidencia de nivel 1+. Así, solo el ESDM cumple con el criterio de evidencia 1+.'),
  (592, 'La Guía NICE 2019 indica que, en menores de 12‑18 años con depresión moderada‑grave, la intervención primaria debe ser la Terapia Cognitivo‑Conductual (TCC) individual, con una duración mínima de 3 meses para asegurar la consolidación de las habilidades de afrontamiento y la reestructuración cognitiva; la evidencia sistemática muestra que este esquema reduce la sintomatología y previene recaídas, mientras que la TCC grupal o familiar no sustituye la individualidad de la intervención en este rango etario. Las demás opciones se apartan de la guía: la recomendación de “cualquier criterio del facultativo” (B) ignora el consenso de NICE sobre la necesidad de considerar las preferencias del menor y sus cuidadores, especialmente en la infancia temprana; la fluoxetina (C) no es la primera opción farmacológica para depresión leve, pues NICE sugiere iniciar con intervenciones psicológicas y, solo en casos de moderación‑grave, considerar la medicación, preferentemente con sertralina o fluvoxamina, no con fluoxetina; y la prohibición de la psicoterapia psicodinámica en menores de 5‑11 años (D) es incorrecta, ya que NICE permite su uso cuando se adapta al desarrollo cognitivo y emocional del niño, aunque la evidencia es más limitada, no la excluye.'),
  (593, 'En el trastorno bipolar infantil y juvenil, la definición de episodio hipomaníaco exige una persistencia de al menos cuatro días consecutivos de estado de ánimo elevado, irritable o eufórico, acompañado de síntomas de mayor energía y actividad que se mantienen por lo menos a la mitad de la duración de un episodio maníaco completo, pero sin alcanzar la gravedad de la manía; la normativa DSM‑5 y la clasificación de la OMS establecen explícitamente el umbral de cuatro días para diferenciar la hipomanía de la manía, pues los episodios de tres días o menos suelen considerarse transitorios o parte de la fase de “ciclos de humor” sin cumplir criterios diagnósticos, mientras que un lapso de cinco días o más, aunque clínicamente posible, no se distingue de la hipomanía en la clasificación y se considera parte de la misma categoría, pero la opción que refleja el mínimo exigido por la normativa es la de cuatro días. Por tanto, la alternativa A (3 días) y la C (5 días) no cumplen con el criterio mínimo de duración, y la D (al menos una semana) excede el límite establecido para la hipomanía, por lo que solo la opción B satisface los requisitos diagnósticos.'),
  (594, 'El modelo de actitudes unitario de Thurstone (1931) conceptualiza la actitud como la valoración afectiva que una persona asigna a un objeto, es decir, el grado de afecto positivo o negativo que se experimenta, sin distinguir entre componentes cognitivos o conductuales; por ello la opción C describe adecuadamente la esencia de la actitud según este enfoque, pues enfatiza el valor afectivo que se asigna al objeto psicológico. Las demás alternativas resultan inexactas: la A introduce una distinción entre actitud implícita y explícita que no aparece en el modelo unitario, la B confunde la actitud con procesos deliberados o automáticos que pertenecen a teorías de procesamiento dual, y la D plantea una dicotomía objetiva‑subjetiva que no corresponde al énfasis de Thurstone en la valoración afectiva interna.'),
  (595, 'La respuesta se fundamenta en el concepto de despersonalización dentro de la teoría de la identidad social, que sostiene que cuando la identidad personal se diluye y el individuo se percibe como parte de un colectivo, la influencia del grupo y sus líderes se intensifica, permitiendo la obediencia sin cuestionar la validez de las órdenes; las demás opciones fallan porque la prominencia de la identidad social (B) no explica la pérdida de juicio individual, la discrepancia entre el autoconcepto y el prototipo del grupo (C) implicaría una mayor resistencia, y una autoconciencia pública baja (D) no necesariamente conduce a la obediencia ciega.'),
  (596, 'La influencia social normativa se refiere a la presión que ejerce el grupo sobre el individuo para que adopte conductas, actitudes o creencias que se perciben como socialmente aceptables, con el fin de obtener aprobación y evitar el rechazo; por eso la opción C describe correctamente el fenómeno al señalar la tendencia a cumplir con las expectativas de los demás para obtener aprobación social. Las demás opciones no capturan este concepto: la A describe la influencia informacional, la B la influencia de identidad o diferenciación, y la D se acerca a la influencia normativa pero enfatiza la adhesión a normas de grupo como definición de pertenencia, lo cual no es la esencia de la normativa que se centra en la aprobación social.'),
  (597, 'La complacencia inducida se define como la tendencia de una persona a aceptar una propuesta o una posición que no corresponde a sus verdaderas creencias o intereses, con el fin de evitar la disonancia cognitiva que surgiría al actuar en contradicción con la información recibida; por tanto, la opción A es la que describe correctamente este fenómeno, ya que la disonancia cognitiva es el proceso de tensión interna que se produce cuando se mantienen simultáneamente dos cogniciones incompatibles, y la complacencia inducida actúa como un mecanismo de reducción de esa tensión. Las demás alternativas son inexactas: la B se refiere a la desindividuación, que implica la pérdida de la identidad individual en grupos, no a la aceptación de propuestas; la C menciona la reciprocidad, un principio de intercambio social que no implica la aceptación de ideas ajenas para evitar la disonancia; y la D habla de dilema social, que implica decisiones entre intereses individuales y colectivos, pero no abarca el mecanismo de complacencia inducida.'),
  (598, 'El fenómeno descrito corresponde al heurístico de disponibilidad, que postula que la frecuencia percibida de un evento se sobreestima cuando la información sobre él es fácilmente accesible en la memoria, lo que aumenta la impresión de que existen numerosos casos similares; este mecanismo se explica por la rapidez con la que se recuperan ejemplos recientes o vívidos, lo que distorsiona la estimación objetiva de la probabilidad. El heurístico de representatividad (opción A) se refiere a la similitud entre un caso y un prototipo, no a la facilidad de recuperación; el heurístico de ajuste (B) implica la modificación de una estimación inicial por información adicional, y el heurístico de anclaje (D) implica la influencia de un valor inicial sobre la estimación final; ambos no explican la relación entre accesibilidad y percepción de frecuencia.'),
  (599, 'Hofstede (1980) desarrolló su primer modelo de clasificación cultural a partir de un análisis comparativo de datos de encuestas de empleados de IBM en más de 50 países, identificando cuatro dimensiones que capturan diferencias sistemáticas en valores y comportamientos organizacionales: distancia de poder (grado de aceptación de desigualdades jerárquicas), evitación de incertidumbre (tolerancia a la ambigüedad y la imprevisibilidad), masculinidad-feminidad (orientación hacia la competencia y el logro frente a la cooperación y la calidad de vida) e individualismo‑colectivismo (prioridad de metas personales sobre las del grupo). Estas dimensiones se derivan de la teoría de la cultura como un conjunto de valores compartidos que guían la conducta, y su relevancia clínica radica en la comprensión de cómo las normas culturales influyen en la percepción de la autoridad, la gestión del estrés y la construcción de la identidad personal. Las demás opciones son incorrectas porque la alternativa B describe la tipología de valores de Schwartz, la C corresponde a la teoría de la motivación de Deci y Ryan, y la D al modelo de la cultura de Hofstede revisado en 2001; ninguna de ellas corresponde al primer conjunto de dimensiones propuesto en 1980.'),
  (600, 'La teoría de la atribución causal de Weiner sostiene que las personas evalúan las causas de los eventos a través de tres dimensiones centrales: locus (interior o exterior), estabilidad (fija o variable) y controlabilidad (controlable o incontrolable); estas dimensiones permiten diferenciar entre atribuciones disposicionales y situacionales y son fundamentales para comprender la motivación y la regulación emocional, ya que influyen en la autoeficacia y en la respuesta conductual. Las demás opciones son incorrectas: la alternativa A describe dimensiones de la teoría de la atribución de Kelley, no de Weiner; la C mezcla categorías de la teoría de la atribución de Rotter y la D corresponde a la clasificación de la teoría de la atribución de Weiner pero con una terminología distinta y sin incluir la dimensión de controlabilidad, por lo que no refleja el marco original.'),
  (601, 'La conducta prosocial se define como cualquier comportamiento que busca beneficiar a otro individuo o al grupo, y puede manifestarse tanto de forma altruista (sin expectativa de retorno) como no altruista (con motivaciones egoístas o de reciprocidad); por ello la opción A es la única que refleja la doble naturaleza de la prosocialidad, distinguiendo entre la motivación intrínseca y la extrínseca, algo que la literatura de psicología social confirma en estudios de ayuda voluntaria y de cooperación. Las demás alternativas son erróneas: la opción B presupone que la ayuda es siempre segura, lo cual no es cierto, pues la asistencia en situaciones de riesgo puede conllevar peligros físicos o psicológicos; la opción C sugiere una correlación positiva con el número de espectadores, cuando la evidencia apunta a la “paradoja del espectador” donde la presencia de más observadores suele disminuir la probabilidad de intervención; y la opción D afirma que la presencia de otro ayudante inhibe la conducta prosocial, lo cual contradice la teoría de la “influencia social positiva” que muestra que la ayuda de un tercero puede, en ciertos contextos, estimular la intervención de observadores adicionales.'),
  (602, 'El fenómeno descrito corresponde al fenómeno de correlaciones ilusorias, en el que la percepción de una relación entre dos variables se genera a partir de una muestra insuficiente y de la tendencia a recordar más los casos que confirman la relación, lo que provoca una sobrestimación de la frecuencia de comportamientos negativos en grupos pequeños; este sesgo se explica por la disponibilidad de la memoria y la necesidad de encontrar patrones, especialmente cuando la información es escasa y la atención se centra en los casos más salientes. Las demás opciones son incorrectas: el efecto priming se refiere a la activación de conceptos sin conciencia, la diferenciación del exogrupo describe la tendencia a ver a los miembros del propio grupo como más homogéneos y a los externos como heterogéneos, y el efecto Pygmalion implica la auto-realización de expectativas sobre el rendimiento de una persona.'),
  (603, 'El DSM‑5 establece que el Trastorno de Atracones requiere que los episodios de ingesta excesiva ocurran, en promedio, al menos una vez a la semana durante un período de tres meses; por ello la opción B coincide con la frecuencia y duración mínimas exigidas para el diagnóstico, reflejando la gravedad clínica del trastorno. Las demás alternativas son incorrectas: la A describe un sesgo de autoevaluación que se relaciona más con la imagen corporal en el Trastorno de la Conducta Alimentaria, pero no constituye un criterio diagnóstico; la C se refiere a la presencia de conductas compensatorias, característica del Trastorno de la Conducta Alimentaria con comportamiento compensatorio, no del trastorno de atracones; y la D establece una frecuencia mayor (dos veces a la semana) y una duración menor (dos meses), por lo que no cumple con los parámetros mínimos del DSM‑5.'),
  (604, 'El DSM‑5 clasifica al Trastorno negativista desafiante, a la piromanía y a la cleptomanía dentro de los “Trastornos disruptivos, del control de los impulsos y de la conducta” porque cada uno presenta una alteración persistente del control de impulsos que se manifiesta en conductas agresivas, destructivas o robóticas, con un patrón de comportamiento que interfiere en la vida social y funcional del individuo; el Trastorno negativista desafiante se caracteriza por un patrón de comportamiento desafiante y hostil hacia figuras de autoridad, la piromanía por la necesidad compulsiva de provocar incendios y la cleptomanía por la impulsividad para robar objetos que no tienen valor económico. En contraste, el juego patológico se ubica en la categoría de “Trastornos de la conducta de juego” (o “Trastornos de la conducta de juego y de la adicción a los juegos de azar”), ya que su núcleo es la compulsión a jugar a pesar de las consecuencias negativas, sin que la conducta se centre en el control de impulsos agresivos o destructivos. Por tanto, las opciones A, C y D se incluyen en la categoría solicitada, mientras que la opción B no lo hace.'),
  (605, 'En la Terapia Dialéctico-Conductual (TDC), la etapa 3 se denomina “Terapia de la vida cotidiana” y su objetivo es enseñar al paciente a vivir con una felicidad e infelicidad “ordinarias”, es decir, a aceptar la realidad tal cual es, sin intentar eliminar el sufrimiento ni buscar la perfección, y a reducir los problemas cotidianos mediante la aplicación de habilidades de regulación emocional, tolerancia al estrés y efectividad interpersonal; por ello la opción D describe con precisión la finalidad de esta fase. Las demás alternativas son inexactas: la A se refiere a la primera fase de la TDC, la “Terapia de la aceptación y la compasión”, donde se trabaja la “desesperación silenciosa”; la B describe la segunda fase, la “Terapia de la regulación emocional”, que busca controlar la conducta; y la C mezcla conceptos de otras terapias de tercera generación (como la terapia de aceptación y compromiso) sin corresponder a la etapa 3 de la TDC.'),
  (606, 'La terapia STEPPS (Systematic Treatment for Personality Disorder – Emotionally Unstable) se caracteriza por su estructura de 12 módulos semanales de 90 minutos que se imparten exclusivamente en grupo, con un enfoque educativo y de habilidades sociales que no se replica en sesiones individuales; por tanto, es la única opción que cumple el requisito de formato exclusivamente grupal. Las demás alternativas presentan componentes individuales: la Terapia Dialéctico-Conductual combina sesiones individuales con grupos de habilidades, la Terapia Cognitivo-Interpersonal integra sesiones individuales con trabajo grupal, y la Terapia Cognitivo-Analítica se basa principalmente en la relación terapéutica individual, por lo que no se ajustan al criterio de exclusividad grupal.'),
  (607, 'En la entrevista motivacional, la ambivalencia del paciente se aborda mediante la escucha empática y el reflejo de sus propios motivos para cambiar, evitando la corrección directa que puede generar resistencia; por tanto, la opción B es la que se ajusta a la técnica de no confrontar, pues el reflejo de corrección suele provocar defensas y disminuir la motivación. La opción A, el balance decisional, se emplea cuando el paciente ya ha decidido cambiar y necesita consolidar su decisión, no cuando está ambivalente; la opción C, dar argumentos a favor del cambio, corresponde a la fase de persuasión, que se reserva cuando el paciente muestra disposición, y la opción D, señalar sus defensas o resistencias, implica confrontación y puede intensificar la ambivalencia, por lo que las tres alternativas restantes son inadecuadas en este contexto.'),
  (608, 'El acrónimo ARCO (Acuerdo de Revisión y Control de la Organización) se emplea dentro del Protocolo Unificado para el Tratamiento Transdiagnóstico de los Trastornos Emocionales como herramienta de seguimiento y ajuste de la intervención, permitiendo a los profesionales registrar de forma sistemática los avances, dificultades y cambios en la respuesta terapéutica, lo que facilita la toma de decisiones clínicas y la coordinación entre los distintos profesionales implicados; las demás opciones no aparecen en la normativa del protocolo, ya que ABC, TIP y CCR1 corresponden a siglas de otros procedimientos o estudios que no se utilizan para la monitorización transdiagnóstica de los trastornos emocionales.'),
  (609, 'El término “alucinación pálida” de Griesinger designa un fenómeno en el que el sujeto percibe una imagen o sonido que parece real pero carece de la intensidad, claridad o fuerza que normalmente se esperaría; se trata de una experiencia perceptiva que, aunque no es una falsa creencia, sí es una distorsión de la percepción que se manifiesta con una calidad tenue y a menudo con una sensación de “algo que falta”. Este concepto se corresponde con la definición contemporánea de pseudoalucinación, que describe una percepción que parece real pero que no tiene la intensidad ni la vividez de una alucinación típica, y que suele asociarse a estados de déficit sensorial o a la presencia de estímulos débiles que el cerebro interpreta como perceptos. Las demás opciones no coinciden: la pseudopercepción implica una interpretación errónea de estímulos reales, no una percepción tenue; la anomalía en la intensidad de los estímulos se refiere a una distorsión perceptiva más general, sin la especificidad de la “pálida” que caracteriza al fenómeno de Griesinger; y la hipoestesia es una disminución de la sensibilidad sensorial, no una experiencia perceptiva de baja intensidad.'),
  (610, 'El modelo de Chadwick, Birchwood y Trower (1996) conceptualiza las voces auditivas como fenómenos que se interpretan a través de creencias sobre el poder, la identidad y el propósito de las voces; estas interpretaciones influyen en la respuesta emocional y conductual del paciente, por lo que el modelo enfatiza la necesidad de intervenir en dichas creencias para reducir la angustia y la disfunción. Las opciones A y B se refieren a categorías de creencias que aparecen en otros modelos (por ejemplo, el modelo de origen de las voces de Birchwood y el modelo de creencias esquemáticas nucleares de Berrios), pero no constituyen el eje central de la propuesta de Chadwick et al.; la opción D es incorrecta porque el modelo sí se centra en las creencias, aunque no sea su única preocupación, y por tanto las opciones A y B comparten el mismo motivo de error.'),
  (611, 'La intervención que contempla la enseñanza de “habilidades de detective” para que los niños descifren sus emociones es el Protocolo Unificado para niños, pues su estructura se basa en la terapia cognitivo‑conductual adaptada a la infancia, donde se utilizan metáforas de investigación y juegos de roles para que el niño identifique, nombre y analice sus estados afectivos, integrándolos en un esquema de autoconocimiento y regulación emocional; esta metodología se distingue de las demás opciones porque las otras intervenciones se centran en estrategias de afrontamiento general (Super Skills For Life), en el manejo de la ansiedad a través de la figura del koala (The Coping Koala) o en la activación de conductas específicas sin el componente investigativo (Take ACTION). Por tanto, las alternativas A, B y C no incluyen la dimensión de “detective” que es esencial para la resolución de misterios emocionales en la infancia.'),
  (612, 'La opción B es la que refleja la práctica contemporánea en la intervención con personas con discapacidad intelectual, pues el modelo funcional, orientado a la conducta y al aprendizaje de habilidades adaptativas, permite diseñar programas individualizados que mejoran la autonomía y la calidad de vida, integrando estrategias de refuerzo, enseñanza estructurada y apoyo contextual; la evidencia clínica demuestra que este enfoque reduce la dependencia y favorece la inclusión social. En contraste, la opción A privilegia un paradigma médico-psicométrico que, aunque útil para la clasificación, no orienta la intervención práctica y puede llevar a una visión reduccionista de la persona. La alternativa C confunde la necesidad de apoyos con la aplicación de baremos de gravedad, pues la intensidad de los apoyos debe basarse en la evaluación funcional y las metas de desarrollo, no únicamente en escalas de severidad. Finalmente, la opción D, al centrarse en pruebas de rendimiento objetivas para valorar el potencial, descuida el aspecto funcional y la adaptación contextual, limitando la intervención a una medición de capacidades sin traducirlas en estrategias de mejora práctica.'),
  (613, 'El patrón descrito—una alta frecuencia de respuestas seguida de una pausa tras cada refuerzo—indica un programa de razón fija, en el que la conducta se mantiene a un ritmo elevado hasta que se produce el refuerzo, después de lo cual la respuesta se detiene brevemente; la pausa es la consecuencia directa de la entrega del reforzador y la frecuencia de respuestas se mantiene constante porque el número de respuestas requeridas antes del refuerzo es fijo. Las opciones A y B describen programas de intervalo, donde el refuerzo depende del tiempo transcurrido y no de la cantidad de respuestas, por lo que no generan la pausa observada; la opción D, razón variable, produce un patrón de respuesta más irregular y no una pausa marcada tras cada refuerzo, ya que el número de respuestas requeridas varía de una ocasión a otra.'),
  (614, 'La tendencia descrita corresponde a la fijación funcional, ya que implica la imposibilidad de percibir un objeto más allá de su uso habitual, limitando la generación de alternativas creativas y obstaculizando la resolución de problemas; la fijación funcional se manifiesta cuando la experiencia previa condiciona la percepción de un objeto a una única función, impidiendo la exploración de otras posibilidades. El efecto de anclaje (B) se refiere a la influencia de un valor inicial sobre juicios posteriores, no a la limitación de usos de un objeto. El sesgo de utilidad (C) no es un término reconocido en la literatura cognitiva y, aun cuando sugiere una valoración de la utilidad, no explica la restricción de funciones aprendidas. El sesgo de disponibilidad (D) implica la facilidad con la que se recuerda información, lo cual no explica la imposibilidad de asignar nuevas funciones a un objeto.'),
  (615, 'La teoría de la emoción de Cannon‑Bard sostiene que la percepción de un estímulo emocional y la respuesta fisiológica se generan simultáneamente a partir de la actividad simultánea del tálamo y la corteza cerebral, sin que la activación fisiológica preceda ni determine la experiencia emocional; por ello la opción C es la que refleja fielmente el planteamiento de Cannon y Bard, que niegan la secuencia de estímulo‑respuesta fisiológica‑emocional propuesta por la teoría de James‑Lange. Las demás alternativas son erróneas: la A describe la hipótesis de James‑Lange, la B también corresponde a esa misma teoría, y la D se alinea con la idea de la teoría de la interpretación de Schachter‑Singer, que añade un componente cognitivo a la activación fisiológica, pero no es la concepción de Cannon‑Bard.'),
  (616, 'La tendencia de los adolescentes a percibir que están bajo constante observación y que los demás juzgan su apariencia y conducta se denomina audiencia imaginaria, pues implica una percepción distorsionada de la atención social que no se basa en evidencia objetiva sino en la interpretación subjetiva de la propia imagen frente a un público imaginario; esta distorsión es típica de la etapa de identidad de la adolescencia, donde la autoimagen y la valoración social son centrales y se manifiestan como una preocupación excesiva por la evaluación externa. La opción A, fábula personal, se refiere a la construcción de narrativas propias que explican la vida y no a la percepción de vigilancia; la C, identidad difusa, describe una falta de definición de la identidad, no la sensación de observación; y la D, confusión de roles, implica la dificultad para distinguir roles sociales, lo cual no corresponde a la preocupación por el juicio de los demás.'),
  (617, 'El fenómeno descrito corresponde a la saliencia atencional, también llamada “pop‑out”, porque los estímulos con contenido emocionalmente relevante (por ejemplo, serpientes o arañas) capturan la atención de forma automática y rápida, apareciendo primero en la búsqueda visual; esto se explica por la potenciación de las vías sensoriales que procesan la amenaza, lo que favorece su detección frente a estímulos neutrales. Las demás opciones son inadecuadas: la alternativa B sugiere un procesamiento top‑down, pero la detección de estímulos desagradables es principalmente bottom‑up; la C confunde el término “fear” con la respuesta emocional, no con el mecanismo de atención; y la D hace referencia al efecto Stroop, que implica interferencia semántica y no la rapidez de detección de estímulos de peligro.'),
  (618, 'Según la teoría de detección de señales de Green y Swets, la capacidad de una persona para detectar un estímulo depende de la sensibilidad del observador, es decir, de su capacidad fisiológica y cognitiva para percibir diferencias mínimas entre señal y ruido, y del criterio de respuesta que establezca para decidir cuándo se ha detectado la señal, lo que determina la tasa de verdaderos positivos y falsos positivos; la sensibilidad del observador se refleja en la pendiente de la curva ROC, mientras que el criterio de respuesta se representa por el punto de corte que el individuo elige en función de la importancia atribuida a los errores de tipo I y II. Las demás opciones son incorrectas porque la intensidad del estímulo (A y D) es una variable externa que afecta la señal pero no la determina; la sensibilidad del entorno (C) no es un constructo reconocido en la teoría, y el lugar en el que ocurre (D) no influye directamente en la detección según el modelo de detección de señales.'),
  (619, 'La dificultad descrita se explica mejor por la interferencia por sobrecarga de las claves, ya que al intentar recuperar un recuerdo específico del desayuno de hace una semana se activan múltiples pistas temporales y contextuales (semana, día, hora, actividades posteriores) que compiten entre sí y dificultan la selección de la clave adecuada, generando un bloqueo de recuperación; la interferencia constructiva implicaría que la nueva información reforzara la memoria, lo cual no ocurre aquí, mientras que la interferencia por usar partes de un conjunto como clave se refiere a la inhibición de subconjuntos dentro de un conjunto más amplio, no a la competencia entre claves temporales, y el olvido es un término genérico que no especifica la causa de la interferencia.'),
  (620, 'La derivación de pacientes desde instituciones públicas a privadas constituye una actuación de riesgo para la mala praxis porque implica un conflicto de intereses y la posible violación del principio de justicia y equidad en el acceso a la atención, además de generar una relación de dependencia que puede comprometer la continuidad y calidad del tratamiento; la práctica de realizar anotaciones subjetivas en la historia clínica, aunque no es la más idónea, no constituye por sí sola un riesgo de mala praxis, pues la subjetividad puede complementarse con datos objetivos y no impide la toma de decisiones clínicas; la solicitud de consentimiento informado a pacientes con trastorno mental grave estabilizados clínicamente es una obligación ética y legal que protege la autonomía del paciente y no representa un riesgo; y la revelación de información clínica a petición de una instancia judicial, siempre que se respete la confidencialidad y se cumplan los requisitos legales, también es una actuación aceptable y no constituye un riesgo de mala praxis.'),
  (621, 'La opción C es la que se ajusta a la definición normativa de relaciones duales en psicoterapia, pues la literatura ética reconoce que dichas relaciones pueden surgir simultáneamente con la intervención o bien después de haber concluido el proceso terapéutico, siempre que exista un vínculo que altere la objetividad profesional; la presencia de una relación dual no está condicionada a un momento específico del tratamiento. En contraste, la alternativa A es incorrecta porque la existencia de una relación dual implica precisamente la pérdida de límites profesionales, no su mantenimiento rígido. La opción B se basa en un supuesto de consenso que no existe; la literatura no establece que los negocios con pacientes sean la variante más inapropiada, pues la gravedad depende del contexto y del impacto en la relación terapéutica. Finalmente, la alternativa D es errónea porque la definición de relación dual incluye explícitamente las relaciones sexuales, por lo que no se excluye de la categoría.'),
  (622, 'El riesgo que se plantea es el de la justicia o equidad, ya que ambas pacientes comparten la misma patología y nivel de sintomatología ansioso‑depresiva, pero la primera recibe una derivación inmediata al servicio de psicología del hospital, mientras que la segunda debe buscar ayuda en el ámbito privado o en una ONG, lo que implica diferencias en accesibilidad, costo y calidad del tratamiento; este desequilibrio viola el principio de justicia, que exige un trato igualitario y proporcional a las necesidades clínicas. El principio de beneficencia no se ve comprometido directamente, pues ambas opciones buscan beneficiar a las pacientes; el principio de solidaridad no se aplica a la relación paciente‑profesional; y el principio de igualdad, aunque relacionado, se refiere a la igualdad de oportunidades de acceso a la atención, no a la distribución equitativa de recursos, por lo que la opción A es la que mejor describe la violación.'),
  (623, 'El fenómeno descrito corresponde a la Ley de cuidados inversos, la cual establece que los recursos sanitarios tienden a concentrarse en los grupos con menor necesidad y mayor capacidad de acceso, dejando de lado a los más vulnerables; esta denominación se fundamenta en la evidencia de que la demanda de servicios se ve influida por factores socioeconómicos y de poder, generando una inversión de la distribución de la atención. Las demás opciones son incorrectas: la opción A se refiere a un concepto inexistente en la literatura de salud pública; la C y D, aunque evocan la desigualdad, no capturan la especificidad del patrón de inversión de recursos que caracteriza la Ley de cuidados inversos.'),
  (624, 'La técnica de escucha activa que permite comprender los objetivos del tratamiento y modificar la interpretación de la conducta de otro, de modo que la respuesta cambie, es el **encuadre**; mediante la reestructuración de la relación terapéutica y la definición de límites y roles, el paciente revalora la situación y adopta una nueva perspectiva funcional. Las demás opciones no cumplen este objetivo: la indagación o sondeo se centra en obtener información sin alterar la interpretación; la confrontación, aunque puede provocar un cambio, se dirige a la corrección de conductas específicas y no a la reconfiguración del marco interpretativo; las instrucciones son directivas que orientan conductas concretas pero no modifican la forma de interpretar la situación.'),
  (625, 'El Inventario de Trastornos de la Conducta Alimentaria EDI‑3 se construyó con la finalidad de evaluar la gravedad y la presencia de síntomas de los principales trastornos alimentarios en adultos, por lo que su aplicación se limita a personas mayores de 16 años, pero no se restringe a la población clínica; su diseño contempla la detección de riesgo en la población general, lo que lo hace útil tanto en contextos clínicos como de investigación. La versión EDI‑3 incluye tres escalas de riesgo específicas: “Obsesión por la delgadez”, “Bulimia” e “Insatisfacción corporal”, que miden la probabilidad de desarrollar cada uno de estos trastornos; estas escalas se basan en la teoría de la disfunción cognitiva y la motivación para la pérdida de peso, y se han validado en estudios con muestras clínicas y de la comunidad. Por tanto, la opción C es la que refleja correctamente la estructura de riesgo del instrumento. Las demás alternativas resultan incorrectas porque la EDI‑3 no está restringida a mayores de 16 años (la opción A), sus autores son Fairburn, Cooper y Taylor (la opción B) y la herramienta no se limita exclusivamente a la población clínica (la opción D).'),
  (626, 'El módulo 3 de la ADOS‑2 está diseñado para niños y adolescentes con lenguaje fluido que todavía utilizan juguetes como medio de juego, pues permite evaluar la interacción social y la comunicación mediante actividades lúdicas que reflejan su nivel de desarrollo; el módulo 1 se reserva para individuos con lenguaje muy limitado o sin habla, el módulo 2 se aplica a personas con lenguaje funcional pero que ya no usan juguetes como principal medio de juego, y el módulo T se emplea para adultos con lenguaje funcional, por lo que las otras opciones no corresponden al perfil descrito.'),
  (627, 'La DIB‑R, diseñada por Zanarini y colaboradores, contempla las dimensiones de impulsividad, afecto, relaciones interpersonales y síntomas de disfunción cognitiva, por lo que la opción que no corresponde es la de inestabilidad; la inestabilidad se contempla dentro de la dimensión de afecto, pero no constituye una escala independiente. Las demás opciones sí son escalas centrales de la entrevista: la impulsividad evalúa conductas desinhibidas, el afecto mide la intensidad y la variabilidad emocional, y las relaciones interpersonales abordan el patrón de vínculos y la percepción de los demás. Por tanto, la alternativa A es la única que no forma parte de las cuatro áreas generales de la DIB‑R.'),
  (628, 'La opción B es la única que se sostiene clínicamente: el registro gráfico de la intensidad de los síntomas a lo largo de un periodo prolongado, mediante diarios o escalas de auto‑observación, permite al paciente visualizar patrones de fluctuación y reconocer la presencia de episodios, lo que favorece la insight y la adherencia al tratamiento; además, el gráfico vital se utiliza como herramienta de feedback en la terapia cognitivo‑conductual para la gestión de la enfermedad. En contraste, la YMRS (opción A) está diseñada para evaluar la manía severa y no es adecuada para el TB tipo II, donde la hipomanía es más leve y la escala puede subestimar la gravedad; la HCL‑32 (opción C) se emplea principalmente para detectar hipomanía y, por tanto, es más útil en TB tipo II que en tipo I, donde la manía suele ser más marcada; y la afirmación de que el diagnóstico de fases maníacas es sencillo (opción D) es errónea, pues muchos pacientes no reconocen sus síntomas como patológicos o los minimizan, dificultando la identificación temprana de la fase.'),
  (629, 'La puntuación directa de 0 en una escala del WAIS‑IV indica que el examinando no respondió correctamente a ninguno de los ítems de esa escala, lo que implica que la aptitud específica evaluada por esa escala no puede determinarse a partir de los datos obtenidos; por tanto, la información sobre la capacidad del sujeto en esa dimensión queda indeterminada, aunque el CI total y los índices compuestos pueden seguir calculándose a partir de las otras escalas. Las demás opciones son erróneas porque la escala permite valores de 0 (no 1‑19), la ausencia de puntuación en Vocabulario no impide el cálculo del Índice de Comprensión Verbal (se puede usar la escala de Síntesis de Conceptos), y no existe obligación de sustituir el CI total por el Índice de Capacidad General cuando una escala presenta 0.'),
  (630, 'El test del reloj es la única prueba de la lista que evalúa las praxias constructivas, ya que exige al paciente dibujar un reloj con una hora específica, lo que implica planificación, coordinación visuomotora y percepción espacial; además, la imposibilidad de ubicar correctamente los números o la hora suele indicar heminegligencia, pues la persona tiende a omitir la mitad del espacio, lo que se refleja en la distribución de los números y la posición de las manecillas, algo que el test del reloj permite observar de forma directa y cuantificable. El token test se centra en la comprensión y producción de lenguaje y la ejecución de órdenes, no en la construcción espacial; el RBMT está orientado a la memoria episódica y la atención auditiva, sin requerir tareas constructivas; y el PASAT mide la velocidad de procesamiento y la atención sostenida mediante sumas auditivas, sin involucrar la construcción de figuras ni la detección de déficit hemisféricos. Todas las alternativas excepto la A carecen de la dimensión constructiva necesaria para valorar praxias y heminegligencia.'),
  (631, 'El Cuestionario de Evaluación del Estilo Personal del Terapeuta (EPT‑C) se ha sometido a una extensa investigación psicométrica que culminó en una validación en España, donde la estructura factorial resultó pentafactorial y se compone de 20 ítems, lo que garantiza la cobertura de los cinco dominios teóricos (autenticidad, empatía, autonomía, flexibilidad y orientación al proceso) y la adecuación al contexto cultural español; esta es la única opción que refleja fielmente la evidencia publicada sobre la versión española del instrumento. La alternativa A es incorrecta porque, aunque el EPT‑C tiene una trayectoria de investigación, no cuenta con una validación y estandarización en inglés; la opción B falla al afirmar que las validaciones se limitan a Latinoamérica, cuando la versión española es la que se ha publicado; y la opción C es errónea al suponer que todas las validaciones convergen en una solución pentafactorial universal, cuando la estructura puede variar según el idioma y la cultura, y la versión española es la única que presenta la solución pentafactorial de 20 ítems.'),
  (632, 'Los catálogos son instrumentos de registro de conductas que se caracterizan por ser listas abiertas y flexibles, diseñadas para adaptarse a la diversidad de situaciones observadas en el campo; su estructura no impone límites rígidos a la cantidad de ítems, lo que permite que el observador añada nuevas conductas conforme se identifiquen, lo que los hace idóneos para la construcción de formatos de campo que requieren sensibilidad y adaptabilidad a contextos específicos, mientras que los repertorios, al ser listas cerradas y exhaustivas, están pensados para evaluaciones estructuradas y comparativas, y las matrices de interacción se emplean para analizar la relación entre pares de conductas, no para la creación de formatos de campo. Las opciones A y B describen características que no se corresponden con la definición de catálogos: la exclusión mutua y la clasificación en catálogos, repertorios y matrices no refleja la realidad de los instrumentos de registro; la opción D atribuye a los repertorios una garantía de exhaustividad que no es inherente a los catálogos, pues estos son deliberadamente abiertos y no exhaustivos.'),
  (633, 'La opción B es falsa porque la ADNM se centra en los eventos estresantes ocurridos en el periodo inmediato previo al episodio, típicamente los últimos 12 meses, no en los tres años anteriores; la escala está diseñada para capturar la relación temporal estrecha entre el evento y la aparición de síntomas de adaptación, tal cual lo estipula la CIE‑11, mientras que la respuesta A describe correctamente los dos formatos disponibles (entrevista clínica estructurada y cuestionario de autoinforme), la C describe adecuadamente los síntomas centrales y asociados que la ADNM evalúa (depresión, ansiedad, evitación, control de impulsos) y la D señala el componente de deterioro funcional, que es una dimensión esencial de la escala.'),
  (634, 'El instrumento que no es un autoinforme es el Psychotic Symptom Rating Scale (PSY‑RATS); se trata de una escala de evaluación clínica que el profesional completa a partir de la entrevista estructurada con el paciente, recabando información sobre la frecuencia, intensidad y contenido de las alucinaciones, sin que el propio paciente rellene el cuestionario. Las demás opciones son autoinformes: la Launay‑Slade Hallucination Scale‑revised (LSHS‑R) se administra directamente al paciente para valorar la frecuencia y el contenido de las alucinaciones; la Voice Power Differential Scale (VPDS) recoge la percepción subjetiva del poder y la influencia de las voces; y el Beliefs About Voices Questionnaire (BAVQ‑R) evalúa las creencias y actitudes que el paciente mantiene respecto a sus voces. Todas las alternativas B, C y D, por lo tanto, se completan con la respuesta del propio individuo, a diferencia de la PSY‑RATS, que se basa en la observación clínica.'),
  (635, 'La opción C es la que corresponde a la formulación del caso en la terapia cognitiva según Clark y Beck (2012), porque la literatura de la terapia cognitiva enfatiza que la eficacia del tratamiento depende de una conceptualización completa y coherente del caso; cuando la hipótesis conceptualizada no abarca adecuadamente los factores cognitivos, emocionales y conductuales que mantienen el trastorno, el tratamiento tiende a fallar, especialmente en casos complejos. En contraste, la opción A menciona la individualización y la generación de hipótesis, pero se enfoca en el modelo de Persons, que es un enfoque de terapia de aceptación y compromiso (ACT) y no en la terapia cognitiva; la opción B introduce la idea de transdiagnóstico y teoría, lo cual no es característico de la formulación de Clark y Beck, que se centra en la especificidad del caso; y la opción D afirma que la formulación debe dirigirse sin influencias teóricas, lo cual es incorrecto porque la terapia cognitiva se basa explícitamente en un marco teórico para guiar la conceptualización y la intervención.'),
  (636, 'La técnica de inmediatez, al centrarse en el momento presente y en la experiencia inmediata del entrevistado, facilita la autoexploración porque el clínico refleja de forma breve y concreta lo que percibe, invitando al paciente a profundizar en sus propias sensaciones y pensamientos sin que el profesional intervenga con interpretaciones o juicios; esta dinámica suele replicar la relación que el paciente mantiene con el clínico, pues ambos comparten la misma temporalidad y foco en la experiencia actual. En cambio, la interpretación (A) implica una interpretación externa que puede limitar la autoexploración al imponer una interpretación; la autorrevelación (C) se orienta a que el clínico comparta información personal, lo que no favorece la autoexploración del paciente; y la afirmación de la capacidad (D) se centra en reforzar la confianza del entrevistado, pero no se dirige específicamente a la autoexploración en el contexto de una relación transicional.'),
  (637, 'El instrumento que evalúa la percepción social en niños es la Batería Neuropsicológica Infantil, NEPSY‑II, ya que incluye subtests específicos como la “Prueba de Percepción Social” y “Reconocimiento de Emociones”, diseñados para medir la capacidad de interpretar gestos, expresiones faciales y normas sociales en la infancia, aspectos que no se abordan en la escala de aptitudes intelectuales (BAS‑II), la batería de Luria (DNI) centrada en funciones ejecutivas y la escala de inteligencia no verbal Leiter‑R, que se limita a la capacidad de razonamiento no verbal sin componentes sociales.'),
  (638, 'La opción d) es la única que se ajusta a la interpretación clínica de la WISC‑V: una discrepancia significativa entre el Índice de Competencia Cognitiva (ICC) y el Índice de Capacidad Cognitiva (ICC) suele indicar dificultades atencionales, pues el ICC (que incluye la velocidad de procesamiento y la memoria de trabajo) se ve afectado por la falta de atención, mientras que el ICC (comprensión verbal y razonamiento perceptivo) permanece relativamente intacto; las demás alternativas son incorrectas: la A) confunde el número de subescalas (la WISC‑V tiene 10 subpruebas, pero el CI total se calcula a partir de los índices y no de las puntuaciones escalares individuales); la B) asume que una diferencia entre comprensión verbal y memoria de trabajo confirma un TDA, cuando en realidad la discrepancia debe evaluarse en conjunto con otras pruebas y criterios clínicos; y la C) interpreta erróneamente la escala de CI total, pues un CI por debajo de 70 indica una discapacidad intelectual, pero la WISC‑V no la utiliza como criterio diagnóstico definitivo, sino como indicador de necesidad de evaluación adicional.'),
  (639, 'El Test del Dibujo de Dos Figuras Humanas (T2F) se emplea específicamente para evaluar la madurez psicológica de niños y adolescentes, ya que el número y la complejidad de las figuras dibujadas correlacionan con el nivel de desarrollo cognitivo y emocional; su aplicación clínica está respaldada por estudios que vinculan la producción de figuras con la etapa de madurez de la persona, lo que lo convierte en la herramienta idónea para medir la madurez del menor. El The Story Stem Assessment Profile (SSAP) se centra en la exploración de la representación narrativa y la dinámica familiar, no en la madurez; la Children’s Global Assessment Scale (CGAS) es una escala de gravedad funcional que evalúa el nivel de funcionamiento general, pero no mide la madurez; y el Cuestionario de Fortalezas y Dificultades (SDQ) es un instrumento de detección de trastornos emocionales y conductuales, sin referencia a la madurez psicológica.'),
  (640, 'El factor que debe evaluarse de manera específica en el trastorno obsesivo‑compulsivo infantil y adolescente es la acomodación familiar, pues la dinámica de la familia –especialmente la tendencia a reforzar o facilitar las compulsiones mediante la participación o la complacencia de los miembros— constituye un componente central del mantenimiento del trastorno y es fundamental para la planificación de la intervención; las otras opciones, aunque relevantes en la evaluación global, no son distintivas del TOC: los antecedentes de tratamiento de los padres (B) se refieren a la historia clínica familiar, no a la interacción directa con el niño; el nivel de rendimiento académico (C) y las dificultades sociales (D) pueden ser consecuencias o comorbilidades, pero no son factores de riesgo o mantenimiento específicos del TOC en esta población.'),
  (641, 'El instrumento que se emplea específicamente para identificar y cuantificar los síntomas prodromales que indican un riesgo elevado de desarrollar psicosis es el SIPS (Structured Interview for Prodromal Syndromes); su diseño permite evaluar la aparición y evolución de síntomas como ideas delirantes, pensamiento desorganizado, y alteraciones perceptivas, y su puntuación se correlaciona con la probabilidad de conversión a trastorno psicótico, lo que lo convierte en la herramienta de referencia en estudios de riesgo de psicosis. El PANSS, aunque mide la gravedad de los síntomas en pacientes con esquizofrenia, no está orientado a la fase prodromal ni a la detección temprana de riesgo. El K‑SADS‑PL se centra en el diagnóstico de trastornos del espectro afectivo y de conducta en población pediátrica y no está diseñado para evaluar síntomas prodromales psicóticos. La BSABS se centra en síntomas básicos, pero su uso principal es en la evaluación clínica de pacientes con esquizofrenia, no en la identificación de riesgo precoz; por lo tanto, las opciones A, C y D no cumplen la función específica de evaluar estados de alto riesgo de psicosis.'),
  (642, 'El Índice Verbal del BAS‑II se construye a partir de la combinación de la prueba de Comprensión Verbal y la de Nominación, pues ambas evalúan la capacidad de acceder, organizar y expresar el vocabulario y el conocimiento semántico, aspectos centrales de la aptitud verbal; la Comprensión Verbal mide la comprensión de textos y la interpretación de información verbal, mientras que la Nominación evalúa la rapidez y precisión en la producción de palabras, lo que permite estimar el nivel de inteligencia verbal. Las demás opciones son incorrectas: la alternativa A (Copia y Cubos) corresponde a la evaluación de la percepción visual‑espacial y la coordinación motora, no a la verbal; la opción C (Conceptos numéricos y Comprensión verbal) mezcla una prueba de razonamiento numérico con una prueba verbal, lo que no refleja el índice verbal; y la alternativa D (Semejanzas y Fluidez verbal) se relaciona con el Índice de Fluidez, que mide la rapidez de generación de palabras, distinto del Índice Verbal.'),
  (643, 'La pérdida o regresión de habilidades comunicativas, como la desaparición de palabras, gestos o la incapacidad de responder a su nombre, constituye la señal más precoz y específica de alerta para el trastorno del espectro autista (TEA) entre los 12 y 18 meses, pues la adquisición del lenguaje es un indicador crítico de desarrollo social y cognitivo y su deterioro suele preceder a otras manifestaciones; la inversión pronominal (A) es típica de trastornos del lenguaje más que de TEA, la dificultad para comprender normas sociales (C) y los dobles sentidos (D) suelen aparecer más tarde y no son tan sensibles ni tan frecuentes en la primera infancia, por lo que se consideran menos indicativas en esta etapa.'),
  (644, 'El Inventario de Evaluación de la Personalidad para Adolescentes (PAI‑A) incluye, entre sus escalas de tratamiento, cinco consideraciones específicas: agresión, ideaciones suicidas, estrés, falta de apoyo social y rechazo al tratamiento; estas escalas se emplean para identificar riesgos inmediatos y planificar intervenciones dirigidas a la reducción de conductas peligrosas y la mejora de la adherencia terapéutica, lo que la diferencia de otras versiones del PAI que no distinguen explícitamente estos dominios. En consecuencia, la opción B es la única que refleja fielmente la estructura de tratamiento del PAI‑A. La alternativa A es errónea porque el autor del PAI‑A no es Butcher, sino que el inventario fue desarrollado por otros autores; la opción C es incorrecta al limitar la edad a 14‑18 años, cuando el instrumento abarca adolescentes de 12 a 18 años; y la opción D es falsa porque el PAI‑A no dispone de escalas de Dominancia y Extraversión, esas pertenecen a la escala de Relaciones Interpersonales del PAI‑Adulto.'),
  (645, 'La STIPO‑R se centra en la evaluación de la organización de la personalidad a través de cinco dominios: identidad, afectividad, control de impulsos, relaciones interpersonales y valores morales; por ello la dimensión de inestabilidad afectiva, que corresponde a la fluctuación emocional típica de trastornos de la personalidad, no forma parte de su estructura, mientras que la identidad, la agresión (como manifestación de control de impulsos) y los valores morales sí son contenidos que el cuestionario mide; las opciones B, C y D se corresponden con los ámbitos que la escala contempla, mientras que la alternativa A se aparta del marco teórico de la STIPO‑R.'),
  (646, 'La CGAS evalúa el funcionamiento global del niño en una escala de 1 a 100, donde valores más altos indican mejor adaptación y valores más bajos reflejan deterioro significativo; un rango de 31‑40 corresponde a un deterioro importante en varias áreas funcionales, pues indica dificultades marcadas en el rendimiento académico, social y familiar, con síntomas que limitan la autonomía y la interacción, lo que coincide con la descripción de un deterioro importante; las opciones A y B (81‑90 y 61‑70) describen niveles de funcionamiento normal a ligeramente deteriorado, mientras que la opción D (11‑20) indica un deterioro severo o crítico, por lo que no corresponde al nivel de deterioro “importante” pero no severo que se plantea.'),
  (647, 'El egocentrismo intelectual en el periodo preoperatorio, según Piaget, se caracteriza por la incapacidad de comprender que otras personas pueden tener perspectivas distintas a la propia; se manifiesta en el finalismo (la tendencia a ver los objetos como si tuvieran un fin inherente), el realismo (la creencia de que la realidad es estática y no cambia con la observación) y el animismo (atribuir cualidades animadas a objetos inanimados). La conservación, en cambio, es la habilidad que se desarrolla en la etapa operativa y permite reconocer que la cantidad de una sustancia permanece constante a pesar de cambios en su forma; por lo tanto, no forma parte de las manifestaciones egocéntricas preoperatorias. Las otras opciones (A, B y D) describen precisamente los patrones de pensamiento típicos de esta etapa, mientras que la opción C se refiere a una competencia cognitiva que aparece más adelante, lo que explica por qué no se incluye entre las principales manifestaciones del egocentrismo intelectual preoperatorio.'),
  (648, 'La resolución de la tarea de la “Falsa Creencia” –es decir, la capacidad de comprender que una persona puede mantener una creencia falsa sobre el estado de las cosas– suele consolidarse de manera fiable entre los 4 y 5 años, cuando el desarrollo de la teoría de la mente alcanza un nivel funcional que permite a los niños inferir intenciones y estados mentales ajenos; este hito se documenta en estudios longitudinales de la infancia que muestran un incremento brusco en la precisión de las respuestas a la tarea a partir de esa edad, coincidiendo con la maduración de la corteza prefrontal y la mejora de la memoria de trabajo. Las opciones B y C son erróneas porque los niños de 2‑3 años todavía presentan la fase de “falsa creencia de baja complejidad”, donde solo pueden prever la ubicación de objetos, y los de 6‑7 años ya han superado el hito, por lo que la tarea ya no es un indicador de desarrollo; la alternativa D es incorrecta porque la mayoría de los niños ya han resuelto la tarea antes de los 10 años, y la resolución a esa edad no implica un nuevo desarrollo sino la consolidación de la habilidad.'),
  (649, 'La opción A describe la función de adaptación de Piaget porque la adaptación se compone de los procesos de asimilación y acomodación, donde la asimilación implica integrar la nueva información en las estructuras cognitivas existentes y la acomodación implica modificar esas estructuras para incorporar la nueva información; la frase de la A resume la asimilación, el mecanismo primario de adaptación, sin perder la referencia a la base de conocimientos previos, lo cual es esencial según la teoría de Piaget. La B, aunque menciona la incorporación de nueva información, se enfoca únicamente en la recepción y no distingue entre asimilación y acomodación, por lo que no refleja la dualidad de la adaptación. La C se centra exclusivamente en la acomodación, omitiendo la asimilación que también es parte de la adaptación. La D describe más bien la función de la adaptación en la regulación del comportamiento en situaciones particulares, pero no explica los mecanismos cognitivos subyacentes que Piaget identifica.'),
  (650, 'La opción B corresponde a la teoría sociobiológica, la cual sostiene que los seres humanos disponen de mecanismos de adaptación innatos que, al interactuar con el entorno, configuran el comportamiento; estos mecanismos son el resultado de la evolución y están diseñados para maximizar la supervivencia y la reproducción, por lo que la interacción entre predisposición biológica y contexto ambiental determina las conductas observables. Las demás alternativas son incorrectas porque la opción A se refiere a teorías cognitivas que enfatizan procesos mentales internos, la C alude a teorías contextuales que ponen el foco en el entorno sin considerar mecanismos innatos de adaptación, y la D describe la teoría del aprendizaje, centrada en la adquisición de conductas mediante la experiencia y la retroalimentación, sin abordar la base biológica de la adaptación.'),
  (651, 'Durante el período sensoriomotor (del nacimiento a los 2 años), el desarrollo cognitivo se centra en la construcción de la permanencia del objeto y la adquisición de representaciones mentales básicas, lo que permite la formación de la noción de número como una capacidad de contar objetos y reconocer cantidades; esta habilidad se manifiesta en la capacidad de distinguir y agrupar objetos en series, una función que emerge en la etapa sensoriomotor. La correlación (B) implica la identificación de relaciones entre variables y se desarrolla más adelante, en la etapa preoperacional, cuando el niño empieza a comprender la causa y la relación entre eventos. La inferencia (C) requiere la capacidad de deducir conclusiones a partir de información previa, una función que aparece en la etapa de operaciones concretas y superiores, cuando el individuo ya posee un razonamiento lógico más complejo. El descentramiento (D), entendido como la capacidad de separar la atención de una sola característica de un objeto para procesar otras, se consolida en la etapa de operaciones concretas, cuando el niño aprende a pensar en múltiples dimensiones simultáneamente. Por tanto, solo la noción de número se desarrolla en el período sensoriomotor, mientras que las demás opciones corresponden a etapas cognitivas posteriores.'),
  (652, 'La opción C corresponde a la teoría de los esquemas de género, la cual sostiene que los niños construyen y organizan la información sobre lo que se considera apropiado para cada género a partir de las normas y expectativas culturales que internalizan, y se autocategorizan mediante el procesamiento de estos esquemas; la teoría del desarrollo cognoscitivo (A) se centra en la evolución de las funciones cognitivas sin referirse específicamente a la internalización de roles de género; la teoría psicosexual (B) se basa en etapas de desarrollo psico‑sexual y no en la organización de la información cultural; la teoría cognoscitiva social (D) aborda la influencia de la observación y el aprendizaje social en la conducta, pero no explica la internalización de esquemas de género como la teoría de los esquemas de género.'),
  (653, 'La teoría de la ampliación‑construcción de las emociones positivas de Fredrickson sostiene que las emociones positivas, como la alegría, el interés o el amor, amplían el repertorio de pensamientos y comportamientos disponibles, fomentando la exploración y la creatividad; a la vez, construyen recursos psicológicos a largo plazo que favorecen la adaptación y la supervivencia, por lo que la opción B refleja fielmente este mecanismo de expansión y fortalecimiento de la resiliencia. Las demás alternativas se desvían de esta propuesta: la A y la C invierten la relación entre emociones positivas y flexibilidad cognitiva, atribuyéndoles efectos negativos que la teoría niega; la D confunde el foco atencional, pues las emociones positivas no reducen la atención ni la concentran en una única respuesta, sino que la dispersan y la enriquecen.'),
  (654, 'En los estudios longitudinales con el CPI se ha documentado que la edad se asocia con un incremento en los rasgos de autocontrol, responsabilidad y cooperación, reflejando la consolidación de la autorregulación y la internalización de normas sociales a lo largo del desarrollo; estos cambios se interpretan como la progresiva maduración de la función ejecutiva y la adopción de roles más estructurados, lo que explica por qué la opción A es la que mejor describe la tendencia observada. Las demás alternativas se desvían de los hallazgos empíricos: la afabilidad y el tesón (opción B) suelen mantenerse estables o incluso incrementarse con la edad, no disminuir; la vitalidad social y la dominancia social (opción C) muestran patrones de estabilidad o ligera variación, sin un aumento de la vitalidad social acompañado de una caída de la dominancia; y la estabilidad emocional (opción D) se mantiene relativamente constante después de la adultez temprana, sin una caída drástica, por lo que las tres opciones restantes son incorrectas.'),
  (655, 'La propuesta de Mischel y Shoda se basa en la idea de que la conducta es el resultado de la interacción entre la situación y los factores internos, y que esta interacción se puede describir mediante una regla de tipo “si‑entonces” que especifica la conducta esperada cuando la situación cumple una condición particular; por eso la opción D, “Si A, entonces X”, refleja fielmente el esquema de sus reglas de contingencia, que expresan la conducta como una respuesta a una situación específica. Las demás alternativas no corresponden a este formato: la A (“Si es A, puede ser X”) introduce una posibilidad sin una relación causal clara; la B (“Evaluar A, actuar X”) sugiere un proceso de evaluación que no es parte de la regla de contingencia propuesta; y la C (“Debería A, no debería X”) implica un juicio normativo que no caracteriza la descripción de Mischel y Shoda, que se centra en la predictibilidad de la conducta bajo condiciones concretas.'),
  (656, 'El Análisis Factorial Confirmatorio (AFC) se consolidó como herramienta de mayor potencia explicativa en psicología diferencial gracias al trabajo de Jöreskog y Sörbom, quienes introdujeron el modelo de ecuaciones estructurales y la estimación de parámetros mediante máxima verosimilitud, permitiendo la prueba de hipótesis sobre la estructura factorial especificada y la evaluación de la bondad de ajuste; su enfoque estadístico avanzado supera a las técnicas anteriores (por ejemplo, el análisis factorial exploratorio) al permitir la confirmación de modelos teóricos y la comparación de alternativas. Las opciones B, C y D son incorrectas: Kaiser y Carroll propusieron la regla de Kaiser y la teoría de la carga de factores, pero no desarrollaron el AFC; Nesselroade y Cattell son pioneros en la teoría de la inteligencia y la medición, pero su trabajo se centró en el análisis factorial exploratorio y la teoría de la carga de factores, no en el AFC; Kline y Tyler son reconocidos por sus contribuciones a la interpretación de modelos de ecuaciones estructurales y la teoría de la validez, pero no por el desarrollo del AFC.'),
  (657, 'La fuente de datos que Cattell designó como “Datos L o Life” corresponde a la información derivada de descripciones u observaciones externas al propio individuo, es decir, datos obtenidos a partir de la vida real y de la conducta observada en contextos naturales; esta categoría se distingue de los datos “D o Dictionary” que se basan en definiciones léxicas, de los “Q o Questionnaire” que provienen de autoinformes estructurados y de los “T o Test” que se recogen mediante instrumentos psicométricos estandarizados, por lo que la opción A es la única que refleja la tradición de Allport y Odbert de usar la descripción externa como fuente primaria de información. Las demás alternativas son incorrectas porque cada una corresponde a un tipo distinto de fuente de datos: la B a la léxica, la C a la autoinformada y la D a la psicométrica.'),
  (658, 'La opción B es la que concuerda con la concepción de Sternberg de la inteligencia creativa, entendida como la capacidad de generar ideas novedosas y útiles mediante la combinación de conocimientos y la aplicación de estrategias originales; por tanto, los individuos con alta inteligencia creativa se distinguen por su habilidad para crear y descubrir, lo cual se refleja en la formulación de la respuesta. En cambio, la alternativa A describe la inteligencia analítica, que se centra en la resolución de problemas mediante el análisis lógico y la aplicación de reglas, no en la adaptación del entorno; la opción C atribuye a la inteligencia práctica la gestión de componentes internos, cuando en realidad la práctica se refiere al manejo eficaz de situaciones cotidianas y la aplicación de conocimientos en contextos reales; y la D menciona una inteligencia naturalista, la cual no forma parte de la teoría triárquica de Sternberg, por lo que su inclusión es incorrecta.'),
  (659, 'La opción C es la que refleja fielmente la clasificación de Binet y Simon (1916), quienes definieron la inteligencia en tres funciones esenciales: la dirección (capacidad de orientar la actividad mental hacia un objetivo), la adaptación (habilidad de ajustar el comportamiento a nuevas exigencias) y el control (regulación de los procesos mentales para mantener la coherencia interna); estas tres dimensiones constituyen la base de su modelo de inteligencia como un conjunto de procesos dinámicos que permiten la resolución de problemas y la adaptación al entorno. Las demás alternativas fallan porque sustituyen la “dirección” por “habilidad” o “capacidad”, conceptos que Binet y Simon no emplearon como categoría funcional; además, la opción A introduce “habilidad” en lugar de “dirección”, mientras que la B intercambia “capacidad” por “dirección”, y la D combina “dirección” con “habilidad”, lo que distorsiona la tripartición original del autor.'),
  (660, 'La opción C es la única que refleja la evidencia empírica sobre la influencia de la cultura en la atención selectiva de la información; en sociedades colectivistas la autocrítica y la atención a los atributos negativos se consideran mecanismos de regulación social y de mantenimiento de la armonía grupal, por lo que los individuos tienden a enfocarse en los aspectos críticos de su desempeño para ajustarse a las normas colectivas, mientras que en culturas individualistas la atención se dirige más a la autoeficacia y la valoración de los logros. Las demás alternativas fallan porque la afirmación A presupone que la motivación de aproximación es mayor en colectivistas, lo cual contrasta con la literatura que indica mayor énfasis en la evitación de la pérdida; la B sugiere que los individualistas se orientan a evitar el fracaso, pero la investigación muestra que tienden a centrarse en la maximización de logros y la autoeficacia; y la D confunde la tendencia de los colectivistas a adoptar atribuciones defensivas con la preservación de la autoestima, cuando en realidad la autocrítica y la atención a los errores son más comunes que la defensa.'),
  (661, 'La motivación descrita corresponde a una regulación introyectada, ya que la persona internaliza la presión de los padres y actúa para evitar la culpa y el disgusto que estos podrían sentir, sin haber incorporado el valor de estudiar como propio; la internalización se produce a través de la identificación con la expectativa externa, pero sin haberla aceptado voluntariamente, lo que caracteriza la regulación introyectada. La opción A describe una regulación externa, donde la conducta se mantiene únicamente por recompensas o castigos externos, y no implica internalización; la opción C, la regulación identificada, implica que el individuo valora la actividad y la integra en su sentido de identidad, lo cual no es el caso cuando la motivación se basa en evitar la culpa; la opción D, la regulación integrada, corresponde a la internalización más profunda, donde la conducta se realiza por su propio valor intrínseco, también distinta de la motivación basada en la culpa.'),
  (662, 'La paradoja de Easterlin se explica porque, una vez satisfechas las necesidades básicas, la percepción de bienestar subjetivo se vuelve más dependiente del estatus económico relativo que de la riqueza absoluta; el incremento de ingresos ya no genera mayor satisfacción porque el individuo compara su posición con la de los demás, y la referencia social domina la valoración interna, lo que reduce la relación positiva entre ingresos y bienestar. Las demás opciones son incorrectas: la A presupone un efecto incremental de cada dólar, contradiciendo la evidencia de un efecto decreciente; la B afirma una relación lineal, cuando la evidencia muestra una relación no lineal o casi nula en niveles altos de ingreso; y la C sugiere que la correlación es mayor en países desarrollados, lo cual no explica la paradoja observada a nivel individual.'),
  (663, 'La subescala de planificación estratégica del Cuestionario de Afrontamiento Proactivo mide la capacidad de organizar y priorizar tareas, dividiéndolas en componentes manejables, lo que facilita la ejecución eficiente de las metas; por ello la opción B describe con precisión el contenido de la subescala, pues refleja la habilidad de establecer prioridades y descomponer tareas en unidades más asequibles, una característica esencial de la planificación estratégica. Las demás opciones son incorrectas: la A se refiere a la fijación de objetivos y conductas orientadas a ellos, más alineada con la subescala de fijación de metas; la C describe la generación de planes alternativos, típica de la subescala de flexibilidad cognitiva; y la D se relaciona con la previsión de estresores, correspondiente a la subescala de anticipación de amenazas.'),
  (664, 'El factor de orden superior que no corresponde al Modelo Dimensional de W. J. Livesley es la extraversión, pues en su esquema los tres factores de orden superior son: desregulación emocional, comportamiento antisocial y compulsividad, cada uno abarcando un conjunto de trastornos de la personalidad que comparten un núcleo común; la extraversión, por el contrario, es un rasgo de personalidad de nivel inferior que se asocia con trastornos de la personalidad como el trastorno narcisista o el trastorno de la personalidad antisocial, pero no constituye un factor de orden superior en dicho modelo. Las otras opciones sí se alinean con los factores de orden superior del modelo: la desregulación emocional incluye trastornos como el trastorno límite de la personalidad; el comportamiento antisocial comprende el trastorno antisocial de la personalidad y el trastorno de la personalidad antisocial; y la compulsividad agrupa el trastorno obsesivo‑compulsivo de la personalidad y el trastorno de la personalidad dependiente, entre otros.'),
  (665, 'Los metaanálisis de Feingold (1994) integran resultados de numerosos estudios de personalidad y concluyen que las diferencias de género en los rasgos de personalidad son mínimas y, en la mayoría de los casos, no alcanzan la significación estadística; la única tendencia consistente es que las mujeres obtienen puntuaciones ligeramente superiores en la dimensión de organización (orden, rectitud, escrupulosidad), aunque el efecto es pequeño y no se considera clínicamente relevante. Esta conclusión se deriva de la combinación de estudios con tamaños de muestra variados y de la heterogeneidad metodológica, lo que reduce la potencia para detectar diferencias pequeñas; por ello la opción d) refleja fielmente el hallazgo de Feingold. Las opciones A, B y C se basan en supuestos de diferencias de género más marcadas (ansiedad, impulsividad, asertividad, confianza y sensibilidad) que no están respaldadas por la evidencia meta‑analítica, ya que los efectos reportados en esos rasgos son nulos o de tamaño trivial y no alcanzan significación estadística en el análisis global.'),
  (666, 'En la Teoría Componencial de la Inteligencia de Sternberg, la codificación de la naturaleza del estímulo, la inferencia de relaciones entre estímulos y la aplicación de inferencias previas a nuevas situaciones se ubican dentro de los procesos de ejecución, ya que implican la manipulación activa de la información percibida para generar respuestas concretas; estos procedimientos operan en tiempo real y requieren la integración de datos sensoriales con estrategias cognitivas previamente aprendidas, lo que los distingue claramente de los metacomponentes que supervisan y regulan el proceso, de los componentes de adquisición del conocimiento que se centran en la formación de nuevas representaciones y de los componentes de planificación global que se ocupan de la organización de estrategias a largo plazo.'),
  (667, 'Allport distingue entre estilos y controles cognitivos señalando que los primeros son rasgos de personalidad que guían la percepción y el procesamiento de la información de forma relativamente estable y general, sin depender mucho del contenido concreto de las tareas, mientras que los controles cognitivos son mecanismos más específicos y flexibles que regulan la atención y la memoria de acuerdo con la demanda situacional; por ello la opción B es la que refleja fielmente esta distinción, pues reconoce la mayor generalidad y menor variabilidad de los estilos frente a los controles. La alternativa A es incorrecta porque los estilos cognitivos no se describen como entidades psicodinámicas sino como rasgos de personalidad. La opción C es errónea porque los controles cognitivos no se presentan como bipolares, sino como procesos de regulación. La alternativa D confunde la función de los controles con la organización de dimensiones, pues los controles no consisten en la organización de etiquetas específicas dentro del individuo.'),
  (668, 'El enunciado describe la secuencia de desarrollo neurobiológico que se observa en la infancia y adolescencia: la mielinización ocurre de manera progresiva y jerárquica, con regiones como la corteza prefrontal madurando más tardíamente que las áreas sensoriomotoras, lo que explica la aparición de funciones ejecutivas y de autorregulación en etapas posteriores; además, la formación de sinapsis y la consolidación de circuitos se presentan en episodios de expansión sináptica seguidos de poda, fenómeno que se denomina brotes de crecimiento, característico de la plasticidad neuronal durante el desarrollo. Por tanto, la alternativa que integra ambos aspectos –mielinización diferencial y brotes de crecimiento– es la opción D. Las alternativas A y C fallan porque afirman que la mielinización ocurre simultáneamente en todas las zonas, lo cual contradice la evidencia de un orden jerárquico; la alternativa B, aunque reconoce la mielinización diferencial, describe un ritmo de maduración estable, en lugar del patrón de brotes que se observa en la neuroplasticidad temprana.'),
  (669, 'La memoria prospectiva, que implica la planificación y ejecución de acciones futuras, depende principalmente de la función ejecutiva y la regulación de la atención sostenida, procesos que están mediados por el córtex prefrontal, especialmente la corteza dorsolateral y la corteza orbitofrontal; por ello, las lesiones en esta región producen déficits en la memoria prospectiva, mientras que el córtex temporal inferior y las áreas parahipocampales están más vinculadas a la memoria episódica y la orientación espacial, y el hipotálamo no participa directamente en la consolidación o recuperación de recuerdos prospectivos. Las opciones A, C y D son incorrectas porque describen estructuras que no están implicadas directamente en la memoria prospectiva, sino en otros dominios cognitivos o fisiológicos.'),
  (670, 'La posibilidad de que el hemisferio derecho asuma la función del lenguaje tras una lesión del hemisferio izquierdo depende de la plasticidad cerebral, la cual es más pronunciada durante la primera infancia; los estudios de neuroimagen y de casos clínicos demuestran que, cuando la lesión ocurre en los primeros años de vida, el cerebro puede reorganizarse de manera que el lóbulo frontal y temporal derecho se active en tareas lingüísticas, aunque el rendimiento no sea idéntico al de un cerebro sano, lo que explica la opción C; las alternativas A y B son erróneas porque existen numerosos reportes de reubicación funcional en la infancia y la estimulación magnética transcraneal no ha logrado inducir una transferencia completa del lenguaje, sino solo modulaciones parciales; la opción D es incorrecta porque la plasticidad funcional se reduce significativamente después de la pubertad, y la evidencia muestra que la reorganización completa del lenguaje no se mantiene ni se logra hasta los 20‑25 años.'),
  (671, 'El modelo de reserva cognitiva de Yaakov Stern postula que las personas con mayor reserva (educación, ocupación intelectual, estimulación cognitiva) presentan una mayor resistencia inicial a los efectos patológicos del Alzheimer, de modo que el diagnóstico clínico se produce más tarde que en individuos con baja reserva; sin embargo, cuando el diagnóstico sí se establece, la progresión de la enfermedad es más rápida porque el cerebro ya ha acumulado una mayor carga patológica antes de manifestarse clínicamente, lo que explica la opción B. Las alternativas A y C son incorrectas porque confunden la relación entre reserva y velocidad de progresión: la reserva no acelera la aparición del diagnóstico, pero sí la velocidad de deterioro una vez que la enfermedad se manifiesta. La opción D es errónea porque la literatura evidencia sí la vinculación de la reserva con la evolución y pronóstico del Alzheimer, no solo con el deterioro cognitivo leve.'),
  (672, 'El temblor intencional, que se intensifica al acercarse a un objetivo y se reduce con el reposo, es el signo motor característico de una lesión cerebelosa porque refleja la disfunción de los circuitos de coordinación y precisión que el cerebelo regula; los movimientos coreicos, hemibalismo y atetosis, por el contrario, están asociados a daños en el ganglio basal, la cápsula interna o la sustancia blanca subcortical, respectivamente, y no presentan la típica progresión del temblor con la intención motora que se observa en la ataxia cerebelosa.'),
  (673, 'El procesamiento auditivo se inicia en el núcleo geniculado medial (no lateral) del tálamo, que proyecta a la corteza auditiva primaria situada en la circunvolución temporal superior, en la región del giro temporal superior; por tanto la opción B es falsa. La corteza auditiva primaria no se localiza en la circunvolución poscentral, sino en el giro temporal superior, lo que invalida la opción A. Una lesión unilateral del área auditiva primaria afecta la percepción del sonido en el oído contralateral, pero no produce sordera completa bilaterales, de modo que la opción C es incorrecta. La opción D describe correctamente la ubicación del área de Wernicke, situada en la circunvolución temporal superior del hemisferio dominante, y por tanto es la única respuesta que coincide con la anatomía y la fisiología auditiva y lingüística establecidas.'),
  (674, 'El modelo pasivo de reserva cognitiva cerebral se fundamenta en la idea de que la capacidad anatómica del cerebro, es decir, el volumen, la densidad y la integridad de las estructuras neuronales, constituye un recurso que permite tolerar el deterioro funcional asociado a procesos neurodegenerativos; por ello la opción A es la que mejor refleja la concepción teórica de la reserva pasiva, que se limita a la disponibilidad de materia cerebral sin considerar la plasticidad funcional. En contraste, la opción B confunde la reserva pasiva con la reserva activa, la cual se asocia a la capacidad de reorganizar redes y procesos cognitivos para compensar la pérdida, y por tanto no se considera que la reserva pasiva pueda prolongar o revertir el estado clínico. La opción C describe la reserva activa, pues implica el uso eficiente de procesos cognitivos y redes neuronales, lo cual no corresponde al modelo pasivo. Finalmente, la opción D mezcla elementos de la reserva activa (nivel educativo, ocupación, hábitos de vida) con la idea de que la reserva pasiva no contempla el cociente intelectual premórbido; sin embargo, la reserva pasiva se centra exclusivamente en la estructura anatómica, por lo que la afirmación sobre la no estimación del cociente intelectual es incorrecta, aunque el resto de factores mencionados pertenecen a la reserva activa.'),
  (675, 'La demencia semántica se caracteriza por la pérdida progresiva de conocimientos generales, incluyendo conceptos, hechos históricos y la capacidad de comprender palabras aisladas, lo que se explica por la atrofia focal del lóbulo temporal anterior, donde se localizan los núcleos de la memoria semántica y el procesamiento léxico; por ello la opción B describe el proceso clínico y neuroanatomía que explica los síntomas. La encefalopatía postanóxica (A) afecta principalmente la memoria episódica y la formación de nuevas memorias, sin producir anomia ni pérdida de conocimiento semántico; el síndrome de Korsakoff (C) implica anomia y amnesia, pero la lesión se centra en los cuerpos mamilares y el tálamo, no en la pérdida de conocimiento general; la enfermedad de Huntington (D) presenta atrofia de los cuerpos estriados y deterioro ejecutivo, pero no se caracteriza por la pérdida de conceptos y hechos históricos.'),
  (676, 'La opción C es la única que refleja la realidad neurofisiológica del sistema serotoninérgico: la mayoría de los receptores 5‑HT, especialmente los subtipos 5‑HT1 y 5‑HT2, están acoplados a proteínas G y su activación produce efectos inhibitorios en la mayoría de las neuronas del SNC, lo que explica la predominancia de la señalización inhibidora de la serotonina; además, estos receptores se encuentran de forma amplia en el cerebro, lo que justifica la descripción de “ampliamente distribuidos”. En la alternativa A, la toxina botulínica no actúa como antagonista de la acetilcolina sino que inhibe la liberación de este neurotransmisor; la atropina es un antagonista muscarínico, pero el veneno de la araña viuda negra (tityus) potencia la liberación de acetilcolina, no la bloquea. En la B, las neuronas noradrenérgicas están dispersas en varias áreas como el tálamo, la corteza prefrontal y la corteza cingulada, no exclusivamente en el locus coeruleus. Finalmente, la D es incorrecta porque la mayoría de los receptores dopaminérgicos (D1‑D5) son metabotrópicos acoplados a proteínas G, y solo el receptor D2‑D5 presentan subtipos que pueden ser modulados por canales iónicos de manera indirecta, pero no son ionotrópicos en sentido clásico.'),
  (677, 'El modelo de covariación de Kelley sostiene que la atribución causal se basa en la comparación de tres dimensiones: la distintividad (si el comportamiento es específico a la persona o general a la situación), el consenso (si otros también actúan de la misma manera) y la consistencia (si la persona actúa de la misma forma en situaciones similares); al combinar estas tres dimensiones, la persona infiere si la causa es interna o externa, estable o inestable y controlable o no, lo que explica por qué la opción C recoge los tres factores esenciales que Kelley identifica. Las alternativas A, B y D son incorrectas porque se refieren a conceptos que pertenecen a otros modelos de atribución (por ejemplo, la internalidad‑externalidad y la estabilidad‑inestabilidad son componentes de la teoría de la atribución de Rotter, la capacidad‑esfuerzo‑dificultad se relaciona con la teoría de la motivación de Locke, y la intencionalidad‑deseabilidad social‑consecuencias son criterios de la teoría de la motivación social de Cialdini); por tanto, no corresponden a las tres dimensiones fundamentales que Kelley propone.'),
  (678, 'La técnica descrita corresponde a la “puerta en la cara” (door‑in‑the‑face), la cual consiste en plantear inicialmente una petición grande que se espera que sea rechazada y, tras el rechazo, ofrecer una petición más modesta que, en realidad, es la que se pretende lograr; el efecto de reciprocidad y la percepción de concesión aumentan la probabilidad de aceptación de la segunda solicitud. Las demás opciones son inexactas: la “técnica del pie en la puerta” implica comenzar con una petición pequeña y luego solicitar algo mayor; la “técnica del amago” se refiere a una oferta falsa o engañosa; y la “técnica de ‘esto no es todo’” no corresponde a ninguna estrategia establecida en la literatura de persuasión.'),
  (679, 'La teoría de la acción razonada de Ajzen y Fishbein (1980) pretende explicar que el comportamiento humano se determina por la intención de realizarlo, la cual a su vez está influida por la actitud hacia la conducta y la percepción subjetiva de normas sociales; por lo tanto, la opción A es la que refleja adecuadamente la propuesta de que las actitudes influyen directamente sobre el comportamiento, pues la teoría sostiene que la evaluación positiva o negativa de la acción condiciona la intención y, en consecuencia, la conducta. Las demás opciones son inexactas: la B confunde la teoría con la persuasión, que no es su foco principal; la C hace referencia a autoconcepto, un constructo no central en la teoría de la acción razonada; y la D menciona la autoeficacia y la conducta prosocial, conceptos que pertenecen a la teoría del comportamiento planificado, una extensión posterior que incorpora la percepción de control, pero no forman parte de la versión original de 1980.'),
  (680, 'La “holgazanería social” de Latané, Williams y Harkins (1979) se refiere a la reducción del esfuerzo individual cuando la tarea se realiza en grupo, fenómeno conocido como “effort diffusion” o difusión de la responsabilidad; por eso la opción A describe adecuadamente la tendencia a ejercer menor esfuerzo en un contexto colectivo que cuando la responsabilidad es individual. Las demás alternativas son incorrectas: la B confunde la holgazanería con la percepción de la falta de esfuerzo de otros, un sesgo de atribución; la C se centra en la ausencia de autoridad, lo cual es un factor de motivación externo distinto; y la D sugiere que el mínimo esfuerzo depende exclusivamente de un refuerzo externo, ignorando la influencia del contexto grupal que es el núcleo del concepto.'),
  (681, 'La respuesta es la opción B, la teoría de la autoafirmación de Steele (1988), porque esta teoría sostiene que cuando una amenaza al concepto propio se percibe, las personas buscan preservar su identidad afirmando competencias en otras áreas, reduciendo así el impacto de la amenaza; este mecanismo de compensación se basa en la necesidad de coherencia interna y la preservación de la autoimagen. La opción A describe la autopercepción de Bem, que se centra en la inferencia de actitudes a partir del comportamiento, no en la defensa de la identidad ante una amenaza. La opción C, la reactancia de Brehm, explica la resistencia a la restricción de libertades, no la compensación de la autoimagen. La opción D, la sobrejustificación de Deci y Ryan, aborda la motivación intrínseca y la pérdida de motivación cuando se perciben incentivos externos, sin referirse al proceso de afirmación de competencias alternativas para proteger el concepto de sí mismo.'),
  (682, 'La formulación de Latané y Darley (1970) sobre la decisión de ayudar en una emergencia consta de cinco pasos: primero, prestar atención a la situación; segundo, interpretar la situación como una emergencia; tercero, asumir la responsabilidad de ayudar; cuarto, decidir qué se puede hacer o cómo ayudar; y quinto, prestar la ayuda; por lo tanto la opción C es la única que refleja fielmente este modelo, pues incluye los componentes de atención, interpretación, responsabilidad, acción concreta y ejecución. Las demás alternativas son incorrectas porque la A omite el paso de asumir la responsabilidad y la acción concreta, reduciéndose a una interpretación y observación de otros; la B añade un paso de empatía que no figura en el modelo original y limita el proceso a cuatro etapas; la D expande el número de pasos a seis, introduciendo observación de otros y empatía como pasos adicionales que no están presentes en la teoría de Latané y Darley.'),
  (683, 'El fenómeno descrito corresponde al efecto de homogeneidad relativa, que se manifiesta cuando los integrantes de un grupo perciben a los miembros externos como un bloque homogéneo y a los propios como heterogéneos, reforzando la identidad grupal y la diferenciación; este sesgo se explica por la necesidad de justificar la superioridad del propio grupo y la tendencia a atribuir características estereotipadas a los exogrupos, mientras se reconoce la diversidad interna. Las demás opciones son inadecuadas: la diferenciación del exogrupo (B) se refiere a la tendencia a distinguir subgrupos dentro del exogrupo, no a la percepción homogénea; el sesgo intragrupal (C) implica una valoración favorable de los miembros del propio grupo, lo cual no describe la desigualdad de percepción entre grupos; y el efecto de acentuación (D) se relaciona con la exageración de diferencias entre grupos, pero no con la homogeneidad relativa de los exogrupos.'),
  (684, 'El error principal en la estimación de fiabilidad con formas alternativas en aplicación diferida proviene de la variabilidad introducida por el muestreo de contenidos y por el muestreo de tiempos, ya que cada forma puede abarcar distintas facetas del constructo y los intervalos entre las administraciones pueden alterar la estabilidad de la respuesta; por tanto la opción B es la que refleja adecuadamente la fuente de error. Las demás alternativas fallan porque la opción A mezcla el cambio de contenidos con el muestreo de contenidos, pero el error de fiabilidad se debe principalmente a la variabilidad de los ítems y no al cambio de contenidos per se; la opción C confunde el error de calificadores con el muestreo de contenidos, mientras que el error de calificadores no es la fuente principal en la aplicación diferida; la opción D menciona la heterogeneidad de ítems, que sí afecta la fiabilidad, pero el error de muestreo de contenidos es el factor dominante en este contexto.'),
  (685, 'El índice que mide la proporción de sujetos que realizan el test con los que se obtienen resultados correctos se denomina eficacia, pues refleja la capacidad total del instrumento para identificar adecuadamente a los casos que presentan la condición evaluada, sin distinguir entre verdaderos positivos y falsos negativos; la sensibilidad y la especificidad, por su parte, se refieren a la capacidad de detectar los casos positivos y negativos respectivamente, mientras que el valor predictivo positivo indica la probabilidad de que un resultado positivo corresponda a un caso real; por tanto, la opción B es la única que describe la proporción global de resultados correctos, mientras que las demás opciones se centran en aspectos distintos de la precisión diagnóstica.'),
  (686, 'La opción B es la única que describe correctamente el significado de un nivel de significación α = 0,005 en un contraste unilateral derecho: la probabilidad de cometer un error tipo I, es decir, rechazar la hipótesis nula H₀ cuando en realidad es verdadera, es exactamente 0,005; este valor representa la probabilidad de obtener un resultado extremo bajo la distribución de referencia cuando la hipótesis nula se sostiene. Las demás alternativas son incorrectas porque la A confunde la probabilidad de cometer un error tipo I con la probabilidad de no rechazar H₀ cuando es falsa (error tipo II), la C interpreta erróneamente el nivel de significación como la probabilidad de no rechazar H₀ cuando es falsa, y la D mezcla la probabilidad de error tipo I con la probabilidad de no rechazar H₀ cuando es verdadera, lo cual no corresponde a ninguna medida estadística estándar.'),
  (687, 'La opción D es la única que refleja correctamente la relación entre el tamaño de la muestra y la varianza de la distribución de medias, pues al aumentar N la varianza de la media disminuye (σ²/N), reduciendo la superposición entre las distribuciones de las dos poblaciones y, por tanto, incrementando la potencia; las demás alternativas son erróneas porque A confunde el cálculo del tamaño del efecto con la varianza muestral, B describe la superposición de manera ambigua y sugiere que el efecto aumenta la superposición, lo cual es contrario a la teoría, y C afirma que mayor potencia implica intervalos de confianza más largos, cuando en realidad la potencia aumenta cuando los intervalos son más estrechos y la diferencia es mayor.'),
  (688, 'La afirmación falsa es la B; la distribución normal unitaria se refiere a la curva con media cero y desviación típica uno, no a la que tiene media 100 y desviación típica 15, que es la escala de Wechsler para las pruebas de inteligencia, pero no lleva ese nombre; la opción A es verdadera porque la función de densidad normal tiende a cero cuando |x|→∞, por lo que es asintótica respecto al eje de abscisas; la C es cierta ya que cualquier combinación lineal de variables normales sigue una distribución normal, con media y varianza determinadas por los coeficientes y covarianzas; la D también es correcta porque los puntos donde la segunda derivada cambia de signo, es decir, los inflexiones, se hallan a una desviación típica de la media, tanto a la izquierda como a la derecha.'),
  (689, 'La teoría de la respuesta al ítem (TRI) introduce la noción de que la información contenida en cada ítem depende de la capacidad del individuo y del nivel de dificultad del ítem, lo que permite comparar puntuaciones de distintas formas de un test sin necesidad de paralelismo, ya que la equivalencia se logra mediante la calibración de los ítems en un mismo marco de referencia; por tanto la alternativa A refleja precisamente esta innovación, pues la TRI permite establecer comparaciones entre formas distintas de un test sin requerir paralelismo, algo que la teoría clásica no permite. Las demás opciones son incorrectas: la B se refiere a un problema de la teoría clásica (no a una regla nueva de la TRI), la C es una afirmación general de la teoría clásica sobre fiabilidad que no constituye una regla específica de la TRI, y la D describe la perspectiva clásica de tratar al test como unidad, no la de la TRI que enfatiza el ítem como unidad de análisis.'),
  (690, 'El modelo humanista‑existencial se fundamenta en una epistemología fenomenológica que valora la experiencia subjetiva y la percepción de la realidad tal como la vive el individuo; la fenomenología, como corriente filosófica, sostiene que el conocimiento se construye a partir de la descripción de la experiencia vivida, lo que se refleja en la práctica humanista‑existencial a través de la escucha empática, la autenticidad y la búsqueda de significado personal, aspectos que no se encuentran en los enfoques cognitivo‑conductuales, que se centran en la modificación de pensamientos y conductas mediante técnicas operantes; los modelos psicodinámicos, por su parte, se apoyan en teorías psicoanalíticas que privilegian los procesos inconscientes y las dinámicas intrapsíquicas, mientras que el modelo contextual (o terapia de aceptación y compromiso) se basa en la teoría de la acción contextual y la terapia basada en la evidencia, orientada a la flexibilidad funcional y la aceptación, no a la fenomenología.'),
  (691, 'La respuesta se fundamenta en la teoría de la incubación de la ansiedad de Eysenck, que postula que la ansiedad se acumula de forma gradual y se manifiesta de manera “Gestaltlike”, es decir, como una experiencia global y no fragmentada, donde el sujeto percibe la amenaza como un todo que desencadena una respuesta fisiológica y cognitiva simultánea; esta visión se alinea con la idea de que la fobia se construye a partir de una respuesta nociva que se integra en la percepción del individuo. En contraste, el modelo de Watson y Rayner (respuesta clásica de condicionamiento) describe la fobia como una asociación estímulo‑respuesta sin la cualidad de totalidad; el modelo bifactorial mediacional de Mowrer (modelo de aprendizaje doble vía) enfatiza la interacción entre aprendizaje clásico y operante, pero no destaca una respuesta Gestalt; y la teoría de preparación de Seligman (teoría de la preparación de la ansiedad) se centra en la predisposición genética y la sensibilidad a la ansiedad, sin referirse a una respuesta “Gestaltlike”.'),
  (692, 'El trastorno de ansiedad social se caracteriza por un miedo intenso y persistente a situaciones sociales que involucran evaluación negativa, y la literatura clínica indica que, a diferencia de otros trastornos de ansiedad, suele presentarse de forma aislada, sin comorbilidad frecuente con trastornos de ansiedad generalizada o fobias específicas; por ello la opción C se ajusta a la descripción de la entidad, mientras que la A es incorrecta porque la ansiedad social no mejora síntomas médicos en adultos mayores, sino que suele empeorarlos; la B es errónea porque el inicio tardío no se asocia con una mayor aparición de depresión o abuso de sustancias, sino que la edad temprana es el factor de riesgo; y la D es falsa porque las expectativas sociales no explican una mayor búsqueda de ayuda en mujeres, sino que la búsqueda de ayuda es más frecuente en hombres con ansiedad social, lo que contradice la afirmación.'),
  (693, 'En el DSM‑5 el trastorno de depresión mayor se caracteriza por la presencia de síntomas depresivos persistentes que duran al menos dos semanas y que impiden el funcionamiento habitual; la persistencia de síntomas leves durante la remisión constituye un factor pronóstico de recurrencia, ya que la evidencia clínica muestra que la presencia de síntomas residuales aumenta la probabilidad de recaída, lo que se refleja en la escala de gravedad y en la necesidad de ajustar el tratamiento; por tanto, la opción B es la que describe correctamente este aspecto pronóstico. La opción A es incorrecta porque la hipersomnia y la hiperfagia son más frecuentes en la depresión mayor en la infancia y adolescencia, no en la tercera edad. La opción C confunde la evolución del duelo con la disforia del trastorno depresivo, pues en el duelo la disforia suele disminuir con el tiempo, mientras que en la depresión mayor persiste o empeora. La opción D, aunque menciona la relación entre intentos de suicidio y suicidios consumados, no corresponde al criterio de riesgo sistemáticamente descrito en el DSM‑5, que enfatiza la historia de intentos como factor de riesgo, pero no lo presenta como la descripción más sistemática; además, la premisa de que la mayoría de suicidios consumados se preceden de intentos fallidos no es una afirmación generalizada en el manual.'),
  (694, 'La opción D se sustenta en la evidencia de estudios de coste‑beneficio que han comparado la activación conductual con la terapia cognitiva en contextos de salud pública, mostrando que la activación conductual ofrece mayor eficiencia en términos de recursos y tiempo, sin sacrificar la eficacia clínica; además, su estructura breve y orientada a la acción facilita su implementación en servicios con limitaciones presupuestarias, lo que la convierte en la intervención más rentable. En cambio, la alternativa A es errónea porque la activación conductual se centra en actividades que generan refuerzo positivo, no en aquellas que resultan evitativas, pues la evitación perpetúa la depresión. La opción B es incorrecta porque la versión de Jacobson et al. (1996) no se basa en la Ley de igualación de Hernstein, sino en la teoría de la activación conductual que enfatiza la relación entre la conducta y la emoción, sin recurrir a esa ley. Finalmente, la alternativa C es demasiado restrictiva: aunque las actividades agradables pueden ser útiles, la activación conductual también incluye tareas que, aunque no sean intrínsecamente placenteras, son significativas y funcionales para el individuo, y su programación se guía por el análisis funcional y la valoración de refuerzo, no únicamente por el placer.'),
  (695, 'La terapia interpersonal (TIP) se fundamenta en el diagnóstico clínico de la depresión, pues su estructura y objetivos están diseñados para responder a los síntomas y a los problemas interpersonales que caracterizan a este trastorno; por ello la opción B se ajusta a la definición de la TIP como un tratamiento orientado desde el diagnóstico. La alternativa A es incorrecta porque la TIP no se centra en las relaciones tempranas ni en la etiología psicoanalítica, sino en los patrones interpersonales actuales que mantienen la depresión. La opción C también es falsa, ya que la TIP posee un sólido respaldo empírico, con numerosos ensayos controlados que demuestran su eficacia. Finalmente, la D es inexacta: la TIP suele estructurarse en 12‑16 sesiones, no en exactamente diez, y su número de sesiones varía según la gravedad y la respuesta del paciente.'),
  (696, 'Según Wampold (2011) la eficacia de los psicólogos clínicos se vincula principalmente con la conciencia intrapersonal y la regulación de sus propias experiencias psicológicas, pues la autorreflexión permite evitar la proyección de sus conflictos internos sobre el paciente y facilita la construcción de una alianza terapéutica auténtica y centrada en el cliente; por tanto, la opción B se alinea con la evidencia que muestra que los terapeutas que practican la supervisión interna y la autoobservación reducen la interferencia de sus procesos psicológicos en la sesión, lo que favorece la respuesta del paciente. Las demás alternativas son erróneas: la experiencia clínica extensa (A) no garantiza la eficacia por sí sola, pues la calidad del proceso terapéutico depende más de la relación que del número de años; la psicoterapia personal reglada (C) puede ser beneficiosa pero no es un predictor universal de eficacia, ya que su impacto varía según la modalidad y la integración en la práctica clínica; la explicación técnica basada en un modelo teórico (D) puede resultar demasiado rígida y centrada en el marco teórico, limitando la flexibilidad necesaria para responder a las necesidades individuales del paciente.'),
  (697, 'El nivel de angustia pretratamiento resulta ser el mejor predictor del resultado terapéutico porque la intensidad de la sintomatología inicial determina la motivación, la capacidad de compromiso y la respuesta a la intervención; estudios longitudinales muestran que mayores niveles de angustia se correlacionan con mayores mejoras cuando se mantiene la adherencia, mientras que diagnósticos, cronicidad o población son variables más estáticas y menos sensibles al proceso terapéutico; por tanto, las demás opciones son insuficientes: el diagnóstico (A) describe la naturaleza del trastorno pero no su gravedad ni la respuesta al tratamiento, la cronicidad (B) indica la duración del problema sin reflejar la motivación actual, y el tipo de población (C) se refiere a características demográficas o contextuales que no predicen directamente el curso clínico.'),
  (698, 'La descripción corresponde al nivel de Declaración del problema/clarificación, ya que la persona logra articular su dificultad, distingue entre contenidos mentales opuestos y mantiene un afecto negativo pero controlado, lo que indica que ha alcanzado la fase de reconocimiento y definición del problema sin haber cruzado el umbral de la crisis emocional; en contraste, el nivel de Comprensión/insight implicaría una mayor profundización en la causa y significado del problema, mientras que la fase de Aplicación/elaboración requeriría la utilización de estrategias de afrontamiento y la fase de Integración/dominio implicaría la internalización y manejo autónomo de la situación, lo que no se evidencia en la descripción.'),
  (699, 'Rogers sostuvo que la autenticidad (congruencia), la empatía y la consideración positiva eran los tres pilares que garantizaban la eficacia terapéutica; la evidencia contemporánea, sin embargo, ha demostrado que la congruencia del terapeuta es la única de esas variables que mantiene una asociación consistente y significativa con los resultados clínicos, mientras que la empatía y la consideración positiva presentan efectos más variables y dependientes del contexto, lo que explica por qué la opción C es la que refleja la posición actual; las demás alternativas son erróneas porque la opción A niega cualquier correlación, contradiciendo los hallazgos empíricos que sí muestran efectos de la congruencia, la opción B sobreestima la evidencia de empatía y consideración positiva, y la opción D afirma incorrectamente que la congruencia tiene mayor evidencia que la consideración positiva, cuando en realidad es la empatía la que comparte mayor respaldo, aunque menos robusto que la congruencia.'),
  (700, 'En la terapia familiar sistémica estructural, la técnica que implica dirigir a los miembros de la familia para que hablen o interactúen entre sí con el fin de observar y modificar las pautas de interacción se denomina escenificación, pues el terapeuta crea una “escena” o “escenario” donde se reproducen las dinámicas familiares, permitiendo identificar jerarquías, alianzas y patrones disfuncionales que pueden ser intervenidos; las demás opciones son incorrectas: la acomodación se refiere a la adaptación de la estructura familiar a un cambio externo, el desequilibrio describe una falta de cohesión o equilibrio entre subsistemas, y el enfoque es una perspectiva teórica general que no especifica una técnica de intervención concreta.'),
  (701, 'El concepto de juego familiar de Selvini Palazzoli se fundamenta en la teoría de los juegos de poder desarrollada por Michel Crozier, que describe cómo los individuos dentro de una organización (o familia) negocian y estructuran sus relaciones mediante estrategias de juego; por ello la opción D es la que se ajusta a la base teórica de la obra. La alternativa A es incorrecta porque, aunque la dinámica familiar se analiza de forma sincrónica, el enfoque de Selvini Palazzoli no otorga un papel prioritario exclusivamente a esa dimensión, sino que integra también la perspectiva sistémica y contextual. La opción B resulta errónea al afirmar que se emplean técnicas estratégicas con un componente lúdico para reorganizar los límites intrafamiliares; en realidad el método se centra en la observación de los patrones de interacción y en la interpretación de los juegos simbólicos, sin recurrir a intervenciones lúdicas explícitas. Finalmente, la respuesta C es inexacta al indicar que se obvia el análisis de creencias, valores y estrategias individuales; el enfoque de Selvini Palazzoli sí contempla estos elementos como componentes esenciales de la dinámica familiar, aunque los interpreta dentro del marco de los juegos de poder.'),
  (702, 'El reflejo en la entrevista motivacional se emplea cuando el paciente expresa un discurso de cambio, pues permite al clínico amplificar y clarificar las motivaciones internas, reforzando la ambivalencia y la autoconfianza; al escuchar un discurso de cambio el reflejo ayuda a consolidar la intención de modificar el comportamiento y a identificar los valores que impulsan dicha decisión, lo que favorece la construcción de un plan de acción concreto. Las demás alternativas son inadecuadas: el reflejo no se justifica cuando el discurso es muy abundante (A) porque la abundancia suele requerir síntesis y resumen, no la ampliación; tampoco cuando el discurso es muy escaso (B) ya que en ese caso el clínico debe explorar más profundamente con preguntas abiertas; y no se utiliza cuando se escucha discurso de mantenimiento (C), pues el objetivo es precisamente cambiar la perspectiva y no reforzar la resistencia al cambio.'),
  (703, 'El modelo de Valeria Ugazio sostiene que la polaridad semántica dominante en la dinámica familiar se refleja en la relación entre la necesidad de ejercer poder y la aparición de trastornos de la conducta alimentaria, pues la búsqueda de control sobre el cuerpo y la alimentación se interpreta como una forma de compensar la falta de poder en el entorno familiar; por ello la opción A describe la asociación que el modelo identifica. Las demás alternativas no se corresponden con la teoría de Ugazio: la bondad no se vincula de manera específica con los trastornos del estado de ánimo, la justicia no constituye la polaridad central en los trastornos obsesivos, y la seguridad no se relaciona de forma predominante con los trastornos fóbicos; en conjunto, estas respuestas fallan al atribuir a conceptos que el modelo no considera como eje principal de la dinámica familiar.'),
  (704, 'La propuesta que integra la teoría de los constructos personales de G. Kelly con la terapia sistémica es el “sistema de constructos familiares” de Harry Procter, pues él expande el modelo de constructos de Kelly a la dimensión familiar, considerando que los constructos individuales se construyen y se reorganizan dentro de la red de relaciones familiares y que la intervención sistémica debe intervenir en la reconfiguración de esos constructos interrelacionados; las demás opciones se refieren a enfoques que, aunque comparten la idea de la familia como contexto de intervención, no incorporan la noción de constructos personales de Kelly (la rejilla de polaridades familiares de Watt se centra en la dinámica de polaridad, el modelo ecológico‑constructivo de Cecchin enfatiza la interacción entre entorno y constructos sin un enfoque sistémico explícito, y la terapia transteórica familiar de Prata combina etapas de cambio con la familia pero no adopta la teoría de constructos de Kelly).'),
  (705, 'La terapia cognitiva post‑racionalista de Vittorio Guidano se articula en tres fases que reflejan la progresión de la intervención: primero la “reconstrucción de la experiencia inmediata”, que consiste en identificar y descomponer las experiencias vividas en el momento presente; segundo la “reconstrucción del estilo afectivo”, donde se trabaja la interpretación emocional que se atribuye a esas experiencias; y finalmente el “análisis evolutivo”, que integra la comprensión de los procesos de cambio a lo largo del tiempo, permitiendo la reestructuración de los esquemas y la consolidación de nuevas formas de afrontamiento. Estas etapas se corresponden con la opción A, pues capturan la secuencia lógica de la metodología de Guidano, que parte de la experiencia concreta, pasa por la dimensión afectiva y culmina en la perspectiva evolutiva del paciente. Las demás alternativas fallan porque no reflejan la estructura específica del modelo: la B describe un esquema más genérico de evaluación y desafío de sistemas constructivos, sin la referencia explícita al estilo afectivo ni al análisis evolutivo; la C introduce conceptos de “evaluación diacrónica” y “moviola” que no aparecen en la literatura de Guidano; y la D, aunque menciona análisis histórico y proyección futura, omite la fase de reconstrucción del estilo afectivo, elemento central del enfoque post‑racionalista.'),
  (706, 'El primer paso que propone Michael Mahoney en la psicoterapia constructivista es la focalización y recuperación del equilibrio, adquiriendo cierto sentido de calma psicofísica, ya que la terapia comienza con la estabilización emocional y la creación de un espacio seguro donde el paciente puede observar sus procesos internos sin la interferencia de la ansiedad; esta fase permite que el terapeuta y el paciente identifiquen y trabajen sobre los patrones constructivos que generan disfunción, estableciendo una base para la posterior reestructuración. Las demás opciones son incorrectas porque la evaluación del mundo interno con la rejilla de constructos personales (A) corresponde a la fase de evaluación, no al inicio; el cambio de expectativas asociadas al sistema constructivo (B) y la búsqueda de excepciones (C) son estrategias que se emplean después de haber alcanzado la calma y el equilibrio, cuando el paciente ya puede afrontar la reconfiguración de sus constructos.'),
  (707, 'La psicoterapia cognitivo‑narrativa propuesta por Gonçalves se centra en la interacción entre la experiencia presente del paciente y la construcción de su relato a lo largo del tiempo, por lo que analiza dos direcciones o niveles: el sincrónico, que corresponde al momento actual de la experiencia y la percepción inmediata del paciente, y el diacrónico, que abarca la evolución histórica y la continuidad de los significados que el individuo atribuye a su vida; esta doble dimensión permite integrar la comprensión de los procesos cognitivos inmediatos con la reconstrucción de la narrativa personal, lo que constituye la base de la intervención. Las opciones A, C y D son incorrectas porque no reflejan la división temporal que caracteriza el modelo de Gonçalves: la opción A se refiere a aspectos intrapsíquicos y de relación, la C a una distinción entre objetivo y narrativo sin base teórica en su propuesta, y la D introduce categorías constructivas y deliberativas que no aparecen en el marco conceptual del enfoque cognitivo‑narrativo.'),
  (708, 'En la psicoterapia focalizada en la transferencia, la monitorización de la transferencia se centra en los canales por los cuales se manifiesta la relación terapéutica: el contenido verbal del discurso del paciente, la comunicación no verbal del paciente y la contratransferencia del terapeuta; estos tres elementos permiten identificar la dinámica de idealización, proyección y resistencia que caracterizan al trastorno límite de la personalidad y guían la intervención para estabilizar la relación y reducir la impulsividad; las demás opciones son incorrectas porque la opción A confunde los síntomas clínicos con los canales de comunicación, la opción C se refiere a la estructura psíquica del ego, no a la transferencia, y la opción D incluye la comunicación escrita, que no forma parte de los canales tradicionales de la transferencia en la sesión.'),
  (709, 'La opción D es falsa porque la “Mente Sabia” es una práctica de la terapia dialéctica conductual que pertenece al módulo de “Mindfulness” pero se clasifica dentro de las “Habilidades Qué” (la capacidad de observar y describir sin juicio, de reconocer la experiencia interna y externa) y no de las “Habilidades Cómo”, que se refieren a la forma de aplicar la atención plena (por ejemplo, “No juzgar” o “Observar”). En la estructura de la TDC, las “Habilidades Qué” incluyen “Observar”, “Describir”, “Participar” y “No juzgar” (aunque este último también se considera una forma de “Cómo” en algunos manuales, se mantiene dentro de la categoría de “Qué” en la clasificación clásica), mientras que las “Habilidades Cómo” se centran en la aplicación práctica de la atención plena, como “No juzgar”, “No reaccionar” y “No aferrarse”. Por lo tanto, la afirmación de que “Mente Sabia” se ubica en las “Habilidades Cómo” es incorrecta, mientras que las demás opciones describen correctamente la clasificación de las habilidades de mindfulness dentro de la TDC.'),
  (710, 'La opción C es falsa porque la terapia dialéctico-conductual (TDC) no ha desarrollado un programa grupal denominado “dialéctico-conductual radicalmente abierto” para el trastorno dependiente de la personalidad; la TDC se aplica principalmente en formato individual o grupal para trastornos de la personalidad borderline y no incluye un enfoque abierto radicalmente distinto para la dependencia. En cambio, la opción A es verdadera: Bornstein describe la disfunción dependiente como un fenómeno multidimensional que abarca cogniciones, motivaciones, afectos y conductas, lo que explica la complejidad de su tratamiento. La opción B es correcta porque Ovelhoser y Fine proponen un modelo de cuatro etapas (dirección activa, aumento de la autoestima, fomento de la autonomía y prevención de recaídas) que se ha utilizado con resultados prometedores en la práctica clínica. Finalmente, la opción D también es válida, pues la psicoterapia orientada a la clarificación, la terapia cognitivo-analítica y la terapia de aceptación y compromiso (ACT) han mostrado evidencia de eficacia moderada en la reducción de síntomas dependientes, respaldando su inclusión en el repertorio terapéutico.'),
  (711, 'La metacomunicación se refiere a la comunicación sobre la propia comunicación, es decir, al diálogo que regula y reflexiona el proceso comunicativo entre terapeuta y paciente; por ello constituye una forma de autorrevelación porque el terapeuta expone sus propios procesos internos y su interpretación de la interacción, lo que facilita la transparencia y la construcción conjunta de significado, y se ha demostrado que favorece la alianza terapéutica y la eficacia clínica; en contraste, las autorrevelaciones en general se consideran útiles pero su eficacia depende de la adecuación contextual y del nivel de experiencia del terapeuta, y la relación real (la relación auténtica entre los involucrados) es reconocida como esencial, aunque su estudio empírico es limitado; el manejo de la contratrasferencia también se valora, pero la evidencia sobre su impacto sigue siendo escasa.'),
  (712, 'El fenómeno de privación del duelo se produce cuando la persona no puede o no desea pasar por el proceso de duelo por la pérdida, ya sea por una elección consciente o por una situación que impide la expresión emocional; la interrupción voluntaria del embarazo constituye una decisión deliberada que evita la experiencia de la pérdida y, por tanto, se ajusta a la definición de privación del duelo, pues la persona evita el proceso de duelo al no haber una relación afectiva que se haya roto. Las demás opciones describen situaciones donde la pérdida se ha producido (B, C) o donde la persona está presente en el momento del fallecimiento (D), lo que implica la posibilidad de experimentar el duelo; en ninguno de esos casos se observa una evitación voluntaria del proceso, por lo que no se trata de privación del duelo.'),
  (713, 'El modelo que mejor explica la decisión de María es el Modelo de la Creencia sobre la Salud, pues este marco conceptual sostiene que las conductas preventivas dependen de la percepción de susceptibilidad, gravedad, beneficios y barreras, además de la autoeficacia; María evalúa su riesgo familiar como alto (susceptibilidad y gravedad), reconoce la utilidad de la mamografía para la detección temprana (beneficios) y minimiza la molestia percibida frente a la amenaza, lo que la lleva a optar por la prueba; las otras opciones se centran en motivaciones más generales de protección (A), en la intención y la planificación de la acción (C) o en la influencia de la razón y la intención sin considerar la autoeficacia (D), por lo que no capturan tan específicamente la valoración de riesgo y beneficio que guía su elección.'),
  (714, 'La opción A es la que se ajusta a la conceptualización de Safran y Muran (2005) sobre la alianza terapéutica; cuando la relación entre terapeuta y paciente se deteriora por desacuerdo en objetivos, falta de colaboración o insuficiente vínculo emocional, se habla de una ruptura de la alianza, es decir, la pérdida de la confianza y el compromiso que sustentan la intervención. Las alternativas B, C y D no corresponden a la definición de ruptura: la B describe un conflicto, que implica una disputa activa pero no necesariamente la pérdida de la alianza; la C y la D se refieren a fallas metacognitivas, que son procesos internos de reflexión sobre los propios pensamientos y los del otro, y aunque pueden contribuir a la ruptura, no son la descripción primaria del deterioro de la alianza según Safran y Muran.'),
  (715, 'La psicoterapia psicodinámica cíclica de Paul Wachtel se caracteriza por combinar de manera sistemática los principios teóricos de la psicodinámica con una estructura de intervención que sigue ciclos de trabajo específicos, integrando conceptos de la teoría de la personalidad, la teoría de la motivación y la teoría de la relación interpersonal; por ello se denomina “integración teórica híbrida”, ya que fusiona distintas corrientes teóricas en un marco coherente y funcional, algo que no ocurre en la integración técnica pragmática (B), que se limitaría a la aplicación de técnicas sin profundizar en su base conceptual, ni en la integración técnica de orientación (C), que implicaría la adopción de una única perspectiva técnica, ni en la integración teórica amplia (A), que sugiere una mera combinación de teorías sin la cohesión estructural que caracteriza al modelo de Wachtel.'),
  (716, 'La terapia de insight y reflexión metacognitiva (Lysaker) se orienta explícitamente a la psicosis y a los trastornos del clúster A de personalidad, integrando la evaluación de la experiencia subjetiva con la regulación de la atención y la metacognición, lo que permite abordar tanto los síntomas psicóticos como los patrones de pensamiento rígidos y paranoides característicos de esos trastornos; las demás opciones, aunque emplean enfoques metacognitivos, se centran en la regulación emocional o la interacción interpersonal (A y B) o en la reestructuración de esquemas disfuncionales (D), y por tanto no están diseñadas específicamente para el tratamiento de la psicosis y el clúster A.'),
  (717, 'La actitud descrita corresponde al “lecho de Procusto”, un término que designa la imposición de un modelo terapéutico rígido sobre el paciente sin considerar sus particularidades, tal como el mito de Procusto que forzaba a sus víctimas a encajar en un lecho de longitud fija; en psicoterapia, esto implica una falta de adaptación del método a las necesidades individuales, lo que reduce la eficacia del tratamiento y puede generar resistencia o ruptura del vínculo terapéutico. La opción A, “arrogancia metodológica”, no es un término clínico establecido y no captura la idea de imposición de un esquema fijo; la opción B, “rigidez”, aunque describe una cualidad del terapeuta, es demasiado genérica y no señala la referencia mitológica que caracteriza al concepto; la opción D, “terapeuta‑centrismo”, se refiere a la tendencia a colocar al terapeuta como eje principal, pero no implica necesariamente la imposición de un método sin adaptación, por lo que las tres alternativas carecen de la especificidad del lecho de Procusto.'),
  (718, 'Bohart y Tallman (2010) sostienen que la evidencia de la agencia humana se manifiesta en la capacidad de los pacientes para participar activamente en su propio proceso de cambio, incluso cuando reciben intervención psicológica; por ello la opción que refleja este concepto es la que indica que “las personas, cuando son usuarias de una psicoterapia, siguen siendo agentes activos altamente implicados en el cambio” (opción D). Las demás alternativas son incorrectas porque la A presume una incapacidad total sin ayuda profesional, contradiciendo la premisa de agencia; la B limita la actividad al momento de la terapia, sin reconocer la continuidad del protagonismo; y la C se refiere a mecanismos comunes a todos los tratamientos, lo cual no aborda la participación activa del individuo, sino la homogeneidad de los procesos terapéuticos.'),
  (719, 'La opción C es la que refleja la realidad de la investigación sobre los factores comunes en psicoterapia: demostrar la eficacia de un tratamiento para un trastorno no basta con probar que funciona, pues el verdadero desafío es desentrañar los procesos internos que generan el cambio, es decir, identificar y medir los factores comunes como la alianza terapéutica, la expectativa de mejora, la empatía y la estructura del proceso terapéutico; sin ese análisis, la evidencia clínica queda incompleta. La alternativa A es incorrecta porque, a diferencia de lo que afirma, no existe consenso sobre las evidencias empíricas de los mecanismos de cambio, pues los estudios sobre estos procesos presentan resultados heterogéneos y metodologías divergentes. La opción B es errónea al presentar la gran cantidad de tratamientos como un factor que facilita el avance científico; en realidad, la proliferación de enfoques fragmenta la investigación y dificulta la consolidación de un marco teórico común. La alternativa D también resulta inexacta porque muchos modelos explican la efectividad de la psicoterapia no solo por factores comunes, sino también por factores específicos y la interacción entre ambos, y no se limita a la relación con el tipo de tratamiento empleado.'),
  (720, 'El modelo de los límites de la regulación de la ingesta de Herman y Polivy sostiene que la desinhibición alimentaria en individuos restrictivos se activa cuando perciben haber cruzado un límite autoimpuesto; esta percepción, aunque puede ser falsa, genera una sensación de pérdida de control que desencadena la compensación. Por tanto, la opción B es la que refleja el mecanismo central del modelo, pues la creencia de haber traspasado el límite, independientemente de su veracidad, constituye el disparador de la desinhibición. Las demás alternativas fallan porque la opción A describe un efecto de violación de la abstinencia, pero el modelo no lo considera el factor clave; la opción C atribuye la desinhibición a alteraciones emocionales, lo cual corresponde a teorías de regulación emocional, no al modelo de límites; y la opción D se refiere a la supresión de pensamientos, un proceso de control cognitivo que tampoco es el elemento central del modelo de Herman y Polivy.'),
  (721, 'La opción B es la única que refleja la cronología típica de la comorbilidad entre la anorexia nerviosa y la depresión mayor: la depresión suele surgir en el mismo año o el siguiente al diagnóstico de AN, lo que sugiere una relación temporal y posiblemente causal entre la alteración de la autoimagen corporal y la pérdida de peso y la aparición de síntomas depresivos, mientras que las demás alternativas fallan por datos epidemiológicos o clínicos; la afirmación A sobre un 50 % de pacientes con AN que experimentan depresión mayor a lo largo de la vida sobreestima la prevalencia, pues estudios indican cifras más cercanas al 30 %; la C es incorrecta porque el neuroticismo elevado y el bajo interés por el reforzamiento social no son características distintivas de la AN, sino más bien de trastornos de ansiedad; y la D sobre el 15 % de familias con otro trastorno alimentario subclínico también sobreestima la frecuencia, ya que la prevalencia familiar se sitúa en torno al 5 %‑10 %.'),
  (722, 'La migración diagnóstica de bulimia nerviosa a anorexia nerviosa es un fenómeno poco frecuente, con estudios longitudinales que indican que solo una minoría de los pacientes experimentan este cambio; la opción B recoge precisamente ese hallazgo, pues la literatura muestra que el porcentaje se sitúa por debajo del 10 % y, por tanto, la afirmación de que se produce en una minoría es la única que concuerda con los datos empíricos. La opción A es incorrecta porque la cifra de “aproximadamente la mitad” sobreestima enormemente la incidencia, contradiciéndose con los estudios que reportan valores mucho menores. La opción C, que menciona un 20 %, también sobrepasa el rango real y, aunque más cercana, sigue siendo demasiado alta para considerarse representativa de la población clínica. Finalmente, la opción D es errónea porque, aunque raro, la migración diagnóstica sí se documenta con cierta frecuencia en la práctica clínica, por lo que describirla como inusual no refleja la evidencia disponible.'),
  (723, 'El trastorno por evitación y restricción de la ingesta de alimentos se caracteriza por la selección de alimentos basada en criterios sensoriales (apariencia, color, olor, textura, etc.), pues la intolerancia a estímulos sensoriales constituye el mecanismo principal que limita la variedad alimentaria y conduce a la ingesta insuficiente; por tanto, la opción A describe fielmente el patrón clínico. La alternativa B se equivoca al afirmar que hay una alteración en la percepción del peso y la forma corporal, ya que en este trastorno la preocupación por la imagen corporal no es predominante, a diferencia de la anorexia nerviosa. La opción C es incorrecta porque la evitación alimentaria suele provocar pérdida de peso y déficit nutricional, aunque la gravedad varía; la ausencia de pérdida de peso no es característica. Finalmente, la opción D es errónea porque la selección de alimentos no se basa en su contenido calórico, sino en la sensibilidad sensorial, lo que distingue a este trastorno de la bulimia o el trastorno por atracón.'),
  (724, 'Rachman (1971) identificó que la persistencia de las obsesiones en el TOC se explica por la sensibilización de los pensamientos, vinculada a un estado de disforia, a la falta de control percibido sobre uno mismo y el entorno, y a la exposición a acontecimientos estresantes que refuerzan la ansiedad; la expresión inadecuada de las propias emociones no figura entre esas variables, pues el modelo de Rachman se centra en la percepción de amenaza y control, no en la regulación emocional; las demás opciones sí corresponden a los factores que el autor consideró relevantes para la intensificación y mantenimiento de las obsesiones.'),
  (725, 'La elección entre la terapia de exposición con prevención de respuesta (EPR) y la terapia de aceptación y compromiso (ACT) se basa en la destreza del terapeuta y las preferencias del paciente, según Ong (2020); la EPR se aplica cuando el profesional posee la formación necesaria para manejar la exposición gradual y la prevención de la respuesta, mientras que la ACT se prefiere cuando el paciente valora la aceptación de sus pensamientos y emociones y busca comprometerse con metas más amplias que no se centran exclusivamente en la reducción de síntomas, lo que permite adaptar la intervención a la motivación y la capacidad de tolerancia al malestar. Las opciones B y C son incorrectas porque, aunque la evidencia respalda la eficacia de la EPR en la reducción de compulsiones y la ACT en la mejora de la calidad de vida y la aceptación, el criterio de selección no se basa únicamente en la eficacia de cada técnica, sino en la combinación de habilidades del terapeuta y las preferencias del paciente; la opción D es errónea porque la comorbilidad clínica no constituye el factor decisivo principal en la elección entre EPR y ACT según la referencia citada.'),
  (726, 'La terapia interpersonal de Klerman y Weissman incorpora la teoría del apego de Bowlby al considerar que los patrones de relación temprana influyen en la dinámica interpersonal actual y en la aparición de síntomas depresivos; el modelo utiliza la identificación de roles, la comunicación y la resolución de conflictos como medios para modificar la relación terapéutica y, por ende, los patrones de apego disfuncionales, lo que explica por qué la opción A es la que integra explícitamente esa teoría. Las demás alternativas se centran en principios distintos: la terapia Morita enfatiza la aceptación de la ansiedad sin intentar cambiarla; la terapia estratégica de la escuela interaccional MRI se basa en la teoría de sistemas y la comunicación, sin referencia al apego; y la terapia estratégica de Haley se orienta a la resolución de problemas mediante la reestructuración de la dinámica familiar, sin incorporar la teoría del apego.'),
  (727, 'El DSM‑5 indica que aproximadamente el 30 % de los pacientes con trastorno obsesivo‑compulsivo presentan comorbilidad con trastornos de tics, lo que refleja la asociación neurobiológica entre los circuitos cortico‑estriado‑corticales y la regulación de la impulsividad; por ello la opción B es la que se ajusta a la evidencia clínica y epidemiológica del manual. La afirmación A es incorrecta porque la prevalencia de inicio antes de los 10 años es mucho menor, alrededor del 5 %‑10 % y no se limita a mujeres; la opción C equivale a una confusión entre TOC y trastorno de acumulación, pues la presencia de obsesiones típicas con conductas de acumulación no excluye el diagnóstico de TOC, y la opción D sobreestima la prevalencia familiar, pues la tasa familiar es aproximadamente 2‑3 veces mayor, no exactamente tres veces.'),
  (728, 'El síndrome de crisis suicida propuesto por Galynker se define como un estado mental presuicida que surge cuando la desregulación cognitiva y afectiva se combina con la percepción de que la vida ya no tiene sentido, lo que conduce a la aparición de pensamientos y conductas suicidas; por ello la opción D es la que recoge fielmente la conceptualización de Galynker, que enfatiza la interacción entre la alteración emocional, la pérdida de control cognitivo y la motivación suicida. Las demás alternativas son incorrectas: la A confunde el síndrome con el estado afectivo de los supervivientes de suicidio, que no es el foco de la teoría; la B describe una fase de riesgo a medio y largo plazo, mientras que el síndrome de crisis se refiere a la etapa inmediata de crisis; y la C menciona criterios diagnósticos que no forman parte de la definición original de Galynker, pues la desesperanza y el vacío son conceptos más generales que no se incluyen explícitamente en su esquema.'),
  (729, 'El argumento falso es el de la hipoactivación de la región frontoestriada en el TOC frente a la activación de la amígdala en los trastornos de ansiedad; la evidencia neuroimagen muestra que el TOC se asocia con una hiperactividad de la corteza orbitofrontal‑corteza cingulada y la caudada, no con una hipoactivación, y que la amígdala también puede estar hiperactiva en el TOC, por lo que la distinción propuesta no se sostiene; las demás opciones son consistentes con la literatura: la respuesta a ISRS es similar entre el TOC y los trastornos de ansiedad (B), la dificultad para iniciar o detener conductas se describe tanto en el TOC como en otros trastornos obsesivo‑compulsivos (C), y la compulsividad constituye el síntoma central del espectro obsesivo‑compulsivo, con la impulsividad como su opuesto (D).'),
  (730, 'La afirmación falsa es la A: la primera sesión de exposición no suele ser altamente eficaz en el tratamiento de obsesiones sin conducta compulsiva manifiesta, ya que la exposición temprana suele requerir una fase de preparación y de construcción de una alianza terapéutica sólida; en la práctica clínica la eficacia de la exposición se incrementa progresivamente a medida que el paciente adquiere tolerancia y aprende a tolerar la ansiedad, por lo que la primera sesión suele ser más de iniciación que de resolución completa. La opción B es coherente con la literatura, pues las compulsiones encubiertas son más variadas, idiosincráticas y se correlacionan con una respuesta menos favorable al tratamiento. La C describe correctamente el uso de cinta de audio como herramienta práctica y eficaz para entrenar la exposición y la prevención de la respuesta en eventos encubiertos. La D también es válida, pues el objetivo terapéutico es modificar la interpretación de las obsesiones, evitar la neutralización y permitir la habituación a los pensamientos obsesivos.'),
  (731, 'En la clasificación de Custer (1984) revisada por Lesieur (1991), la fase inicial de la adicción al juego se denomina “fase de ganancia” y se caracteriza por la percepción de que el juego produce beneficios económicos y emocionales, lo que refuerza la conducta y aumenta la frecuencia de juego; por tanto la opción A describe adecuadamente este estadio. Las demás alternativas corresponden a etapas posteriores: la opción B describe la fase de “desorganización vital”, donde el jugador deja de atender otras áreas de su vida; la opción C se refiere a la fase de “contemplación de la ayuda”, que ocurre cuando el jugador reconoce la necesidad de tratamiento; y la opción D se relaciona con la fase de “caza de pérdidas”, en la que el jugador intenta recuperar lo perdido, lo cual no ocurre en la primera fase.'),
  (732, 'El enfoque integrado es el que se fundamenta en la evidencia de que los trastornos adictivos y los trastornos psicopatológicos comórbidos interactúan de manera bidireccional, de modo que la presencia de uno agrava el curso y la respuesta al tratamiento del otro; por ello, la intervención debe contemplar simultáneamente ambos problemas, permitiendo la aplicación de estrategias específicas (por ejemplo, terapia cognitivo-conductual para la adicción y técnicas de regulación emocional para el trastorno comórbido) dentro de la misma sesión o programa, lo que optimiza la adherencia y la eficacia clínica. Las demás opciones son inadecuadas: la secuencialidad (A) puede prolongar la exposición al riesgo y retrasar la recuperación; la intervención paralela (C) conlleva la duplicación de recursos y puede generar conflictos de tratamiento; y priorizar el trastorno más grave (D) no garantiza la resolución del otro problema y puede perpetuar la comorbilidad.'),
  (733, 'En la fase de estabilización del tratamiento de trastornos traumáticos y disociativos, el objetivo primordial es crear un entorno seguro y establecer una relación terapéutica fiable que permita al paciente desarrollar habilidades de regulación emocional y de afrontamiento; esta estrategia facilita la posterior exploración de los recuerdos traumáticos y la integración de la experiencia disociativa, pues sin una base de seguridad el riesgo de reviviscencia y disociación aumenta y el proceso terapéutico se vuelve inestable. Las opciones A y D se refieren a etapas posteriores de procesamiento e integración, no a la estabilización inicial; la opción B describe un enfoque centrado en el apego, que aunque relevante, no constituye el objetivo primario de la fase de estabilización, por lo que las tres alternativas restantes son incorrectas.'),
  (734, 'La descripción coincide con los criterios de la CIE‑11 para el trastorno de estrés postraumático complejo, pues combina los síntomas clásicos de intrusión, reexperimentación, hipervigilancia y evitación con un patrón de alteraciones afectivas profundas, autocrítica extrema y dificultades interpersonales que caracterizan la disfunción en la regulación emocional propia del trastorno complejo; además, la presencia de creencias de inferioridad y sentimientos de vergüenza y culpa son elementos específicos que distinguen al trastorno complejo del trastorno de estrés postraumático ordinario. Las otras opciones son inadecuadas: el trastorno de identidad disociativo se centra en la fragmentación de la identidad y la pérdida de memoria, sin el componente de intrusión y evitación tan marcado; el trastorno límite de la personalidad se caracteriza por impulsividad, inestabilidad afectiva y relaciones interpersonales caóticas, pero no incluye los síntomas de intrusión y hipervigilancia típicos del PTSD; el trastorno de estrés agudo se limita a la fase inicial post‑evento y no contempla la persistencia de síntomas ni la disfunción afectiva y relacional tan extensa que se describe.'),
  (735, 'El tratamiento del trastorno de estrés postraumático (TEPT) se fundamenta en la evidencia de que las intervenciones centradas en el trauma, como la terapia cognitivo-conductual con exposición (TEP) o la terapia de procesamiento cognitivo, son las más eficaces; la recomendación de que se ofrezcan independientemente del tiempo transcurrido desde el evento se basa en la constancia de la eficacia de estas intervenciones tanto en fases tempranas como en etapas tardías de la recuperación, siempre que el paciente esté clínicamente estable, y no se requiere un periodo de espera prolongado. En contraste, la opción A propone un debriefing de una sola sesión, lo cual está contraindicado por estudios que muestran riesgo de empeoramiento y falta de beneficio sostenido. La opción B favorece tratamientos no centrados en el trauma, como la terapia de apoyo o la terapia de relajación, los cuales no abordan los recuerdos intrusivos ni las distorsiones cognitivas que mantienen el TEPT, por lo que no son la primera elección. La opción D privilegia la farmacoterapia como primera opción, aunque los fármacos pueden ser útiles como complemento o en casos de comorbilidad, la literatura indica que la terapia psicológica centrada en el trauma debe preceder a la medicación. Así, la alternativa C se sostiene clínicamente mientras que las demás presentan errores conceptuales o de práctica.'),
  (736, 'El fenómeno descrito corresponde a fantosmias, que son alteraciones sensoriales en la percepción del olor que se manifiestan como olores fantasma, a menudo desagradables o inusuales, y son frecuentes en trastornos psicóticos como la esquizofrenia; la interpretación de que “todo huele a gas” y la sospecha de un intento de asesinato refleja una alucinación olfativa típica de la psicosis, donde el paciente confunde estímulos sensoriales reales con una percepción distorsionada. Las acoasmas, por otro lado, implican alteraciones en la percepción del sonido y no se relacionan con olores; los fotomas son alucinaciones visuales que implican la percepción de luces o imágenes, y el síndrome de Cotard se caracteriza por delirios de negación de la existencia del propio cuerpo o de la vida, sin vínculo con alteraciones olfativas.'),
  (737, 'La respuesta d) es la que concuerda con la teoría de la representación dual de Brewin y colaboradores (2003), la cual postula la existencia de dos sistemas de memoria que operan en paralelo: el sistema verbalmente accesible, que procesa la información de manera consciente y secuencial, y el sistema situacionalmente accesible, que almacena la experiencia de manera no verbal, con una codificación espacial y sensorial que se recupera de forma espontánea y no consciente; ambos sistemas se activan simultáneamente cuando se recuerda un suceso traumático, generando la disociación entre la narrativa consciente y la experiencia visceral. Las demás opciones son erróneas porque confunden la naturaleza paralela de los sistemas con una secuencialidad (B y C), o bien describen incorrectamente la naturaleza de la segunda memoria, llamándola “temporalmente accesible” en lugar de “situacionalmente accesible” (A y C), lo que no corresponde a la terminología ni al mecanismo propuesto por Brewin.'),
  (738, 'Los movimientos atetóticos son de tipo involuntario, continuo, lento, de naturaleza sinuosa y sin finalidad específica; se caracterizan por su fluidez y falta de propósito, lo que los diferencia de los movimientos bruscos y rápidos de la corea, de las repeticiones rítmicas y estereotipadas de las estereotipias, y de los movimientos automáticos que ocurren sin conciencia y suelen ser más breves y aislados; por tanto la opción D describe con precisión la definición clínica de atetosis, mientras que las demás alternativas corresponden a manifestaciones distintas: la A describe movimientos bruscos y descoordinados, la B se refiere a repeticiones rítmicas y la C a movimientos automáticos sin intención.'),
  (739, 'La propuesta de Otto Kernberg sobre la organización estructural de la personalidad define la personalidad borderline como una estructura que se caracteriza por un uso dominante de la escisión como mecanismo de defensa, una difusión de identidad que implica una falta de cohesión interna y un egocentrismo que se manifiesta en la dificultad para integrar la propia identidad con la de los demás; además, el juicio de realidad se mantiene relativamente intacto, lo que permite una percepción funcional del entorno. Por tanto, la opción que no corresponde a los elementos constitutivos de la organización borderline es la de egocentrismo, pues Kernberg lo considera un rasgo transitorio que se presenta en la organización psicótica, no en la borderline. Las otras opciones (escisión, difusión de identidad y juicio de realidad mantenido) sí están explícitamente citadas en la teoría de Kernberg como pilares de la estructura borderline.'),
  (740, 'La opción B es la que refleja con precisión los constructos transdiagnósticos nucleares descritos por Barlow et al. (2018) para los trastornos emocionales: la auto‑preocupación neurótica, la percepción de incontrolabilidad e impredecibilidad, las tendencias a la acción impulsadas por la emoción y la evitación emocional; estos elementos constituyen la base de la respuesta emocional disfuncional y la regulación afectiva inadecuada que atraviesa múltiples trastornos. Las demás alternativas fallan porque combinan conceptos que no aparecen simultáneamente en el modelo de Barlow: la opción A sustituye la auto‑preocupación por la atención focalizada en señales de amenaza y añade sesgos cognitivos, lo que corresponde más a los trastornos de ansiedad; la opción C introduce la supresión emocional en lugar de la evitación emocional y cambia la auto‑preocupación por la auto‑percepción neurótica, desviándose del marco transdiagnóstico; la opción D mezcla la atención focalizada con la evitación emocional, pero omite la auto‑preocupación neurótica, por lo que no cumple con la definición completa del constructo.'),
  (741, 'La experiencia descrita corresponde a la autoscopia, un tipo de alucinación extracampina en la que el sujeto percibe una imagen de sí mismo en un espejo o cristal, con la conciencia de que la figura es su propio reflejo; la descripción de una consistencia gelatinosa y transparente se ajusta a la caracterización típica de la autoscopia en la literatura clínica, donde la visión se percibe como “poco real” pero con identidad propia. La autotopagnosia implica la incapacidad de reconocer la posición de las partes del propio cuerpo, no la percepción de un doble; las alucinaciones extracampinas comprenden una gama más amplia de fenómenos que incluyen la autoscopia, pero la pregunta pide el término específico, por lo que la opción C es demasiado genérica. La desrealización se refiere a una sensación de desconexión con el entorno externo, sin la percepción de un doble propio, por lo que la opción D también es incorrecta.'),
  (742, 'El síndrome de Charles Bonnet se manifiesta principalmente con alucinaciones visuales complejas y de gran escala que aparecen en pacientes con pérdida de visión significativa; dichas imágenes suelen describirse como “liliputienses” porque los objetos y figuras que se perciben son mucho más grandes que en la realidad, creando una distorsión de tamaño que se asemeja a la exageración típica de la literatura de L. L. Silk; por tanto, la opción A es la que mejor refleja la característica clínica del trastorno. Las demás alternativas son inexactas: la micropsia (B) implica una reducción de tamaño, lo cual es contrario a la ampliación que se observa en Charles Bonnet; la pareidolia (C) se refiere a la percepción de patrones significativos en estímulos ambiguos, pero no constituye la forma dominante de alucinación en este síndrome; y las alucinaciones negativas (D) describen la ausencia de estímulos perceptivos, lo cual no corresponde al fenómeno de alucinaciones visuales intensas que caracteriza al síndrome.'),
  (743, 'Las investigaciones que aplican modelos cognitivos a las alucinaciones auditivas revelan que la interpretación de las voces como benevolentes está asociada a una menor intensidad de malestar; la percepción de benevolencia reduce la amenaza percibida y, por ende, el estrés emocional, lo que explica la relación inversa señalada en la opción C. Las demás alternativas son inconsistentes con la evidencia: la opción A sugiere que la creencia de malevolencia disminuye la perturbación, lo cual contradice la literatura que muestra que la malevolencia aumenta el conflicto interno y la ansiedad; la B afirma que las creencias no influyen en el afecto ni en los patrones de afrontamiento, lo cual es falso porque los estudios demuestran que las interpretaciones cognitivas modulan la respuesta emocional y las estrategias de afrontamiento; y la D plantea que la familiaridad con las voces reduce el compromiso, pero los datos indican que la familiaridad suele aumentar la aceptación y la integración de las voces en la narrativa personal, no suprimir el compromiso.'),
  (744, 'La fase de apofanía de Klaus Conrad describe la aparición de una creencia de que el propio cuerpo está infectado por organismos externos; cuando la persona percibe la presencia de insectos o parásitos en su piel, se trata de un delirio hipocondríaco, pues la convicción es falsa, persistente y no corresponde a una experiencia sensorial real, sino que constituye una interpretación patológica de sensaciones corporales, típica del trastorno delirante de tipo hipocondríaco; las opciones A y B se refieren a alucinaciones, que son percepciones sensoriales sin estímulo externo, y en este caso la percepción se basa en una interpretación errónea de sensaciones reales, no en una alucinación; la opción C describe una creencia disfuncional hipocondríaca, que carece de la intensidad y la convicción delirante que caracteriza al delirio, por lo que se descarta.'),
  (745, 'La opción A es la que se corresponde con la evidencia clínica sobre la duración de los episodios depresivos en el trastorno bipolar frente al unipolar: los episodios de depresión en el trastorno bipolar suelen ser más breves, con una duración media de 2 a 4 semanas, mientras que en el trastorno depresivo mayor la duración típica supera las 6 semanas, a menudo alcanzando 8 a 12 semanas o más, lo que explica la diferencia en la duración. En contraste, la opción B es errónea porque los síntomas catatónicos son más frecuentes en la fase maníaca del trastorno bipolar que en la fase depresiva, y no se asocian de manera significativa con la depresión unipolar. La opción C resulta incorrecta porque, aunque la frecuencia de episodios puede variar, la literatura indica que el trastorno bipolar suele presentar un mayor número de episodios a lo largo de la vida, no el contrario. Finalmente, la opción D es falsa porque los síntomas psicóticos son más típicos de la depresión bipolar, especialmente en la fase maníaca o mixto, mientras que la depresión unipolar suele presentar síntomas psicóticos con menor frecuencia y en un contexto más limitado.'),
  (746, 'El cuidado sistemático del trastorno bipolar comprende la coordinación integral de recursos clínicos, sociales y comunitarios para asegurar continuidad y calidad en la atención; por ello la opción D, que incluye gestión de casos, tratamiento asertivo comunitario y equipos de atención en crisis, describe precisamente esta estrategia de intervención estructurada y multidisciplinaria, alineada con la evidencia de mejora de la adherencia y reducción de recaídas. Las demás alternativas se refieren a modalidades de intervención más específicas: la A señala la terapia centrada en la familia, una técnica psicoeducativa que forma parte del cuidado sistemático pero no lo constituye por sí sola; la B describe un programa intensivo de psicoterapia y farmacología, que sí se integra dentro del cuidado sistemático, pero la opción no refleja la totalidad del enfoque de gestión de casos y atención comunitaria; la C menciona intervenciones psicoeducativas, también componentes del cuidado sistemático, pero nuevamente no abarca la coordinación de servicios y la respuesta a crisis que son esenciales en esta estrategia.'),
  (747, 'El riesgo de suicidio en el trastorno bipolar se estima en 20 a 30 veces mayor que en la población general, cifra respaldada por estudios epidemiológicos que comparan tasas de mortalidad por suicidio entre pacientes con TB y grupos de referencia, y que se mantiene constante a lo largo de la enfermedad; la opción B refleja precisamente ese factor de riesgo cuantitativo, mientras que la A es errónea porque el riesgo es comparable entre TB tipo I y tipo II, con datos que indican que la prevalencia de intentos no difiere de forma significativa entre ambos subtipos; la C es incorrecta ya que la historia de intentos previos y la proporción de días con episodios depresivos son los predictores más robustos de suicidio consumado en TB, tal como lo demuestran los modelos de riesgo clínico; la D se basa en una interpretación errónea de la literatura, pues los estudios no muestran diferencias estadísticamente significativas en la prevalencia de intentos entre TB tipo I y tipo II, por lo que las opciones A, C y D comparten el error de confundir la magnitud del riesgo con la distribución entre subtipos o de negar la validez de los factores de riesgo conocidos.'),
  (748, 'En la entrevista motivacional, “evocar” se refiere al proceso de hacer explícitas las motivaciones del paciente para el cambio, pues consiste en explorar y articular las razones internas que impulsan la voluntad de modificar un comportamiento, lo que permite al profesional identificar y reforzar la ambivalencia y la motivación intrínseca; las demás opciones son incorrectas porque la A describe la alianza terapéutica, la B corresponde al proceso de evaluación y planificación de intervenciones, y la C se relaciona con la dirección de la conversación, pero no con la articulación de motivaciones.'),
  (749, 'El concepto propuesto es la “Evidencia basada en la práctica” (EBP), que se entiende como la recopilación sistemática de datos de la práctica clínica cotidiana para complementar la evidencia empírica derivada de ensayos controlados, con el fin de cerrar la brecha entre investigación y aplicación real; por tanto la opción C es la que corresponde. Las alternativas A y B se centran únicamente en la práctica basada en la evidencia, sin reconocer la necesidad de integrar la experiencia clínica real, y por ello no abordan la problemática planteada. La opción D, aunque menciona la evidencia basada en la práctica, la presenta como una alternativa exclusiva a la práctica basada en la evidencia, lo cual es incorrecto porque la propuesta es complementaria, no sustitutiva.'),
  (750, 'El fenómeno descrito corresponde a una confusión de los límites del yo, ya que el paciente experimenta una dilatación de la frontera entre su identidad y el entorno, percibiéndose como un ente abstracto y fusionado con el entorno, lo que indica una alteración de la percepción de la propia identidad y la de los objetos externos; la pérdida de atribución personal (opción A) implicaría que el paciente no reconoce la autoría de sus propios actos, lo cual no se refleja en la descripción; la disociación del afecto (opción B) se caracterizaría por una desconexión emocional, no por la sensación de fusión con el entorno; y la escisión de la unidad del yo (opción D) implicaría la presencia de dos o más identidades distintas, algo que no se menciona en la situación planteada.'),
  (751, 'El enunciado de Karl Jaspers distingue los delirios primarios de los secundarios por su carácter intrínsecamente inexplicable y su aparición sin un antecedente psíquico claro; por ello la respuesta que indica que “resultan difíciles de comprender y explicar” es la que corresponde, pues los delirios primarios se caracterizan por ser fenómenos de origen no derivado de procesos mentales anteriores y no pueden ser reducidos a explicaciones lógicas o a síntomas de otras patologías. Las opciones A y B son erróneas porque implican que el origen del delirio puede ser delimitado o que surge como consecuencia de otros procesos psíquicos, lo cual describe más bien a los delirios secundarios. La opción C es incorrecta porque sugiere que los delirios primarios son intentos de explicación de experiencias anómalas previas, una característica propia de los delirios secundarios que buscan dar sentido a eventos extraños.'),
  (752, 'La presión del habla se caracteriza por la rapidez con la que el paciente produce el discurso y por la cantidad de material que se expresa en un intervalo corto, reflejando una aceleración de la actividad verbal que suele acompañar a estados de excitación psicomotriz y a la presencia de ideas aceleradas; por ello la opción A es la que recoge los rasgos esenciales de este fenómeno, mientras que las demás alternativas describen aspectos de la presión del habla que son secundarios o pertenecen a otras alteraciones discursivas: la tangencialidad, incoherencia y pérdida de meta (B) se asocian más a la dispersión del pensamiento; la “ensalada de palabras” y la ilogicidad (C) son indicativos de la desorganización del lenguaje; y el pensamiento divagatorio y autorreferencial (D) se relacionan con la autorreferencialidad y la falta de foco, pero no con la velocidad y la cantidad de discurso que definen la presión del habla.'),
  (753, 'La clave que distingue la tangencialidad del descarrilamiento y de la pérdida de asociaciones según Andreasen es que la tangencialidad se manifiesta en las respuestas que el paciente ofrece a las preguntas que se le plantean, sin que se produzcan transiciones espontáneas en el discurso; el paciente se mantiene en la línea de la pregunta pero se desvía de forma deliberada, manteniendo una coherencia interna dentro de la respuesta, mientras que el descarrilamiento implica una ruptura en la continuidad del discurso y la pérdida de asociaciones se caracteriza por la falta de relación entre ideas sin una respuesta estructurada a una pregunta. Por tanto, la opción A es la que describe correctamente este aspecto diferencial. Las demás opciones son incorrectas porque la B incluye la repercusión en las transiciones con el interlocutor, que no es la distinción central; la C habla de respuestas sugeridas con premisas no compartidas, lo cual no corresponde a la definición de tangencialidad; y la D menciona la afectación pragmática por excesivos paréntesis del interlocutor, lo cual tampoco refleja la diferencia planteada por Andreasen.'),
  (754, 'El síndrome afásico descrito se corresponde con la afasia de conducción, ya que se caracteriza por la presencia de parafasias fonémicas frecuentes, una comprensión que suele mantenerse relativamente intacta o con leves alteraciones, una repetición gravemente deteriorada y anomia, lo que coincide con la lesión de la vía arcuata que interconecta las áreas de Broca y Wernicke; en este trastorno la producción espontánea se ve afectada por la pérdida de la capacidad de integrar la información auditiva con la fonética, mientras que la comprensión se preserva porque la vía de comprensión auditiva no está comprometida. Las demás opciones son inadecuadas: la afasia de Broca (A) presenta una repetición preservada y una comprensión más marcada, no la combinación de repetición muy deteriorada y anomia; la afasia anómica amnésica (B) se caracteriza por una anomia severa pero sin parafasias fonémicas tan frecuentes ni un deterioro tan marcado de la repetición; la afasia transcortical mixta (C) mantiene la repetición intacta, lo que contradice la descripción de repetición muy deteriorada.'),
  (755, 'En la epilepsia del lóbulo temporal, la manifestación más frecuente de alucinaciones sensoriales es la olfativa, pues la región temporal incluye la amígdala y la corteza piriforme, estructuras clave en el procesamiento olfativo, y la actividad epileptiforme suele desencadenar episodios de “olor a humo” o “olor a comida” que son típicos de esta localización; la modalidad auditiva, aunque también puede presentarse, es menos frecuente porque la corteza auditiva se ubica en el lóbulo temporal medio y su activación epileptiforme no es tan típica; la visual es poco frecuente porque la corteza visual se encuentra en el lóbulo occipital, no en el temporal; la táctil, por último, se asocia más con epilepsias frontales o parietales. Así, la opción d) se sustenta en la anatomía funcional del lóbulo temporal, mientras que las demás se descartan por la menor incidencia de sus respectivas áreas sensoriales en la epilepsia temporal.'),
  (756, 'La propuesta de Brewin y Andrews (2017) sostiene que la producción de memorias falsas se favorece cuando el contenido evocador incluye detalles personales relevantes que facilitan la integración de la información en la narrativa autobiográfica; por ello la opción B, que describe la creación de imágenes con detalles personales relevantes, es la que más se ajusta a su modelo, pues dichos detalles aumentan la plausibilidad y la sensación de veracidad de la memoria falsa, impulsando la reconstrucción y la consolidación de la misma. Las demás alternativas son incorrectas porque la inducción de recuerdos mediante hipnosis (A) se basa en un mecanismo de sugestión más que en la incorporación de detalles autobiográficos; la presión grupal (C) y la obediencia a la autoridad (D) son procesos sociales que pueden generar confabulaciones, pero no están directamente vinculados al modelo de Brewin y Andrews, que enfatiza la relevancia personal del contenido más que la influencia de factores externos de conformidad o autoridad.'),
  (757, 'La criptoamnesia se caracteriza por la pérdida de acceso consciente a recuerdos de contenido semántico, mientras que el material permanece disponible en la memoria no consciente; por ello, se presenta exclusivamente con información de naturaleza semántica, ya que los recuerdos episódicos o de percepción no se ven afectados de la misma manera. El déjà vu y el jamais vu son fenómenos de percepción de familiaridad o extrañeza que se manifiestan con material perceptivo y no dependen de la semántica; el pseudopresentimiento, por su parte, se refiere a la sensación de que un evento futuro está a punto de ocurrir y se basa en la anticipación, no en la recuperación semántica. Por tanto, solo la criptoamnesia se limita a la pérdida de acceso consciente a material semántico.'),
  (758, 'La hipermnesia se define como una memoria excesiva o una recuperación de información que parece más abundante o vívida de lo habitual, fenómeno que se observa con frecuencia en trastornos disociativos y en algunas formas de amnesia. Este exceso de recuerdo no se debe a una confabulación ni a un error de reconocimiento, sino a una disfunción en el proceso de recuperación que produce una “parapraxia del recuerdo”, es decir, una alteración en la producción de la memoria que se manifiesta como un recuerdo exagerado o incontrolado; por tanto la opción d) es la que corresponde. Las alternativas a) y b) se refieren a errores de reconocimiento (parapraxia o paramnesia del reconocimiento), que implican la identificación incorrecta de estímulos, y no al exceso de recuerdo. La opción c) habla de paramnesia del recuerdo, que implica confabulación o falsos recuerdos, distinto del fenómeno de hipermnesia.'),
  (759, 'El estilo amplificador somatosensorial de Barsky (1992) se conceptualiza como la tendencia a interpretar de forma exagerada y a atribuir mayor significado a las sensaciones físicas, lo que conduce a la búsqueda constante de información somática y a la interpretación de las mismas como indicativas de una amenaza grave; este enfoque fue posteriormente refinado por Köteles y Witthöft, quienes introdujeron el constructo de amplificación de la amenaza somática, manteniendo la idea central de la sobrevaloración de las sensaciones físicas pero incorporando una dimensión más específica de percepción de peligro. Por tanto, la alternativa C refleja fielmente la evolución teórica del concepto. La opción A es incorrecta porque Barsky no se centró en las alteraciones atencionales y valorativas del trastorno dismórfico corporal, sino en la amplificación general de sensaciones somáticas. La alternativa B, aunque menciona la hipervigilancia, no distingue la especificidad del constructo de Barsky, que abarca más que la simple vigilancia. Finalmente, la opción D es errónea porque el estilo amplificador sí contempla variables cognitivas, especialmente la interpretación de la amenaza, y no se limita únicamente a alteraciones atencionales.'),
  (760, 'El fenómeno descrito corresponde a una alucinación refleja, ya que se trata de una experiencia sensorial (audición y sensación táctil) que se produce en ausencia de estímulo externo real y que se asocia a la percepción de una persona que no está presente; la característica de “reflejo” se da cuando la percepción se produce como una respuesta a un estímulo interno o a una actividad cerebral que se interpreta como externa, lo que explica la sensación de golpe en el estómago y la creencia de haber sido agredida por la hermana. Las opciones B y C son incorrectas porque la alucinación sintética implica la creación de una experiencia sensorial que no tiene base en estímulos externos ni internos, y la pseudoalucinación se refiere a una experiencia que se percibe como real pero que en realidad es una fantasía o pensamiento, sin la componente sensorial de la alucinación refleja; la opción D, alucinación funcional, se reserva a los trastornos somatomorfos donde la percepción sensorial se explica por una función psicológica específica, lo cual no se ajusta al caso presentado.'),
  (761, 'La opción D es la que se ajusta a la evidencia clínica: las benzodiacepinas se consideran seguras solo para un uso a corto plazo (2‑4 semanas) porque su uso prolongado aumenta el riesgo de tolerancia, dependencia, síndrome de abstinencia, deterioro cognitivo y caídas, especialmente en población anciana; por ello las guías recomiendan limitar su duración y buscar alternativas. Las alternativas A, B y C son incorrectas porque, al contrario de lo que afirman, existe evidencia clara de que la retirada tras un consumo prolongado produce síntomas de abstinencia; el uso crónico se asocia con deterioro cognitivo y con un mayor riesgo de caídas, por lo que las opciones A, B y C se basan en afirmaciones que contradicen la literatura actual.'),
  (762, 'En la alucinosis alcohólica, la intoxicación y el síndrome de abstinencia generan una alteración neuroquímica marcada por la disfunción de los sistemas dopaminérgicos y glutamatérgicos, lo que favorece la aparición de alucinaciones auditivas, a menudo con contenido persecutorio o de voces críticas; estos síntomas son tan característicos que la literatura clínica los considera casi exclusivos de este cuadro. En contraste, el episodio maníaco suele presentar ideaciones grandiosas y delirios de grandeza, pero las alucinaciones auditivas son poco frecuentes y, cuando aparecen, suelen ser de naturaleza ideológica más que sensorial; la depresión mayor, aunque puede incluir alucinaciones, las presenta en menor proporción y generalmente de tipo visual o olfativo, no auditivo; el delirium, por su parte, se caracteriza por alteraciones de la conciencia y la percepción, pero las alucinaciones auditivas son raras, ya que el foco principal es la confusión y la desorientación. Por tanto, la opción C es la que mejor se ajusta a la frecuencia clínica de alucinaciones auditivas.'),
  (763, 'La faceta de suspicacia se sitúa dentro del dominio de Desapego del modelo alternativo del DSM‑5, ya que el Desapego se caracteriza por la evitación de la intimidad y la desconexión emocional; la suspicacia refleja una tendencia a desconfiar de los demás y a mantener distancia, lo que concuerda con la falta de vinculación afectiva típica de este dominio. Las demás opciones son incorrectas porque Psicoticismo (A) se refiere a la tendencia a la percepción distorsionada y la falta de realismo, Desinhibición (B) implica impulsividad y búsqueda de estimulación, y Antagonismo (C) se relaciona con la hostilidad y la manipulación; ninguno de estos dominios captura la característica de desconfianza y evitación social que define la suspicacia.'),
  (764, 'El modelo de cascadas emocionales de Selby y Joiner (2009) sostiene que la desregulación emocional en el trastorno límite de la personalidad se intensifica cuando la experiencia emocional negativa se mantiene activa y se vuelve más difícil de regular; la rumiación sobre estos aspectos emocionales negativos constituye precisamente ese mecanismo de mantenimiento, ya que prolonga la activación fisiológica y cognitiva, generando un círculo vicioso de intensidad y duración de la emoción que favorece la impulsividad y la autoagresión; las demás opciones, aunque relevantes para la psicopatología del TLP, no describen un proceso que potencie la desregulación emocional en el marco de las cascadas: la persistencia de la desorganización del apego (A) se relaciona más con la historia temprana y la disfunción relacional, la desconfianza epistémica (B) se vincula con la percepción de la realidad y la interpretación de la información, y las diadas objetales relacionales rígidas (D) se centran en la calidad de las relaciones interpersonales, pero no en el mecanismo de rumiación que intensifica la cascada emocional.'),
  (765, 'El criterio falso es el de la opción C, pues el DSM‑5 describe la personalidad dependiente como una necesidad excesiva de ser cuidado que se manifiesta en la búsqueda de apoyo y en la sumisión a los demás, pero no incluye la realización voluntaria de actividades que resulten desagradables; la dependencia se caracteriza por la evitación del abandono y la incapacidad para tomar decisiones sin la aprobación de otros, no por la disposición a hacer cosas que no les agraden. En contraste, la opción A se refiere al miedo realista y la preocupación por el abandono, que sí es un rasgo central del trastorno; la opción B describe la dependencia funcional en la toma de decisiones y responsabilidades, otro criterio esencial; y la opción D señala la búsqueda de nuevas relaciones para recibir cuidado tras el fin de una relación estrecha, también una manifestación típica del patrón dependiente. Todas las demás alternativas reflejan correctamente los criterios diagnósticos del DSM‑5.'),
  (766, 'El enunciado que presenta la afirmación falsa es la opción A, porque la tricotilomanía, según el DSM‑5, se clasifica como un trastorno de control de impulsos y no requiere la especificación de introspección ni de creencias delirantes; esos criterios pertenecen a la tricotilomanía cuando se presenta con comorbilidad con trastornos del espectro psicótico, pero no son parte del diagnóstico base, por lo que la frase es incorrecta. En cambio, la opción B es coherente con la descripción del trastorno por acumulación, donde la adquisición excesiva, especialmente la compra, es el patrón más frecuente, y la opción C refleja la alta comorbilidad con trastorno depresivo mayor, que suele aparecer después del TDC, y la opción D cumple con el requisito de intentos repetidos de detener el rascarse, tal como lo exige el DSM‑5.'),
  (767, 'La opción B es la única que se ajusta a la evidencia actual sobre la prevención de la psicosis en personas con estados mentales de alto riesgo (EMAR); los estudios de cohorte y los ensayos clínicos sistemáticos no han identificado una intervención con eficacia demostrada y consistente, por lo que la comunidad científica no ha podido establecer una recomendación sólida ni un protocolo de tratamiento universalmente aceptado, y la práctica clínica se basa en la individualización del caso. Las demás alternativas se basan en premisas infundadas: la A presupone una superioridad de la psicofarmacología frente a la psicológica, contradicha por la falta de datos concluyentes y por la evidencia de que los fármacos antipsicóticos no reducen de manera fiable la transición a la psicosis en la fase de alto riesgo; la C afirma que la terapia cognitivo-conductual combinada con intervenciones familiares es el estándar, cuando en realidad la evidencia respalda la necesidad de más investigación antes de declararla estándar; y la D sugiere que las intervenciones basadas en las necesidades son desaconsejadas, aunque la literatura muestra que su eficacia es variable y no se ha descartado su utilidad en ciertos contextos.'),
  (768, 'La terapia de mejora cognitiva (CET) de Hogarty y Greenwald se centra en la rehabilitación de los déficits cognitivos que caracterizan a la esquizofrenia, mediante la práctica de tareas que ejercitan la memoria de trabajo, la velocidad de procesamiento y la atención; por ello su objetivo principal es el entrenamiento de la cognición social, es decir, la capacidad de comprender y responder a las señales sociales, lo que se refleja en la opción D, que es la única que describe correctamente la intervención. Las demás opciones son erróneas: la opción A confunde CET con intervenciones orientadas al insight, que son típicas de la terapia cognitivo‑conductual, no de la CET; la opción B es incorrecta porque CET se implementa en la fase crónica o de estabilización, cuando los déficits cognitivos son persistentes, no en la fase aguda; y la opción C es falsa porque CET no es una terapia contextual, sino una intervención basada en la práctica repetida de tareas cognitivas específicas.'),
  (769, 'La terapia de aceptación y compromiso (ACT) aplicada a la psicosis se centra en la distanciamiento funcional del contenido delirante y en la activación de la voluntad para actuar conforme a valores personales; por ello la opción A es la que describe adecuadamente la creación de distancia con respecto al lenguaje delirante y el desarrollo de la voluntad, dos componentes esenciales de ACT que permiten que el paciente experimente sus síntomas sin que estos controlen su conducta. Las demás alternativas son inadecuadas: la B propone reestructurar polaridades semánticas, una técnica más propia de la terapia cognitiva, no de ACT; la C introduce un estado de desesperanza creativa y una sintonización empática con el afecto, conceptos que no se corresponden con la aceptación y el compromiso; y la D habla de un sentido trascendental del yo y una terapia evocadora, que se alejan de la orientación práctica y basada en valores de ACT.'),
  (770, 'El trastorno esquizoafectivo se considera una entidad de baja frecuencia, con estudios epidemiológicos que sitúan su prevalencia vital en torno al 0,3 % de la población general; además, la literatura indica que la incidencia es mayor en mujeres que en hombres, lo que explica la opción A, que combina ambos datos. Las demás alternativas son incorrectas porque la opción B atribuye una prevalencia comparable a la de la esquizofrenia, lo cual excede los valores reportados; la opción C mantiene la prevalencia correcta pero invierte el sexo con mayor incidencia; y la opción D eleva la prevalencia a 1,6 %, una cifra que corresponde a la esquizofrenia y no al trastorno esquizoafectivo.'),
  (771, 'La afirmación falsa es la C; el grupo de EMAR con síntomas psicóticos atenuados no se asocia a un mayor riesgo de transición que los demás grupos de riesgo, pues los estudios de cohortes longitudinales han demostrado que el riesgo de convertirse en cuadro psicótico es similar o incluso menor que en los grupos con síntomas de riesgo más severos (por ejemplo, aquellos con síntomas de riesgo psicóticos de mayor intensidad o con antecedentes familiares de psicosis), y la evidencia indica que la progresión depende más de factores como la gravedad de los síntomas, la presencia de comorbilidades y la respuesta al tratamiento precoz que del tipo de EMAR en sí. Por lo tanto, la opción C contradice la literatura actual. Las demás opciones son consistentes con la clasificación y la epidemiología de los EMAR: la A refleja la mayor incidencia de trastornos del espectro esquizofrénico; la B señala que el grupo de síntomas atenuados es el más frecuente; y la D reconoce la heterogeneidad y la evolución no lineal de estos estados mentales.'),
  (772, 'La opción B es la única que refleja la evidencia de que los modelos de intervención familiar psicoeducativa para la esquizofrenia deben integrar la comprensión de la etiología sistémica, es decir, que la dinámica familiar y la comunicación contribuyen a la aparición y mantenimiento de la enfermedad; por ello, los programas que omiten este componente carecen de la base teórica necesaria para modificar los patrones de interacción que perpetúan la sintomatología y la crisis. En contraste, la alternativa A describe una eficacia limitada que no se corresponde con los estudios meta‑analíticos que demuestran reducciones significativas en la carga familiar y la expresión emocional, así como en la frecuencia de hospitalizaciones cuando se aplican intervenciones estructuradas y basadas en la psicoeducación. La opción C es incorrecta porque la literatura indica que la duración prolongada y la flexibilidad de los programas, más que la brevedad, favorecen la consolidación de habilidades y la prevención de recaídas. Finalmente, la alternativa D se equivoca al privilegiar los abordajes unifamiliares; los datos muestran que los programas multifamiliares, que incluyen grupos de apoyo y la interacción entre familias, ofrecen ventajas en la reducción del aislamiento y la mejora de la calidad de vida, superando a los unifamiliares.'),
  (773, 'La reducción de la sobrestimulación ambiental se prioriza en la fase aguda de la esquizofrenia porque durante este período los síntomas psicóticos (delirios, alucinaciones, pensamiento desorganizado) están en su punto máximo y el entorno puede exacerbar la ansiedad, la confusión y la desorientación del paciente; limitar la carga sensorial facilita la estabilización clínica y la respuesta a la medicación antipsicótica, favoreciendo la reducción de la agitación y la mejora de la percepción del entorno. En la fase prodrómica la sobrestimulación no suele ser el factor dominante, pues los síntomas son leves y la intervención se centra en la prevención y el reconocimiento temprano; en la fase de estabilización y en la fase estable el objetivo es consolidar la recuperación y promover la reintegración social, por lo que la atención se orienta a la reeducación psicosocial y la prevención de recaídas, no a la reducción de estímulos.'),
  (774, 'La fase de comprobación empírica de las creencias delirantes consiste precisamente en evaluar la validez de la idea delirante y de una alternativa no delirante mediante la exposición a pruebas concretas, lo que permite contrastar la evidencia y generar una reestructuración cognitiva; por ello la opción D es la única que refleja el procedimiento correcto, ya que la terapia exige poner a prueba simultáneamente ambas hipótesis para evitar la confirmación parcial y favorecer la disociación de la creencia. Las demás alternativas son incorrectas: la opción A describe un orden inverso al que establece la práctica clínica, donde el análisis verbal precede a la comprobación empírica; la opción B presupone que la comprobación empírica aislada es igualmente eficaz, lo cual no se ha demostrado y contradice la necesidad de integrar el análisis verbal para contextualizar la creencia; la opción C confunde la fase de análisis lógico, que se realiza antes de la comprobación empírica, con la fase de prueba de hipótesis, por lo que la lógica interna se evalúa en la etapa previa, no en la fase de comprobación.'),
  (775, 'La opción D corresponde a la terapia cognitivo‑conductual de Kingdon y Turkingon, la cual incorpora la estrategia de normalización racional: el terapeuta explica que los síntomas psicóticos son respuestas cognitivas normales ante experiencias amenazantes, los desestigmatiza y los deja abiertos a la discusión racional, lo que reduce la ansiedad y la resistencia al tratamiento; esta técnica se basa en la teoría de la normalización de la experiencia psicótica y se diferencia de las demás porque combina la reestructuración cognitiva con la exposición gradual a los síntomas. Las alternativas A, B y C no emplean la normalización racional; la terapia de Tarrier se centra en la potenciación de estrategias de afrontamiento sin un enfoque de normalización, la terapia metacognitiva interpersonal se orienta a la regulación metacognitiva y la terapia cognitiva de Chadwick, Birchwood y Tower enfatiza la reestructuración de creencias disfuncionales sin la misma estrategia de desestigmatización de los síntomas.'),
  (776, 'La afirmación falsa es la B: la PBCT no pretende que el paciente enfrente los síntomas de forma directa; al contrario, su objetivo es modificar la relación que mantiene con las experiencias estresantes, fomentando la aceptación y la conciencia plena, al igual que la TACE, pero con un enfoque más centrado en la reestructuración de esquemas y la integración del yo; las demás opciones describen adecuadamente la PBCT: la A señala el trabajo con esquemas negativos y la creación de esquemas positivos; la C reconoce que el significado sintomático es una dimensión central que abarca delirios, voces y síntomas primarios; y la D refleja la concepción de un yo simbólico complejo, cambiante y emocionalmente variado que la PBCT promueve.'),
  (777, 'La propuesta de Beutler et al. (2000) y la psicoterapia prescriptiva sostiene que el cambio terapéutico se maximiza cuando el paciente se enfrenta a estímulos que provocan evitación conductual y emocional, pues la exposición activa a estos estímulos facilita la desensibilización y la reestructuración cognitiva; por ello la opción d) refleja la premisa central de la terapia basada en la exposición, que se ha demostrado eficaz en trastornos de ansiedad y en la reducción de conductas de evitación. Las demás alternativas son incorrectas porque la opción a) contradice la evidencia de que el deterioro funcional sí influye en el pronóstico, la opción b) subestima el papel del apoyo social, que según la literatura es un factor protector y moderador del curso terapéutico, y la opción c) equivoca la recomendación de intervenciones mínimamente estructuradas, las cuales se prefieren en casos de afrontamiento centrado en la tarea, pero no son la única estrategia aconsejable.'),
  (778, 'La terapia de enfoque modular propuesta por Chorpita y Weisz (2009) se basa en la idea de que los trastornos infantiles comparten procesos transdiagnósticos y que el tratamiento debe ser individualizado; por ello, el protocolo contempla una selección de módulos terapéuticos que se eligen según la gravedad y los problemas identificados en la entrevista inicial con el menor y sus cuidadores, permitiendo adaptar la intervención a la presentación clínica concreta, lo que explica la opción D; las demás alternativas son incorrectas porque la propuesta no se limita a un formato grupal (A), no prescribe un flujo rígido sin variaciones (B), y no incluye 33 módulos centrados en mecanismos transdiagnósticos desde un enfoque sistémico (C).'),
  (779, 'La opción A es la que refleja la práctica clínica más frecuente en los enfoques familiares para el trastorno negativista desafiante, ya que la literatura especializada indica que el manejo de conflictos y el entrenamiento en habilidades de comunicación son las técnicas de intervención primaria que mejor abordan la dinámica familiar y la relación padre‑hijo, reduciendo la incidencia de conductas desafiantes; en contraste, la opción B se basa en una guía NICE que, aunque valiosa, recomienda intervenciones multimodales y no se limita exclusivamente a la familia, por lo que no es la técnica más habitual; la opción C confunde la intervención centrada en el niño con el entrenamiento cognitivo, que se dirige principalmente al propio niño y no a la familia; y la opción D, aunque plantea un posible sesgo cultural, carece de evidencia empírica que demuestre una menor eficacia en entornos culturales distintos, por lo que no constituye una afirmación respaldada por la práctica clínica.'),
  (780, 'La opción B es la que corresponde al modelo de psicoterapia familiar de Lieberman (2004) para niños y adolescentes expuestos a violencia contra el cuidador principal, pues la intervención se centra en la regulación emocional y afectiva de ambos miembros de la unidad familiar, buscando construir una narrativa conjunta del trauma que permita la integración de la experiencia y la reparación del vínculo afectivo; este enfoque se basa en la teoría del apego y en la terapia de aceptación y compromiso, pero su esencia clínica radica en la co-regulación emocional y la narrativa compartida. En contraste, la alternativa A menciona procedimientos de aprendizaje social y terapia de aceptación y compromiso sin enfatizar la co-regulación emocional ni la narrativa, por lo que no refleja la especificidad del modelo; la opción C describe un esquema de sesiones individualizadas con intersección ocasional, lo cual no coincide con la práctica de sesiones conjuntas continuas que caracteriza la intervención; y la alternativa D se enfoca en la identificación de pensamientos ansiosos y exposición, aspectos más propios de la terapia cognitivo-conductual individual que no son el núcleo de la psicoterapia familiar de Lieberman.'),
  (781, 'La opción B es la que refleja la realidad clínica de los estados mentales de alto riesgo (EMAR), ya que la literatura de estudios longitudinales muestra que más de la mitad de los individuos con EMAR presentan ideación suicida, lo que constituye un factor de riesgo significativo y exige intervención temprana; en contraste, la opción A confunde la evolución de los trastornos psicóticos, pues la transición a psicosis afectiva es menos frecuente que a trastornos del espectro esquizofrénico; la opción C es errónea porque, aunque algunos EMAR no evolucionan a un trastorno psicótico pleno, la ausencia de diagnóstico no elimina la necesidad de seguimiento y posibles tratamientos preventivos; y la opción D, aunque suena plausible, carece de evidencia robusta y la iniciación precoz de antipsicóticos en adolescentes con EMAR no se ha demostrado que reduzca de manera concluyente el riesgo de psicosis, por lo que su afirmación es infundada.'),
  (782, 'El trastorno de ansiedad por separación se caracteriza por una angustia desproporcionada ante la separación de figuras de apego, con síntomas que aparecen típicamente entre los 3 y 6 años, aunque puede diagnosticarse en edades más avanzadas; la literatura clínica indica que la prevalencia es similar en ambos sexos, por lo que la opción C refleja la distribución equitativa por género que se observa en estudios de población clínica, donde no se detectan diferencias significativas entre varones y mujeres. La alternativa A es incorrecta porque la edad de aparición no se limita a los 7 años y el diagnóstico puede establecerse en cualquier edad, siempre que se cumplan los criterios; la presencia de síntomas similares en adolescentes y adultos no excluye el trastorno de ansiedad por separación, sino que puede coexistir con otros trastornos. La opción B es errónea porque el trastorno obsesivo‑compulsivo no es el diagnóstico comórbido más frecuente en niños de 4‑6 años; las comorbilidades más habituales son trastornos de ansiedad generalizada, trastornos de conducta y trastornos del desarrollo. Finalmente, la respuesta D describe una situación de miedo a una crisis de pánico, lo cual se relaciona más con el trastorno de pánico o el trastorno de ansiedad generalizada, no con la ansiedad por separación, que se centra en la separación de figuras de apego y no en la ausencia de ayuda ante una crisis.'),
  (783, 'La terapia familiar funcional (Sexton et al., 2004) se fundamenta en la premisa de que los comportamientos problemáticos de cada miembro de la familia, incluido el adolescente con conductas adictivas, cumplen una función dentro del sistema familiar; por ello, la intervención busca identificar y modificar las contingencias que refuerzan dichos comportamientos, manteniendo la perspectiva de que tanto las conductas adaptativas como las disfuncionales pueden tener un valor funcional, lo que explica la opción C; las demás alternativas son incorrectas: la opción A describe una estructura de fases que corresponde a la terapia familiar sistémica tradicional, no a la funcional; la opción B reduce la conducta a una desviación del desarrollo, sin considerar la función dentro del contexto familiar; y la opción D mezcla elementos de distintas corrientes (modificación de conducta, estructural y estratégica) que no son inherentes a la terapia funcional, la cual se centra principalmente en la función de los comportamientos y la dinámica de refuerzo dentro de la familia.'),
  (784, 'La terapia multidimensional del duelo (Hill et al., 2019) se define como una intervención psicosocial integral cuyo objetivo es disminuir la pena, los síntomas de depresión y de estrés postraumático, al mismo tiempo que facilita la búsqueda de sentido en la pérdida y fomenta el desarrollo adaptativo de niños y adolescentes; esta descripción coincide con la opción A, pues la propuesta de Hill incorpora componentes psicoeducativos, narrativos y conductuales que abordan tanto la dimensión emocional como la cognitiva del duelo, y se aplica en formato individual o grupal, con énfasis en la resiliencia y la adaptación. Las demás alternativas son inexactas: la B confunde el enfoque con un programa exclusivamente grupal y omite la dimensión de dolor traumático; la C presenta la intervención como exclusivamente familiar y centrada en la resiliencia, sin mencionar los componentes psicoeducativos y narrativos; la D describe una estructura de actividades separadas para cuidadores y niños, lo cual no corresponde al modelo multidimensional que integra las experiencias de ambos en conjunto, por lo que las opciones B, C y D son incorrectas.'),
  (785, 'La opción C es la que se ajusta a la evidencia clínica sobre la evolución de los trastornos infantiles y juveniles: muchos problemas que se presentan en la infancia, como conductas desafiantes, ansiedad social o trastornos de aprendizaje, pueden modificarse o incluso desaparecer con el desarrollo normal, sin necesidad de intervención psicológica intensiva, siempre que se realice una valoración adecuada y se monitorice la evolución; por ello, la intervención debe priorizarse cuando la conducta persiste, se agrava o interfiere significativamente con el funcionamiento funcional, evitando el tratamiento de problemas que son parte del desarrollo típico. Las demás alternativas son incorrectas porque la opción A subestima la autonomía del niño y la importancia de la perspectiva clínica sobre la demanda parental; la opción B presupone que la participación parental debe incrementarse linealmente con la edad, lo cual no se sostiene, ya que la participación disminuye a medida que el adolescente busca mayor independencia; y la opción D promueve la atención a conductas no observables, lo que contradice la práctica basada en la observación directa y la medición objetiva de los síntomas.'),
  (786, 'El modelo más idóneo para abordar la hetero‑agresividad en un niño con TEA dentro del aula es la intervención basada en antecedentes, pues permite identificar y modificar los estímulos discriminativos que provocan la conducta agresiva, alterando los antecedentes positivos o negativos y reforzando sustitutos funcionales; este enfoque se fundamenta en la teoría del análisis conductual aplicada, donde la prevención de la agresión se logra al cambiar el entorno y las señales que desencadenan la conducta, algo esencial en el contexto escolar donde la interacción social es constante. Las otras opciones son insuficientes o insuficientemente específicas: el refuerzo (A) solo modifica la frecuencia de la conducta sin abordar sus causas subyacentes; la espera estructurada (B) se centra en la regulación emocional y no en la prevención de la agresión; y la intervención basada en familias (C) es valiosa para la generalización, pero no sustituye la modificación directa de los antecedentes que ocurren en el aula.'),
  (787, 'La opción A es falsa porque la literatura sobre psicoterapia infantil indica que los padres tienden a aceptar con mayor facilidad las intervenciones orientadas a aumentar los comportamientos positivos, ya que perciben estos objetivos como más constructivos y menos críticos de la conducta del niño; en contraste, las estrategias que se enfocan en reducir los comportamientos negativos suelen generar mayor resistencia porque implican una valoración negativa del comportamiento actual del niño. Por otro lado, la opción B es verdadera: el Inventario de Alianza de Trabajo (IAT) se ha validado principalmente en adultos y su uso en niños pequeños resulta inapropiado debido a la falta de madurez cognitiva y a la necesidad de adaptar la escala a la edad. La opción C también es verdadera, pues refleja la tendencia de los padres a aceptar más las intervenciones que promueven conductas positivas. Finalmente, la opción D es correcta, ya que la evaluación de las características individuales de los cuidadores (por ejemplo, su estilo de crianza, nivel de estrés y recursos emocionales) es esencial para adaptar la intervención y maximizar la alianza terapéutica.'),
  (788, 'El DSM‑5 define el trastorno de movimientos estereotipados como una alteración del control motor que se manifiesta en movimientos repetitivos, involuntarios y sin un objetivo funcional claro, típicamente observados en niños y que pueden incluir conductas autolesivas; por ello la opción C es la que coincide con la descripción diagnóstica, pues la autolesión es una manifestación posible dentro de este trastorno. La alternativa A es incorrecta porque el DSM‑5 no especifica una edad mínima de aparición, y la edad de dos años no es un criterio diagnóstico; la opción B es errónea al afirmar que los movimientos tienen un aparente objetivo, cuando la característica esencial es la falta de propósito funcional; y la D es inexacta porque la tricotilomanía se clasifica como un trastorno de control de impulsos distinto, no como parte de los movimientos estereotipados.'),
  (789, 'La terapia de claves traumáticas se constituye como una intervención cognitivo-conductual que integra la psicoeducación, la reestructuración cognitiva y la exposición dirigida a estímulos clave, con el objetivo de desensibilizar la respuesta emocional y cognitiva asociada al trauma; este enfoque se basa en la premisa de que la exposición gradual a los recuerdos y a los desencadenantes específicos permite la reestructuración de las interpretaciones disfuncionales y la consolidación de nuevas asociaciones más adaptativas, lo que se refleja en la reducción de la sintomatología postraumática. Las demás opciones son incorrectas porque la A describe la terapia de desensibilización y reprocesamiento por movimientos oculares (EMDR) aplicada a menores, no la terapia de claves; la B se refiere a un abordaje psicodinámico, que no corresponde al modelo cognitivo‑conductual de la terapia de claves; y la C menciona un tratamiento de “traumas tipo 1”, término que no se emplea en la literatura clínica ni en la descripción de la terapia de claves.'),
  (790, 'El diagnóstico de trastorno de la personalidad en la infancia y adolescencia se permite cuando los rasgos desadaptativos son generalizados, consistentes a lo largo del tiempo y se han mantenido durante al menos un año, tal como establece el criterio de la DSM‑5 y la práctica clínica; la presencia de una duración mínima de un año garantiza la estabilidad del patrón y evita la confusión con episodios transitorios de crisis de desarrollo o de otras patologías. Las opciones A y B son erróneas porque la edad no es el único factor determinante y el diagnóstico sí puede realizarse en preadolescentes cuando se cumplen los criterios de duración y consistencia. La opción C es incorrecta porque no se limita a casos “excepcionales de extrema gravedad”; la normativa no establece tal restricción, sino que exige la estabilidad y generalización de los rasgos.'),
  (791, 'La adaptación de la terapia dialéctico conductual (TDC) para adolescentes incorpora un quinto módulo denominado “Caminando por el sendero del medio”, que integra la práctica de la atención plena con la regulación emocional y la tolerancia a la angustia, adaptado a la etapa de desarrollo donde la búsqueda de identidad y la necesidad de autonomía son predominantes; este módulo facilita la aplicación de las habilidades de TDC en contextos escolares y familiares, manteniendo la coherencia con la estructura de los cuatro módulos originales (mindfulness, regulación emocional, tolerancia a la angustia y efectividad interpersonal). Las demás opciones son erróneas: la opción A es falsa porque la atención plena es un pilar central de la TDC y se mantiene en la versión para adolescentes; la opción B describe un entrenamiento que no es específico de la TDC y no forma parte de su estructura modular; y la opción D, aunque la teoría biosocial se comparte con la familia, no se expone “a toda la familia” como un componente de la adaptación, sino que se integra de forma más limitada en la intervención familiar.'),
  (792, 'La adaptación de la terapia dialéctica conductual (TDC) a la población adolescente fue desarrollada por Alec L. Miller y Jill H. Rathus, quienes diseñaron un protocolo específico que incorpora la estructura de la TDC para adultos con la necesidad de trabajar con la madurez emocional y la autonomía de los menores, integrando sesiones familiares y estrategias de motivación adaptadas a la etapa de desarrollo; la evidencia clínica muestra que esta versión mejora la regulación emocional y reduce los comportamientos autolesivos en adolescentes, manteniendo la coherencia con los principios de la TDC original. Las demás opciones son incorrectas: la opción B corresponde a una autora que ha trabajado en la TDC pero no en su adaptación adolescente; la opción C se refiere a un psiquiatra australiano especializado en salud mental juvenil, pero no en la TDC; y la opción D es un investigador que ha contribuido a la psicología clínica, pero no a la adaptación de la TDC para adolescentes.'),
  (793, 'La afirmación falsa es la B, pues la evidencia empírica indica que los menores con ansiedad social suelen responder de manera más eficaz a intervenciones grupales que a las individuales; el contexto grupal facilita la exposición social en un entorno seguro y la práctica de habilidades sociales con pares, lo que favorece la generalización y la reducción de la evitación, mientras que el tratamiento individual, aunque útil, no aprovecha la dinámica de grupo que constituye un factor terapéutico clave en la ansiedad social. En contraste, la opción A se sustenta en numerosos ensayos controlados que han mostrado equivalencia entre la terapia cognitivo-conductual online y la presencial en la reducción de síntomas de ansiedad; la opción C es cierta porque el mutismo selectivo es un trastorno poco frecuente y los estudios con diseños rigurosos son escasos, lo que limita la evidencia de eficacia de las intervenciones; y la opción D se alinea con las guías de práctica clínica, las cuales recomiendan enfoques familiares basados en la TCC para la primera infancia, integrando a los cuidadores en la exposición y la modificación de patrones de interacción que refuerzan la ansiedad.'),
  (794, 'La terapia de inversión del hábito, también conocida como entrenamiento en respuesta competitiva (ERC), se fundamenta en la premisa de que el tics son respuestas automáticas que pueden ser suprimidas mediante la conciencia y la sustitución de una respuesta contraria; por ello, el componente esencial es el entrenamiento en conciencia, que permite al niño o adolescente identificar el antecedente y la sensación de urgencia que precede al tic, y el entrenamiento en respuesta competitiva, que enseña una conducta alternativa que compite con la tics y que puede ser mantenida bajo la misma condición de estímulo; el apoyo social, ya sea de la familia o del entorno escolar, facilita la generalización y el mantenimiento de la conducta aprendida al reforzar la práctica y la motivación. Las demás opciones fallan porque omiten el elemento de conciencia (A, B, C) o sustituyen la conciencia por instigación (B) o práctica lúdica (A, C), lo que no corresponde a la metodología establecida; además, la inclusión de refuerzo positivo en lugar de apoyo social (B, C) no cubre la dimensión de contextualización y sostenibilidad que el apoyo social brinda en la infancia y adolescencia.'),
  (795, 'El modelado en vídeo es la piedra angular de la intervención “Los años increíbles” (The Incredible Years), donde se emplean grabaciones de conductas modelo (por ejemplo, estrategias de disciplina y comunicación) que los padres y los niños observan y luego practican, reforzando la adquisición de habilidades sociales y conductas adaptativas; en contraste, la Terapia Morita se basa en la aceptación de la ansiedad sin técnicas de modelado visual, Cool Little Kids utiliza la técnica de juego simbólico y la terapia de interacción padres-hijos (PCIT) se centra en la retroalimentación auditiva y en la práctica en vivo, sin recurrir a material audiovisual como recurso principal.'),
  (796, 'El modelo funcional de autolesiones de Nock y Prinstein (2004) se fundamenta en la idea de que la conducta autolesiva cumple funciones distintas que pueden clasificarse en cuatro grandes grupos: auto‑recompensa (refuerzo positivo), auto‑castigo (refuerzo negativo), regulación emocional y comunicación interpersonal; por ello la opción B es la única que refleja fielmente la estructura propuesta por los autores, que distingue explícitamente estos cuatro dominios funcionales y los relaciona con la motivación subyacente de la autolesión. Las demás alternativas fallan porque la opción A sugiere una variación de intervención según el nivel de alteración funcional, algo que el modelo no contempla, pues se centra en la identificación de funciones, no en la adaptación de tratamientos; la opción C se enfoca en el riesgo, mientras que el modelo de Nock y Prinstein se orienta a la función de la conducta, no a su peligrosidad; y la opción D atribuye la autolesión a la disociación, una hipótesis que no es parte de la teoría de Nock y Prinstein, quien la vincula más con la regulación emocional y la comunicación.'),
  (797, 'El tratamiento que contempla la fase de establecer una independencia saludable en la infancia y adolescencia con trastornos de la conducta alimentaria es la terapia basada en la familia, pues su marco teórico enfatiza la transición de la dependencia familiar a la autonomía individual, integrando a los padres como agentes de apoyo y facilitadores del desarrollo de habilidades de afrontamiento y autocuidado del paciente, lo que permite la consolidación de una identidad propia y la regulación de la alimentación en un contexto de supervisión gradual; la terapia cognitivo‑conductual mejorada se centra en la reestructuración de pensamientos y conductas alimentarias sin un énfasis explícito en la independencia, la terapia sistémica estratégica se orienta a la resolución de problemas familiares inmediatos y la terapia interpersonal se enfoca en las relaciones interpersonales y la afectividad, pero no aborda directamente la transición a la autonomía.'),
  (798, 'La opción B es la que refleja la realidad clínica del tratamiento infantojuvenil: en numerosos trastornos, como la depresión mayor, el trastorno de ansiedad generalizada o el trastorno obsesivo‑compulsivo, la práctica habitual favorece la prescripción de fármacos, lo que conduce a una medicalización del problema y a efectos adversos bien documentados (sedación, alteraciones del apetito, problemas de crecimiento, riesgo de abuso, etc.); la evidencia indica que la intervención farmacológica no sustituye a la psicoterapia, sino que a menudo la complementa, y su uso indiscriminado puede generar más complicaciones que beneficios. Las demás alternativas son erróneas: la A sobreestima la falta de acceso a psicoterapia, pues los datos actuales muestran una brecha menor, aunque todavía significativa, pero no tan alta; la C es falsa porque la psicoterapia no se prioriza por la ausencia de efectos adversos, sino por su eficacia y la ausencia de efectos secundarios graves; la D subestima la prevalencia de trastornos infantiles, ya que estudios epidemiológicos indican que entre el 20% y el 30% de los niños y adolescentes presentan trastornos que pueden beneficiarse de intervenciones psicológicas, pero la cifra exacta no coincide con el 25% propuesto.'),
  (799, 'El tratamiento “The Incredible Years” es un programa de intervención familiar y familiarizada que se centra en la modificación de la conducta del niño a través del entrenamiento de los padres, con el fin de mejorar la disciplina, la comunicación y la relación familiar; por ello la opción D es la que describe adecuadamente su objetivo principal, ya que el programa se dirige a los cuidadores de niños con trastorno desafiante‑oposicionista, enseñándoles estrategias de refuerzo positivo, límites consistentes y manejo de la frustración. La alternativa A es incorrecta porque el enfoque no se limita al niño y al adolescente, sino que se centra en la familia, y el programa está diseñado para niños de edad temprana, no específicamente adolescentes. La opción B es errónea porque el protocolo se adapta a la edad y etapa de desarrollo del niño, con módulos diferenciados para preescolar, escolar y adolescencia, y no se aplica de forma idéntica en todas las edades. La respuesta C también es falsa: aunque el programa puede tener efectos indirectos sobre el rendimiento escolar al mejorar la conducta y la autoestima, su objetivo explícito no es mejorar el rendimiento académico, sino la conducta y la relación familiar.'),
  (800, 'La guía NICE 2019 recomienda, para la depresión moderada en niños y adolescentes, iniciar con terapia interpersonal basada en la familia (IPT‑F) porque la evidencia muestra que la intervención centrada en la dinámica familiar y la mejora de la comunicación y el apoyo emocional reduce los síntomas depresivos y mejora el funcionamiento funcional en esta edad; además, la IPT‑F es la única modalidad psicológica que la guía clasifica como “intervención de primera línea” para la depresión moderada en menores, con un perfil de riesgo bajo y sin necesidad de medicación inicial. En contraste, la opción A propone tratamiento farmacológico de entrada, lo cual la guía desaconseja salvo en casos de depresión severa o cuando la terapia psicológica no es viable; la opción B sugiere una terapia cognitivo‑conductual (TCC) con un esquema de abandono prematuro y posterior introducción de antidepresivos, pero la TCC no está indicada como primera línea para la depresión moderada en menores según NICE, y el protocolo de suspender tras 4‑6 sesiones carece de respaldo empírico; la opción C combina IPT‑F con psicofármacos, pero la guía indica que la combinación no aporta beneficio adicional frente a la IPT‑F sola en esta población y puede aumentar el riesgo de efectos adversos sin mejora clínica demostrada. Por tanto, la alternativa d es la que se alinea con las directrices de NICE y la evidencia disponible.'),
  (801, 'La recomendación de que los niños vuelvan al colegio cuanto antes tras el fallecimiento del padre se basa en la evidencia de que la continuidad de la rutina escolar favorece la estabilidad emocional y la adaptación, ofreciendo un entorno estructurado y apoyo de pares y docentes que facilita la expresión de emociones y la reconstrucción de la identidad; al contrario, la opción A sugiere una protección mediante la negación que impide la integración de la experiencia y aumenta el riesgo de trastornos de ansiedad, la opción B, aunque reconoce la importancia de la expresión emocional, no contempla la necesidad de un marco de referencia adecuado para la edad y puede sobrecargar a los niños con emociones que no pueden procesar; la opción C, al simplificar la muerte con la frase “está durmiendo para siempre”, introduce una narrativa falsa que puede generar confusión y dificultades para aceptar la realidad, especialmente cuando el niño de 5 años ya está en una etapa de comprensión más concreta del concepto de muerte.'),
  (802, 'La afirmación falsa es la opción A, pues la evaluación de las fobias infantiles no se limita al niño a partir de los cinco años; la edad de inicio de la valoración debe ser temprana, incluso en niños menores, porque la detección precoz facilita la intervención y reduce la consolidación de conductas de evitación; además, la literatura indica que la edad de inicio de la fobia suele ser antes de los cinco años y que la evaluación temprana permite identificar factores de riesgo y proteger al desarrollo; las demás opciones son coherentes con la práctica clínica: la opción B señala que los adultos suelen subestimar la gravedad de las fobias infantiles, un sesgo que se documenta en estudios de percepción parental; la opción C resalta la importancia de observar la reacción de los padres ante la fobia, ya que su respuesta puede reforzar o mitigar la ansiedad del niño; y la opción D subraya la necesidad de conocer las conductas de afrontamiento del niño, pues estas indican la gravedad y la posible intervención. Todas las demás opciones, por tanto, se sustentan en principios de evaluación y tratamiento de las fobias infantiles.'),
  (803, 'El trastorno de desregulación disruptiva del estado de ánimo se define como una alteración marcada de la regulación emocional que se manifiesta en episodios de irritabilidad crónica, explosiones de ira y conductas agresivas, con una frecuencia y duración que exceden la típica variabilidad emocional infantil; su diagnóstico se basa en la presencia de estos síntomas durante al menos un año, con episodios de al menos tres meses consecutivos, y se diferencia de la conducta desafiante por la intensidad y la falta de un patrón de obediencia o de oposición estructurada, lo que explica por qué la opción C es la que se corresponde con la descripción clínica oficial. La opción A es incorrecta porque la categoría ha sido cuestionada por su falta de evidencia empírica robusta y por la ambigüedad en su delimitación con otros trastornos de la conducta; la opción B es falsa ya que el trastorno no se introdujo con el objetivo de evitar el sobrediagnóstico del TDAH, sino como una respuesta a la necesidad de clasificar la desregulación emocional severa; y la opción D es errónea porque, aunque la impulsividad puede estar presente, la tristeza no es un síntoma característico de este trastorno, que se centra más en la irritabilidad y la agresividad.'),
  (804, 'La opción A es la que se corresponde con la práctica clínica establecida: la valoración de los trastornos de la eliminación debe incluir la búsqueda de señales de abuso o maltrato infantil, ya que la presencia de estos factores aumenta el riesgo de que la eliminación sea un síntoma de trauma y requiere una intervención multidisciplinaria que incluya protección y apoyo psicosocial; además, la detección temprana de maltrato mejora los resultados terapéuticos. En contraste, la opción B es incorrecta porque, aunque el estreñimiento puede contribuir a la encopresis, la intervención médica sola suele resolver menos del 30 % de los casos, y la mayoría requiere terapia conductual y apoyo psicosocial. La alternativa C también es errónea, pues la evidencia muestra que la presencia de un trastorno del neurodesarrollo reduce la eficacia de los tratamientos psicológicos tradicionales para la enuresis, requiriendo enfoques más integrados y personalizados. Finalmente, la respuesta D es falsa, puesto que existen varios tratamientos empíricamente validados para la enuresis nocturna, como los dispositivos de alarma, la terapia cognitivo-conductual y los fármacos antidiuréticos, con evidencia de eficacia en múltiples estudios.'),
  (805, 'La Parent-Infant Psychotherapy (PIP) se centra en la relación madre‑infante y en la transferencia de patrones de vinculación de la madre hacia sus propios progenitores, de modo que la madre pueda identificar y modificar las conductas que afectan el desarrollo emocional y la seguridad del niño; por ello la opción C es la que describe adecuadamente su objetivo terapéutico, pues la intervención busca que la madre comprenda y modifique sus experiencias de apego pasadas para mejorar su rol materno presente. Las demás alternativas son incorrectas: la A se enfoca en conductas infantiles, mientras que PIP actúa sobre la relación y la internalización de patrones de apego, no solo en la conducta del niño; la B sugiere aplicabilidad a cualquier edad, pero la PIP se limita a la etapa temprana del desarrollo, cuando la relación madre‑infante es fundamental; la D la clasifica como cognitivo‑conductual, aunque su enfoque es más psicodinámico y centrado en la relación, no en la modificación de pensamientos y conductas de forma directa.'),
  (806, 'El trastorno negativista desafiante se clasifica como un trastorno de la conducta y, según el DSM‑5, su diagnóstico exige la presencia de al menos dos síntomas de anhedonia (pérdida de interés o placer en actividades previamente disfrutadas) durante un período de al menos seis meses; esta especificación se incluye para diferenciarlo de otras conductas desafiantes que no implican pérdida de motivación intrínseca. El pica, el trastorno del desarrollo intelectual y el trastorno de la Tourette no incorporan el criterio de anhedonia en su definición diagnóstica; el pica se centra en la ingesta de sustancias no nutritivas, el trastorno intelectual se basa en déficits cognitivos y adaptativos, y el trastorno de la Tourette se caracteriza por tics motores y vocales, sin requerir pérdida de placer.'),
  (807, 'En el trastorno de estrés postraumático infantil y adolescente, la presencia de juegos repetitivos que incorporan temáticas del trauma constituye la manifestación más típica en niños mayores de seis años, ya que el juego simbólico es el medio primario de procesamiento emocional y cognitivo en esta edad, permitiendo la integración de experiencias traumáticas en un marco estructurado y seguro; por ello la opción d) refleja la evidencia clínica de que el juego repetitivo es un mecanismo adaptativo y expresivo de la reexperiencia del evento traumático. La alternativa a) es errónea porque la reexperiencia se presenta con frecuencia en la infancia, aunque puede manifestarse de forma distinta; la b) confunde la conducta regresiva, que sí es frecuente en la infancia, con la adolescencia, donde la expresión conductual tiende a ser más madura y menos regresiva; y la c) presupone una relación causal estricta entre sueños angustiosos y la situación traumática, cuando en realidad los sueños pueden ser más amplios y no necesariamente vinculados directamente al evento.'),
  (808, 'La respuesta que se indica como la adecuada es la opción C, porque la conducta descrita constituye abuso sexual infantil, una situación que exige la protección inmediata de la víctima y la obligación legal de denunciar ante las autoridades competentes; la psicóloga debe garantizar la seguridad de la paciente y activar los protocolos de protección infantil sin dilación. Las opciones A y B, aunque pueden parecer útiles para esclarecer la situación, se centran en la verificación de la información y la obtención de detalles, lo cual es secundario frente a la prioridad de proteger al menor y cumplir la obligación de denuncia; además, la opción B corre el riesgo de prolongar la exposición del niño a la situación traumática. La opción D es errónea porque sugiere inacción ante la posibilidad de inconsistencias, lo que contraviene el deber de actuar ante cualquier indicio de abuso; la falta de consistencia no justifica la omisión de la protección y la denuncia.'),
  (809, 'El trastorno de estrés postraumático (TEPT) en la infancia y adolescencia presenta una mayor prevalencia cuando el trauma es de naturaleza interpersonal (violencia física, sexual, abuso o abandono), y la literatura indica que las niñas y adolescentes muestran tasas más elevadas que los varones, probablemente por la mayor exposición a violencia de género y por diferencias en la expresión emocional y búsqueda de apoyo; por ello la opción A refleja la evidencia epidemiológica y clínica, mientras que la B es incorrecta porque los sucesos no interpersonales no muestran mayor prevalencia y la prevalencia no es igual entre géneros; la C es errónea porque, aunque las niñas y adolescentes sí presentan mayor riesgo, los sucesos no interpersonales no son los más frecuentes; la D falla al afirmar que la prevalencia es igual entre géneros, contradiciendo los datos de mayor incidencia en mujeres jóvenes.'),
  (810, 'El modelo que enfatiza una intervención centrada en la familia mediante entrenamiento para padres es el Método Hanen, el cual se basa en la premisa de que la mejora de la comunicación y la reducción de conductas problemáticas en el niño se logran a través de la enseñanza de estrategias específicas a los cuidadores, reforzando su rol como agentes de cambio en el entorno cotidiano; la evidencia clínica muestra que la capacitación en observación, descripción y refuerzo positivo permite a los padres modificar el contexto que favorece la aparición de conductas desadaptativas, lo que se traduce en una mejora sostenida del funcionamiento funcional del niño. Las demás opciones son incorrectas: el Modelo DIR se centra en la relación y las diferencias individuales del desarrollo, sin un componente estructurado de entrenamiento parental; el Método de entrenamiento en Respuestas Centrales (PRT) se enfoca en la enseñanza de habilidades de respuesta a estímulos específicos, pero no tiene como objetivo principal la formación de los padres; el Modelo Denver es una intervención temprana basada en la observación y la intervención directa con el niño, sin un componente de entrenamiento familiar.'),
  (811, 'El círculo arterial cerebral, o polígono de Willis, se constituye por la anastomosis de las arterias carótidas internas y las arterias vertebrales, formando una red de vasos que garantiza la perfusión cerebral incluso cuando una de las arterias principales se obstruye; por tanto la opción A es la única que describe correctamente la anatomía funcional de esta estructura. La opción B es errónea porque el polígono de Willis no se localiza en el cuerpo calloso, sino en la base del cerebro, en la región del tronco encefálico y la corteza cerebral; la opción C sobrepasa la sensibilidad de las arterias, pues la alteración de su calibre puede provocar isquemia, pero no implica necesariamente la muerte inmediata del paciente; y la opción D confunde la anatomía, pues la arteria basilar se forma por la unión de las arterias vertebrales y no adopta una forma aislada, sino que se ramifica en las arterias cerebrales posteriores y participa en el círculo arterial.'),
  (812, 'La prueba de McNemar se emplea para comparar la frecuencia de dos categorías en una misma muestra antes y después de un tratamiento o evento, evaluando si la distribución de las respuestas cambia de manera significativa; por lo tanto, la opción C describe adecuadamente su objetivo, ya que se centra en la comparación de diferencias en un mismo grupo a dos momentos distintos. Las demás alternativas son inexactas: la A se refiere a la asociación entre variables en muestras pequeñas, pero McNemar no se limita a tamaños pequeños ni a variables independientes; la B habla de relaciones entre dos o más variables, lo que corresponde más a pruebas de correlación o chi‑cuadrado, no a McNemar; y la D menciona tres o más grupos, lo cual corresponde a pruebas como la ANOVA o Kruskal‑Wallis, no a la prueba de McNemar.'),
  (813, 'En el Modelo Cúbico de la Estructura del Intelecto de Guilford, la dimensión denominada “contenidos” se refiere precisamente al tipo de información que las personas procesan, es decir, el material sobre el cual se aplican las operaciones mentales; por tanto, la respuesta es la opción A. Las demás alternativas corresponden a otras dimensiones del modelo: la opción B hace referencia a las “operaciones mentales”, que son los procesos cognitivos que se aplican a los contenidos; la C indica los “productos”, es decir, los resultados que emergen de la interacción entre contenidos y operaciones; y la D, “unidades”, no es una dimensión reconocida en el modelo cubico.'),
  (814, 'El fórnix es un haz de fibras de la materia blanca que constituye la principal vía de salida del hipocampo hacia el cuerpo mamilar y el septum, jugando un papel esencial en la consolidación de la memoria episódica y la navegación espacial; por tanto, la opción A, que describe al fórnix como un haz de fibras que conecta distintas regiones cerebrales, se ajusta a la anatomía y función neurobiológica del mismo, mientras que la alternativa B confunde el fórnix con el complejo tálamo-hipotálamo, que no existe; la opción C lo identifica erróneamente como un ganglio basal, cuando en realidad pertenece a la vía límbica; y la D lo describe como una lámina de sustancia gris separada del núcleo lenticular por la cápsula externa, lo cual corresponde a la cápsula interna, no al fórnix.'),
  (815, 'La MCMI‑IV (Millon Clinical Multiaxial Inventory‑IV) se construye sobre el modelo de Millon de trastornos de personalidad y está diseñada explícitamente para mapear sus escalas a los criterios diagnósticos del DSM‑IV y DSM‑5, por lo que muestra la mayor convergencia con la clasificación diagnóstica; las otras pruebas (EPQ, 16 PF y BFQ) se basan en modelos de rasgos (esquemas de personalidad o Big Five) que no están alineados directamente con los criterios diagnósticos del DSM, por lo que su relación con la clasificación diagnóstica es menor.'),
  (816, 'El estado de identidad que Marcia denomina “moratoria” se caracteriza por la suspensión de la toma de decisiones sobre la identidad, la cual se mantiene en un estado de “crisis de identidad” en el que el individuo contempla distintas alternativas sin comprometerse con ninguna; la moratoria implica la búsqueda activa de información y la reflexión profunda antes de elegir una trayectoria, lo que explica por qué la opción D es la que corresponde. La opción A, “difusión de la identidad”, describe un estado de confusión y falta de dirección, pero no implica la evaluación de alternativas; la B, “exclusión”, se refiere a la negación de la identidad de un grupo o categoría, y la C, “logro de la identidad”, corresponde a la consolidación de una identidad firme, por lo que las tres alternativas restantes no reflejan el proceso de deliberación y postergación que caracteriza la moratoria.'),
  (817, 'El delirium se caracteriza por una alteración súbita y fluctuante de la atención y la conciencia, acompañada de deterioro de los procesos cognitivos (memoria, orientación, percepción), y suele presentarse con alucinaciones visuales y episodios de agitación; estos hallazgos encajan con la descripción clínica del trastorno, mientras que el trastorno de ideas delirantes implica creencias falsas sostenidas sin alteración de la conciencia, el trastorno de despersonalización‑desrealización se centra en experiencias de desconexión del propio cuerpo o del entorno sin pérdida de la atención y la conciencia, y la epilepsia del lóbulo temporal se manifiesta con crisis epilépticas focales y no con la fluctuación cognitiva típica del delirium.'),
  (818, 'El umbral absoluto es la intensidad mínima necesaria para que un estímulo sea percibido al menos la mitad de las veces que se presenta; se trata de la sensibilidad básica del sistema sensorial a un estímulo aislado, sin referencia a otro estímulo. Esta definición coincide con la pregunta, pues exige la detección del 50 % de las veces, lo que corresponde a la medida de sensibilidad absoluta. Las demás opciones son incorrectas: el umbral diferencial (A) se refiere a la mínima diferencia entre dos estímulos que permite distinguirlos, no a la detección de un solo estímulo; el umbral relativo (B) implica la variación de la intensidad de un estímulo en función de la presencia de otro estímulo de referencia; y el umbral discriminativo (C) se relaciona con la capacidad de diferenciar entre dos estímulos, no con la percepción de uno solo.'),
  (819, 'La fobia a las arañas se trata con exposición sistemática (extinción) y el problema de la renovación surge cuando la conducta extinguida se recupera al cambiar de contexto; la solución más eficaz es realizar la extinción en múltiples entornos, lo que reduce el efecto de renovación al impedir que el estímulo condicionado se asocie exclusivamente con un solo contexto, y facilita la generalización de la respuesta extinguida a nuevas situaciones; las otras opciones son inadecuadas: el contraste no afecta la recuperación de la respuesta extinguida, el aumento del tiempo de las sesiones no elimina la renovación por sí solo, y la afirmación de que no se puede reducir la renovación es falsa, pues la evidencia clínica muestra que la exposición en varios contextos sí disminuye la recuperación.'),
  (820, 'La opción D recoge las tres fases esenciales de la teoría de la disociación estructural para el tratamiento de niños con trauma grave: primero la estabilización, que implica establecer un entorno seguro y reducir la intensidad de los síntomas disociativos; segundo el procesamiento de los recuerdos traumáticos, donde se trabaja la memoria y la narrativa del evento; y tercero la integración de estilos de afrontamiento adaptativos, que consolida las habilidades aprendidas y promueve la resiliencia; esta secuencia refleja la progresión clínica recomendada por la teoría, donde la seguridad precede al trabajo de contenido y la integración. Las demás alternativas fallan porque la A propone un esquema demasiado general y no menciona la fase de estabilización; la B se centra en la psicoeducación y la narrativa sin abordar explícitamente la integración de afrontamientos; la C incluye el desarrollo de capacidades de afrontamiento pero omite la fase de estabilización y el procesamiento de recuerdos, por lo que no sigue la estructura propuesta por la teoría.'),
  (821, 'El buffer episódico, según el modelo multicomponente de Baddeley (2012), es el subsistema que integra y coordina la información proveniente de los otros componentes (bucle fonológico y visuoespacial) con la memoria a largo plazo, permitiendo la creación de una representación coherente y contextualizada de episodios autobiográficos; por ello, en tareas que exigen la combinación de datos verbales y visuales y su relación con experiencias personales, este componente se vuelve esencial para la consolidación y recuperación de la información contextualizada. El ejecutivo central, aunque supervisa la atención y la planificación, no almacena ni integra la información episódica; el bucle fonológico se limita al procesamiento de material auditivo y no integra la información visual ni autobiográfica; y el sistema atencional supervisor, que regula la atención y la supervisión de los procesos cognitivos, tampoco participa directamente en la integración episódica requerida en la tarea planteada.'),
  (822, 'El fenómeno observado es la interferencia proactiva, ya que la información previamente aprendida (la lista 1) dificulta la recuperación de la nueva información (la lista 2), provocando que la palabra “tambor” se recuerde en lugar de la palabra correcta de la segunda lista; este tipo de interferencia se produce cuando los recuerdos antiguos persisten y perturban la consolidación o el acceso a los nuevos recuerdos. Las demás opciones son incorrectas: la interferencia retroactiva implicaría que la lista 2 afectara la memoria de la lista 1, lo cual no ocurre; la interferencia contextual se refiere a la pérdida de memoria cuando el contexto de aprendizaje y recuerdo difiere, y la inhibición colaborativa no es un término reconocido en la teoría de la memoria.'),
  (823, 'La protanopia, ausencia funcional de los conos L (rojo), produce una reducción de la sensibilidad a la longitud de onda larga, de modo que los estímulos de color rojo se perciben con menor intensidad y se confunden con el verde; además, la falta de contraste en la zona roja del espectro hace que las luces rojas se vean más apagadas, especialmente en condiciones de baja luminancia como la conducción nocturna, mientras que la percepción del verde, que depende de los conos M, permanece relativamente intacta. Las otras opciones son incorrectas: la deuteranopia afecta los conos M (verde) y no explica la confusión roja‑verde ni la atenuación de las luces rojas; la tritanopia altera los conos S (azul) y no influye en la discriminación roja‑verde; la acromatopsia implica la pérdida total de la visión cromática y la visión en blanco‑negro, lo que no concuerda con la preservación parcial de la percepción de verde descrita en el caso.'),
  (824, 'La sobreestimación de la probabilidad diagnóstica del TEPT se explica por el heurístico de disponibilidad, pues el residente, tras haber atendido varios casos graves, mantiene en su memoria inmediata ejemplos vívidos y recientes de TEPT, los cuales son más accesibles y, por tanto, influyen en la evaluación de la probabilidad de que un nuevo paciente presente la misma patología; este sesgo hace que la frecuencia real del trastorno se sobreestime. El heurístico de anclaje (A) se refiere a la tendencia a fijarse en un valor inicial, no a la accesibilidad de ejemplos recientes; el heurístico de representatividad (C) implicaría juzgar la probabilidad según la semejanza con un prototipo, lo cual no explica la influencia de la experiencia reciente; el heurístico de simulación (D) se relaciona con la capacidad de imaginar situaciones, no con la accesibilidad de recuerdos clínicos.'),
  (825, 'Según la teoría motivacional del proceso oponente de Solomon y Corbit, la exposición prolongada a un estímulo produce un proceso A que genera una respuesta inmediata y un proceso B que se activa de forma contraria, con la finalidad de equilibrar la activación inicial; por tanto, la opción B describe adecuadamente la dinámica de los procesos opuestos, donde el proceso B actúa como inhibidor del proceso A y viceversa, manteniendo la homeostasis conductual. Las demás opciones son erróneas porque la A y la B no son procesos primario y secundario de igual intensidad (A), no incluyen la función de regulación homeostática que se deriva de la interacción entre ambos procesos (C), ni describen la distinción entre proceso primario, general y sumatorio con intensidades disímiles (D).'),
  (826, 'El proceso descrito corresponde al condicionamiento de huella, en el cual el estímulo incondicionado (EI) se presenta después de que el estímulo condicionado (EC) ha concluido, generando una respuesta que se mantiene durante un intervalo de tiempo; la respuesta condicionada se “huella” en la memoria de la asociación, y la aparición tardía del EI permite que la respuesta se consolide en la fase de retención, característica de la huella. Las demás alternativas son incorrectas: el condicionamiento de demora (A) implica que el EC precede al EI con un intervalo de tiempo, pero el EI se presenta inmediatamente después del EC, no tras su terminación; el condicionamiento simultáneo (B) se produce cuando EC y EI aparecen al mismo tiempo, sin intervalo; y el condicionamiento hacia atrás (D) se refiere a la asociación de un estímulo que sigue al estímulo condicionado, pero sin la característica de que el EI se presente solo después de la terminación del EC.'),
  (827, 'La opción C se corresponde con la teoría probabilística de la formación de conceptos, la cual sostiene que los conceptos se construyen a partir de la identificación de características comunes entre los ejemplos y la posterior estimación de la probabilidad de que una nueva instancia pertenezca al mismo grupo, es decir, se forma un prototipo estadístico; la abstracción de rasgos compartidos y la asignación de pesos probabilísticos a cada rasgo generan un concepto que puede aplicarse a nuevas situaciones. Las demás alternativas son incorrectas: la A describe la teoría clásica, que asume la existencia de una esencia fija y no contempla la variabilidad estadística; la B se refiere a modelos mixtos que combinan elementos de la teoría clásica y ejemplar, pero no se centran en la abstracción de características para formar prototipos; y la D corresponde a la teoría del ejemplar, que sostiene que los conceptos se basan en la memoria de ejemplos específicos sin una abstracción estadística.'),
  (828, 'El fenómeno descrito se explica por la memoria congruente con el humor, ya que la información que se presenta en un estado afectivo similar al que se experimenta durante la codificación se almacena y recupera con mayor facilidad; en este caso, la tristeza que se siente al estudiar la depresión favorece la consolidación de los síntomas relacionados con ese estado, generando un rendimiento superior en la memorización. Las opciones A y B son incorrectas porque la memoria dependiente del humor sugiere una relación bidireccional y la carga afectiva del material implica una carga emocional del contenido, no la congruencia entre estado y material; la opción D es errónea porque evidencia empírica demuestra que el afecto influye en la memoria, por lo que no puede ser descartado.'),
  (829, 'El método estadístico más empleado para detectar la presencia de funcionamiento diferencial de ítems (DIF) es el procedimiento de Mantel‑Haenszel, que compara la probabilidad de responder correctamente a un ítem entre grupos de referencia (por ejemplo, género o origen étnico) mientras controla la capacidad total, proporcionando una estimación de la diferencia de riesgo ajustada; la técnica es robusta, se aplica a datos de respuesta binaria y permite clasificar los ítems en DIF leve, moderado o severo. Las demás alternativas son inadecuadas: el modelo de Samejima corresponde a la curva de respuesta de ítems de tipo IRT de escala de Rasch con parámetros de dificultad y discriminación, no a la detección de DIF; el análisis de distractores se utiliza para evaluar la calidad de las opciones en pruebas de opción múltiple, pero no mide diferencias entre grupos; y la regresión múltiple jerárquica, aunque puede incluir variables de grupo, no es el método estándar para DIF y carece de la especificidad de Mantel‑Haenszel.'),
  (830, 'En la Teoría de Respuesta al Ítem, la función de información de un ítem cuantifica la precisión con la que el ítem estima el rasgo latente θ; su valor máximo se alcanza cuando la estimación de θ coincide con el parámetro de dificultad b del ítem, pues en ese punto la pendiente de la curva característica es máxima y la probabilidad de respuesta cambia más rápidamente con respecto a θ, lo que maximiza la información; por tanto la opción A describe correctamente este comportamiento. La opción B es errónea porque la información varía con θ, alcanzando su pico en b y disminuyendo a ambos lados. La opción C confunde información con error estándar de medida; aunque el error estándar es la raíz cuadrada de la inversa de la información, la información no es directamente el error típico. La opción D es falsa porque la información se calcula como la varianza de la respuesta condicionada a θ, que no depende de la pendiente de la curva característica ni de la probabilidad acumulada de la distribución normal estándar; esos conceptos pertenecen a la derivación de la función de probabilidad, no a la función de información.'),
  (831, 'La eficacia del test, entendida como la proporción de clasificaciones correctas respecto al total de personas evaluadas, corresponde a la opción B, ya que mide la capacidad global del instrumento para identificar correctamente tanto casos como no casos, integrando sensibilidad y especificidad en una única medida de rendimiento; las demás alternativas describen conceptos distintos: la opción A describe la sensibilidad, la opción C la especificidad (aunque invertida), y la opción D la especificidad propiamente dicha, por lo que no se ajustan al concepto de eficacia.'),
  (832, 'La prueba de Kolmogorov‑Smirnov compara la función de distribución empírica de la muestra con la función de distribución teórica, calculando la máxima diferencia absoluta entre ambas y evaluándola contra valores críticos que dependen del tamaño muestral; por ello es la herramienta estándar para verificar la normalidad u otra distribución específica, ya que no requiere supuestos de varianza homogénea ni de datos pareados. La prueba de Mauchly, por su parte, se emplea para comprobar la esfericidad en análisis de varianza de medidas repetidas, no la forma de la distribución; el test de rachas evalúa la aleatoriedad de la secuencia de valores, no su ajuste a una distribución teórica; y la prueba de Levene se utiliza para comparar la homogeneidad de varianzas entre grupos, no la distribución de los datos.'),
  (833, 'El enfoque de métodos mixtos en investigación clínica combina procedimientos cualitativos y cuantitativos dentro de un mismo estudio, permitiendo integrar la riqueza descriptiva de las entrevistas o grupos focales con la rigurosidad estadística de las mediciones numéricas; de este modo se logra una comprensión más completa del fenómeno, ya que la triangulación de datos facilita la corroboración y la ampliación de las interpretaciones, algo que no ocurre cuando se utilizan exclusivamente una sola metodología. Las opciones A y B describen análisis estadísticos de diseño de medidas repetidas, pero no abordan la integración de enfoques metodológicos distintos, por lo que son insuficientes; la opción C sugiere una sustitución de métodos cuantitativos por análisis avanzados, lo cual no refleja la esencia de los métodos mixtos, que se centran en la combinación de ambos tipos de datos, no en reemplazarlos.'),
  (834, 'El valor p de 0,001 se interpreta como la probabilidad, bajo la hipótesis nula de que no existe diferencia entre los grupos en la población, de obtener una diferencia igual o mayor a la observada simplemente por azar; por tanto, la opción A describe correctamente este concepto, pues expresa que la probabilidad de obtener ese resultado si la hipótesis nula fuera cierta es del 0,1 %. Las demás alternativas son erróneas porque confunden el valor p con la probabilidad de que la hipótesis nula sea cierta (B), con la eficacia del tratamiento (C) o con la relevancia clínica de la diferencia (D), conceptos que no se derivan directamente del valor p y que requieren de análisis adicionales como estimaciones de efecto y criterios clínicos.'),
  (835, 'La técnica cuyo objetivo principal es identificar constructos latentes a partir de las correlaciones entre variables observadas es el análisis factorial; este método modela la covarianza entre indicadores como consecuencia de factores subyacentes, permitiendo la reducción de dimensionalidad y la interpretación de estructuras teóricas. El análisis discriminante múltiple (A) se utiliza para clasificar observaciones en grupos predefinidos, no para descubrir factores; el análisis de conglomerados jerárquicos (B) agrupa casos según similitud, sin inferir constructos latentes; la regresión logística multinomial (C) predice categorías de una variable dependiente a partir de predictores, tampoco busca estructuras latentes.'),
  (836, 'El profesional debe obtener el consentimiento informado de la madre, ya que la ley protege a la menor cuando uno de los progenitores ha sido condenado por violencia de género y se le ha impuesto una orden de alejamiento; en este contexto la patria potestad del padre no le confiere el derecho de decidir sobre la atención psicológica de la niña, por lo que la madre, como representante legal activa y no amenazada, es la única persona autorizada para otorgar dicho consentimiento, y el psicólogo debe informar al padre sobre el proceso sin que su presencia sea necesaria; las demás opciones son erróneas: la A implica una doble obtención de consentimiento que no está justificada cuando uno de los progenitores está bajo orden de alejamiento; la C confunde la presencia de un adulto acompañante con la autoridad para consentir, pues la patria potestad del padre se ve limitada por la sentencia; la D descarta la obligación de obtener consentimiento, lo cual es incorrecto, pues la obtención del CI sigue siendo requisito indispensable incluso en la red pública.'),
  (837, 'La opción d) es la única que concuerda con la normativa de confidencialidad y la obligación de la psicóloga de actuar como perito: debe presentarse al tribunal y, al hacerlo, debe dejar constancia de que sus conclusiones se basan en la práctica clínica y asistencial que ha mantenido con el paciente, sin revelar datos confidenciales ni violar el secreto profesional; la declaración se limita a la información que el caso exige y que puede aportar de forma objetiva y respaldada por la práctica. Las alternativas A y B son erróneas porque la ley no exime al profesional del deber de declarar cuando la información es relevante para el proceso penal; la confidencialidad no protege la obligación de testificar cuando la información no constituye un secreto profesional. La opción C es incorrecta porque no se requiere un peritaje previo; la declaración puede basarse en la actividad clínica habitual, siempre que se fundamenten las conclusiones en la práctica realizada.'),
  (838, 'La opción A es la que se ajusta al principio de justicia en el ámbito clínico, pues la justicia se interpreta como equidad en el trato, no como igualdad estricta; la frecuencia de las citas debe reflejar las necesidades clínicas individuales, garantizando que cada paciente reciba la atención proporcional a su gravedad y evolución, lo que evita la discriminación y promueve la distribución justa de recursos. Las alternativas B y D fallan porque asumen una interpretación literal de la justicia como uniformidad o una separación entre la gestión administrativa y la práctica clínica, respectivamente, ignorando la normativa ética que exige adaptar la atención a la situación de cada paciente; la opción C es incorrecta porque la idea de “beneficiar al 50 %” no se basa en criterios clínicos ni en la equidad, sino en una supuesta paridad arbitraria.'),
  (839, 'La respuesta se fundamenta en la teoría de la relación terapéutica, donde la autorrevelación del terapeuta, cuando se emplea con moderación y en el contexto adecuado, funciona como un recurso que facilita la construcción de un rapport genuino y reduce la distancia interpersonal; la falta de este recurso puede generar una sensación de frialdad y limitar la apertura del paciente, comprometiendo la alianza terapéutica esencial para la evaluación; las demás opciones son erróneas porque la empatía cognitiva no implica “sentir con el otro” sino comprender su perspectiva manteniendo la propia identidad, por lo que la opción A confunde los conceptos; la autorrevelación sí se considera una técnica válida y no produce efectos negativos cuando se aplica correctamente, contraviniendo la opción B; y la compasión, al ser una respuesta emocional genuina al sufrimiento del paciente, contribuye precisamente a establecer el rapport, invalidando la opción C.'),
  (840, 'La formulación de caso es una hipótesis explicativa fundamentada en teoría que integra la información recopilada durante la evaluación para planificar y dirigir el tratamiento y evaluar el cambio; esta definición coincide con la opción A, ya que reconoce la función de la formulación como un marco teórico que guía tanto la intervención como la valoración de la evolución clínica, en lugar de limitarse a un esquema interno o a una descripción meramente descriptiva. La opción B es incorrecta porque, aunque la formulación ayuda a ordenar datos, su objetivo no se restringe a ser un esquema interno del terapeuta, sino que debe ser compartido con el paciente y otros profesionales para orientar el tratamiento. La alternativa C es errónea pues la formulación no es el objetivo central de la evaluación ni permanece inmutable; se revisa y ajusta a medida que se obtienen nuevos datos o se produce el cambio clínico. Finalmente, la respuesta D es falsa porque la formulación no se limita a describir síntomas y no excluye el diagnóstico psiquiátrico; al contrario, la formulación y el diagnóstico pueden coexistir y complementarse dentro de un enfoque integrador.'),
  (841, 'En la entrevista psicológica, los sondeos o pruebas se definen como preguntas que animan al entrevistado a expresar sus ideas o sentimientos sobre un problema que ha verbalizado; esta técnica busca profundizar en la experiencia subjetiva del paciente y facilita la construcción de una narrativa coherente, permitiendo al profesional captar matices emocionales y cognitivos que no emergen de manera espontánea, lo cual es esencial para la elaboración de un diagnóstico y la planificación de la intervención. Las demás alternativas son erróneas: la opción A describe una técnica de confrontación o interrogatorio que no corresponde al concepto de sondeo, la B confunde el sondeo con una entrevista no directiva, mientras que la D se refiere a la técnica de reflexión o clarificación, que aunque también es útil, no es la definición de sondeo; por tanto, solo la opción C recoge la esencia funcional de los sondeos en la práctica clínica.'),
  (842, 'La prueba que no forma parte de la Batería Cognitiva de Consenso MATRICS (MCCB) es el Trail Making Test (Parte B); la MCCB incluye el Trail Making Test (Parte A) para evaluar la velocidad de procesamiento, pero la parte B, que mide la flexibilidad cognitiva, se excluye porque se considera más adecuada para la batería de pruebas de la Neuropsychological Assessment Battery (NAB) y no se utiliza en la MCCB. Las demás opciones sí están incluidas: el MSCEIT se emplea para medir la regulación emocional, el Laberintos de la NAB se utilizan para evaluar la memoria espacial y la fluidez verbal semántica (animales) es una prueba de categoría verbal que forma parte del conjunto de evaluaciones de la MCCB.'),
  (843, 'La puntuación de Tasa Base (TB) de 87 en el patrón clínico de personalidad evitativa indica que la persona presenta rasgos evitativos que superan el umbral clínicamente significativo, ya que en el MCMI‑IV una TB superior a 85 se interpreta como indicativa de un patrón clínico relevante; por tanto la respuesta C es la que refleja adecuadamente que la patología es suficientemente generalizada para considerarse clínicamente significativa. La opción A es incorrecta porque la TB es la medida interpretativa propia del instrumento y no necesita una transformación adicional; la opción B es errónea porque una TB de 87 está por encima del rango de “por debajo de lo clínicamente significativo” (que correspondería a valores más bajos); y la opción D es inexacta porque la escala de control del MCMI‑IV no se aplica a los patrones clínicos, sino a la validez de la respuesta, por lo que la TB no se interpreta en términos de sinceridad de la contestación.'),
  (844, 'El índice que se deriva de las escalas de Comprensión Verbal y Razonamiento Perceptivo en la WAIS‑IV es el Índice de Capacidad General (ICG), pues la teoría de Wechsler sostiene que la capacidad general se construye a partir de la interacción entre la dimensión verbal y la dimensión perceptiva, reflejando la capacidad cognitiva global; por tanto la opción B es la que corresponde. La alternativa A describe el CI total, que se obtiene al combinar todos los índices, no únicamente esos dos dominios; la opción C introduce un término no utilizado por Wechsler (Capacidad Cognitiva), y la D es incorrecta porque la escala sí dispone de ese índice específico.'),
  (845, 'La opción C es la única que refleja la estructura real del Inventario de Depresión de Beck (BDI‑II); su segunda edición contiene 21 ítems que cubren síntomas cognitivos, afectivos, físicos y de comportamiento, entre los que se incluyen tanto la pérdida como el aumento del apetito y del sueño, lo que permite captar la variabilidad de estos síntomas en la depresión; la alternativa A es errónea porque los cuestionarios son herramientas complementarias y no pueden sustituir la entrevista clínica, que sigue siendo el estándar de oro para el diagnóstico; la opción B es falsa porque la escala de Hamilton (HRSD) se emplea tanto para la detección inicial como para la monitorización de la evolución del trastorno depresivo, ya que sus puntuaciones cambian con el tratamiento; y la alternativa D es incorrecta porque en el BDI‑II una puntuación de 8 se sitúa en el rango de depresión mínima o sin depresión, no en la leve, cuyo rango comienza en 13, lo que demuestra un error de interpretación de los cut‑offs.'),
  (846, 'La opción A es la que se corresponde con la práctica clínica establecida: la Structured Interview for Psychosis-Risk Syndromes (SIPS) y la Comprehensive Assessment of At-Risk Mental States (CAARMS) son los dos instrumentos de referencia para la evaluación de los Estados Mentales de Alto Riesgo, pues ambos emplean entrevistas semiestructuradas con escalas de gravedad y frecuencia que permiten identificar los síntomas prodromales de la esquizofrenia y estimar la probabilidad de transición a un trastorno psicótico; la SIPS se compone de 19 ítems distribuidos en dominios positivos, negativos, desorganizados y generales, mientras que la CAARMS incluye la Scale of Prodromal Symptoms (SOPS) y criterios específicos para el trastorno de la personalidad esquizotípica, pero no incorpora un cuestionario de antecedentes familiares ni una versión de la GAF, y la SOPS es parte de la CAARMS, no una entrevista independiente desarrollada por Yale. Por tanto, las alternativas B, C y D contienen errores: B confunde la estructura de la CAARMS con elementos que no forman parte de ella; C atribuye incorrectamente el origen de la SOPS al equipo PRIME de Yale; D describe la SIPS con precisión, pero la pregunta exige la identificación de los instrumentos más utilizados, no la descripción de la SIPS.'),
  (847, 'La subescalas de Cubos se incluye en los tres instrumentos de Wechsler (WPPSI‑IV, WISC‑V y WAIS‑IV) porque evalúa la capacidad de razonamiento espacial y la organización visual‑motor, competencias que se consideran esenciales en la medición de la inteligencia en todas las edades; su estructura de bloques de construcción permite una comparación directa entre los niveles de desarrollo cognitivo de la infancia temprana, la infancia intermedia y la edad adulta, y su puntuación se integra en los índices de razonamiento perceptivo de cada escala. Las demás opciones no se encuentran simultáneamente en los tres tests: Puzzles visuales es una subescalas exclusiva de la WPPSI‑IV y la WISC‑V, pero no aparece en la WAIS‑IV; Span de dibujos es una medida de atención y memoria de trabajo que se incluye en la WAIS‑IV y la WISC‑V, pero no en la WPPSI‑IV; y Búsqueda de símbolos es una subescalas de velocidad de procesamiento presente en la WAIS‑IV y la WISC‑V, pero no en la WPPSI‑IV.'),
  (848, 'El diferencial semántico, introducido por Charles Osgood, se fundamenta en la premisa de que cada concepto contiene un significado denotativo (referencial) y otro connotativo (emocional o evaluativo), y evalúa la posición de un término a lo largo de escalas bipolarizadas que capturan estas dimensiones; por tanto, la opción C es la que describe adecuadamente esta forma de evaluación. Las demás alternativas son incorrectas: la técnica de la rejilla (B) se centra en la codificación de respuestas a preguntas específicas y no distingue entre significados denotativos y connotativos; las listas de adjetivos (A) y las clasificaciones Q (D) emplean categorías de rasgos o criterios, pero no operan con la doble dimensión semántica propuesta por el diferencial.'),
  (849, 'El BCSE se emplea como prueba opcional dentro del Programa Integrado de Exploración Neuropsicológica (PIEN‑Barcelona), donde su uso está previsto para la valoración de la función cognitiva en adultos de 1 a 89 años, complementando la batería de pruebas neuropsicológicas que incluye la evaluación de memoria, atención, lenguaje y funciones ejecutivas; la inclusión de esta escala en el PIEN se justifica por su brevedad, validez transdiagnóstica y la posibilidad de detectar deterioro cognitivo leve en contextos clínicos y de investigación. Las demás opciones son incorrectas: la CAMCOG‑R (A) es una escala de evaluación cognitiva que no contempla el BCSE como prueba opcional; la WAIS‑IV (B) es una escala de inteligencia que no incluye la prueba BCSE en su batería; y la WMS‑IV (C) se centra exclusivamente en la memoria y tampoco incorpora el BCSE como opción.'),
  (850, 'La escala DES (Dissociative Experiences Scale) de Bernstein y Putnam (1986) está diseñada para cuantificar la frecuencia y la intensidad de los síntomas disociativos, incluyendo amnesia, despersonalización, derealización y experiencias de pérdida de identidad; por tanto la opción D es la que corresponde a su finalidad clínica. Las demás alternativas se refieren a constructos distintos: la dismorfia corporal (A) se evalúa con instrumentos como la MDS, la depresión mayor (B) con la MADRS o la BDI, y los episodios de desregulación emocional (C) se miden con escalas de regulación emocional o de trastornos de personalidad; ninguna de ellas contempla la medición de fenómenos disociativos como la DES.'),
  (851, 'La opción B es la que se ajusta a la práctica clínica: el SENA (Escala de Atención y Concentración) y el CARAS-R (Cuestionario de Atención y Hiperactividad) ya capturan la información esencial sobre déficit de atención e hiperactividad, pero la inclusión de pruebas proyectivas o de razonamiento, como las matrices de Raven o las semejanzas de Wechsler, aporta datos adicionales sobre el funcionamiento cognitivo general y la capacidad de razonamiento abstracto, lo que permite diferenciar mejor el TDAH de otras dificultades de aprendizaje o trastornos del procesamiento cognitivo; por tanto, la ampliación con estos instrumentos mejora la validez diagnóstica. La alternativa A es errónea porque el Toulouse-Piéron Revisado es una escala de hiperactividad y conductas disruptivas, no una fuente de nueva información cuando ya se dispone de SENA y CARAS-R, que sí evalúan la atención; la opción C es incorrecta porque el ENFEN (Escala de Evaluación de la Función Ejecutiva) está diseñado para niños de 6 a 12 años, por lo que la edad de la niña es adecuada; la alternativa D es falsa porque el SENA sí valora la atención, siendo uno de los instrumentos más utilizados para detectar déficit atencional en la infancia.'),
  (852, 'La concordancia entre informadores es la característica que distingue a la depresión infantil de otras patologías infantiles; los estudios de validación del CDI y de otras escalas de auto‑informe muestran que la correlación entre la percepción del niño, la de los padres y la de los profesores suele ser baja, reflejando la subjetividad de los síntomas y la dificultad de observarlos en contextos distintos, por lo que la opción B es la afirmación que se ajusta a la evidencia clínica; las demás alternativas son incorrectas porque la opción A presupone que los dibujos infantiles de niños deprimidos presentan “abundancia de detalles con contenido negativo”, cuando en realidad la evidencia indica que tienden a mostrar menos detalle y mayor simplificación; la opción C describe erróneamente la estructura del CDI, el cual posee una única dimensión depresiva, no una dimensión positiva; y la opción D confunde rabietas, que son más frecuentes en trastornos de conducta, con un síntoma exclusivo de la depresión preescolar, lo cual no se sostiene en la literatura.'),
  (853, 'La opción A es la única que se ajusta a la práctica clínica de evaluación del funcionamiento adaptativo en un niño de 6 años que presenta conductas desafiantes ante límites parentales; la Escala VABS‑3 de Vineland permite cuantificar la autonomía, la comunicación y las habilidades sociales, lo que facilita diferenciar una conducta típica de la infancia de un posible trastorno del espectro autista o de un trastorno de conducta, ya que la puntuación baja en la dimensión de adaptabilidad puede indicar dificultades de regulación emocional y social; las demás alternativas son incorrectas porque la opción B confunde la interpretación de dibujos y juegos simbólicos con la presencia de un trastorno afectivo, cuando en realidad estos instrumentos son más indicativos de procesos de juego y no de diagnóstico de trastornos del estado de ánimo; la opción C presupone que la repetición de la conducta en distintos contextos implica automáticamente TDAH, aunque el TDAH se caracteriza por impulsividad y falta de atención más que por la agresión específica ante límites; y la opción D sugiere que el BASC‑3, aunque útil para evaluar síntomas conductuales y emocionales, no está diseñado como screening específico para trastornos del espectro autista, por lo que su uso no sería el más adecuado en este caso.'),
  (854, 'La coprolalia, es decir, el uso involuntario de palabras o frases obscenas, no se considera una característica típica del trastorno del espectro autista; su presencia se asocia más con el síndrome de Tourette y otras afecciones de tics, por lo que no se incluye en el cuadro clínico autista. En contraste, la ecolalia (repetición de palabras o frases escuchadas), la inversión pronominal (uso incorrecto de pronombres) y la escasez de vocabulario son alteraciones lingüísticas frecuentemente observadas en el autismo, reflejando dificultades en la pragmática, la sintaxis y la adquisición del lenguaje; por tanto, las opciones A, C y D describen manifestaciones habituales del trastorno.'),
  (855, 'El DSM‑5‑TR permite el diagnóstico simultáneo de TDAH y trastorno del espectro autista porque ambos pueden coexistir y el criterio de “exclusión” no se aplica; la presencia de rasgos autistas no impide la identificación de síntomas de inatención y de hiperactividad‑impulsividad que cumplen los criterios de TDAH, por lo que la opción A se sustenta en la normativa actual. En cambio, la opción B es incorrecta porque el DSM‑5‑TR establece la edad de aparición antes de los 12 años, no antes de los 7; la edad mínima de 7 años es un criterio de la clasificación ICD‑10. La opción C es errónea porque el ítem “con frecuencia es incapaz de jugar o de ocuparse tranquilamente en actividades recreativas” se refiere a la hiperactividad, no a la inatención, y la opción D es falsa porque a partir de los 16 años (no 17) el número de síntomas requeridos para el criterio de hiperactividad‑impulsividad se reduce a cinco, no a seis.'),
  (856, 'La opción D es la que corresponde al protocolo de seguimiento de prematuros porque la escala Bayley‑III está diseñada específicamente para evaluar el desarrollo cognitivo, motriz y de la comunicación en niños de 1 a 42 meses, con un apartado de “edad corregida” que permite ajustar la edad cronológica a la gestacional, lo que resulta esencial en la población prematura; además, la Bayley‑III incorpora escalas de desarrollo motor, lenguaje receptivo y expresivo, y cognitivo que se han validado en estudios de seguimiento de prematuros y permiten detectar retrasos tempranos y planificar intervenciones. La opción A, la Escala de Brazelton, se centra en la observación del comportamiento neonatal y la respuesta a estímulos, no en la medición cuantitativa del desarrollo cognitivo y motor a los 18 meses; la B, la Escala de Aptitudes Intelectuales (BAS‑II), es una prueba de inteligencia para escolares y no está diseñada para la edad temprana ni para la edad corregida; la C, la WPPSI‑IV, es una prueba de inteligencia para niños de 2,5 a 7 años y no cubre la edad de 18 meses ni la edad corregida, por lo que las tres alternativas se descartan por no ajustarse a la población y al objetivo de medición.'),
  (857, 'La información más relevante para comprender funcionalmente los síntomas obsesivo‑compulsivos de Lucía es la posible existencia de ganancias secundarias dentro del contexto familiar, pues la motivación de los rituales puede estar vinculada a la obtención de atención, control o evitación de demandas, y la identificación de estos refuerzos permite orientar la intervención hacia la modificación de la dinámica familiar y la reducción de la función de los comportamientos; las otras opciones, aunque útiles en la valoración clínica, no aportan directamente a la explicación funcional: la frecuencia y duración (A) describen la manifestación pero no su función; los antecedentes médicos o neurológicos (B) son relevantes para descartar causas orgánicas, pero no explican la motivación de los rituales; el grado de insight (C) indica la conciencia del paciente sobre el carácter egodistónico, pero no revela la función de los síntomas en el entorno.'),
  (858, 'La Escala de Funcionamiento Reflexivo para Niños y adolescentes (CRFS) está diseñada para medir la capacidad de los jóvenes de comprender e integrar los estados mentales propios y ajenos dentro de su discurso narrativo, lo que constituye el núcleo de la teoría de la mente y la autorreflexión; por tanto, la opción A describe con precisión el constructo que la escala evalúa, ya que la escala se basa en la observación de la narrativa del niño y su habilidad para atribuir intenciones y emociones a sí mismo y a los demás, un proceso que implica la reflexión sobre estados mentales. Las demás opciones son erróneas: la B se refiere a la resonancia emocional, un aspecto de la empatía que no es el foco principal de la CRFS; la C describe la identificación de conductas observables y su explicación en términos no mentalistas, lo cual corresponde más a la observación conductual que a la reflexión mental; y la D aborda el control atencional y la autorregulación conductual en contextos sociales, constructo que se evalúa con instrumentos distintos, como escalas de autorregulación o pruebas de atención.'),
  (859, 'Según Vygotski, el lenguaje y el pensamiento se originan de forma independiente; el lenguaje es una función social que se internaliza a lo largo del desarrollo, mientras que el pensamiento se constituye a partir de la mediación del habla egocéntrica, que actúa como herramienta de regulación interna; por ello la opción B es la que refleja correctamente la teoría de la internalización y la convergencia de ambos procesos a través de la mediación del habla. Las demás alternativas son erróneas: la A confunde el proceso de andamiaje con la base de las capacidades, la C sugiere una socialización progresiva del lenguaje que no corresponde a la concepción de Vygotski, y la D presenta una definición ambigua y mezcla conceptos que no están alineados con la teoría original.'),
  (860, 'La opción B corresponde a un precursor de la teoría de la mente porque implica la comprensión de los planos conductual y representacional de la intencionalidad, es decir, la capacidad de reconocer que los demás poseen estados mentales que guían su conducta, lo que constituye la base para desarrollar la capacidad de atribuir intenciones y predecir comportamientos; este reconocimiento se produce antes de que el individuo distinga entre creencias verdaderas y falsas o comprenda los contenidos proposicionales de las actitudes intencionales, que son etapas posteriores de la teoría de la mente. Por el contrario, la opción A describe un prerrequisito más amplio (la percepción de los humanos como agentes autoanimados), pero no se centra en la intencionalidad; la opción C se refiere a la diferenciación entre creencias verdaderas y falsas, que es una habilidad más avanzada que la de reconocer la intencionalidad; y la opción D aborda la comprensión de los contenidos proposicionales de las actitudes intencionales, también una etapa posterior a la comprensión de los planos conductual y representacional.'),
  (861, 'La opción d es la que corresponde a la teoría de Luquet: en la fase de realismo frustrado el niño se enfrenta a obstáculos que incluyen dificultades motoras, limitaciones atencionales y una incapacidad sintética, pues todavía no ha integrado los elementos del objeto en una representación coherente; por ello su producción se ve marcada por la falta de organización y la fragmentación de la imagen. Las demás alternativas resultan incorrectas porque la fase de realismo fortuito (opción A) no implica una relación causal entre el significado y la semejanza del dibujo y el objeto, sino que se caracteriza por la reproducción de la apariencia sin intención de significado; la fase de realismo frustrado (opción B) no se distingue por la retirada del dibujo por falta de habilidad, sino por la frustración ante la imposibilidad de lograr la representación adecuada; y la fase de realismo visual (opción C) no es la que introduce los procedimientos de transparencia y abatimiento, los cuales pertenecen a la fase de realismo fortuito.'),
  (862, 'La Teoría Focal de J. C. Coleman sostiene que el desarrollo se organiza en una sucesión de estadíos que se construyen a partir de la resolución de aspectos específicos de la identidad; cada estadío se caracteriza por la integración de un foco particular, pero estos focos no se limitan a una sola dimensión de la identidad, sino que abarcan múltiples dimensiones (cognitiva, emocional, social, etc.), por lo que la afirmación de que “cada foco se centra en una dimensión de la identidad” es una simplificación errónea. En cambio, las demás opciones reflejan principios centrales de la teoría: la secuencia de desarrollo es flexible y puede variar según la experiencia individual (B); la transición entre estadíos es fluida y no se delimita estrictamente (C); y la resolución de un aspecto no constituye un requisito previo absoluto para avanzar al siguiente estadío, pues la identidad se construye de forma simultánea y recíproca (D).'),
  (863, 'La investigación de Tiffany Field sobre la sincronía en el vínculo de apego se centró en la capacidad de la madre para “leer” y responder a las señales del infante; el hallazgo más consistente fue que los niños mostraban mayor probabilidad de responder cuando la madre imitaba sus expresiones faciales, gestos o vocalizaciones, lo que facilita la regulación emocional y la consolidación de la relación; la imitación actúa como un espejo que valida la experiencia del niño y refuerza la comunicación no verbal, elementos esenciales en la teoría del apego. Las demás opciones son incorrectas: la opción B (las pausas) describe un fenómeno de regulación temporal, pero no es el factor que Field identificó como el más influyente; la C (conducta espontánea de la madre) es demasiado amplia y no especifica la imitación; y la D (intentos por captar y mantener la atención) se refiere a estrategias de atención, no a la respuesta específica de imitación que resultó ser la más efectiva para la sincronía.'),
  (864, 'La fase descrita corresponde a la etapa de “Mantenimiento de la proximidad” en la teoría de Bowlby, donde el neonato, tras haber identificado a la madre como figura primaria, comienza a buscar activamente su presencia y a mostrar aversión a los extraños; esta conducta se manifiesta mediante la locomoción y señales de apego que garantizan la cercanía, lo que coincide con la opción C. Las alternativas A y B describen etapas anteriores: la primera se refiere al reconocimiento de figuras sin discriminación y la segunda al inicio de la discriminación, pero sin la expresión de rechazo a los desconocidos; la opción D, por su parte, se refiere a una fase posterior de asociación con objetivos, que no implica la selección de figuras subsidiarias ni el rechazo a los extraños.'),
  (865, 'En la teoría de Piaget, la niña está aplicando la asimilación, pues incorpora el nuevo objeto (el avión) dentro de un esquema ya existente (pájaro) sin modificar la estructura cognitiva; la información se interpreta a través de un marco previo, lo que explica por qué la designa como “pájaro”. Las demás opciones son incorrectas: la organización (A) se refiere a la clasificación de estímulos dentro de categorías, no al proceso de incorporar un nuevo objeto a un esquema; la adaptación (B) es el conjunto de asimilación y acomodación y no describe un proceso puntual; y la acomodación (D) implicaría la modificación del esquema para ajustarse al nuevo objeto, lo cual no ocurre cuando la niña mantiene la categoría de pájaro sin cambios.'),
  (866, 'La respuesta es la opción C porque, según el modelo de Schaffer (1984), el estadio de coordinación de personas y objetos es el momento en el que el bebé ya ha superado la fase de interés activo por las personas y la fase de interés por los objetos, y comienza a integrar ambos dominios en la interacción; en este punto aparecen los primeros gestos comunicativos, como señalar, que indican la transición hacia la comunicación triádica (bebé, interlocutor y objeto). Las opciones A y B corresponden a estadios anteriores en los que el bebé se centra únicamente en la atención a las personas o a los objetos, sin todavía combinar ambos; por lo tanto, no se produce la señalización ni la comunicación triádica. La opción D describe un estadio posterior, en el que el lenguaje se incorpora a la comunicación, lo que sucede después de haber establecido los gestos iniciales y la coordinación de personas y objetos.'),
  (867, 'El análisis de las fuentes de variabilidad biológica en psicología diferencial se centra en dos componentes esenciales: la proporción de la varianza fenotípica que se atribuye a la dotación genética individual y la variación que se origina en el funcionamiento diferencial de los mecanismos biológicos; esto corresponde a la opción D, ya que la varianza fenotípica es la medida observable de las diferencias psicológicas y la genética y los procesos biológicos son las fuentes biológicas subyacentes que se evalúan en estudios de herencia y neurobiología. Las demás opciones son erróneas porque A y C confunden la varianza psicológica o ambiental con la fenotípica, y B sustituye los mecanismos biológicos por los psicológicos, lo cual no corresponde al enfoque de investigación biológica.'),
  (868, 'El tiempo de inspección se define como el intervalo entre la presentación de un estímulo y el momento en que el sujeto indica que ha terminado de procesarlo, sin requerir una respuesta activa; por ello no implica la ejecución motora que acompaña al tiempo de reacción, lo que elimina la necesidad de balancear velocidad y precisión mediante una ratio, un problema frecuente en los estudios de velocidad mental; en cambio, el tiempo de reacción incluye la fase motora y, al combinarse con la precisión, puede confundir la interpretación de los resultados, pues la variabilidad motora y la estrategia de respuesta influyen en la medida. Por consiguiente, la opción C es la que describe correctamente la ventaja del tiempo de inspección. Las demás alternativas son erróneas: la A sugiere que la medida es más compacta y abarca más procesos, lo cual no es una ventaja específica del tiempo de inspección; la B indica una influencia excesiva de factores como motivación y personalidad, cuando en realidad el tiempo de inspección reduce dicha influencia; y la D menciona la obligación de separar tiempo de decisión y de movimiento, lo cual se aplica al tiempo de reacción, no al tiempo de inspección.'),
  (869, 'La respuesta A se fundamenta en la concepción de los rasgos como constructos teóricos que no se manifiestan de forma directa en la conducta observable, sino que se deducen a partir de patrones de comportamiento recurrentes que sirven como indicadores de la presencia y la intensidad del rasgo; por tanto, su carácter subyacente implica que el rasgo no es una entidad empíricamente accesible, sino una inferencia basada en la evidencia conductual, lo cual coincide con la definición de rasgo como una dimensión latente que se infiere mediante la observación de indicadores comportamentales representativos. Las opciones B y C, aunque describen aspectos relevantes de los rasgos (su naturaleza continua y su tendencia a predisponer a ciertos comportamientos), no abordan la cuestión de la no observabilidad directa, mientras que la D, que sugiere una consistencia interna, se refiere a la estabilidad del rasgo a lo largo del tiempo y no a su inferencia a partir de indicadores.'),
  (870, 'La investigación longitudinal sobre la inteligencia muestra que, a partir de la infancia temprana, la estructura de las aptitudes se consolida en un modelo jerárquico de tres estratos (g, dominio y habilidades específicas), lo que explica la consistencia de los coeficientes de correlación entre las pruebas de diferentes dominios a lo largo del desarrollo; por ello la opción B es la que refleja fielmente los hallazgos empíricos. La opción A es incorrecta porque la evidencia indica que la estructura jerárquica se mantiene estable, no que varíe con la edad; la opción C es falsa porque, aunque la inteligencia tiene una organización jerárquica, las capacidades individuales pueden cambiar con la experiencia y el aprendizaje; y la opción D se equivoca al afirmar que la alta estabilidad predictiva se observa en los primeros meses de vida, cuando en realidad la estabilidad es más pronunciada a partir de los 6 años, cuando la estructura se ha consolidado.'),
  (871, 'La opción A describe el nivel de regulación “integrada” del continuo motivacional de Ryan y Deci, donde la persona reconoce la actividad como propia y la valora, pero aún no la ha incorporado completamente a su identidad y a la coherencia de su experiencia personal; por tanto la motivación es parcialmente autónoma pero no total, lo que coincide con la definición de regulación “integrada” (autonomía moderada). La alternativa B corresponde a la regulación “externa” (control externo), donde la conducta se guía por recompensas o castigos, y la opción D describe la regulación “introjetiva” (control interno), donde la acción se orienta a evitar la culpa o a buscar aprobación, ambas distintas de la regulación integrada. La alternativa C, que indica una motivación totalmente autónoma o autorregulada, corresponde a la regulación “autónoma” (autonomía plena), que no es la que se plantea en la pregunta.'),
  (872, 'La propuesta de Costa y McCrae (1994) sobre la personalidad se centra en los rasgos de carácter, definidos como disposiciones estables que guían la percepción, el pensamiento y el comportamiento; por tanto, la opción que menciona “las necesidades básicas o sistemas de motivación que impulsan la conducta” (B) es la que no corresponde a su modelo, ya que la teoría de los cinco grandes no incluye la motivación como componente esencial de la personalidad, sino que se enfoca en la organización de los rasgos. Las demás alternativas, aunque no son parte de la definición de Costa y McCrae, sí pueden considerarse elementos relevantes en otras teorías de la personalidad: A describe los sistemas psicofísicos que se asemejan a los rasgos; C se refiere a la biografía objetiva, que influye en la formación de la personalidad; y D al autoconcepto, que constituye un aspecto importante del sentido de identidad personal.'),
  (873, 'El factor p de Caspi et al. (2014) representa la propensión general a la psicopatología y se ha asociado con la variabilidad compartida entre todas las manifestaciones clínicas; sin embargo, la literatura indica que su carga más fuerte se observa en la dimensión de desórdenes del pensamiento, pues la alteración cognitiva es un componente transversal que permea tanto la ansiedad como la depresión y las conductas antisociales, y su presencia se refleja en la mayor correlación entre el factor p y los índices de pensamiento disfuncional; las otras opciones, aunque también están relacionadas con la psicopatología, se consideran subdimensiones más específicas: la ansiedad y la depresión son trastornos de estado afectivo que, aunque correlacionados con p, no capturan la misma amplitud de disfunción cognitiva, y las conductas antisociales son más bien una manifestación conductual que no constituye la dimensión principal que carga el factor p.'),
  (874, 'La obra de Huarte de San Juan se considera un antecedente del estudio científico de las diferencias individuales porque, al correlacionar las variaciones en características específicas de las personas con las habilidades que podrían desarrollar, estableció una relación funcional entre rasgos innatos y potencial de aprendizaje, sentando las bases de la psicología diferencial; las demás opciones son inexactas: la opción B confunde la distinción entre habilidades naturales y aprendidas con la propia clasificación de Huarte; la C se refiere a una división conceptual que no es atribuible a su obra; y la D atribuye una metodología genética y cuantitativa que aparece en autores posteriores, no en Huarte.'),
  (875, 'La baja autoeficacia implica una creencia en la propia incapacidad para controlar los resultados de las acciones, lo que favorece la rumiación y la anticipación negativa de los eventos futuros; este patrón cognitivo se asocia con la activación de circuitos de frustración y desamparo que predisponen a la depresión, por lo que la opción B describe el mecanismo más directamente vinculado a la literatura sobre autoeficacia y síntomas depresivos. Las demás alternativas son incorrectas porque la opción A se refiere a atribuciones externas, pero la investigación muestra que la autoeficacia afecta principalmente la percepción interna de control, no solo la atribución; la opción C habla de activación fisiológica, un proceso más relacionado con la motivación y la respuesta de acción, no con la generación de síntomas depresivos; y la opción D, aunque menciona la dependencia de factores externos, no explica el vínculo con la rumiación ni la anticipación negativa, por lo que no captura el mecanismo central señalado por los estudios sobre autoeficacia y depresión.'),
  (876, 'La teoría de la motivación de logro de Atkinson sostiene que los individuos con alta necesidad de logro (n‑A) buscan maximizar la probabilidad de éxito mientras minimizan el riesgo de fracaso; por ello, seleccionan tareas de dificultad intermedia, donde el riesgo de fracaso es moderado y la posibilidad de éxito es alta, lo que les permite experimentar la satisfacción de la superación sin exponerse a la ansiedad que provocaría una tarea demasiado difícil; la opción B refleja precisamente ese equilibrio entre riesgo y recompensa que caracteriza al n‑A, mientras que la opción A describe una estrategia de evitación del riesgo que se asocia más con la necesidad de evitar el fracaso (n‑E), la opción C describe una búsqueda de riesgo extremo que se observa en la necesidad de poder (n‑P) o en la búsqueda de la novedad, y la opción D se refiere a un aspecto metodológico de la evaluación que no está vinculado a la elección de tareas según la teoría de Atkinson.'),
  (877, 'Los estudios sociohistóricos de la personalidad de Jean Twenge (2000, 2001) muestran que el aumento del Neuroticismo/Ansiedad está vinculado a un mayor número de personas que viven solas y a una reducción de la tasa de nacimientos, pues la ansiedad y la inseguridad emocional fomentan la reticencia a compromisos familiares y la adopción de estilos de vida más individualistas, lo que explica la tendencia a la soltería y a la disminución de la reproducción; las opciones A y B son erróneas porque el incremento del neuroticismo no se relaciona con una disminución del individualismo ni con cambios educativos hacia la permisividad, y la opción C es incorrecta al asociar el neuroticismo con la movilidad y globalización, fenómenos que no se correlacionan directamente con la ansiedad de la personalidad.'),
  (878, 'La dislexia del desarrollo se ha asociado de forma consistente con alteraciones en la organización cortical de las áreas auditivas y fonológicas, particularmente en el Planum Temporale izquierdo; los estudios post mortem revelan ectopias y dislaminación de capas corticales, y la neuroimagen muestra una reducción de la asimetría típica de esta región, lo que compromete la integración fonológica y la codificación del lenguaje escrito, explicando la dificultad lectora; las otras opciones son inadecuadas: la opción A describe un atrofia global que no se observa en la dislexia y afecta áreas motoras y cerebelosas no centrales para la lectura; la B indica un aumento de actividad en áreas occipito‑temporales, lo cual se observa en lectores con dislexia compensatoria, no en la causa primaria; la D sugiere un déficit prefrontal medial auditivo, pero la evidencia apunta a disfunciones en las áreas temporales y no a una hipoactivación prefrontal.'),
  (879, 'La hipótesis del marcador somático de Damasio postula que las emociones se traducen en cambios fisiológicos (marcadores somáticos) que se integran en la evaluación de opciones y, por tanto, guían la toma de decisiones, especialmente cuando la información racional es insuficiente o ambigua, como en dilemas morales; por eso la opción B describe correctamente el papel de los marcadores somáticos como indicadores de valor emocional que influyen en la elección. La alternativa A es incorrecta porque ignora la influencia emocional que Damasio sostiene como esencial; la C se basa en una interpretación errónea del efecto de la lesión orbitofrontal, que en realidad suele deteriorar la toma de decisiones al eliminar la regulación emocional, no mejorarla; y la D se refiere a la memoria autobiográfica, un proceso distinto que no constituye la propuesta central de la teoría del marcador somático.'),
  (880, 'La hormona antimülleriana (AMH), producida por los Sertoli de los testículos en la etapa embrionaria, es la que ejerce la acción de regresión del sistema de Müller; su presencia provoca la degradación de los conductos que en ausencia de AMH se diferenciarían en los órganos sexuales femeninos (trompas de Falopio, útero y parte superior de la vagina). Esta función es esencial para la diferenciación sexual masculina y se produce antes de la aparición de la testosterona, que posteriormente estimula la masculinización de los genitales externos. Las demás opciones son incorrectas: la testosterona (A) y la dihidrotestosterona (B) son andrógenos que participan en la masculinización de los genitales, pero no tienen efecto sobre el sistema de Müller; la inhibina (C) regula la secreción de FSH y no interviene en el desarrollo de los conductos de Müller.'),
  (881, 'El hipocampo es el centro de la codificación inicial y la consolidación de los recuerdos declarativos, tanto episódicos como semánticos, tal como se evidencia en el caso de H.M. y en estudios de lesiones hipocampales que muestran amnesia anterógrada sin pérdida de memoria procedimental; por tanto, su función principal es la transformación de la información de corto a largo plazo, aunque los recuerdos terminan almacenados en regiones corticales. Las demás opciones son erróneas porque el hipocampo no actúa como el depósito final de todos los recuerdos (opción B), no participa en la manipulación de la memoria de trabajo (opción C), y su papel no se limita a la expresión de respuestas emocionales inconscientes, que involucra principalmente la amígdala (opción D).'),
  (882, 'El hipotálamo es el centro de regulación de la homeostasis y la comunicación entre el sistema nervioso y el sistema endocrino; su función principal incluye la secreción de hormonas hipotalámicas que estimulan o inhiben la glándula pituitaria, la modulación de la actividad simpática y parasimpática a través de sus núcleos de integración y la regulación del balance hídrico mediante la liberación de vasopresina y la producción de ADH, lo que explica por qué la opción B recoge los tres aspectos esenciales: comunicación neuroendocrina, control autonómico y metabolismo hídrico. La alternativa A incluye la regulación de procesos atencionales automáticos o controlados, una función más atribuible a estructuras prefrontales y no al hipotálamo; la opción C describe procesos de integración motora y valoración afectiva que se realizan en la corteza motora y el sistema límbico, respectivamente, sin implicar directamente al hipotálamo; la opción D menciona ritmos circadianos, que sí están mediados por el hipotálamo, pero la coordinación motora y la consolidación de la memoria son funciones de la corteza motora y el hipocampo, no del hipotálamo.'),
  (883, 'El líquido cefalorraquídeo se sintetiza principalmente en los plexos coroideos, estructuras vasculares situadas dentro de los ventrículos cerebrales que filtran la sangre plasmática y generan LCR a través de la membrana basilar y la capa de ependima; esta producción constituye la fuente cuantitativa del LCR, mientras que su circulación y absorción se realizan en el espacio subaracnoideo y las vellosidades aracnoideas, respectivamente, pero no son lugares de síntesis. Las opciones A y B describen compartimentos donde el LCR circula o se almacena, pero no se produce; la opción D se refiere a la vía de absorción del LCR, no a su origen, por lo que las alternativas A, B y D son incorrectas.'),
  (884, 'La distinción entre afasias transcorticales y perisilvianas se basa en la preservación de la repetición auditiva; en las afasias transcorticales la repetición se mantiene intacta porque el circuito de repetición (corteza temporal superior y área de Broca) permanece funcional, aunque el acceso a la producción y comprensión se ve comprometido por la disfunción de los núcleos de la red de lenguaje, mientras que en las afasias perisilvianas (Broca y Wernicke) la repetición se deteriora porque el daño afecta directamente a los núcleos de la red de lenguaje y a los enlaces que permiten la repetición. Las opciones A y C confunden la función de repetición con la conciencia de las dificultades, que no es la característica discriminante principal; la anosognosia puede aparecer en ambos tipos, pero no distingue entre ellos. La opción D invierte la relación de la repetición, atribuyéndola erróneamente a la perisilviana, lo cual contradice la evidencia neuropsicológica de que la repetición se mantiene en las afasias transcorticales.'),
  (885, 'El CAD, o red neuronal por defecto, se caracteriza por su actividad espontánea cuando la mente no está dirigida a una tarea externa; su activación se observa durante la introspección, la imaginación y la planificación futura, lo que explica la opción D, pues la divagación y la fantasía sobre el futuro son manifestaciones típicas de la activación de esta red; las demás alternativas son erróneas porque la red no se completa tan tempranamente (la opción A confunde su desarrollo con el del córtex prefrontal, que madura más allá de los 4 años), no se limita a zonas posteriores del cerebro ni excluye el córtex prefrontal (opción B), y su activación no depende de estados meditativos profundos ni de “dejar la mente en blanco” (opción C).'),
  (886, 'La apraxia ideomotora se manifiesta como un déficit en la programación espaciotemporal de movimientos ya aprendidos, afectando la ejecución de gestos transitivos y la coordinación de la fuerza y la dirección, mientras que la apraxia ideatoria implica un trastorno en la concepción de las secuencias de actos o en el conocimiento funcional de los objetos, por lo que la persona no puede planificar la serie de pasos necesarios para usar un objeto correctamente; esta distinción se basa en la diferencia entre la ejecución motora concreta y la planificación conceptual de la acción. Las opciones A y D confunden los tipos de gestos y la conservación de fórmulas motoras, respectivamente, y no reflejan la división funcional entre la programación motora y la planificación conceptual. La opción C atribuye localizaciones anatómicas incorrectas, pues ambas apraxias pueden derivar de lesiones corticales y subcorticales, sin una exclusividad de una región a la otra.'),
  (887, 'La prueba descrita es el Test de Wada, también conocido como prueba de intracarotídea de amital, que consiste en inyectar amital sódico en la arteria carótida interna para anestesiar selectivamente un hemisferio y evaluar la lateralización del lenguaje y la función de memoria, lo que permite valorar el riesgo de amnesia postoperatoria en la cirugía de epilepsia; la técnica se emplea específicamente para determinar la dominancia lingüística y la reserva de la memoria, y su aplicación clínica está bien establecida en la planificación quirúrgica de la epilepsia. El Test de Harris (B) se refiere a una prueba de memoria episódica y no a la anestesia hemisférica; el Test de Edimburgo (C) es un cuestionario de síntomas de depresión y no tiene relación con la lateralización cerebral; el Test de lateralidad Martin‑Lobo (D) es un método de valoración de la lateralidad motora y no implica anestesia selectiva ni se usa en cirugía de epilepsia.'),
  (888, 'El paso de Ca²⁺ a través de los canales de calcio tipo voltage‑dependiente en el botón terminal desencadena la fusión de las vesículas sinápticas con la membrana presináptica, proceso que se conoce como exocitosis; por lo tanto la opción D describe el evento inmediato, pues la entrada de Ca²⁺ activa los complejos de SNARE y los proteínas de fusión que movilizan y liberan el neurotransmisor. Las demás alternativas son incorrectas: la despolarización de la membrana postsináptica (A) es un efecto secundario que ocurre después de que el neurotransmisor se ha difundido y ha activado los receptores; la unión de los neurotransmisores a los receptores postsinápticos (B) es el paso que sigue a la liberación, no el inmediato tras la entrada de Ca²⁺; y la degradación enzimática del neurotransmisor (C) ocurre tras la señal postsináptica, en el espacio sináptico, y no está vinculada directamente al flujo de Ca²⁺.'),
  (889, 'El síndrome de Korsakoff se caracteriza por una amnesia anterógrada severa que impide la consolidación de nuevos hechos episódicos, mientras que la memoria semántica suele permanecer relativamente preservada, lo que permite que el paciente recuerde conceptos y hechos generales sin dificultad; esta distinción se explica por la lesión de la cápsula de Meynert y las áreas periamigdala, que afectan el circuito de la memoria episódica pero no el sistema semántico. En contraste, la opción A equivale a una alteración global de memoria que no distingue entre episodios y semántica, lo que no se observa en Korsakoff. La opción B describe una amnesia anterógrada moderada y una retrógrada total, pero en la práctica la retrógrada es parcial y suele presentar un gradiente temporal, con mayor pérdida de recuerdos recientes que de infancia. La opción C afirma que la amnesia retrógrada carece de gradiente temporal, lo cual es incorrecto, pues la pérdida de recuerdos recientes suele ser más pronunciada que la de los eventos lejanos.'),
  (890, 'El criterio de alucinaciones visuales complejas, bien formadas y detalladas, junto con signos motores espontáneos de parkinsonismo, constituye la descripción clásica de la demencia con cuerpos de Lewy, donde la presencia de alucinaciones visuales es uno de los criterios diagnósticos centrales y suele preceder a la aparición de los síntomas motores; en la enfermedad de Parkinson las alucinaciones pueden aparecer en etapas avanzadas, pero no son criterio central, y la demencia frontotemporal se caracteriza por alteraciones de la personalidad y del lenguaje sin alucinaciones visuales típicas, mientras que la corea de Huntington presenta movimientos involuntarios y deterioro cognitivo, pero no alucinaciones visuales complejas.'),
  (891, 'La heminegligencia se manifiesta como una pérdida de atención y conciencia hacia la mitad contralateral del espacio, típicamente el lado izquierdo cuando el daño cerebral afecta el lóbulo parietal derecho; esta lesión altera la integración sensorial y la orientación espacial, de modo que el paciente ignora estímulos en ese campo, lo que explica por qué la opción D es la que describe con precisión la localización anatómica y la función clínica típica de la heminegligencia, mientras que las demás alternativas se equivocan: la A confunde heminegligencia con hemianopsia, que es una pérdida visual de campo, y la heminegligencia no es un sinónimo de hemianopsia ipsilateral; la B asocia erróneamente la heminegligencia con parálisis motora, cuando en realidad la motricidad puede permanecer intacta; y la C sugiere que el paciente es consciente de sus déficits y corrige espontáneamente, lo cual es característico de la hemianopsia, no de la heminegligencia, que se caracteriza por una falta de conciencia de los déficits.'),
  (892, 'La afasia transcortical mixta se caracteriza por una combinación de los déficits de la afasia de Broca (discurso espontáneo muy limitado, pero con buena repetición) y de la afasia global (comprensión auditiva severamente deteriorada), pero sin la pérdida de la capacidad de repetición que se observa en la afasia global; por ello los pacientes presentan un habla normal al repetir, una comprensión auditiva muy deteriorada y una fluidez muy pobre en la emisión espontánea, lo que coincide con la descripción de la pregunta. Las opciones A y B se descartan porque la afasia de Broca presenta repetición preservada pero comprensión relativamente intacta, y la afasia motora transcortical, aunque también conserva la repetición, no muestra el nivel de deterioro auditivo que caracteriza a la transcortical mixta. La opción D, la afasia global, implica una pérdida de la repetición, contradiciendo el hallazgo de habla normal al repetir.'),
  (893, 'El factor común de las terapias familiares sistémicas es la **explicitar y hacer circular la experiencia emocional interna, habitualmente no compartida** (opción B), porque la intervención sistémica se centra en la comunicación y la circulación de emociones dentro del sistema familiar, facilitando la expresión de sentimientos que permanecen ocultos y alterando la dinámica de interacción para promover la integración emocional; las demás opciones son incorrectas: la opción A describe una visión lineal y contextualizada que no corresponde al enfoque sistémico, que valora la circularidad y la interdependencia; la opción C enfatiza la frecuencia de interacciones diádicas, mientras que la terapia sistémica busca la interacción multilateral y la reconfiguración de patrones familiares; la opción D sugiere disminuir las interacciones metacomunicativas, pero en la práctica sistémica se fomenta la metacomunicación para clarificar roles y significados.'),
  (894, 'El modo del adulto sano en la terapia de esquemas de Young actúa como un regulador central que integra y modera los modos disfuncionales, permitiendo que la persona responda de manera adaptativa a las demandas internas y externas; esta función se basa en la capacidad de combinar la lógica y la empatía para reestructurar las respuestas emocionales y conductuales, evitando la reactivación de patrones infantiles y la sobrecompensación; las demás opciones son incorrectas porque la opción A describe una estrategia de control cognitivo que se asocia más con el modo infantil de evitación, la opción C se refiere a la confrontación racional típica del modo adulto crítico, y la opción D implica la refuerzo de conductas disfuncionales, lo cual es contrario a la función integradora y moderadora del modo adulto sano.'),
  (895, 'La propuesta de Castonguay et al. (2019) distingue entre factores que influyen en el pronóstico, los moderadores del paciente, las variables de proceso y la relación terapéutica; los factores moderadores del paciente comprenden características individuales que alteran la respuesta al tratamiento, entre ellas las preferencias del paciente y su estilo de afrontamiento, pues estos determinan la manera en que el individuo interpreta y responde a las intervenciones, modulando la eficacia terapéutica; las opciones A y C se refieren a variables que afectan el resultado final o el proceso interno del tratamiento pero no a la predisposición individual que modula la respuesta, mientras que la D se centra en la alianza y la interacción entre terapeuta y paciente, sin contemplar la influencia de las preferencias y estrategias de afrontamiento del propio paciente.'),
  (896, 'La práctica descrita corresponde a la obtención de feedback sobre el proceso terapéutico, pues la psicóloga solicita deliberadamente la valoración del paciente respecto al método, la utilidad de las sesiones y la sensación de comprensión, con el fin de evaluar la calidad de la intervención y ajustar la técnica; esta estrategia se centra en la retroalimentación directa del cliente para mejorar la eficacia del tratamiento. Las opciones A y C se refieren a enfoques específicos (modelo de Prochaska y DiClemente y entrevista motivacional, respectivamente) que implican intervenciones estructuradas y técnicas de cambio de comportamiento, no simplemente la recolección de opiniones; la opción B, la reparación de rupturas en la alianza terapéutica, se emplea cuando ya existe una fractura en la relación, lo cual no es el caso aquí, pues la actividad se orienta a la evaluación continua y no a la reparación de una ruptura.'),
  (897, 'La estereotipia verbal descrita, en la que el paciente repite palabras o sílabas de su propio discurso, se denomina palilalia; se trata de una repetición involuntaria de la propia producción lingüística, típica de trastornos neurológicos como la enfermedad de Parkinson o la parálisis cerebral, y se diferencia de la ecolalia, que implica la repetición de palabras ajenas, de la perseveración semántica, que se refiere a la repetición de conceptos o categorías semánticas, y de la taquifemia, que se relaciona con la velocidad de habla, no con la repetición.'),
  (898, 'El discurso circunstancial se caracteriza por la inclusión de datos que, aunque no son esenciales para el mensaje central, mantienen una relación temática con el tema principal; estos datos se añaden de forma espontánea y suelen estar vinculados a la experiencia del hablante, lo que permite al interlocutor contextualizar la información sin desviarse completamente del objetivo comunicativo, por lo que la opción D describe con precisión esta modalidad. Las demás alternativas son erróneas: la opción A describe un discurso con paréntesis escasos, típico del descarrilamiento, no del circunstancial; la B se refiere a un exceso de paréntesis que se asocia al discurso desorganizado o al descarrilamiento, no a la circunstancial; y la C señala una gran cantidad de detalles anómalos y perseverantes, característica del discurso de tipo perseverante o de pensamiento intrusivo, pero no del circunstancial.'),
  (899, 'El paciente amnésico presenta una disfunción de la memoria episódica que dificulta la integración de unidades de información en una narrativa coherente, lo que explica la opción B: la amnesia se caracteriza por la incapacidad de conectar eventos de forma significativa, reflejando la pérdida de la memoria de trabajo y la consolidación de la información episódica; en cambio, la opción A describe una amnesia anterógrada con preservación de la memoria retrograda, lo cual no es típico en la amnesia general; la opción C confunde la memoria implícita con la explícita, ya que en la amnesia la memoria implícita suele mantenerse intacta mientras que la explícita se ve afectada; y la opción D equivale a una amnesia semántica, donde la memoria semántica se deteriora y la episódica permanece relativamente intacta, lo cual no corresponde a la amnesia clásica descrita.'),
  (900, 'La opción B es la que mejor refleja la distinción propuesta por Farina et al. (2019), pues la desintegración se caracteriza por la pérdida de la coherencia y la integración de procesos cognitivos y emocionales, afectando la conectividad cerebral y las funciones integradoras de alto orden, mientras que la disociación implica la fragmentación de experiencias que, aunque se perciben como desconectadas, mantienen una reorganización funcional dentro de sistemas psíquicos diferenciados; las alternativas A, C y D se equivocan al asociar la disociación con una desconexión gradual entre afecto y cognición, limitar la desintegración a fenómenos somáticos, o atribuir a la disociación un proceso regresivo emocional, lo cual no corresponde a la conceptualización de Farina et al.'),
  (901, 'La descripción clínica coincide con la alternancia entre una personalidad aparentemente normal (PAN) y una parte emocional (PE) que se activa en respuesta a estímulos traumáticos, tal como plantea la teoría de la disociación estructural de la personalidad de Van der Hart et al.; la PAN mantiene la continuidad funcional del self y la vida cotidiana, mientras que la PE, fijada en recuerdos no integrados, se manifiesta con agresividad y pérdida de memoria, lo que explica la desconexión y la posterior amnesia; las demás opciones fallan porque la opción A atribuye el fenómeno a un mecanismo fisiológico vagal que no explica la división de la identidad, la opción C describe despersonalización sin pérdida de continuidad del self, y la opción D sugiere disociaciones parciales sin la marcada división estructural entre PAN y PE que caracteriza el caso.'),
  (902, 'El trastorno de disforia por la integridad corporal, según la CIE‑11, se define por un deseo intenso y persistente de adquirir una discapacidad física importante, acompañado de una incomodidad persistente con el funcionamiento o la configuración actual del propio cuerpo; la clave está en que la disforia se dirige al cuerpo tal como es, no a la incapacidad de desempeñar roles sociales ni a la percepción de una apariencia socialmente inadecuada, y tampoco a un miedo a una enfermedad grave, pues el trastorno no implica ansiedad por la salud sino una alteración de la relación con la propia corporalidad. Por tanto, la opción A describe precisamente la relación intrínseca entre la disforia y la percepción corporal actual. Las opciones B y C se refieren a factores externos o a la imagen corporal, que son relevantes en trastornos de la conducta alimentaria, pero no en la disforia por la integridad corporal; la opción D describe un temor a la enfermedad, que corresponde a un trastorno de ansiedad, no a la disforia.'),
  (903, 'El patrón descrito corresponde a conductas pasivas de acumulación, ya que la paciente no adquiere objetos de forma intencional ni los guarda con la finalidad de conservarlos, sino que simplemente no logra deshacerse de los que ya posee, lo que produce malestar y se caracteriza por una falta de iniciativa para eliminar los objetos, típica de la acumulación pasiva; en la CIE‑11 esta categoría se distingue de la activa, donde la adquisición deliberada es el eje central, y de la conservación precautoria, que se refiere a la retención de objetos por motivos de seguridad o previsión, y de la evitación ansiosa, que implica un miedo a perder el control sobre la propia vida o entorno, pero no necesariamente se centra en la acumulación de objetos. Por tanto, la opción D es la que mejor encaja con la descripción clínica, mientras que las demás se descartan por tratarse de procesos motivacionales o conductuales diferentes.'),
  (904, 'La opción C es la que refleja la explicación teórica de Abramowitz et al. (2018) sobre la eficacia de la exposición con prevención de respuesta (EPR) en el TOC: la terapia no solo provoca la habituación del miedo condicionado, sino que, al impedir la respuesta de neutralización, permite que el paciente experimente la ausencia de la amenaza esperada, lo que lleva a la incorporación de nueva información que reestructura la representación cognitiva del estímulo temido y produce una relación inhibitoria entre el estímulo y la respuesta de ansiedad; este proceso de reestructuración cognitiva es el mecanismo central que explica la reducción de la compulsión. Las demás opciones son insuficientes o incorrectas: la A se centra únicamente en la habituación, omitiendo la importancia de la prevención de respuesta; la B confunde la tolerancia con la fatiga fisiológica, que no es el objetivo de la EPR; y la D describe un proceso de reducción de evitación que, aunque relevante, no es el mecanismo primario señalado por los autores.'),
  (905, 'La amenaza percibida en el modelo de creencias de salud se constituye a partir de la evaluación que hace el individuo de su susceptibilidad a contraer la enfermedad y de la gravedad que atribuye a dicha condición; estos dos componentes se integran con las claves para la acción, es decir, las señales que indican la necesidad de intervención, de modo que la percepción de riesgo se vuelve una construcción cognitiva que guía la respuesta conductual. Las demás alternativas son erróneas: la opción B confunde la amenaza con el conjunto de creencias generales sobre la enfermedad, sin diferenciar susceptibilidad y gravedad; la C se refiere a la autoeficacia, que constituye la percepción de control, no la amenaza; y la D limita la amenaza a factores genéticos, omitiendo la dimensión subjetiva de la percepción de riesgo que el modelo enfatiza.'),
  (906, 'El factor que no protege contra el síndrome postcuidados intensivos familiar (SPCI‑F) es el rol pasivo en la toma de decisiones (D); al no participar activamente, el familiar pierde la sensación de control y la oportunidad de procesar la experiencia, lo que aumenta la vulnerabilidad al trastorno. En contraste, la edad avanzada del paciente (A) no es un factor protector, sino más bien un riesgo, pues la pérdida de un ser querido mayor suele generar mayor duelo; las creencias religiosas o espirituales fuertes (B) y la sensación de control percibida (C) sí actúan como amortiguadores, proporcionando sentido, esperanza y una estructura cognitiva que facilita la adaptación emocional. Por tanto, las opciones A y D comparten el mismo motivo de error: son factores de riesgo o no protectores, mientras que B y C son verdaderos protectores.'),
  (907, 'La respuesta se fundamenta en la caracterización clínica de los trastornos depresivos, donde la teoría de la regulación emocional indica que la disfunción se manifiesta como una reactividad emocional exacerbada ante estímulos negativos (dolor, pérdida, fracaso) y una anhedonia que se traduce en una respuesta atenuada a estímulos positivos, reflejando una alteración en la valoración y procesamiento de la información emocional; este patrón se documenta en estudios de reactividad fisiológica y auto‑reportes de afecto. En contraste, los trastornos de ansiedad presentan una hiper‑reactividad a amenazas anticipadas pero no necesariamente una respuesta atenuada a estímulos positivos; los trastornos de estrés postraumático muestran una reactividad intensa a recordatorios traumáticos, pero la respuesta a estímulos positivos puede mantenerse intacta; el trastorno límite de personalidad se caracteriza por una regulación emocional disfuncional con fluctuaciones abruptas y reactividad intensa, pero la atenuación de la respuesta a estímulos positivos no es una característica distintiva.'),
  (908, 'El modelo de continuo psicótico de Van Os y Kapur (2009) propone una visión transdiagnóstica que descompone los trastornos psicóticos en tres dominios fundamentales: el dominio psicótico (ideas delirantes, alucinaciones, etc.), el dominio desorganizado (pensamiento y comportamiento incoherentes) y el dominio negativo (anhedonia, alogia, avolition); además, incorporan un eje afectivo que abarca la variabilidad de estados emocionales que acompañan a la sintomatología psicótica, lo que permite capturar la heterogeneidad clínica entre esquizofrenia, trastorno bipolar con episodios psicóticos y otras condiciones. Las demás opciones son incorrectas porque la alternativa B omite el eje afectivo y confunde la desorganización con la dimensión negativa; la C introduce dimensiones depresiva, maníaca y mixta que no forman parte del marco original, y la D propone categorías sintomática, conductual y afectiva que no reflejan la estructura propuesta por Van Os y Kapur.'),
  (909, 'La opción C resulta la más adecuada porque, en la psicoterapia de la psicosis, el terapeuta debe adoptar una postura de escucha empática y de colaboración, invitando al paciente a explorar de forma gradual y segura la relación entre sus experiencias delirantes o alucinatorias y su funcionamiento cotidiano; esta estrategia facilita la construcción de un marco de referencia más realista sin confrontar directamente la realidad del delirio, lo que podría provocar una reacción defensiva o empeorar la desconfianza. En contraste, la alternativa A, al presionar al paciente con preguntas directas para un análisis funcional inmediato, corre el riesgo de provocar ansiedad y resistencia, pues el paciente puede percibirla como una acusación o una amenaza a su sentido de realidad. La opción B, que sugiere un lenguaje técnico y preciso, puede resultar alienante y generar una brecha comunicativa, ya que el uso de terminología clínica sin contextualización puede reforzar la sensación de incomprensión del paciente. Finalmente, la alternativa D, que propone un debate cognitivo centrado en las interpretaciones del paciente y la vigilancia de sus evasiones, puede ser contraproducente al enfocarse demasiado en la corrección de la interpretación y sin considerar la dimensión afectiva y de seguridad del paciente, lo que puede intensificar la ansiedad y el aislamiento.'),
  (910, 'La opción B recoge los tres criterios diagnósticos esenciales de la anorexia nerviosa según el DSM‑5: (i) restricción de la ingesta que conduce a un peso corporal por debajo de lo esperado para la edad y la altura; (ii) miedo intenso a ganar peso o a engordar, incluso cuando el individuo ya está por debajo del peso saludable; y (iii) alteración persistente de la percepción de la imagen corporal, con una preocupación desproporcionada por la forma y el peso. Estos tres elementos constituyen la base diagnóstica y son necesarios para diferenciar la anorexia de otras formas de trastornos alimentarios. Las demás alternativas fallan porque omiten o sustituyen criterios imprescindibles: la A sustituye la alteración de la imagen corporal por una sensación de ineficacia, que no es un criterio diagnóstico; la C introduce la preocupación por comer en público, un factor de riesgo pero no un criterio; y la D sustituye la restricción de la ingesta por bajo peso, que es un resultado de la restricción y no un criterio independiente, y agrupa la alteración de la imagen corporal con el pensamiento inflexible, que tampoco es un criterio diagnóstico.'),
  (911, 'La bulimia nerviosa se caracteriza por episodios recurrentes de ingesta excesiva seguidos de conductas compensatorias inapropiadas, entre las que se incluyen el vómito autoinducido, el uso de laxantes o diuréticos y el ejercicio excesivo; dichas conductas alteran el equilibrio electrolítico y el metabolismo, provocando desequilibrios hormonales que se reflejan en irregularidades menstruales o amenorrea, por lo que la opción B es la que mejor describe una consecuencia fisiológica frecuente del trastorno. La opción A es errónea porque la bulimia se asocia más a menudo con un índice de masa corporal normal o ligeramente elevado, no con obesidad; la opción C es falsa ya que la deshidratación y la alteración de los electrolitos, especialmente el potasio, pueden desencadenar arritmias y otras complicaciones cardíacas; y la opción D es incorrecta porque la transición entre anorexia nerviosa y bulimia nerviosa es relativamente frecuente, especialmente en la fase de recuperación, por lo que no se limita a una minoría.'),
  (912, 'El término «anorexia» procede del griego *an* (sin) + *orexis* (apetito), por lo que su significado literal es la ausencia de apetito; la falta de deseo de comer es el núcleo semántico que distingue la palabra, aunque en la práctica clínica se manifiesta también como una reducción de la ingesta. Las demás opciones, aunque describen manifestaciones de la enfermedad, no corresponden al sentido etimológico: la nula ingesta de alimentos (B) es un resultado clínico, no la raíz del término; el bajo peso (C) es una consecuencia fisiológica y no un componente lingüístico; la restricción alimentaria voluntaria (D) describe la conducta típica del trastorno, pero no refleja el significado literal del vocablo.'),
  (913, 'El DSM‑5 clasifica los trastornos de la conducta alimentaria en categorías específicas; la bulimia nerviosa requiere episodios de ingesta excesiva seguida de conductas compensatorias (vomito, uso de laxantes, ayuno, ejercicio excesivo) y una preocupación marcada por el peso y la forma corporal, además de la presencia de episodios de ingesta excesiva que no se describen en la pregunta. En el caso planteado, la única conducta disfuncional es la purga recurrente sin episodios de ingesta excesiva ni preocupación por el peso, lo que no satisface los criterios de bulimia ni de anorexia nerviosa; tampoco se trata de ortorexia, que se caracteriza por una obsesión por la comida “saludable” y no por purgas. Por tanto, la presentación se ajusta a la categoría de “Otro trastorno alimentario o de la ingestión especificado”, que recoge patrones de conducta alimentaria disfuncional que no cumplen con los criterios de los trastornos principales. Las opciones A y B son erróneas porque implican bulimia nerviosa, la cual exige episodios de ingesta excesiva; la opción C es incorrecta porque la ortorexia se centra en la calidad de la comida y no en purgas sin ingesta excesiva.'),
  (914, 'La opción A es la única que se ajusta a la evidencia clínica: la anorexia nerviosa no responde a fármacos específicos para su sintomatología principal, ya que el tratamiento farmacológico se reserva a comorbilidades como depresión o ansiedad, mientras que la reeducación nutricional y la terapia psicológica son las intervenciones efectivas; las demás alternativas son incorrectas porque la B confunde la demacración del peso con la egodistonía, conceptos que no constituyen los dos factores centrales de la psicopatología anorexica; la C es errónea pues los suplementos nutricionales son parte esencial de la rehidratación y reposición de micronutrientes; y la D es falsa porque la terapia psicodinámica puede ser útil para explorar la dinámica subyacente del trastorno, aunque no es la única opción terapéutica.'),
  (915, 'La opción D es la que se ajusta a la práctica clínica establecida: en los terrores nocturnos la intervención primaria se dirige a los factores precipitantes (por ejemplo, falta de sueño, estrés, consumo de alcohol o medicamentos que alteran el sueño) porque estos son los desencadenantes más frecuentes y modificables; al controlar o eliminar dichos factores se reduce la frecuencia y gravedad de los episodios, lo que constituye la base de cualquier protocolo terapéutico. La alternativa A es incorrecta porque la terapia de ensayo en imaginación (IRT) se emplea principalmente para pesadillas, no para terrores nocturnos, y no se considera una variante de la desensibilización sistemática. La B es errónea porque, aunque la IRT se usa en el tratamiento de pesadillas, su aplicación suele ser grupal o en pareja, no estrictamente individual. La C también es falsa; despertar al paciente durante un episodio de terrores nocturnos puede aumentar la confusión y la excitación, y la recomendación clínica es dejar que el episodio termine de forma segura sin interrumpirlo.'),
  (916, 'El trastorno de comportamiento del sueño REM (TBCREM) se caracteriza por la pérdida de la atonía muscular típica del sueño REM y la realización de movimientos motores vigorosos, a menudo violentos, durante el sueño; su aparición precoz es un hallazgo clínico de gran relevancia porque se ha documentado que el TBCREM es el primer síntoma de la enfermedad de Parkinson y, en menor medida, de otras demencias parkinsonianas como la enfermedad de Lewy, lo que lo convierte en un marcador temprano de neurodegeneración; en contraste, las demás opciones carecen de fundamento: la afirmación de que los trastornos del sueño suelen presentarse en ausencia de otras afecciones clínicas es falsa, ya que la mayoría se asocian con comorbilidades psiquiátricas o médicas; la narcolepsia se relaciona con alteraciones del sistema nervioso central (especialmente la pérdida de neuronas orexigénicas en el hipotálamo), no con el sistema periférico; y la prevalencia de los trastornos del sueño es, al contrario, alta, con estimaciones que oscilan entre el 10 % y el 30 % de la población, por lo que la idea de baja prevalencia es errónea.'),
  (917, 'La narcolepsia se caracteriza por una pérdida de la regulación del sueño y la vigilia que se manifiesta clínicamente en episodios de sueño súbito, cataplejía y alucinaciones hipnagógicas/hipnopómpicas; la evidencia clínica y epidemiológica muestra que la mayoría de los pacientes presentan un aumento del índice de masa corporal (IMC) y una mayor prevalencia de obesidad, probablemente debido a la alteración del metabolismo energético y la reducción de la actividad física, por lo que la opción C refleja la asociación fisiopatológica más robusta y documentada. Por otro lado, la afirmación A es incorrecta porque el test de latencia múltiple del sueño (MSLT) muestra resultados positivos en la mayoría de los casos, no en solo el 2‑4 %; la opción B es falsa porque la cataplejía implica una pérdida de tono muscular sin alteración de la consciencia, y la opción D, aunque describe síntomas típicos, no es la característica más distintiva ni la más prevalente en la narcolepsia.'),
  (918, 'El trastorno de hipersomnia se caracteriza por una somnolencia excesiva que persiste a lo largo del día y, en su forma más grave, puede incluir una prolongada alteración de la alerta tras la transición sueño‑vigilia; la persona aparenta estar despierta pero presenta una marcada disminución de la coordinación motora, conductas inadecuadas, y se observan déficits de memoria, desorientación temporoespacial y sensación de mareo, lo que indica una disfunción del sistema de regulación de la vigilia que se manifiesta en la fase de despertar; por ello la opción A es la que mejor describe ese cuadro clínico. Las demás alternativas son incorrectas porque el trastorno de hipersomnia se distingue de la narcolepsia (que presenta episodios de sueño súbito y pérdida de tono muscular durante la vigilia), del trastorno de la conducta del sueño REM (que implica comportamientos activos durante el sueño REM y no afecta la transición sueño‑vigilia), y del trastorno del despertar del sueño no REM (que se limita a la sensación de “aturdimiento” sin los déficits cognitivos y motores tan marcados descritos).'),
  (919, 'El término “comportamiento suicida” según la CIE‑11 se refiere a las conductas que, aunque no culminan en la muerte, constituyen una acción dirigida a provocar la propia muerte y que, por su naturaleza, se clasifican como intentos de suicidio; por ello la opción C, que describe acciones concretas como la compra de un arma o el almacenamiento de medicamentos realizadas con la intención de terminar con la vida, corresponde a la definición de comportamiento suicida, diferenciándola de los pensamientos suicidas (opción B) que son solo ideaciones sin acción concreta, de la conducta autodestructiva sin intención de muerte (opción A) que carece de la finalidad de terminar la vida, y de las lesiones autoinfligidas con expectativa de daño físico menor (opción D) que no tienen la intención de terminar con la vida.'),
  (920, 'La teoría de la desesperanza de Beck se centra en la cognición negativa y la percepción de falta de control que subyacen a la ideación suicida, pero no distingue explícitamente los procesos que llevan de la ideación al intento; por tanto, no pertenece al enfoque ideación‑a‑acción que separa los mecanismos generadores de ideación de los que facilitan la transición al comportamiento real. En contraste, la teoría interpersonal de Joiner, el modelo integrado motivacional‑volitivo de O’Connor y la teoría de los tres pasos de Klonsky y May sí establecen fases distintas, describiendo factores motivacionales, volitivos y de ejecución que explican la progresión de la ideación a la acción suicida. Las opciones A, C y D, por lo tanto, sí forman parte de este marco, mientras que la opción B no.'),
  (921, 'La opción d) es la única que refleja la evidencia epidemiológica sobre la paradoja de género en la conducta suicida: los hombres tienen una mayor tasa de suicidio consumado, mientras que las mujeres presentan una mayor frecuencia de intentos, lo que explica la diferencia entre la mortalidad y la incidencia de intentos; la opción a) confunde la mortalidad con la incidencia de intentos al afirmar que las tasas de suicidio consumado son similares, cuando en realidad los hombres superan a las mujeres; la opción b) ignora la diferencia estadísticamente significativa entre géneros en la mortalidad por suicidio, y la opción c) limita incorrectamente la mayor mortalidad masculina a una franja etaria específica, cuando la diferencia se observa en la mayoría de las edades adultas.'),
  (922, 'El cuadro descrito corresponde a una indiferencia afectiva, ya que la paciente muestra una marcada reducción de la expresión emocional, falta de contacto afectivo y una actitud frialdad ante estímulos personales, características típicas de la indiferencia que implica una pérdida de la capacidad de experimentar afectos, distinta de la distimia que se caracteriza por un estado de ánimo bajo persistente pero no tan severo, de la rigidez afectiva que se refiere a la inflexibilidad emocional más que a su ausencia, y de la abulia que se centra en la falta de motivación y acción más que en la falta de afecto; por lo tanto, la opción D es la que mejor explica la sintomatología observada.'),
  (923, 'El cuadro clínico descrito corresponde a ataques de ira, ya que la paciente presenta episodios de excitación fisiológica (taquicardia, tensión) acompañados de una intensa necesidad de liberar energía mediante gritos o golpes, sin que exista un miedo a la pérdida de control o a un resultado catastrófico; la sensación de “explotar” indica una tensión acumulada que se libera de forma agresiva, característica de los ataques de ira, los cuales se desencadenan en situaciones de frustración o conflicto interpersonal. Las crisis de angustia (B) se caracterizan por un miedo intenso a la muerte o a perder el control, lo que no se observa aquí; las crisis disociativas (C) implican una pérdida de la realidad o identidad, no la agresividad descrita; y las crisis de ansiedad generalizada (D) se presentan de forma persistente y no episódica, con preocupación constante, lo cual difiere de la episodicidad y la naturaleza agresiva de la paciente.'),
  (924, 'El objetivo que no pertenece a la fase inicial según el programa de Chóliz y Marcos (2020) es la opción B, pues la fase inicial se centra en la evaluación clínica y la construcción de una alianza terapéutica; se analizan la adicción desde una perspectiva biopsicosocial (A), se evalúa la necesidad de intervenir en otras áreas (C) y se trabaja la aceptación del problema por parte del paciente (D), mientras que la información sobre el juego y sus consecuencias se reserva para etapas posteriores de intervención. Las demás opciones son parte de la valoración inicial y la motivación del paciente, por lo que no se consideran incorrectas.'),
  (925, 'El control cognitivo, entendido como la capacidad de supervisar y ajustar la actividad de otros procesos ejecutivos, se ve particularmente comprometido en el trastorno depresivo mayor, pues la dificultad para mantener la atención y la planificación se traduce en patrones de pensamiento negativos y en la imposibilidad de emplear estrategias adaptativas de regulación emocional; la evidencia neuropsicológica muestra que la actividad de la corteza prefrontal dorsolateral y ventromedial se ve reducida, lo que explica la rigidez cognitiva y la falta de flexibilidad que caracterizan la depresión, mientras que la inhibición cognitiva y la memoria de trabajo, aunque también alteradas, no son el eje central del procesamiento de la información y la regulación emocional en este trastorno; la flexibilidad cognitiva, por su parte, se ve afectada pero es más una consecuencia del deterioro del control ejecutivo que una alteración primaria.'),
  (926, 'La hipótesis de la amortiguación sostiene que el apoyo social actúa como un amortiguador frente a los efectos nocivos del estrés, reduciendo la intensidad de la respuesta fisiológica y psicológica a los factores estresantes y, por tanto, mitigando los daños que estos pueden ocasionar en la salud; por eso la opción B es la que refleja fielmente este concepto, pues señala que el apoyo social atenúa los perjuicios que la exposición al estrés produce. Las demás alternativas se apartan de esta idea: la A presume un efecto positivo y directo del apoyo instrumental sin considerar la moderación por el estrés, lo cual no es una premisa de la teoría; la C se centra en conductas perjudiciales, una consecuencia indirecta que la hipótesis no aborda explícitamente; y la D habla de facilidades para conductas promotoras de la salud, una función más propia de la hipótesis de la promoción que de la amortiguación.'),
  (927, 'El sesgo negativo interpretativo, según Beck, implica la tendencia a atribuir causas internas, estables y globales a eventos negativos, lo que favorece la persistencia de la autocrítica y la percepción de incontrolabilidad; la literatura meta‑analítica sobre el trastorno depresivo mayor muestra que este patrón cognitivo se asocia de forma consistente con la gravedad y la recurrencia de la depresión, y se ha identificado como predictor de respuesta a terapia cognitiva, lo que explica su mayor nivel de consistencia frente a los demás errores; la abstracción selectiva (A) se refiere a la tendencia a enfocarse en detalles negativos sin considerar el contexto, pero su evidencia empírica es menos robusta y suele confundirse con la sobregeneralización (D), que implica extrapolar un evento negativo a todos los ámbitos de la vida, una relación más débil con la depresión; las inferencias arbitrarias (C) se centran en la tendencia a hacer suposiciones sin evidencia, pero su relación directa con la depresión es menos específica y su validez se limita a situaciones de alta incertidumbre, por lo que los tres errores restantes presentan menor consistencia clínica en el trastorno depresivo mayor.'),
  (928, 'En los trastornos depresivos se observa una mayor frecuencia de fracaso en las relaciones de pareja que en los trastornos bipolares, debido a que la sintomatología depresiva crónica (sentimientos de culpa, baja autoestima y retraimiento social) deteriora la capacidad de mantener vínculos afectivos estables, mientras que en la bipolaridad la fase maníaca suele reforzar la socialización y la percepción de la pareja, mitigando la ruptura prematura; por tanto, la opción A se sustenta en la relación directa entre la sintomatología depresiva y la calidad de las relaciones interpersonales. Las demás alternativas son incorrectas: la opción B confunde la prevalencia de síntomas atípicos, que es mayor en la bipolaridad; la C es errónea porque la somatización suele ser más frecuente en la depresión; y la D se basa en la epidemiología del periparto, donde la depresión posparto es más frecuente que la bipolaridad.'),
  (929, 'La Terapia Interpersonal (TIP) de Klerman y Weissman se fundamenta en la hipótesis de que la depresión mayor se mantiene por la interacción entre el individuo y su entorno interpersonal; por ello, el protocolo prescribe un abordaje secuencial que prioriza las áreas problemáticas identificadas (conflictos interpersonales, roles, pérdidas y transiciones), interviniendo de forma estructurada y escalonada para maximizar la eficacia clínica y evitar la sobrecarga del paciente; las demás opciones son erróneas porque la TIP no incorpora reestructuración cognitiva (esa es característica de la terapia cognitivo‑conductual), no la conceptualiza como una enfermedad médica de origen neuroquímico (aunque reconoce su componente biológico, el mantenimiento se explica por factores interpersonales) y no ofrece un marco comprensivo completo de la depresión, sino un modelo pragmático y empírico centrado en la relación interpersonal.'),
  (930, 'El DSM‑5‑TR reconoce que el curso de la depresión mayor puede verse modulado por factores socioculturales; la pobreza, el racismo y la marginalización aumentan la exposición a estrés crónico y reducen el acceso a recursos de afrontamiento, lo que explica la variabilidad en la evolución clínica y la persistencia de síntomas, por lo que la opción A se alinea con la descripción del manual; las demás alternativas fallan porque la literatura indica que los varones presentan menos síntomas atípicos que las mujeres, por lo que la opción B es errónea; la recuperación de un episodio mayor suele requerir más de tres meses en la mayoría de los casos y el 30 % no corresponde a datos del DSM‑5‑TR, lo que invalida la opción C; finalmente, la tasa de suicidio consumado tiende a ser más alta en la adolescencia y la adultez temprana, disminuyendo en la adultez media y tardía, por lo que la opción D también es incorrecta.'),
  (931, 'El pronóstico de los trastornos de síntomas neurológicos funcionales (TSNF) se basa en la evidencia de que la edad temprana y el diagnóstico precoz favorecen la recuperación, pues la neuroplasticidad y la menor consolidación de patrones de respuesta disfuncional permiten una mayor eficacia de las intervenciones psicodinámicas y conductuales; por ello la opción C se ajusta a la literatura clínica que indica que la edad temprana y el diagnóstico temprano se asocian con mejor evolución. Las demás opciones son erróneas: la opción A sobreestima la resolución completa, pues la mayoría de los pacientes presentan mejoría parcial o fluctuaciones; la opción B confunde duración prolongada con pronóstico favorable, cuando en realidad la persistencia de síntomas suele correlacionarse con peor evolución; y la opción D generaliza la mejoría espontánea de los ataques psicógenos, aunque la evidencia muestra que la remisión espontánea es rara y que la intervención activa suele ser necesaria.'),
  (932, 'La variable transdiagnóstica que no se ha postulado como común en los trastornos por preocupaciones somáticas es el perfeccionismo orientado a la salud; aunque el perfeccionismo puede aparecer en distintas patologías, la literatura específica sobre trastornos somáticos destaca la amplificación somatosensorial, la intolerancia a la incertidumbre y el pensamiento rumiativo como factores de riesgo y mantenimiento, mientras que el perfeccionismo se asocia más con trastornos de ansiedad generalizada y trastornos obsesivo‑compulsivos, no con la preocupación somática per se. Las demás opciones son consideradas transdiagnósticas en este ámbito: la amplificación somatosensorial explica la mayor sensibilidad a sensaciones físicas, la intolerancia a la incertidumbre motiva la búsqueda constante de información médica y el pensamiento rumiativo perpetúa la interpretación negativa de los síntomas.'),
  (933, 'La terapia de activación conductual de Jacobson (2001) se centra en identificar y aumentar la participación en actividades que generan refuerzo positivo, estructurando un plan de actividades valiosas y trabajando la extinción de evitaciones mediante la exposición gradual a tareas previamente evitadas; por ello la opción B, la programación de actividades valiosas, y la opción C, la extinción de evitaciones, son componentes esenciales de la intervención, mientras que la atención a la experiencia (mindfulness) se incorpora como una técnica complementaria para mejorar la conciencia de los estados internos y facilitar la adherencia al plan de activación, aunque no es exclusiva de la terapia de activación. En contraste, la opción D, los ejercicios de autocompasión, no forma parte del protocolo original de Jacobson, ya que su enfoque se limita a la reestructuración conductual y la exposición a actividades, sin incluir intervenciones centradas en la autocompasión, motivo por el cual se descarta como técnica propia de dicha terapia.'),
  (934, 'La premisa fundamental de la terapia centrada en soluciones de De Shazer sostiene que cada individuo posee recursos internos y fortalezas que, cuando se identifican y activan, pueden catalizar el cambio; esta visión optimista y colaborativa se contrapone a la idea de déficit o necesidad de instrucción, y se basa en la evidencia de que la focalización en las soluciones y los recursos disponibles potencia la autoeficacia y la resiliencia, lo que explica por qué la opción D es la única que refleja la filosofía de la terapia centrada en soluciones. Las demás alternativas son erróneas: la A presupone un déficit de competencia que la terapia no reconoce; la B describe una tendencia de conformismo social que no es una premisa central del modelo; y la C asume una visión estructuralista de las conductas problemáticas, contraria a la orientación de recursos y soluciones.'),
  (935, 'En la terapia centrada en la emoción (TCE) de Greenberg el proceso de cambio se basa en la reexperiencia y reestructuración de la emoción disfuncional; el paciente, al procesar la emoción intensamente y permitir que fluya hasta su resolución, puede sustituir la emoción disfuncional por una respuesta emocional más adaptativa, lo que facilita la integración y la regulación emocional; por tanto, la opción C describe el mecanismo central de la TCE. Las demás alternativas son incorrectas: la A se refiere a técnicas de relajación que, aunque útiles, no constituyen el núcleo del cambio en la TCE; la B describe una estrategia de distanciamiento cognitivo típica de enfoques cognitivo-conductuales, no de la TCE; y la D implica sustitución de emociones por pensamientos racionales, característica de la terapia cognitiva, no de la TCE.'),
  (936, 'La terapia centrada en el presente, tal como la describen Classen, Butler y Spiegel (2001), se fundamenta en la idea de que el proceso terapéutico debe situarse en el aquí y ahora, utilizando la relación entre paciente y terapeuta como principal vehículo de cambio; por ello la opción D es la que refleja fielmente esta característica central, pues la intervención se orienta a mejorar las relaciones interpersonales y a trabajar la experiencia presente del paciente dentro del marco de la alianza terapéutica. Las demás alternativas son erróneas: la opción A describe más bien un enfoque cognitivo‑conductual que se centra en la reestructuración de creencias, no en el presente; la B hace referencia a un formato grupal, que no es inherente a la terapia centrada en el presente, la cual puede aplicarse individualmente; y la C se limita a la reducción de síntomas, omitiendo el énfasis en la relación terapéutica y el trabajo en el momento presente.'),
  (937, 'El enunciado señala que, entre los distintos tipos de trauma, las víctimas de accidentes de tráfico tienden a manifestar una mayor frecuencia de síntomas de sobresalto (hipervigilancia, reactividad fisiológica exagerada) y, al mismo tiempo, presentan un menor nivel de evitación, ya que el trauma suele ser más inmediato y el contexto de la lesión permite una exposición continua a recordatorios; por ello la opción C refleja la diferencia clínica entre los grupos. La alternativa A es errónea porque la reexperimentación (flashbacks, intrusiones) se presenta con igual intensidad tanto en accidentes de tráfico como en agresiones sexuales, sin una mayor prevalencia en un grupo u otro. La opción B falla al afirmar que la evitación es prácticamente ausente en otras categorías, cuando en realidad la evitación es un síntoma transdiagnóstico que se observa en la mayoría de los casos de TEPT, independientemente del tipo de trauma. La respuesta D es incorrecta porque la hiperactivación y los cambios en el estado de ánimo son componentes centrales del TEPT que se observan en todas las categorías de trauma, no solo en terrorismo o maltrato.'),
  (938, 'El trastorno por estrés postraumático complejo, tal como lo define la CIE‑11, se caracteriza por la presencia de los tres clusters de síntomas del TEPT (reexperiencia, evitación y alteraciones cognitivas y de humor) y, además, incorpora un conjunto de síntomas adicionales que reflejan una disfunción profunda en la regulación emocional, el autoconcepto y las relaciones interpersonales; por ello la opción B es la que concuerda con la descripción oficial, pues reconoce la superposición de los síntomas del TEPT con la nueva dimensión de alteraciones interpersonales y de autoconcepto que distinguen al trastorno complejo. La alternativa A es errónea porque el TEPT complejo no excluye la reexperiencia ni la evitación, sino que las mantiene como componentes esenciales. La opción C es incorrecta porque la CIE‑11 no reemplaza la hiperactivación por disociación crónica; la disociación puede estar presente pero no sustituye a los síntomas de hiperactivación. Finalmente, la opción D es falsa porque el especificador “con síntomas disociativos” del DSM‑5‑TR no equivale a la categoría de TEPT complejo de la CIE‑11, que incluye criterios adicionales más allá de la disociación.'),
  (939, 'El factor que se considera un indicador negativo de recuperación en el trastorno por estrés postraumático es la exposición repetida y prolongada a abuso sexual intrafamiliar durante la infancia (opción D); la evidencia clínica muestra que la repetición y la prolongación de experiencias traumáticas en la infancia aumentan la vulnerabilidad a la disfunción psicológica a largo plazo, favoreciendo la consolidación de síntomas persistentes y la aparición de trastornos comórbidos, mientras que la exposición a un solo evento traumático (opción A) no implica la misma carga de riesgo; la elevada reactividad fisiológica inmediata (opción B) puede ser un signo de alarma pero no necesariamente impide la recuperación, pues la respuesta fisiológica puede normalizarse con el tiempo y el tratamiento; el alto apoyo social percibido (opción C) es, por el contrario, un factor protector que facilita la adaptación y la recuperación, por lo que las opciones A, B y C son incorrectas.'),
  (940, 'El episodio se caracteriza por la aparición de síntomas de tristeza, insomnio y preocupación constante tras un evento estresante reciente (el despido), con una duración de dos semanas, lo que encaja en la definición de trastorno de adaptación según CIE‑11 y DSM‑5‑TR, donde la respuesta emocional es desproporcionada al evento pero no alcanza la gravedad de un episodio depresivo mayor ni la intensidad de una ansiedad generalizada; el hecho de que la reacción se limite al contexto laboral y no haya indicios de intrusión persistente o flashbacks descarte el trastorno de estrés postraumático. La opción A se descarta porque la ansiedad generalizada implica preocupación crónica e incontrolable sobre múltiples dominios, no solo sobre la situación laboral; la opción C es inadecuada porque el trastorno de estrés postraumático requiere síntomas intrusivos y evitación de recuerdos traumáticos, lo cual no se menciona; la opción D se excluye porque el episodio depresivo mayor requiere una sintomatología más extensa y persistente, con pérdida de interés y otras alteraciones, no solo tristeza y preocupación.'),
  (941, 'La opción A es la intervención de primera elección porque la exposición prolongada (exposición prolongada a la memoria traumática) está respaldada por la evidencia como la terapia más eficaz para el trastorno de estrés postraumático; permite la habituación de la respuesta fisiológica y la reestructuración cognitiva de los recuerdos intrusivos, reduciendo la evitación y la hipervigilancia, y se adapta a la sintomatología de este paciente que presenta recuerdos intrusivos, pesadillas y ansiedad específica al sonido de frenos. Las demás alternativas son inadecuadas: la terapia centrada en el presente (B) se orienta a la regulación emocional y la integración de la experiencia, pero no aborda directamente la exposición a los recuerdos traumáticos; el entrenamiento en inoculación de estrés (C) se utiliza para la prevención de la ansiedad en situaciones futuras, no para tratar el TEPT ya consolidado; y el debriefing psicológico (D) se reserva para intervenciones tempranas y no se ha demostrado que sea efectivo en la reducción de síntomas de TEPT, pudiendo incluso empeorar la consolidación de los recuerdos traumáticos.'),
  (942, 'En la terapia de procesamiento cognitivo (CPT) el objetivo central es identificar y reestructurar las creencias disfuncionales que mantienen el trastorno por estrés postraumático, por lo que el punto de estancamiento se produce cuando el paciente se aferra a la auto‑culpa por el evento traumático, pues esa creencia perpetúa la disfunción cognitiva y bloquea la re‑evaluación del trauma; la auto‑culpa constituye el núcleo de la distorsión cognitiva que CPT intenta modificar, y su persistencia impide avanzar en la reestructuración. En cambio, la dificultad para expresar y comunicar emociones (B) se considera un síntoma de evitación emocional que puede acompañar al TEPT pero no constituye el punto de estancamiento propio de la CPT, que se centra en las cogniciones, no en la expresión afectiva; la evitación de situaciones que recuerdan el trauma (C) es un mecanismo de afrontamiento que se aborda en la fase de exposición, no un obstáculo cognitivo; y la dificultad para regular emociones intensas (D) es una consecuencia de la disfunción emocional del TEPT, pero no es la creencia central que CPT intenta cambiar, por lo que no representa el punto de estancamiento clínico en esta intervención.'),
  (943, 'El trastorno psicótico breve se caracteriza por la aparición súbita de síntomas psicóticos que duran entre 1 día y 1 mes, con recuperación completa en menos de 6 meses; la literatura diagnóstica y los criterios del DSM‑5 y la CIE‑11 señalan que, aunque pueden presentarse tanto síntomas positivos (delirios, alucinaciones) como negativos (apathy, anhedonia), la catatonía no es típica ni obligatoria en este trastorno, por lo que la opción que indica ausencia de síntomas negativos y presencia de catatonía (A) se ajusta a la descripción clínica más frecuente. Las demás alternativas son incorrectas porque (B) y (C) incluyen la presencia de síntomas negativos, lo cual no es característico del trastorno breve, y (D) combina síntomas positivos, negativos y catatonía, lo que excede el espectro clínico habitual y no se corresponde con la definición diagnóstica.'),
  (944, 'La despersonalización se considera un síntoma frecuente en la fase prodrómica de la esquizofrenia, ya que en esta etapa los pacientes experimentan alteraciones en la percepción del yo y del entorno que pueden preceder a la aparición de los síntomas psicóticos más marcados; por ello la opción B es la que mejor refleja la literatura clínica que describe la evolución de la enfermedad. Las demás alternativas son incorrectas porque la despersonalización no se limita a la fase aguda (opción C) ni es un fenómeno excepcional (opción A), y no se presenta con mayor frecuencia en la fase residual (opción D), donde el cuadro clínico suele haber remitido y los síntomas psicóticos están reducidos.'),
  (945, 'El discurso incomprensible que a veces presenta la esquizofrenia se debe a una alteración de la producción y organización del lenguaje que se asemeja a la afasia sensorial, donde la dificultad radica en la percepción de los estímulos lingüísticos y la integración de la información, provocando que el hablante no pueda comprender ni estructurar adecuadamente sus propios enunciados; en la esquizofrenia, la desorganización del pensamiento y la falta de coherencia semántica generan precisamente esta pérdida de sentido y la imposibilidad de captar el significado propio del discurso. Las demás opciones son incorrectas porque la afasia productiva (B) implica una producción de lenguaje afectada pero con comprensión intacta, lo cual no refleja la incomprensibilidad del propio discurso; la afasia anómica (C) se caracteriza por la dificultad para encontrar palabras concretas, pero el discurso sigue siendo comprensible en su estructura general; y la afasia cortical (D) se refiere a daños en el área cortical del lenguaje, una condición neurológica distinta que no explica la naturaleza psicótica del discurso.'),
  (946, 'La opción C es la que se corresponde con la práctica clínica basada en la evidencia para el manejo de los trastornos psicóticos: la terapia cognitivo‑conductual (TCC) se emplea no solo en la fase aguda, sino también en la fase de remisión, y su objetivo incluye la prevención de recaídas mediante la identificación y modificación de pensamientos disfuncionales, la mejora de la adherencia al tratamiento farmacológico y el fortalecimiento de estrategias de afrontamiento; estos componentes están respaldados por estudios que muestran una reducción significativa de la frecuencia y gravedad de los episodios recurrentes. Las alternativas A y D se contradicen con la literatura que indica que, aunque la intervención individual puede ser más segura en la fase aguda, las intervenciones grupales y familiares también pueden ser útiles y no se desaconsejan de forma absoluta; además, la fase aguda no implica una prohibición total de las intervenciones psicológicas. La alternativa B es errónea porque la TCC sí se aplica en la fase de remisión, precisamente para consolidar los avances terapéuticos y prevenir recaídas, por lo que la afirmación de que no se aplica en esa etapa es falsa.'),
  (947, 'El DSM‑5‑TR define el trastorno bipolar tipo I como la presencia de al menos un episodio maníaco completo, independientemente de si se han producido episodios depresivos mayores; la manía es el criterio diagnóstico primario y la ausencia de episodios depresivos no impide el diagnóstico, por lo que la opción C refleja fielmente la normativa. Las demás alternativas son inexactas: la opción A confunde la etiología con el criterio diagnóstico, pues la historia familiar no es requisito; la opción B describe el tipo II, que requiere hipomanía y depresión mayor, no manía; y la opción D atribuye erróneamente síntomas psicóticos a la hipomanía, cuando los psicóticos pueden aparecer en cualquier fase del trastorno bipolar pero no son obligatorios ni exclusivos de la hipomanía.'),
  (948, 'El DSM‑5‑TR define el episodio hipomaníaco como un período de estado de ánimo anormalmente elevado, expansivo o irritable que dura al menos cuatro días, con un incremento sostenido de la energía y la actividad, pero sin la presencia de síntomas psicóticos ni deterioro funcional grave; la duración mínima de cuatro días es la que distingue al episodio hipomaníaco de la manía, que requiere al menos siete días y sí puede incluir deterioro funcional y síntomas psicóticos. Por tanto, la opción A refleja fielmente la descripción normativa del DSM‑5‑TR. Las demás alternativas son erróneas: la B confunde la hipomanía con la manía, pues la hipomanía no suele requerir hospitalización ni producir deterioro funcional severo; la C introduce una condición que el DSM‑5‑TR no contempla, pues la presencia de síntomas psicóticos implica un episodio maníaco, no hipomaníaco, y la duración mínima sigue siendo de cuatro días; la D altera el intervalo temporal mínimo, que es de cuatro y no siete días, y repite la ausencia de síntomas psicóticos, que sí es característica de la hipomanía.'),
  (949, 'La opción B es la que se ajusta a la evidencia epidemiológica y clínica sobre la esquizofrenia: el sexo masculino se asocia con un inicio temprano, típicamente en la adolescencia tardía o la adultez temprana, mientras que el inicio en las mujeres suele ocurrir en la adultez media, lo que explica la diferencia en la edad de aparición y la presentación clínica; además, la presencia de síntomas negativos y la mayor carga de comorbilidad en hombres se correlaciona con este patrón de inicio precoz. Las demás alternativas resultan incorrectas: la prevalencia de esquizofrenia es globalmente de alrededor del 1 % y no varía sustancialmente entre áreas rurales y urbanas, lo que descarta la A y la C; la evolución de la enfermedad no es más desfavorable en mujeres, sino que suele presentar un curso más favorable con mayor probabilidad de recuperación y menor riesgo de suicidio, lo que invalida la D.'),
  (950, 'El DSM‑5‑TR define el trastorno esquizoafectivo como la coexistencia de un episodio de trastorno del estado de ánimo (depresivo o bipolar) con síntomas psicóticos que, además, se presentan por al menos dos semanas sin la presencia de síntomas afectivos, lo que garantiza que la psicosis no sea simplemente una manifestación del episodio de ánimo; por tanto la opción B resume fielmente este criterio; las demás alternativas son incorrectas: la A confunde la necesidad de simultaneidad con la realidad de que la psicosis puede aparecer aislada; la C equivoca al ubicar el trastorno dentro del espectro bipolar, cuando el DSM lo clasifica como trastorno psicótico con componente afectivo; y la D subestima el periodo mínimo requerido, estableciendo erróneamente una duración máxima de una semana.'),
  (951, 'La afirmación falsa es la A, porque la presencia de alucinaciones visuales, aunque frecuente en el trastorno neurocognitivo mayor o leve con cuerpos de Lewy (TNCCL), no constituye un criterio diferencial frente al trastorno neurocognitivo asociado a la enfermedad de Parkinson; en ambos casos las alucinaciones visuales pueden aparecer, pero en el TNCCL suelen ser más frecuentes, más vívidas y aparecen con mayor rapidez, pero su presencia no excluye la posibilidad de un trastorno neurocognitivo relacionado con Parkinson, por lo que no es un elemento diagnóstico exclusivo. En cambio, la opción B es verdadera, pues la carga funcional del TNCCL suele ser mayor que en el Alzheimer debido a la combinación de deterioro cognitivo, fluctuaciones de atención y síntomas extrapiramidales que afectan la autonomía diaria. La opción C también es correcta, pues la fluctuación de la atención y la alerta es una característica clínica distintiva del TNCCL, con variaciones que pueden ocurrir a lo largo del día. Finalmente, la opción D es cierta, ya que la mayoría de los casos de TNCCL son esporádicos y no presentan antecedentes familiares, a diferencia de otras formas de demencia con componentes genéticos.'),
  (952, 'La opción B es la única que se sostiene ante la evidencia empírica de la práctica clínica en Atención Primaria: estudios controlados randomizados han demostrado que la TCC individual, cuando la lleva a cabo un profesional especializado, reduce de forma sustancial la intensidad de los síntomas somáticos y mejora la funcionalidad, superando tanto el tratamiento habitual como la TCC grupal, cuyo efecto se ve atenuado por la heterogeneidad de los participantes y la falta de personalización del plan terapéutico; en contraste, la opción A se basa en resultados preliminares y no muestra cambios clínicamente relevantes en la calidad de vida, la opción C carece de datos consistentes que vinculen la formación médica con la disminución de consultas, y la opción D, aunque señala limitaciones metodológicas, no reconoce la evidencia de eficacia que sí se ha documentado en ensayos bien diseñados.'),
  (953, 'La opción D resulta incorrecta porque la falta de acceso a intervenciones psicológicas especializadas no conduce necesariamente a una mayor preferencia por el tratamiento farmacológico; en realidad, la ausencia de recursos psicológicos suele generar una subutilización de cualquier forma de tratamiento, tanto farmacológico como no farmacológico, y no implica una inclinación sistemática hacia la medicación, sino más bien una falta de opciones de atención. En contraste, las alternativas A, B y C describen barreras bien documentadas en la literatura perinatal: la ausencia de evaluaciones estandarizadas en atención primaria dificulta la detección precoz (A), el acceso limitado a especialistas en salud mental restringe la disponibilidad de tratamientos adecuados (B), y el estigma asociado a la salud mental durante el embarazo y el posparto impide que las mujeres busquen ayuda (C).'),
  (954, 'El cuadro clínico descrito se ajusta a la definición de episodio depresivo mayor leve o moderado del DSM‑5‑TR, ya que la duración es inferior a dos semanas y la gravedad de los síntomas (ánimo deprimido, insomnio, fatiga, dificultad de concentración y pérdida de interés) no alcanza el umbral de severidad que requeriría un episodio moderado o grave; además, la presencia de una red de apoyo social y la continuidad laboral sugieren un nivel de funcionalidad que no justifica una derivación inmediata a salud mental especializada. Según la Guía NICE 2022, la primera línea para este nivel de gravedad consiste en ofrecer un tratamiento psicológico breve, preferentemente cognitivo‑conductual, dentro de la atención primaria, complementado con apoyo psicoeducativo y seguimiento regular, sin necesidad de iniciar tratamiento farmacológico de inmediato. Las opciones A y B son incorrectas porque la opción A subestima la gravedad al etiquetarla como trastorno adaptativo, mientras que la B propone un inicio farmacológico innecesario en ausencia de criterios de severidad que lo justifiquen. La opción D es errónea porque la guía NICE no recomienda derivación a salud mental especializada ni tratamiento combinado de fármacos e intervención psicológica para episodios leves o moderados gestionables en AP.'),
  (955, 'El modelo de incertidumbre de Dugas et al. (2007) sostiene que la ansiedad generalizada se origina en la percepción de una amenaza constante e impredecible; la respuesta adaptativa que se desarrolla es la evitación cognitiva, es decir, la tendencia a mantener la atención en pensamientos que minimizan la incertidumbre (por ejemplo, rumiación, preocupación constante) y a evitar la confrontación directa con la fuente de la amenaza, porque la incertidumbre no puede ser eliminada por la acción. Por ello, la opción B es la que mejor refleja la teoría, pues la evitación cognitiva constituye la estrategia principal de afrontamiento en la TDA. Las demás alternativas son erróneas: la opción A se refiere a la evitación conductual, que, aunque puede ocurrir en trastornos de ansiedad, no es la respuesta dominante en el modelo de incertidumbre; la opción C sugiere una equivalencia entre evitación cognitiva y conductual, lo cual no se sostiene en la literatura de Dugas, donde la cognición predomina; y la opción D describe la generación de imágenes catastróficas, un síntoma asociado a la ansiedad, pero no a la estrategia de evitación que el modelo identifica como central.'),
  (956, 'La técnica descrita, que consiste en identificar la fuente de preocupación y posponer deliberadamente el proceso de preocupación sin suprimir el desencadenante, corresponde a la terapia metacognitiva de Wells et al. (1996); esta intervención se centra en modificar las estrategias de pensamiento (por ejemplo, la preocupación excesiva) mediante la conciencia y la regulación de los procesos metacognitivos, evitando la supresión y fomentando la tolerancia a la incertidumbre, lo que reduce la ansiedad generalizada; las demás opciones son incorrectas porque el programa de reducción del estrés basado en mindfulness (A) enfatiza la atención plena y la aceptación presente, no la postergación de la preocupación; la terapia de aceptación y compromiso (C) promueve la aceptación de experiencias internas y la acción comprometida con valores, sin posponer la preocupación; y la terapia de exposición y prevención de respuesta (D) se basa en la exposición sistemática a estímulos ansiógenos y la prevención de conductas de respuesta, lo que difiere del enfoque metacognitivo de posponer la preocupación.'),
  (957, 'El trastorno de ansiedad generalizada se caracteriza por una preocupación excesiva y persistente que no se restringe a situaciones específicas, sino que abarca múltiples eventos cotidianos que el individuo percibe como difíciles de controlar; esta preocupación se mantiene durante al menos seis meses y se acompaña de síntomas somáticos y cognitivos que no se limitan a estímulos concretos, lo que distingue al TGA de los trastornos de ansiedad que se activan ante estímulos o situaciones particulares (por ejemplo, fobias específicas o trastorno de pánico). Por tanto, la opción C resume adecuadamente la característica diferencial de la generalización de la ansiedad en el TGA. Las demás opciones describen aspectos que pueden aparecer en varios trastornos de ansiedad: la opción A habla de síntomas en respuesta a situaciones donde podría no haber ayuda, una descripción más amplia que no distingue el TGA; la opción B menciona síntomas inesperados y no limitados a estímulos, pero esta descripción también se aplica a trastornos de pánico y agorafobia; la opción D enumera síntomas físicos y cognitivos comunes a muchos trastornos de ansiedad, sin resaltar la generalización.'),
  (958, 'La técnica de enraizamiento, o grounding, se emplea sobre todo en el manejo de los trastornos disociativos porque su objetivo principal es restablecer la conexión del individuo con el presente y con su entorno, reduciendo la sensación de desconexión, despersonalización o derealización que caracterizan a la disociación; las estrategias de grounding (enfoque en la respiración, sensaciones táctiles, anclaje sensorial, recordatorio de la identidad) actúan directamente sobre los procesos de percepción y memoria episódica, facilitando la integración de la experiencia y la reducción de síntomas disociativos. En contraste, los trastornos psicóticos (B) se centran en la alteración de la realidad perceptiva y la delusión, donde las intervenciones se orientan a la realidad y la cognición, no al enraizamiento sensorial; el trastorno de ansiedad social (C) se trata principalmente con terapia cognitivo-conductual enfocada en la exposición social y la reestructuración cognitiva, sin necesidad de técnicas de grounding; y el trastorno límite de personalidad (D) requiere intervenciones centradas en la regulación emocional y la mejora de la identidad, donde el grounding puede ser útil pero no es la técnica principal, por lo que las opciones B, C y D no corresponden a la utilización principal de esta técnica.'),
  (959, 'El modelo BASK de Braun (1988) describe la organización de la experiencia disociativa en cuatro ejes interrelacionados: conducta, afecto, sensación somática y conocimiento; cada eje representa una dimensión distinta de la experiencia que puede verse afectada por la disociación, y la interacción entre ellos explica la complejidad de los síntomas disociativos. Las demás opciones son erróneas porque sustituyen el eje de conocimiento por memoria biográfica o significados, lo que no corresponde a la propuesta original, y omiten la dimensión somática que es esencial para comprender la alteración de la percepción corporal en los trastornos disociativos.'),
  (960, 'El modelo de terapia interpersonal y de ritmo social (TIPR) postula que la recaída en el trastorno bipolar se origina cuando los ritmos sociales desregulados se combinan con dos vulnerabilidades adicionales: la exposición a eventos vitales estresantes y la falta de adherencia al tratamiento farmacológico; estos dos elementos interactúan con la alteración del ritmo social para precipitar episodios, pues los eventos estresantes generan demandas interpersonales que alteran los ciclos de sueño y actividad, mientras que la no adherencia disminuye la estabilidad neuroquímica y la protección farmacológica, creando un entorno propicio para la recaída. Las demás opciones son incorrectas porque, aunque el consumo de sustancias y los conflictos interpersonales pueden influir en la evolución del trastorno, el modelo TIPR no los identifica como factores de vulnerabilidad primarios; la opción C confunde eventos traumáticos con eventos estresantes y añade la falta de apoyo social, que no forma parte de los tres factores del modelo; y la opción D reduce el modelo a dos elementos, omitiendo el componente crítico de eventos vitales estresantes.'),
  (961, 'El metaanálisis de Turner et al. (2018) concluyó que las intervenciones de entrenamiento en habilidades sociales (EHS) dirigidas a pacientes con trastornos psicóticos generan un efecto significativo sobre los síntomas negativos, los cuales suelen incluir la anhedonia, la falta de motivación y la reducción de la interacción social, y también sobre la psicopatología general, es decir, la gravedad total de los síntomas psicóticos; la evidencia muestra que la mejora en la expresión y la recepción de señales sociales facilita la reducción de la alienación y la percepción de la realidad distorsionada, sin evidenciar cambios sustanciales en el funcionamiento social o en la cognición social. Por tanto, la opción que refleja estos hallazgos es la d). Las demás alternativas son incorrectas porque la opción a) atribuye mejoras al funcionamiento social y a los síntomas psicóticos, lo cual no se apoya en la meta‑análisis; la opción b) sugiere mejoras en la cognición social, un dominio que no mostró beneficio estadísticamente significativo; y la opción c) confunde los síntomas positivos con la psicopatología general, cuando la evidencia apunta a los síntomas negativos como el principal objetivo de la EHS.'),
  (962, 'La CIE‑11 incluye en su sección de trastornos adictivos dos diagnósticos específicos de conductas: el trastorno por juego de apuestas (F63.0) y el trastorno por uso de videojuegos (F63.1); ambos se caracterizan por la presencia de un patrón de conducta persistente que produce deterioro funcional y se mantiene a pesar de consecuencias negativas, con criterios de pérdida de control, tolerancia y abstinencia. Las demás opciones son incorrectas porque la CIE‑11 no contempla un “trastorno de juego patológico” como entidad distinta, ni reconoce la “adicción a las redes sociales” o la “compras compulsivas” como diagnósticos independientes; la compra compulsiva se clasifica dentro de los trastornos de conducta compulsiva (F63.2) y no se incluye en la lista de adicciones comportamentales de la CIE‑11.'),
  (963, 'El trastorno de juego se reconoce como la única adicción conductual formalmente incluida en el DSM‑5‑TR, lo que la opción C confirma; su inclusión se basa en criterios clínicos que evidencian un patrón de juego persistente y problemático, con consecuencias negativas en la vida personal, laboral y social, y se distingue de otras conductas adictivas por su naturaleza no farmacológica. La opción A es errónea porque la prevalencia en España ronda el 1 %–2 %, no el 46 %; la opción B es incorrecta ya que el perfil típico muestra alta impulsividad y baja autodirección, no lo contrario; y la opción D se contradice con la evidencia epidemiológica que indica que el trastorno suele debutar en la tercera década en ambos sexos, con un patrón de desarrollo más rápido en los hombres (efecto telescoping), no más lento en las mujeres.'),
  (964, 'La falacia del jugador se manifiesta cuando un individuo, al participar en actividades de azar, ignora la independencia estadística de los eventos y concluye que la ocurrencia reciente de un resultado afecta la probabilidad de los sucesos futuros, lo que constituye un sesgo cognitivo que distorsiona la percepción de la aleatoriedad; por tanto, la opción D describe correctamente este fenómeno al señalar la falta de consideración de la independencia entre sucesos aleatorios. Las demás alternativas son erróneas: la A se refiere a la disponibilidad de memoria, un sesgo distinto; la B describe una creencia de habilidad o estrategia que altera la probabilidad, lo que corresponde a la ilusión de control, no a la falacia del jugador; y la C habla de una percepción de superioridad personal, lo que corresponde a la autoevaluación positiva, tampoco a la falacia del jugador.'),
  (965, 'El diagnóstico que corresponde es “Juego patológico persistente moderado”, ya que el DSM‑5‑TR clasifica la gravedad del trastorno por juego en función de la cantidad de criterios cumplidos (moderado: 4‑5 criterios; grave: 6‑9 criterios) y de la modalidad de la patología (persistente cuando los criterios se cumplen de forma continua o episódica cuando se presentan episodios aislados); en este caso se observan 6 criterios, lo que indica gravedad, pero la descripción indica que la conducta es continua durante varios años, lo que lo sitúa en la modalidad persistente, por lo que la opción que combina ambos aspectos es la A. Las opciones B y D son incorrectas porque, aunque mencionan la modalidad episódica, la descripción clínica no indica episodios aislados sino una conducta continua. La opción C, “Juego patológico persistente grave”, es errónea porque, aunque la modalidad sea persistente, el número de criterios (6) no alcanza el umbral de gravedad que requiere 7‑9 criterios; por tanto, la gravedad debe clasificarse como moderada.'),
  (966, 'El DSM‑5‑TR establece que la remisión inicial de un trastorno de juego patológico se produce cuando el individuo no cumple con ninguno de los criterios diagnósticos durante un periodo de al menos tres meses, pero sin alcanzar el umbral de doce meses; por tanto la opción B describe correctamente ese intervalo. La alternativa A confiere un periodo insuficiente (señalando seis meses) y no corresponde al criterio de remisión, mientras que las opciones C y D implican periodos de doce y veinticuatro meses, respectivamente, que exceden el rango de remisión inicial y, en consecuencia, no cumplen la definición del DSM‑5‑TR.'),
  (967, 'La compra compulsiva se caracteriza por una disfunción en la regulación de la impulsividad, tanto emocional como cognitiva; los estudios de autoinforme y pruebas neuropsicológicas muestran que estos individuos reportan mayor urgencia emocional (tanto positiva como negativa) y presentan déficits en la impulsividad cognitiva, evidenciados por menor perseverancia y menor premeditación al tomar decisiones de compra, lo que explica la falta de control sobre los impulsos de gasto; en contraste, la opción B es incorrecta porque niega la elevada urgencia emocional que sí se observa en la literatura; la opción C se equivoca al afirmar un mayor funcionamiento ejecutivo, cuando en realidad se observa un deterioro en la atención selectiva y en la capacidad de inhibir respuestas impulsivas; y la opción D falla al indicar que la impulsividad cognitiva no difiere, pues la evidencia muestra que la falta de perseverancia y premeditación es un componente clave de la patología de la compra compulsiva.'),
  (968, 'El modelo de Barlow (2000) distingue entre vulnerabilidad biológica, que se refiere a predisposiciones fisiológicas o neurobiológicas que aumentan la susceptibilidad a trastornos, y vulnerabilidad psicológica, subdividida en general (factores transversales como la baja tolerancia al estrés o la tendencia a la ansiedad) y específica (mecanismos cognitivos o conductuales que favorecen la aparición de un trastorno particular); por tanto la opción C resume fielmente esta clasificación. Las alternativas A y D incluyen una categoría genética o social que Barlow no contempla, y la opción B confunde la biología general y específica, pues la teoría no diferencia entre biología general y específica, sino entre biología y psicología general y específica.'),
  (969, 'El criterio señalado por Bieling et al. (2006) se basa en la necesidad de que el paciente no presente comorbilidades que puedan interferir con la eficacia de la terapia cognitivo‑conductual (TCC) dirigida a los ataques de pánico y la agorafobia; la presencia de trastornos como abuso de sustancias o depresión mayor suele requerir un abordaje previo o simultáneo para estabilizar la condición y evitar que dichos trastornos condicionen la respuesta al tratamiento de ansiedad, por lo que su ausencia constituye un requisito práctico y clínico para la inclusión en un programa de TCC; las demás opciones son incorrectas porque la atribución orgánica (A) no es un criterio de selección, la gravedad de la agorafobia (B) no determina la elegibilidad y la recurrencia de ataques sin cumplir los criterios diagnósticos completos (C) no garantiza la adecuación del protocolo de TCC, ya que la intervención se basa en la presencia diagnóstica formal.'),
  (970, 'La respiración lenta o diafragmática se emplea en la terapia cognitivo‑conductual del trastorno de pánico precisamente para regular la respuesta fisiológica de la ansiedad, reduciendo la hiperventilación y la hipocapnia que suelen acompañar las crisis; sin embargo, no es un componente obligatorio en todas las situaciones, pues su objetivo es moderar la intensidad de la ansiedad sin eliminarla, evitando que el paciente se convierta en una conducta de evitación que perpetúe el miedo; estudios de exposición combinada han demostrado que la inclusión de la respiración diafragmática mejora sistemáticamente los resultados, pues facilita la tolerancia a la ansiedad durante la exposición, pero no se requiere de una evaluación individualizada que impida su uso en grupos, ya que la técnica puede enseñarse de manera estandarizada y supervisada en sesiones grupales. Las opciones A y D son erróneas porque la respiración diafragmática no es necesaria en todas las crisis ni requiere un entrenamiento individualizado exclusivo; la opción C, aunque parcialmente correcta, omite el aspecto de regulación de la ansiedad y la prevención de conductas de evitación, por lo que no representa la afirmación más completa.'),
  (971, 'La respuesta que mejor describe una estrategia de afrontamiento típica de la hipocondría es la opción B: ducharse a oscuras para no detectar posibles signos o síntomas en el cuerpo, ya que la hipocondría se caracteriza por una preocupación excesiva por la presencia de enfermedades y una interpretación catastrofista de cualquier sensación corporal; al eliminar la luz, la persona reduce la posibilidad de observar y, por ende, de interpretar erróneamente cualquier anomalía física, lo que le permite evitar la ansiedad que provocan las sensaciones corporales. La opción A, aunque implica evitación social, no se centra en la percepción de síntomas físicos, por lo que no es una respuesta de seguridad específica de la hipocondría. La opción C, dejar de buscar información médica, es una medida de control cognitivo que puede ser útil, pero no constituye una estrategia de escape del estado ansioso en el sentido de evitar la percepción de síntomas; más bien, reduce la exposición a estímulos que aumentan la ansiedad. La opción D, lavarse las manos frecuentemente, es una conducta de higiene que puede asociarse con la obsesión por la limpieza, pero no se orienta a escapar de la ansiedad sobre la enfermedad, sino a reforzar la sensación de control sobre la contaminación.'),
  (972, 'En el tratamiento cognitivo‑conductual de la hipocondría, la eliminación de conductas de seguridad debe iniciarse en la fase intermedia‑avanzada del proceso terapéutico, cuando el paciente ya ha consolidado la reestructuración cognitiva y la exposición a la ansiedad; comenzar en la fase final implicaría que el paciente ya haya desarrollado una dependencia de las conductas de seguridad, lo que aumentaría el riesgo de abandono y la recaída, por lo que la afirmación A es la que se contradice con la práctica clínica establecida. La opción B es coherente con la selección de conductas de seguridad basándose en su nivel de ansiedad y su interferencia funcional, mientras que la opción C refleja la preferencia por conductas observables y de control voluntario, que son más susceptibles de ser modificadas mediante la exposición y la reestructuración; la opción D, por su parte, reconoce la utilidad de los experimentos conductuales como complemento de la eliminación directa, permitiendo al paciente comprobar la veracidad de sus creencias y reducir la ansiedad de manera más efectiva. Por tanto, las demás opciones son consistentes con los principios del tratamiento cognitivo‑conductual de la hipocondría.'),
  (973, 'La opción C es la que corresponde al objetivo de la reestructuración cognitiva en hipocondría: se busca que el paciente comprenda que la causa del malestar no radica en los síntomas físicos ni en los pensamientos intrusivos sobre la enfermedad, sino en la interpretación distorsionada y la valoración disfuncional de dichos síntomas, de modo que se reduzca la ansiedad y la preocupación; las demás alternativas son incorrectas porque la técnica de la doble columna (A) sí se emplea para identificar y modificar cogniciones disfuncionales; el debate directo del contenido de la amenaza (B) puede generar confrontación y no se recomienda antes de establecer una relación terapéutica sólida; y los experimentos conductuales (D) se planifican después de haber modificado las valoraciones disfuncionales, no antes.'),
  (974, 'El modelo alternativo del DSM‑5‑TR, denominado “modelo dimensional de rasgos de personalidad”, propone cinco dominios transdiagnósticos que capturan la variabilidad de los rasgos patológicos: afecto negativo, desapego, antagonismo, desinhibición y psicoticismo; estos dominios permiten una evaluación más fina de la personalidad clínica y se alinean con la estructura de los trastornos de la personalidad. La opción A refleja precisamente estos cinco ámbitos, por lo que es la respuesta adecuada. Las demás alternativas describen constructos que pertenecen a modelos teóricos distintos: la opción B corresponde al modelo de “dimensiones de la personalidad” de la psicología de la personalidad (por ejemplo, el modelo de la personalidad de la Universidad de California, Los Ángeles), la opción C recoge rasgos que se encuentran en el “modelo de los rasgos de la personalidad de la psicología clínica” (por ejemplo, el modelo de la personalidad de la Universidad de Harvard), y la opción D mezcla dominios que pertenecen al modelo de “Trastornos de la Personalidad” del DSM‑5‑TR con conceptos que no forman parte de los cinco dominios del modelo alternativo, por lo que son incorrectas.'),
  (975, 'El rasgo distintivo que permite diferenciar el trastorno de personalidad límite (TPL) del trastorno histriónico es la presencia de arrebatos coléricos y conductas autodestructivas, que reflejan la marcada inestabilidad afectiva y la impulsividad característica del TPL; estos episodios de ira intensa y la tendencia a la autolesión o al suicidio son infrecuentes en el trastorno histriónico, donde la búsqueda de atención y la teatralidad predominan. Las otras opciones describen manifestaciones que pueden aparecer en ambos trastornos: la búsqueda de atención y la conducta manipuladora son comunes en el histriónico y también pueden presentarse en el TPL, mientras que la rápida variación emocional es típica de ambos, aunque en el TPL la intensidad y la frecuencia son mayores; por lo tanto, la opción C es la que más claramente diferencia clínicamente los dos perfiles.'),
  (976, 'La técnica “Párate, Escucha y Mira” se emplea en la fase media de la terapia basada en la mentalización, tanto en sesiones individuales como grupales, y su propósito es estimular la capacidad del paciente para observar y reflexionar sobre sus propios estados mentales y los de los demás, promoviendo así la mentalización; por ello la opción C describe correctamente su uso y objetivo. Las demás alternativas son erróneas: la A confunde la técnica con un procedimiento de cierre terapéutico orientado a la pérdida, lo cual no corresponde a su función; la B lo sitúa en la fase inicial y en formato individual con el fin de involucrar al paciente, cuando en realidad se aplica más adelante y puede ser grupal; y la D la ubica en la fase final y la presenta como una herramienta de contraste entre percepciones, lo cual no es su finalidad principal.'),
  (977, 'La respuesta es la opción C porque Guidano, al elaborar su modelo de psicoterapia cognitiva posracionalista, identificó cuatro organizaciones de significado personal que estructuran la experiencia subjetiva: la fóbica, la obsesiva, la depresiva y la dependiente, cada una vinculada a un esquema de interpretación del mundo que conduce a patrones de pensamiento y conducta disfuncionales; la categoría “narcisista” no aparece en su clasificación, pues Guidano la considera una construcción más propia de la psicopatología clásica y no como una organización de significado personal en su enfoque posracionalista. Las demás alternativas (A, B y D) sí están explícitamente incluidas en el modelo, pues cada una corresponde a una de las cuatro estructuras de significado que Guidano propone para explicar la disfunción cognitiva y la resistencia al cambio terapéutico.'),
  (978, 'La opción A es la que cuenta con un grado de evidencia sólido porque los estudios de intervención clínica muestran que la combinación de psicoterapia (por ejemplo, terapia cognitivo‑conductual o terapia interpersonal) y farmacoterapia con antidepresivos reduce significativamente la frecuencia de intentos y la ideación suicida en pacientes con trastorno depresivo mayor, especialmente cuando se aplica de forma temprana y continua; la evidencia proviene de ensayos controlados aleatorios y revisiones sistemáticas que establecen la eficacia de esta estrategia de tratamiento en la prevención de la conducta suicida. En contraste, la opción B, aunque útil para la prevención primaria, se basa principalmente en estudios de casos y no en ensayos controlados que demuestren su eficacia específica en la reducción de la conducta suicida; la opción C, el entrenamiento de guardianes o gatekeepers, tiene evidencia moderada y se limita a la detección temprana, no a la prevención directa; y la opción D, la formación a profesionales sanitarios, se sustenta en estudios de mejora de competencias, pero no en datos concluyentes sobre la reducción de la conducta suicida, por lo que su nivel de evidencia es inferior al de la intervención farmacológica y psicoterapéutica.'),
  (979, 'El discurso refleja una visión grandiosa de sí mismo, una necesidad constante de admiración y una falta de empatía hacia los demás, rasgos que constituyen la esencia del trastorno narcisista de la personalidad según el modelo alternativo del DSM‑5‑TR; la frase “Yo no necesito que nadie me diga lo que está bien o mal” indica una autoestima inflada y una tendencia a invalidar las normas externas, mientras que “Si tus amigos o tu familia no te apoyan, mejor prescinde de ellos” muestra una actitud de desprecio hacia la relación interpersonal y una falta de reconocimiento de la importancia de los vínculos afectivos, todo lo cual se alinea con los criterios de narcisismo. Las demás opciones son incorrectas: la opción A (antisocial) se caracteriza por la violación de los derechos de los demás y la falta de remordimiento, no por la búsqueda de admiración; la opción B (evitativa) implica miedo al rechazo y una baja autoestima, lo opuesto a la autoconfianza desmedida del discurso; la opción D (límite) se centra en la impulsividad, la inestabilidad emocional y la autoimagen fluctuante, aspectos que no aparecen en el texto.'),
  (980, 'El episodio descrito se ajusta a la simulación porque el paciente presenta una alteración de la conciencia (mutismo, flexibilidad cérea y ausencia de dolor) que aparece de forma súbita y desaparece de manera brusca en un momento de alta motivación (la hora de la comida), sin evidencia de alteraciones neurológicas (EEG normal) ni de un trastorno catatónico que requeriría síntomas persistentes y una alteración de la respuesta a estímulos más allá de la comida; además, la aparición de la sintomatología justo después de un conflicto familiar y su rápida resolución con la comida sugieren una conducta voluntaria dirigida a obtener una recompensa (dinero o atención). El estupor disociativo implicaría una pérdida de la respuesta a estímulos dolorosos con una alteración de la identidad o la conciencia que no se describe aquí; el estupor orgánico requeriría hallazgos patológicos en el EEG o en la neuroimagen; el estupor catatónico se caracterizaría por síntomas más persistentes y una respuesta a la comida no tan específica. Por tanto, la opción D es la más coherente.'),
  (981, 'La afirmación correcta es la B porque la Parent–Infant Psychotherapy (PIP) se fundamenta en una teoría transgeneracional que sostiene que los patrones de relación y los conflictos no resueltos de los progenitores se reproducen en la relación con el bebé, y la intervención se centra en identificar y modificar estos patrones para favorecer un vínculo seguro; la propuesta de la App Padre (opción A) no forma parte de la PIP, la evidencia no indica mayor eficacia en preescolar que en la primera infancia (opción C) y la PIP no se limita al entrenamiento de habilidades conductuales (opción D), sino que aborda la dinámica relacional y la internalización de roles parentales.'),
  (982, 'La caja de arena constituye la única técnica que facilita la elaboración simbólica del trauma en niños y adolescentes porque permite que el paciente proyecte sus experiencias internas en un entorno tridimensional, manipulando figuras y objetos que representan eventos, emociones y relaciones; el proceso creativo y la interacción con el espacio simbólico favorecen la integración de recuerdos disociados y la reestructuración de la narrativa traumática, algo que no se logra de forma directa con la reexperimentación emocional, la técnica 5‑4‑3‑2‑1 o el escaneo corporal, que se centran más en la regulación fisiológica, la atención sensorial o la reexpresión de sensaciones sin ofrecer un medio explícito para la construcción simbólica de la trama traumática.'),
  (983, 'La opción A es la que se ajusta a la práctica clínica basada en la evidencia, pues la participación familiar constituye un componente esencial del tratamiento de conductas autolesivas y suicidas en adolescentes, ya que la familia puede proporcionar apoyo emocional, supervisión y recursos que favorecen la adherencia al plan terapéutico y reducen la probabilidad de recaída; además, la intervención familiar permite identificar y modificar factores de riesgo como la falta de comunicación o el conflicto intergeneracional, elementos que suelen perpetuar el comportamiento autolesivo. Las demás alternativas son erróneas: la B ignora la obligación ética de informar y proteger al menor cuando la confidencialidad puede poner en riesgo su vida, y la C promueve la exposición innecesaria a detalles que pueden reforzar la conducta y aumentar la ansiedad familiar; la D, aunque reconoce la importancia de evaluar el contexto familiar, subestima la utilidad de la intervención familiar incluso cuando existen conflictos, pues la terapia familiar puede ser adaptada para manejar dichos problemas sin que resulte contraproducente.'),
  (984, 'El Programa HANEN se caracteriza por su enfoque de entrenamiento familiar, donde los progenitores reciben una formación intensiva y luego aplican las estrategias de intervención en el entorno cotidiano del niño, convirtiéndose en los principales agentes de cambio; esta descripción coincide con la opción d, pues el programa enfatiza la capacitación de los cuidadores como facilitadores de la adquisición de habilidades sociales, comunicativas y de autocontrol, con seguimiento y supervisión profesional inicial. Las demás opciones son incorrectas: la A describe un modelo que mezcla conductual y evolutivo en contextos naturales, pero no enfatiza la formación parental; la B se refiere a un enfoque mixto con la metodología SCERTS, que no corresponde al marco de HANEN; y la C se centra en un programa puramente conductual con reforzadores naturales y análisis funcional, lo cual no refleja la naturaleza centrada en la familia del programa HANEN.'),
  (985, 'El tratamiento conductual con pautas para los padres o cuidadores es el más recomendado porque la evidencia clínica demuestra que las intervenciones dirigidas a la familia mejoran la estructura ambiental, la consistencia en la disciplina y la comunicación, factores críticos para la regulación de la atención y la impulsividad en niños con TDAH, y se ha demostrado que reducen la severidad de los síntomas y mejoran el rendimiento escolar; además, la intervención familiar permite la generalización de estrategias de manejo en el contexto cotidiano, algo que las otras opciones no garantizan. El neurofeedback (A) carece de evidencia robusta y su aplicación práctica en la infancia es limitada; el tratamiento farmacológico (B) es eficaz para la reducción de síntomas, pero no aborda la modificación de conductas y la interacción familiar, por lo que no constituye la primera línea terapéutica en la práctica clínica; el entrenamiento en habilidades sociales (C) es útil para mejorar la interacción social, pero no interviene directamente en la atención y la hiperactividad, y suele complementarse con otras modalidades.'),
  (986, 'El Cool Little Kids es un programa de intervención breve y estructurado que se centra en la prevención y el tratamiento de la agresión y la conducta antisocial en niños de edad temprana, por lo que la opción D es la única que coincide con la descripción de su población objetivo, ya que el programa está específicamente diseñado para niños con un temperamento impulsivo y propenso a la agresión, no para aquellos con temperamento inhibido; la opción A es incorrecta porque el programa no se limita a niños con trastornos de conducta diagnosticados, sino que se aplica a niños con conductas problemáticas tempranas; la opción B es errónea pues el Cool Little Kids se dirige a niños de 4 a 7 años, no a adolescentes de 10 a 14 años; y la opción C es inexacta porque el enfoque del programa es conductual y cognitivo‑conductual, no psicodinámico.'),
  (987, 'La opción B es la adecuada porque el trastorno de ansiedad generalizada en adolescentes se trata eficazmente con intervenciones cognitivo-conductuales estructuradas; el programa No Worries! es un protocolo grupal específicamente diseñado para este grupo etario, que combina reestructuración cognitiva, técnicas de relajación y estrategias de afrontamiento contextualizadas a la vida escolar y familiar, y cuenta con evidencia empírica de eficacia en la reducción de síntomas y mejora funcional; la exposición en vivo (A) y en imaginación (C) son técnicas útiles para fobias específicas o trastornos de ansiedad con componentes de miedo concreto, pero no son la primera línea para la ansiedad generalizada, que requiere un enfoque más amplio y orientado a la cognición; la alternativa D es incorrecta porque existe una sólida base de estudios que avalan la eficacia de la terapia cognitivo-conductual y de programas específicos como No Worries! en la población adolescente.'),
  (988, 'El abandono escolar, el absentismo escolar y la mala relación con los iguales son factores de riesgo socioambientales o contextuales reconocidos en la literatura sobre conducta suicida infantojuvenil, ya que reflejan alteraciones en la interacción social, la integración escolar y el soporte de pares, elementos que influyen directamente en la percepción de pertenencia y en la exposición a situaciones de estrés social; en cambio, la baja motivación académica es una característica interna del individuo que, aunque puede contribuir al deterioro del bienestar, no se considera un factor de riesgo contextual porque no implica una alteración directa del entorno social o escolar, sino una actitud interna que puede ser modificada sin intervención en el contexto externo. Las opciones A, C y D se agrupan como factores socioambientales porque implican cambios en la estructura social y educativa que aumentan la vulnerabilidad a la conducta suicida.'),
  (989, 'La disfasia evolutiva o trastorno específico del lenguaje es una alteración neurodesarrollada que persiste más allá de la edad escolar y, a diferencia de otras dificultades del lenguaje, no se resuelve con la madurez; por ello, la literatura clínica indica que los déficits funcionales continúan en la adolescencia y en la edad adulta, incluso cuando el paciente ha recibido intervención temprana, ya que la recuperación completa depende de la gravedad inicial y de la continuidad del tratamiento, y la evidencia muestra que la mayoría de los casos siguen presentando dificultades de comprensión y producción de lenguaje en la adultez. Por consiguiente, la opción B refleja la continuidad de los síntomas. Las demás alternativas son erróneas: la A presupone una desaparición del trastorno tras la intervención precoz, lo cual no se sostiene en estudios longitudinales; la C confunde la naturaleza de la disfasia, que afecta tanto la comprensión como la expresión, y la D sobreestima la predominancia fonológica, pues la disfasia afecta de manera más amplia los aspectos semánticos y pragmáticos del lenguaje.'),
  (990, 'El hallazgo evolutivo que se ha documentado al comparar la presentación clínica del trastorno de ansiedad generalizada (TAG) entre niños y adolescentes es que, aunque ambos grupos muestran índices comparables de síntomas específicos, los adolescentes presentan un mayor número total de síntomas y niveles más elevados de ansiedad y depresión, lo que sugiere una intensificación del trastorno con la maduración y la exposición a factores de riesgo psicosociales propios de la adolescencia; esta conclusión se sustenta en estudios longitudinales que evidencian un incremento de la carga sintomática y la comorbilidad con trastornos depresivos en la etapa adolescente. En contraste, la opción A es incorrecta porque la ideación suicida y los síntomas cognitivos no se presentan con mayor frecuencia en niños menores de 12 años; la opción B es errónea pues el criterio de preocupación excesiva sí se aplica a niños, aunque la expresión somática sea más frecuente; y la opción D es falsa porque el TAG no es infrecuente antes de la adolescencia ni requiere una duración de 12 meses para su diagnóstico en niños.'),
  (991, 'El patrón de apego descrito, con alta ansiedad relacional y alta comodidad por la cercanía, corresponde al estilo preocupado‑ambivalente, caracterizado por la búsqueda constante de aprobación y la inquietud ante la disponibilidad del cuidador, lo que genera una tensión interna entre el deseo de cercanía y el temor al abandono; este patrón se diferencia del estilo seguro, que combina confianza y autonomía, del estilo rechazante‑evitador, que muestra evitación de la intimidad, y del estilo temeroso‑desorganizado, que presenta incoherencia y miedo simultáneo a la cercanía y al rechazo.'),
  (992, 'La opción B es la que mejor refleja la evidencia clínica sobre la depresión en la infancia y adolescencia; la irritabilidad, el enfado y la frustración son expresiones frecuentes de la tristeza en niños y adolescentes, a menudo más evidentes que la expresión verbal de melancolía, y su presencia se considera un síntoma clave en el diagnóstico de depresión infantojuvenil. En contraste, la opción A es errónea porque los pensamientos de inutilidad y desesperanza, aunque presentes, no son más comunes en los niños pequeños que en los adolescentes; de hecho, la cognición abstracta necesaria para esos pensamientos suele desarrollarse más en la adolescencia. La opción C se rechaza porque los autoinformes confiables requieren de una cierta madurez verbal y cognitiva que la mayoría de los niños menores de 7‑8 años no poseen, por lo que la fiabilidad de los cuestionarios a partir de los 3 años es muy limitada. Finalmente, la opción D presenta una visión simplista y desactualizada, pues la depresión en la infancia ya involucra tanto procesos cognitivos como fisiológicos y motores, y la transición a la adolescencia no implica una exclusión de los sistemas cognitivos, sino una interacción más compleja entre ellos.'),
  (993, 'La opción A es la única que refleja la evidencia clínica actual: para la depresión infantil no existen tratamientos con nivel 1 o 2 de apoyo empírico, mientras que la TCC individual está bien establecida (nivel 1) para la depresión adolescente, con estudios que muestran eficacia comparable a la farmacoterapia; las demás opciones son incorrectas porque la opción B sobreestima el nivel de evidencia en niños (no hay estudios de nivel 1), la opción C confunde la modalidad de TCC (la individual es la más efectiva en ambos grupos, no se reserva la de grupo o interpersonal en adolescentes) y la opción D subestima la evidencia de la TCC en adolescentes y sobrevaloriza la medicación, pues la fluoxetina sí cuenta con nivel 1 de apoyo empírico, pero la TCC también tiene ese nivel.'),
  (994, 'La encopresis se diagnostica cuando el niño tiene al menos cuatro años de edad y presenta al menos un episodio de evacuación fecal en ropa interior cada mes durante un periodo de tres meses consecutivos; estos criterios reflejan la persistencia del comportamiento y la incapacidad de controlar la defecación, aspectos centrales del trastorno según el DSM‑5‑TR. La opción C coincide con estos requisitos, pues indica la edad mínima de cuatro años y la frecuencia mínima de un episodio mensual durante tres meses, lo que garantiza que el cuadro no sea transitorio ni aislado. Las demás alternativas son incorrectas porque la A establece una edad demasiado alta (seis años) y una frecuencia mensual insuficiente (dos episodios al mes) para demostrar la persistencia; la B reduce la edad mínima a cinco años y exige una frecuencia semanal que excede el estándar del DSM‑5‑TR; la D reduce la edad a cuatro años pero fija una frecuencia de dos episodios semanales durante solo un mes, lo cual no satisface el requisito de duración de tres meses.'),
  (995, 'La respuesta se fundamenta en la evidencia clínica que sostiene que el entrenamiento en hábitos defecatorios, basado en el condicionamiento operante, constituye la técnica conductual multicomponente más aceptada para lograr la defecación regular en el retrete; este método combina el refuerzo positivo de la evacuación voluntaria con la programación de horarios, la motivación mediante recompensas y la supervisión de la respuesta fisiológica, lo que permite consolidar un patrón de defecación autónomo y regular. Las demás opciones son incorrectas porque el biofeedback anorrectal (A) se centra en la retroalimentación muscular y no en el refuerzo conductual; la alarma fecal (C) emplea un estímulo externo para provocar la evacuación, pero se basa en el condicionamiento clásico y no en el reforzamiento de la conducta deseada; y la práctica positiva contingente (D) no constituye una técnica específica ni multicomponente reconocida para la encopresis, ya que se limita a la aplicación de refuerzos sin la estructuración de horarios ni la supervisión de la respuesta fisiológica.'),
  (996, 'La afirmación A es la única que coincide con la evidencia epidemiológica de la discapacidad intelectual: en la mayoría de los casos no se identifica una causa específica, estimándose que alrededor del 50 % de los pacientes no presentan una etiología claramente definida, lo que refleja la complejidad genética y ambiental de la condición; en contraste, la opción B es incorrecta porque la prevalencia varía según la región y los criterios diagnósticos, no permanece constante a nivel mundial; la opción C es errónea porque la distribución de la gravedad no se describe con un 75 % leve y 25 % grave, sino que la mayoría de los casos son leves o moderados, pero las cifras exactas difieren; y la opción D es falsa porque la discapacidad intelectual adquirida suele manifestarse de forma aguda o subaguda, no de manera insidiosa.'),
  (997, 'La opción B es la que se ajusta a la evidencia clínica y a las guías diagnósticas actuales: la esquizofrenia infantil suele aparecer de forma súbita tras un periodo de desarrollo normal o casi normal, con un deterioro rápido de la función social y cognitiva que caracteriza la fase de aparición temprana de la enfermedad; este patrón de evolución se diferencia de la progresión lenta o de la aparición gradual de síntomas en otras afecciones del espectro autista o trastornos del desarrollo. En contraste, la opción A es incorrecta porque el diagnóstico diferencial con el trastorno del espectro autista no se basa en la presencia de creencias e intereses atípicos, sino en la falta de reciprocidad social y la presencia de patrones de comportamiento restringidos y repetitivos; la presencia de creencias delirantes no es característica del TEA. La opción C es errónea porque tanto el DSM‑5‑TR como la CIE‑11 mantienen la esquizofrenia como una única entidad diagnóstica, sin separar categorías por edad; las diferencias se reflejan en criterios de edad de inicio y en la descripción de los síntomas, pero no en la creación de una categoría distinta. Finalmente, la opción D es falsa porque, aunque los síntomas psicóticos pueden compartir ciertos elementos, el contenido y la forma de las alucinaciones y delirios en la esquizofrenia infantil suelen ser más concretos, menos elaborados y más ligados a la realidad inmediata, en contraste con los patrones más abstractos y complejos observados en la esquizofrenia adulta.'),
  (998, 'El trastorno de la comunicación social (pragmática) se caracteriza por dificultades persistentes en el uso flexible del lenguaje y el comportamiento social, y es frecuente que coexistan problemas de conducta y trastornos específicos del aprendizaje, ya que la incapacidad para adaptar el lenguaje a contextos sociales puede generar frustración y dificultades académicas; por tanto la opción A refleja la realidad clínica de la comorbilidad. La opción B es incorrecta porque, cuando se cumplen los criterios del trastorno del espectro autista, se diagnostica ese trastorno y no se añade el trastorno pragmático como diagnóstico adicional, pues el primero abarca la sintomatología pragmática. La opción C es errónea porque la falta de competencia no se limita al lenguaje verbal; el no verbal (gestos, expresiones faciales, contacto visual) también suele verse afectado. La opción D es falsa porque los patrones restrictivos y repetitivos son característicos del espectro autista, no del trastorno pragmático aislado.'),
  (999, 'El trastorno negativista desafiante se caracteriza por una actitud de oposición y desafío hacia figuras de autoridad; la literatura clínica indica que la severidad de la conducta desafiante es más frecuente y más persistente en niñas que en niños, probablemente debido a la mayor exposición a la crítica y a la presión de cumplir con normas de género que generan frustración y rebelión; por tanto, la opción D se sostiene porque los estudios longitudinales muestran que el riesgo de desarrollar síntomas graves es mayor en chicas cuando se presentan factores de riesgo parental, como la disciplina estricta o la falta de apoyo emocional, mientras que en varones la relación con la severidad parental es menos consistente. Las demás alternativas son erróneas: la A es falsa porque el inicio temprano del trastorno negativista desafiante suele asociarse a una mayor recurrencia y a un peor pronóstico, no a una mayor estabilidad; la B es incorrecta pues la prevalencia es similar entre géneros, aunque la incidencia puede variar ligeramente con la edad, pero no se observa una mayor prevalencia en varones; la C es inexacta porque no existe evidencia robusta que vincule a los inmigrantes de primera generación o a los refugiados con un mayor riesgo de este trastorno, por lo que las opciones A, B y C comparten la falacia de generalizar datos sin respaldo empírico.'),
  (1000, 'La intervención que utiliza el juego como contexto terapéutico central y estructurado para el entrenamiento parental es la terapia de interacción padres‑hijos (PCIT), ya que en esta modalidad el terapeuta observa y guía la interacción en tiempo real dentro de una sesión de juego, proporcionando retroalimentación inmediata sobre el uso de comandos, reforzadores y límites, lo que permite a los padres practicar habilidades de disciplina y afecto en un entorno controlado y replicable; las otras opciones no emplean el juego de manera estructurada para la formación parental: el programa Triple P se basa en estrategias de comunicación y disciplina a través de sesiones de grupo o individual, sin un componente de juego terapéutico; The Incredible Years combina sesiones de grupo y entrenamiento parental con actividades lúdicas, pero el juego no es el eje central de la intervención; y el entrenamiento en Manejo para Padres Oregón (PMT‑O) se centra en la enseñanza de técnicas de manejo conductual mediante instrucciones verbales y ejercicios de práctica, sin incorporar el juego como herramienta primaria.'),
  (1001, 'El mecanismo central del modelo de Patterson sobre la coerción es el refuerzo mutuo entre las conductas del niño y las respuestas de los padres, donde cada conducta desafiante del niño provoca una reacción de los padres que, en lugar de corregirla, la refuerza (por ejemplo, atención, escape o alivio del estrés), perpetuando así el ciclo de conducta disfuncional; las demás opciones son incorrectas porque la falta de consecuencias negativas (A) describe una consecuencia de la coerción pero no el proceso de mantenimiento, el déficit de habilidades lingüísticas (B) no es un componente teórico del modelo de Patterson, y el exceso de control parental (C) se considera más un antecedente de la coerción que el mecanismo que sostiene la conducta desafiante.'),
  (1002, 'La afirmación B es la que se aparta de la práctica clínica establecida: asegurar la confidencialidad de todas las conductas del menor no es viable ni ético, ya que la confidencialidad debe limitarse a la información relevante para la intervención y a la protección de la integridad del paciente, sin incluir conductas que no sean pertinentes o que puedan comprometer la seguridad; además, la confidencialidad no se extiende a la “confidencialidad de conductas” sino a la información comunicada por el paciente, por lo que la propuesta de B viola tanto la normativa ética como la lógica de la alianza terapéutica. Por el contrario, las demás opciones describen principios aceptados: la desconfianza inicial (A) se interpreta como una respuesta adaptativa y se maneja con paciencia; el silencio o la evitación (C) se tolera sin interpretaciones precipitadas para no invalidar la experiencia del menor; y la sintonía emocional (D) se prioriza sobre la exposición verbal directa para construir una relación de confianza, especialmente en poblaciones con problemas de conducta.'),
  (1003, 'El DSM‑5‑TR describe el trastorno de apego reactivo (TRD) como una condición que se manifiesta en la infancia temprana cuando el niño experimenta una falta prolongada de cuidado sensible, provocando dificultades persistentes en la regulación emocional y las relaciones interpersonales; la frecuencia de la presentación clínica es relativamente alta, especialmente en contextos de negligencia o abuso, por lo que la afirmación de que es poco frecuente (opción C) es la única que coincide con la realidad epidemiológica y con la descripción del manual, que indica que el TRD es un trastorno relativamente común en poblaciones de riesgo. La opción A es errónea porque el diagnóstico no depende de que el niño haya alcanzado los 5 años; el TRD se evalúa en la infancia temprana y puede diagnosticarse antes de esa edad. La opción B es incorrecta porque el DSM‑5‑TR no contempla subtipos (evitativo, desinhibido o ambivalente) para el TRD; esos subtipos pertenecen a otros trastornos de apego, como el trastorno de apego inseguro. La opción D es falsa porque el diagnóstico de TRD exige la presencia de un patrón externo de cuidado insuficiente o inadecuado, tal como lo establece el criterio A del manual.'),
  (1004, 'El DSM‑5‑TR distingue al trastorno negativista desafiante (TND) del trastorno de desregulación disruptiva del estado de ánimo (TDDEA) principalmente por la presencia de síntomas afectivos persistentes en el TDDEA; en el TND los episodios de irritabilidad son episódicos y no acompañados de un estado de ánimo disfuncional sostenido, por lo que los síntomas afectivos son realmente raros en niños con TND, lo que hace que la opción A sea la que describe correctamente la diferencia diagnóstica; las demás alternativas son incorrectas porque la opción B confunde los rasgos de ira con la irritabilidad característica del TND, la opción C es errónea pues el DSM prohíbe la comorbilidad simultánea cuando los criterios se superponen, y la opción D es falsa porque el TND requiere la presencia de los síntomas en al menos tres contextos diferentes, no dos.'),
  (1005, 'La opción B es la que se ajusta a la evidencia epidemiológica y clínica: las adolescentes tienden a avanzar más rápidamente desde el consumo experimental hasta patrones problemáticos, probablemente debido a factores de riesgo psicosociales, presión de pares y vulnerabilidades hormonales que aceleran la progresión; en contraste, los varones suelen mostrar una trayectoria más lenta y menos lineal. La alternativa A es incorrecta porque, aunque los jóvenes varones pueden ser más susceptibles a la influencia de sus pares, la literatura no indica que la influencia sea mayor que la de las chicas; la diferencia se centra más en la frecuencia de consumo que en la influencia per se. La opción C es errónea porque la representación de género en los servicios de tratamiento no refleja necesariamente la prevalencia real, pues las mujeres suelen subrepresentarse por barreras de acceso y estigma. Finalmente, la alternativa D se basa en una generalización incorrecta: los varones suelen presentar más problemas psicológicos comórbidos, no los varones con consumo, por lo que la afirmación está invertida.'),
  (1006, 'La opción B es la que se ajusta a la evidencia de Miller et al. (2007) sobre la DBT‑A, pues los estudios de seguimiento muestran que la sensación de desesperanza, cuando es alta, atenúa la eficacia de la intervención en la reducción de la ideación suicida, actuando como moderador del efecto positivo; esto se explica por la teoría de la desesperanza como factor de riesgo que dificulta la motivación para el cambio y la aplicación de las habilidades aprendidas. Las demás alternativas son erróneas: la A es falsa porque existen datos de seguimiento que indican que la frecuencia de autolesiones se mantiene reducida a largo plazo; la C es incorrecta porque la DBT‑A se centra en la regulación emocional y la aceptación, no en la reestructuración cognitiva; y la D es inexacta porque la intervención no se limita a la fase post‑hospitalaria ni se dirige exclusivamente a la prevención de intentos suicidas, sino que aborda una gama más amplia de conductas autolesivas y emocionales.'),
  (1007, 'La opción A es la única que refleja la evidencia clínica sobre la adolescencia, donde la neurociencia muestra que el sistema de recompensa aún se está desarrollando y la corteza prefrontal, responsable de la evaluación de riesgos y la toma de decisiones, está incompleta; por ello los adolescentes experimentan menos consecuencias negativas y perciben los reforzadores del consumo como más intensos, lo que explica la mayor tolerancia a la experimentación y la menor sensibilidad a los riesgos. Las demás alternativas se contradicen con los datos epidemiológicos y de intervención: la opción B invierte la relación real, pues los adultos suelen valorar más el riesgo y la gravedad que los adolescentes; la opción C es falsa porque la búsqueda de ayuda y la intención de cambio suelen ser más escasas en la adolescencia, dada la resistencia a la autoridad y la falta de reconocimiento del problema; y la opción D es incorrecta porque los adultos presentan mayor tasa de abandono de tratamientos, no la adolescencia, debido a la menor motivación intrínseca y a la falta de recursos familiares o institucionales.'),
  (1008, 'El fenómeno descrito corresponde al efecto de primacía, pues la teoría de Asch sostiene que la primera información que se recibe sobre un rasgo o conducta de una persona tiende a fijarse en la memoria y a influir en la interpretación de datos posteriores, de modo que la información contradictoria se adapta para mantener la coherencia con la impresión inicial; este mecanismo de ajuste se conoce como “primacía” porque la primera impresión domina la evaluación subsecuente. El efecto de recencia (A) se refiere a la influencia de la información más reciente, no a la adaptación de datos contradictorios a una impresión previa. El efecto de asimilación de atributos (B) implica la integración de nuevos rasgos en un esquema ya existente, pero no especifica la adaptación de información contradictoria a una impresión previa. El efecto de inferencia previa (C) no es un término reconocido en la literatura de Asch y no describe el proceso de ajuste de datos contradictorios; por tanto, las opciones A, B y C son incorrectas.'),
  (1009, 'La facilitación social se explica por la presencia de una tarea que el individuo percibe como sencilla o familiar, lo que permite que la presencia de otros actúe como un estímulo que aumenta la frecuencia de respuesta; en el caso de la aprehensión por la evaluación, la presencia de observadores provoca una activación fisiológica que, cuando la tarea es simple, favorece el rendimiento, mientras que en tareas complejas produce inhibición; por tanto la opción C refleja el mecanismo de facilitación social. El liderazgo (A) se relaciona con la influencia y la dirección de un grupo, no con la mejora del rendimiento ante la presencia de observadores; la desconexión moral (B) se refiere a la justificación de conductas inmorales y no a la dinámica de rendimiento social; y la atracción social (D) implica la preferencia por la compañía de otros, pero no explica el efecto de mejora del desempeño en presencia de observadores.'),
  (1010, 'La teoría de la acción razonada y la teoría de la conducta planeada sostienen que la intención conductual, el factor más inmediato que precede a la acción, se forma a partir de tres componentes: la actitud hacia la conducta, la norma subjetiva (la percepción de las expectativas sociales) y el control conductual percibido (la percepción de la facilidad o dificultad de realizar la conducta); estos tres determinantes se combinan para generar la intención, que a su vez guía la conducta real, por lo que la opción A recoge precisamente estos cuatro factores interrelacionados; las demás alternativas presentan conceptos que, aunque relevantes en otros modelos (motivación, autoeficacia, planificación, identidad social, etc.), no constituyen los constructos centrales de la teoría de la acción razonada y la conducta planeada, por lo que resultan incorrectas.'),
  (1011, 'La hipótesis del recuerdo congruente con el estado de ánimo sostiene que la recuperación de recuerdos se facilita cuando el estado afectivo interno coincide con el tono emocional del material memorizado; por ello, en un estado de ánimo positivo se favorece el recuerdo de episodios agradables y, en un estado de ánimo negativo, la evocación de experiencias desagradables, lo que explica la tendencia a filtrar la información de acuerdo con el estado emocional actual. Las demás opciones son incorrectas porque la hipótesis del recuerdo dependiente del estado de ánimo (A) se refiere a la influencia del estado emocional sobre la codificación más que sobre la recuperación, la hipótesis del recuerdo contaminante (C) describe la interferencia de recuerdos no relacionados con el estado de ánimo, y la hipótesis del recuerdo reactante (D) implica una reacción emocional al recuerdo que no explica la congruencia entre estado y contenido.'),
  (1012, 'La opción A se sostiene porque la teoría de la transferencia de la excitación, propuesta por Zillmann, sostiene que la activación fisiológica y emocional generada en una situación puede persistir y modular la respuesta a estímulos posteriores, de modo que una experiencia agresiva inicial aumenta la probabilidad de reacciones agresivas en contextos subsiguientes; esto se explica mediante la persistencia de la excitación que se “transfiere” a nuevas situaciones, intensificando la respuesta emocional. Las demás alternativas son incorrectas: la B describe la agresión desplazada, que se centra en la redirección de la agresión hacia un objetivo sustituto y no en la persistencia de la excitación; la C se refiere a la frustración‑agresión, que explica la agresión como consecuencia de la frustración, sin enfatizar la transferencia de excitación; y la D, la teoría general de la agresión humana, abarca factores biológicos, psicológicos y sociales, pero no plantea específicamente la persistencia de la activación emocional entre situaciones.'),
  (1013, 'El efecto espectador, también denominado fenómeno de la “bystander effect”, describe la disminución de la probabilidad de intervenir en una situación de emergencia cuando hay presencia de otros observadores; la responsabilidad se difunde y la persona solitaria percibe mayor obligación de actuar, por lo que es más propensa a ayudar, lo que explica la opción D. La alternativa A confunde la motivación con la compasión, pues la compasión puede estar presente tanto en presencia como en ausencia de otros y no explica la variación en la probabilidad de ayuda; la B introduce un motivo intrínseco de alivio emocional que no corresponde al mecanismo de difusión de responsabilidad; mientras que la C invierte la relación, pues la presencia de otros reduce la intervención, no la aumenta.'),
  (1014, 'El fenómeno descrito por Jones y Niesbett (1972) corresponde al efecto actor‑observador, que se explica por la distinción entre la percepción de la propia agencia y la de los demás: al actuar, la persona tiende a atribuir su comportamiento a causas externas (situacionales) para proteger su autoimagen, mientras que al observar a otros la tendencia es atribuir sus conductas a disposiciones internas (personales), una explicación que se sustenta en la teoría de la atribución de Heider y la evidencia de la auto‑protección y la consistencia interna; las demás opciones son inadecuadas: el efecto de la comparación atribucional (A) se refiere a la comparación de causas entre sí, no a la distinción entre actor y observador; el efecto de la polarización atribucional (B) implica una tendencia a atribuir causas de manera más extrema, pero no distingue entre el propio y el de otros; el efecto del locus de control (C) se relaciona con la percepción de control interno o externo sobre resultados, pero no aborda la doble atribución de conductas propias y ajenas.'),
  (1015, 'El fenómeno descrito corresponde al efecto del contacto extendido, que se produce cuando la relación positiva entre un miembro del propio endogrupo y un miembro del exogrupo se generaliza a todo el exogrupo, reduciendo así los prejuicios y mejorando las actitudes; la teoría de la identidad social explica que el vínculo entre los grupos se percibe como una extensión de la propia identidad, lo que favorece la transferencia de la valoración positiva. Las demás opciones son incorrectas: el “efecto de vinculación” no es un término reconocido en la literatura sobre prejuicio intergrupal; el “efecto de distintividad óptima” se refiere a la diferenciación de grupos internos y no al contacto entre grupos; y el “efecto de identidad endogrupal” describe la consolidación de la identidad interna, no la mejora de la percepción del exogrupo.'),
  (1016, 'La evidencia de validez según los Standards for Educational and Psychological Testing se clasifica en cuatro tipos: contenido, constructo, criterio y de respuesta; la fiabilidad, aunque esencial para la precisión de las puntuaciones, no constituye una forma de evidencia de validez, pues la fiabilidad solo indica consistencia interna o estabilidad temporal, no la adecuación del contenido o la relación con otras variables; por ello la opción C es la que no se considera evidencia de validez. Las demás alternativas sí corresponden a los tipos aceptados: la evidencia basada en el contenido evalúa la representatividad de los ítems respecto al dominio de interés; la evidencia basada en los procesos de respuesta examina la lógica y coherencia de las respuestas de los examinados; y la evidencia basada en la relación con otras variables (criterio) verifica la correlación con medidas externas que se supone que están relacionadas con el constructo.'),
  (1017, 'El sistema parvocelular del núcleo geniculado lateral se caracteriza por recibir principalmente las aferencias de la vía retinocorticala que transportan información de alta resolución visual, como los detalles finos y la percepción del color, gracias a la densidad de ganglionares midget y a la organización de las capas 3 y 4 del núcleo, donde se concentran las células parvocelulares; por tanto, la opción que indica que es responsable del análisis de los detalles finos de la imagen y de la percepción del color corresponde a la función principal atribuida a esta vía. Las demás alternativas son erróneas: la opción A describe la vía magnocelular, que recibe la mayor parte de la información ipsilateral en las capas 1, 4 y 6, no la parvocelular; la B confunde el sistema olfativo con el visual, pues el núcleo geniculado lateral no participa en la coordinación de la información olfatoria; y la D se refiere a la vía de la magnocelular, que se especializa en la sensibilidad al movimiento y en la percepción de características generales del estímulo.'),
  (1018, 'El cuadro clínico de J. se ajusta a los criterios del trastorno neurocognitivo frontotemporal (TNF) mayor, ya que presenta deterioro significativo en el funcionamiento cognitivo y en la conducta, con pérdida de rendimiento laboral, supervisión y reasignación a tareas más simples, y cambios de personalidad que incluyen frialdad emocional, conductas compulsivas y una visión distorsionada de una relación sentimental, lo que indica alteraciones en la impulsividad y la toma de decisiones; estos síntomas cumplen con la gravedad mayor según el DSM‑5‑TR, pues el deterioro afecta la independencia funcional en al menos dos áreas (cognición y conducta) y es suficientemente severo como para requerir supervisión. La opción “mayor posible” se emplea cuando la evidencia clínica sugiere la presencia de un TNF mayor pero no se dispone de datos suficientes para confirmar la gravedad con certeza, por lo que la clasificación se mantiene en “posible”. Las opciones A y B se refieren a la gravedad mayor y leve respectivamente, pero la descripción de J. indica un deterioro mayor, no leve. La opción D, “leve posible”, es incorrecta porque la severidad de los síntomas excede la leveidad, y la palabra “posible” no se aplica a la gravedad leve en el DSM‑5‑TR.'),
  (1019, 'El tratamiento ambulatorio de la bulimia nerviosa es el enfoque más frecuente y eficaz, ya que la mayoría de los pacientes presentan un nivel de gravedad que permite la intervención en un entorno no hospitalario y se ha demostrado que la terapia cognitivo‑conductual (TCC) y otras modalidades estructuradas reducen la frecuencia de episodios de ingesta excesiva y purga; por ello la opción C es la que mejor refleja la práctica clínica basada en la evidencia. La alternativa A es errónea porque existen estudios que avalan la utilidad de programas de autoayuda estructurados, aunque no sustituyen la TCC; la opción B es incorrecta porque el tratamiento de la bulimia no se centra en el peso corporal, sino en la conducta alimentaria y la cognición asociada, y los cambios de peso suelen ser mínimos; y la opción D se rechaza porque, a diferencia de los trastornos de ansiedad, las terapias de tercera generación (como la terapia de aceptación y compromiso) todavía no cuentan con suficiente evidencia empírica específica para la bulimia nerviosa.'),
  (1020, 'En la etapa de duelo de los menores de 6 a 9 años, la comprensión de la muerte se caracteriza por una visión de su irreversibilidad y universalidad, pero con una limitada capacidad de asimilación de la posibilidad de que la propia muerte pueda afectarlos o a sus familiares; por ello, la opción C refleja que estos niños reconocen la imposibilidad de detener la muerte y la universalidad del fenómeno, aunque no aceptan plenamente la amenaza personal, lo cual es coherente con el desarrollo cognitivo de esta edad donde el pensamiento concreto y la falta de abstracción impiden la internalización completa de la fatalidad. Las demás opciones son erróneas porque la A presupone una incapacidad total de entender la universalidad, cuando en realidad los niños de esta edad ya la perciben; la B exagera su comprensión al afirmar que entienden la muerte como universal, irreversible y permanente, cuando en realidad su entendimiento es más parcial; y la D describe el egocentrismo y pensamiento mágico de edades más tempranas (3‑5 años), no de los 6‑9 años, por lo que no corresponde al perfil cognitivo de este grupo.'),
  (1021, 'El esquema de refuerzo que se describe corresponde a un programa de razón variable, ya que la recompensa (el éxito de meter la pelota en el hoyo) se otorga después de un número variable de golpes, sin que el jugador pueda predecir cuántos golpes serán necesarios en cada intento; la contingencia entre el comportamiento y la recompensa es aleatoria en cuanto al número de respuestas, lo que produce una alta tasa de respuesta y resistencia al abandono, características típicas de la razón variable. Las opciones A y D se refieren a esquemas de razón fija e intervalo fijo, respectivamente, donde la recompensa se otorga después de un número fijo de respuestas o después de un intervalo de tiempo fijo, lo que no coincide con la imprevisibilidad de golpes descrita. La opción C, intervalo variable, implica que la recompensa se concede tras un intervalo de tiempo variable, lo cual también difiere de la contingencia basada en el número de golpes.'),
  (1022, 'El instrumento MULTICAGE CAD‑4 de Pedrero y colaboradores (2007) es un cuestionario multidimensional que evalúa conductas adictivas en tres dominios: consumo de sustancias, juego de apuestas y videojuegos, permitiendo identificar patrones de riesgo y dependencia en cada uno de estos ámbitos; su estructura de ítems y escalas específicas para cada modalidad lo hace el único de la lista que abarca los tres tipos de conducta adictiva solicitada, mientras que el BPGS (opción B) se limita al juego de apuestas, el IGD‑20 (opción C) solo a la adicción a los videojuegos y la PVP (opción D) se centra exclusivamente en el juego de video, por lo que no cumplen el criterio de cubrir las tres áreas.'),
  (1023, 'La influencia teórica que constituye un antecedente de la corriente intersubjetivista del psicoanálisis, según la plantilla oficial, es la psicología del self de Heinz Kohut (opción B). La intersubjetividad se centra en la co-construcción de significados y la identificación mutua entre paciente y terapeuta, conceptos que Kohut desarrolló al enfatizar la importancia de la empatía, la validación y la relación de transferencia como medios para la formación y reparación del self; estos elementos se incorporan directamente en la teoría intersubjetiva de Stolorow y Atwood. Las demás opciones son incorrectas porque el modelo lingüístico de Lacan (A) se enfoca en la estructura del lenguaje y la relación del sujeto con el Otro simbólico, no en la intersubjetividad clínica; la teoría estructural de la personalidad de Kernberg (C) se basa en la integración de aspectos psíquicos y la dinámica de la identidad, pero no constituye un antecedente directo de la intersubjetividad; y el trabajo de lo negativo de A. Green (D) se orienta a la psicología del desarrollo y la teoría del apego, sin abordar la co-construcción intersubjetiva que caracteriza a la corriente intersubjetivista.'),
  (1024, 'La descripción corresponde a la etapa de mantenimiento de las relaciones mutuas y aprobación de otros, que en la jerarquía de Kohlberg se ubica en el nivel de moralidad convencional (fase 3), donde la evaluación de una acción se basa en la intención del actor y en la percepción de que la conducta favorece la armonía y el reconocimiento social; la persona valora la buena voluntad y la intención de ayudar, considerando las circunstancias para determinar la legitimidad de la acción, lo cual es característico de esta etapa. Las demás opciones se refieren a niveles anteriores o posteriores: la etapa de propósito instrumental e intercambio (fase 2) se centra en la reciprocidad y la utilidad práctica sin considerar la intención; la etapa de interés social y conciencia (fase 5) implica la valoración de los derechos individuales y la justicia más allá de la aprobación social; y la etapa de moralidad de contrato o de los derechos individuales (fase 6) se basa en principios abstractos y universales, no en la evaluación de intenciones y circunstancias.'),
  (1025, 'La opción D es la que se ajusta a los principios de la evaluación clínica en el maltrato infantil: la decisión de entrevistar a cuidadores o familiares debe basarse en la valoración clínica del caso y en las dinámicas relacionales observadas, ya que la información contextual y la interacción familiar son esenciales para comprender la situación y determinar la necesidad de intervención, sin que la evaluación se limite a un análisis puramente individual. Las alternativas A, B y C son incorrectas porque la A descarta la relevancia de las variables familiares y contextuales, que son parte integral de la valoración; la B sobrecarga el proceso con la búsqueda de coherencia y credibilidad del relato del menor, lo que puede sesgar la interpretación clínica; y la C promueve una exclusión indebida de recursos expresivos o proyectivos, que en el contexto del maltrato infantil son valiosos para acceder a información emocional y dinámica que no se captura con instrumentos estandarizados.')
) AS v(id, explicacion)
WHERE p.id = v.id;

DO $$
DECLARE
  total_despues int;
  sin_explicacion_despues int;
BEGIN
  SELECT COUNT(*) INTO total_despues FROM public.preguntas;
  SELECT COUNT(*) INTO sin_explicacion_despues
    FROM public.preguntas WHERE explicacion IS NULL OR explicacion = '';
  IF total_despues != 1025 THEN
    RAISE EXCEPTION 'Total de preguntas cambio: % -- abortando.', total_despues;
  END IF;
  IF sin_explicacion_despues != 0 THEN
    RAISE EXCEPTION '% preguntas se quedaron sin explicacion -- abortando.', sin_explicacion_despues;
  END IF;
  RAISE NOTICE 'OK: % preguntas, 0 sin explicacion.', total_despues;
END $$;

COMMIT;
